UnBotKnownBots = UnBotKnownBots or {};
UnBotSquadConfig = UnBotSquadConfig or {};
UnBotBotRegistry = UnBotBotRegistry or {};

function UnBotIsAccountAltProfile(name, profile)
	return (
		(profile and (profile.accountAlt or profile.protectedAccountCharacter))
		or (
			UnBotAccountAlts
			and UnBotAccountAlts.IsAlt
			and UnBotAccountAlts.IsAlt(name, profile)
		)
	) and true or false;
end

-- Keep the registry inside an old, already registered SavedVariable as well.
-- This protects installations where WoW cached the TOC before UnBotBotRegistry
-- was added to the SavedVariables declaration. SavedVariables can arrive only
-- immediately before ADDON_LOADED, so this merge is repeated from that event.

local function UnBotIsValidBotName(name)
	return (
		name
		and name ~= ""
		and name ~= UnitName("player")
		and name ~= UNKNOWN
		and name ~= UNKNOWNOBJECT
	);
end

local function UnBotRegistryProfileCount(registry)
	local count = 0;
	for name, profile in pairs((registry and registry.bots) or {}) do
		if (UnBotIsValidBotName(name) and profile) then
			count = count + 1;
		end
	end
	return count;
end

local function UnBotRegistryMerge(target, source)
	if (not source or target == source) then
		return target;
	end
	target.bots = target.bots or {};
	for name, profile in pairs(source.bots or {}) do
		if (UnBotIsValidBotName(name) and profile) then
			local savedProfile = target.bots[name];
			if (
				not savedProfile
				or (tonumber(profile.lastSeen) or 0) >= (tonumber(savedProfile.lastSeen) or 0)
			) then
				target.bots[name] = profile;
			end
		end
	end

	target.meta = target.meta or {};
	for key, value in pairs(source.meta or {}) do
		if (key == "classStatus" and type(value) == "table") then
			target.meta.classStatus = target.meta.classStatus or {};
			for className, status in pairs(value) do
				local savedStatus = target.meta.classStatus[className];
				local sourceTime = math.max(
					tonumber(status.lastFinished) or 0,
					tonumber(status.lastFailed) or 0,
					tonumber(status.lastAttemptStarted) or 0
				);
				local savedTime = savedStatus and math.max(
					tonumber(savedStatus.lastFinished) or 0,
					tonumber(savedStatus.lastFailed) or 0,
					tonumber(savedStatus.lastAttemptStarted) or 0
				) or 0;
				if (not savedStatus or sourceTime >= savedTime) then
					target.meta.classStatus[className] = status;
				end
			end
		elseif (target.meta[key] == nil) then
			target.meta[key] = value;
		end
	end
	return target;
end

function UnBotRegistryApplyBundledSeed(target)
	if UnBotPublicRegistrySeed and UnBotPublicRegistry
		and UnBotPublicRegistry.Server() ~= UnBotPublicRegistrySeed.serverKey then return 0, 0, false; end
	local currentRealm = GetRealmName and GetRealmName() or "";
	local currentRealmKey = string.lower((currentRealm:gsub("^%s+", ""):gsub("%s+$", "")));
	local currentFaction = UnitFactionGroup and UnitFactionGroup("player") or "";
	local currentFactionKey = string.lower(tostring(currentFaction or ""));
	local currentContextKey = currentRealmKey.."|"..currentFactionKey;
	local seed = UnBotBotRegistrySeeds and UnBotBotRegistrySeeds[currentContextKey] or UnBotBotRegistrySeed;
	local seedMeta = seed and seed.meta;
	local seedRealmKey = seedMeta and string.lower(tostring(seedMeta.realmKey or "")) or "";
	local seedFactionKey = seedMeta and string.lower(tostring(seedMeta.faction or "")) or "";
	if (
		type(target) ~= "table"
		or type(seed) ~= "table"
		or type(seed.bots) ~= "table"
		or seedRealmKey == ""
		or seedFactionKey == ""
		or currentRealmKey ~= seedRealmKey
		or currentFactionKey ~= seedFactionKey
	) then
		return 0, 0, false;
	end

	target.bots = target.bots or {};
	target.meta = target.meta or {};
	if (target.meta.bundledSeedId == seedMeta.seedId) then
		return 0, 0, false;
	end

	local added, updated = 0, 0;
	local profileFields = {
		"name", "className", "specName", "level", "gearScore",
		"raceName", "gender", "firstSeen", "lastSeen", "specCheckedAt", "feralRole",
	};
	for name, seedProfile in pairs(seed.bots) do
		if (UnBotIsValidBotName(name) and type(seedProfile) == "table") then
			local savedProfile = target.bots[name];
			if (not savedProfile) then
				savedProfile = {};
				for _, field in ipairs(profileFields) do
					savedProfile[field] = seedProfile[field];
				end
				savedProfile.source = "bundled-seed";
				target.bots[name] = savedProfile;
				added = added + 1;
			elseif (not UnBotIsAccountAltProfile(name, savedProfile)) then
				local seedTime = math.max(
					tonumber(seedProfile.specCheckedAt) or 0,
					tonumber(seedProfile.lastSeen) or 0
				);
				local savedTime = math.max(
					tonumber(savedProfile.specCheckedAt) or 0,
					tonumber(savedProfile.lastSeen) or 0
				);
				local changed = false;
				for _, field in ipairs(profileFields) do
					if (
						seedProfile[field] ~= nil
						and field ~= "firstSeen"
						and (savedProfile[field] == nil or seedTime > savedTime)
						and savedProfile[field] ~= seedProfile[field]
					) then
						savedProfile[field] = seedProfile[field];
						changed = true;
					end
				end
				if (
					seedProfile.firstSeen ~= nil
					and (
						savedProfile.firstSeen == nil
						or (tonumber(seedProfile.firstSeen) or 0) < (tonumber(savedProfile.firstSeen) or 0)
					)
				) then
					savedProfile.firstSeen = seedProfile.firstSeen;
					changed = true;
				end
				if (changed) then
					updated = updated + 1;
				end
			end
			UnBotKnownBots[name] = true;
		end
	end

	target.meta.bundledSeedId = seedMeta.seedId;
	target.meta.bundledSeedRealm = seedMeta.realmName;
	target.meta.bundledSeedFaction = seedMeta.faction;
	target.meta.realmKey = seedMeta.realmKey;
	target.meta.faction = seedMeta.faction;
	target.meta.bundledSeedGeneratedAt = seedMeta.generatedAt;
	target.meta.bundledSeedImportedAt = time();
	target.meta.bundledSeedProfileCount = seedMeta.profileCount;
	UnBotRegistrySeedImportStatus = {
		added = added,
		updated = updated,
		total = UnBotRegistryProfileCount(target),
		realmName = seedMeta.realmName,
	};
	return added, updated, true;
end

function UnBotRegistryCurrentContext()
	local realmName = GetRealmName and GetRealmName() or "unknown-realm";
	local realmKey = string.lower((tostring(realmName):gsub("^%s+", ""):gsub("%s+$", "")));
	local faction = UnitFactionGroup and UnitFactionGroup("player") or "unknown-faction";
	local factionKey = string.lower(tostring(faction or "unknown-faction"));
	if (realmKey == "") then realmKey = "unknown-realm"; end
	if (factionKey == "") then factionKey = "unknown-faction"; end
	return realmKey.."|"..factionKey, realmKey, faction;
end

function UnBotRegistryStoredContext(registry)
	if (type(registry) ~= "table") then
		return nil;
	end
	registry.meta = registry.meta or {};
	local meta = registry.meta;
	local realmKey = string.lower(tostring(meta.realmKey or meta.bundledSeedRealm or ""));
	local faction = meta.faction or meta.bundledSeedFaction;
	local factionKey = string.lower(tostring(faction or ""));
	if (
		(realmKey == "" or factionKey == "")
		and UnBotRegistryProfileCount(registry) > 0
		and UnBotBotRegistrySeed and UnBotBotRegistrySeed.meta
	) then
		local overlap = 0;
		for name in pairs(registry.bots or {}) do
			if (UnBotBotRegistrySeed.bots and UnBotBotRegistrySeed.bots[name]) then
				overlap = overlap + 1;
			end
		end
		if (
			overlap >= math.floor(
				(tonumber(UnBotBotRegistrySeed.meta.profileCount) or 0) * 0.9
			)
		) then
			realmKey = string.lower(tostring(UnBotBotRegistrySeed.meta.realmKey or ""));
			faction = UnBotBotRegistrySeed.meta.faction;
			factionKey = string.lower(tostring(faction or ""));
		end
	end
	if (realmKey == "" or factionKey == "") then
		return nil;
	end
	meta.realmKey = realmKey;
	meta.faction = faction;
	return realmKey.."|"..factionKey, realmKey, faction;
end

function UnBotRegistryMatchesCurrentContext(registry)
	local currentKey = UnBotRegistryCurrentContext();
	local storedKey = UnBotRegistryStoredContext(registry);
	return not storedKey or storedKey == currentKey;
end

local function UnBotRegistryAttachStorage()
	UnBotSquadConfig = UnBotSquadConfig or {};
	local standalone = UnBotBotRegistry;
	local embedded = UnBotSquadConfig.botRegistry;
	local standaloneCount = UnBotRegistryProfileCount(standalone);
	local embeddedCount = UnBotRegistryProfileCount(embedded);
	local contexts = UnBotSquadConfig.botRegistriesByContext or {};
	local knownContexts = UnBotSquadConfig.knownBotsByContext or {};
	local currentKey, currentRealmKey, currentFaction = UnBotRegistryCurrentContext();
	local standaloneKey = UnBotRegistryStoredContext(standalone);
	local embeddedKey = UnBotRegistryStoredContext(embedded);
	local legacyKey = standaloneKey or embeddedKey or currentKey;

	local function preserveRegistry(source, sourceKey)
		if (type(source) ~= "table" or UnBotRegistryProfileCount(source) == 0) then
			return;
		end
		sourceKey = sourceKey or currentKey;
		local bucket = contexts[sourceKey] or { version = 1, bots = {}, meta = { classStatus = {} } };
		UnBotRegistryMerge(bucket, source);
		if (not UnBotRegistryStoredContext(bucket)) then
			bucket.meta.realmKey = currentRealmKey;
			bucket.meta.faction = currentFaction;
		end
		contexts[sourceKey] = bucket;
	end

	preserveRegistry(standalone, standaloneKey);
	preserveRegistry(embedded, embeddedKey);

	for contextKey, registry in pairs(contexts) do
		registry.version = 1;
		registry.bots = registry.bots or {};
		registry.meta = registry.meta or {};
		registry.meta.classStatus = registry.meta.classStatus or {};
		if (not UnBotRegistryStoredContext(registry)) then
			local realmKey, factionKey = string.match(contextKey, "^(.-)|(.+)$");
			registry.meta.realmKey = realmKey or currentRealmKey;
			registry.meta.faction = factionKey or currentFaction;
		end
	end

	local registry = contexts[currentKey];
	if (not registry) then
		registry = {
			version = 1,
			bots = {},
			meta = {
				classStatus = {},
				realmKey = currentRealmKey,
				faction = currentFaction,
			},
		};
		contexts[currentKey] = registry;
	end

	local legacyKnown = UnBotKnownBots or {};
	knownContexts[legacyKey] = knownContexts[legacyKey] or {};
	for name in pairs(legacyKnown) do
		if (UnBotIsValidBotName(name)) then
			knownContexts[legacyKey][name] = true;
		end
	end
	knownContexts[currentKey] = knownContexts[currentKey] or {};
	UnBotKnownBots = knownContexts[currentKey];
	UnBotBotRegistry = registry;
	UnBotRegistryApplyBundledSeed(registry);

	for name in pairs(registry.bots) do
		if (not UnBotIsValidBotName(name)) then
			registry.bots[name] = nil;
		end
	end
	for name in pairs(UnBotKnownBots) do
		if (not UnBotIsValidBotName(name)) then
			UnBotKnownBots[name] = nil;
		end
	end

	UnBotSquadConfig.botRegistriesByContext = contexts;
	UnBotSquadConfig.knownBotsByContext = knownContexts;
	UnBotSquadConfig.activeBotRegistryContext = currentKey;
	UnBotSquadConfig.botRegistry = registry;
	if (UnBotPublicRegistry) then UnBotPublicRegistry.Apply(registry); end
	if (UnBotSharedNames) then UnBotSharedNames.Attach(); end
	return UnBotRegistryProfileCount(registry), embeddedCount, standaloneCount;
end

UnBotRegistryAttachStorage();

local function UnBotRememberKnownBot(name)
	if (UnBotIsValidBotName(name)) then
		UnBotKnownBots[name] = true;
		if (UnBotSharedNames) then UnBotSharedNames.Found(name); end
	end
end

