local function UnBotSpecSummonNormalize(text)
	text = string.lower(tostring(text or ""));
	text = string.gsub(text, "|c%x%x%x%x%x%x%x%x", "");
	text = string.gsub(text, "|r", "");
	text = string.gsub(text, "|h", "");
	text = string.gsub(text, "%s+", " ");
	text = string.gsub(text, "^%s+", "");
	text = string.gsub(text, "%s+$", "");
	return text;
end

function UnBotSpecSummonPlayerSupportsSpecs()
	return (tonumber(UnitLevel("player")) or 0) >= 11;
end

function UnBotFeralRoleFromWhoText(text)
	text = UnBotSpecSummonNormalize(text);
	local balancePoints, feralPoints, restorationPoints = string.match(
		text,
		"feral combat%s*%((%d+)%s*/%s*(%d+)%s*/%s*(%d+)%)"
	);
	if (not feralPoints) then
		return nil, nil;
	end
	local talentBuild = tostring(balancePoints).."/"..tostring(feralPoints).."/"..tostring(restorationPoints);
	if (talentBuild == "0/60/11") then
		return "bear", talentBuild;
	elseif (talentBuild == "0/53/18" or talentBuild == "0/55/16") then
		return "cat", talentBuild;
	end
	return nil, talentBuild;
end

function UnBotFeralProfileRole(profile)
	if (UnBotTalentInfo and type(profile)=="table" and profile.talentSnapshot and not profile.talentSnapshotStale) then
		return (UnBotTalentInfo.Get(profile).specRole or ""):match("^feral (%S+)$");
	end
	if (
		type(profile) ~= "table"
		or UnBotSpecSummonNormalize(profile.className) ~= "druid"
	) then
		return nil;
	end
	local role = UnBotSpecSummonNormalize(profile.feralRole);
	if (
		(role == "bear" or role == "cat")
		and (
			UnBotSpecSummonNormalize(profile.specName) == "feral combat"
			or (
				UnBotSpecSummonNormalize(profile.feralRoleSource) == "combat-strategy"
				and tonumber(profile.level)
				and tonumber(profile.level) < 80
			)
		)
	) then
		return role;
	end
	if (UnBotSpecSummonNormalize(profile.specName) ~= "feral combat") then
		return nil;
	end
	local detectedRole, talentBuild = UnBotFeralRoleFromWhoText(profile.rawWho);
	if (talentBuild) then
		profile.talentBuild = talentBuild;
	end
	if (detectedRole) then
		profile.feralRole = detectedRole;
	end
	return detectedRole;
end

function UnBotStoreFeralRole(profile, whoInfo)
	if (type(profile) ~= "table" or type(whoInfo) ~= "table") then
		return;
	end
	if (UnBotTalentInfo) then UnBotTalentInfo.ObserveWho(profile,whoInfo); end
	if (
		UnBotSpecSummonNormalize(whoInfo.className) == "druid"
	) then
		if (whoInfo.feralRole) then
			profile.feralRole = whoInfo.feralRole;
			profile.feralRoleSource = "talent-build";
			profile.feralRoleCheckedAt = time();
		elseif (
			UnBotSpecSummonNormalize(profile.feralRoleSource) ~= "combat-strategy"
			or not tonumber(whoInfo.level)
			or tonumber(whoInfo.level) >= 80
		) then
			profile.feralRole = nil;
			profile.feralRoleSource = nil;
			profile.feralRoleCheckedAt = nil;
		end
		profile.talentBuild = whoInfo.talentBuild;
	else
		profile.feralRole = nil;
		profile.feralRoleSource = nil;
		profile.feralRoleCheckedAt = nil;
		profile.talentBuild = whoInfo.talentBuild;
	end
end

function UnBotFeralRoleFromStrategyText(text)
	text = UnBotSpecSummonNormalize(text);
	local strategyText = string.match(text, "strategies:%s*(.*)");
	if (strategyText == nil) then
		return nil, false;
	end
	local hasBear = false;
	local hasCat = false;
	for strategy in string.gmatch(strategyText, "[^,]+") do
		strategy = UnBotSpecSummonNormalize(strategy);
		if (strategy == "bear") then
			hasBear = true;
		elseif (strategy == "cat") then
			hasCat = true;
		end
	end
	if (hasBear and not hasCat) then
		return "bear", true;
	elseif (hasCat and not hasBear) then
		return "cat", true;
	end
	return nil, true;
end

function UnBotStoreFeralStrategyRole(name, whoInfo, role)
	if (
		not UnBotIsValidBotName(name)
		or type(whoInfo) ~= "table"
		or UnBotSpecSummonNormalize(whoInfo.className) ~= "druid"
		or (role ~= "bear" and role ~= "cat")
	) then
		return false;
	end
	whoInfo.feralRole = role;
	UnBotRegistryAttachStorage();
	local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (profile) then
		profile.feralRole = role;
		profile.feralRoleSource = "combat-strategy";
		profile.feralRoleCheckedAt = time();
		UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	end
	if (UnBotSpecSummon.verifiedCandidates and UnBotSpecSummon.verifiedCandidates[name]) then
		UnBotSpecSummon.verifiedCandidates[name].feralRole = role;
	end
	return true;
end

local function UnBotRegistryFlagTimeText(timestamp)
	if (not timestamp or timestamp <= 0) then
		return "?";
	end
	return date("%d.%m.%Y %H:%M", timestamp);
end

local function UnBotRegistryNextMorningTimestamp()
	local now = time();
	local morning = date("*t", now);
	morning.hour = 6;
	morning.min = 0;
	morning.sec = 0;
	local result = time(morning);
	if (result <= now) then
		morning.day = morning.day + 1;
		result = time(morning);
	end
	return result;
end

local function UnBotRegistryGetActiveFlag(profile)
	if (not profile) then
		return nil;
	end
	profile.rotationFlags = profile.rotationFlags or {};
	local flags = profile.rotationFlags;
	if (UnBotBuffCycleArrivalBlock and profile.name and UnBotBuffCycleArrivalBlock(profile.name)) then
		return {kind = "quarantine", untilTime = 0, untilExit = true, reason = "не телепортируется; до выхода из подземелья"};
	end
	if (UnBotIsAccountAltProfile(profile.name, profile)) then
		flags.quarantinedUntil = nil;
		flags.quarantineReason = nil;
		flags.quarantinedAt = nil;
		return nil;
	end
	local now = time();
	if ((tonumber(flags.quarantinedUntil) or 0) > 0 and flags.quarantinedUntil <= now) then
		flags.quarantinedUntil = nil;
		flags.quarantineReason = nil;
		flags.quarantinedAt = nil;
	end
	if ((tonumber(flags.soulstoneUntil) or 0) > 0 and flags.soulstoneUntil <= now) then
		flags.soulstoneUntil = nil;
		flags.soulstoneUsedAt = nil;
	end
	if ((tonumber(flags.quarantinedUntil) or 0) > now) then
		return {
			kind = "quarantine",
			untilTime = flags.quarantinedUntil,
			reason = flags.quarantineReason or "бот недоступен рядом с игроком",
		};
	end
	if ((tonumber(flags.soulstoneUntil) or 0) > now) then
		return {
			kind = "soulstone",
			untilTime = flags.soulstoneUntil,
			reason = "Soulstone на перезарядке",
		};
	end
	return nil;
end

local function UnBotRegistrySetQuarantine(name, reason, untilTime)
	UnBotRegistryAttachStorage();
	local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (not profile) then
		return false;
	end
	if (UnBotIsAccountAltProfile(name, profile)) then
		profile.rotationFlags = profile.rotationFlags or {};
		profile.rotationFlags.quarantinedAt = nil;
		profile.rotationFlags.quarantinedUntil = nil;
		profile.rotationFlags.quarantineReason = nil;
		UnBotSquadConfig.botRegistry = UnBotBotRegistry;
		return false;
	end
	profile.rotationFlags = profile.rotationFlags or {};
	profile.rotationFlags.quarantinedAt = time();
	profile.rotationFlags.quarantinedUntil = untilTime or UnBotRegistryNextMorningTimestamp();
	profile.rotationFlags.quarantineReason = reason or "бот не телепортируется к игроку";
	profile.lastSeen = time();
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	return true;
end

function UnBotRegistrySetHourlyQuarantine(name, reason, label)
	UnBotRegistryAttachStorage();
	local profile = name and UnBotBotRegistry.bots
		and UnBotBotRegistry.bots[name];
	if (not profile) then
		return false;
	end
	local existingUntil = profile.rotationFlags
		and tonumber(profile.rotationFlags.quarantinedUntil) or 0;
	local untilTime = math.max(time() + 3600, existingUntil);
	if (not UnBotRegistrySetQuarantine(name, reason, untilTime)) then
		return false;
	end
	UnBotSpecSummonMessage(
		(label or "Ротация")..": "..tostring(name).." исключён до "
		..UnBotRegistryFlagTimeText(untilTime).." — "..tostring(reason).."."
	);
	return true;
end

local function UnBotRegistryMarkSoulstoneCooldown(name)
	UnBotRegistryAttachStorage();
	local profile = name and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (not profile) then
		return false;
	end
	profile.rotationFlags = profile.rotationFlags or {};
	local now = time();
	if ((tonumber(profile.rotationFlags.soulstoneUntil) or 0) <= now) then
		profile.rotationFlags.soulstoneUsedAt = now;
		profile.rotationFlags.soulstoneUntil = now + (15 * 60);
		profile.lastSeen = now;
		UnBotSquadConfig.botRegistry = UnBotBotRegistry;
		UnBotSpecSummonMessage(
			"Ротация: "..name.." временно исключён — Soulstone на перезарядке до "
			..UnBotRegistryFlagTimeText(profile.rotationFlags.soulstoneUntil).."."
		);
	end
	return true;
end

local function UnBotRegistryClearFlags(name)
	UnBotRegistryAttachStorage();
	local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (not profile) then
		return false;
	end
	profile.rotationFlags = {};
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	return true;
end

local function UnBotRegistryRecordGameplaySummon(name, source)
	UnBotRegistryAttachStorage();
	local profile = name and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (not profile) then
		return nil;
	end
	profile.summonCount = (tonumber(profile.summonCount) or 0) + 1;
	profile.lastSummonedAt = time();
	profile.lastSummonSource = source or "unknown";
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	return profile.summonCount;
end

local function UnBotRegistryRecordJunkSale(name)
	UnBotRegistryAttachStorage();
	local profile = name and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (not profile) then
		return false;
	end
	profile.junkSoldAt = time();
	profile.junkSoldSummonCount = tonumber(profile.summonCount) or 0;
	profile.forceJunkCycle = nil;
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	return true;
end

local function UnBotRegistryNeedsJunkSale(profile)
	if (not profile) then
		return false;
	end
	if (UnBotIsAccountAltProfile(profile.name, profile)) then
		return false;
	end
	if (profile.forceJunkCycle) then
		return true;
	end
	local summonCount = tonumber(profile.summonCount) or 0;
	local soldSummonCount = tonumber(profile.junkSoldSummonCount) or 0;
	return summonCount > soldSummonCount;
end

function UnBotRegistryProfileNeedsJunkSale(profile)
	return UnBotRegistryNeedsJunkSale(profile);
end

function UnBotJunkCleanerForceFullCycleRevision()
	UnBotRegistryAttachStorage();
	UnBotSquadConfig = UnBotSquadConfig or {};
	-- v3 намеренно отличается от ранней ошибочной ревизии, которая могла
	-- отметиться выполненной на пустом реестре до ADDON_LOADED.
	local revision = "vendor-restock-2026-08-01-v3-after-savedvariables";
	if (UnBotSquadConfig.junkCleanerFullCycleRevision == revision) then
		return;
	end
	local resetCount = 0;
	for name, profile in pairs((UnBotBotRegistry and UnBotBotRegistry.bots) or {}) do
		if (UnBotIsValidBotName(name) and profile and not UnBotIsAccountAltProfile(name, profile)) then
			-- Явный флаг включает даже профили, которые ещё ни разу не призывались.
			-- Он снимается только после успешных продажи и закупки конкретного бота.
			profile.forceJunkCycle = true;
			profile.junkSoldSummonCount = -1;
			resetCount = resetCount + 1;
		end
	end
	UnBotSquadConfig.junkCleanerFullCycleRevision = revision;
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	UnBotSpecSummonMessage(
		"Всем профилям установлен принудительный флаг продажи/закупки: "
		..tostring(resetCount).." ботов. Флаг снимается только после успешной обработки."
	);
end

function UnBotJunkCleanerForceAllNow()
	UnBotRegistryAttachStorage();
	local checkpoint = UnBotJunkCleanerCheckpoint
		and UnBotJunkCleanerCheckpoint.GetActive
		and UnBotJunkCleanerCheckpoint.GetActive();
	local resetCount = 0;
	if (checkpoint) then
		for name in pairs(checkpoint.names or {}) do
			local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
			if (profile and not UnBotIsAccountAltProfile(name, profile)) then
				if (checkpoint.completed and checkpoint.completed[name]) then
					profile.forceJunkCycle = nil;
				else
					profile.forceJunkCycle = true;
					profile.junkSoldSummonCount = -1;
					resetCount = resetCount + 1;
				end
			end
		end
		UnBotSquadConfig.botRegistry = UnBotBotRegistry;
		checkpoint.updatedAt = time();
		UnBotSpecSummonMessage(
			"Продолжается незавершённая партия обслуживания: сохранено "
			..tostring(checkpoint.completedCount or 0).."/"
			..tostring(checkpoint.total or 0)..", осталось "
			..tostring(resetCount)..". Уже завершённые боты повторно не помечены."
		);
		return;
	end
	local checkpointNames = {};
	for name, profile in pairs((UnBotBotRegistry and UnBotBotRegistry.bots) or {}) do
		if (UnBotIsValidBotName(name) and profile and not UnBotIsAccountAltProfile(name, profile)) then
			profile.forceJunkCycle = true;
			profile.junkSoldSummonCount = -1;
			table.insert(checkpointNames, name);
			resetCount = resetCount + 1;
		end
	end
	if (UnBotJunkCleanerCheckpoint and UnBotJunkCleanerCheckpoint.Create) then
		UnBotJunkCleanerCheckpoint.Create(checkpointNames);
	end
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	UnBotSpecSummonMessage(
		"Все профили повторно помечены для продажи/закупки: "
		..tostring(resetCount).." ботов. Создана новая сохраняемая партия."
	);
end

local function UnBotRegistryFindProfileName(name)
	if (not name or name == "") then
		return nil;
	end
	local wanted = string.lower(tostring(name));
	for savedName in pairs((UnBotBotRegistry and UnBotBotRegistry.bots) or {}) do
		if (string.lower(savedName) == wanted) then
			return savedName;
		end
	end
	return nil;
end

local function UnBotRegistryFlagCommand(message)
	UnBotRegistryAttachStorage();
	message = tostring(message or "");
	message = string.gsub(message, "^%s+", "");
	message = string.gsub(message, "%s+$", "");
	local first, rest = string.match(message, "^(%S+)%s*(.-)$");
	local command = string.lower(first or "");

	if (command == "list" or command == "список") then
		local count = 0;
		for name, profile in pairs(UnBotBotRegistry.bots or {}) do
			local flag = UnBotRegistryGetActiveFlag(profile);
			if (flag) then
				count = count + 1;
				UnBotSpecSummonMessage(
					"Флаг: "..name.." | "..flag.reason.." | до "
					..(flag.untilExit and "выхода из подземелья" or UnBotRegistryFlagTimeText(flag.untilTime)).."."
				);
			end
		end
		UnBotSpecSummonMessage("Активных флагов ротации: "..tostring(count)..".");
		return;
	end

	local action = "quarantine";
	local requestedName = first;
	if (command == "clear" or command == "снять") then
		action = "clear";
		requestedName = rest;
	elseif (command == "status" or command == "статус") then
		action = "status";
		requestedName = rest;
	elseif (command == "ss" or command == "soulstone") then
		action = "soulstone";
		requestedName = rest;
	end
	if (not requestedName or requestedName == "") then
		requestedName = UnitName("target");
	end
	local name = UnBotRegistryFindProfileName(requestedName);
	if (not name) then
		UnBotSpecSummonMessage(
			"Флаги: бот не найден в реестре. Использование: /ubflag <имя>, "
			.."/ubflag clear <имя>, /ubflag status <имя>, /ubflag list."
		);
		return;
	end

	if (action == "clear") then
		UnBotRegistryClearFlags(name);
		UnBotSpecSummonMessage("Ротация: все временные флаги сняты с "..name..".");
	elseif (action == "status") then
		local flag = UnBotRegistryGetActiveFlag(UnBotBotRegistry.bots[name]);
		if (flag) then
			UnBotSpecSummonMessage(
				"Флаг: "..name.." | "..flag.reason.." | до "
				..(flag.untilExit and "выхода из подземелья" or UnBotRegistryFlagTimeText(flag.untilTime)).."."
			);
		else
			UnBotSpecSummonMessage("Флаг: "..name.." доступен для ротации.");
		end
	elseif (action == "soulstone") then
		UnBotRegistryMarkSoulstoneCooldown(name);
	else
		local untilTime = UnBotRegistryNextMorningTimestamp();
		if (UnBotRegistrySetQuarantine(name, "ручной карантин: бот не телепортируется к игроку", untilTime)) then
			UnBotSpecSummonMessage(
				"Ротация: "..name.." помещён в карантин до "
				..UnBotRegistryFlagTimeText(untilTime).."."
			);
		else
			UnBotSpecSummonMessage(
				"Альт "..name.." защищён: карантин к персонажам аккаунта не применяется."
			);
		end
	end
end

local function UnBotRegistryProfileMatches(profile, className, specAliases)
	if (not profile or UnBotSpecSummonNormalize(profile.className) ~= UnBotSpecSummonNormalize(className)) then
		return false;
	end
	-- Talent specializations do not exist yet at levels 1-10. Some playerbot
	-- builds nevertheless report a default 0/0/0 spec, so only the class is
	-- meaningful for every summon path at those levels.
	if (not UnBotSpecSummonPlayerSupportsSpecs()) then
		return true;
	end
	if (specAliases and specAliases.anySpec) then
		return true;
	end
	if (specAliases and specAliases.feralRole) then
		return UnBotFeralProfileRole(profile) == specAliases.feralRole;
	end
	local savedSpec = UnBotSpecSummonNormalize(profile.specName);
	for _, specName in ipairs(specAliases or {}) do
		if (savedSpec == UnBotSpecSummonNormalize(specName)) then
			return true;
		end
	end
	return false;
end

local function UnBotRegistryCandidates(className, specAliases, excluded, includeOtherSpecs)
	UnBotRegistryAttachStorage();
	local candidates = {};
	if (not UnBotRegistryMatchesCurrentContext(UnBotBotRegistry)) then
		return candidates;
	end
	for name, profile in pairs(UnBotBotRegistry.bots or {}) do
		if (
			UnBotIsValidBotName(name)
			and not UnBotIsAccountAltProfile(name, profile)
			and not (excluded and excluded[name])
			and not (
				UnBotMythicPlusBuffShouldExcludeRegistryName
				and UnBotMythicPlusBuffShouldExcludeRegistryName(name)
			)
			and not UnBotRegistryGetActiveFlag(profile)
			and UnBotSpecSummonNormalize(profile.className) == UnBotSpecSummonNormalize(className)
			and (includeOtherSpecs or UnBotRegistryProfileMatches(profile, className, specAliases))
		) then
			table.insert(candidates, name);
		end
	end
	table.sort(candidates, function(a, b)
		local pa = UnBotBotRegistry.bots[a] or {};
		local pb = UnBotBotRegistry.bots[b] or {};
		-- The ground-chest service learns this capability lazily from the bot's
		-- `spells` response. Spell ID 1804 is stable; the displayed spell-list
		-- index is not. Confirmed lockpickers must win over untested rogues.
		if (UnBotSpecSummon.preferLockpick and UnBotSpecSummonNormalize(className) == "rogue") then
			local lockpickA = pa.lockpickSpellKnown == true and 2 or (pa.lockpickSpellKnown == false and 0 or 1);
			local lockpickB = pb.lockpickSpellKnown == true and 2 or (pb.lockpickSpellKnown == false and 0 or 1);
			if (lockpickA ~= lockpickB) then
				return lockpickA > lockpickB;
			end
		end
		-- The saved specialization only prioritizes candidates. It never proves
		-- the current server-side specialization; every selected bot still goes
		-- through add -> who before it can occupy a slot.
		local exactA = UnBotRegistryProfileMatches(pa, className, specAliases);
		local exactB = UnBotRegistryProfileMatches(pb, className, specAliases);
		if (exactA ~= exactB) then
			return exactA;
		end
		-- Общая LRU-ротация: сначала никогда не призывавшиеся и те, кого
		-- не использовали дольше всего. Это распределяет расход реагентов
		-- и накопление добычи между всеми подходящими профилями реестра.
		local sa = tonumber(pa.lastSummonedAt) or 0;
		local sb = tonumber(pb.lastSummonedAt) or 0;
		if (sa ~= sb) then
			return sa < sb;
		end
		local ca = tonumber(pa.summonCount) or 0;
		local cb = tonumber(pb.summonCount) or 0;
		if (ca ~= cb) then
			return ca < cb;
		end
		local ga = tonumber(pa.gearScore) or 0;
		local gb = tonumber(pb.gearScore) or 0;
		if (ga ~= gb) then
			return ga > gb;
		end
		local ta = tonumber(pa.lastSeen) or 0;
		local tb = tonumber(pb.lastSeen) or 0;
		if (ta ~= tb) then
			return ta > tb;
		end
		return string.lower(a) < string.lower(b);
	end);
	return candidates;
end

local function UnBotRegistryCandidateCount(className, specAliases, includeOtherSpecs)
	return #UnBotRegistryCandidates(className, specAliases, nil, includeOtherSpecs);
end

function UnBotGroundChestCandidateList(excluded)
	return UnBotRegistryCandidates(
		"rogue",
		{"assassination", "assasination", "combat", "subtlety"},
		excluded,
		true
	);
end

local function UnBotSpecSummonGetMembers()
	local members = {};
	members[UnitName("player")] = true;
	if (GetNumRaidMembers() and GetNumRaidMembers() > 0) then
		for i = 1, GetNumRaidMembers(), 1 do
			local name = GetRaidRosterInfo(i);
			if (not name or name == UNKNOWNOBJECT or name == UNKNOWN) then
				name = UnitName("raid"..i);
			end
			if (name and name ~= UNKNOWNOBJECT and name ~= UNKNOWN) then
				members[name] = true;
			end
		end
	else
		for i = 1, GetNumPartyMembers(), 1 do
			local name = UnitName("party"..i);
			if (UnBotIsValidBotName(name)) then
				members[name] = true;
			end
		end
	end
	return members;
end

local function UnBotSpecSummonFindNewMember()
	local members = UnBotSpecSummonGetMembers();
	for name in pairs(members) do
		if (not UnBotSpecSummon.knownMembers[name] and name ~= UnitName("player") and not UnBotSpecSummon.checked[name]) then
			UnBotRememberKnownBot(name);
			return name;
		end
	end
	return nil;
end

local function UnBotSpecSummonIsInGroup(name)
	if (not name) then
		return false;
	end
	local members = UnBotSpecSummonGetMembers();
	return members[name] == true;
end

-- MythicPlusBuff.lua lives in a separate chunk so the critical top-level local
-- count of this file does not grow. These narrow wrappers expose only the roster
-- operations required by that module.
function UnBotMythicPlusBuffGetMembers()
	local members = {};
	for name in pairs(UnBotSpecSummonGetMembers()) do
		members[name] = true;
	end
	return members;
end

function UnBotMythicPlusBuffIsInGroup(name)
	return UnBotSpecSummonIsInGroup(name);
end

-- GroundChest.lua is loaded as a separate Lua chunk and therefore cannot call
-- these local roster/registry helpers directly.
function UnBotGroundChestIsInGroup(name)
	return UnBotSpecSummonIsInGroup(name);
end

function UnBotGroundChestRecordGameplaySummon(name, source)
	return UnBotRegistryRecordGameplaySummon(name, source);
end

function UnBotSquadRosterFindUnit(name)
	if (not name) then
		return nil;
	end
	if (UnitName("player") == name) then
		return "player";
	end
	if (GetNumRaidMembers() and GetNumRaidMembers() > 0) then
		for i = 1, GetNumRaidMembers(), 1 do
			local unit = "raid"..i;
			local rosterName = GetRaidRosterInfo(i);
			if (rosterName == name or UnitName(unit) == name) then
				return unit;
			end
		end
	else
		for i = 1, GetNumPartyMembers(), 1 do
			local unit = "party"..i;
			if (UnitName(unit) == name) then
				return unit;
			end
		end
	end
	return nil;
end

function UnBotBotServiceBuildCurrentGroupQueue(operation)
	UnBotRegistryAttachStorage();
	operation = operation or "standard";
	local queue = {};
	local members = UnBotSpecSummonGetMembers();
	for name in pairs(members) do
		local unit = name ~= UnitName("player") and UnBotSquadRosterFindUnit(name) or nil;
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		local accountAlt = UnBotIsAccountAltProfile(name, profile)
			or (UnBotAccountAlts and UnBotAccountAlts.IsListed(name));
		local allowedAlt = accountAlt
			and (operation == "standard" or operation == "fast" or operation == "alt-fast")
			and UnBotAccountAlts
			and UnBotAccountAlts.IsMaintenanceAllowed
			and ((operation == "fast" or operation == "alt-fast")
				and UnBotAccountAlts.IsGrayJunkAllowed(name)
				or (operation == "standard" and UnBotAccountAlts.IsMaintenanceAllowed(name)));
		if (
			unit
			and UnitIsConnected(unit)
			and (profile or (accountAlt and allowedAlt))
			and (
				(operation == "alt-fast" and accountAlt and allowedAlt)
				or (operation ~= "alt-fast" and (not accountAlt or allowedAlt))
			)
		) then
			table.insert(queue, name);
		end
	end
	table.sort(queue, function(a, b)
		local pa = UnBotBotRegistry.bots[a] or {};
		local pb = UnBotBotRegistry.bots[b] or {};
		local classA = UnBotSpecSummonNormalize(pa.className);
		local classB = UnBotSpecSummonNormalize(pb.className);
		if (classA ~= classB) then
			return classA < classB;
		end
		return string.lower(a) < string.lower(b);
	end);
	return queue;
end

function UnBotSquadRosterIsResurrectionReserve(name)
	local storage = UnBotSquadConfig and UnBotSquadConfig.raidReserve;
	if not name or not storage then return false; end
	if storage.druidName == name then return true; end
	for _, field in ipairs({"resurrectionNames", "druidNames"}) do
		for _, saved in ipairs(storage[field] or {}) do if saved == name then return true; end end
	end
	return false;
end

function UnBotSquadRosterIsOfflineReserve(name, unit)
	if (
		not name
		or name == UnitName("player")
		or not UnBotBotRegistry
		or not UnBotBotRegistry.bots
		or not UnBotBotRegistry.bots[name]
	) then
		return false;
	end
	local storage = UnBotSquadConfig and UnBotSquadConfig.raidReserve;
	local savedReserve = storage and storage.druidName == name;
	for _, reserveName in ipairs((storage and storage.resurrectionNames) or {}) do
		if (reserveName == name) then savedReserve = true; break end
	end
	if (not savedReserve and storage and storage.druidNames) then
		for _, reserveName in ipairs(storage.druidNames) do
			if (reserveName == name) then
				savedReserve = true;
				break
			end
		end
	end
	if (not savedReserve) then
		return false;
	end
	local flag = UnBotRegistryGetActiveFlag(UnBotBotRegistry.bots[name]);
	if (flag and flag.kind == "quarantine") then
		return false;
	end
	unit = unit or UnBotSquadRosterFindUnit(name);
	return unit and UnitIsConnected and not UnitIsConnected(unit) and true or false;
end

function UnBotSquadRosterReserveNames()
	local names = {};
	if (not UnBotBotRegistry or not UnBotBotRegistry.bots) then
		return names;
	end
	local members = UnBotSpecSummonGetMembers();
	members[UnitName("player")] = nil;
	for name in pairs(members) do
		if (UnBotSquadRosterIsOfflineReserve(name)) then
			table.insert(names, name);
		end
	end
	table.sort(names);
	return names;
end

local function UnBotSpecSummonUninvite(name)
	if (not name) then
		return;
	end

	if ((UnitAffectingCombat and UnitAffectingCombat("player"))
		or (InCombatLockdown and InCombatLockdown())) then return; end
	local unit = UnBotSquadRosterFindUnit(name);
	UnBotSpecSummon.uninviteAttempts = UnBotSpecSummon.uninviteAttempts or {};
	local now = GetTime();
	for oldName, entry in pairs(UnBotSpecSummon.uninviteAttempts) do
		if now - entry.at > 15 then UnBotSpecSummon.uninviteAttempts[oldName] = nil; end
	end
	if not unit then UnBotSpecSummon.uninviteAttempts[name] = nil; return; end
	local previous = UnBotSpecSummon.uninviteAttempts[name];
	if previous and now - previous.at < 0.5 then return; end
	local attempt = previous and previous.attempt + 1 or 1;
	UnBotSpecSummon.uninviteAttempts[name] = {at = now, attempt = attempt};
	local playerFaction = UnitFactionGroup and UnitFactionGroup("player");
	local targetFaction = unit and UnitFactionGroup and UnitFactionGroup(unit);
	if (attempt == 2 and (not playerFaction or not targetFaction or playerFaction == targetFaction)) then
		SendChatMessage("leave", "WHISPER", nil, name);
	else
		UninviteUnit(attempt == 1 and name or unit);
	end
end

function UnBotMythicPlusBuffUninvite(name)
	UnBotSpecSummonUninvite(name);
end

UnBotSpecSummonMessage = function(text)
	if (UnBotSummonLog) then UnBotSummonLog.Safe("Add", "message", text); end
	if (UnBotBuffDiagnosticAdd) then
		UnBotBuffDiagnosticAdd("message", text);
	end
	if (DisplayInfomation) then
		DisplayInfomation(text);
	else
		DEFAULT_CHAT_FRAME:AddMessage("|cff00cccc"..text.."|r");
	end
end

function UnBotBotCenterMessage(text)
	UnBotSpecSummonMessage(text);
end

-- External modules cannot see the local message function in this chunk.
_G.UnBotSpecSummonMessage = UnBotBotCenterMessage;

local function UnBotSpecSummonAliasMatches(aliases, text, confirmedFeralRole)
	if (not aliases) then
		return false;
	end
	if (aliases.anySpec) then
		return true;
	end
	if (aliases.feralRole) then
		local feralRole = confirmedFeralRole or UnBotFeralRoleFromWhoText(text);
		if (feralRole ~= aliases.feralRole) then
			return false;
		end
		return true;
	end
	for i = 1, #(aliases) do
		local spec = aliases[i];
		if (string.find(text, spec.." (", 1, true)) then
			return true;
		end
	end
	return false;
end

local function UnBotSpecSummonParseWho(message)
	local text = UnBotSpecSummonNormalize(message);
	if (not string.find(text, " lvl", 1, true) or not string.find(text, " gs", 1, true)) then
		return nil;
	end

	local level = tonumber(string.match(text, "lvl%s*[:=]?%s*(%d+)"))
		or tonumber(string.match(text, "(%d+)%s*lvl"));
	local gearScore = tonumber(string.match(text, "gs%s*[:=]?%s*(%d+)"))
		or tonumber(string.match(text, "(%d+)%s*gs"));
	local zoneName = string.match(text, "%(([^()]*)%)%s*,%s*playing with");
	local feralRole, talentBuild = UnBotFeralRoleFromWhoText(text);
	if (not talentBuild) then
		local a,b,c = string.match(text,"(%d+)%s*/%s*(%d+)%s*/%s*(%d+)");
		if (a) then talentBuild=a.."/"..b.."/"..c; end
	end
	local info = {
		text = text,
		className = nil,
		specName = nil,
		level = level,
		gearScore = gearScore,
		zoneName = zoneName,
		feralRole = feralRole,
		talentBuild = talentBuild,
	};
	for className, whoClassName in pairs(UnBotSpecSummonWhoClassNames) do
		if (string.find(text, " "..whoClassName.." ", 1, true)) then
			info.className = className;
			break
		end
	end
	for i = 1, #UnBotSpecSummonWhoSpecs, 1 do
		local spec = UnBotSpecSummonWhoSpecs[i];
		if (
			(not info.className or info.className == spec.className)
			and string.find(text, spec.text.." (", 1, true)
		) then
			info.specName = spec.key;
			break
		end
	end
	return info;
end

function UnBotParseBotWho(message)
	return UnBotSpecSummonParseWho(message);
end

local function UnBotSpecSummonStop(text)
	if UnBotSpecSummon.whoPull then
		UnBotSpecSummon.registryRequests[UnBotSpecSummon.whoPull.name] = nil;
	end
	if (UnBotPVEFastSummon) then UnBotPVEFastSummon.Cancel(); end
	if (UnBotTalentInfo) then UnBotTalentInfo.Cancel(UnBotSpecSummon); end
	if (UnBotSummonLog) then
		UnBotSummonLog.Safe("Observe");
		UnBotSummonLog.Safe("Add", "summon_stop", text);
	end
	for name in pairs(UnBotSpecSummon.rejectedOnline) do
		if UnBotPVEFastSummon and UnBotPVEFastSummon.Enabled() then
			UnBotPVEFastSummon.QueueCleanup(name);
		else
			UnBotSpecSummonUninvite(name);
			UnBotSpecSummon.cleanupQueue[name] = { removeSent = false, untilTime = GetTime() + 30, nextTime = GetTime() + 1 };
		end
	end
	UnBotSpecSummon.rejectedOnline = {};
	UnBotSpecSummon.kickQueue = {};
	if (text) then
		UnBotSpecSummonMessage(text);
	end
	UnBotSpecSummon.active = false;
	UnBotSpecSummon.stage = nil;
	UnBotSpecSummon.candidate = nil;
	UnBotSpecSummon.requestedName = nil;
	UnBotSpecSummon.requestedSlot = nil;
	UnBotSpecSummon.completionAction = nil;
	UnBotSpecSummon.completionSource = nil;
	UnBotSpecSummon.inviteAt = 0;
	UnBotSpecSummon.inviteAttempts = 0;
	UnBotSpecSummon.requestedFallback = false;
	UnBotSpecSummon.initAttempts = 0;
	UnBotSpecSummon.lastInitAt = 0;
	UnBotSpecSummon.whoAttempts = 0;
	UnBotSpecSummon.whoPull = nil;
	UnBotSpecSummon.feralStrategyAttempts = 0;
	UnBotSpecSummon.pendingFeralWhoInfo = nil;
	UnBotSpecSummon.pendingFeralWhoRaw = nil;
	UnBotSpecSummon.extraNames = {};
	UnBotSpecSummon.verifiedCandidates = {};
	UnBotSpecSummon.initUsed = {};
	UnBotSpecSummon.preferLockpick = false;
	UnBotSpecSummon.pvePreset, UnBotSpecSummon.pvePresetDoneName, UnBotSpecSummon.pveVerifiedWho = nil, nil, nil;
	UnBotSpecSummon.pveExistingPrepared, UnBotSpecSummon.pveExistingQueue = nil, nil;
end

UnBotSpecSummon.StopForPreset = UnBotSpecSummonStop;

local function UnBotSpecSummonSquadProgressText()
	if (not UnBotSpecSummon.squad or not UnBotSpecSummon.squad.slots) then
		return "";
	end

	local parts = {};
	for i = 1, #(UnBotSpecSummon.squad.slots) do
		local slot = UnBotSpecSummon.squad.slots[i];
		local label = slot.accountAltName and ("@"..slot.accountAltName)
			or (slot.className.." "..slot.specKey);
		table.insert(parts, label..(slot.skipped and " — пропущен (другая фракция)" or (" "..tostring(slot.have).."/"..tostring(slot.need))));
	end
	return table.concat(parts, ", ");
end

function UnBotSpecSummonIsTankSpec(className, specName)
	className = UnBotSpecSummonNormalize(className);
	specName = UnBotSpecSummonNormalize(specName);
	return (
		(className == "warrior" and (specName == "prot" or specName == "protection"))
		or (className == "paladin" and (specName == "prot" or specName == "protection"))
		or (className == "dk" and specName == "blood")
		or (className == "druid" and specName == "bear")
	) and true or false;
end

function UnBotSpecSummonEnsureFeralRoleStrategy(name, className, specName, source)
	if (UnBotIsAccountAltProfile(name, UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name])) then return false; end
	className = UnBotSpecSummonNormalize(className);
	specName = UnBotSpecSummonNormalize(specName);
	if (
		not UnBotIsValidBotName(name)
		or className ~= "druid"
		or (specName ~= "bear" and specName ~= "cat")
	) then
		return false;
	end
	if (specName == "bear") then
		SendChatMessage("co +tank,+bear,-dps,-cat", "WHISPER", nil, name);
	else
		SendChatMessage("co +dps,+cat,-tank,-bear", "WHISPER", nil, name);
	end
	UnBotRegistryAttachStorage();
	if (UnBotBotRegistry.bots and UnBotBotRegistry.bots[name]) then
		UnBotBotRegistry.bots[name].feralRole = specName;
		UnBotBotRegistry.bots[name].feralRoleSource = "combat-strategy";
		UnBotBotRegistry.bots[name].feralRoleCheckedAt = time();
		UnBotBotRegistry.bots[name].feralRoleStrategySetAt = time();
		UnBotBotRegistry.bots[name].feralRoleStrategySource = source or "feral-role-check";
		UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	end
	UnBotSpecSummonMessage(
		"Feral "..name..": роль "..(specName == "bear" and "танк/медведь" or "ДПС/кошка")
		.." закреплена однозначной боевой стратегией."
	);
	return true;
end

function UnBotSpecSummonEnsureCombatRole(name, className, specName, source)
	if (UnBotSpecSummonEnsureFeralRoleStrategy(name, className, specName, source)) then
		return true;
	end
	return UnBotSpecSummonEnsureTankStrategy(name, className, specName, source);
end

function UnBotSpecSummonEnsureTankStrategy(name, className, specName, source)
	if (UnBotIsAccountAltProfile(name, UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name])) then return false; end
	if (
		not UnBotIsValidBotName(name)
		or not UnBotSpecSummonIsTankSpec(className, specName)
	) then
		return false;
	end
	SendChatMessage("co +tank", "WHISPER", nil, name);
	UnBotRegistryAttachStorage();
	if (UnBotBotRegistry.bots and UnBotBotRegistry.bots[name]) then
		UnBotBotRegistry.bots[name].tankStrategySetAt = time();
		UnBotBotRegistry.bots[name].tankStrategySource = source or "tank-check";
		UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	end
	UnBotSpecSummonMessage(
		"Танк "..name..": обязательная боевая стратегия tank включена (co +tank)."
	);
	return true;
end

function UnBotGroupStrategySendManualProfile(name, enabled)
	if (not UnBotIsValidBotName(name) or name == UnitName("player")) then
		return false;
	end
	local operation = enabled and "+" or "-";
	SendChatMessage("co "..operation.."aoe", "WHISPER", nil, name);
	SendChatMessage("co "..operation.."avoid aoe", "WHISPER", nil, name);
	SendChatMessage("co "..operation.."icc", "WHISPER", nil, name);
	return true;
end

UnBotAltLootAutomation = UnBotAltLootAutomation or {
	managed = false,
	active = false,
	nextAttemptAt = 0,
	expiresAt = 0,
	attempts = 0,
	maxAttempts = 12,
	announce = false,
	reason = nil,
	lastSignature = nil,
};

function UnBotAltLootAutomationScan()
	local altCount = 0;
	local wildCount = 0;
	local unknownCount = 0;
	local members = {};
	for name in pairs(UnBotSpecSummonGetMembers()) do
		local unit = name ~= UnitName("player") and UnBotSquadRosterFindUnit(name) or nil;
		local profile = UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		profile = type(profile) == "table" and profile or nil;
		if (
			UnBotIsValidBotName(name)
			and name ~= UnitName("player")
			and unit
			and UnitIsConnected(unit)
		) then
			if (UnBotIsAccountAltProfile(name, profile)) then
				altCount = altCount + 1;
				members[#members+1] = name..":alt";
			elseif (profile) then
				wildCount = wildCount + 1;
				members[#members+1] = name..":wild";
			else
				unknownCount = unknownCount + 1;
				members[#members+1] = name..":unknown";
			end
		end
	end
	table.sort(members);
	return altCount, wildCount, unknownCount, table.concat(members, "|");
end

function UnBotAltLootAutomationApplied(method)
	if (method == "master") then
		return UnBotGunshipMasterLootPlayerIsMaster
			and UnBotGunshipMasterLootPlayerIsMaster()
			and GetLootThreshold and GetLootThreshold() == 2;
	end
	return GetLootMethod and GetLootMethod() == "freeforall";
end

function UnBotAltLootAutomationArm(reason, silent)
	local state = UnBotAltLootAutomation;
	if (UnBotLootSettings and UnBotLootSettings.MethodAutomationBlocked()) then state.active = false; return; end
	local altCount, wildCount, unknownCount, signature = UnBotAltLootAutomationScan();
	state.managed = true;
	-- Roster/loot events also fire after SetLootMethod. An active cycle keeps
	-- its original deadline, attempt budget and pacing even if members change.
	if (state.active or (silent and state.rosterSignature == signature)) then
		state.rosterSignature = signature;
		if (state.active) then state.announce = state.announce or not silent; end
		return;
	end
	state.rosterSignature = signature;
	state.active = true;
	state.nextAttemptAt = GetTime() + 0.35;
	state.expiresAt = GetTime() + 20;
	state.attempts = 0;
	state.reason = reason or state.reason or "призыв альта";
	state.announce = state.announce or not silent;
end

function UnBotAltLootAutomationTry()
	local state = UnBotAltLootAutomation;
	if (UnBotLootSettings and UnBotLootSettings.MethodAutomationBlocked()) then state.active = false; return false; end
	if (not state.active) then
		return false;
	end
	local now = GetTime();
	local altCount, wildCount, unknownCount, rosterSignature = UnBotAltLootAutomationScan();
	state.rosterSignature = rosterSignature;
	if (unknownCount > 0) then
		state.active = false;
		state.announce = false;
		if (UnBotLootControl) then UnBotLootControl.MethodResult("В группе есть неизвестные участники. Способ добычи выберите вручную; UnBot ими не управляет."); end
		return false;
	end
	if (altCount == 0 and wildCount == 0) then
		state.active = false;
		state.managed = false;
		state.announce = false;
		state.lastSignature = nil;
		return false;
	end
	if ((InCombatLockdown and InCombatLockdown()) or (UnitAffectingCombat and UnitAffectingCombat("player"))) then
		if (now >= (state.expiresAt or 0)) then
			state.active = false;
			state.announce = false;
			if (UnBotLootControl) then UnBotLootControl.MethodResult("Добыча не изменена: бой продолжается. Повторите применение после боя."); end
			UnBotSpecSummonMessage(
				"Лут альтов: способ добычи не изменён — игрок оставался в бою 20 секунд. "
				.."Повторите пункт запрета лута вне боя."
			);
		else
			state.nextAttemptAt = now + 1;
		end
		return false;
	end
	if (not SetLootMethod or not GetLootMethod) then
		state.active = false;
		state.announce = false;
		UnBotSpecSummonMessage("Лут альтов: API способа добычи недоступен.");
		return false;
	end
	local method = wildCount > 0 and "master" or "freeforall";
	local signature = method..":"..tostring(altCount)..":"..tostring(wildCount);
	if (UnBotAltLootAutomationApplied(method)) then
		state.active = false;
		if (UnBotLootControl and UnBotLootControl.awaitingMethod) then
			UnBotLootControl.awaitingMethod = false;
			UnBotLootControl.MethodResult("Способ добычи применён. "..(method == "master" and "Зелёные и более ценные предметы распределяете вы; серые и белые боты могут собирать." or "Включено «Каждый за себя». Личные разрешения проверяются кнопкой «Проверить»."));
		end
		if (state.announce or state.lastSignature ~= signature) then
			if (method == "master") then
				UnBotSpecSummonMessage(
					"Лут альтов: найден дикий бот; после призыва автоматически включён "
					.."мастер-лут на игрока. Альтов: "..tostring(altCount)
					..", диких: "..tostring(wildCount).."."
				);
			else
				UnBotSpecSummonMessage(
					"Лут альтов: после призыва автоматически включено «Каждый за себя». "
					.."Подключённых альтов: "..tostring(altCount).."."
				);
			end
		end
		state.announce = false;
		state.lastSignature = signature;
		return true;
	end
	if (
		now >= (state.expiresAt or 0)
		or (state.attempts or 0) >= (state.maxAttempts or 12)
	) then
		state.active = false;
		state.announce = false;
		if (UnBotLootControl) then UnBotLootControl.MethodResult("Не удалось изменить способ добычи. Нужны права лидера; выберите его вручную или повторите применение."); end
		UnBotSpecSummonMessage(
			"Лут альтов: "..(method == "master" and "мастер-лут" or "«Каждый за себя»")
			.." не применился после "..tostring(state.attempts or 0)
			.." попыток. Нужны права лидера; установите способ добычи вручную."
		);
		return false;
	end
	state.attempts = (state.attempts or 0) + 1;
	state.nextAttemptAt = now + 0.75;
	if (method == "master") then
		if (GetLootMethod() ~= "master" or not UnBotGunshipMasterLootPlayerIsMaster or not UnBotGunshipMasterLootPlayerIsMaster()) then
			pcall(SetLootMethod, "master", UnitName("player"));
		end
		if (SetLootThreshold and (not GetLootThreshold or GetLootThreshold() ~= 2)) then pcall(SetLootThreshold, 2); end
	else
		pcall(SetLootMethod, "freeforall");
	end
	return false;
end

UnBotAltLootAutomationFrame = UnBotAltLootAutomationFrame
	or CreateFrame("Frame", "UnBotAltLootAutomationFrame");
UnBotAltLootAutomationFrame:RegisterEvent("PARTY_MEMBERS_CHANGED");
UnBotAltLootAutomationFrame:RegisterEvent("RAID_ROSTER_UPDATE");
UnBotAltLootAutomationFrame:RegisterEvent("PLAYER_REGEN_ENABLED");
UnBotAltLootAutomationFrame:SetScript("OnEvent", function(self, event)
	if (UnBotAltLootAutomation.managed) then
		UnBotAltLootAutomationArm("изменение состава после призыва альта", true);
	end
end);
UnBotAltLootAutomationFrame:SetScript("OnUpdate", function(self)
	if (
		UnBotAltLootAutomation.active
		and GetTime() >= (UnBotAltLootAutomation.nextAttemptAt or 0)
	) then
		UnBotAltLootAutomationTry();
	end
end);

function UnBotAccountAltApplyQuestSupportProfile(name, source)
	-- Compatibility entry point: no implicit quest/loot profile or chat burst.
	return UnBotAltStrategies and UnBotAltStrategies.OnSummon(name, source) or false;
end

function UnBotGroupStrategyApplyManualProfile(enabled)
	local count = 0;
	for name in pairs(UnBotSpecSummonGetMembers()) do
		local unit = name ~= UnitName("player") and UnBotSquadRosterFindUnit(name) or nil;
		if (unit and UnitIsConnected(unit) and UnBotIsValidBotName(name)) then
			count = count + 1;
		end
	end
	if (count == 0) then
		UnBotSpecSummonMessage("Нет онлайн-ботов в группе / рейде: команды не отправлены.");
		return;
	end
	if (count > 0) then
		local operation = enabled and "+" or "-";
		SendChatMessage("co "..operation.."aoe", "PARTY");
		SendChatMessage("co "..operation.."avoid aoe", "PARTY");
		SendChatMessage("co "..operation.."icc", "PARTY");
	end
	UnBotSpecSummonMessage(
		"Команды "..(enabled and "включения" or "отключения").." aoe, avoid aoe и icc отправлены через /p: онлайн-ботов "
		..tostring(count)..". Результат: «Показать текущие боевые настройки»."
	);
end

UnBotLootHelp = UnBotLootHelp or {};

function UnBotLootHelpToggle()
	UnBotLootControl.Open();
end

function UnBotGroupStrategyDisableLoot()
	UnBotLootControl.Apply();
end

function UnBotGroupStrategyQueryCurrent()
	local count = 0;
	for name in pairs(UnBotSpecSummonGetMembers()) do
		if (UnBotIsValidBotName(name) and name ~= UnitName("player")) then
			SendChatMessage("co ?", "WHISPER", nil, name);
			count = count + 1;
		end
	end
	UnBotSpecSummonMessage("Запрошены боевые стратегии у "..tostring(count).." ботов.");
end

function UnBotGroupStrategyToggleAutoManualProfile()
	UnBotSquadConfig = UnBotSquadConfig or {};
	UnBotSquadConfig.autoManualRaidStrategies = not UnBotSquadConfig.autoManualRaidStrategies;
	UnBotSpecSummonMessage(
		"Автоматический ручной рейдовый профиль после обычного призыва: "
		..(UnBotSquadConfig.autoManualRaidStrategies and "ВКЛ." or "ВЫКЛ.")
	);
end

function UnBotGroupStrategyOnGameplaySummon(name, source)
	local accountAltAdjusted = UnBotAccountAltApplyQuestSupportProfile(name, source);
	if (UnBotIsAccountAltProfile(name, UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name])) then
		return accountAltAdjusted;
	end
	if (
		not UnBotSquadConfig
		or not UnBotSquadConfig.autoManualRaidStrategies
		or not UnBotIsValidBotName(name)
	) then
		return accountAltAdjusted;
	end
	-- Боссовые пресеты управляют icc и фокусом сами. Например, Саурфангу
	-- стратегия icc нужна для кровавых чудовищ, а экспериментальный профиль
	-- Мерзоцида полностью фиксирует мили-ДД на боссе. Автопрофиль применяется
	-- только к обычному призыву.
	if (
		(UnBotSpecSummon and UnBotSpecSummon.mode == "squad")
		or (source and string.find(source, "portal", 1, true))
		or (source and string.find(source, "lockbox-service", 1, true))
	) then
		return accountAltAdjusted;
	end
	return UnBotGroupStrategySendManualProfile(name, false) or accountAltAdjusted;
end

UnBotProtectionPaladinSelfHeal = UnBotProtectionPaladinSelfHeal or {
	nextScanAt = 0,
	bots = {},
};

function UnBotProtectionPaladinSelfHealUnitProfile(unit)
	if (
		not unit
		or not UnitExists(unit)
		or not UnitIsConnected(unit)
		or UnitIsDeadOrGhost(unit)
	) then
		return nil, nil;
	end
	local name = UnitName(unit);
	local profile = name and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (
		not profile
		or UnBotSpecSummonNormalize(profile.className) ~= "paladin"
		or (
			UnBotSpecSummonNormalize(profile.specName) ~= "protection"
			and UnBotSpecSummonNormalize(profile.specName) ~= "prot"
		)
	) then
		return nil, nil;
	end
	return name, profile;
end

function UnBotProtectionPaladinSelfHealCommand(unit, name, now)
	local maximum = tonumber(UnitHealthMax(unit)) or 0;
	if (maximum <= 0 or not UnitAffectingCombat(unit)) then
		return;
	end
	local health = tonumber(UnitHealth(unit)) or 0;
	local percent = health * 100 / maximum;
	local bot = UnBotProtectionPaladinSelfHeal.bots[name] or {
		nextHealAt = 0,
		nextEmergencyAt = 0,
		emergencyUsed = false,
		band = "healthy",
	};
	UnBotProtectionPaladinSelfHeal.bots[name] = bot;

	if (percent >= 68) then
		bot.band = "healthy";
		bot.emergencyUsed = false;
		return;
	end

	if (
		percent <= 18
		and not bot.emergencyUsed
		and now >= (bot.nextEmergencyAt or 0)
	) then
		SendChatMessage("cast Lay on Hands on "..name, "WHISPER", nil, name);
		bot.emergencyUsed = true;
		bot.nextEmergencyAt = now + 15;
		bot.nextHealAt = now + 1.4;
		if (bot.band ~= "emergency") then
			UnBotSpecSummonMessage(
				"Прот-пал "..name..": критические "..tostring(math.floor(percent + 0.5))
				.."% HP — приказано Возложение рук на себя."
			);
		end
		bot.band = "emergency";
		return;
	end

	if (percent <= 52 and now >= (bot.nextHealAt or 0)) then
		SendChatMessage("cast Holy Light on "..name, "WHISPER", nil, name);
		bot.nextHealAt = now + 2.6;
		if (bot.band == "healthy") then
			UnBotSpecSummonMessage(
				"Прот-пал "..name..": "..tostring(math.floor(percent + 0.5))
				.."% HP — включено аварийное самолечение Светом небес."
			);
		end
		bot.band = percent <= 18 and "emergency" or "healing";
	end
end

function UnBotProtectionPaladinSelfHealScan(now)
	if (GetNumRaidMembers() and GetNumRaidMembers() > 0) then
		for i = 1, math.min(40, GetNumRaidMembers()), 1 do
			local unit = "raid"..i;
			local name = UnBotProtectionPaladinSelfHealUnitProfile(unit);
			if (name) then
				UnBotProtectionPaladinSelfHealCommand(unit, name, now);
			end
		end
	else
		for i = 1, math.min(4, GetNumPartyMembers() or 0), 1 do
			local unit = "party"..i;
			local name = UnBotProtectionPaladinSelfHealUnitProfile(unit);
			if (name) then
				UnBotProtectionPaladinSelfHealCommand(unit, name, now);
			end
		end
	end
end

UnBotProtectionPaladinSelfHealFrame = UnBotProtectionPaladinSelfHealFrame
	or CreateFrame("Frame", "UnBotProtectionPaladinSelfHealFrame");
UnBotProtectionPaladinSelfHealFrame:SetScript("OnUpdate", function()
	local now = GetTime();
	if (now < (UnBotProtectionPaladinSelfHeal.nextScanAt or 0)) then
		return;
	end
	UnBotProtectionPaladinSelfHeal.nextScanAt = now + 0.2;
	UnBotProtectionPaladinSelfHealScan(now);
end);

function UnBotSpecSummonHasFreshConfirmation(name)
	if UnBotSpecSummon.confirmedRoster then
		return UnBotSpecSummon.confirmedRoster.Get(name,"who")~=nil
			and (not UnBotBuffCycleCasterReady or UnBotBuffCycleCasterReady(name));
	end
	local observation = UnBotSpecSummon.verifiedCandidates and UnBotSpecSummon.verifiedCandidates[name];
	local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	local unit = UnBotSquadRosterFindUnit(name);
	return observation and profile and observation.guid and unit and UnitIsConnected(unit)
		and (not UnBotBuffCycleCasterReady or UnBotBuffCycleCasterReady(name))
		and not observation.disconnected and GetTime() - observation.checkedAt <= 90
		and UnitGUID(unit) == observation.guid and observation.className == profile.className
		and observation.specName == profile.specName and observation.feralRole == profile.feralRole;
end

local function UnBotSpecSummonFinishSquad(messagePrefix)
	if (UnBotGunshipMasterLoot and UnBotGunshipMasterLoot.CheckSummon
		and not UnBotGunshipMasterLoot.CheckSummon(true)) then
		if (UnBotSpecSummon.active) then
			UnBotSpecSummon.stage = "wait_next";
			UnBotSpecSummon.stageTime = GetTime() + 0.2;
		end
		return;
	end
	UnBotSquadBuilder.postSummonSequence = UnBotSquadBuilder.postSummonSequence or {buffRaid = false};
	UnBotSquadBuilder.postSummonSequence.requireArrival = true;
	UnBotSquadBuilder.postSummonSequence.arrivalChecked = false;
	-- Arrival replacements must not retry refused named positions.
	local arrivalRequirements = {};
	local skippedCount = 0;
	for _, slot in ipairs(UnBotSpecSummon.squad.slots) do
		if (not slot.skipped) then
			table.insert(arrivalRequirements, slot.accountAltName and ("@"..slot.accountAltName)
				or (slot.className.." "..slot.specKey.." "..tostring(slot.need)));
		else
			skippedCount = skippedCount + 1;
		end
	end
	UnBotSquadBuilder.postSummonSequence.requirementsText = table.concat(arrivalRequirements, ", ");
	UnBotSquadBuilder.postSummonSequence.arrivalNames = {};
	-- Carry observations across arrival replacements, not across manual starts.
	UnBotSquadBuilder.postSummonSequence.checkedCandidates = {};
	for name in pairs(UnBotSpecSummon.checked or {}) do
		UnBotSquadBuilder.postSummonSequence.checkedCandidates[name] = true;
	end
	for _, slot in ipairs(UnBotSpecSummon.squad.slots or {}) do
		for name in pairs(slot.names or {}) do
			UnBotSquadBuilder.postSummonSequence.arrivalNames[name] = true;
		end
	end
	local progress = UnBotSpecSummonSquadProgressText();
	local summonedNames = {};
	local summonedAltCount = 0;
	local referenceZone = UnBotSpecSummon.squad and UnBotSpecSummon.squad.referenceZone;
	local postCheckScheduled = false;
	for name in pairs((UnBotSpecSummon.squad and UnBotSpecSummon.squad.summonedNames) or {}) do
		if (UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots and UnBotBotRegistry.bots[name])) then
			summonedAltCount = summonedAltCount + 1;
		elseif (not UnBotSpecSummonHasFreshConfirmation(name)) then
			table.insert(summonedNames, name);
		end
	end
	table.sort(summonedNames);
	UnBotSpecSummonStop((skippedCount > 0 and ("Доступные позиции собраны; пропущено из-за фракции "..tostring(skippedCount)..": ")
		or "Слоты по классу/спеку заполнены: ")..progress..". Проверяю фактическое прибытие ботов.");
	if (#summonedNames == 0) then
		UnBotSpecSummonMessage(
			(summonedAltCount > 0
				and "Именные альты добавлены без проверки специализации; новых обычных ботов для проверки нет."
				or "Состав подтверждён: повторный who для уже проверенных ботов не требуется.")
		);
	elseif (not UnBotSpecSummonPlayerSupportsSpecs()) then
		UnBotSpecSummonMessage(
			"Уровень "..tostring(UnitLevel("player") or "?")
			..": состав принят по классам; итоговая проверка специализаций и init отключены до 11 уровня."
		);
	elseif (UnBotSquadSpecCheckSchedule) then
		UnBotSquadSpecCheckSchedule(summonedNames, referenceZone);
		postCheckScheduled = true;
	elseif (UnBotSquadSpecCheckStart) then
		UnBotSquadSpecCheckStart({
			queue = summonedNames,
			mode = "post_summon",
			referenceZone = referenceZone,
		});
		postCheckScheduled = true;
	end
	if (not postCheckScheduled) then
		if (UnBotSquadPostSummonContinue) then
			UnBotSquadPostSummonContinue();
		elseif (UnBotBossPresetAfterSquadComplete) then
			UnBotBossPresetAfterSquadComplete();
		end
	end

end

local function UnBotSpecSummonSquadComplete()
	if (not UnBotSpecSummon.squad or not UnBotSpecSummon.squad.slots) then
		return false;
	end

	for i = 1, #(UnBotSpecSummon.squad.slots) do
		local slot = UnBotSpecSummon.squad.slots[i];
		if (not slot.skipped and slot.have < slot.need) then
			return false;
		end
	end
	return true;
end

local function UnBotSpecSummonSquadPickClass()
	if (not UnBotSpecSummon.squad or not UnBotSpecSummon.squad.slots) then
		return nil;
	end

	for i = 1, #(UnBotSpecSummon.squad.slots) do
		local slot = UnBotSpecSummon.squad.slots[i];
		if (not slot.skipped and slot.have < slot.need) then
			return slot.className;
		end
	end
	return nil;
end

local function UnBotSpecSummonSquadAccept(name, whoInfo)
	if (not whoInfo or not whoInfo.className or not UnBotSpecSummon.squad or not UnBotSpecSummon.squad.slots) then
		return false;
	end

	for i = 1, #(UnBotSpecSummon.squad.slots) do
		local slot = UnBotSpecSummon.squad.slots[i];
		local namedMatch = slot.accountAltName and name == slot.accountAltName;
		local lowLevelClassMatch = not UnBotSpecSummonPlayerSupportsSpecs()
			and not slot.accountAltName
			and slot.className == whoInfo.className;
		local roleMatch = not slot.accountAltName
			and not UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots and UnBotBotRegistry.bots[name])
			and slot.className == whoInfo.className
			and (lowLevelClassMatch or UnBotSpecSummonAliasMatches(
				slot.specAliases,
				whoInfo.text,
				whoInfo.feralRole
			));
		if (slot.have < slot.need and (namedMatch or roleMatch)) then
			if (namedMatch) then
				slot.className = whoInfo.className or slot.className;
				if (whoInfo.specName) then
					slot.specKey = whoInfo.specName;
					slot.specAliases = {whoInfo.specName};
				end
			end
			slot.have = slot.have + 1;
			slot.names[name] = true;
			UnBotSpecSummon.squad.summonedNames[name] = true;
			UnBotSpecSummon.CancelStaleCleanup(name);
			UnBotSpecSummon.checked[name] = true;
			local summonCount = UnBotRegistryRecordGameplaySummon(name, "squad-who");
			UnBotGroupStrategyOnGameplaySummon(name, "squad-who");
			if (UnBotSpecSummonPlayerSupportsSpecs()) then
				UnBotSpecSummonEnsureCombatRole(
					name,
					slot.className,
					slot.specKey,
					"squad-who"
				);
			end
			if (lowLevelClassMatch) then
				UnBotSpecSummonMessage(
					"Строгий подбор: "..name.." — уровень "..tostring(whoInfo.level)
					..", таланты ещё недоступны; слот "..tostring(slot.className).." "
					..tostring(slot.specKey).." зачтён по классу без init."
				);
			end
			UnBotSpecSummonMessage(
				"Squad summon kept: "..name.." -> "..slot.className.." "..slot.specKey
				.." ("..tostring(slot.have).."/"..tostring(slot.need).."), summons "
				..tostring(summonCount or "?").."."
			);
			return true;
		end
	end
	return false;
end

local function UnBotSpecSummonAcceptRegistryCandidate(name)
	local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (not profile) then
		return false;
	end

	if (UnBotSpecSummon.mode == "squad") then
		local requestedSlot = UnBotSpecSummon.requestedSlot;
		local slot;
		local lowLevelClassMatch = false;
		if (requestedSlot and requestedSlot.accountAltName and name == requestedSlot.accountAltName) then
			slot = requestedSlot;
		else
			-- Dynamic factual assignment: a bot whose server-side spec changed can
			-- fill any still-open compatible slot. The saved profile only decided
			-- which name was tried first.
			for _, wantedSlot in ipairs(UnBotSpecSummon.squad.slots or {}) do
				local lowLevelMatch = not UnBotSpecSummonPlayerSupportsSpecs()
					and not wantedSlot.accountAltName
					and UnBotSpecSummonNormalize(profile.className)
						== UnBotSpecSummonNormalize(wantedSlot.className);
				local roleMatch = not wantedSlot.accountAltName
					and not UnBotIsAccountAltProfile(name, profile)
					and (lowLevelMatch or UnBotRegistryProfileMatches(
						profile,
						wantedSlot.className,
						wantedSlot.specAliases
					));
				if (wantedSlot.have < wantedSlot.need and roleMatch) then
					slot = wantedSlot;
					lowLevelClassMatch = lowLevelMatch and true or false;
					break
				end
			end
		end
		if (not slot or slot.have >= slot.need) then
			return false;
		end
		if (slot.accountAltName) then
			slot.className = profile.className or slot.className;
			if (profile.specName) then
				slot.specKey = profile.specName;
				slot.specAliases = {profile.specName};
			end
		end
		slot.have = slot.have + 1;
		slot.names[name] = true;
		UnBotSpecSummon.squad.summonedNames[name] = true;
		UnBotSpecSummon.CancelStaleCleanup(name);
		UnBotSpecSummon.checked[name] = true;
		UnBotSpecSummon.registryRequests[name] = nil;
		UnBotRememberKnownBot(name);
		local summonCount = UnBotRegistryRecordGameplaySummon(name, "squad-registry");
		UnBotGroupStrategyOnGameplaySummon(name, "squad-registry");
		if (UnBotSpecSummonPlayerSupportsSpecs()) then
			UnBotSpecSummonEnsureCombatRole(
				name,
				slot.className,
				slot.specKey,
				"squad-registry"
			);
		end
		if (lowLevelClassMatch) then
			UnBotSpecSummonMessage(
				"Подбор до 11 уровня: "..name.." занял слот класса "
				..tostring(slot.className).." без проверки специализации и без init."
			);
		end
		if (requestedSlot and requestedSlot ~= slot) then
			UnBotSpecSummonMessage(
				"Фактическое распределение: "..name.." оказался "
				..tostring(profile.className).." "..tostring(profile.specName)
				.." и занял другой открытый слот "..tostring(slot.className)
				.." "..tostring(slot.specKey)..". Сохранённый спек был только подсказкой."
			);
		end
		UnBotSpecSummonMessage(
			"Squad registry summon kept: "..name.." -> "..tostring(slot.className or "unknown").." "
			..tostring(profile.specName).." ("..tostring(slot.have).."/"..tostring(slot.need)
			.."), summons "..tostring(summonCount or "?").."."
		);
		UnBotSpecSummon.candidate = nil;
		UnBotSpecSummon.requestedName = nil;
		UnBotSpecSummon.requestedSlot = nil;
		if (UnBotSpecSummonSquadComplete()) then
			if (UnBotPVEFastSummon and UnBotPVEFastSummon.BeforeFinish()) then return true; end
			UnBotSpecSummonFinishSquad("Squad registry summon complete: ");
		else
			UnBotSpecSummon.stage = "wait_next";
			UnBotSpecSummon.stageTime = GetTime() + (UnBotBatchSummon and 0.02 or 0.5);
		end
		return true;
	end

	if (not UnBotRegistryProfileMatches(profile, UnBotSpecSummon.className, UnBotSpecSummon.specAliases)) then
		return false;
	end
	UnBotSpecSummon.checked[name] = true;
	UnBotSpecSummon.registryRequests[name] = nil;
	UnBotRememberKnownBot(name);
	local completionAction = UnBotSpecSummon.completionAction;
	local completionSource = UnBotSpecSummon.completionSource;
	local summonSource = completionAction and ((completionSource or "service").."-registry") or "spec-registry";
	local summonCount = UnBotRegistryRecordGameplaySummon(name, summonSource);
	UnBotGroupStrategyOnGameplaySummon(name, summonSource);
	if (UnBotSpecSummonPlayerSupportsSpecs()) then
		UnBotSpecSummonEnsureCombatRole(
			name,
			profile.className,
			UnBotSpecSummon.specName or profile.specName,
			summonSource
		);
	else
		UnBotSpecSummonMessage(
			"Подбор до 11 уровня: "..name.." выбран только по классу "
			..tostring(profile.className).."; who специализации и init не выполняются."
		);
	end
	UnBotSpecSummonStop(
		"Spec registry summon matched: "..name.." ("
		..tostring(profile.className).." "
		..tostring(UnBotSpecSummonPlayerSupportsSpecs()
			and (UnBotFeralProfileRole(profile) or profile.specName)
			or "class-only")
		..", GS "..tostring(profile.gearScore or "?")
		..", summons "..tostring(summonCount or "?")..")."
	);
	if (completionAction) then
		completionAction(name);
	end
	return true;
end

-- A saved profile is only a hint. Ordinary registry summons are confirmed
-- with `who`; exact account-alt slots are accepted by name and refreshed
-- asynchronously after the protected character has entered the group.
function UnBotSpecSummonStoreRegistryWho(name, whoInfo, rawWho)
	local existingProfile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	local accountAlt = UnBotIsAccountAltProfile(name, existingProfile);
	if (
		not UnBotIsValidBotName(name)
		or not whoInfo
		or not whoInfo.className
		or (not whoInfo.specName and not accountAlt)
	) then
		return nil, nil;
	end
	UnBotRegistryAttachStorage();
	local profile = UnBotBotRegistry.bots[name] or {
		name = name,
		firstSeen = time(),
		seenCount = 0,
	};
	local oldClass = profile.className;
	local oldSpec = profile.specName;
	profile.name = name;
	profile.className = whoInfo.className;
	profile.specName = whoInfo.specName or profile.specName;
	profile.level = whoInfo.level or profile.level;
	profile.gearScore = whoInfo.gearScore or profile.gearScore;
	profile.rawWho = rawWho or profile.rawWho;
	UnBotStoreFeralRole(profile, whoInfo);
	if (whoInfo.feralRoleSource == "combat-strategy") then
		profile.feralRoleSource = "combat-strategy";
		profile.feralRoleCheckedAt = time();
	end
	if (UnBotIsAccountAltProfile(name, profile)) then
		profile.accountAlt = true;
		profile.protectedAccountCharacter = true;
		profile.rotationAllowed = false;
		profile.source = "account-alt";
	elseif (UnBotSpecSummon.mode == "squad") then
		if (UnBotSpecSummon.requestedFallback and tonumber(whoInfo.level) and tonumber(whoInfo.level) < 10) then
			profile.source = "strict-squad-low-level";
		elseif (UnBotSpecSummon.requestedFallback and (UnBotSpecSummon.initAttempts or 0) > 0) then
			profile.source = "strict-squad-init";
		else
			profile.source = "strict-squad-who";
		end
	else
		profile.source = "strict-spec-who";
	end
	profile.lastSeen = time();
	profile.specCheckedAt = time();
	profile.seenCount = (profile.seenCount or 0) + 1;
	if (UnBotSpecSummon.requestedFallback and (UnBotSpecSummon.initAttempts or 0) > 0) then
		profile.specRebalancedAt = time();
		profile.specRebalanceFrom = oldSpec;
		profile.specRebalanceTarget = UnBotSpecSummon.requestedSlot and UnBotSpecSummon.requestedSlot.specKey;
		profile.specRebalanceInitAttempts = UnBotSpecSummon.initAttempts;
	end
	UnBotBotRegistry.bots[name] = profile;
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	UnBotRememberKnownBot(name);
	if (not profile.accountAlt) then
		UnBotSpecSummon.verifiedCandidates = UnBotSpecSummon.verifiedCandidates or {};
		UnBotSpecSummon.verifiedCandidates[name] = {
			className = whoInfo.className,
			specName = whoInfo.specName,
			feralRole = whoInfo.feralRole,
			level = whoInfo.level,
			checkedAt = GetTime(),
			guid = UnitGUID and UnBotSquadRosterFindUnit(name) and UnitGUID(UnBotSquadRosterFindUnit(name)),
		};
	end
	if (profile.accountAlt and UnBotAccountAlts and UnBotAccountAlts.ProtectProfile) then
		UnBotAccountAlts.ProtectProfile(name, whoInfo, rawWho);
	end
	if UnBotSpecSummon.confirmedRoster then UnBotSpecSummon.confirmedRoster.Who(name,whoInfo);end
	return oldClass, oldSpec;
end

-- Restored 6.38.164 donor selection, verified against 6.38.155.
-- A donor is used only after factual who checks of the available class.
function UnBotSpecSummonFindFallbackCandidate(slot)
	if (not slot or slot.accountAltName or not UnBotSpecSummon.squad) then
		return nil, nil, 0;
	end
	if (slot.specAliases and slot.specAliases.anySpec) then
		-- A class-only slot accepts every real specialization and must never
		-- initialize a verified bot merely to manufacture a synthetic "any" spec.
		return nil, nil, 0;
	end
	local availableBySpec = {};
	local requiredBySpec = {};
	local namesBySpec = {};
	local cleanupPending = {};
	for _, wantedSlot in ipairs(UnBotSpecSummon.squad.slots or {}) do
		if (wantedSlot.className == slot.className and wantedSlot.have < wantedSlot.need) then
			local wantedSpec = UnBotSpecSummonNormalize((wantedSlot.specAliases or {})[1] or wantedSlot.specKey);
			if (UnBotSpecCountBalanceNormalizeSpec) then
				wantedSpec = UnBotSpecCountBalanceNormalizeSpec(wantedSpec);
			end
			if (wantedSlot.specAliases and wantedSlot.specAliases.feralRole) then
				wantedSpec = wantedSpec..":"..wantedSlot.specAliases.feralRole;
			end
			requiredBySpec[wantedSpec] = (requiredBySpec[wantedSpec] or 0) + wantedSlot.need - wantedSlot.have;
		end
	end
	for name, observation in pairs(UnBotSpecSummon.verifiedCandidates or {}) do
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (
			UnBotIsValidBotName(name)
			and profile
			and not UnBotIsAccountAltProfile(name, profile)
			and not (UnBotSpecSummon.squad.summonedNames or {})[name]
			and not (UnBotSpecSummon.initUsed or {})[name]
			and not (UnBotPVEFastSummon and UnBotPVEFastSummon.blocked[name])
			and not UnBotRegistryGetActiveFlag(profile)
			and not UnBotSpecSummonIsInGroup(name)
			and UnBotSpecSummonNormalize(observation.className) == UnBotSpecSummonNormalize(slot.className)
		) then
			local specName = UnBotSpecSummonNormalize(observation.specName);
			if (UnBotSpecCountBalanceNormalizeSpec) then
				specName = UnBotSpecCountBalanceNormalizeSpec(specName);
			end
			if (specName == "feral combat" and observation.feralRole) then
				specName = specName..":"..observation.feralRole;
			end
			if (specName ~= "") then
				availableBySpec[specName] = (availableBySpec[specName] or 0) + 1;
				namesBySpec[specName] = namesBySpec[specName] or {};
				if (UnBotSpecSummon.cleanupQueue[name]) then
					cleanupPending[specName] = true;
				else
					table.insert(namesBySpec[specName], name);
				end
			end
		end
	end
	local donorSpec;
	local donorCount = 0;
	local donorSurplus = 0;
	for specName, count in pairs(availableBySpec) do
		local surplus = count - (requiredBySpec[specName] or 0);
		if (
			surplus > 0
			and (
				not donorSpec
				or count > donorCount
				or (count == donorCount and surplus > donorSurplus)
				or (count == donorCount and surplus == donorSurplus and specName < donorSpec)
			)
		) then
			donorSpec = specName;
			donorCount = count;
			donorSurplus = surplus;
		end
	end
	if (not donorSpec) then
		return nil, nil, 0;
	end
	local candidates = namesBySpec[donorSpec] or {};
	table.sort(candidates, function(a, b)
		local pa = UnBotBotRegistry.bots[a] or {};
		local pb = UnBotBotRegistry.bots[b] or {};
		local sa = tonumber(pa.lastSummonedAt) or 0;
		local sb = tonumber(pb.lastSummonedAt) or 0;
		if (sa ~= sb) then
			return sa < sb;
		end
		return string.lower(a) < string.lower(b);
	end);
	if (not candidates[1] and cleanupPending[donorSpec]) then
		-- The verified donor is still awaiting confirmed group exclusion.
		-- Wait instead of racing an add against our own cleanup command.
		return nil, donorSpec, -1;
	end
	return candidates[1], donorSpec, donorCount;
end

function UnBotSpecSummonBeginRegistryWho(name)
	UnBotSpecSummon.whoPull = nil;
	if (not name) then
		return;
	end
	if (not UnBotSpecSummonPlayerSupportsSpecs()) then
		if (not UnBotSpecSummonAcceptRegistryCandidate(name)) then
			UnBotSpecSummonStop(
				"Подбор до 11 уровня остановлен: профиль "..tostring(name)
				.." не подтверждает требуемый класс; команды who и init не отправлялись."
			);
		end
		return;
	end
	if (
		UnBotSpecSummon.mode == "squad"
		and UnBotSpecSummon.requestedSlot
		and UnBotSpecSummon.requestedSlot.accountAltName == name
	) then
		if (UnBotAccountAlts and UnBotAccountAlts.RefreshProfileFromUnit) then
			UnBotAccountAlts.RefreshProfileFromUnit(name);
		end
		UnBotSpecSummonMessage(
			"Именной альт "..name
			.." вошёл в группу и подтверждён по точному имени; сведения прочитаны из ростера без who."
		);
		if (not UnBotSpecSummonAcceptRegistryCandidate(name)) then
			UnBotSpecSummonStop(
				"Именной альт "..name
				.." вошёл в группу, но его защищённый профиль недоступен."
			);
		end
		return;
	end
	if (UnBotBatchSummon and UnBotBatchSummon.DeliverCached(name)) then return; end
	UnBotSpecSummon.stage = "wait_registry_who";
	UnBotSpecSummon.stageTime = GetTime() + 5;
	UnBotSpecSummon.whoAttempts = 1;
	SendChatMessage("who", "WHISPER", nil, name);
	UnBotSpecSummonMessage(
		"Строгая проверка: "..name.." вошёл в состав; подтверждаю фактический класс/спек через who."
	);
end

function UnBotSpecSummonSendRegistryInit()
	local name = UnBotSpecSummon.requestedName;
	if (not name) then
		return;
	end
	if (not UnBotSpecSummonPlayerSupportsSpecs()) then
		UnBotSpecSummonStop(
			"Init отменён: до 11 уровня специализации не проверяются и не изменяются."
		);
		return;
	end
	local slot = UnBotSpecSummon.requestedSlot;
	local observation = UnBotSpecSummon.verifiedCandidates
		and UnBotSpecSummon.verifiedCandidates[name];
	if (
		not UnBotSpecSummon.requestedFallback
		or not observation
		or not observation.className
		or not observation.specName
		or not slot
		or slot.accountAltName
		or slot.have >= slot.need
		or UnBotSpecSummonNormalize(observation.className)
			~= UnBotSpecSummonNormalize(slot.className)
	) then
		UnBotSpecSummon.rejectedOnline[name] = true;
		UnBotSpecSummonStop(
			"Защита общего пула: init для "..tostring(name)
			.." отменён — нет свежего who и подтверждённого незаполненного слота."
		);
		return;
	end
	-- Never reinitialize an unconfirmed, unavailable or protected character.
	local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	local unit = UnBotSquadRosterFindUnit(name);
	if (not profile or UnBotIsAccountAltProfile(name,profile) or UnBotSquadRosterIsOfflineReserve(name)
		or UnBotRegistryGetActiveFlag(profile) or not UnBotRegistryMatchesCurrentContext(UnBotBotRegistry)
		or not unit or not UnitIsConnected(unit) or UnitIsDeadOrGhost(unit)
		or UnitAffectingCombat("player") or InCombatLockdown() or UnitAffectingCombat(unit)
		or not observation.checkedAt or GetTime() - observation.checkedAt > 15) then
		UnBotSpecSummonStop("Ребалансировка PvE остановлена: донор недоступен, защищён или нет свежего who.");
		return;
	end
	if ((UnBotSpecSummon.initAttempts or 0) >= (UnBotSpecSummon.maxInitAttempts or 6)) then
		UnBotSpecSummonMessage(
			"Строгий подбор: "..name.." не получил нужный спек за "
			..tostring(UnBotSpecSummon.maxInitAttempts or 6).." init; пробую другого донора."
		);
		if UnBotPVEFastSummon and UnBotPVEFastSummon.Reject(name) then return; end
		UnBotSpecSummon.checked[name] = true;
		UnBotSpecSummon.rejectedOnline[name] = true;
		UnBotSpecSummonUninvite(name);
		UnBotSpecSummon.kickQueue[name] = {
			untilTime = GetTime() + 15,
			nextTime = GetTime() + 1,
			attempts = 0,
			maxAttempts = 3,
		};
		UnBotSpecSummon.stage = "wait_rejected_leave";
		UnBotSpecSummon.stageTime = GetTime() + 0.5;
		UnBotSpecSummon.stageUntil = GetTime() + 15;
		return;
	end
	local now = GetTime();
	local allowedAt = (UnBotSpecSummon.lastInitAt or 0) + 3;
	if ((UnBotSpecSummon.lastInitAt or 0) > 0 and now < allowedAt) then
		UnBotSpecSummon.stage = "wait_registry_init_rate";
		UnBotSpecSummon.stageTime = allowedAt;
		return;
	end
	UnBotSpecSummon.initAttempts = (UnBotSpecSummon.initAttempts or 0) + 1;
	UnBotSpecSummon.lastInitAt = now;
	UnBotSpecSummon.whoAttempts = 0;
	SendChatMessage(".playerbot bot init "..name, "SAY");
	UnBotSpecSummon.stage = "wait_registry_init_settle";
	UnBotSpecSummon.stageTime = now + 1;
	UnBotSpecSummonMessage(
		"Строгий подбор: "..name.." — init "..tostring(UnBotSpecSummon.initAttempts)
		.."/"..tostring(UnBotSpecSummon.maxInitAttempts or 6).." для "
		..tostring(UnBotSpecSummon.requestedSlot and UnBotSpecSummon.requestedSlot.className or "?")
		.." "..tostring(UnBotSpecSummon.requestedSlot and UnBotSpecSummon.requestedSlot.specKey or "?").."."
	);
end

function UnBotSpecSummon.SkipEnemyAlt(name)
	local state = UnBotSpecSummon;
	local found = false;
	for _, slot in ipairs(state.squad and state.squad.slots or {}) do
		if (slot.accountAltName == name and not slot.skipped) then
			slot.skipped = "opposite-faction";
			found = true;
		end
	end
	if (not found) then return false; end
	state.checked[name] = true;
	state.registryRequests[name] = nil;
	if (state.squad.prefetchPending) then state.squad.prefetchPending[name] = nil; end
	UnBotSpecSummonMessage(UnBotAccountAlts.SquadFactionStatus(name).." Продолжаю призыв остальных участников.");
	if (state.requestedName == name) then
		state.candidate, state.requestedName, state.requestedSlot = nil, nil, nil;
		state.inviteAt, state.inviteAttempts = 0, 0;
		state.stage, state.stageTime = "wait_next", GetTime() + 0.1;
	end
	if (UnBotSquadBuilderRefresh) then UnBotSquadBuilderRefresh(); end
	return true;
end

function UnBotSpecSummon.EnemyAltReply(event, message)
	local state = UnBotSpecSummon;
	if (event ~= "CHAT_MSG_SYSTEM" or state.mode ~= "squad" or not state.squad or not UnBotAccountAlts) then return false; end
	message = tostring(message or ""):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "");
	local name, result = string.match(message, "[Aa]dd:%s*([^%s]+)%s*%-%s*(.+)");
	if (not name or not string.find(string.lower(result), "opposite faction", 1, true)) then return false; end
	for _, slot in ipairs(state.squad.slots) do
		if (slot.accountAltName and UnBotSpecSummonNormalize(slot.accountAltName) == UnBotSpecSummonNormalize(name)) then
			name = slot.accountAltName;
			local sent = state.requestedName == name and state.stage == "wait_registry_member";
			for _, entry in ipairs(state.squad.prefetch or {}) do
				if (entry.name == name and entry.sentAt) then sent = true; break end
			end
			if (not sent or slot.skipped) then return false; end
			UnBotAccountAlts.SetFaction(name, UnBotAccountAlts.OppositeFaction(UnBotAccountAlts.CurrentFaction()), "server-opposite-faction");
			UnBotAccountAlts.MarkError(name, "opposite faction: "..result);
			return state.SkipEnemyAlt(name);
		end
	end
	return false;
end

function UnBotSpecSummon.PrefetchStart()
	local state = UnBotSpecSummon;
	local queue, excluded = {}, {};
	local candidateLists, candidateIndexes = {}, {};
	for name in pairs(state.checked) do excluded[name] = true; end
	for _, slot in ipairs(state.squad.slots) do
		for i = 1, slot.skipped and 0 or math.max(0, slot.need - slot.have) do
			local name;
			if (slot.accountAltName) then
				if (UnBotAccountAlts and UnBotAccountAlts.IsEnabled and UnBotAccountAlts.CanAddToSquad
					and UnBotAccountAlts.IsEnabled(slot.accountAltName)
					and UnBotAccountAlts.CanAddToSquad(slot.accountAltName)
					and not excluded[slot.accountAltName]) then name = slot.accountAltName; end
			else
				local candidateKey = tostring(slot.className).."\031"
					..table.concat(slot.specAliases or {}, "\031").."\031"
					..tostring(slot.specAliases and slot.specAliases.feralRole or "").."\031"
					..tostring(slot.specAliases and slot.specAliases.anySpec or "");
				if (not candidateLists[candidateKey]) then
					-- Sorting the whole registry once per requested raid member caused
					-- multi-second UI stalls for 30-39 equal slots. The sort order is
					-- stable during this snapshot, so consume one cached list instead.
					candidateLists[candidateKey] = UnBotRegistryCandidates(
						slot.className,
						slot.specAliases,
						nil,
						true
					);
					if (UnBotPVEFastSummon) then candidateLists[candidateKey]=UnBotPVEFastSummon.Candidates(candidateLists[candidateKey],slot,true); end
					candidateIndexes[candidateKey] = 1;
				end
				local candidates = candidateLists[candidateKey];
				local candidateIndex = candidateIndexes[candidateKey] or 1;
				while (candidateIndex <= #candidates) do
					local candidate = candidates[candidateIndex];
					candidateIndex = candidateIndex + 1;
					if (
						not excluded[candidate]
						and not UnBotBuffCycleArrivalBlock(candidate)
					) then
						name = candidate;
						break
					end
				end
				candidateIndexes[candidateKey] = candidateIndex;
			end
			if (name) then
				excluded[name] = true;
				table.insert(queue, {name=name, slot=slot});
			end
		end
	end
	state.squad.batch = nil;
	state.squad.prefetch = queue;
	state.squad.prefetchPending = {};
	state.squad.prefetchIndex = 1;
	state.squad.prefetchRead = 1;
	state.stage = "squad_prefetch";
	state.stageTime = GetTime();
	UnBotSpecSummonMessage("Состав: проход 1/2 — призыв по именам, кандидатов "..tostring(#queue)..".");
end

function UnBotSpecSummon.PrefetchQueued(name)
	local state = UnBotSpecSummon;
	return state.active and state.mode == "squad" and state.squad
		and state.squad.prefetchPending and state.squad.prefetchPending[name];
end

function UnBotSpecSummon.PrefetchSend()
	if (UnBotBatchSummon and UnBotBatchSummon.CanPrefetch()) then return UnBotBatchSummon.PrefetchSend(); end
	local state, now = UnBotSpecSummon, GetTime();
	if (UnitAffectingCombat and UnitAffectingCombat("player")) then
		state.stageTime = now + 1;
		return true;
	end
	local squad = state.squad;
	if (UnBotGunshipMasterLoot and UnBotGunshipMasterLoot.summonGuard) then
		local previous = squad.prefetch[squad.prefetchIndex - 1];
		if (previous and not UnBotSpecSummonIsInGroup(previous.name)) then
			-- Let the normal join/invite path handle a missing candidate.
			if (now >= previous.sentAt + 5) then return false; end
			state.stageTime = now + 0.2;
			return true;
		end
		if (not UnBotGunshipMasterLoot.CheckSummon()) then
			state.stageTime = now + 0.2;
			return true;
		end
	end
	local entry = squad.prefetch[squad.prefetchIndex];
	if (not entry) then return false; end
	if (entry.slot.skipped) then
		squad.prefetchIndex = squad.prefetchIndex + 1;
		state.stageTime = now + 0.1;
		return true;
	end
	local occupied = math.max(1 + (GetNumPartyMembers() or 0), GetNumRaidMembers() or 0);
	for name in pairs(squad.prefetchPending) do
		if (not UnBotSpecSummonIsInGroup(name)) then occupied = occupied + 1; end
	end
	-- Physical raid roster includes the player; instance/buff limits are separate.
	if (occupied >= 40) then return false; end
	if (GetNumPartyMembers() == 4 and GetNumRaidMembers() == 0) then ConvertToRaid(); end
	entry.sentAt = now;
	UnBotSpecSummon.CancelStaleCleanup(entry.name);
	squad.prefetchPending[entry.name] = true;
	state.checked[entry.name] = true;
	state.registryRequests[entry.name] = now + 120;
	SendChatMessage(".playerbot bot add "..entry.name, "SAY");
	if (UnBotGunshipMasterLoot and UnBotGunshipMasterLoot.RecordAttempt) then
		UnBotGunshipMasterLoot.RecordAttempt(entry.name);
	end
	squad.prefetchIndex = squad.prefetchIndex + 1;
	state.stageTime = now + 0.7;
	return true;
end

local function UnBotSpecSummonTryNext()
	if (UnBotSpecSummon.mode == "squad" and UnBotGunshipMasterLoot
		and UnBotGunshipMasterLoot.CheckSummon
		and not UnBotGunshipMasterLoot.CheckSummon()) then
		if (UnBotSpecSummon.active) then
			UnBotSpecSummon.stage = "wait_next";
			UnBotSpecSummon.stageTime = GetTime() + 0.2;
		end
		return;
	end
	if (
		UnBotSpecSummon.completionSource == "lockbox-service"
		and (UnBotSpecSummon.tries or 0) >= 3
	) then
		UnBotSpecSummonStop(
			"Вскрытие сундука остановлено после 3 попыток призыва разбойника. "
			.."Дальнейшие команды не отправляются."
		);
		return;
	end
	local slot = nil;
	local prefetched;
	if (UnBotSpecSummon.mode == "squad") then
		if (UnBotSpecSummonSquadComplete()) then
			if (UnBotPVEFastSummon and UnBotPVEFastSummon.BeforeFinish()) then return; end
			UnBotSpecSummonFinishSquad("Squad registry summon complete: ");
			return;
		end
		if (not UnBotSpecSummon.squad.prefetch) then
			UnBotSpecSummon.PrefetchStart();
			return;
		end
		local squad = UnBotSpecSummon.squad;
		prefetched = squad.prefetch[squad.prefetchRead];
		while (prefetched and (prefetched.slot.skipped or prefetched.batchFailure)) do
			squad.prefetchPending[prefetched.name] = nil;
			squad.prefetchRead = squad.prefetchRead + 1;
			prefetched = squad.prefetch[squad.prefetchRead];
		end
		if (prefetched and prefetched.sentAt) then
			squad.prefetchRead = squad.prefetchRead + 1;
			squad.prefetchPending[prefetched.name] = nil;
			slot = prefetched.slot;
		else prefetched = nil; end
		for _, wantedSlot in ipairs(UnBotSpecSummon.squad.slots or {}) do
			if (not slot and not wantedSlot.skipped and not wantedSlot.pveExhausted and wantedSlot.have < wantedSlot.need) then
				slot = wantedSlot;
				break
			end
		end
		if (not slot) then
			if (UnBotPVEFastSummon) then UnBotPVEFastSummon.FinishPartial(); return; end
			UnBotSpecSummonFinishSquad("Squad registry summon complete: ");
			return;
		end
		UnBotSpecSummon.currentClassName = slot.className;
	else
		UnBotSpecSummon.currentClassName = UnBotSpecSummon.className;
	end

	if (GetNumPartyMembers() == 4 and GetNumRaidMembers() == 0) then
		ConvertToRaid();
	end

	if (not prefetched and UnBotBatchSummon and UnBotBatchSummon.Refill()) then return; end
	local className = slot and slot.className or UnBotSpecSummon.className;
	local specAliases = slot and slot.specAliases or UnBotSpecSummon.specAliases;
	-- Exact names first. Compatible PvE shortages may use a named preset donor;
	-- other classes keep the factual class audit before init.
	local candidates = {};
	if (not prefetched and not (slot and slot.accountAltName)) then
		candidates = UnBotRegistryCandidates(
			className,
			specAliases,
			UnBotSpecSummon.checked,
			true
		);
	end
	if (slot and not prefetched and UnBotPVEFastSummon) then candidates=UnBotPVEFastSummon.Candidates(candidates,slot); end
	local requestedName = prefetched and prefetched.name or (slot and slot.accountAltName or candidates[1]);
	local fallbackSpec;
	local fallbackCount = 0;
	if (slot and slot.accountAltName) then
		if (
			UnBotSpecSummonNormalize(slot.accountAltName)
			== UnBotSpecSummonNormalize(UnitName("player") or "")
		) then
			UnBotSpecSummonStop(
				"Именной слот "..tostring(slot.accountAltName)
				.." совпадает с текущим персонажем и пропущен без команды add. "
				.."Такие слоты теперь удаляются из обычного состава автоматически."
			);
			return;
		end
		if (
			not UnBotAccountAlts
			or not UnBotAccountAlts.IsEnabled
			or not UnBotAccountAlts.IsEnabled(slot.accountAltName)
		) then
			UnBotSpecSummonStop(
				"Именной альт "..tostring(slot.accountAltName)
				.." отсутствует или отключён. Проверьте вкладку Альты."
			);
			return;
		end
		if (not UnBotAccountAlts.CanAddToSquad(slot.accountAltName)) then
			UnBotSpecSummon.SkipEnemyAlt(slot.accountAltName);
			UnBotSpecSummon.stage, UnBotSpecSummon.stageTime = "wait_next", GetTime() + 0.1;
			return;
		end
		if (UnBotSpecSummon.checked[requestedName] and not prefetched) then
			UnBotSpecSummonStop(
				"Именной альт "..tostring(requestedName)
				.." не смог занять слот; случайная замена запрещена."
			);
			return;
		end
	elseif (not requestedName and slot and not (UnBotPVEFastSummon and UnBotPVEFastSummon.Handles(slot))) then
		requestedName, fallbackSpec, fallbackCount = UnBotSpecSummonFindFallbackCandidate(slot);
	end
	if (not requestedName and fallbackCount == -1) then
		UnBotSpecSummon.stage = "wait_next";
		UnBotSpecSummon.stageTime = GetTime() + 1;
		return;
	end
	if (not requestedName) then
		if (slot and UnBotPVEFastSummon) then
			if (UnBotPVEFastSummon.PendingDonor(slot)) then
				UnBotSpecSummon.stage,UnBotSpecSummon.stageTime="wait_next",GetTime()+.2;
			else UnBotPVEFastSummon.MarkExhausted(slot,"доступные кандидаты и подтверждённые доноры закончились"); end
			return;
		end
		local specLabel = slot and slot.specKey or UnBotSpecSummon.specName;
		UnBotSpecSummonStop(
			"Строгий подбор остановлен: проверка add -> who не нашла доступного кандидата или "
			.."подтверждённого избыточного спека того же класса для "
			..tostring(className).." "..tostring(specLabel)
			..". Выполните полный скан ботов или пополните реестр."
		);
		return;
	end

	if (slot and UnBotPVEFastSummon and not UnBotPVEFastSummon.Capacity(requestedName,slot)) then return; end
	UnBotSpecSummon.tries = UnBotSpecSummon.tries + 1;
	if (slot) then
		slot.registryAttempts = (slot.registryAttempts or 0) + 1;
	end
	UnBotSpecSummon.knownMembers = UnBotSpecSummonGetMembers();
	UnBotSpecSummon.candidate = requestedName;
	UnBotSpecSummon.pvePresetDoneName = nil;
	UnBotSpecSummon.requestedName = requestedName;
	UnBotSpecSummon.requestedSlot = slot;
	UnBotSpecSummon.requestedFallback = fallbackSpec and true or false;
	if (fallbackSpec) then
		UnBotSpecSummon.initUsed[requestedName] = true;
	end
	UnBotSpecSummon.initAttempts = 0;
	UnBotSpecSummon.lastInitAt = 0;
	UnBotSpecSummon.whoAttempts = 0;
	UnBotSpecSummon.checked[requestedName] = true;
	UnBotSpecSummon.CancelStaleCleanup(requestedName);
	UnBotSpecSummon.registryRequests[requestedName] = GetTime() + 120;
	UnBotSpecSummon.stage = "wait_registry_member";
	UnBotSpecSummon.stageTime = GetTime()
		+ (UnBotSpecSummon.mode == "squad" and 5 or 10);
	UnBotSpecSummon.inviteAt = GetTime() + 1.25;
	UnBotSpecSummon.inviteAttempts = 0;
	if (prefetched) then
		UnBotSpecSummon.stage = "wait_prefetch_ready";
		UnBotSpecSummon.stageTime = math.max(GetTime(), prefetched.sentAt + (prefetched.batch and 0 or 15));
	else
		if not (slot and UnBotPVEFastSummon and UnBotPVEFastSummon.InviteReleased(requestedName)) then
			SendChatMessage(".playerbot bot add "..requestedName, "SAY");
		end
		if (UnBotSpecSummon.mode == "squad" and UnBotGunshipMasterLoot
			and UnBotGunshipMasterLoot.RecordAttempt) then
			UnBotGunshipMasterLoot.RecordAttempt(requestedName);
		end
	end
	if (UnBotSpecSummon.mode == "squad") then
		if (slot.accountAltName) then
			UnBotSpecSummonMessage(
				"Именной призыв альта: "..requestedName
				.." | "..UnBotSpecSummonSquadProgressText()
			);
		elseif (fallbackSpec) then
			UnBotSpecSummonMessage(
				"Строгий подбор: все доступные "..slot.className
				.." проверены через add → who, фактический дефицит "..slot.specKey
				.." подтверждён. Точечно вызываю донора "..requestedName.." ("..fallbackSpec
				..", подтверждено "..tostring(fallbackCount)..") и повторно проверяю who; "
				.."только после ответа разрешено до "..tostring(UnBotSpecSummon.maxInitAttempts or 6)
				.." init."
			);
		else
			UnBotSpecSummonMessage(
				"Squad registry summon: "..requestedName.." -> "..slot.className.." "..slot.specKey
				.." | candidate "..tostring(slot.registryAttempts)
				.." | "..UnBotSpecSummonSquadProgressText()
			);
		end
	else
		UnBotSpecSummonMessage(
			"Spec registry summon: "..requestedName.." -> "..UnBotSpecSummon.className.." "
			..UnBotSpecSummon.specName.." | candidate "..tostring(UnBotSpecSummon.tries).."."
		);
	end
end

UnBotSpecSummon.ContinuePreset = UnBotSpecSummonTryNext;
UnBotSpecSummon.PVETransport = {StoreWho=UnBotSpecSummonStoreRegistryWho,
	Accept=UnBotSpecSummonAcceptRegistryCandidate,Stop=UnBotSpecSummonStop};

function UnBotSpecSummonRejectRegistryJoin(reason)
	local name = UnBotSpecSummon.requestedName;
	if (
		not UnBotSpecSummon.active
		or not UnBotSpecSummon.registryMode
		or UnBotSpecSummon.stage ~= "wait_registry_member"
		or not name
		or UnBotSpecSummonIsInGroup(name)
	) then
		return false;
	end
	if (UnBotSpecSummon.requestedSlot and UnBotSpecSummon.requestedSlot.accountAltName) then
			UnBotSpecSummonStop(
				"Именной альт "..tostring(name).." не вошёл в группу: "
				..tostring(reason or "сервер не подтвердил вход")
				..". Случайная замена не выполнялась."
			);
			return true;
	end
	if (not UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots and UnBotBotRegistry.bots[name])) then
		UnBotRegistrySetHourlyQuarantine(
			name,
			reason or "сбор состава: бот не вошёл в группу",
			"Ротация"
		);
	end
	UnBotSpecSummonMessage(
		"Кандидат "..tostring(name)
		.." не вошёл в группу; пробую другого доступного бота того же класса/спека."
	);
	UnBotSpecSummon.candidate = nil;
	UnBotSpecSummon.requestedName = nil;
	UnBotSpecSummon.requestedSlot = nil;
	UnBotSpecSummon.inviteAt = 0;
	UnBotSpecSummon.inviteAttempts = 0;
	UnBotSpecSummonTryNext();
	return true;
end

local function UnBotSpecSummonRejectCandidate()
	UnBotSpecSummon.whoPull = nil;
	if (UnBotPVEFastSummon and UnBotPVEFastSummon.Reject()) then return; end
	local name = UnBotSpecSummon.candidate;
	if (name) then
		UnBotSpecSummon.checked[name] = true;
		UnBotSpecSummon.rejectedOnline[name] = true;
		UnBotSpecSummonUninvite(name);
		UnBotSpecSummon.kickQueue[name] = {
			untilTime = GetTime() + 15,
			nextTime = GetTime() + 1,
			attempts = 0,
			maxAttempts = 3,
		};
	end
	UnBotSpecSummon.stage = "wait_rejected_leave";
	UnBotSpecSummon.stageTime = GetTime() + 0.5;
	UnBotSpecSummon.stageUntil = GetTime() + 15;
end

UnBotSpecSummon.RejectForTalent = function(reason)
	if (reason) then UnBotSpecSummonMessage(reason); end
	if (UnitAffectingCombat("player") or InCombatLockdown()) then UnBotSpecSummonStop("Подбор остановлен боем; текущий бот сохранён"); return; end
	UnBotSpecSummonRejectCandidate();
end;

-- One bounded pull rescues a silent ordinary PvE candidate before cleanup.
-- State belongs to this composition, never to SavedVariables or an alt profile.
function UnBotSpecSummon.WhoPullGuard()
 local s = UnBotSpecSummon;
 local op = s.whoPull;
 if not op then return false; end
 if not s.active or s.mode ~= "squad" or s.squad ~= op.owner
  or s.stage ~= "wait_registry_who" or s.requestedName ~= op.name or s.candidate ~= op.name then
  s.whoPull = nil; return false;
 end
 local unit = UnBotSquadRosterFindUnit(op.name);
 if UnitAffectingCombat("player") or InCombatLockdown() or (unit and UnitAffectingCombat(unit))
  or op.context ~= UnBotRegistryCurrentContext()
  or op.zone ~= (GetRealZoneText and GetRealZoneText())
  or (unit and (UnitName(unit) ~= op.name or UnitGUID(unit) ~= op.guid))
  or UnBotIsAccountAltProfile(op.name, UnBotBotRegistry.bots[op.name])
  or UnBotSquadRosterIsOfflineReserve(op.name) or (s.squad.pvpNames or {})[op.name] then
  UnBotSpecSummonStop("Восстановление who остановлено: "..op.name.." — бой, смена участника, локации или назначения; состав сохранён.");
  return true;
 end
 if not unit or not UnitIsConnected(unit) or UnitIsDeadOrGhost(unit) then
  s.whoPull = nil;
  UnBotSpecSummonMessage("Восстановление who: "..op.name.." больше не доступен живым онлайн в группе; перехожу к штатной очистке.");
  UnBotSpecSummonRejectCandidate();
  return true;
 end
 return false;
end
function UnBotSpecSummon.BeginWhoPull()
 local s = UnBotSpecSummon;
 local name, slot = s.requestedName, s.requestedSlot;
 if not s.active or not s.registryMode or s.mode ~= "squad" or not s.squad
  or s.stage ~= "wait_registry_who"
  or not name or s.candidate ~= name or not slot or slot.accountAltName
  or (s.squad.whoPullTried or {})[name] or (s.squad.pvpNames or {})[name]
  or UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots[name])
  or UnBotSquadRosterIsOfflineReserve(name) then return false; end
 local unit = UnBotSquadRosterFindUnit(name);
 if not unit or UnitName(unit) ~= name or not UnitIsConnected(unit)
  or UnitIsDeadOrGhost(unit) or not UnitGUID(unit) then return false; end
 s.squad.whoPullTried = s.squad.whoPullTried or {};
 s.squad.whoPullTried[name] = true;
 local now = GetTime();
 s.whoPull = {name = name, owner = s.squad, guid = UnitGUID(unit),
  context = UnBotRegistryCurrentContext(), zone = GetRealZoneText and GetRealZoneText(),
  retryAt = now + 5, deadline = now + 10, phase = "pull"};
 if s.confirmedRoster then s.confirmedRoster.Forget(name); end
 if s.WhoPullGuard() then return true; end
 s.stageTime = now + 5;
 UnBotSpecSummonMessage("Восстановление who: "..name.." молчит; отправляю summon (1/1), через 5 секунд повторю who. Исключение пока отложено.");
 SendChatMessage("summon", "WHISPER", nil, name);
 return true;
end
function UnBotSpecSummon.WhoPullTick()
 local s = UnBotSpecSummon;
 if s.WhoPullGuard() then return true; end
 local op = s.whoPull;
 if not op then return false; end
 local now = GetTime();
 if now >= op.deadline then
  s.whoPull = nil;
  UnBotSpecSummonMessage("Восстановление who: "..op.name.." не ответил после summon и повторной проверки; перехожу к штатной очистке.");
  UnBotSpecSummonRejectCandidate();
 elseif op.phase == "pull" and now >= op.retryAt then
  op.phase = "who";
  s.whoAttempts = 3;
  s.stageTime = op.deadline;
  UnBotSpecSummonMessage("Восстановление who: "..op.name.." — повторяю who после summon (1/1).");
  SendChatMessage("who", "WHISPER", nil, op.name);
 end
 return true;
end
function UnBotSpecSummon.WhoPullReply(event, message, sender)
 local s = UnBotSpecSummon;
 if s.WhoPullGuard() then return true; end
 if s.whoPull and GetTime() >= s.whoPull.deadline then return s.WhoPullTick(); end
 if not s.active or s.mode ~= "squad" or not s.registryMode
  or s.stage ~= "wait_registry_who" or not s.requestedName then return false; end
 local name, text = s.requestedName, UnBotSpecSummonNormalize(message);
 local notFound = event == "CHAT_MSG_SYSTEM" and UnBotSquadSpecCheck
  and UnBotSquadSpecCheck.PlayerNotFound and UnBotSquadSpecCheck.PlayerNotFound(message, name);
 local addressed = event == "CHAT_MSG_WHISPER" and sender == name
  or event == "CHAT_MSG_SYSTEM" and UnBotBuffCycleMessageHasName and UnBotBuffCycleMessageHasName(message, name);
 if notFound or (addressed and (text:find("unknown command",1,true) or text:find("unknown spell",1,true)
  or text:find("cannot cast",1,true) or text:find("no items",1,true) or text:find("too low",1,true)
  or text:find("i'll do it later",1,true) or text:find("i will do it later",1,true)
  or text:find("not in your instance",1,true) or text:find("not in your dungeon",1,true)
  or text:find("не находится в вашем подземелье",1,true))) then
  s.whoPull = nil;
  if s.confirmedRoster then s.confirmedRoster.Forget(name); end
  UnBotSpecSummonMessage("Восстановление who: "..name.." — явный отказ сервера; summon и повторные who отменены. Перехожу к штатной очистке.");
  UnBotSpecSummonRejectCandidate();
  return true;
 end
 return false;
end

function UnBotSpecSummon.InitReply(event, message, sender)
	local s = UnBotSpecSummon;
	if (not s.active or not s.requestedFallback or not s.requestedName or (s.initAttempts or 0) == 0
		or (s.stage ~= "wait_registry_init_settle" and s.stage ~= "wait_registry_who" and s.stage ~= "wait_registry_init_rate")) then return false; end
	local text = UnBotSpecSummonNormalize(message);
	if (not ((event == "CHAT_MSG_WHISPER" and sender == s.requestedName)
		or (event == "CHAT_MSG_SYSTEM" and (text:find(UnBotSpecSummonNormalize(s.requestedName),1,true)
			or GetTime() - (s.lastInitAt or 0) <= 3)))) then return false; end
	if (text:find("unknown command",1,true) or text:find("unknown spell",1,true)
		or text:find("cannot cast",1,true) or text:find("no items",1,true)
		or text:find("too low",1,true) or text:find("not found",1,true)
		or text:find("i'll do it later",1,true) or text:find("i will do it later",1,true)) then
		UnBotSpecSummonStop("Ребалансировка PvE остановлена: сервер отказал для "..s.requestedName..": "..tostring(message));
		return true;
	end
	return false;
end

function UnBotSpecSummonNeedsFeralStrategyQuery(whoInfo)
	if (
		type(whoInfo) ~= "table"
		or UnBotSpecSummonNormalize(whoInfo.className) ~= "druid"
		or whoInfo.feralRole
	) then
		return false;
	end
	local level = tonumber(whoInfo.level);
	if (
		UnBotSpecSummonNormalize(whoInfo.specName) ~= "feral combat"
		and (not level or level >= 80)
	) then
		return false;
	end
	if (UnBotSpecSummon.mode == "squad") then
		for _, slot in ipairs((UnBotSpecSummon.squad and UnBotSpecSummon.squad.slots) or {}) do
			if (
				not slot.accountAltName
				and slot.have < slot.need
				and UnBotSpecSummonNormalize(slot.className) == "druid"
				and slot.specAliases
				and slot.specAliases.feralRole
			) then
				return true;
			end
		end
		return false;
	end
	return UnBotSpecSummon.specAliases
		and UnBotSpecSummon.specAliases.feralRole
		and true or false;
end

function UnBotSpecSummonResolveRegistryCandidate(name, whoInfo)
	if (UnBotSpecSummonAcceptRegistryCandidate(name)) then
		return true;
	elseif (UnBotPVEFastSummon and UnBotPVEFastSummon.Begin(name, whoInfo)) then
		return false;
	elseif (UnBotSpecSummon.requestedFallback) then
		UnBotSpecSummonMessage(
			"Строгий подбор: "..name.." сейчас "..tostring(whoInfo.className).." "
			..tostring(whoInfo.specName)
			..", нужен "..tostring(UnBotSpecSummon.requestedSlot and UnBotSpecSummon.requestedSlot.className or "?")
			.." "..tostring(UnBotSpecSummon.requestedSlot and UnBotSpecSummon.requestedSlot.specKey or "?").."."
		);
		UnBotSpecSummonSendRegistryInit();
	else
		UnBotSpecSummonMessage(
			"Строгий подбор: фактический "..tostring(whoInfo.className).." "
			..tostring(whoInfo.specName).." у "..name
			.." не закрывает ни один оставшийся слот; "
			.."наблюдение сохранено, продолжаю безопасную проверку класса без init."
		);
		UnBotSpecSummonRejectCandidate();
	end
	return false;
end

function UnBotSpecSummonBeginFeralStrategyQuery(name, whoInfo, rawWho)
	local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (
		profile
		and UnBotSpecSummonNormalize(profile.feralRoleSource) == "combat-strategy"
	) then
		profile.feralRole = nil;
		profile.feralRoleSource = nil;
		profile.feralRoleCheckedAt = nil;
		if (UnBotSpecSummon.verifiedCandidates and UnBotSpecSummon.verifiedCandidates[name]) then
			UnBotSpecSummon.verifiedCandidates[name].feralRole = nil;
		end
		UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	end
	UnBotSpecSummon.pendingFeralWhoInfo = whoInfo;
	UnBotSpecSummon.pendingFeralWhoRaw = rawWho;
	UnBotSpecSummon.feralStrategyAttempts = 1;
	UnBotSpecSummon.stage = "wait_registry_feral_strategy";
	UnBotSpecSummon.stageTime = GetTime() + 3;
	SendChatMessage("co ?", "WHISPER", nil, name);
	UnBotSpecSummonMessage(
		"Feral-проверка: у "..name.." на уровне "..tostring(whoInfo.level or "?")
		.." расклад талантов не определяет Bear/Cat; запрашиваю фактические стратегии co ?."
	);
end

function UnBotSpecSummonFinishFeralStrategyQuery(role, reason)
	local name = UnBotSpecSummon.requestedName;
	local whoInfo = UnBotSpecSummon.pendingFeralWhoInfo;
	UnBotSpecSummon.pendingFeralWhoInfo = nil;
	UnBotSpecSummon.pendingFeralWhoRaw = nil;
	UnBotSpecSummon.feralStrategyAttempts = 0;
	if (not name or not whoInfo) then
		UnBotSpecSummonStop("Feral-проверка остановлена: потерян активный кандидат.");
		return;
	end
	if (role and UnBotStoreFeralStrategyRole(name, whoInfo, role)) then
		UnBotSpecSummonMessage(
			"Feral-проверка: "..name.." — co ? подтвердил "
			..(role == "bear" and "Bear (Tank)" or "Cat (DPS)").."."
		);
	else
		UnBotSpecSummonMessage(
			"Feral-проверка: "..name.." — "
			..tostring(reason or "ответ co ? не содержит однозначной стратегии bear или cat")
			.."; точный Feral-слот не засчитан."
		);
	end
	UnBotSpecSummonResolveRegistryCandidate(name, whoInfo);
end

function UnBotSpecSummonStart(msg, completionAction, completionSource)
	if (UnBotFullTalentCatalog and UnBotFullTalentCatalog.IsBusy()) then UnBotSpecSummonMessage("Сначала завершите сбор полного каталога талантов."); return false; end
	if UnBotStrategySurvey and UnBotStrategySurvey.active then UnBotSpecSummonMessage("Сначала остановите сбор стратегий."); return false; end
	if (UnBotSpecSummon.active) then
		UnBotSpecSummonMessage("Сначала дождитесь окончания текущего призыва бота.");
		return false;
	end
	if (UnBotDKSpecBalance and UnBotDKSpecBalance.active) then
		UnBotSpecSummonMessage("Сначала остановите выравнивание спеков по количеству.");
		return;
	end
	if (UnBotBotScanner and UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Stop the bot scan before starting Spec Summon.");
		return;
	end
	msg = UnBotSpecSummonNormalize(msg);
	if (msg == "" or msg == "help") then
		UnBotSpecSummonMessage("Usage: /ubspec <class> <spec>. Example: /ubspec paladin ret");
		return;
	end

	local parts = {};
	for part in string.gmatch(msg, "%S+") do
		table.insert(parts, part);
	end

	local className = UnBotSpecSummonClassAliases[parts[1]];
	if (not className) then
		UnBotSpecSummonMessage("Unknown class: "..tostring(parts[1]));
		return;
	end

	-- Older versions accepted a numeric max-tries suffix. Keep parsing it so
	-- existing macros continue to work, but registry mode now tries every
	-- matching saved profile instead of stopping at an arbitrary limit.
	if (#parts > 2 and tonumber(parts[#parts])) then
		table.remove(parts, #parts);
	end
	table.remove(parts, 1);

	local specKey = table.concat(parts, " ");
	local specAliases = UnBotSpecSummonSpecAliases[specKey] or UnBotSpecSummonSpecAliases[parts[1]];
	if (not specAliases) then
		UnBotSpecSummonMessage("Unknown spec: "..specKey);
		return;
	end
	-- A repeated single-spec request is allowed to add another bot of the same
	-- role, but it must never select a name that is already in our roster.
	-- Otherwise an already-present bot can answer `who` after the server reports
	-- `player already logged in` and be counted as a fresh summon a second time.
	local currentMembers = UnBotSpecSummonGetMembers();
	currentMembers[UnitName("player")] = nil;
	local registryCount = #UnBotRegistryCandidates(
		className,
		specAliases,
		currentMembers,
		true
	);
	if (registryCount == 0) then
		UnBotSpecSummonMessage(
			"Spec registry summon: no available "..className
			.." profiles to verify. Check /ubflags list or run the full bot scan."
		);
		return;
	end

	UnBotSpecSummon.active = true;
	UnBotSpecSummon.registryMode = true;
	UnBotSpecSummon.mode = "single";
	UnBotSpecSummon.className = className;
	UnBotSpecSummon.currentClassName = className;
	UnBotSpecSummon.specName = specKey;
	UnBotSpecSummon.specAliases = specAliases;
	UnBotSpecSummon.squad = nil;
	UnBotSpecSummon.tries = 0;
	UnBotSpecSummon.checked = currentMembers;
	UnBotSpecSummon.rejectedOnline = {};
	UnBotSpecSummon.kickQueue = {};
	UnBotSpecSummon.cleanupQueue = {};
	UnBotSpecSummon.requestedName = nil;
	UnBotSpecSummon.requestedSlot = nil;
	UnBotSpecSummon.requestedFallback = false;
	UnBotSpecSummon.initAttempts = 0;
	UnBotSpecSummon.lastInitAt = 0;
	UnBotSpecSummon.whoAttempts = 0;
	UnBotSpecSummon.feralStrategyAttempts = 0;
	UnBotSpecSummon.pendingFeralWhoInfo = nil;
	UnBotSpecSummon.pendingFeralWhoRaw = nil;
	UnBotSpecSummon.extraNames = {};
	UnBotSpecSummon.verifiedCandidates = {};
	UnBotSpecSummon.initUsed = {};
	UnBotSpecSummon.completionAction = type(completionAction) == "function"
		and completionAction or nil;
	UnBotSpecSummon.completionSource = completionSource or nil;
	UnBotSpecSummon.pvePreset, UnBotSpecSummon.pvePresetDoneName, UnBotSpecSummon.pveVerifiedWho = nil, nil, nil;
	UnBotSpecSummon.pveExistingPrepared, UnBotSpecSummon.pveExistingQueue = nil, nil;
	UnBotSpecSummonMessage(
		"Spec registry summon started: "..tostring(registryCount)
		.." saved "..className.." candidates; last-known spec only sets order, add -> who decides."
	);
	UnBotSpecSummonTryNext();
	return true;
end

local function UnBotSpecSummonParseSquadPart(part)
	if (UnBotAccountAlts and UnBotAccountAlts.ParseSquadPart) then
		local altSlot, altError = UnBotAccountAlts.ParseSquadPart(part);
		if (altSlot or altError) then
			return altSlot, altError;
		end
	end
	part = UnBotSpecSummonNormalize(part);
	if (part == "") then
		return nil, "empty squad part";
	end

	local words = {};
	for word in string.gmatch(part, "%S+") do
		table.insert(words, word);
	end

	local count = 1;
	if (#words >= 1 and tonumber(words[1])) then
		count = tonumber(words[1]);
		table.remove(words, 1);
	elseif (#words >= 1 and tonumber(words[#words])) then
		count = tonumber(words[#words]);
		table.remove(words, #words);
	end

	if (#words < 2) then
		return nil, "bad squad part: "..part;
	end

	local className = UnBotSpecSummonClassAliases[words[1]];
	if (not className) then
		return nil, "unknown class: "..tostring(words[1]);
	end
	table.remove(words, 1);

	local specKey = table.concat(words, " ");
	local specAliases = specKey == "any"
		and {anySpec = true}
		or (UnBotSpecSummonSpecAliases[specKey] or UnBotSpecSummonSpecAliases[words[1]]);
	if (not specAliases) then
		return nil, "unknown spec: "..specKey;
	end

	return {
		className = className,
		specKey = specKey,
		specAliases = specAliases,
		need = count,
		have = 0,
		names = {},
	};
end

function UnBotSpecSummonSquadStart(msg, skipCurrentRosterCheck, referenceZone, whoRecoveryAttempted, checkedCandidates)
	if (UnBotFullTalentCatalog and UnBotFullTalentCatalog.IsBusy()) then UnBotSpecSummonMessage("Сначала завершите сбор полного каталога талантов."); return false; end
	if UnBotStrategySurvey and UnBotStrategySurvey.active then UnBotSpecSummonMessage("Сначала остановите сбор стратегий."); return false; end
	if (UnBotDKSpecBalance and UnBotDKSpecBalance.active) then
		UnBotSpecSummonMessage("Сначала остановите выравнивание спеков по количеству.");
		return;
	end
	if (UnBotBotScanner and UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Stop the bot scan before starting Squad Summon.");
		return;
	end
	if (
		not skipCurrentRosterCheck
		and UnBotSquadSpecCheck
		and (
			UnBotSquadSpecCheck.active
			or (UnBotSquadSpecCheck.autoStartAt or 0) > 0
		)
	) then
		UnBotSpecSummonMessage("Сначала дождитесь окончания текущей проверки спеков.");
		return;
	end
	msg = tostring(msg or "");
	local trimmed = UnBotSpecSummonNormalize(msg);
	if (trimmed == "" or trimmed == "help") then
		UnBotSpecSummonMessage("Usage: /ubsquad paladin ret 2, paladin holy 1, paladin prot 1");
		return;
	end

	local slots = {};
	for part in string.gmatch(trimmed, "([^,;]+)") do
		local slot, err = UnBotSpecSummonParseSquadPart(part);
		if (not slot) then
			UnBotSpecSummonMessage("Squad summon: "..tostring(err));
			return;
		end
		table.insert(slots, slot);
	end

	if (#slots == 0) then
		UnBotSpecSummonMessage("Squad summon: no slots parsed.");
		return;
	end
	-- Exact specialization and named-alt slots must claim compatible bots before
	-- broad class-only slots, regardless of the order in which the user added rows.
	local orderedSlots = {};
	for _, slot in ipairs(slots) do
		if (not (slot.specAliases and slot.specAliases.anySpec)) then
			table.insert(orderedSlots, slot);
		end
	end
	for _, slot in ipairs(slots) do
		if (slot.specAliases and slot.specAliases.anySpec) then
			table.insert(orderedSlots, slot);
		end
	end
	slots = orderedSlots;
	if (not referenceZone and GetRealZoneText) then
		referenceZone = GetRealZoneText();
	end
	if (UnBotSummonLog and not UnBotSummonLog.current) then
		UnBotSummonLog.Safe("Begin", msg, "squad", skipCurrentRosterCheck);
	end

	UnBotRegistryAttachStorage();
	local currentMembers = UnBotSpecSummonGetMembers();
	currentMembers[UnitName("player")] = nil;
	local pvpAssignments, pvpNames = {}, {};
	if (UnBotPVPSummon and UnBotPVPSummon.PlanExisting) then
		pvpAssignments, pvpNames = UnBotPVPSummon.PlanExisting(slots);
	end
	local currentNames = {};
	local reserveNames = {};
	for name in pairs(currentMembers) do
		if (UnBotBotRegistry.bots and UnBotBotRegistry.bots[name]) then
			if (UnBotSquadRosterIsOfflineReserve(name)) then
				table.insert(reserveNames, name);
			elseif (not pvpNames[name]) then
				table.insert(currentNames, name);
			end
		end
	end
	table.sort(currentNames);
	table.sort(reserveNames);

	local pendingWho, reused = {}, 0;
	for _,name in ipairs(currentNames) do
		if not UnBotIsAccountAltProfile(name,UnBotBotRegistry.bots[name]) then
			if UnBotSpecSummonHasFreshConfirmation(name) then reused=reused+1;
			else table.insert(pendingWho,name);end
		end
	end
	if not skipCurrentRosterCheck then
		UnBotSquadSpecCheck.results = {};
		if reused>0 then UnBotSpecSummonMessage("Повторный добор: свежие подтверждения "..reused.."; проверить текущих ботов "..#pendingWho..".");end
	end
	if (not skipCurrentRosterCheck and #pendingWho > 0 and UnBotSquadSpecCheckStart) then
		UnBotSpecSummonMessage(
			"Сначала проверяю боевой состав: "..tostring(#pendingWho)
			.." ботов. После опроса будут вызваны только недостающие."
		);
		if (#reserveNames > 0) then
			UnBotSpecSummonMessage(
				"Офлайн-резерв в составе рейда (ростере): "
				..table.concat(reserveNames, ", ")
				..". Не проверяется и не активируется."
			);
		end
		UnBotSquadSpecCheckStart({
			queue = pendingWho,
			mode = "pre_summon",
			continuation = function(checkedReferenceZone)
				UnBotSpecSummonSquadStart(trimmed, true, checkedReferenceZone, whoRecoveryAttempted, checkedCandidates);
			end,
		});
		return;
	end

	-- A partial post-summon who pass contains only the names it queried.
	-- Missing entries are not proof that accepted roster members are surplus.
	if (skipCurrentRosterCheck and UnBotSpecSummonPlayerSupportsSpecs()) then
		local unverified = {};
		for _, name in ipairs(currentNames) do
			local profile = UnBotBotRegistry.bots[name];
			if (not UnBotIsAccountAltProfile(name, profile)
				and not (UnBotSquadSpecCheck.results and UnBotSquadSpecCheck.results[name])
				and not UnBotSpecSummonHasFreshConfirmation(name)) then
				table.insert(unverified, name);
			end
		end
		if (#unverified > 0) then
			if (not whoRecoveryAttempted and UnBotSquadSpecCheckStart) then
				UnBotSpecSummonMessage("Подбор: неполная проверка who для "
					..table.concat(unverified, ", ")
					..". Один раз повторно опрашиваю неподтверждённых ботов без исключений.");
				-- Session proofs retain the other members while results is reset.
				-- Without that cache, keep the original complete-pass fallback.
				UnBotSquadSpecCheckStart({
					queue = UnBotSpecSummon.confirmedRoster and unverified or currentNames,
					mode = "pre_summon",
					referenceZone = referenceZone,
					continuation = function(checkedReferenceZone)
						UnBotSpecSummonSquadStart(trimmed, true, checkedReferenceZone or referenceZone, true, checkedCandidates);
					end,
				});
				return;
			end
			if (UnBotPVEFastSummon) then
				UnBotSpecSummonMessage("PvE: нет свежего who для "..table.concat(unverified,", ")
					.."; эти участники не засчитаны, продолжаю остальные позиции.");
			else
				UnBotSquadBuilder.postSummonSequence=nil;UnBotSquadBuilder.pendingBossPreset=nil;
				UnBotSpecSummonMessage("Подбор остановлен: нет свежей проверки who для "
					..table.concat(unverified, ", ")..". Состав сохранён; повторите проверку состава.");
				return;
			end
		end
	end

	local credited = 0;
	local quarantinedCurrent = 0;
	local extraCurrentNames = {};
	for _, name in ipairs(currentNames) do
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		local flag = UnBotRegistryGetActiveFlag(profile);
		local matched = false;
		local currentWhoVerified = not skipCurrentRosterCheck
			or not UnBotSpecSummonPlayerSupportsSpecs()
			or UnBotIsAccountAltProfile(name, profile)
			or UnBotSpecSummonHasFreshConfirmation(name)
			or (UnBotSquadSpecCheck.results and UnBotSquadSpecCheck.results[name]);
		if (flag and flag.kind == "quarantine") then
			quarantinedCurrent = quarantinedCurrent + 1;
		elseif (currentWhoVerified) then
			for _, slot in ipairs(slots) do
				local namedMatch = slot.accountAltName and name == slot.accountAltName;
				local roleMatch = not slot.accountAltName
					and not UnBotIsAccountAltProfile(name, profile)
					and (
						(
							profile
							and not (slot.specAliases and slot.specAliases.feralRole)
							and tonumber(profile.level)
							and tonumber(profile.level) > 0
							and tonumber(profile.level) < 10
							and UnBotSpecSummonNormalize(profile.className)
								== UnBotSpecSummonNormalize(slot.className)
						)
						or UnBotRegistryProfileMatches(profile, slot.className, slot.specAliases)
					);
				if (
					slot.have < slot.need
					and (namedMatch or roleMatch)
				) then
					slot.have = slot.have + 1;
					slot.names[name] = true;
					if (namedMatch) then
						UnBotAccountAltApplyQuestSupportProfile(name, "squad-current");
					elseif (UnBotSpecSummonPlayerSupportsSpecs()) then
						UnBotSpecSummonEnsureCombatRole(
							name,
							slot.className,
							slot.specKey,
							"squad-current"
						);
					end
					credited = credited + 1;
					matched = true;
					break
				end
			end
		end
		if (not matched) then
			table.insert(extraCurrentNames, name);
			if (not currentWhoVerified) then
				UnBotSpecSummonMessage(
					"Строгий подбор: "..name
					.." не ответил на обязательный who и не будет засчитан по старому реестру."
				);
			end
		end
	end

	local requirements = {};
	for _, slot in ipairs(slots) do
		if (not slot.accountAltName) then
		local classOnly = not UnBotSpecSummonPlayerSupportsSpecs();
		local key = classOnly and slot.className or (
			slot.className.."\031"..table.concat(slot.specAliases or {}, "\031")
				.."\031"..tostring(slot.specAliases and slot.specAliases.feralRole or "")
				.."\031"..tostring(slot.specAliases and slot.specAliases.anySpec or "")
		);
		local requirement = requirements[key];
		if (not requirement) then
			requirement = {
				className = slot.className,
				specKey = classOnly and "class-only" or slot.specKey,
				specAliases = slot.specAliases,
				need = 0,
			};
			if (classOnly) then
				requirement.specAliases = nil;
			end
			requirements[key] = requirement;
		end
		requirement.need = requirement.need + math.max(0, slot.need - slot.have);
		end
		slot.registryAttempts = 0;
	end
	for _, requirement in pairs(requirements) do
		local available = #UnBotRegistryCandidates(
			requirement.className,
			requirement.specAliases,
			currentMembers
		);
		if (available < requirement.need) then
			UnBotSpecSummonMessage(
				"Строгий подбор: последних известных профилей мало для "..requirement.className.." "
				..requirement.specKey..": нужно "..tostring(requirement.need)
				..", подсказок точного спека "..tostring(available)
				..". Сначала через add -> who будут проверены остальные боты класса; "
				.."init разрешится только после подтверждённого фактического дефицита."
			);
		end
	end

	UnBotSpecSummon.active = true;
	UnBotSpecSummon.registryMode = true;
	UnBotSpecSummon.mode = "squad";
	UnBotSpecSummon.className = nil;
	UnBotSpecSummon.currentClassName = nil;
	UnBotSpecSummon.specName = nil;
	UnBotSpecSummon.specAliases = nil;
	UnBotSpecSummon.squad = {
		requirementsText = trimmed,
		slots = slots,
		initialNames = currentMembers,
		summonedNames = {},
		referenceZone = referenceZone,
		reserveNames = reserveNames,
		pvpNames = pvpNames,
		pvpAssignments = pvpAssignments,
		pvpSignature = UnBotPVPSummon and UnBotPVPSummon.Signature(),
	};
	-- New explicit composition supersedes the previous buff snapshot.
	UnBotSpecSummon.ResetBuffSnapshot();
	for _, slot in ipairs(slots) do
		for name in pairs(slot.names) do UnBotSpecSummon.CancelStaleCleanup(name); end
	end
	UnBotSpecSummon.tries = 0;
	UnBotSpecSummon.checked = {};
	for name in pairs(checkedCandidates or {}) do
		UnBotSpecSummon.checked[name] = true;
	end
	for name in pairs(currentMembers) do
		UnBotSpecSummon.checked[name] = true;
	end
	UnBotSpecSummon.rejectedOnline = {};
	UnBotSpecSummon.kickQueue = {};
	UnBotSpecSummon.cleanupQueue = {};
	UnBotSpecSummon.requestedName = nil;
	UnBotSpecSummon.requestedSlot = nil;
	UnBotSpecSummon.requestedFallback = false;
	UnBotSpecSummon.initAttempts = 0;
	UnBotSpecSummon.lastInitAt = 0;
	UnBotSpecSummon.whoAttempts = 0;
	UnBotSpecSummon.feralStrategyAttempts = 0;
	UnBotSpecSummon.pendingFeralWhoInfo = nil;
	UnBotSpecSummon.pendingFeralWhoRaw = nil;
	UnBotSpecSummon.extraNames = {};
	UnBotSpecSummon.verifiedCandidates = {};
	UnBotSpecSummon.initUsed = {};
	UnBotSpecSummon.fastTried = {};
	UnBotSpecSummon.completionAction = nil;
	UnBotSpecSummon.completionSource = nil;
	UnBotSpecSummon.pvePreset, UnBotSpecSummon.pvePresetDoneName, UnBotSpecSummon.pveVerifiedWho = nil, nil, nil;
	UnBotSpecSummon.pveExistingPrepared, UnBotSpecSummon.pveExistingQueue = nil, nil;
	UnBotSpecSummonMessage(
		"Squad registry summon started: "..UnBotSpecSummonSquadProgressText()
		.." | уже в составе зачтено "..tostring(credited)
		..(quarantinedCurrent > 0 and (", в карантине не зачтено "..tostring(quarantinedCurrent)) or "")
		..(#reserveNames > 0 and (", офлайн-резерв сохранён "..tostring(#reserveNames)) or "")
		.."."
	);
	if (next(pvpNames)) then
		local preserved = {};
		for name in pairs(pvpNames) do
			table.insert(preserved,name);
			UnBotSpecSummon.CancelStaleCleanup(name);
		end
		table.sort(preserved);
		UnBotSpecSummonMessage("PVE: текущие участники сохранены для отдельной проверки PVP: "..table.concat(preserved,", ")..".");
	end
	if (#extraCurrentNames > 0) then
		for _, name in ipairs(extraCurrentNames) do
			UnBotSpecSummon.extraNames[name] = true;
			if (UnBotPVEFastSummon) then UnBotPVEFastSummon.QueueCleanup(name);
			else UnBotSpecSummonUninvite(name); end
		end
		UnBotSpecSummon.stage = UnBotPVEFastSummon and "wait_next" or "wait_squad_extras";
		UnBotSpecSummon.stageTime = GetTime() + 0.5;
		UnBotSpecSummon.stageUntil = GetTime() + 15;
		UnBotSpecSummonMessage(
			"Строгий подбор: удаляю лишних или не совпавших со слотами ботов перед добором: "
			..table.concat(extraCurrentNames, ", ").."."
		);
	else
		UnBotSpecSummonTryNext();
	end
end

local function UnBotSpecSummonWhoMatches(message)
	local whoInfo = UnBotSpecSummonParseWho(message);
	if (not whoInfo) then
		return nil;
	end

	local className = UnBotSpecSummonWhoClassNames[UnBotSpecSummon.className];
	if (not className or not whoInfo.className or whoInfo.className ~= UnBotSpecSummon.className) then
		return nil;
	end

	return UnBotSpecSummonAliasMatches(
		UnBotSpecSummon.specAliases,
		whoInfo.text,
		whoInfo.feralRole
	);
end

local frame = CreateFrame("Frame", "UnBotSpecSummonFrame");
frame:RegisterEvent("CHAT_MSG_WHISPER");
frame:RegisterEvent("CHAT_MSG_SYSTEM");
frame:RegisterEvent("PARTY_MEMBERS_CHANGED");
frame:RegisterEvent("RAID_ROSTER_UPDATE");
frame:SetScript("OnEvent", function(self, event, arg1, arg2)
	if (UnBotBatchSummon and UnBotBatchSummon.PrefetchReply(event,arg1,arg2)) then return; end
	if (UnBotPVEFastSummon and UnBotPVEFastSummon.Reply(event,arg1,arg2)) then return; end
	if event == "PARTY_MEMBERS_CHANGED" or event == "RAID_ROSTER_UPDATE" then
		for name, observation in pairs(UnBotSpecSummon.verifiedCandidates or {}) do
			local unit = UnBotSquadRosterFindUnit(name);
			if not unit or not UnitIsConnected(unit) then observation.disconnected = true; end
		end
	end
	if (not UnBotSpecSummon.active) then
		return;
	end
	if (UnBotSpecSummon.WhoPullReply and UnBotSpecSummon.WhoPullReply(event,arg1,arg2)) then return; end
	if (UnBotSpecSummon.InitReply and UnBotSpecSummon.InitReply(event,arg1,arg2)) then return; end
	if (UnBotSpecSummon.EnemyAltReply(event,arg1)) then return; end
	if (
		event == "CHAT_MSG_SYSTEM"
		and UnBotSpecSummon.registryMode
		and UnBotSpecSummon.stage == "wait_registry_who"
	) then
		local text = UnBotSpecSummonNormalize(arg1);
		if (
			string.find(text, "обмениваться личными сообщениями можно только с союзниками", 1, true)
			or string.find(text, "only whisper players of your faction", 1, true)
			or string.find(text, "only whisper to players in your faction", 1, true)
		) then
			UnBotSpecSummonMessage(
				"Строгая проверка остановлена: межфракционный who для "
				..tostring(UnBotSpecSummon.requestedName).." недоступен."
			);
			UnBotSpecSummonRejectCandidate();
			return;
		end
	end
	if (
		UnBotSpecSummon.registryMode
		and UnBotSpecSummon.stage == "wait_registry_member"
		and UnBotSpecSummon.requestedName
		and not UnBotSpecSummonIsInGroup(UnBotSpecSummon.requestedName)
	) then
		local requestedName = UnBotSpecSummon.requestedName;
		local requestedText = UnBotSpecSummonNormalize(requestedName);
		local text = UnBotSpecSummonNormalize(arg1);
		if (
			event == "CHAT_MSG_WHISPER"
			and arg2 == requestedName
			and (
				string.find(text, "i'll do it later", 1, true)
				or string.find(text, "i will do it later", 1, true)
			)
		) then
			UnBotSpecSummonRejectRegistryJoin(
				"сбор состава: бот явно отказался от приглашения"
			);
			return;
		elseif (event == "CHAT_MSG_SYSTEM") then
			local alreadyActive =
				string.find(text, "player already logged in", 1, true)
				or string.find(text, "already logged in", 1, true)
				or string.find(text, "already in group", 1, true)
				or string.find(text, "уже состоит в группе", 1, true)
				or string.find(text, "уже в игре", 1, true);
			if (alreadyActive and (not UnBotSpecSummon.squad or not UnBotSpecSummon.squad.prefetch
				or UnBotBuffCycleMessageHasName(arg1, requestedName))) then
				-- There is only one active named add request in this state, so the
				-- server reply is definitive even if a localized prefix omitted the
				-- name. Stop all pending invites immediately and rotate the bot out.
				UnBotSpecSummon.inviteAttempts = 0;
				UnBotSpecSummon.inviteAt = math.huge;
				UnBotSpecSummonRejectRegistryJoin(
					"сбор состава: сервер подтвердил, что бот уже залогинен у другого игрока"
				);
				return;
			elseif (
				string.find(text, requestedText, 1, true)
				and (
				string.find(text, "отклоняет приглашение", 1, true)
				or string.find(text, "declines your group invitation", 1, true)
				or string.find(text, "declined your group invitation", 1, true)
				)
			) then
				UnBotSpecSummonRejectRegistryJoin(
					"сбор состава: бот явно отказался от приглашения"
				);
				return;
			elseif (
				string.find(text, requestedText, 1, true)
				and (
				string.find(text, "не находится в вашем подземелье", 1, true)
				or string.find(text, "not in your instance", 1, true)
				or string.find(text, "not in your dungeon", 1, true)
				)
			) then
				UnBotSpecSummonRejectRegistryJoin(
					"сбор состава: бот находится в другой копии подземелья"
				);
				return;
			end
		end
	end
	if (
		UnBotSpecSummon.registryMode
		and (event == "PARTY_MEMBERS_CHANGED" or event == "RAID_ROSTER_UPDATE")
		and UnBotSpecSummon.stage == "wait_registry_member"
		and UnBotSpecSummon.requestedName
		and UnBotSpecSummonIsInGroup(UnBotSpecSummon.requestedName)
	) then
		UnBotSpecSummonBeginRegistryWho(UnBotSpecSummon.requestedName);
		return;
	end

	if (
		event == "CHAT_MSG_WHISPER"
		and UnBotSpecSummon.registryMode
		and UnBotSpecSummon.stage == "wait_registry_feral_strategy"
		and arg2 == UnBotSpecSummon.requestedName
	) then
		local feralRole, strategyReply = UnBotFeralRoleFromStrategyText(arg1);
		if (not strategyReply) then
			return;
		end
		UnBotSpecSummonFinishFeralStrategyQuery(
			feralRole,
			feralRole and nil or "ответ co ? не содержит однозначной стратегии bear или cat"
		);
		return;
	end

	if (
		event == "CHAT_MSG_WHISPER"
		and UnBotSpecSummon.registryMode
		and UnBotSpecSummon.stage == "wait_registry_who"
		and arg2 == UnBotSpecSummon.requestedName
	) then
		local whoInfo = UnBotSpecSummonParseWho(arg1);
		if (not whoInfo or not whoInfo.className or not whoInfo.specName) then
			return;
		end
		if UnBotSpecSummon.whoPull then
			UnBotSpecSummon.whoPull = nil;
			UnBotSpecSummonMessage("Восстановление who: "..arg2.." ответил; продолжаю проверку класса/спека без исключения.");
		end
		local oldClass, oldSpec = UnBotSpecSummonStoreRegistryWho(arg2, whoInfo, arg1);
		if (oldClass ~= whoInfo.className or oldSpec ~= whoInfo.specName) then
			UnBotSpecSummonMessage(
				"Реестр обновлён сразу: "..arg2.." | "
				..tostring(oldClass or "?").." "..tostring(oldSpec or "?").." -> "
				..tostring(whoInfo.className).." "..tostring(whoInfo.specName).."."
			);
		end
		if (UnBotSpecSummonNeedsFeralStrategyQuery(whoInfo)) then
			UnBotSpecSummonBeginFeralStrategyQuery(arg2, whoInfo, arg1);
			return;
		end
		UnBotSpecSummonResolveRegistryCandidate(arg2, whoInfo);
		return;
	end

	if (event == "CHAT_MSG_WHISPER" and UnBotSpecSummon.stage == "wait_who" and arg2 == UnBotSpecSummon.candidate) then
		if (UnBotSpecSummon.mode == "squad") then
			local whoInfo = UnBotSpecSummonParseWho(arg1);
			if (not whoInfo) then
				return;
			elseif (UnBotSpecSummonSquadAccept(arg2, whoInfo)) then
				if (UnBotSpecSummonSquadComplete()) then
					UnBotSpecSummonFinishSquad("Squad summon complete: ");
				else
					UnBotSpecSummon.candidate = nil;
					UnBotSpecSummon.stage = "wait_next";
					UnBotSpecSummon.stageTime = GetTime() + 1;
				end
			else
				UnBotSpecSummonMessage("Squad summon rejected: "..arg2.." does not fit remaining slots.");
				UnBotSpecSummonRejectCandidate();
			end
			return;
		end

		local whoMatches = UnBotSpecSummonWhoMatches(arg1);
		if (whoMatches == nil) then
			return;
		elseif (whoMatches) then
			local completionAction = UnBotSpecSummon.completionAction;
			local completionSource = UnBotSpecSummon.completionSource;
			local summonSource = completionAction and ((completionSource or "service").."-who") or "spec-who";
			local summonCount = UnBotRegistryRecordGameplaySummon(arg2, summonSource);
			UnBotGroupStrategyOnGameplaySummon(arg2, summonSource);
			UnBotSpecSummonStop(
				"Spec summon matched: "..arg2.." ("..UnBotSpecSummon.specName
					..", summons "..tostring(summonCount or "?")..")."
			);
			if (completionAction) then
				completionAction(arg2);
			end
		else
			UnBotSpecSummonMessage("Spec summon rejected: "..arg2.." is not "..UnBotSpecSummon.specName..".");
			UnBotSpecSummonRejectCandidate();
		end
	elseif (event == "PARTY_MEMBERS_CHANGED" or event == "RAID_ROSTER_UPDATE") then
		if (UnBotSpecSummon.stage == "wait_member") then
			local name = UnBotSpecSummonFindNewMember();
			if (name) then
				UnBotSpecSummon.candidate = name;
				UnBotSpecSummon.stage = "wait_who";
				UnBotSpecSummon.stageTime = GetTime() + 12;
				SendChatMessage("who", "WHISPER", nil, name);
			end
		end
	end
end);

UnBotSpecSummon.DeliverPresetWho = function(name,message)
	frame:GetScript("OnEvent")(frame,"CHAT_MSG_WHISPER",message,name);
end;

frame:SetScript("OnUpdate", function(self)
	if (UnBotGunshipMasterLoot and UnBotGunshipMasterLoot.paused) then return; end
	local now = GetTime();
	if (UnBotPVEFastSummon) then UnBotPVEFastSummon.TickCleanup(); end
	for name, expiresAt in pairs(UnBotSpecSummon.registryRequests or {}) do
		if (UnBotPVEFastSummon and UnBotPVEFastSummon.Excluded(name)) then
			UnBotSpecSummon.registryRequests[name]=nil;
		elseif (UnBotSpecSummon.CleanupProtected(name)) then
			UnBotSpecSummon.CancelStaleCleanup(name);
		elseif (
			name ~= UnBotSpecSummon.requestedName
			and not UnBotSpecSummon.PrefetchQueued(name)
			and UnBotSpecSummonIsInGroup(name)
			and not UnBotSpecSummon.cleanupQueue[name]
		) then
			if UnBotPVEFastSummon and UnBotPVEFastSummon.Enabled() then
				UnBotPVEFastSummon.QueueCleanup(name);
			else
				UnBotSpecSummonUninvite(name);
				UnBotSpecSummon.cleanupQueue[name] = {
					removeSent = false,
					nextTime = now + 0.5,
					untilTime = now + 30,
				};
			end
			UnBotSpecSummon.registryRequests[name] = nil;
			UnBotSpecSummonMessage("Registry summon: caught delayed unused bot "..name.."; removing it safely.");
		elseif (now >= (expiresAt or 0) and not UnBotSpecSummonIsInGroup(name)
			and not UnBotSpecSummon.PrefetchQueued(name)) then
			UnBotSpecSummon.registryRequests[name] = nil;
		end
	end
	for name, kick in pairs(UnBotSpecSummon.kickQueue) do
		if (UnBotSpecSummon.CleanupProtected(name)) then
			UnBotSpecSummon.CancelStaleCleanup(name);
		elseif (not UnBotSpecSummonIsInGroup(name)) then
			UnBotSpecSummon.kickQueue[name] = nil;
		elseif (now >= kick.untilTime) then
			UnBotSpecSummonStop("Spec summon stopped: cannot remove "..name.." from raid.");
			return;
		elseif (now >= kick.nextTime) then
			kick.attempts = (kick.attempts or 0) + 1;
			if (kick.attempts <= (kick.maxAttempts or 3)) then
				UnBotSpecSummonUninvite(name);
				kick.nextTime = now + 2;
			else
				kick.nextTime = math.huge;
			end
		end
	end

	for name, cleanup in pairs(UnBotSpecSummon.cleanupQueue) do
		if (cleanup.pveOwned) then
			-- The finite PvE cleanup above owns this name.
		elseif (UnBotSpecSummon.CleanupProtected(name)) then
			UnBotSpecSummon.CancelStaleCleanup(name);
		elseif (UnBotSpecSummonIsInGroup(name)) then
			if (now >= cleanup.nextTime) then
				cleanup.attempts = (cleanup.attempts or 0) + 1;
				if (cleanup.attempts <= (cleanup.maxAttempts or 3)) then
					UnBotSpecSummonUninvite(name);
					cleanup.nextTime = now + 2;
				else
					UnBotSpecSummon.cleanupQueue[name] = nil;
					UnBotSpecSummonMessage(
						"Очистка остановлена после 3 попыток: "..name
						.." всё ещё в группе; дальнейшие команды не отправляются."
					);
				end
			end
		elseif (not cleanup.removeSent) then
			SendChatMessage(".playerbot bot remove "..name, "SAY");
			cleanup.removeSent = true;
			cleanup.untilTime = now + 3;
		elseif (now >= cleanup.untilTime) then
			UnBotSpecSummon.cleanupQueue[name] = nil;
		end
	end

	-- `bot add` can bring an offline bot online without placing it in our group.
	-- A normal named summon still gets limited explicit invites. Strict squad
	-- assembly and the lockbox service give only one invite per candidate; the
	-- lockbox service also caps the whole search at three candidate attempts.
	if (
		UnBotSpecSummon.active
		and UnBotSpecSummon.registryMode
		and UnBotSpecSummon.stage == "wait_registry_member"
		and UnBotSpecSummon.requestedName
		and not UnBotSpecSummonIsInGroup(UnBotSpecSummon.requestedName)
		and now >= (UnBotSpecSummon.inviteAt or 0)
		and (UnBotSpecSummon.inviteAttempts or 0)
			< ((
				UnBotSpecSummon.mode == "squad"
				or UnBotSpecSummon.completionSource == "lockbox-service"
			) and 1 or 4)
	) then
		if (UnitAffectingCombat and UnitAffectingCombat("player")) then
			UnBotSpecSummon.inviteAt = now + 1;
			UnBotSpecSummon.stageTime = math.max(UnBotSpecSummon.stageTime or 0, now + 2);
		else
			UnBotSpecSummon.inviteAttempts = (UnBotSpecSummon.inviteAttempts or 0) + 1;
			if (UnBotSpecSummon.inviteAttempts == 3) then
				SendChatMessage(".playerbot bot add "..UnBotSpecSummon.requestedName, "SAY");
			end
			InviteUnit(UnBotSpecSummon.requestedName);
			UnBotSpecSummon.inviteAt = now + 2;
			if (UnBotSpecSummon.inviteAttempts == 1) then
				UnBotSpecSummonMessage(
					"Registry summon: "..UnBotSpecSummon.requestedName
					.." переведён онлайн; отправляю одно отдельное приглашение в группу."
				);
			end
		end
	end

	if (UnBotSpecSummon.WhoPullTick and UnBotSpecSummon.WhoPullTick()) then return; end
	if (UnBotPVEFastSummon and UnBotPVEFastSummon.TickActive()) then return; end
	if (not UnBotSpecSummon.active or not UnBotSpecSummon.stageTime or GetTime() < UnBotSpecSummon.stageTime) then
		return;
	end
	if (UnBotSpecSummon.registryMode) then
		if (UnBotSpecSummon.stage == "squad_prefetch") then
			if (not UnBotSpecSummon.PrefetchSend()) then
				UnBotSpecSummonMessage("Состав: проход 2/2 — разбор свежих спеков и проверка прибытия.");
				UnBotSpecSummonTryNext();
			end
		elseif (UnBotSpecSummon.stage == "wait_prefetch_ready") then
			UnBotSpecSummon.stage = "wait_registry_member";
			UnBotSpecSummon.stageTime = now + 5;
			UnBotSpecSummon.inviteAt = now;
			if (UnBotSpecSummonIsInGroup(UnBotSpecSummon.requestedName)) then
				UnBotSpecSummonBeginRegistryWho(UnBotSpecSummon.requestedName);
			end
		elseif (UnBotSpecSummon.stage == "wait_squad_extras") then
			local remaining = {};
			for name in pairs(UnBotSpecSummon.extraNames or {}) do
				if (UnBotSpecSummonIsInGroup(name)) then
					table.insert(remaining, name);
				else
					UnBotSpecSummon.cleanupQueue[name] = {
						removeSent = false,
						nextTime = now,
						untilTime = now + 30,
					};
					UnBotSpecSummon.extraNames[name] = nil;
				end
			end
			table.sort(remaining);
			if (#remaining == 0) then
				UnBotSpecSummonMessage("Строгий подбор: лишние позиции освобождены; продолжаю точный добор.");
				UnBotSpecSummonTryNext();
			elseif (now >= (UnBotSpecSummon.stageUntil or 0)) then
				for _, name in ipairs(remaining) do
					UnBotSpecSummonUninvite(name);
				end
				UnBotSpecSummonStop(
					"Строгий подбор остановлен: не удалось за 15 секунд освободить лишние позиции: "
					..table.concat(remaining, ", ").."."
				);
			else
				for _, name in ipairs(remaining) do
					UnBotSpecSummonUninvite(name);
				end
				UnBotSpecSummon.stageTime = now + 1;
			end
		elseif (UnBotSpecSummon.stage == "wait_registry_member") then
			local requestedName = UnBotSpecSummon.requestedName;
			if (requestedName and UnBotSpecSummonIsInGroup(requestedName)) then
				UnBotSpecSummonBeginRegistryWho(requestedName);
			else
				UnBotSpecSummonRejectRegistryJoin(
					"сбор состава: не вошёл в группу после add и одного приглашения"
				);
			end
		elseif (UnBotSpecSummon.stage == "wait_registry_who") then
			if ((UnBotSpecSummon.whoAttempts or 0) < 2 and UnBotSpecSummon.requestedName) then
				UnBotSpecSummon.whoAttempts = (UnBotSpecSummon.whoAttempts or 0) + 1;
				SendChatMessage("who", "WHISPER", nil, UnBotSpecSummon.requestedName);
				UnBotSpecSummon.stageTime = now + 3;
				UnBotSpecSummonMessage(
					"Строгая проверка: повторяю who для "..UnBotSpecSummon.requestedName
					.." ("..tostring(UnBotSpecSummon.whoAttempts).."/2)."
				);
			elseif UnBotSpecSummon.BeginWhoPull and UnBotSpecSummon.BeginWhoPull() then
				-- The bounded rescue owns this candidate until a fresh who or failure.
			else
				UnBotSpecSummonMessage(
					"Строгая проверка: нет ответа who от "..tostring(UnBotSpecSummon.requestedName)
					.."; слот не засчитан и init запрещён без свежего подтверждения."
				);
				UnBotSpecSummonRejectCandidate();
			end
		elseif (UnBotSpecSummon.stage == "wait_registry_feral_strategy") then
			if (
				(UnBotSpecSummon.feralStrategyAttempts or 0) < 2
				and UnBotSpecSummon.requestedName
			) then
				UnBotSpecSummon.feralStrategyAttempts =
					(UnBotSpecSummon.feralStrategyAttempts or 0) + 1;
				SendChatMessage("co ?", "WHISPER", nil, UnBotSpecSummon.requestedName);
				UnBotSpecSummon.stageTime = now + 3;
				UnBotSpecSummonMessage(
					"Feral-проверка: повторяю co ? для "..UnBotSpecSummon.requestedName
					.." ("..tostring(UnBotSpecSummon.feralStrategyAttempts).."/2)."
				);
			else
				UnBotSpecSummonFinishFeralStrategyQuery(
					nil,
					"нет распознаваемого ответа co ? после двух попыток"
				);
			end
		elseif (UnBotSpecSummon.stage == "wait_registry_init_rate") then
			UnBotSpecSummonSendRegistryInit();
		elseif (UnBotSpecSummon.stage == "wait_registry_init_settle") then
			if (UnBotSpecSummon.requestedName and UnBotSpecSummonIsInGroup(UnBotSpecSummon.requestedName)) then
				UnBotSpecSummon.stage = "wait_registry_who";
				UnBotSpecSummon.whoAttempts = 1;
				SendChatMessage("who", "WHISPER", nil, UnBotSpecSummon.requestedName);
				UnBotSpecSummon.stageTime = now + 3;
			else
				UnBotSpecSummonMessage(
					"Строгий подбор: "..tostring(UnBotSpecSummon.requestedName)
					.." покинул группу во время init; пробую другого кандидата."
				);
				UnBotSpecSummonRejectCandidate();
			end
		elseif (UnBotSpecSummon.stage == "wait_rejected_leave") then
			if (
				not UnBotSpecSummonIsInGroup(UnBotSpecSummon.candidate)
				or now >= (UnBotSpecSummon.stageUntil or 0)
			) then
				if (UnBotSpecSummonIsInGroup(UnBotSpecSummon.candidate)) then
					UnBotSpecSummonStop(
						"Строгий подбор остановлен: не удалось удалить "
						..tostring(UnBotSpecSummon.candidate).." из рейда."
					);
					return;
				end
				UnBotSpecSummonMessage(
					"Строгий подбор: неподходящий кандидат удалён; продолжаю тот же незаполненный слот."
				);
				local rejectedName = UnBotSpecSummon.candidate;
				if (rejectedName) then
					UnBotSpecSummon.cleanupQueue[rejectedName] = {
						removeSent = false,
						nextTime = now,
						untilTime = now + 30,
					};
					UnBotSpecSummon.rejectedOnline[rejectedName] = nil;
					UnBotSpecSummon.registryRequests[rejectedName] = nil;
				end
				UnBotSpecSummon.candidate = nil;
				UnBotSpecSummon.requestedName = nil;
				UnBotSpecSummon.requestedSlot = nil;
				UnBotSpecSummon.requestedFallback = false;
				UnBotSpecSummonTryNext();
			else
				UnBotSpecSummon.stageTime = now + 0.5;
			end
		elseif (UnBotSpecSummon.stage == "wait_next") then
			UnBotSpecSummonTryNext();
		end
		return;
	end

	if (UnBotSpecSummon.stage == "wait_member") then
		local name = UnBotSpecSummonFindNewMember();
		if (name) then
			UnBotSpecSummon.candidate = name;
			UnBotSpecSummon.stage = "wait_who";
			UnBotSpecSummon.stageTime = GetTime() + 12;
			SendChatMessage("who", "WHISPER", nil, name);
		else
			if (UnBotSpecSummon.mode == "squad") then
				UnBotSpecSummonMessage("Squad summon: no new bot detected.");
			else
				UnBotSpecSummonMessage("Spec summon: no new bot detected.");
			end
			UnBotSpecSummonTryNext();
		end
	elseif (UnBotSpecSummon.stage == "wait_who") then
		if (UnBotSpecSummon.mode == "squad") then
			UnBotSpecSummonMessage("Squad summon: no who response from "..tostring(UnBotSpecSummon.candidate)..".");
		else
			UnBotSpecSummonMessage("Spec summon: no who response from "..tostring(UnBotSpecSummon.candidate)..".");
		end
		UnBotSpecSummonRejectCandidate();
	elseif (UnBotSpecSummon.stage == "wait_rejected_leave") then
		if (not UnBotSpecSummonIsInGroup(UnBotSpecSummon.candidate) or GetTime() >= UnBotSpecSummon.stageUntil) then
			if (UnBotSpecSummonIsInGroup(UnBotSpecSummon.candidate)) then
				UnBotSpecSummonStop("Spec summon stopped: cannot remove "..tostring(UnBotSpecSummon.candidate).." from raid.");
				return;
			end
			UnBotSpecSummon.candidate = nil;
			UnBotSpecSummonTryNext();
		else
			UnBotSpecSummon.stageTime = GetTime() + 0.5;
		end
	elseif (UnBotSpecSummon.stage == "wait_next") then
		UnBotSpecSummonTryNext();
	end
end);

local UnBotBotFix = {
	active = false,
	name = nil,
	stage = nil,
	nextTime = 0,
	untilTime = 0,
	removeCount = 0,
	summonCount = 0,
};

local function UnBotBotFixNameFromTarget()
	local name = UnitName("target");
	if (name and name ~= UnitName("player") and UnitIsPlayer("target")) then
		return name;
	end
	return nil;
end

local function UnBotBotFixStart(msg)
	if (UnBotDKSpecBalance and UnBotDKSpecBalance.active) then
		UnBotSpecSummonMessage("Сначала остановите выравнивание спеков по количеству.");
		return;
	end
	local name = tostring(msg or "");
	name = string.gsub(name, "^%s+", "");
	name = string.gsub(name, "%s+$", "");
	if (name == "" or UnBotSpecSummonNormalize(name) == "target") then
		name = UnBotBotFixNameFromTarget();
	end
	if (not name or name == "") then
		UnBotSpecSummonMessage("Usage: /ubfixbot <botName>, or target a bot and click the repair button.");
		return;
	end

	UnBotBotFix.active = true;
	UnBotBotFix.name = name;
	UnBotBotFix.stage = "kick";
	UnBotBotFix.nextTime = 0;
	UnBotBotFix.untilTime = GetTime() + 8;
	UnBotBotFix.removeCount = 0;
	UnBotBotFix.summonCount = 0;
	UnBotSpecSummonMessage("Bot repair started: "..name);
end

local function UnBotBotFixFinish(text)
	if (text) then
		UnBotSpecSummonMessage(text);
	end
	UnBotBotFix.active = false;
	UnBotBotFix.name = nil;
	UnBotBotFix.stage = nil;
end

local botFixFrame = CreateFrame("Frame", "UnBotBotFixFrame");
botFixFrame:SetScript("OnUpdate", function(self)
	if (not UnBotBotFix.active or GetTime() < (UnBotBotFix.nextTime or 0)) then
		return;
	end

	local now = GetTime();
	local name = UnBotBotFix.name;
	if (not name) then
		UnBotBotFixFinish(nil);
		return;
	end

	if (UnBotBotFix.stage == "kick") then
		if (UnBotSpecSummonIsInGroup(name) and now < UnBotBotFix.untilTime) then
			SendChatMessage("leave", "WHISPER", nil, name);
			SendChatMessage("stay", "WHISPER", nil, name);
			UninviteUnit(name);
			if (GetNumRaidMembers() and GetNumRaidMembers() > 0) then
				for i = 1, GetNumRaidMembers(), 1 do
					local rosterName = GetRaidRosterInfo(i);
					local unit = "raid"..i;
					if (rosterName == name or UnitName(unit) == name) then
						UninviteUnit(unit);
					end
				end
			end
			UnBotBotFix.nextTime = now + 1;
			return;
		end
		UnBotBotFix.stage = "remove";
		UnBotBotFix.nextTime = 0;
	elseif (UnBotBotFix.stage == "remove") then
		SendChatMessage(".playerbot bot remove "..name, "SAY");
		UnBotBotFix.removeCount = UnBotBotFix.removeCount + 1;
		if (UnBotBotFix.removeCount < 3) then
			UnBotBotFix.nextTime = now + 1.5;
		else
			UnBotBotFix.stage = "add";
			UnBotBotFix.nextTime = now + 2;
		end
	elseif (UnBotBotFix.stage == "add") then
		SendChatMessage(".playerbot bot add "..name, "SAY");
		UnBotBotFix.stage = "summon";
		UnBotBotFix.untilTime = now + 12;
		UnBotBotFix.summonCount = 0;
		UnBotBotFix.nextTime = now + 2;
	elseif (UnBotBotFix.stage == "summon") then
		SendChatMessage("summon", "WHISPER", nil, name);
		SendChatMessage("follow", "WHISPER", nil, name);
		SendChatMessage("reset botAI", "WHISPER", nil, name);
		UnBotBotFix.summonCount = UnBotBotFix.summonCount + 1;
		if (UnBotBotFix.summonCount >= 3 and UnBotSpecSummonIsInGroup(name)) then
			UnBotBotFixFinish("Bot repair sequence finished: "..name..".");
		elseif (now >= UnBotBotFix.untilTime) then
			UnBotBotFixFinish("Bot repair sent add/summon, but "..name.." is not visible in group yet.");
		else
			UnBotBotFix.nextTime = now + 2;
		end
	end
end);

local UnBotBuffCycle = {
	active = false,
	version = "6.3 reagent report",
	mode = "solo",
	superFast = false,
	phaseIndex = 0,
	runtimePhases = nil,
	stage = nil,
	nextTime = 0,
	stageUntil = 0,
	baselineMembers = {},
	originalMembers = {},
	offlineMembers = {},
	assignments = {},
	assignedNames = {},
	blessingCasterNames = {},
	summonIndex = 1,
	setupIndex = 1,
	commandQueue = {},
	commandIndex = 1,
	retryRound = 0,
	maxCastAttempts = 2,
	summoned = {},
	cleanup = {},
	registryCandidates = {},
	registryCandidateIndex = {},
	registryAttempts = {},
	requestedByName = {},
	registryInvites = {},
	attemptedNames = {},
	lateRegistryNames = {},
	keptRegistryNames = {},
	maxRegistryAttempts = 4,
	summonPass = 1,
	targetNames = nil,
	raidTemporaryCapacity = nil,
	raidMemberLimit = 25,
	capacityWaitLogged = false,
	playerActionReported = {},
	restoreReserveAt = nil,
	dungeonReservePending = false,
	dungeonReserveSuperFast = false,
	completionAction = nil,
	log = false,
	progressLastPercent = -1,
	progressLastAt = 0,
	progressLastStage = nil,
	progressLastPhase = 0,
	progressLastChatPercent = -20,
	progressStopHintShown = false,
	lastCastByName = {},
	reagentFailures = {},
	reagentFailureLabels = {},
	reagentFailureOrder = {},
	diagnosticLastStage = nil,
	diagnosticLastPhase = 0,
	refreshPending = {},
	refreshFreshCount = 0,
	refreshNeededCount = 0,
	levelSkippedLabels = {},
	levelSkippedOrder = {},
	serverWaitDeadline = 0,
	serverWaitLastMessageAt = 0,
	arrivalAttempts = {},
	arrivalNextSummonAt = {},
	arrivalReady = {},
	arrivalDeadline = 0,
	arrivalLastMessageAt = 0,
	arrivalResumeMissingOnly = false,
};

-- These helpers must be declared after local UnBotBuffCycle. Functions above
-- this declaration call them through the existing namespace at runtime.
function UnBotSpecSummon.ResetBuffSnapshot()
	UnBotBuffCycle.originalMembers = {};
end

-- A new owner cancels old removal requests before sending add or retaining a
-- roster member. Queues belong to an operation, not permanently to a name.
function UnBotSpecSummon.CancelStaleCleanup(name)
	if (not name) then return; end
	if (UnBotPVEFastSummon) then UnBotPVEFastSummon.CancelCleanup(name); end
	if (UnBotBotScanner) then
		for _, key in ipairs({"cleanupOwnedNames", "lateCleanupNames"}) do
			if (UnBotBotScanner[key]) then UnBotBotScanner[key][name] = nil; end
		end
	end
	for _, key in ipairs({"cleanupQueue", "kickQueue", "rejectedOnline", "registryRequests"}) do
		if (UnBotSpecSummon[key]) then UnBotSpecSummon[key][name] = nil; end
	end
	for _, key in ipairs({"cleanup", "lateRegistryNames", "summoned"}) do
		if (UnBotBuffCycle[key]) then UnBotBuffCycle[key][name] = nil; end
	end
end

function UnBotSpecSummon.CleanupProtected(name)
	if (name == UnitName("player")) then return true; end
	if (UnBotSquadRosterIsOfflineReserve(name)) then return true; end
	if (UnBotSpecSummon.active and UnBotSpecSummon.squad and UnBotSpecSummon.squad.pvpNames
		and UnBotSpecSummon.squad.pvpNames[name]) then return true; end
	if (UnBotBuffCycle.originalMembers and UnBotBuffCycle.originalMembers[name]) then return true; end
	return false;
end

function UnBotMythicPlusBuffCycleActive()
	return UnBotBuffCycle.active == true;
end

function UnBotBuffDiagnosticAdd(kind, text)
	local diagnostic = UnBotSquadConfig and UnBotSquadConfig.lastBuffDiagnostic;
	if (type(diagnostic) ~= "table" or not diagnostic.active) then
		return;
	end
	kind = tostring(kind or "event");
	diagnostic.counts = type(diagnostic.counts) == "table" and diagnostic.counts or {};
	diagnostic.counts[kind] = (tonumber(diagnostic.counts[kind]) or 0) + 1;
	diagnostic.entries = type(diagnostic.entries) == "table" and diagnostic.entries or {};
	if (#diagnostic.entries >= (tonumber(diagnostic.maxEntries) or 1600)) then
		diagnostic.truncated = (tonumber(diagnostic.truncated) or 0) + 1;
		return;
	end
	local elapsed = math.max(0, GetTime() - (tonumber(diagnostic.startedUptime) or GetTime()));
	table.insert(diagnostic.entries, {
		t = math.floor(elapsed * 100 + 0.5) / 100,
		kind = kind,
		text = string.sub(tostring(text or ""), 1, 800),
	});
end

function UnBotBuffDiagnosticStart(mode, superFast)
	UnBotSquadConfig = UnBotSquadConfig or {};
	UnBotSquadConfig.lastSoloBuffDiagnostic = nil;
	if (not UnBotSquadConfig.buffDiagnosticEnabled) then
		return false;
	end
	UnBotSquadConfig.lastBuffDiagnostic = {
		schemaVersion = 2,
		active = true,
		mode = mode == "raid" and "raid" or "solo",
		superFast = superFast and true or false,
		startedAt = date and date("%Y-%m-%d %H:%M:%S") or nil,
		startedUptime = GetTime(),
		maxEntries = 1600,
		entries = {},
		counts = {},
		addonVersion = GetAddOnMetadata and GetAddOnMetadata("UnBotCustom", "Version") or nil,
		playerName = UnitName("player"),
		playerClass = select(2, UnitClass("player")),
		playerLevel = UnitLevel("player"),
		realmName = GetRealmName and GetRealmName() or nil,
		zoneName = GetRealZoneText and GetRealZoneText() or nil,
	};
	local instanceName, instanceType, difficultyIndex, difficultyName, maxPlayers = GetInstanceInfo();
	UnBotBuffDiagnosticAdd(
		"start",
		"version="..tostring(UnBotSquadConfig.lastBuffDiagnostic.addonVersion)
		.."; mode="..tostring(UnBotSquadConfig.lastBuffDiagnostic.mode)
		.."; superFast="..tostring(UnBotSquadConfig.lastBuffDiagnostic.superFast)
		.."; player="..tostring(UnBotSquadConfig.lastBuffDiagnostic.playerName)
		.."; class="..tostring(UnBotSquadConfig.lastBuffDiagnostic.playerClass)
		.."; level="..tostring(UnBotSquadConfig.lastBuffDiagnostic.playerLevel)
		.."; realm="..tostring(UnBotSquadConfig.lastBuffDiagnostic.realmName)
		.."; zone="..tostring(UnBotSquadConfig.lastBuffDiagnostic.zoneName)
		.."; instance="..tostring(instanceName)
		.."; instanceType="..tostring(instanceType)
		.."; difficulty="..tostring(difficultyName or difficultyIndex)
		.."; maxPlayers="..tostring(maxPlayers)
	);
	UnBotSpecSummonMessage(
		"Расширенный лог баффов включён для этого запуска. После завершения выполните /reload и пришлите SavedVariables\\UnBot.lua."
	);
	return true;
end

function UnBotBuffDiagnosticFinish(result)
	local diagnostic = UnBotSquadConfig and UnBotSquadConfig.lastBuffDiagnostic;
	if (type(diagnostic) ~= "table" or not diagnostic.active) then
		return;
	end
	UnBotBuffDiagnosticAdd("finish", result or "finished");
	diagnostic.active = false;
	diagnostic.endedAt = date and date("%Y-%m-%d %H:%M:%S") or nil;
	diagnostic.duration = math.floor(math.max(0, GetTime() - (tonumber(diagnostic.startedUptime) or GetTime())) * 100 + 0.5) / 100;
	diagnostic.result = tostring(result or "finished");
	UnBotSpecSummonMessage(
		"Расширенный лог баффов сохранён: "..tostring(#(diagnostic.entries or {}))
		.." записей. Выполните /reload и пришлите SavedVariables\\UnBot.lua."
	);
end

function UnBotBuffDiagnosticSetEnabled(enabled, announce)
	UnBotSquadConfig = UnBotSquadConfig or {};
	enabled = enabled and true or false;
	if (enabled and UnBotBuffCycle.active) then
		if (announce) then
			UnBotSpecSummonMessage(
				"Расширенный лог нужно включить до запуска баффов. Остановите текущий цикл, включите лог и запустите его заново."
			);
		end
		return false;
	end
	UnBotSquadConfig.buffDiagnosticEnabled = enabled;
	if (not enabled) then
		UnBotBuffDiagnosticFinish("Diagnostic capture disabled by user.");
	end
	if (UnBotBuffProfileUI and UnBotBuffProfileUI.diagnosticCheck) then
		UnBotBuffProfileUI.diagnosticCheck:SetChecked(enabled);
	end
	if (announce) then
		UnBotSpecSummonMessage(
			enabled
				and "Расширенный лог баффов включён. Журнал будет сохраняться после каждого запуска бафф-цикла."
				or "Расширенный лог баффов выключен; уже собранная запись сохранена."
		);
	end
	return true;
end

function UnBotBuffDiagnosticRoster(event)
	local diagnostic = UnBotSquadConfig and UnBotSquadConfig.lastBuffDiagnostic;
	if (type(diagnostic) ~= "table" or not diagnostic.active) then
		return;
	end
	local members = {};
	if (GetNumRaidMembers and GetNumRaidMembers() > 0) then
		for i = 1, GetNumRaidMembers(), 1 do
			local name = GetRaidRosterInfo(i) or UnitName("raid"..i);
			if (name) then
				table.insert(members, name..(UnitIsConnected("raid"..i) and "[on]" or "[off]"));
			end
		end
	else
		local playerName = UnitName("player");
		if (playerName) then
			table.insert(members, playerName..(UnitIsConnected("player") and "[on]" or "[off]"));
		end
		for i = 1, (GetNumPartyMembers and GetNumPartyMembers() or 0), 1 do
			local name = UnitName("party"..i);
			if (name) then
				table.insert(members, name..(UnitIsConnected("party"..i) and "[on]" or "[off]"));
			end
		end
	end
	table.sort(members);
	UnBotBuffDiagnosticAdd("roster", tostring(event or "snapshot")..": "..(#members > 0 and table.concat(members, ", ") or "empty"));
end

function UnBotBuffDiagnosticPlan()
	for phaseNumber, runtimePhase in ipairs(UnBotBuffCycle.runtimePhases or {}) do
		local descriptions = {};
		for _, bot in ipairs(runtimePhase.bots or {}) do
			local labels = {};
			for _, buff in ipairs(bot.buffs or {}) do
				table.insert(labels, tostring(buff.label)..(buff.required and "[required]" or "[optional]"));
			end
			table.insert(descriptions, tostring(bot.label).."{"..table.concat(labels, ", ").."}");
		end
		UnBotBuffDiagnosticAdd(
			"plan",
			"phase="..tostring(phaseNumber).." "..tostring(runtimePhase.label)
			..": "..table.concat(descriptions, "; ")
		);
	end
end

function UnBotBuffDiagnosticCommand(message)
	UnBotSquadConfig = UnBotSquadConfig or {};
	local command = UnBotSpecSummonNormalize(message);
	if (command == "clear" or command == "очистить") then
		if (
			UnBotSquadConfig.lastBuffDiagnostic
			and UnBotSquadConfig.lastBuffDiagnostic.active
		) then
			UnBotSpecSummonMessage("Нельзя очистить расширенный лог во время активного бафф-цикла.");
			return;
		end
		UnBotSquadConfig.lastBuffDiagnostic = nil;
		UnBotSpecSummonMessage("Сохранённый расширенный лог баффов очищен.");
		return;
	end
	local diagnostic = UnBotSquadConfig.lastBuffDiagnostic;
	local stateText = UnBotSquadConfig.buffDiagnosticEnabled
		and (diagnostic and diagnostic.active and "пишется сейчас" or "включён")
		or diagnostic and diagnostic.active and "пишется сейчас"
		or "выключен";
	local savedText = type(diagnostic) == "table"
		and (tostring(#(diagnostic.entries or {})).." записей; режим "
			..tostring(diagnostic.mode or "?").."; результат "
			..tostring(diagnostic.result or (diagnostic.active and "в процессе" or "не завершён")))
		or "нет сохранённого лога";
	UnBotSpecSummonMessage(
		"Расширенный лог баффов: "..stateText.."; "..savedText
		..". Включение и выключение — только галочкой в окне настройки баффов; служебные команды: /ubbufflog status, clear."
	);
end

