function UnBotBuffProfileEnsure()
	UnBotSquadConfig = UnBotSquadConfig or {};
	UnBotSquadConfig.buffProfiles = UnBotSquadConfig.buffProfiles or {};
	for _, profileName in ipairs({"solo", "raid"}) do
		if (type(UnBotSquadConfig.buffProfiles[profileName]) ~= "table") then
			UnBotSquadConfig.buffProfiles[profileName] = {};
		end
		UnBotSquadConfig.buffProfiles[profileName].refreshMinutes =
			type(UnBotSquadConfig.buffProfiles[profileName].refreshMinutes) == "table"
			and UnBotSquadConfig.buffProfiles[profileName].refreshMinutes or {};
		for _, entry in ipairs(UnBotBuffProfileEntries) do
			if (type(UnBotSquadConfig.buffProfiles[profileName][entry.key]) ~= "boolean") then
				UnBotSquadConfig.buffProfiles[profileName][entry.key] = true;
			end
			if (tonumber(UnBotSquadConfig.buffProfiles[profileName].refreshMinutes[entry.key]) == nil) then
				UnBotSquadConfig.buffProfiles[profileName].refreshMinutes[entry.key] = entry.defaultMinutes;
			end
		end
		if (tonumber(UnBotSquadConfig.buffProfiles[profileName].refreshMinutes.Soulstone) == nil) then
			UnBotSquadConfig.buffProfiles[profileName].refreshMinutes.Soulstone = 15;
		end
		if (
			UnBotSquadConfig.buffProfiles[profileName].soulstoneTarget ~= "player"
			and UnBotSquadConfig.buffProfiles[profileName].soulstoneTarget ~= "self"
		) then
			UnBotSquadConfig.buffProfiles[profileName].soulstoneTarget = "off";
		end
		if (type(UnBotSquadConfig.buffProfiles[profileName].prepareOfflineReserve) ~= "boolean") then
			UnBotSquadConfig.buffProfiles[profileName].prepareOfflineReserve = false;
		end
	end
	return UnBotSquadConfig.buffProfiles;
end

function UnBotBuffProfileDefaultMinutes(key)
	if (key == "Soulstone") then
		return 15;
	end
	for _, entry in ipairs(UnBotBuffProfileEntries or {}) do
		if (entry.key == key) then
			return math.max(0, tonumber(entry.defaultMinutes) or 0);
		end
	end
	return 0;
end

function UnBotBuffProfileRefreshMinutes(profileName, key)
	local profiles = UnBotSquadConfig and UnBotSquadConfig.buffProfiles;
	if (type(profiles) ~= "table") then
		profiles = UnBotBuffProfileEnsure();
	end
	local profile = profiles[profileName == "raid" and "raid" or "solo"];
	if (type(profile) ~= "table" or type(profile.refreshMinutes) ~= "table") then
		profiles = UnBotBuffProfileEnsure();
		profile = profiles[profileName == "raid" and "raid" or "solo"];
	end
	local value = tonumber(profile.refreshMinutes and profile.refreshMinutes[key]);
	if (value == nil) then
		value = UnBotBuffProfileDefaultMinutes(key);
	end
	return math.max(0, math.min(1440, value));
end

function UnBotBuffProfileSoulstoneTarget(profileName)
	if (
		profileName == "raid"
		and UnBotMythicPlusBuffIsRunning
		and UnBotMythicPlusBuffIsRunning()
	) then
		return "off";
	end
	local profiles = UnBotBuffProfileEnsure();
	local profile = profiles[profileName == "raid" and "raid" or "solo"];
	return profile.soulstoneTarget or "off";
end

function UnBotBuffProfilePrepareOfflineReserve(profileName)
	return false; -- Compatibility only; automatic reserve preparation was retired.
end

function UnBotBuffProfileIsSuperFastBuff(key)
	return key ~= "Detect Invisibility"
		and key ~= "Fear Ward"
		and key ~= "Unending Breath";
end

function UnBotBuffProfileIsEnabled(profileName, key, superFast)
	if (key == "Soulstone") then
		return UnBotBuffProfileSoulstoneTarget(profileName) ~= "off";
	end
	if (superFast) then
		return UnBotBuffProfileIsSuperFastBuff(key);
	end
	local profiles = UnBotBuffProfileEnsure();
	local profile = profiles[profileName == "raid" and "raid" or "solo"];
	return profile[key] ~= false;
end

local UnBotBuffCycleClassFiles = {
	PRIEST = "priest",
	MAGE = "mage",
	DRUID = "druid",
	WARLOCK = "warlock",
	PALADIN = "paladin",
	DEATHKNIGHT = "dk",
	WARRIOR = "warrior",
};

local function UnBotBuffCyclePlayerLevel()
	local level = tonumber(UnitLevel("player")) or 1;
	return math.max(1, level);
end

local function UnBotBuffCycleBuffAvailable(buff)
	return UnBotBuffCyclePlayerLevel() >= (tonumber(buff and buff.minLevel) or 1);
end

local function UnBotBuffCycleRaidSize()
	local raidCount = GetNumRaidMembers and GetNumRaidMembers() or 0;
	if (raidCount > 0) then
		return raidCount;
	end
	return 1 + (GetNumPartyMembers and GetNumPartyMembers() or 0);
end

function UnBotBuffCycleResolveMemberLimit(requestedLimit)
	local limit = tonumber(requestedLimit);
	if (limit and limit >= 2) then
		return math.max(2, math.min(40, math.floor(limit)));
	end
	if (GetInstanceInfo) then
		local instanceName, instanceType, difficultyIndex, difficultyName, maxPlayers =
			GetInstanceInfo();
		maxPlayers = tonumber(maxPlayers);
		if (maxPlayers and maxPlayers >= 2) then
			return math.max(2, math.min(40, math.floor(maxPlayers)));
		end
	end
	return 25;
end

local function UnBotBuffCycleRaidFreeSlots(includePending)
	local pending = 0;
	if (includePending) then
		for name in pairs(UnBotBuffCycle.registryInvites or {}) do
			if (not UnBotSpecSummonIsInGroup(name)) then pending = pending + 1; end
		end
	end
	return math.max(
		0,
		(tonumber(UnBotBuffCycle.raidMemberLimit) or 25) - UnBotBuffCycleRaidSize() - pending
	);
end

local function UnBotBuffCycleAppendPhaseBatches(target, label, bots, batchSize)
	local batch = {};
	local batchNumber = 0;
	local totalBatches = math.ceil(#bots / batchSize);
	for _, bot in ipairs(bots) do
		table.insert(batch, bot);
		if (#batch >= batchSize) then
			batchNumber = batchNumber + 1;
			table.insert(target, {
				label = totalBatches > 1
					and (label.." "..tostring(batchNumber).."/"..tostring(totalBatches))
					or label,
				bots = batch,
			});
			batch = {};
		end
	end
	if (#batch > 0) then
		batchNumber = batchNumber + 1;
		table.insert(target, {
			label = totalBatches > 1
				and (label.." "..tostring(batchNumber).."/"..tostring(totalBatches))
				or label,
			bots = batch,
		});
	end
end

local function UnBotBuffCycleBuildRuntimePhases()
	local runtimePhases = {};
	UnBotBuffCycle.raidWaveMode = (UnBotBuffCycle.mode == "raid" or UnBotBuffCycle.mode == "solo")
		and not (UnBotMythicPlusBuffIsRunning and UnBotMythicPlusBuffIsRunning());
	UnBotBuffCycle.levelSkippedLabels = {};
	UnBotBuffCycle.levelSkippedOrder = {};
	for _, phase in ipairs(UnBotBuffCyclePhases) do
		local runtimePhase = {
			label = phase.label,
			bots = {},
		};
		for _, bot in ipairs(phase.bots or {}) do
			local availableBuffs = {};
			for _, buff in ipairs(bot.buffs or {}) do
				local enabled = UnBotBuffProfileIsEnabled(
					UnBotBuffCycle.mode,
					buff.label,
					UnBotBuffCycle.superFast
				);
				local available = UnBotBuffCycleBuffAvailable(buff);
				local skippedLabel = UnBotBuffCycleProgressBuffLabel(buff.label);
				if (enabled and not available and not UnBotBuffCycle.levelSkippedLabels[skippedLabel]) then
					UnBotBuffCycle.levelSkippedLabels[skippedLabel] = true;
					table.insert(UnBotBuffCycle.levelSkippedOrder, skippedLabel);
				end
				local includeBuff = enabled and available;
				if (includeBuff and UnBotBuffCycle.mode == "solo") then
					includeBuff = UnBotBuffCycleSoloBuffNeedsRefresh(buff);
				end
				if (includeBuff) then
					table.insert(availableBuffs, buff);
				end
			end
			if (#availableBuffs > 0) then
				table.insert(runtimePhase.bots, {
					className = bot.className,
					spec = bot.spec,
					specAliases = bot.specAliases,
					label = bot.label,
					maxRegistryAttempts = bot.maxRegistryAttempts,
					keepInGroup = bot.keepInGroup or (
						bot.className == "warlock"
						and UnBotBuffProfileIsEnabled(
							UnBotBuffCycle.mode,
							"Soulstone",
							UnBotBuffCycle.superFast
						)
					),
					preCommands = bot.preCommands,
					buffs = availableBuffs,
				});
			end
		end
		if (#runtimePhase.bots > 0) then
			table.insert(runtimePhases, runtimePhase);
		end
	end

	if (UnBotBuffCycle.mode == "raid" or UnBotBuffCycle.raidWaveMode) then
		local batchedPhases = {};
		local normalBots = {};
		local deferredBots = {};
		local batchSize = (UnBotBuffCycle.raidTemporaryCapacity or 0) <= 0
			and 99
			or math.max(1, UnBotBuffCycle.raidTemporaryCapacity or UnBotBuffCycleRaidFreeSlots());
		for _, phase in ipairs(runtimePhases) do
			for _, bot in ipairs(phase.bots or {}) do
				if (bot.keepInGroup) then
					table.insert(deferredBots, bot);
				else
					table.insert(normalBots, bot);
				end
			end
			if (not UnBotBuffCycle.raidWaveMode) then
				UnBotBuffCycleAppendPhaseBatches(batchedPhases, phase.label, normalBots, batchSize);
				normalBots = {};
			end
		end
		-- Fill every wave across the old class phases. Retained casters go last
		-- so they cannot occupy slots needed by subsequent temporary waves.
		for _, bot in ipairs(deferredBots) do
			table.insert(normalBots, bot);
		end
		UnBotBuffCycleAppendPhaseBatches(batchedPhases,
			UnBotBuffCycle.raidWaveMode and "Общая очередь бафферов" or "persistent buffs", normalBots, batchSize);
		runtimePhases = batchedPhases;
	end
	return runtimePhases;
end

local function UnBotBuffCycleForEachGroupMember(callback)
	if (GetNumRaidMembers() and GetNumRaidMembers() > 0) then
		for i = 1, GetNumRaidMembers(), 1 do
			local unit = "raid"..i;
			local name = GetRaidRosterInfo(i) or UnitName(unit);
			if (name and name ~= UnitName("player")) then
				callback(name, unit);
			end
		end
	else
		for i = 1, GetNumPartyMembers(), 1 do
			local unit = "party"..i;
			local name = UnitName(unit);
			if (name) then
				callback(name, unit);
			end
		end
	end
end

local function UnBotBuffCycleOtherMemberCount(onlineOnly)
	local count = 0;
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		if (not onlineOnly or (unit and UnitIsConnected(unit))) then
			count = count + 1;
		end
	end);
	return count;
end

local function UnBotBuffCycleSnapshotTargets()
	local targets = {};
	local seen = {};
	local playerName = UnitName("player");
	if (playerName) then
		table.insert(targets, playerName);
		seen[playerName] = true;
	end
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		if (name and unit and UnitIsConnected(unit) and not seen[name]) then
			table.insert(targets, name);
			seen[name] = true;
		end
	end);
	return targets;
end

local function UnBotBuffCycleResolveUnit(name)
	if (not name) then
		return nil;
	end
	if (name == UnitName("player")) then
		return "player";
	end
	if (GetNumRaidMembers() and GetNumRaidMembers() > 0) then
		for i = 1, GetNumRaidMembers(), 1 do
			local unit = "raid"..i;
			if ((GetRaidRosterInfo(i) or UnitName(unit)) == name) then
				return unit;
			end
		end
	else
		for i = 1, GetNumPartyMembers(), 1 do
			local unit = "party"..i;
			if (UnitName(unit) == name) then
				return unit;
			end
		end
	end
	return nil;
end

local function UnBotBuffCycleTargetClass(name)
	local unit = UnBotBuffCycleResolveUnit(name);
	if (not unit) then
		return nil;
	end
	local localizedClass, classFile = UnitClass(unit);
	return UnBotBuffCycleClassFiles[classFile] or string.lower(tostring(localizedClass or ""));
end

local function UnBotBuffCycleTargetIsTank(name)
	local className = UnBotBuffCycleTargetClass(name);
	local profile = UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	local specName = UnBotSpecSummonNormalize(profile and profile.specName);
	if (className == "warrior" or className == "paladin") then
		return name == UnitName("player") or specName == "protection";
	elseif (className == "dk") then
		return name == UnitName("player") or specName == "blood";
	elseif (className == "druid") then
		return name == UnitName("player") or UnBotFeralProfileRole(profile) == "bear";
	end
	return false;
end

local function UnBotBuffCycleTargetCasterScore(name)
	local className = UnBotBuffCycleTargetClass(name);
	if (className == "mage" or className == "warlock") then
		return 4;
	elseif (className == "priest" or className == "shaman" or className == "druid") then
		return 3;
	elseif (className == "paladin") then
		return 2;
	end
	return 0;
end

local function UnBotBuffCycleFormatCommand(command)
	command = tostring(command or "");
	command = string.gsub(command, "{player}", UnitName("player") or "");
	local playerName = UnitName("player");
	if (playerName and string.find(command, "^cast%s+") and not string.find(command, "%son%s+"..playerName.."$") and string.find(command, "%s"..playerName.."$")) then
		command = string.gsub(command, "%s"..playerName.."$", " on "..playerName);
	end
	return command;
end

local function UnBotBuffCycleSendWhisper(name, command)
	command = UnBotBuffCycleFormatCommand(command);
	UnBotBuffDiagnosticAdd("send_whisper", tostring(name)..": "..command);
	if (UnBotBuffCycle.log) then
		UnBotSpecSummonMessage("Buff cycle send -> "..tostring(name)..": "..command);
	end
	SendChatMessage(command, "WHISPER", nil, name);
end

local function UnBotBuffCycleSendSay(command, direct)
	command = UnBotBuffCycleFormatCommand(command);
	local channel = "SAY";
	if (UnitIsDeadOrGhost and UnitIsDeadOrGhost("player")) then
		if (GetNumRaidMembers and GetNumRaidMembers() > 0) then
			channel = "RAID";
		elseif (GetNumPartyMembers and GetNumPartyMembers() > 0) then
			channel = "PARTY";
		end
	end
	if (UnBotBuffCycle.log) then
		UnBotSpecSummonMessage("Buff cycle send -> "..channel..": "..command);
	end
	UnBotBuffDiagnosticAdd("send_"..string.lower(channel), command);
	-- Reserve operations own their lifecycle; only buff operations use the buff queue.
	if (not direct and UnBotBatchSummon and UnBotBatchSummon.QueueBuff(command)) then return; end
	SendChatMessage(command, channel);
end

function UnBotBuffCycleFindUnitBuff(unit, buff)
	if (not unit or not buff) then
		return nil;
	end
	local wantedIds = buff.ids or {};
	if (
		buff.lowLevelIds
		and UnBotBuffCyclePlayerLevel() < (tonumber(buff.groupMinLevel) or 1)
	) then
		wantedIds = buff.lowLevelIds;
	end
	for i = 1, 40, 1 do
		local name, rank, icon, count, debuffType, duration, expirationTime, unitCaster, isStealable, shouldConsolidate, spellId = UnitBuff(unit, i);
		if (not name) then
			break
		end
		for _, wantedId in ipairs(wantedIds) do
			if ((spellId and spellId == wantedId) or (GetSpellInfo and name == GetSpellInfo(wantedId))) then
				return i, expirationTime, duration, spellId, name;
			end
		end
	end
	return nil;
end

function UnBotBuffCycleRefreshThreshold(buff, duration)
	local threshold = UnBotBuffProfileRefreshMinutes(
		UnBotBuffCycle.mode,
		buff and buff.label
	) * 60;
	duration = tonumber(duration);
	if (duration and duration > 0) then
		-- Low-rank single-target auras are shorter than their group versions.
		-- Trust the duration reported by this client and leave normal latency room.
		threshold = math.min(threshold, duration * 0.8);
	end
	return math.max(0, threshold);
end

function UnBotBuffCycleSoloBuffNeedsRefresh(buff)
	if (
		buff
		and buff.soulstone
		and UnBotBuffProfileSoulstoneTarget("solo") == "self"
	) then
		UnBotBuffCycle.refreshNeededCount = (UnBotBuffCycle.refreshNeededCount or 0) + 1;
		return true;
	end
	local auraIndex, expirationTime, duration = UnBotBuffCycleFindUnitBuff("player", buff);
	local threshold = UnBotBuffCycleRefreshThreshold(buff, duration);
	if (not auraIndex) then
		UnBotBuffCycle.refreshPending[buff.label] = { existed = false };
		UnBotBuffCycle.refreshNeededCount = (UnBotBuffCycle.refreshNeededCount or 0) + 1;
		UnBotBuffDiagnosticAdd("refresh", tostring(buff.label)..": missing; will apply");
		return true;
	end
	local remaining = expirationTime and expirationTime > 0
		and math.max(0, expirationTime - GetTime()) or math.huge;
	if (remaining >= threshold - 2) then
		UnBotBuffCycle.refreshFreshCount = (UnBotBuffCycle.refreshFreshCount or 0) + 1;
		UnBotBuffDiagnosticAdd(
			"refresh",
			tostring(buff.label)..": fresh; remaining="..tostring(math.floor(remaining))
			.."s; threshold="..tostring(math.floor(threshold)).."s; skipped"
		);
		return false;
	end
	UnBotBuffCycle.refreshPending[buff.label] = {
		existed = true,
		originalExpiration = expirationTime,
		originalRemaining = remaining,
		duration = duration,
	};
	UnBotBuffCycle.refreshNeededCount = (UnBotBuffCycle.refreshNeededCount or 0) + 1;
	UnBotBuffDiagnosticAdd(
		"refresh",
		tostring(buff.label)..": stale; remaining="..tostring(math.floor(remaining))
		.."s; threshold="..tostring(math.floor(threshold)).."s; will replace"
	);
	return true;
end

function UnBotBuffCyclePrepareSoloRefresh(buff)
	if (UnBotBuffCycle.mode ~= "solo" or not buff) then
		return true;
	end
	local pending = UnBotBuffCycle.refreshPending and UnBotBuffCycle.refreshPending[buff.label];
	if (not pending) then
		return true;
	end
	if (not pending.existed) then
		return true;
	end
	local auraIndex, expirationTime = UnBotBuffCycleFindUnitBuff("player", buff);
	if (not auraIndex) then
		return true;
	end
	if (
		expirationTime
		and pending.originalExpiration
		and expirationTime > pending.originalExpiration + 5
	) then
		pending.refreshedElsewhere = true;
		UnBotBuffDiagnosticAdd("refresh", tostring(buff.label)..": already refreshed before command; command skipped");
		return false;
	end
	if ((tonumber(UnBotBuffCycle.retryRound) or 0) < 1) then
		pending.attemptedWithoutCancel = true;
		UnBotBuffDiagnosticAdd(
			"refresh",
			tostring(buff.label)..": first refresh attempt keeps the existing aura"
		);
		return true;
	end
	if (pending.cancelRequested) then
		return true;
	end
	if (UnitAffectingCombat and UnitAffectingCombat("player")) then
		pending.cancelBlocked = true;
		UnBotSpecSummonMessage(
			"Fast Solo: истекающий бафф "..tostring(buff.label)
			.." не снимается в бою; обновление пропущено."
		);
		return false;
	end
	if (CancelUnitBuff) then
		CancelUnitBuff("player", auraIndex);
		pending.cancelRequested = true;
		UnBotBuffDiagnosticAdd(
			"refresh",
			tostring(buff.label)..": stale aura cancelled immediately before recast"
		);
	end
	return true;
end

local function UnBotBuffCycleUnitHasBuff(unit, buff, requireFresh)
	local auraIndex, expirationTime, duration = UnBotBuffCycleFindUnitBuff(unit, buff);
	if (not auraIndex) then
		return false;
	end
	local refreshSeconds = UnBotBuffCycleRefreshThreshold(buff, duration);
	if (
		requireFresh
		and refreshSeconds > 0
		and expirationTime
		and expirationTime > 0
		and (expirationTime - GetTime()) < refreshSeconds - 2
	) then
		return false;
	end
	return true;
end

local function UnBotBuffCyclePlayerHasBuff(buff)
	return UnBotBuffCycleUnitHasBuff("player", buff);
end

function UnBotBuffCycleEffectiveGroupTarget(buff)
	if (buff and buff.soulstone) then
		return UnBotBuffProfileSoulstoneTarget(UnBotBuffCycle.mode) == "self"
			and "self" or "master";
	end
	return buff and buff.groupTarget or "all";
end

function UnBotBuffCycleAssignedBuffMissing(buff, sourceName)
	if (buff and buff.soulstone and UnBotBuffProfileSoulstoneTarget(UnBotBuffCycle.mode) == "self") then
		local unit = sourceName and UnBotBuffCycleResolveUnit(sourceName);
		local hasBuff = unit and UnBotBuffCycleUnitHasBuff(unit, buff, true);
		return not hasBuff;
	end
	local auraIndex, expirationTime = UnBotBuffCycleFindUnitBuff("player", buff);
	if (not auraIndex) then
		return true;
	end
	local pending = UnBotBuffCycle.mode == "solo"
		and UnBotBuffCycle.refreshPending
		and UnBotBuffCycle.refreshPending[buff and buff.label];
	if (
		pending
		and pending.existed
		and pending.originalExpiration
		and expirationTime
		and expirationTime <= pending.originalExpiration + 5
		and not pending.refreshedElsewhere
	) then
		return true;
	end
	return false;
end

local function UnBotBuffCycleGroupAffectedNames(buff, missingOnly, sourceName)
	local targets = UnBotBuffCycle.targetNames or UnBotBuffCycleSnapshotTargets();
	local targetMode = UnBotBuffCycleEffectiveGroupTarget(buff);
	if (targetMode == "self" and sourceName) then
		targets = { sourceName };
	end
	local affected = {};
	local bestCaster;
	local bestCasterScore = -1;

	for _, name in ipairs(targets) do
		local unit = UnBotBuffCycleResolveUnit(name);
		if (unit) then
			local include = false;
			if (targetMode == "master") then
				include = name == UnitName("player");
			elseif (targetMode == "self") then
				include = name == sourceName;
			elseif (targetMode == "tanks") then
				include = UnBotBuffCycleTargetIsTank(name);
			elseif (targetMode == "caster") then
				local score = UnBotBuffCycleTargetCasterScore(name);
				if (name ~= sourceName and score > 0 and score > bestCasterScore) then
					bestCaster = name;
					bestCasterScore = score;
				end
			else
				include = true;
			end
			local targetHasBuff = include and UnBotBuffCycleUnitHasBuff(unit, buff, true);
			if (include and (not missingOnly or not targetHasBuff)) then
				table.insert(affected, name);
			end
		end
	end

	if (targetMode == "caster" and bestCaster) then
		local unit = UnBotBuffCycleResolveUnit(bestCaster);
		if (not missingOnly or not UnBotBuffCycleUnitHasBuff(unit, buff, true)) then
			table.insert(affected, bestCaster);
		end
	elseif (targetMode == "tanks" and #affected == 0 and not missingOnly) then
		local playerName = UnitName("player");
		if (playerName) then
			table.insert(affected, playerName);
		end
	end
	return affected;
end

local function UnBotBuffCycleGroupCommandTargets(buff, missingOnly, sourceName)
	local affected = UnBotBuffCycleGroupAffectedNames(buff, missingOnly, sourceName);
	local targetMode = UnBotBuffCycleEffectiveGroupTarget(buff);
	if (
		buff.lowLevelCommand
		and UnBotBuffCyclePlayerLevel() < (tonumber(buff.groupMinLevel) or 1)
	) then
		return affected;
	end
	if (targetMode == "raid") then
		return affected[1] and { affected[1] } or {};
	elseif (targetMode == "class") then
		local representatives = {};
		local seenClasses = {};
		for _, name in ipairs(affected) do
			local className = UnBotBuffCycleTargetClass(name) or name;
			if (not seenClasses[className]) then
				seenClasses[className] = true;
				table.insert(representatives, name);
			end
		end
		return representatives;
	end
	return affected;
end

local function UnBotBuffCycleCleanup()
	for name in pairs(UnBotBuffCycle.summoned or {}) do
		if (
			UnBotSpecSummonIsInGroup(name)
			and not (UnBotBuffCycle.originalMembers and UnBotBuffCycle.originalMembers[name])
			and not (UnBotBuffCycle.cleanup[name] and UnBotBuffCycle.cleanup[name].boundedArrival)
		) then
			UnBotBuffCycle.keptRegistryNames[name] = nil;
			if not ((UnitAffectingCombat and UnitAffectingCombat("player")) or (InCombatLockdown and InCombatLockdown())) then
				UnBotSpecSummonUninvite(name);
			end
			UnBotBuffCycle.cleanup[name] = {
				removeSent = false, nextTime = GetTime() + 0.5, untilTime = GetTime() + 30,
			};
		end
	end
end

local function UnBotBuffCycleStop(text, cleanup, preserveProgress)
	if (cleanup) then
		UnBotBuffCycleCleanup();
	end
	if (not preserveProgress) then
		UnBotBuffCycleProgressHide();
	end
	UnBotBuffCycle.active = false;
	UnBotBuffCycle.stage = nil;
	UnBotBuffCycle.phaseIndex = 0;
	UnBotBuffCycle.runtimePhases = nil;
	UnBotBuffCycle.assignments = {};
	UnBotBuffCycle.assignedNames = {};
	UnBotBuffCycle.blessingCasterNames = {};
	UnBotBuffCycle.registryInvites = {};
	UnBotBuffCycle.targetNames = nil;
	UnBotBuffCycle.raidTemporaryCapacity = nil;
	UnBotBuffCycle.raidWaveMode = nil;
	UnBotBuffCycle.sentCommands = nil;
	UnBotBuffCycle.nextCastByName = nil;
	UnBotBuffCycle.verifyAfter = nil;
	UnBotBuffCycle.raidMemberLimit = 25;
	UnBotBuffCycle.capacityWaitLogged = false;
	-- Keep the snapshot until the next explicit operation: delayed cleanup
	-- runs even while active=false, including after successful completion.
	UnBotBuffCycle.offlineMembers = {};
	UnBotBuffCycle.mode = "solo";
	UnBotBuffCycle.superFast = false;
	UnBotBuffCycle.completionAction = nil;
	UnBotBuffCycle.refreshPending = {};
	UnBotBuffCycle.refreshFreshCount = 0;
	UnBotBuffCycle.refreshNeededCount = 0;
	UnBotBuffCycle.levelSkippedLabels = {};
	UnBotBuffCycle.levelSkippedOrder = {};
	UnBotBuffCycle.replacementSetupOnly = nil;
	UnBotBuffCycle.replacementMissingOnly = nil;
	UnBotBuffCycle.serverWaitDeadline = 0;
	UnBotBuffCycle.serverWaitLastMessageAt = 0;
	UnBotBuffCycle.arrivalAttempts = {};
	UnBotBuffCycle.arrivalNextSummonAt = {};
	UnBotBuffCycle.arrivalReady = {};
	UnBotBuffCycle.arrivalDeadline = 0;
	UnBotBuffCycle.arrivalLastMessageAt = 0;
	UnBotBuffCycle.arrivalResumeMissingOnly = false;
	UnBotBuffCycle.arrivalReplacementName = nil;
	UnBotBuffCycleProgressReset();
	if (text) then
		UnBotSpecSummonMessage(text);
	end
	UnBotBuffDiagnosticFinish(text or "Buff cycle stopped without a result message.");
end

local function UnBotBuffCycleCurrentPhase()
	local phases = UnBotBuffCycle.runtimePhases or UnBotBuffCyclePhases;
	return phases[UnBotBuffCycle.phaseIndex];
end

-- An interrupted run never owns a later manual run or its completion callback.
function UnBotBuffCycle.Interrupt(reason)
	if not UnBotBuffCycle.active then return; end
	for name in pairs(UnBotBuffCycle.requestedByName or {}) do
		if not (UnBotBuffCycle.originalMembers and UnBotBuffCycle.originalMembers[name])
			and not UnBotSquadRosterIsOfflineReserve(name) then
			UnBotBuffCycle.cleanup[name] = UnBotBuffCycle.cleanup[name] or
				{removeSent=false,nextTime=GetTime(),untilTime=GetTime()+30};
		end
	end
	UnBotBuffCycleStop("Бафф-цикл прерван: "..reason..". После воскрешения и очистки временных бафферов запустите заново.", true);
	if UnBotSquadBuilder then
		UnBotSquadBuilder.postSummonSequence=nil;
		UnBotSquadBuilder.pendingBossPreset=nil;
	end
end

function UnBotBuffCycle.ReadyForStart()
	if UnitIsDeadOrGhost and UnitIsDeadOrGhost("player") then
		UnBotSpecSummonMessage("Бафф-цикл не запущен: игрок мёртв. Повторите после воскрешения."); return false;
	end
	if UnitAffectingCombat and UnitAffectingCombat("player") then
		UnBotSpecSummonMessage("Бафф-цикл не запущен: идёт бой."); return false;
	end
	if not UnBotBuffCycle.active and next(UnBotBuffCycle.cleanup or {}) then
		UnBotSpecSummonMessage("Бафф-цикл: завершаю очистку предыдущих временных бафферов; повторите запуск после неё."); return false;
	end
	return true;
end

function UnBotBuffCycle.MarkUnavailable(index)
	local phase=UnBotBuffCycleCurrentPhase();
	local bot=phase and phase.bots[index];
	if not bot or UnBotBuffCycle.assignments[index] then return; end
	UnBotBuffCycle.skippedAssignments=UnBotBuffCycle.skippedAssignments or {};
	if UnBotBuffCycle.skippedAssignments[index] then return; end
	UnBotBuffCycle.skippedAssignments[index]=true;
	UnBotBuffCycle.skippedBuffs=UnBotBuffCycle.skippedBuffs or {};
	for _,buff in ipairs(bot.buffs or {}) do
		local label=UnBotBuffCycleProgressBuffLabel(buff.label);
		UnBotBuffCycle.skippedBuffs[label]="не найден доступный баффер";
		UnBotSpecSummonMessage("Пропущен бафф: "..label.." — не найден доступный баффер; продолжаю остальные.");
		UnBotBuffDiagnosticAdd("skipped_buff",label..": не найден доступный баффер");
	end
end

local function UnBotBuffCycleAssignMembers()
	local phase = UnBotBuffCycleCurrentPhase();
	if (not phase) then
		return;
	end
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		local assignmentIndex = UnBotBuffCycle.requestedByName[name];
		if (
			assignmentIndex
			and unit and UnitIsConnected(unit)
			and not (UnitIsDeadOrGhost and UnitIsDeadOrGhost(unit))
			and not UnBotBuffCycle.baselineMembers[name]
			and not UnBotBuffCycle.assignedNames[name]
			and not UnBotBuffCycle.assignments[assignmentIndex]
			and not (
				phase.bots[assignmentIndex]
				and phase.bots[assignmentIndex].className == "paladin"
				and UnBotBuffCycle.blessingCasterNames[name]
			)
		) then
			local bot = phase.bots[assignmentIndex];
			UnBotBuffCycle.assignments[assignmentIndex] = name;
			UnBotBuffCycle.assignedNames[name] = true;
			if (bot.className == "paladin") then
				UnBotBuffCycle.blessingCasterNames[name] = true;
			end
			UnBotBuffCycle.summoned[name] = true;
			UnBotRememberKnownBot(name);
			local summonCount = UnBotRegistryRecordGameplaySummon(
				name,
				UnBotBuffCycle.mode == "raid" and "raid-buff" or "fast-solo"
			);
			if (bot.className == "warlock") then
				UnBotBuffCycleSendWhisper(name, "nc -ss master,-ss self,-ss tank,-ss healer");
				UnBotSpecSummonMessage(
					"Buff cycle: Soulstone disabled for temporary Warlock "..name
					.."; the bot will be removed after buffing."
				);
			end
			if not UnBotBuffCycleCasterReady(name) then
				UnBotBuffCycleSendWhisper(name, "summon");
				UnBotBuffCycle.arrivalAttempts[name] = 1;
			end
			UnBotBuffCycle.arrivalNextSummonAt[name] = GetTime() + 5;
			UnBotSpecSummonMessage(
				"Buff registry: "..bot.label.." joined; waiting for summon near player ("..name..", "
				..bot.className.." "..bot.spec..", summons "
				..tostring(summonCount or "?")..")."
			);
		elseif (
			assignmentIndex
			and unit and UnitIsConnected(unit)
			and not UnBotBuffCycle.baselineMembers[name]
			and not UnBotBuffCycle.assignedNames[name]
			and UnBotBuffCycle.assignments[assignmentIndex] ~= name
		) then
			-- A previously timed-out named request arrived after its replacement.
			UnBotBuffCycle.assignedNames[name] = true;
			UnBotBuffCycle.summoned[name] = true;
			UnBotSpecSummonUninvite(name);
			UnBotBuffCycle.cleanup[name] = {
				removeSent = false,
				nextTime = GetTime() + 0.5,
				untilTime = GetTime() + 30,
			};
			UnBotSpecSummonMessage("Buff registry: removing delayed duplicate "..name..".");
		end
	end);
end

local function UnBotBuffCyclePrepareRegistryPhase()
	local phase = UnBotBuffCycleCurrentPhase();
	UnBotBuffCycle.skippedAssignments = {};
	UnBotBuffCycle.registryCandidates = {};
	UnBotBuffCycle.registryCandidateIndex = {};
	UnBotBuffCycle.registryAttempts = {};
	UnBotBuffCycle.requestedByName = {};
	UnBotBuffCycle.registryInvites = {};
	UnBotBuffCycle.attemptedNames = {};
	UnBotBuffCycle.summonPass = 1;
	UnBotBuffCycle.arrivalAttempts = {};
	UnBotBuffCycle.arrivalNextSummonAt = {};
	UnBotBuffCycle.arrivalReady = {};
	for i, bot in ipairs((phase and phase.bots) or {}) do
		UnBotBuffCycle.registryCandidates[i] = UnBotRegistryCandidates(
			bot.className,
			bot.specAliases or {bot.spec},
			UnBotBuffCycle.offlineMembers
		);
		UnBotBuffCycle.registryCandidateIndex[i] = 1;
		UnBotBuffCycle.registryAttempts[i] = 0;
	end

	if (UnBotBuffCycle.mode == "raid") then
		for assignmentIndex, bot in ipairs((phase and phase.bots) or {}) do
			UnBotBuffCycleForEachGroupMember(function(name, unit)
				local profile = UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
				if (
					not UnBotBuffCycle.assignments[assignmentIndex]
					and unit and UnitIsConnected(unit)
					and not (UnitIsDeadOrGhost and UnitIsDeadOrGhost(unit))
					and not UnBotBuffCycle.assignedNames[name]
					and not (
						bot.className == "paladin"
						and UnBotBuffCycle.blessingCasterNames[name]
					)
					and UnBotRegistryProfileMatches(
						profile,
						bot.className,
						bot.specAliases or {bot.spec}
					)
				) then
					UnBotBuffCycle.assignments[assignmentIndex] = name;
					UnBotBuffCycle.assignedNames[name] = true;
					if (bot.className == "paladin") then
						UnBotBuffCycle.blessingCasterNames[name] = true;
					end
					UnBotBuffCycle.attemptedNames[name] = true;
					UnBotSpecSummonMessage(
						"Баф рейда: используем уже находящегося в группе "
						..name.." ("..bot.className.." "
						..tostring(profile.specName or bot.spec)..")."
					);
				end
			end);
		end
	end
end

local function UnBotBuffCycleNextRegistryCandidate(assignmentIndex)
	local phase = UnBotBuffCycleCurrentPhase();
	local bot = phase and phase.bots[assignmentIndex];
	local candidates = UnBotBuffCycle.registryCandidates[assignmentIndex] or {};
	local candidateIndex = UnBotBuffCycle.registryCandidateIndex[assignmentIndex] or 1;
	while (candidateIndex <= #candidates) do
		local name = candidates[candidateIndex];
		local profile = UnBotBotRegistry and UnBotBotRegistry.bots
			and UnBotBotRegistry.bots[name];
		candidateIndex = candidateIndex + 1;
		UnBotBuffCycle.registryCandidateIndex[assignmentIndex] = candidateIndex;
		if (
			not UnBotBuffCycle.attemptedNames[name]
			and not UnBotSpecSummonIsInGroup(name)
			and not (UnBotBuffCycle.originalMembers and UnBotBuffCycle.originalMembers[name])
			and not (UnBotBuffCycle.baselineMembers and UnBotBuffCycle.baselineMembers[name])
			and not UnBotRegistryGetActiveFlag(profile)
			and not UnBotBuffCycleArrivalBlock(name)
			and not (
				bot and bot.className == "paladin"
				and UnBotBuffCycle.blessingCasterNames[name]
			)
		) then
			UnBotSpecSummon.CancelStaleCleanup(name);
			UnBotBuffCycle.attemptedNames[name] = true;
			UnBotBuffCycle.registryAttempts[assignmentIndex] =
				(UnBotBuffCycle.registryAttempts[assignmentIndex] or 0) + 1;
			UnBotBuffCycle.requestedByName[name] = assignmentIndex;
			UnBotBuffCycle.registryInvites[name] = {
				attempts=0, nextTime=GetTime()+3, untilTime=GetTime()+6,
				maxAttempts=1, retryInterval=3, waitWithoutQuarantine=true,
			};
			UnBotBuffCycle.lateRegistryNames[name] = UnBotBuffCycle.mode == "solo"
				and math.max(
					GetTime() + 300,
					(tonumber(UnBotBuffCycle.serverWaitDeadline) or GetTime()) + 120
				)
				or GetTime() + 120;
			return name;
		end
	end
	return nil;
end

function UnBotBuffCycleRegistryAttemptLimit(assignmentIndex)
	-- The finite phase snapshot is the limit: a failed fourth candidate must
	-- not hide the fifth. attemptedNames and candidateIndex prevent repeats.
	return math.max(1, #(UnBotBuffCycle.registryCandidates[assignmentIndex] or {}));
end

function UnBotBuffCycleCanRetryAssignment(assignmentIndex)
	local phase = UnBotBuffCycleCurrentPhase();
	local bot = phase and phase.bots and phase.bots[assignmentIndex];
	if (
		not bot
		or (UnBotBuffCycle.registryAttempts[assignmentIndex] or 0)
			>= UnBotBuffCycleRegistryAttemptLimit(assignmentIndex)
	) then
		return false;
	end
	local candidates = UnBotBuffCycle.registryCandidates[assignmentIndex] or {};
	local candidateIndex = UnBotBuffCycle.registryCandidateIndex[assignmentIndex] or 1;
	for index = candidateIndex, #candidates, 1 do
		local candidateName = candidates[index];
		local profile = UnBotBotRegistry and UnBotBotRegistry.bots
			and UnBotBotRegistry.bots[candidateName];
		if (
			not UnBotBuffCycle.attemptedNames[candidateName]
			and not UnBotSpecSummonIsInGroup(candidateName)
			and not (UnBotBuffCycle.originalMembers and UnBotBuffCycle.originalMembers[candidateName])
			and not (UnBotBuffCycle.baselineMembers and UnBotBuffCycle.baselineMembers[candidateName])
			and not UnBotBuffCycleArrivalBlock(candidateName)
			and not UnBotRegistryGetActiveFlag(profile)
			and not (
				bot.className == "paladin"
				and UnBotBuffCycle.blessingCasterNames[candidateName]
			)
		) then
			return true;
		end
	end
	return false;
end

local function UnBotBuffCycleCanRetryRegistry()
	local phase = UnBotBuffCycleCurrentPhase();
	for i = 1, #((phase and phase.bots) or {}), 1 do
		if (
			not UnBotBuffCycle.assignments[i]
			and UnBotBuffCycleCanRetryAssignment(i)
		) then
			return true;
		end
	end
	return false;
end

local function UnBotBuffCycleValidateRegistry()
	if (
		UnBotBuffCycle.mode == "raid"
		and (UnBotBuffCycle.raidTemporaryCapacity or 0) <= 0
	) then
		return true;
	end
	for _, phase in ipairs(UnBotBuffCycle.runtimePhases or UnBotBuffCyclePhases) do
		local requirements = {};
		for _, bot in ipairs(phase.bots or {}) do
			local classOnly = not UnBotSpecSummonPlayerSupportsSpecs();
			local aliases = bot.specAliases or {bot.spec};
			local key = classOnly
				and bot.className
				or (bot.className.."\031"..table.concat(aliases, "\031"));
			local requirement = requirements[key];
			if (not requirement) then
				requirement = {
					className = bot.className,
					spec = classOnly and "class-only" or bot.spec,
					specAliases = aliases,
					need = 0,
				};
				if (classOnly) then
					requirement.specAliases = nil;
				end
				requirements[key] = requirement;
			end
			requirement.need = requirement.need + 1;
		end
		for _, requirement in pairs(requirements) do
			local available = #UnBotRegistryCandidates(
				requirement.className,
				requirement.specAliases or {requirement.spec},
				UnBotBuffCycle.offlineMembers,
				not UnBotSpecSummonPlayerSupportsSpecs()
			);
			if (available < requirement.need) then
				UnBotSpecSummonMessage(
					(UnBotBuffCycle.mode == "raid" and "Баф рейда" or "Fast Solo")
					.." registry missing: "..requirement.className.." "..requirement.spec
					.." needs "..tostring(requirement.need)..", saved "..tostring(available)
					..". Попробую доступных кандидатов; при неудаче пропущу только эти баффы."
				);
				-- Missing one specialization must not cancel the other buffs.
			end
		end
	end
	return true;
end

local function UnBotBuffCycleAllAssigned()
	local phase = UnBotBuffCycleCurrentPhase();
	if (not phase) then
		return false;
	end
	for i = 1, #phase.bots, 1 do
		if (not UnBotBuffCycle.assignments[i]) then
			return false;
		end
	end
	return true;
end

function UnBotBuffCycleHasPendingRegistryInvites(requestedIndex)
	for name, invite in pairs(UnBotBuffCycle.registryInvites or {}) do
		local assignmentIndex = UnBotBuffCycle.requestedByName[name];
		if (
			invite
			and assignmentIndex
			and (not requestedIndex or assignmentIndex == requestedIndex)
			and not UnBotBuffCycle.assignments[assignmentIndex]
		) then
			return true;
		end
	end
	return false;
end

function UnBotBuffCycleMessageHasName(text, name)
	for token in tostring(text or ""):lower():gmatch("[^%s%p]+") do
		if token == tostring(name or ""):lower() then return true; end
	end
	return false;
end

function UnBotBuffCycleArrivalBlock(name, failed, refresh)
	if failed and UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots and UnBotBotRegistry.bots[name]) then return false; end
	if not GetInstanceInfo or not GetRealmName or not IsInInstance then return false; end
	local inside, kind = IsInInstance();
	local instanceName, instanceKind, difficulty, _, _, _, _, mapID = GetInstanceInfo();
	local realm, player = GetRealmName(), UnitName("player");
	if not realm or not player then return false; end
	local context = realm..":"..player;
	UnBotSquadConfig = UnBotSquadConfig or {};
	UnBotSquadConfig.buffArrivalBlocks = UnBotSquadConfig.buffArrivalBlocks or {};
	local blocks = UnBotSquadConfig.buffArrivalBlocks;
	if not inside or (kind ~= "party" and kind ~= "raid") then
		if refresh and inside == false then blocks[context] = nil; end
		if failed then UnBotBuffCycleQuarantineForHour(name, "не появился после двух summon с интервалом 3 секунды"); end
		return false;
	end
	if not instanceName or instanceName == "" then return false; end
	local key = instanceName..":"..tostring(mapID)..":"..tostring(difficulty);
	if refresh and blocks[context] and blocks[context].instance ~= key then blocks[context] = nil; end
	if failed then
		if not blocks[context] or blocks[context].instance ~= key then blocks[context] = {instance = key, names = {}}; end
		blocks[context].names[name] = time();
		UnBotSpecSummonMessage("Бафф-карантин: "..name.." не подтвердил прибытие после summon; исключён до выхода из подземелья.");
	end
	return name and blocks[context] and blocks[context].instance == key and blocks[context].names[name] ~= nil or false;
end

function UnBotBuffCycleCasterReady(name)
	local unit = UnBotBuffCycleResolveUnit(name);
	if (
		not unit
		or not UnitExists(unit)
		or not UnitIsConnected(unit)
		or (UnitIsDeadOrGhost and UnitIsDeadOrGhost(unit))
		or (UnitIsVisible and not UnitIsVisible(unit))
	) then
		return false;
	end
	if (CheckInteractDistance) then
		return CheckInteractDistance(unit, 1) and true or false;
	end
	if (UnitInRange) then
		return UnitInRange(unit) and true or false;
	end
	return true;
end

function UnBotBuffCycleBeginArrivalWait(resumeMissingOnly, reason)
	local now = GetTime();
	if not next(UnBotBuffCycle.registryInvites or {}) then
		local phase=UnBotBuffCycleCurrentPhase();
		for index=1,#((phase and phase.bots) or {}) do UnBotBuffCycle.MarkUnavailable(index); end
		if not next(UnBotBuffCycle.assignments or {}) then
			UnBotBuffCycle.stage="wait_cleanup"; UnBotBuffCycle.nextTime=now; UnBotBuffCycle.stageUntil=now; return;
		end
	end
	UnBotBuffCycle.stage = "arrival";
	UnBotBuffCycle.arrivalDeadline = now + 30;
	UnBotBuffCycle.arrivalLastMessageAt = 0;
	UnBotBuffCycle.arrivalReady = UnBotBuffCycle.arrivalReady or {};
	UnBotBuffCycle.arrivalResumeMissingOnly = resumeMissingOnly == true;
	UnBotBuffCycle.nextTime = now;
	UnBotSpecSummonMessage(
		reason or "Бафф-цикл: проверяю прибытие; до двух summon с интервалом 3 секунды."
	);
end

function UnBotBuffCycleReplaceAbsentCaster(assignmentIndex, name, now)
	UnBotBuffCycleArrivalBlock(name, true);
	UnBotBuffCycle.assignments[assignmentIndex] = nil;
	UnBotBuffCycle.assignedNames[name] = nil;
	UnBotBuffCycle.requestedByName[name] = nil;
	UnBotBuffCycle.registryInvites[name] = nil;
	UnBotBuffCycle.keptRegistryNames[name] = nil;
	UnBotBuffCycle.replacementMissingOnly = true;
	UnBotBuffCycle.replacementSetupOnly = nil;
	UnBotBuffCycle.summonIndex = assignmentIndex;
	UnBotBuffCycle.setupIndex = 1;
	UnBotBuffCycle.stageUntil = now + 10;
	UnBotBuffCycle.serverWaitDeadline = now + 180;
	UnBotBuffCycle.stage = "summon";
	UnBotBuffCycle.nextTime = now;
	UnBotSpecSummonMessage("Бафф-цикл: "..name.." не появился рядом; перехожу к следующему кандидату без повторного summon.");
	if (
		not (UnBotBuffCycle.originalMembers and UnBotBuffCycle.originalMembers[name])
		and not (UnBotBuffCycle.offlineMembers and UnBotBuffCycle.offlineMembers[name])
	) then
		UnBotBuffCycle.arrivalReplacementName = name;
		UnBotBuffCycle.stage = "arrival_cleanup";
		UnBotBuffCycle.cleanup[name] = {
			removeSent = false, nextTime = now, untilTime = now + 15,
			boundedArrival = true, attempts = 0,
		};
	end
end

function UnBotBuffCycleArrivalUpdate(now, pollOnly)
	local phase = UnBotBuffCycleCurrentPhase();
	local missingNames = {};
	for assignmentIndex = 1, #((phase and phase.bots) or {}), 1 do
		local name = UnBotBuffCycle.assignments[assignmentIndex];
		if (name and UnBotBuffCycleCasterReady(name)) then
			if (not UnBotBuffCycle.arrivalReady[name]) then
				UnBotBuffCycle.arrivalReady[name] = true;
				UnBotBuffCycleSendWhisper(name, "stay");
			end
		elseif (name) then
			if UnBotBuffCycle.arrivalReady[name] then
				-- A previously nearby caster can briefly move out of range.
				UnBotBuffCycle.arrivalReady[name] = nil;
				UnBotBuffCycle.arrivalAttempts[name] = math.max(1, UnBotBuffCycle.arrivalAttempts[name] or 0);
				UnBotBuffCycle.arrivalNextSummonAt[name] = now + 5;
			end
			table.insert(missingNames, name or tostring((phase.bots[assignmentIndex] or {}).label or assignmentIndex));
			if (name and now >= (UnBotBuffCycle.arrivalNextSummonAt[name] or 0)) then
				local attempts = tonumber(UnBotBuffCycle.arrivalAttempts[name]) or 0;
					if (attempts < 2) then
					UnBotBuffCycle.arrivalAttempts[name] = attempts + 1;
						UnBotBuffCycle.arrivalNextSummonAt[name] = now + 3;
					UnBotBuffCycleSendWhisper(name, "summon");
						UnBotSpecSummonMessage("Бафф-цикл: "..name.." — summon "..tostring(attempts+1).."/2; жду 3 секунды.");
				else
					UnBotBuffCycleReplaceAbsentCaster(assignmentIndex, name, now);
					return true;
				end
			end
		end
	end
	if (pollOnly) then
		return false;
	end
	if (#missingNames == 0) then
		UnBotSpecSummonMessage("Бафф-цикл: выбранные бафферы подтверждены рядом с игроком; начинаю команды баффов.");
		UnBotBuffCycle.stage = "reset";
		if (not UnBotBuffCycle.replacementSetupOnly) then
			UnBotBuffCycle.setupIndex = 1;
		end
		UnBotBuffCycle.arrivalDeadline = 0;
		UnBotBuffCycle.arrivalLastMessageAt = 0;
		UnBotBuffCycle.nextTime = UnBotBuffCycle.raidWaveMode and now or now + 0.3;
		return true;
	end
	if (
		(UnBotBuffCycle.arrivalLastMessageAt or 0) == 0
		or now - (UnBotBuffCycle.arrivalLastMessageAt or 0) >= 60
	) then
		UnBotBuffCycle.arrivalLastMessageAt = now;
		UnBotSpecSummonMessage(
			"Бафф-цикл: ожидаю появления рядом: "
			..table.concat(missingNames, ", ")
			..". После двух summon с интервалом 3 секунды без прибытия — следующий кандидат."
		);
	end
	UnBotBuffCycle.nextTime = now + (UnBotBuffCycle.raidWaveMode and 0.1 or 1);
	return false;
end

function UnBotBuffCycleMissingCastersNeedArrival(missingEntries)
	for _, missing in ipairs(missingEntries or {}) do
		if (missing.name and not UnBotBuffCycleCasterReady(missing.name)) then
			UnBotBuffCycleBeginArrivalWait(
				true,
				"Бафф-цикл: "..tostring(missing.name)
				.." перестал быть виден рядом; проверяю прибытие без повторной телепортации."
			);
			return true;
		end
	end
	return false;
end

local function UnBotBuffCycleMissingBuffs(requiredOnly)
	local missing = {};
	local phase = UnBotBuffCycleCurrentPhase();
	if (not phase) then
		return missing;
	end
	for i, bot in ipairs(phase.bots) do
		local name = UnBotBuffCycle.assignments[i];
		for _, buff in ipairs(bot.buffs or {}) do
			if (not requiredOnly or buff.required) then
				if (UnBotBuffCycle.mode == "raid") then
					if (name) then
						for _, targetName in ipairs(UnBotBuffCycleGroupAffectedNames(buff, true, name)) do
							table.insert(missing, {
								name = name,
								bot = bot,
								buff = buff,
								targetName = targetName,
							});
						end
					else
						for _, targetName in ipairs(UnBotBuffCycleGroupAffectedNames(buff, true, nil)) do
							table.insert(missing, {
								name = nil,
								bot = bot,
								buff = buff,
								targetName = targetName,
							});
						end
					end
				elseif (UnBotBuffCycleAssignedBuffMissing(buff, name)) then
					table.insert(missing, { name = name, bot = bot, buff = buff });
				end
			end
		end
	end
	return missing;
end

function UnBotBuffDiagnosticVerify(requiredMissing, allMissing)
	local diagnostic = UnBotSquadConfig and UnBotSquadConfig.lastBuffDiagnostic;
	if (type(diagnostic) ~= "table" or not diagnostic.active) then
		return;
	end
	local phase = UnBotBuffCycleCurrentPhase();
	local states = {};
	for assignmentIndex, bot in ipairs((phase and phase.bots) or {}) do
		local name = UnBotBuffCycle.assignments[assignmentIndex];
		for _, buff in ipairs(bot.buffs or {}) do
			local missing = UnBotBuffCycleAssignedBuffMissing(buff, name);
			local auraIndex, expirationTime = UnBotBuffCycleFindUnitBuff("player", buff);
			local remaining = auraIndex and expirationTime and expirationTime > 0
				and math.max(0, math.floor(expirationTime - GetTime())) or nil;
			table.insert(
				states,
				tostring(buff.label).."="..(missing and "MISSING" or "present")
				..(remaining and ("["..tostring(remaining).."s]") or "")
				.."<-"..tostring(name or "unassigned")
			);
		end
	end
	local missingDetails = {};
	for _, missing in ipairs(allMissing or {}) do
		table.insert(
			missingDetails,
			tostring(missing.buff and missing.buff.label or "?")
			.."<-"..tostring(missing.name or "unassigned")
			.."->"..tostring(missing.targetName or "group/player")
			..(missing.buff and missing.buff.required and "[required]" or "[optional]")
		);
	end
	UnBotBuffDiagnosticAdd(
		"verify",
		"phase="..tostring(UnBotBuffCycle.phaseIndex)
		.."; retryRound="..tostring(UnBotBuffCycle.retryRound or 0)
		.."; requiredMissing="..tostring(#(requiredMissing or {}))
		.."; allMissing="..tostring(#(allMissing or {}))
		.."; auras="..table.concat(states, "; ")
		.."; missingDetails="..(#missingDetails > 0 and table.concat(missingDetails, "; ") or "none")
	);
end

function UnBotBuffCycleProgressReset()
	UnBotBuffCycle.progressLastPercent = -1;
	UnBotBuffCycle.progressLastAt = 0;
	UnBotBuffCycle.progressLastStage = nil;
	UnBotBuffCycle.progressLastPhase = 0;
	UnBotBuffCycle.progressLastChatPercent = -20;
	UnBotBuffCycle.progressStopHintShown = false;
end

function UnBotBuffCycleProgressHide()
	UnBotBuffCycle.progressDisplayUntil = nil;
	if (UnBotBuffCycle.progressDisplayFrame) then
		UnBotBuffCycle.progressDisplayFrame:Hide();
	end
end

function UnBotBuffCycleProgressDisplay()
	if (UnBotBuffCycle.progressDisplayFrame) then
		return UnBotBuffCycle.progressDisplayFrame;
	end
	local frame = CreateFrame("Frame", "UnBotBuffProgressFrame", UIParent);
	frame:SetWidth(math.min(880, math.max(480, UIParent:GetWidth() - 80)));
	frame:SetHeight(76);
	frame:SetPoint("TOP", UIParent, "TOP", 0, -150);
	frame:SetFrameStrata("HIGH");
	frame:SetFrameLevel(20);
	frame:SetClampedToScreen(true);
	local background = frame:CreateTexture(nil, "BACKGROUND");
	background:SetAllPoints(frame);
	background:SetTexture(0, 0, 0, 0.58);
	local text = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge");
	text:SetPoint("TOPLEFT", frame, "TOPLEFT", 12, -10);
	text:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -12, 10);
	text:SetJustifyH("CENTER");
	text:SetJustifyV("MIDDLE");
	text:SetTextColor(1, 0.58, 0.12);
	text:SetShadowColor(0, 0, 0, 1);
	text:SetShadowOffset(1, -1);
	local fontFile = GameFontNormalLarge and GameFontNormalLarge:GetFont();
	if (fontFile) then
		text:SetFont(fontFile, 20, "OUTLINE");
	end
	frame.text = text;
	frame:SetScript("OnUpdate", function(self)
		if (
			UnBotBuffCycle.progressDisplayUntil
			and GetTime() >= UnBotBuffCycle.progressDisplayUntil
		) then
			UnBotBuffCycle.progressDisplayUntil = nil;
			self:Hide();
		end
	end);
	frame:Hide();
	UnBotBuffCycle.progressDisplayFrame = frame;
	return frame;
end

function UnBotBuffCycleProgressStageLabel(stage)
	if (stage == "summon") then
		return "ВЫЗОВ БАФЕРОВ";
	elseif (stage == "arrival") then
		return "ОЖИДАНИЕ БАФЕРОВ РЯДОМ";
	elseif (stage == "reset") then
		return "ПОДГОТОВКА БОТОВ";
	elseif (stage == "cast") then
		return "НАЛОЖЕНИЕ БАФФОВ";
	elseif (stage == "verify") then
		return "ПРОВЕРКА АУР";
	elseif (stage == "wait_cleanup") then
		return "УДАЛЕНИЕ ВРЕМЕННЫХ БАФЕРОВ";
	end
	return "ПОДГОТОВКА";
end

function UnBotBuffCycleProgressPhaseLabel(label)
	label = tostring(label or "");
	if (string.find(label, "paladin blessings", 1, true)) then
		return "благословения паладинов";
	elseif (string.find(label, "short combat buffs", 1, true)) then
		return "короткие боевые баффы";
	elseif (string.find(label, "persistent buffs", 1, true)) then
		return "постоянные баффы";
	elseif (string.find(label, "long buffs", 1, true)) then
		return "долгие баффы";
	end
	return label ~= "" and label or "баффы";
end

function UnBotBuffCycleProgressBuffLabel(label)
	local labels = {
		["Fortitude"] = "Стойкость",
		["Spirit"] = "Дух",
		["Shadow Protection"] = "Защита от тёмной магии",
		["Fear Ward"] = "Защита от страха",
		["Arcane Brilliance"] = "Чародейская гениальность",
		["Focus Magic"] = "Сосредоточение магии",
		["Gift of the Wild"] = "Дар дикой природы",
		["Thorns"] = "Шипы",
		["Detect Invisibility"] = "Обнаружение невидимости",
		["Unending Breath"] = "Подводное дыхание",
		["Soulstone"] = "Камень души",
		["Might"] = "Могущество",
		["Greater Blessing of Sanctuary (30 min)"] = "Святилище",
		["Wisdom"] = "Мудрость",
		["Kings"] = "Короли",
		["Horn of Winter"] = "Зимний горн",
		["Commanding Shout"] = "Командирский крик",
	};
	return labels[tostring(label or "")] or tostring(label or "?");
end

function UnBotBuffProfileSetButtonSelected(button, selected)
	if (selected) then
		button:Disable();
	else
		button:Enable();
	end
end

function UnBotBuffProfileSaveRefreshBox(box)
	if (not box or not box.buffKey) then
		return;
	end
	local profiles = UnBotBuffProfileEnsure();
	local profileName = UnBotBuffProfileUI.profile == "solo" and "solo" or "raid";
	local value = tonumber(box:GetText());
	if (value == nil) then
		value = UnBotBuffProfileDefaultMinutes(box.buffKey);
	end
	value = math.max(0, math.min(1440, math.floor(value + 0.5)));
	profiles[profileName].refreshMinutes[box.buffKey] = value;
	box:SetText(tostring(value));
	box:ClearFocus();
end

function UnBotBuffProfileSaveRefreshInputs()
	for _, box in ipairs(UnBotBuffProfileUI.refreshBoxes or {}) do
		if (box:HasFocus()) then
			UnBotBuffProfileSaveRefreshBox(box);
		end
	end
end

function UnBotBuffProfileCreateRefreshBox(parent)
	local box = CreateFrame("EditBox", nil, parent);
	box:SetBackdrop({
		bgFile = [[Interface\Tooltips\UI-Tooltip-Background]],
		edgeFile = [[Interface\Tooltips\UI-Tooltip-Border]],
		tile = true,
		tileSize = 8,
		edgeSize = 8,
		insets = { left = 2, right = 2, top = 2, bottom = 2 },
	});
	box:SetBackdropColor(0.02, 0.02, 0.02, 0.94);
	box:SetBackdropBorderColor(0.45, 0.45, 0.45, 1);
	box:SetTextInsets(5, 5, 0, 0);
	box:SetFontObject(GameFontHighlight);
	box:SetJustifyH("CENTER");
	return box;
end

function UnBotBuffProfileRefresh()
	local ui = UnBotBuffProfileUI;
	if (not ui.frame) then
		return;
	end
	local profiles = UnBotBuffProfileEnsure();
	local profileName = ui.profile == "solo" and "solo" or "raid";
	local profile = profiles[profileName];
	ui.profileLabel:SetText(
		profileName == "solo"
			and "Профиль: соло (кнопка Fast Solo)"
			or "Профиль: группа / рейд (кнопка «Добаффать»)"
	);
	UnBotBuffProfileSetButtonSelected(ui.soloButton, profileName == "solo");
	UnBotBuffProfileSetButtonSelected(ui.raidButton, profileName == "raid");
	UnBotBuffProfileSetButtonSelected(ui.soulstoneOffButton, profile.soulstoneTarget == "off");
	UnBotBuffProfileSetButtonSelected(ui.soulstonePlayerButton, profile.soulstoneTarget == "player");
	UnBotBuffProfileSetButtonSelected(ui.soulstoneSelfButton, profile.soulstoneTarget == "self");
	if (ui.diagnosticCheck) then
		ui.diagnosticCheck:SetChecked(UnBotSquadConfig.buffDiagnosticEnabled == true);
	end
	for _, check in ipairs(ui.checks) do
		check:SetChecked(profile[check.buffKey] ~= false);
	end
	for _, box in ipairs(ui.refreshBoxes or {}) do
		box:SetText(tostring(UnBotBuffProfileRefreshMinutes(profileName, box.buffKey)));
	end
end

function UnBotBuffProfileSelect(profileName)
	UnBotBuffProfileSaveRefreshInputs();
	UnBotBuffProfileUI.profile = profileName == "solo" and "solo" or "raid";
	UnBotBuffProfileRefresh();
end

function UnBotBuffProfileSetSoulstone(targetName)
	local profiles = UnBotBuffProfileEnsure();
	local profileName = UnBotBuffProfileUI.profile == "solo" and "solo" or "raid";
	if (targetName ~= "player" and targetName ~= "self") then
		targetName = "off";
	end
	profiles[profileName].soulstoneTarget = targetName;
	UnBotBuffProfileRefresh();
end

function UnBotBuffProfileSetPrepareOfflineReserve(enabled)
	local profiles = UnBotBuffProfileEnsure();
	local profileName = UnBotBuffProfileUI.profile == "solo" and "solo" or "raid";
	profiles[profileName].prepareOfflineReserve = false;
	UnBotBuffProfileRefresh();
end

