function UnBotBuffProfileToggle()
	UnBotBuffProfileCreateFrame();
	if (UnBotBuffProfileUI.frame:IsShown()) then
		UnBotBuffProfileUI.frame:Hide();
	else
		UnBotBuffProfileRefresh();
		UnBotBuffProfileUI.frame:Show();
	end
end

function UnBotBuffCycleResetReagentFailures()
	UnBotBuffCycle.skippedBuffs = {};
	UnBotBuffCycle.sentCommands = {};
	UnBotBuffCycle.nextCastByName = {};
	UnBotBuffCycle.verifyAfter = 0;
	UnBotBuffCycle.lastCastByName = {};
	UnBotBuffCycle.castFailures = {};
	UnBotBuffCycle.reagentFailures = {};
	UnBotBuffCycle.reagentFailureLabels = {};
	UnBotBuffCycle.reagentFailureOrder = {};
end

function UnBotBuffCycleReagentFailureKey(name, buff, phaseIndex)
	return tostring(phaseIndex or UnBotBuffCycle.phaseIndex or 0).."\031"
		..tostring(name or "?").."\031"..tostring(buff and buff.label or "?");
end

function UnBotBuffCycleIsReagentBlocked(name, buff)
	local key = UnBotBuffCycleReagentFailureKey(name, buff);
	return (UnBotBuffCycle.reagentFailures and UnBotBuffCycle.reagentFailures[key])
		or (UnBotBuffCycle.castFailures and UnBotBuffCycle.castFailures[key]) or false;
end

function UnBotBuffCycleWhisperReportsMissingReagent(message)
	local text = UnBotSpecSummonNormalize(message);
	return string.find(text, "no items", 1, true)
		or string.find(text, "no item", 1, true)
		or string.find(text, "not enough item", 1, true)
		or string.find(text, "required item", 1, true)
		or string.find(text, "no reagent", 1, true)
		or string.find(text, "not enough reagent", 1, true)
		or string.find(text, "missing reagent", 1, true)
		or string.find(text, "requires reagent", 1, true)
		or string.find(text, "required reagent", 1, true)
		or string.find(text, "нет реагент", 1, true)
		or string.find(text, "не хватает реагент", 1, true)
		or string.find(text, "недостаточно реагент", 1, true)
		or string.find(text, "требуется реагент", 1, true)
		or string.find(text, "нет необходимого предмет", 1, true);
end

function UnBotBuffCycleWhisperReportsCastFailure(message)
	local text = UnBotSpecSummonNormalize(message);
	return string.find(text, "cannot cast", 1, true)
		or string.find(text, "can't cast", 1, true)
		or string.find(text, "cant cast", 1, true)
		or string.find(text, "unable to cast", 1, true)
		or string.find(text, "unknown spell", 1, true)
		or string.find(text, "не могу наложить", 1, true)
		or string.find(text, "не могу применить", 1, true)
		or string.find(text, "невозможно применить", 1, true)
		or string.find(text, "не удается применить", 1, true)
		or string.find(text, "не удаётся применить", 1, true);
end

-- Server cast refusals also arrive through CHAT_MSG_SYSTEM, not only whispers.
-- Block only the identified caster/effect in this phase, never the roster.
function UnBotBuffCycle.RecordCastRefusal(message, sender)
	if (not UnBotBuffCycle.active or not sender
		or not UnBotBuffCycleWhisperReportsCastFailure(message)) then return false; end
	local recent = UnBotBuffCycle.lastCastByName and UnBotBuffCycle.lastCastByName[sender];
	if (not recent or not recent.buff or recent.phaseIndex ~= UnBotBuffCycle.phaseIndex
		or GetTime() - (tonumber(recent.at) or 0) > 12) then return false; end
	local spellID = tonumber(tostring(message):match("|Hspell:(%d+)"));
	if (spellID) then
		local matches = false;
		for _, key in ipairs({"ids", "lowLevelIds"}) do
			for _, id in ipairs(recent.buff[key] or {}) do
				if (id == spellID) then matches = true; end
			end
		end
		if (not matches) then return false; end
	elseif (GetTime() - (tonumber(recent.at) or 0) > 3) then
		return false;
	end
	local key = recent.failureKey or UnBotBuffCycleReagentFailureKey(sender, recent.buff);
	UnBotBuffCycle.castFailures = UnBotBuffCycle.castFailures or {};
	if (not UnBotBuffCycle.castFailures[key]) then
		UnBotBuffCycle.castFailures[key] = true;
		UnBotSpecSummonMessage("Бафф-цикл: "..sender.." — сервер отказал в «"
			..UnBotBuffCycleProgressBuffLabel(recent.buff.label)
			.."». Повторы этого эффекта от данного бота отключены до конца этапа; состав сохранён.");
	end
	return true;
end

function UnBotBuffDiagnosticRecordCastFailure(message, sender)
	local diagnostic = UnBotSquadConfig and UnBotSquadConfig.lastBuffDiagnostic;
	if (
		type(diagnostic) ~= "table"
		or not diagnostic.active
		or not sender
		or not UnBotBuffCycleWhisperReportsCastFailure(message)
	) then
		return;
	end
	local recent = UnBotBuffCycle.lastCastByName[sender];
	local context = "no recent cast context";
	if (recent) then
		context = "buff="..tostring(recent.buff and recent.buff.label or "?")
			.."; target="..tostring(recent.targetName or "group/player")
			.."; phase="..tostring(recent.phaseIndex or UnBotBuffCycle.phaseIndex)
			.."; age="..tostring(math.floor(math.max(0, GetTime() - (tonumber(recent.at) or GetTime())) * 100 + 0.5) / 100).."s";
	end
	UnBotBuffDiagnosticAdd(
		"cast_failure",
		tostring(sender)..": "..tostring(message or "").."; "..context
	);
end

function UnBotBuffCycleRecordReagentFailure(message, sender)
	if (
		not UnBotBuffCycle.active
		or not sender
		or not UnBotBuffCycleWhisperReportsMissingReagent(message)
	) then
		return false;
	end
	local recent = UnBotBuffCycle.lastCastByName[sender];
	if (
		recent
		and GetTime() - (tonumber(recent.at) or 0) > 12
	) then
		recent = nil;
	end
	if (not recent) then
		local phase = UnBotBuffCycleCurrentPhase();
		for assignmentIndex, name in pairs(UnBotBuffCycle.assignments or {}) do
			local bot = phase and phase.bots and phase.bots[assignmentIndex];
			if (name == sender and bot and #(bot.buffs or {}) == 1) then
				recent = {
					buff = bot.buffs[1],
					phaseIndex = UnBotBuffCycle.phaseIndex,
				};
				break
			end
		end
	end
	if (not recent or not recent.buff) then
		return false;
	end
	local key = recent.failureKey or UnBotBuffCycleReagentFailureKey(
		sender,
		recent.buff,
		recent.phaseIndex
	);
	local label = UnBotBuffCycleProgressBuffLabel(recent.buff.label);
	local isNewLabel = not UnBotBuffCycle.reagentFailureLabels[label];
	UnBotBuffCycle.reagentFailures[key] = true;
	if (isNewLabel) then
		UnBotBuffCycle.reagentFailureLabels[label] = true;
		table.insert(UnBotBuffCycle.reagentFailureOrder, label);
		UnBotBuffCycleProgressRaidNotice(
			(UnBotBuffCycle.mode == "raid" and "БАФЫ РЕЙДА" or "FAST SOLO")
			.." - НЕТ РЕАГЕНТОВ\nНЕ НАЛОЖЕНО: "..label
			.." - ПОДРОБНОСТИ В ЧАТЕ",
			true,
			7
		);
	end
	UnBotSpecSummonMessage(
		"|cffff6060"..(UnBotBuffCycle.mode == "raid" and "Бафы рейда" or "Fast Solo")
		..": "..tostring(sender).." не наложил «"..label
		.."» — закончились реагенты. Требуется закупка классовых реагентов; "
		.."откройте торговца и в Центре управления ботами запустите точный закуп.|r"
	);
	return true;
end

function UnBotBuffCycleQuarantineForHour(name, reason)
	return UnBotRegistrySetHourlyQuarantine(name, reason, "Бафф-карантин");
end

function UnBotBuffCycleQuarantineMissingCasters(missingEntries)
	local names = {};
	for _, missing in ipairs(missingEntries or {}) do
		if (
			missing.name
			and missing.buff
			and UnBotBuffCycleCasterReady(missing.name)
			and not UnBotBuffCycleIsReagentBlocked(missing.name, missing.buff)
		) then
			names[missing.name] = true;
		end
	end
	for name in pairs(names) do
		UnBotBuffCycleQuarantineForHour(
			name,
			"обязательный бафф не подтверждён после всех повторов"
		);
	end
end

function UnBotBuffCycleTryReplaceSanctuaryCaster(missingEntries)
	if (UnBotBuffCycle.mode ~= "solo") then
		return false;
	end
	local phase = UnBotBuffCycleCurrentPhase();
	local assignmentIndex;
	for index, bot in ipairs((phase and phase.bots) or {}) do
		if (bot.label == "Sanctuary Paladin") then
			for _, missing in ipairs(missingEntries or {}) do
				if (
					missing.name == UnBotBuffCycle.assignments[index]
					and missing.buff
					and missing.buff.label == "Greater Blessing of Sanctuary (30 min)"
				) then
					assignmentIndex = index;
					break
				end
			end
		end
		if (assignmentIndex) then
			break
		end
	end
	if (
		not assignmentIndex
		or not UnBotBuffCycleCanRetryAssignment(assignmentIndex)
	) then
		return false;
	end
	local name = UnBotBuffCycle.assignments[assignmentIndex];
	UnBotBuffCycleQuarantineForHour(
		name,
		"не смог наложить ни великое, ни обычное Благословение Святилища"
	);
	UnBotBuffDiagnosticAdd(
		"sanctuary-replace",
		"name="..tostring(name)
		.."; summonAttempts="..tostring(UnBotBuffCycle.registryAttempts[assignmentIndex] or 0)
		.."/"..tostring(UnBotBuffCycleRegistryAttemptLimit(assignmentIndex))
	);
	UnBotBuffCycle.assignments[assignmentIndex] = nil;
	UnBotBuffCycle.assignedNames[name] = nil;
	UnBotBuffCycle.requestedByName[name] = nil;
	UnBotBuffCycle.registryInvites[name] = nil;
	UnBotBuffCycle.keptRegistryNames[name] = nil;
	if (UnBotSpecSummonIsInGroup(name)) then
		UnBotSpecSummonUninvite(name);
	end
	UnBotBuffCycle.cleanup[name] = {
		removeSent = false,
		nextTime = GetTime() + 0.5,
		untilTime = GetTime() + 30,
	};
	UnBotBuffCycle.retryRound = 0;
	UnBotBuffCycle.summonIndex = assignmentIndex;
	UnBotBuffCycle.setupIndex = assignmentIndex;
	UnBotBuffCycle.replacementSetupOnly = true;
	UnBotBuffCycle.replacementMissingOnly = true;
	UnBotBuffCycle.serverWaitDeadline = GetTime() + 180;
	UnBotBuffCycle.serverWaitLastMessageAt = 0;
	UnBotBuffCycle.stage = "summon";
	UnBotBuffCycle.stageUntil = GetTime() + 10;
	UnBotBuffCycle.nextTime = GetTime() + 1.2;
	UnBotSpecSummonMessage(
		"Fast Solo: "..tostring(name)
		.." не наложил Святилище двумя командами; вызываю следующего Protection Paladin (до "
		..tostring(UnBotBuffCycleRegistryAttemptLimit(assignmentIndex)).." кандидатов)."
	);
	return true;
end

function UnBotBuffCycleProgressBuffStatus()
	local ordered = {};
	local seen = {};
	local missingByLabel = {};
	for _, phase in ipairs(UnBotBuffCycle.runtimePhases or UnBotBuffCyclePhases) do
		for botIndex, bot in ipairs(phase.bots or {}) do
			local sourceName = phase == UnBotBuffCycleCurrentPhase()
				and UnBotBuffCycle.assignments[botIndex] or nil;
			for _, buff in ipairs(bot.buffs or {}) do
				local label = UnBotBuffCycleProgressBuffLabel(buff.label);
				if (not seen[label]) then
					seen[label] = true;
					table.insert(ordered, label);
				end
				if (UnBotBuffCycle.mode == "raid") then
					if (
						(buff.soulstone and UnBotBuffCycleEffectiveGroupTarget(buff) == "self" and not sourceName)
						or #UnBotBuffCycleGroupAffectedNames(buff, true, sourceName) > 0
					) then
						missingByLabel[label] = true;
					end
				elseif (UnBotBuffCycleAssignedBuffMissing(buff, sourceName)) then
					missingByLabel[label] = true;
				end
			end
		end
	end
	local applied = {};
	local missing = {};
	for _, label in ipairs(ordered) do
		if (missingByLabel[label]) then
			table.insert(missing, label);
		else
			table.insert(applied, label);
		end
	end
	return applied, missing;
end

function UnBotBuffCycleProgressShortList(values, limit)
	limit = math.max(1, tonumber(limit) or 5);
	local shown = {};
	for index = 1, math.min(#values, limit), 1 do
		table.insert(shown, values[index]);
	end
	local result = #shown > 0 and table.concat(shown, ", ") or "нет";
	if (#values > limit) then
		result = result.." и ещё "..tostring(#values - limit);
	end
	return result;
end

function UnBotBuffCycleProgressValue()
	local applied, missing = UnBotBuffCycleProgressBuffStatus();
	local total = #applied + #missing;
	if (total <= 0) then
		return 0;
	end
	return math.max(0, math.min(100, math.floor((#applied / total) * 100 + 0.5)));
end

function UnBotBuffCycleProgressRaidNotice(text, sound, hideAfter)
	local frame = UnBotBuffCycleProgressDisplay();
	frame.text:SetText(tostring(text or ""));
	frame:Show();
	UnBotBuffCycle.progressDisplayUntil = hideAfter
		and (GetTime() + math.max(1, tonumber(hideAfter) or 1)) or nil;
	if (sound and PlaySound) then
		PlaySound("RaidWarning");
	end
end

function UnBotBuffCycleProgressNotice(force, finished)
	if (not UnBotBuffCycle.active and not finished) then
		return false;
	end
	local now = GetTime();
	local applied, missing = UnBotBuffCycleProgressBuffStatus();
	local total = #applied + #missing;
	local percent = UnBotBuffCycleProgressValue();
	if (finished and #missing == 0) then
		percent = 100;
	end
	if (not finished) then
		percent = math.max(
			percent,
			math.max(0, tonumber(UnBotBuffCycle.progressLastPercent) or 0)
		);
	end
	local phaseChanged = UnBotBuffCycle.progressLastPhase ~= UnBotBuffCycle.phaseIndex;
	local stageChanged = UnBotBuffCycle.progressLastStage ~= UnBotBuffCycle.stage;
	local percentChanged = percent >= (tonumber(UnBotBuffCycle.progressLastPercent) or -1) + 10;
	if (
		not force
		and not phaseChanged
		and not (stageChanged and now - (UnBotBuffCycle.progressLastAt or 0) >= 2.5)
		and not (percentChanged and now - (UnBotBuffCycle.progressLastAt or 0) >= 4)
	) then
		return false;
	end
	local phase = UnBotBuffCycleCurrentPhase();
	local modeLabel = UnBotBuffCycle.mode == "raid" and "БАФЫ РЕЙДА" or "FAST SOLO";
	local phaseLabel = finished and "готово"
		or UnBotBuffCycleProgressPhaseLabel(phase and phase.label);
	local stageLabel = finished and "ЗАВЕРШЕНО"
		or UnBotBuffCycleProgressStageLabel(UnBotBuffCycle.stage);
	local screenText = modeLabel.."  -  "..tostring(percent).."%  -  "..stageLabel;
	local reagentMissing = UnBotBuffCycle.reagentFailureOrder or {};
	if (finished and #reagentMissing > 0) then
		screenText = modeLabel.."  -  ЗАВЕРШЕНО  -  "
			..tostring(#applied).."/"..tostring(total).." ПОДТВЕРЖДЕНО"
			.."\nНЕ ПОДТВЕРЖДЕНО: "..tostring(#missing)
			.."  -  НЕТ РЕАГЕНТОВ: "..tostring(#reagentMissing);
	elseif (finished and #missing > 0) then
		screenText = modeLabel.."  -  ЗАВЕРШЕНО  -  "
			..tostring(#applied).."/"..tostring(total).." ПОДТВЕРЖДЕНО"
			.."\nНЕ ПОДТВЕРЖДЕНО: "..tostring(#missing);
	elseif (finished) then
		screenText = modeLabel.."  -  100%  -  ВСЕ "
			..tostring(total).." ДОСТУПНЫЕ АУРЫ ПОДТВЕРЖДЕНЫ";
	elseif (#missing == 0) then
		screenText = screenText.."\nВСЕ ДОСТУПНЫЕ АУРЫ ПОДТВЕРЖДЕНЫ";
	else
		screenText = screenText.."\nОСТАЛОСЬ ПОДТВЕРДИТЬ: "..tostring(#missing);
	end
	if (finished and #(UnBotBuffCycle.levelSkippedOrder or {}) > 0) then
		screenText = screenText.."  -  НЕДОСТУПНО НА УРОВНЕ "
			..tostring(UnBotBuffCyclePlayerLevel())..": "
			..tostring(#UnBotBuffCycle.levelSkippedOrder);
	end
	if (not UnBotBuffCycle.progressStopHintShown and not finished) then
		UnBotBuffCycle.progressStopHintShown = true;
		UnBotSpecSummonMessage(
			"|cffffff00Бафф-цикл обычно занимает около минуты; при задержке сервера ожидание бафферов может занять до трёх минут. Остановить в любой момент: /ubstopbuffs; повторный клик той же кнопки также останавливает цикл.|r"
		);
	end
	UnBotBuffCycleProgressRaidNotice(
		screenText,
		force or phaseChanged or finished,
		finished and 7 or nil
	);
	if (
		force
		or finished
		or phaseChanged
		or percent >= (tonumber(UnBotBuffCycle.progressLastChatPercent) or -20) + 20
	) then
		UnBotSpecSummonMessage(
			modeLabel.." "..tostring(percent).."%: "..phaseLabel.." — "..stageLabel
			..". Подтверждены ("..tostring(#applied).."/"..tostring(total)
			.." доступных): "
			..UnBotBuffCycleProgressShortList(applied, 7).."."
		);
		UnBotSpecSummonMessage(
			"Не подтверждены ("..tostring(#missing).."): "
			..UnBotBuffCycleProgressShortList(missing, 7).."."
		);
		if (finished and #(UnBotBuffCycle.levelSkippedOrder or {}) > 0) then
			UnBotSpecSummonMessage(
				"Недоступны на уровне "..tostring(UnBotBuffCyclePlayerLevel())
				.." ("..tostring(#UnBotBuffCycle.levelSkippedOrder).."): "
				..table.concat(UnBotBuffCycle.levelSkippedOrder, ", ").."."
			);
		end
		if (finished and #reagentMissing > 0) then
			UnBotSpecSummonMessage(
				"|cffff6060Не наложены из-за отсутствия реагентов ("
				..tostring(#reagentMissing).."): "
				..table.concat(reagentMissing, ", ")
				..". Требуется закупка классовых реагентов.|r"
			);
		end
		UnBotBuffCycle.progressLastChatPercent = percent;
	end
	UnBotBuffCycle.progressLastPercent = percent;
	UnBotBuffCycle.progressLastAt = now;
	UnBotBuffCycle.progressLastStage = UnBotBuffCycle.stage;
	UnBotBuffCycle.progressLastPhase = UnBotBuffCycle.phaseIndex;
	return true;
end

local function UnBotBuffCycleBuffCommand(buff)
	if (
		buff.lowLevelCommand
		and UnBotBuffCyclePlayerLevel() < (tonumber(buff.groupMinLevel) or 1)
	) then
		return buff.lowLevelCommand;
	end
	local commands = buff.commands;
	if (commands and #commands > 0) then
		if (UnBotBuffCycle.mode == "raid") then
			return commands[1];
		end
		local commandIndex = math.min((UnBotBuffCycle.retryRound or 0) + 1, #commands);
		return commands[commandIndex];
	end
	return buff.command;
end

local function UnBotBuffCycleBuildCommandQueue(missingOnly)
	local phase = UnBotBuffCycleCurrentPhase();
	local queue = {};
	local perBotQueues = {};
	local maxCommands = 0;
	if (not phase) then
		return queue;
	end
	for i, bot in ipairs(phase.bots) do
		local botQueue = {};
		perBotQueues[i] = botQueue;
		local name = UnBotBuffCycle.assignments[i];
		if (name) then
			local botHasMissing = false;
			if (UnBotBuffCycle.mode == "raid") then
				for _, buff in ipairs(bot.buffs or {}) do
					local targets = UnBotBuffCycleGroupCommandTargets(buff, missingOnly, name);
					if (#targets > 0) then
						botHasMissing = true;
					end
				end
			else
				for _, buff in ipairs(bot.buffs or {}) do
					if (not missingOnly or UnBotBuffCycleAssignedBuffMissing(buff, name)) then
						botHasMissing = true;
					end
				end
			end
			if (botHasMissing) then
				for _, command in ipairs(bot.preCommands or {}) do
					table.insert(botQueue, { name = name, command = command });
				end
			end
			for _, buff in ipairs(bot.buffs or {}) do
				if (UnBotBuffCycle.mode == "raid") then
					local command = UnBotBuffCycleBuffCommand(buff);
					for _, targetName in ipairs(UnBotBuffCycleGroupCommandTargets(buff, missingOnly, name)) do
						if (not UnBotBuffCycleIsReagentBlocked(name, buff)) then
							table.insert(botQueue, {
								name = name,
								command = string.gsub(command or "", "{player}", targetName),
								buff = buff,
								targetName = targetName,
							});
						end
					end
				elseif (
					(not missingOnly or UnBotBuffCycleAssignedBuffMissing(buff, name))
					and not UnBotBuffCycleIsReagentBlocked(name, buff)
				) then
					local command = UnBotBuffCycleBuffCommand(buff);
					if (buff.soulstone and UnBotBuffProfileSoulstoneTarget(UnBotBuffCycle.mode) == "self") then
						command = string.gsub(command or "", "{player}", name);
					end
					table.insert(botQueue, { name = name, command = command, buff = buff });
				end
			end
			maxCommands = math.max(maxCommands, #botQueue);
		end
	end

	-- Round-robin keeps global chat traffic fast while giving each individual bot
	-- more than one GCD before its next spell command.
	for commandNumber = 1, maxCommands, 1 do
		for botNumber = 1, #phase.bots, 1 do
			local entry = perBotQueues[botNumber] and perBotQueues[botNumber][commandNumber];
			if (entry) then
				table.insert(queue, entry);
			end
		end
	end
	return queue;
end

local function UnBotBuffCycleStartCasting(missingOnly)
	if UnBotBuffCycle.stage == "verify" then UnBotBuffCycle.sentCommands = {}; end
	UnBotBuffCycle.commandQueue = UnBotBuffCycleBuildCommandQueue(missingOnly);
	UnBotBuffDiagnosticAdd(
		"queue",
		"phase="..tostring(UnBotBuffCycle.phaseIndex)
		.."; missingOnly="..tostring(missingOnly == true)
		.."; commands="..tostring(#UnBotBuffCycle.commandQueue)
	);
	UnBotBuffCycle.commandIndex = 1;
	UnBotBuffCycle.stage = "cast";
	UnBotBuffCycle.nextTime = GetTime();
end

-- Keep ordering/GCD per caster; a slow caster never stalls another bot.
function UnBotBuffCycle.CommandKey(entry)
	return tostring(entry.name).."\031"..tostring(entry.command).."\031"..tostring(entry.targetName or "");
end

function UnBotBuffCycle.CastTiming(entry)
	local spell=tostring(entry.command or ""):match("^cast%s+(.+)%s+on%s+.+$")
		or tostring(entry.command or ""):match("^cast%s+(.+)$");
	local ms=GetSpellInfo and spell and select(7,GetSpellInfo(tonumber(spell) or spell));
	-- Unknown cross-class spell data: conservative three-second cast window.
	local seconds=type(ms)=="number" and math.max(0,ms/1000) or 3;
	return math.max(1.6,seconds+0.2),seconds;
end

function UnBotBuffCycle.CastReady(now, preparing)
	local state=UnBotBuffCycle;
	local queue=preparing and UnBotBuffCycleBuildCommandQueue(state.arrivalResumeMissingOnly==true)
		or state.commandQueue or {};
	state.sentCommands=state.sentCommands or {};
	state.lastCastByName=state.lastCastByName or {};
	state.nextCastByName=state.nextCastByName or {};
	local waitingByName={}; local pendingReady=false; local missing=false;
	for index,entry in ipairs(queue) do
		local key=UnBotBuffCycle.CommandKey(entry);
		if not state.sentCommands[key] then
			if not waitingByName[entry.name] then
				waitingByName[entry.name]=true;
				if UnBotBuffCycleCasterReady(entry.name) then
					pendingReady=true;
					if now >= (state.nextCastByName[entry.name] or 0) then
						local send=not entry.buff or not UnBotBuffCycleIsReagentBlocked(entry.name,entry.buff);
						send=send and (not entry.buff or UnBotBuffCyclePrepareSoloRefresh(entry.buff));
						if send then
							local delay,castSeconds=UnBotBuffCycle.CastTiming(entry);
							if entry.buff then state.lastCastByName[entry.name]={buff=entry.buff,targetName=entry.targetName,
								phaseIndex=state.phaseIndex,failureKey=UnBotBuffCycleReagentFailureKey(entry.name,entry.buff),at=now}; end
							UnBotBuffCycleSendWhisper(entry.name,entry.command);
							state.nextCastByName[entry.name]=now+delay;
							state.verifyAfter=math.max(state.verifyAfter or 0,now+castSeconds);
						end
						state.sentCommands[key]=true;
					end
				else missing=true; end
			end
		end
	end
	if preparing then return; end
	state.commandIndex=1;
	while queue[state.commandIndex] and state.sentCommands[UnBotBuffCycle.CommandKey(queue[state.commandIndex])] do
		state.commandIndex=state.commandIndex+1;
	end
	if not queue[state.commandIndex] then
		state.stage="verify"; state.nextTime=math.max(now,state.verifyAfter or 0)+2;
	elseif missing and not pendingReady then
		UnBotBuffCycleBeginArrivalWait(true,"Бафф-цикл: оставшийся баффер не готов; проверяю прибытие.");
	else state.nextTime=now+0.05; end
end

function UnBotBuffCycleReportPlayerActions()
	if (UnBotBuffCycle.mode ~= "raid") then
		return;
	end
	local phase = UnBotBuffCycleCurrentPhase();
	if (not phase) then
		return;
	end
	for assignmentIndex, bot in ipairs(phase.bots or {}) do
		if (not UnBotBuffCycle.assignments[assignmentIndex]) then
			for _, buff in ipairs(bot.buffs or {}) do
				if (buff.required) then
					local reportKey = tostring(UnBotBuffCycle.phaseIndex)..":"
						..tostring(assignmentIndex)..":"..tostring(buff.label);
					local targets = UnBotBuffCycleGroupCommandTargets(buff, true, nil);
					if (
						#targets > 0
						and not UnBotBuffCycle.playerActionReported[reportKey]
					) then
						UnBotBuffCycle.playerActionReported[reportKey] = true;
						local command = UnBotBuffCycleBuffCommand(buff) or "";
						local spellName = string.match(command, "^cast%s+(.+)%s+on%s+")
							or string.match(command, "^cast%s+(.+)$")
							or tostring(buff.label);
						local playerClass = UnBotBuffCycleTargetClass(UnitName("player"));
						local prefix = playerClass == bot.className
							and "|cffffff00Игроку"
							or ("|cffffff00Нужен "..tostring(bot.className));
						local targetHint = table.concat(targets, ", ");
						if (buff.groupTarget == "class") then
							targetHint = targetHint.." (по одной цели каждого класса)";
						elseif (buff.groupTarget == "raid") then
							targetHint = targetHint.." (групповой баф накроет рейд)";
						end
						UnBotSpecSummonMessage(
							prefix..": наложить "..spellName.." на "..targetHint
							..". Автоматического бафера в текущем составе нет.|r"
						);
					end
				end
			end
		end
	end
end

local function UnBotBuffCycleBeginCleanup()
	local phase = UnBotBuffCycleCurrentPhase();
	for assignmentIndex, name in pairs(UnBotBuffCycle.assignments) do
		local bot = phase and phase.bots[assignmentIndex];
		if (UnBotBuffCycle.originalMembers and UnBotBuffCycle.originalMembers[name]) then
			UnBotSpecSummonMessage("Баф рейда: оставляем исходного участника "..name.." в группе.");
		elseif (bot and bot.keepInGroup) then
			UnBotBuffCycle.keptRegistryNames[name] = true;
			UnBotSpecSummonMessage(
				"Buff registry: keeping "..name.." in group so "..bot.label
				.." can maintain its level-appropriate buffs."
			);
		else
			UnBotSpecSummonUninvite(name);
			UnBotBuffCycle.cleanup[name] = {
				removeSent = false,
				nextTime = GetTime() + 0.5,
				untilTime = GetTime() + 30,
			};
		end
	end
	UnBotBuffCycle.stage = "wait_cleanup";
	UnBotBuffCycle.nextTime = GetTime() + 0.5;
	UnBotBuffCycle.stageUntil = GetTime() + 15;
end

local function UnBotBuffCyclePhaseMembersGone()
	local phase = UnBotBuffCycleCurrentPhase();
	for assignmentIndex, name in pairs(UnBotBuffCycle.assignments) do
		local bot = phase and phase.bots[assignmentIndex];
		if (
			not (UnBotBuffCycle.originalMembers and UnBotBuffCycle.originalMembers[name])
			and not (bot and bot.keepInGroup)
			and UnBotSpecSummonIsInGroup(name)
		) then
			return false;
		end
	end
	return true;
end

local function UnBotBuffCycleStartPhase()
	local phase = UnBotBuffCycleCurrentPhase();
	if (not phase) then
		local restoreReserve =
			(UnBotBuffCycle.mode == "raid" or UnBotBuffCycle.mode == "solo")
			and UnBotBuffProfilePrepareOfflineReserve(UnBotBuffCycle.mode)
			and not (
				UnBotBuffCycle.mode == "solo"
				and UnBotFastSoloIsPartyInstance()
				and UnBotFastSoloDungeonReserveReady()
			);
		local completionAction = UnBotBuffCycle.completionAction;
		local confirmed, unconfirmed = UnBotBuffCycleProgressBuffStatus();
		local completionText = "Бафф-цикл завершён: подтверждено "
			..tostring(#confirmed).."/"..tostring(#confirmed + #unconfirmed)
			.." доступных эффектов";
		if (#unconfirmed > 0) then
			completionText = completionText.."; не удалось подтвердить: "
				..table.concat(unconfirmed, ", ");
		end
		if (#(UnBotBuffCycle.levelSkippedOrder or {}) > 0) then
			completionText = completionText.."; недоступно на уровне "
				..tostring(UnBotBuffCyclePlayerLevel())..": "
				..table.concat(UnBotBuffCycle.levelSkippedOrder, ", ");
		end
		local skipped={};
		for label in pairs(UnBotBuffCycle.skippedBuffs or {}) do table.insert(skipped,label); end
		table.sort(skipped);
		if #skipped>0 then completionText=completionText.."; не найден баффер: "..table.concat(skipped,", "); end
		completionText = completionText..". Временные баферы удалены, исходный состав сохранён.";
		UnBotBuffCycleProgressNotice(true, true);
		UnBotBuffCycleStop(completionText, false, true);
		if (completionAction) then
			completionAction();
		end
		return;
	end
	UnBotBuffCycle.sentCommands = {};
	UnBotBuffCycle.verifyAfter = 0;
	UnBotBuffCycle.baselineMembers = UnBotSpecSummonGetMembers();
	UnBotBuffCycle.assignments = {};
	UnBotBuffCycle.assignedNames = {};
	UnBotBuffCycle.summonIndex = 1;
	UnBotBuffCycle.setupIndex = 1;
	UnBotBuffCycle.retryRound = 0;
	UnBotBuffCycle.capacityWaitLogged = false;
	UnBotBuffCycle.playerActionReported = {};
	UnBotBuffCycle.replacementSetupOnly = nil;
	UnBotBuffCycle.replacementMissingOnly = nil;
	UnBotBuffCycle.serverWaitDeadline = GetTime() + 180;
	UnBotBuffCycle.serverWaitLastMessageAt = 0;
	UnBotBuffCycle.arrivalAttempts = {};
	UnBotBuffCycle.arrivalNextSummonAt = {};
	UnBotBuffCycle.arrivalReady = {};
	UnBotBuffCycle.arrivalDeadline = 0;
	UnBotBuffCycle.arrivalLastMessageAt = 0;
	UnBotBuffCycle.arrivalResumeMissingOnly = false;
	UnBotBuffCyclePrepareRegistryPhase();
	UnBotBuffCycle.stage = "summon";
	UnBotBuffCycle.nextTime = GetTime();
	UnBotBuffCycle.stageUntil = GetTime() + 10;
	if (UnBotBuffCycle.raidWaveMode) then
		UnBotSpecSummonMessage((UnBotBuffCycle.mode == "solo" and "Fast Solo" or "Баф рейда")
			..": волна "..tostring(UnBotBuffCycle.phaseIndex)
			.."/"..tostring(#UnBotBuffCycle.runtimePhases)..", бафферов: "..tostring(#phase.bots)
			..". Сначала призыв, затем команды баффов в порядке очереди.");
	end
	UnBotSpecSummonMessage(
		"Buff registry phase "..tostring(UnBotBuffCycle.phaseIndex).."/"
		..tostring(#(UnBotBuffCycle.runtimePhases or UnBotBuffCyclePhases))..": "..phase.label.."."
	);
	UnBotBuffCycleProgressNotice(true, false);
end

function UnBotFastSoloIsPartyInstance()
	return GetInstanceInfo and select(2, GetInstanceInfo()) == "party" and true or false;
end

function UnBotFastSoloDungeonReserveReady()
	if (not UnBotFastSoloIsPartyInstance()) then
		return false;
	end
	for _, name in ipairs(UnBotSquadRosterReserveNames()) do
		local profile = UnBotBotRegistry and UnBotBotRegistry.bots
			and UnBotBotRegistry.bots[name];
		if (
			profile
			and UnBotRaidReserveResurrectionSpell(name)
			and UnBotSquadRosterIsOfflineReserve(name)
		) then
			return true;
		end
	end
	return false;
end

function UnBotBuffCycleStart(superFast)
	if not UnBotBuffCycle.ReadyForStart() then return false; end
	if (UnBotFullTalentCatalog and UnBotFullTalentCatalog.IsBusy()) then UnBotSpecSummonMessage("Сначала завершите сбор полного каталога талантов."); return false; end
	if (
		UnBotMythicPlusBuffIsRunning
		and UnBotMythicPlusBuffIsRunning()
		and not (
			UnBotMythicPlusBuffMayStartBuffCycle
			and UnBotMythicPlusBuffMayStartBuffCycle()
		)
	) then
		UnBotSpecSummonMessage("Сначала завершите или остановите бафф Mythic+.");
		return false;
	end
	superFast = superFast == true;
	if (UnBotBuffCycle.dungeonReservePending) then
		UnBotBuffCycleStopByUser();
		return;
	end
	if (UnBotBuffCycle.active) then
		if (UnBotBuffCycleStopByUser) then
			UnBotBuffCycleStopByUser();
		else
			UnBotBuffCycleStop("Buff cycle stopped.", true);
		end
		return;
	end
	if (IsMounted and IsMounted()) then
		UnBotSpecSummonMessage(
			"Бафф-цикл не запущен: вы находитесь на маунте. Спешьтесь и повторите запуск — призванные боты копируют маунт и не могут накладывать баффы."
		);
		return;
	end
	if (UnBotBotScanner and UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Stop the bot scan before starting Fast Solo.");
		return;
	end
	if (UnBotDKSpecBalance and UnBotDKSpecBalance.active) then
		UnBotSpecSummonMessage("Сначала остановите выравнивание спеков по количеству.");
		return;
	end
	if (UnBotJunkCleaner and UnBotJunkCleaner.active) then
		UnBotSpecSummonMessage("Stop the junk cleaner before starting Fast Solo.");
		return;
	end
	if (UnBotFastJunkRaid and UnBotFastJunkRaid.active) then
		UnBotSpecSummonMessage("Сначала остановите быструю рейдовую продажу серого хлама.");
		return;
	end
	if (UnitAffectingCombat and UnitAffectingCombat("player")) then
		UnBotSpecSummonMessage("Fast Solo запускается только вне боя: истекающие ауры нельзя безопасно заменять в бою.");
		return;
	end
	if (UnBotBuffCycleOtherMemberCount(true) > 0) then
		UnBotSpecSummonMessage("Fast Solo: сначала освободите группу от активных участников и повторите запуск.");
		return;
	end
	UnBotBuffCycle.mode = "solo";
	UnBotBuffCycle.superFast = superFast;
	UnBotBuffCycle.refreshPending = {};
	UnBotBuffCycle.refreshFreshCount = 0;
	UnBotBuffCycle.refreshNeededCount = 0;
	UnBotBuffDiagnosticStart("solo", superFast);
	UnBotBuffCycle.originalMembers = UnBotSpecSummonGetMembers();
	UnBotBuffCycle.blessingCasterNames = {};
	UnBotBuffCycle.offlineMembers = {};
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		if (name and (not unit or not UnitIsConnected(unit))) then
			UnBotBuffCycle.offlineMembers[name] = true;
		end
	end);
	for name in pairs(UnBotBuffCycle.originalMembers or {}) do
		UnBotSpecSummon.CancelStaleCleanup(name);
	end
	UnBotBuffCycle.targetNames = nil;
	UnBotBuffCycle.raidMemberLimit = UnBotBuffCycleResolveMemberLimit();
	UnBotBuffCycle.raidTemporaryCapacity = UnBotBuffCycleRaidFreeSlots();
	if (UnBotBuffCycle.raidTemporaryCapacity <= 0) then
		UnBotSpecSummonMessage("Fast Solo: свободных мест для бафферов нет; офлайн-резерв сохранён.");
		UnBotBuffDiagnosticFinish("No free slots for Fast Solo buffers.");
		return;
	end
	UnBotBuffCycle.runtimePhases = UnBotBuffCycleBuildRuntimePhases();
	if (#UnBotBuffCycle.runtimePhases == 0) then
		if ((UnBotBuffCycle.refreshFreshCount or 0) > 0) then
			UnBotSpecSummonMessage(
				"Fast Solo: все выбранные баффы соответствуют настроенным порогам остатка; обновление не требуется."
			);
			UnBotBuffDiagnosticFinish("All selected buffs satisfy their configured remaining-time thresholds.");
		else
			UnBotSpecSummonMessage(
				(superFast and "Супербыстрые баффы (соло)" or "Fast Solo")
				..": на уровне "..tostring(UnBotBuffCyclePlayerLevel())
				.." в выбранном наборе нет доступных баффов."
			);
			UnBotBuffDiagnosticFinish("No enabled buffs are available for the player level.");
		end
		UnBotBuffCycle.runtimePhases = nil;
		return;
	end
	UnBotSpecSummonMessage(
		"Fast Solo: баффов выше настроенного порога пропущено: "
		..tostring(UnBotBuffCycle.refreshFreshCount or 0)
		.."; требуется наложить или обновить: "
		..tostring(UnBotBuffCycle.refreshNeededCount or 0).."."
	);
	if (not UnBotBuffCycleValidateRegistry()) then
		UnBotBuffDiagnosticFinish("Buff registry validation failed.");
		UnBotBuffCycle.runtimePhases = nil;
		return;
	end
	UnBotBuffCycleResetReagentFailures();
	UnBotBuffDiagnosticPlan();
	UnBotBuffCycle.active = true;
	UnBotBuffCycle.phaseIndex = 1;
	UnBotBuffCycle.summoned = {};
	UnBotBuffCycle.cleanup = UnBotBuffCycle.cleanup or {};
	UnBotBuffCycleProgressReset();
	UnBotBuffCycle.diagnosticLastStage = nil;
	UnBotBuffCycle.diagnosticLastPhase = 0;
	UnBotBuffDiagnosticRoster("start");
	UnBotSpecSummonMessage(
		(superFast and "Супербыстрые баффы (соло)" or "Fast Solo")
		.." запущены для уровня "..tostring(UnBotBuffCyclePlayerLevel()).."."
	);
	if (superFast) then
		UnBotSpecSummonMessage(
			"Супербыстрый набор: пропущены только обнаружение невидимости, защита от страха "
			.."и подводное дыхание; Soulstone применяется по отдельной настройке."
		);
	end
	UnBotBuffCycleStartPhase();
end

UnBotSquadNearbyGate = UnBotSquadNearbyGate or {
	active = false,
	completionAction = nil,
	attempts = {},
	nextSummonAt = {},
	startedAt = 0,
	deadline = 0,
	nextScanAt = 0,
	lastMissingText = nil,
	stage = "idle",
	replacementNames = {},
	requirementsText = nil,
	referenceZone = nil,
};

function UnBotSquadNearbyGateUnitReady(unit)
	if (
		not unit
		or not UnitExists(unit)
		or not UnitIsConnected(unit)
	) then
		return false;
	end
	if (UnitIsVisible and not UnitIsVisible(unit)) then
		return false;
	end
	if (UnitInRange) then
		if (UnitInRange(unit)) then return true; end
	end
	if (CheckInteractDistance) then
		return CheckInteractDistance(unit, 1) and true or false;
	end
	return not UnitIsVisible or UnitIsVisible(unit);
end

function UnBotSquadNearbyGateMissingNames()
	local missing = {};
	if (UnBotSquadNearbyGate.assemblyNames) then
		for name in pairs(UnBotSquadNearbyGate.assemblyNames) do
			local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
			local unit = UnBotBuffCycleResolveUnit(name);
			if (name ~= UnitName("player") and not UnBotIsAccountAltProfile(name, profile)
				and not UnBotSquadRosterIsOfflineReserve(name, unit)
				and not UnBotSquadNearbyGateUnitReady(unit)) then table.insert(missing, name); end
		end
		table.sort(missing);
		return missing;
	end
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		local isBot = name
			and UnBotBotRegistry
			and UnBotBotRegistry.bots
			and UnBotBotRegistry.bots[name];
		if (
			isBot
			and not UnBotIsAccountAltProfile(name, isBot)
			and not UnBotSquadRosterIsOfflineReserve(name, unit)
			and not UnBotSquadNearbyGateUnitReady(unit)
		) then
			table.insert(missing, name);
		end
	end);
	table.sort(missing);
	return missing;
end

function UnBotSquadNearbyGateOnlineBotCount()
	local count = 0;
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		if (
			name
			and UnBotBotRegistry
			and UnBotBotRegistry.bots
			and UnBotBotRegistry.bots[name]
			and not UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots[name])
			and not UnBotSquadRosterIsOfflineReserve(name, unit)
		) then
			count = count + 1;
		end
	end);
	return count;
end

function UnBotSquadNearbyGateStop(text, clearSequence)
	local state = UnBotSquadNearbyGate;
	UnBotBuffCycleProgressHide();
	state.active = false;
	state.completionAction = nil;
	state.attempts = {};
	state.nextSummonAt = {};
	state.startedAt = 0;
	state.deadline = 0;
	state.nextScanAt = 0;
	state.lastMissingText = nil;
	state.stage = "idle";
	state.replacementNames = {};
	state.removals = {};
	state.requirementsText = nil;
	state.referenceZone = nil;
	state.assemblyNames = nil;
	state.assembly = nil;
	if (clearSequence) then
		UnBotSquadBuilder.postSummonSequence = nil;
		UnBotSquadBuilder.pendingBossPreset = nil;
	end
	if (text) then
		UnBotSpecSummonMessage(text);
	end
end

function UnBotSquadNearbyGateFinishSuccess()
	local state = UnBotSquadNearbyGate;
	local completionAction = state.completionAction;
	local botCount = UnBotSquadNearbyGateOnlineBotCount();
	local assembly = state.assembly;
	UnBotSquadNearbyGateStop(nil, false);
	UnBotSpecSummonMessage(
		assembly and "Состав собран: все выбранные боевые боты рядом с игроком."
		or ("Предбаффовая проверка завершена: все "..tostring(botCount)
		.." боевых ботов находятся рядом с игроком. Запускаю баффы.")
	);
	if (completionAction) then
		completionAction();
	end
end

function UnBotSquadNearbyGateFinishFailure(missing)
	if (UnBotSquadNearbyGate.assembly) then
		local result = UnBotSquadNearbyGateStartReplacement(missing);
		if (result == "started") then return; end
		if (result == "blocked") then UnBotSquadNearbyGateStop(nil, true); return; end
	end
	local names = table.concat(missing or {}, ", ");
	UnBotSquadNearbyGateStop(nil, true);
	UnBotSpecSummonMessage(
		"|cffff6060Предбаффовая проверка остановлена: после ограниченных попыток summon не рядом: "
		..tostring(names ~= "" and names or "неизвестно")
		..". Состав сохранён, боты не исключены и не помещены в карантин. Баффы и команды босса не запущены; подведите ботов и повторите добафф рейда.|r"
	);
end

function UnBotSquadNearbyGateSendSummons(missing, now)
	local state = UnBotSquadNearbyGate;
	for _, name in ipairs(missing or {}) do
		local unit = UnBotBuffCycleResolveUnit(name);
		if (
			unit
			and UnitIsConnected(unit)
			and (state.attempts[name] or 0) < 3
			and now >= (state.nextSummonAt[name] or 0)
		) then
			UnBotBuffCycleSendWhisper(name, "summon");
			UnBotBuffCycleSendWhisper(name, "follow");
			state.attempts[name] = (state.attempts[name] or 0) + 1;
			state.nextSummonAt[name] = now + 3;
		end
	end
end

function UnBotSquadNearbyGateStartReplacement(missing)
	local state = UnBotSquadNearbyGate;
	local sequence = UnBotSquadBuilder.postSummonSequence;
	local filteredMissing = {};
	for _, name in ipairs(missing or {}) do
		local profile = UnBotBotRegistry
			and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (name ~= UnitName("player")
			and not UnBotIsAccountAltProfile(name, profile)
			and not UnBotSquadRosterIsOfflineReserve(name)) then
			table.insert(filteredMissing, name);
		end
	end
	missing = filteredMissing;
	if (#missing == 0) then
		return nil;
	end
	local requirementsText = sequence and sequence.requirementsText
		or (type(UnBotSquadBuilderRequirementsText) == "function" and UnBotSquadBuilderRequirementsText() or nil);
	if (not sequence or not requirementsText or requirementsText == "") then
		return nil;
	end
	local now = GetTime();
	local replacementRound = (tonumber(sequence and sequence.locationReplacementRounds) or 0) + 1;
	local untilTime = UnBotRegistryNextMorningTimestamp();
	if (replacementRound > 3) then
		for _, name in ipairs(missing or {}) do
			local profile = UnBotBotRegistry
				and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
			local flag = UnBotRegistryGetActiveFlag(profile);
			if (not flag or flag.kind ~= "quarantine") then
				UnBotRegistrySetQuarantine(
					name,
					"предбаффовая проверка: бот не виден рядом с игроком",
					untilTime
				);
			end
		end
		UnBotSquadBuilder.postSummonSequence = nil;
		UnBotSquadBuilder.pendingBossPreset = nil;
		UnBotSpecSummonMessage(
			"|cffff6060Предбаффовая ротация остановлена после трёх раундов замен: "
			..table.concat(missing or {}, ", ")
			.." также не находятся рядом. Боты помещены в карантин; баффы и команды босса не запущены.|r"
		);
		return "blocked";
	end
	sequence.locationReplacementRounds = replacementRound;
	state.active = true;
	state.stage = "remove_missing";
	state.completionAction = nil;
	state.attempts = {};
	state.nextSummonAt = {};
	state.startedAt = now;
	state.deadline = now + 30;
	state.nextScanAt = now;
	state.lastMissingText = table.concat(missing or {}, ", ");
	state.replacementNames = {};
	state.removals = {};
	state.requirementsText = requirementsText;
	state.referenceZone = GetRealZoneText
		and UnBotSpecSummonNormalize(GetRealZoneText()) or nil;

	for _, name in ipairs(missing or {}) do
		state.replacementNames[name] = true;
		state.removals[name] = {attempts = 0, nextTime = now};
		local profile = UnBotBotRegistry
			and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		local flag = UnBotRegistryGetActiveFlag(profile);
		if (not state.assembly and (not flag or flag.kind ~= "quarantine")) then
			local reason = "предбаффовая проверка: бот не виден рядом с игроком";
			if (UnBotRegistrySetQuarantine(name, reason, untilTime)) then
				UnBotSpecSummonMessage(
					"Ротация: "..tostring(name).." помещён в карантин до "
					..UnBotRegistryFlagTimeText(untilTime).." — "..reason.."."
				);
			end
		end
	end

	if (sequence) then
		sequence.arrivalChecked = false;
		sequence.buffStageFinished = false;
		sequence.buffStarted = false;
	end
	UnBotSpecSummonMessage(
		(state.assembly and "Сбор состава: заменяю не прибывших ботов: " or "Предбаффовая ротация: удаляю из рейда отсутствующих ботов: ")
		..state.lastMissingText
		..". После освобождения слотов подберу замену того же класса/спека (раунд "
		..tostring(replacementRound).."/3)."
	);
	UnBotBuffCycleProgressRaidNotice(
		(state.assembly and "СБОР СОСТАВА — МЕНЯЮ НЕ ПРИБЫВШИХ БОТОВ" or "ПОДГОТОВКА К БАФАМ — МЕНЯЮ ОТСУТСТВУЮЩИХ БОТОВ").."\nОСТАНОВИТЬ: /ubstopbuffs",
		true
	);
	return "started";
end

-- `bot remove` logs a bot out, but does not prove departure from the raid.
-- Restore an offline failed combat candidate once, then wait for roster removal
-- before logging it out. Never summon it to the player during this recovery.
function UnBotSquadNearbyGate.RemoveCandidate(name, now)
	local state = UnBotSquadNearbyGate;
	local removal = state.removals[name];
	if (removal.done) then return true; end
	if (removal.failed) then return false; end
	local profile = UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (name == UnitName("player") or UnBotIsAccountAltProfile(name, profile)
		or UnBotSquadRosterIsOfflineReserve(name)) then
		removal.failed = true;
		return false;
	end
	if (now >= state.deadline) then return false; end
	if ((InCombatLockdown and InCombatLockdown())
		or (UnitAffectingCombat and UnitAffectingCombat("player"))) then return false; end
	local unit = UnBotSquadRosterFindUnit(name);
	if (state.assembly and removal.attempts == 0 and unit and UnBotSquadNearbyGateUnitReady(unit)) then
		removal.done = true;
		UnBotSpecSummonMessage("Сбор состава: "..name.." появился рядом; оставляю его в составе.");
		return true;
	end
	if (not unit) then
		-- Require a second roster observation, not just the command's return.
		removal.absentSince = removal.absentSince or now;
		if (now - removal.absentSince < 0.5) then return false; end
		if (state.assembly) then
			UnBotRegistrySetHourlyQuarantine(name, "сбор состава: не появился рядом после трёх summon", "Ротация");
		end
		UnBotBuffCycleSendSay(".playerbot bot remove "..name);
		removal.done = true;
		UnBotSpecSummonMessage("Ротация: "..name.." исключён из рейда; отправлена команда офлайн.");
		return true;
	end
	removal.absentSince = nil;
	if (not UnitIsConnected(unit)) then
		if (not removal.onlineRequestedAt) then
			removal.onlineRequestedAt = now;
			removal.waitingOnline = true;
			UnBotBuffCycleSendSay(".playerbot bot add "..name);
			UnBotSpecSummonMessage("Ротация: "..name.." офлайн в рейде; возвращаю онлайн для исключения (до 10 секунд).");
		elseif (not removal.waitingOnline or now - removal.onlineRequestedAt >= 10) then
			removal.failed = true;
			UnBotSpecSummonMessage("Ротация: "..name.." не подтвердил устойчивый онлайн; повторный add не отправляется.");
		end
		return false;
	end
	if (removal.waitingOnline) then
		removal.waitingOnline = nil;
		removal.nextTime = now;
		UnBotSpecSummon.uninviteAttempts = UnBotSpecSummon.uninviteAttempts or {};
		UnBotSpecSummon.uninviteAttempts[name] = nil;
		UnBotSpecSummonMessage("Ротация: "..name.." снова онлайн; исключаю из рейда.");
	end
	if (now >= removal.nextTime and removal.attempts < 3) then
		UnBotSpecSummonUninvite(name);
		removal.attempts = removal.attempts + 1;
		removal.nextTime = now + 2;
	end
	return false;
end

function UnBotSquadNearbyGateReplacementUpdate(now)
	local state = UnBotSquadNearbyGate;
	local remaining = {};
	for name in pairs(state.replacementNames or {}) do
		if (not state.RemoveCandidate(name, now)) then
			table.insert(remaining, name);
		end
	end
	table.sort(remaining);
	if (#remaining == 0) then
		local requirementsText = state.requirementsText;
		local referenceZone = state.referenceZone;
		local sequence = UnBotSquadBuilder.postSummonSequence;
		UnBotSquadNearbyGateStop(nil, false);
		UnBotSpecSummonMessage(
			"Предбаффовая ротация: слоты освобождены; вызываю замены по сохранённому составу."
		);
		UnBotSpecSummonSquadStart(requirementsText, true, referenceZone, nil, sequence and sequence.checkedCandidates);
		if (
			not UnBotSpecSummon.active
			and UnBotSquadBuilder.postSummonSequence == sequence
			and not UnBotSquadSpecCheck.active
			and (UnBotSquadSpecCheck.autoStartAt or 0) <= 0
			and not UnBotSquadNearbyGate.active
			and not UnBotBuffCycle.active
		) then
			UnBotSquadBuilder.postSummonSequence = nil;
			UnBotSquadBuilder.pendingBossPreset = nil;
			UnBotSpecSummonMessage(
				"|cffff6060Предбаффовая ротация остановлена: подбор замен не удалось запустить. Проверьте сообщения реестра выше; баффы и команды босса не запущены.|r"
			);
		end
		return;
	end
	if (now >= (state.deadline or 0)) then
		UnBotSquadNearbyGateStop(nil, true);
		UnBotSpecSummonMessage(
			"|cffff6060Предбаффовая ротация остановлена: не удалось освободить места: "
			..table.concat(remaining, ", ")
			..". Баффы и команды босса не запущены.|r"
		);
	end
end

function UnBotSquadNearbyGateStart(completionAction, assemblyNames)
	local state = UnBotSquadNearbyGate;
	if (state.active) then
		return "waiting";
	end
	if (IsMounted and IsMounted()) then
		UnBotSquadNearbyGateStop(
			"Бафф-цикл не запущен: вы находитесь на маунте. Спешьтесь и повторите запуск — призванные боты копируют маунт и не могут накладывать баффы.",
			true
		);
		return "blocked";
	end
	if (UnitAffectingCombat("player")) then
		UnBotSquadNearbyGateStop(
			"Предбаффовая проверка не запущена в бою. Баффы и команды босса отменены; завершите бой и повторите призыв состава.",
			true
		);
		return "blocked";
	end
	state.assemblyNames = assemblyNames;
	state.assembly = assemblyNames ~= nil;
	local missing = UnBotSquadNearbyGateMissingNames();
	if (#missing == 0) then
		UnBotSpecSummonMessage(
			"Предбаффовая проверка: все "
			..tostring(UnBotSquadNearbyGateOnlineBotCount())
			.." боевых ботов уже рядом."
		);
		return "ready";
	end
	-- Range/visibility can lag roster arrival or fail for the whole raid.
	-- A proximity check never authorizes replacing the accepted combat squad.
	state.active = true;
	state.stage = "wait_nearby";
	state.completionAction = completionAction;
	state.attempts = {};
	state.nextSummonAt = {};
	state.startedAt = GetTime();
	state.deadline = state.startedAt + 18;
	state.nextScanAt = state.startedAt;
	state.lastMissingText = table.concat(missing, ", ");
	UnBotSpecSummonMessage(
		(state.assembly and "Проверка прибытия состава: не рядом " or "Предбаффовая проверка: не рядом ")..state.lastMissingText
		..". Отправляю до трёх summon; ожидаю прибытия до 18 секунд."
	);
	UnBotSpecSummonMessage(
		"|cffffff00Остановить предбаффовую проверку и всю очередь: /ubstopbuffs.|r"
	);
	UnBotBuffCycleProgressRaidNotice(
		(state.assembly and "СБОР СОСТАВА — ЖДУ БОТОВ РЯДОМ" or "ПОДГОТОВКА К БАФАМ — ЖДУ БОТОВ РЯДОМ").."\nОСТАНОВИТЬ: /ubstopbuffs",
		true
	);
	UnBotSquadNearbyGateSendSummons(missing, state.startedAt);
	return "waiting";
end

UnBotSquadNearbyGateFrame = UnBotSquadNearbyGateFrame
	or CreateFrame("Frame", "UnBotSquadNearbyGateFrame");
UnBotSquadNearbyGateFrame:SetScript("OnUpdate", function()
	local state = UnBotSquadNearbyGate;
	if (not state.active) then
		return;
	end
	if UnitIsDeadOrGhost and UnitIsDeadOrGhost("player") then
		UnBotSquadNearbyGateStop("Предбаффовая проверка прервана: игрок погиб. После воскрешения запустите баффы заново.",true); return;
	end
	local now = GetTime();
	if (now < (state.nextScanAt or 0)) then
		return;
	end
	state.nextScanAt = now + 0.5;
	if (IsMounted and IsMounted()) then
		UnBotSquadNearbyGateStop(
			"Предбаффовая проверка остановлена: вы сели на маунта. Спешьтесь и запустите бафф-цикл заново.",
			true
		);
		return;
	end
	if (UnitAffectingCombat("player")) then
		UnBotSquadNearbyGateStop(
			"|cffff6060Предбаффовая проверка остановлена начавшимся боем; баффы и команды босса не запущены.|r",
			true
		);
		return;
	end
	if (state.stage == "remove_missing") then
		UnBotSquadNearbyGateReplacementUpdate(now);
		return;
	end
	local missing = UnBotSquadNearbyGateMissingNames();
	if (#missing == 0) then
		UnBotSquadNearbyGateFinishSuccess();
		return;
	end
	local missingText = table.concat(missing, ", ");
	if (missingText ~= state.lastMissingText) then
		state.lastMissingText = missingText;
		UnBotSpecSummonMessage(
			"Предбаффовая проверка: ещё не рядом "..missingText.."."
		);
	end
	if (now >= (state.deadline or 0)) then
		UnBotSquadNearbyGateFinishFailure(missing);
		return;
	end
	UnBotSquadNearbyGateSendSummons(missing, now);
end);

function UnBotRaidBuffCycleStart(completionAction, memberLimit, nearbyChecked, superFast)
	if not UnBotBuffCycle.ReadyForStart() then return false; end
	if (
		UnBotMythicPlusBuffIsRunning
		and UnBotMythicPlusBuffIsRunning()
		and not (
			UnBotMythicPlusBuffMayStartBuffCycle
			and UnBotMythicPlusBuffMayStartBuffCycle()
		)
	) then
		UnBotSpecSummonMessage("Сначала завершите или остановите бафф Mythic+.");
		return false;
	end
	if (UnBotBuffCycle.active) then
		if (UnBotBuffCycleStopByUser) then
			UnBotBuffCycleStopByUser();
		else
			UnBotBuffCycleStop("Баф рейда остановлен. Временно вызванные боты удаляются.", true);
		end
		return false;
	end
	if (IsMounted and IsMounted()) then
		UnBotSpecSummonMessage(
			"Бафф-цикл не запущен: вы находитесь на маунте. Спешьтесь и повторите запуск — призванные боты копируют маунт и не могут накладывать баффы."
		);
		return false;
	end
	if (
		not nearbyChecked
		and UnBotSquadNearbyGate
		and UnBotSquadNearbyGate.active
	) then
		if (UnBotBuffCycleStopByUser) then
			UnBotBuffCycleStopByUser();
		else
			UnBotSquadNearbyGateStop(
				"Предбаффовая проверка остановлена пользователем.",
				true
			);
		end
		return false;
	end
	if (UnBotBotScanner and UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Сначала остановите полный скан ботов.");
		return false;
	end
	if (UnBotDKSpecBalance and UnBotDKSpecBalance.active) then
		UnBotSpecSummonMessage("Сначала остановите выравнивание спеков по количеству.");
		return false;
	end
	if (UnBotJunkCleaner and UnBotJunkCleaner.active) then
		UnBotSpecSummonMessage("Сначала остановите продажу хлама.");
		return false;
	end
	if (UnBotFastJunkRaid and UnBotFastJunkRaid.active) then
		UnBotSpecSummonMessage("Сначала остановите быструю рейдовую продажу серого хлама.");
		return false;
	end
	if (UnBotSpecSummon.active) then
		UnBotSpecSummonMessage("Сначала завершите текущий призыв состава.");
		return false;
	end
	if (UnBotBuffCycleOtherMemberCount() == 0) then
		UnBotSpecSummonMessage("Баф рейда: сначала соберите группу или рейд.");
		return false;
	end
	if (not nearbyChecked) then
		local gateResult = UnBotSquadNearbyGateStart(function()
			local started = UnBotRaidBuffCycleStart(
				completionAction,
				memberLimit,
				true,
				superFast
			);
			if (not started and type(completionAction) == "function") then
				completionAction();
			end
		end);
		if (gateResult == "waiting") then
			return true;
		elseif (gateResult == "replacing") then
			return true, "nearby-replacing";
		elseif (gateResult == "blocked") then
			return false, "nearby-blocked";
		end
	end
	UnBotBuffCycle.raidMemberLimit = UnBotBuffCycleResolveMemberLimit(memberLimit);
	local currentRaidSize = UnBotBuffCycleRaidSize();

	UnBotBuffCycle.mode = "raid";
	UnBotBuffCycle.superFast = superFast and true or false;
	UnBotBuffDiagnosticStart("raid", superFast);
	UnBotBuffCycle.originalMembers = UnBotSpecSummonGetMembers();
	UnBotBuffCycle.blessingCasterNames = {};
	UnBotBuffCycle.offlineMembers = {};
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		if (name and (not unit or not UnitIsConnected(unit))) then
			UnBotBuffCycle.offlineMembers[name] = true;
		end
	end);
	for name in pairs(UnBotBuffCycle.originalMembers or {}) do
		UnBotSpecSummon.CancelStaleCleanup(name);
	end
	UnBotBuffCycle.targetNames = UnBotBuffCycleSnapshotTargets();
	UnBotBuffCycle.raidTemporaryCapacity = math.max(
		0,
		UnBotBuffCycle.raidMemberLimit - currentRaidSize
	);
	UnBotBuffCycle.runtimePhases = UnBotBuffCycleBuildRuntimePhases();
	if (#UnBotBuffCycle.runtimePhases == 0) then
		UnBotSpecSummonMessage(
			"Баф рейда: на уровне "..tostring(UnBotBuffCyclePlayerLevel())
			.." в выбранном наборе нет доступных баффов."
		);
		UnBotBuffCycle.runtimePhases = nil;
		UnBotBuffCycle.targetNames = nil;
		UnBotBuffCycle.raidTemporaryCapacity = nil;
		UnBotBuffCycle.raidMemberLimit = 25;
		UnBotBuffCycle.mode = "solo";
		UnBotBuffCycle.superFast = false;
		UnBotBuffDiagnosticFinish("No enabled raid buffs are available for the player level.");
		return false;
	end
	if (not UnBotBuffCycleValidateRegistry()) then
		UnBotBuffDiagnosticFinish("Raid buff registry validation failed.");
		UnBotBuffCycle.runtimePhases = nil;
		UnBotBuffCycle.targetNames = nil;
		UnBotBuffCycle.raidTemporaryCapacity = nil;
		UnBotBuffCycle.raidMemberLimit = 25;
		UnBotBuffCycle.mode = "solo";
		UnBotBuffCycle.superFast = false;
		return false;
	end

	UnBotBuffCycle.completionAction = type(completionAction) == "function"
		and completionAction or nil;
	UnBotBuffCycleResetReagentFailures();
	UnBotBuffDiagnosticPlan();
	UnBotBuffCycle.active = true;
	UnBotBuffCycle.playerActionReported = {};
	UnBotBuffCycle.phaseIndex = 1;
	UnBotBuffCycle.summoned = {};
	UnBotBuffCycle.cleanup = UnBotBuffCycle.cleanup or {};
	UnBotBuffCycleProgressReset();
	UnBotBuffCycle.diagnosticLastStage = nil;
	UnBotBuffCycle.diagnosticLastPhase = 0;
	UnBotBuffDiagnosticRoster("start");
	UnBotSpecSummonMessage(
		(UnBotBuffCycle.superFast and "Супербыстрые баффы" or "Баф рейда")
		.." запущены: целей "..tostring(#UnBotBuffCycle.targetNames)
		..", временных баферов одновременно не больше "
		..tostring(UnBotBuffCycle.raidTemporaryCapacity)
		.." (лимит состава "..tostring(UnBotBuffCycle.raidMemberLimit)..")"
		..". Будут обновлены только эффекты из выбранного набора."
	);
	if (UnBotBuffCycle.superFast) then
		UnBotSpecSummonMessage(
			"Супербыстрый набор: пропущены только обнаружение невидимости, защита от страха "
			.."и подводное дыхание; Soulstone применяется по отдельной настройке."
		);
	end
	if (UnBotBuffCycle.raidTemporaryCapacity == 0) then
		UnBotSpecSummonMessage(
			"Баф рейда: состав "..tostring(UnBotBuffCycleRaidSize()).."/"
			..tostring(UnBotBuffCycle.raidMemberLimit)
			..". Используются только подходящие боты, уже находящиеся в рейде."
		);
	end
	UnBotBuffCycleStartPhase();
	return true;
end

function UnBotBuffCycleStopByUser()
	if (
		UnBotMythicPlusBuffIsRunning
		and UnBotMythicPlusBuffIsRunning()
		and not (
			UnBotMythicPlusBuffIsStoppingBuffCycle
			and UnBotMythicPlusBuffIsStoppingBuffCycle()
		)
		and UnBotMythicPlusBuffStopByUser
	) then
		return UnBotMythicPlusBuffStopByUser();
	end
	local stopped = false;
	if (UnBotBuffCycle.dungeonReservePending) then
		UnBotBuffCycle.dungeonReservePending = false;
		UnBotBuffCycle.dungeonReserveSuperFast = false;
		if (
			UnBotRaidReserve
			and UnBotRaidReserve.active
			and UnBotRaidReserve.action == "prepare"
			and UnBotRaidReserveStop
		) then
			UnBotRaidReserveStop("Подготовка резерва для Fast Solo остановлена пользователем.");
		else
			UnBotSpecSummonMessage("Ожидание резерва для Fast Solo отменено пользователем.");
		end
		stopped = true;
	end
	if (UnBotSquadNearbyGate and UnBotSquadNearbyGate.active) then
		UnBotSquadNearbyGateStop(
			"Предбаффовая проверка остановлена пользователем.",
			true
		);
		stopped = true;
	end
	if (UnBotBuffCycle.active) then
		UnBotBuffCycleStop(
			"Бафф-цикл остановлен пользователем. Временно вызванные боты удаляются.",
			true
		);
		stopped = true;
	end
	if (UnBotSquadBuilder and UnBotSquadBuilder.postSummonSequence) then
		if (UnBotSpecSummon and UnBotSpecSummon.active) then
			UnBotSpecSummonStop(
				"Автоматическая очередь состава и баффов остановлена пользователем."
			);
		end
		UnBotSquadBuilder.postSummonSequence = nil;
		UnBotSquadBuilder.pendingBossPreset = nil;
		stopped = true;
	end
	if (stopped) then
		UnBotBuffCycleProgressRaidNotice(
			"БАФФ-ЦИКЛ ОСТАНОВЛЕН\nВРЕМЕННЫЕ БАФЕРЫ УДАЛЯЮТСЯ",
			true,
			7
		);
	else
		UnBotSpecSummonMessage("Нет активного бафф-цикла или предбаффовой проверки.");
	end
	return stopped;
end

local UnBotSoulstoneTest = {
	active = false,
	stage = nil,
	nextTime = 0,
	stageUntil = 0,
	baselineMembers = {},
	candidate = nil,
	attempt = 0,
	registryCandidates = {},
	registryCandidateIndex = 1,
	requestedName = nil,
	requestedNames = {},
};

local UnBotSoulstoneTestAura = {
	minLevel = 18,
	ids = {47883, 27239, 20707},
};

local function UnBotSoulstoneAuraCasterName(fallbackName)
	for i = 1, 40, 1 do
		local auraName, rank, icon, count, debuffType, duration, expirationTime, unitCaster, isStealable, shouldConsolidate, spellId = UnitBuff("player", i);
		if (not auraName) then
			break
		end
		for _, wantedId in ipairs(UnBotSoulstoneTestAura.ids or {}) do
			if (
				(spellId and spellId == wantedId)
				or (GetSpellInfo and auraName == GetSpellInfo(wantedId))
			) then
				local casterName = unitCaster and UnitName(unitCaster);
				return casterName or fallbackName;
			end
		end
	end
	return fallbackName;
end

local UnBotSoulstoneTestCommands = {
	"nc +ss master",
};

local function UnBotSoulstoneTestFindWarlock()
	if (
		UnBotSoulstoneTest.requestedName
		and UnBotSpecSummonIsInGroup(UnBotSoulstoneTest.requestedName)
	) then
		return UnBotSoulstoneTest.requestedName;
	end
	for name in pairs(UnBotSoulstoneTest.requestedNames or {}) do
		if (UnBotSpecSummonIsInGroup(name)) then
			return name;
		end
	end
	return nil;
end

local function UnBotSoulstoneTestCleanup()
	local cleanupNames = {};
	if (UnBotSoulstoneTest.candidate) then
		cleanupNames[UnBotSoulstoneTest.candidate] = true;
	end
	for name in pairs(UnBotSoulstoneTest.requestedNames or {}) do
		if (UnBotSpecSummonIsInGroup(name)) then
			cleanupNames[name] = true;
		end
	end
	for name in pairs(cleanupNames) do
		if (UnBotSpecSummonIsInGroup(name)) then
			UnBotSpecSummonUninvite(name);
			UnBotBuffCycle.cleanup[name] = {
				removeSent = false,
				nextTime = GetTime() + 0.5,
				untilTime = GetTime() + 30,
			};
		end
	end
end

local function UnBotSoulstoneTestStop(text, cleanup)
	if (cleanup) then
		UnBotSoulstoneTestCleanup();
	end
	UnBotSoulstoneTest.active = false;
	UnBotSoulstoneTest.stage = nil;
	UnBotSoulstoneTest.candidate = nil;
	UnBotSoulstoneTest.requestedName = nil;
	if (text) then
		UnBotSpecSummonMessage(text);
	end
end

local function UnBotSoulstoneTestAcceptWarlock(name)
	if (not name or UnBotSoulstoneTest.candidate) then
		return;
	end
	UnBotSoulstoneTest.candidate = name;
	UnBotSoulstoneTest.requestedName = name;
	UnBotRememberKnownBot(name);
	local summonCount = UnBotRegistryRecordGameplaySummon(name, "soulstone-test");
	UnBotSoulstoneTest.stage = "reset";
	UnBotSoulstoneTest.nextTime = GetTime() + 0.5;
	UnBotBuffCycleSendWhisper(name, "summon");
	UnBotBuffCycleSendWhisper(name, "stay");
	UnBotSpecSummonMessage(
		"Soulstone test: Warlock ready ("..name..", summons "
		..tostring(summonCount or "?")..")."
	);
end

local function UnBotSoulstoneTestTryNextWarlock()
	local name = UnBotSoulstoneTest.registryCandidates[UnBotSoulstoneTest.registryCandidateIndex];
	if (not name or UnBotSoulstoneTest.registryCandidateIndex > 4) then
		UnBotSoulstoneTestStop("Soulstone test failed: no saved Demonology Warlock joined.", false);
		return false;
	end
	UnBotSoulstoneTest.registryCandidateIndex = UnBotSoulstoneTest.registryCandidateIndex + 1;
	UnBotSoulstoneTest.requestedName = name;
	UnBotSoulstoneTest.requestedNames[name] = true;
	UnBotSoulstoneTest.stage = "wait_member";
	UnBotSoulstoneTest.nextTime = GetTime() + 0.25;
	UnBotSoulstoneTest.stageUntil = GetTime() + 10;
	UnBotBuffCycleSendSay(".playerbot bot add "..name);
	UnBotSpecSummonMessage(
		"Soulstone registry summon: "..name.." (Demonology candidate "
		..tostring(UnBotSoulstoneTest.registryCandidateIndex - 1).."/4)."
	);
	return true;
end

local function UnBotSoulstoneTestStart()
	if (UnBotFullTalentCatalog and UnBotFullTalentCatalog.IsBusy()) then UnBotSpecSummonMessage("Сначала завершите сбор полного каталога талантов."); return false; end
	if (UnBotSoulstoneTest.active) then
		UnBotSoulstoneTestStop("Soulstone test stopped; Warlock removed.", true);
		return;
	end
	if (UnBotBuffCyclePlayerLevel() < UnBotSoulstoneTestAura.minLevel) then
		UnBotSpecSummonMessage(
			"Soulstone недоступен на уровне "..tostring(UnBotBuffCyclePlayerLevel())
			..". Минимальный уровень: "..tostring(UnBotSoulstoneTestAura.minLevel).."."
		);
		return;
	end
	if (UnBotBotScanner and UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Stop the bot scan before starting the Soulstone test.");
		return;
	end
	if (UnBotDKSpecBalance and UnBotDKSpecBalance.active) then
		UnBotSpecSummonMessage("Сначала остановите выравнивание спеков по количеству.");
		return;
	end
	if (UnBotJunkCleaner and UnBotJunkCleaner.active) then
		UnBotSpecSummonMessage("Stop the junk cleaner before starting the Soulstone test.");
		return;
	end
	if (UnBotFastJunkRaid and UnBotFastJunkRaid.active) then
		UnBotSpecSummonMessage("Сначала остановите быструю рейдовую продажу серого хлама.");
		return;
	end
	if (UnBotBuffCycle.active) then
		UnBotSpecSummonMessage("Stop Fast Solo before starting the Soulstone test.");
		return;
	end
	if (UnBotBuffCycleOtherMemberCount() > 0) then
		UnBotSpecSummonMessage("Soulstone test requires an empty group.");
		return;
	end
	local registryCandidates = UnBotRegistryCandidates("warlock", {"demonology"});
	if (#registryCandidates == 0) then
		UnBotSpecSummonMessage(
			"Soulstone test: no available Demonology Warlock. Check /ubflags list or run the full bot scan."
		);
		return;
	end

	UnBotSoulstoneTest.active = true;
	UnBotSoulstoneTest.baselineMembers = UnBotSpecSummonGetMembers();
	UnBotSoulstoneTest.candidate = nil;
	UnBotSoulstoneTest.attempt = 0;
	UnBotSoulstoneTest.registryCandidates = registryCandidates;
	UnBotSoulstoneTest.registryCandidateIndex = 1;
	UnBotSoulstoneTest.requestedName = nil;
	UnBotSoulstoneTest.requestedNames = {};
	UnBotSpecSummonMessage(
		"Soulstone test started from registry: "..tostring(#registryCandidates)
		.." Demonology candidates."
	);
	UnBotSoulstoneTestTryNextWarlock();
end

local soulstoneTestFrame = CreateFrame("Frame", "UnBotSoulstoneTestFrame");
soulstoneTestFrame:RegisterEvent("PARTY_MEMBERS_CHANGED");
soulstoneTestFrame:RegisterEvent("RAID_ROSTER_UPDATE");
soulstoneTestFrame:SetScript("OnEvent", function()
	if (UnBotSoulstoneTest.active and UnBotSoulstoneTest.stage == "wait_member") then
		UnBotSoulstoneTestAcceptWarlock(UnBotSoulstoneTestFindWarlock());
	end
end);

soulstoneTestFrame:SetScript("OnUpdate", function()
	if (not UnBotSoulstoneTest.active or GetTime() < (UnBotSoulstoneTest.nextTime or 0)) then
		return;
	end
	local now = GetTime();
	local name = UnBotSoulstoneTest.candidate;

	if (UnBotSoulstoneTest.stage == "wait_member") then
		local warlock = UnBotSoulstoneTestFindWarlock();
		if (warlock) then
			UnBotSoulstoneTestAcceptWarlock(warlock);
		elseif (now >= UnBotSoulstoneTest.stageUntil) then
			UnBotSpecSummonMessage(
				"Soulstone registry candidate "..tostring(UnBotSoulstoneTest.requestedName)
				.." did not join; trying the next saved Warlock."
			);
			UnBotSoulstoneTestTryNextWarlock();
		else
			UnBotSoulstoneTest.nextTime = now + 0.25;
		end
	elseif (UnBotSoulstoneTest.stage == "reset") then
		UnBotBuffCycleSendWhisper(name, "reset botAI");
		UnBotSoulstoneTest.stage = "cast";
		UnBotSoulstoneTest.nextTime = now + 1;
	elseif (UnBotSoulstoneTest.stage == "cast") then
		UnBotSoulstoneTest.attempt = UnBotSoulstoneTest.attempt + 1;
		local command = UnBotSoulstoneTestCommands[UnBotSoulstoneTest.attempt];
		UnBotSpecSummonMessage("Soulstone test "..tostring(UnBotSoulstoneTest.attempt).."/"..tostring(#UnBotSoulstoneTestCommands)..": "..command);
		UnBotBuffCycleSendWhisper(name, command);
		UnBotSoulstoneTest.stage = "verify";
		UnBotSoulstoneTest.nextTime = now + 4;
	elseif (UnBotSoulstoneTest.stage == "verify") then
		if (UnBotBuffCyclePlayerHasBuff(UnBotSoulstoneTestAura)) then
			UnBotRegistryMarkSoulstoneCooldown(UnBotSoulstoneAuraCasterName(name));
			UnBotSoulstoneTest.stage = "passed";
			UnBotSoulstoneTest.nextTime = math.huge;
			UnBotSpecSummonMessage(
				"Soulstone test passed: aura detected. Warlock stays in group because "
				.."Soulstone disappears when its caster leaves. Click the test button again to remove it."
			);
		elseif (UnBotSoulstoneTest.attempt < #UnBotSoulstoneTestCommands) then
			UnBotSoulstoneTest.stage = "cast";
			UnBotSoulstoneTest.nextTime = now;
		else
			UnBotSoulstoneTest.stage = "pending";
			UnBotSoulstoneTest.nextTime = now + 5;
			UnBotSpecSummonMessage(
				"Soulstone strategy enabled. Aura is not active yet, usually because the existing "
				.."Soulstone is on cooldown. Warlock stays in group and will apply it when ready."
			);
		end
	elseif (UnBotSoulstoneTest.stage == "pending") then
		if (UnBotBuffCyclePlayerHasBuff(UnBotSoulstoneTestAura)) then
			UnBotRegistryMarkSoulstoneCooldown(UnBotSoulstoneAuraCasterName(name));
			UnBotSoulstoneTest.stage = "passed";
			UnBotSoulstoneTest.nextTime = math.huge;
			UnBotSpecSummonMessage("Soulstone test passed after cooldown: aura detected.");
		else
			UnBotSoulstoneTest.nextTime = now + 5;
		end
	end
end);

local UnBotWarlockGroupBuff = {
	activeName = nil,
	stage = "idle",
	queue = {},
	queueIndex = 1,
	nextTime = 0,
	nextCheck = 0,
	soulstoneAttempt = 0,
	cooldownUntil = 0,
	retryRound = 0,
	suppressedUntil = 0,
	lastPlayerLevel = nil,
	soulstoneStrategyName = nil,
	soulstoneStrategyAt = 0,
	soulstonePendingLogged = false,
	soulstonePendingSince = 0,
	soulstoneTriedNames = {},
	soulstoneReplacementName = nil,
	soulstoneReplacementOldName = nil,
	soulstoneReplacementUntil = 0,
	soulstoneReplacementCount = 0,
	soulstoneReplacementExhausted = false,
};

local UnBotWarlockGroupBuffAuras = {
	{
		label = "Detect Invisibility",
		ids = {132},
		command = "cast Detect Invisibility on {player}",
		minLevel = 26,
	},
	{
		label = "Unending Breath",
		ids = {5697},
		command = "cast Unending Breath on {player}",
		minLevel = 16,
	},
};

local function UnBotWarlockGroupBuffHasAvailable()
	if (UnBotBuffCycleRaidSize() <= 10) then
		for _, buff in ipairs(UnBotWarlockGroupBuffAuras) do
			if (UnBotBuffCycleBuffAvailable(buff)) then
				return true;
			end
		end
	end
	return false;
end

local function UnBotWarlockGroupBuffFind()
	local bestName = nil;
	local bestGearScore = -1;
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (
			profile
			and unit and UnitIsConnected(unit)
			and UnBotSpecSummonNormalize(profile.className) == "warlock"
			and not (UnBotBuffCycle.cleanup and UnBotBuffCycle.cleanup[name])
		) then
			local gearScore = tonumber(profile.gearScore) or 0;
			if (
				not bestName
				or gearScore > bestGearScore
				or (gearScore == bestGearScore and string.lower(name) < string.lower(bestName))
			) then
				bestName = name;
				bestGearScore = gearScore;
			end
		end
	end);
	return bestName;
end

local function UnBotWarlockGroupBuffMissing()
	local missing = {};
	if (UnBotBuffCycleRaidSize() <= 10) then
		for _, buff in ipairs(UnBotWarlockGroupBuffAuras) do
			if (UnBotBuffCycleBuffAvailable(buff) and not UnBotBuffCyclePlayerHasBuff(buff)) then
				table.insert(missing, buff);
			end
		end
	end
	return missing, false;
end

local function UnBotWarlockGroupBuffBuildQueue(initial)
	local name = UnBotWarlockGroupBuff.activeName;
	if (not name or not UnBotSpecSummonIsInGroup(name)) then
		return false;
	end
	local missing, soulstoneMissing = UnBotWarlockGroupBuffMissing();
	local queue = {};
	if (initial) then
		table.insert(queue, "summon");
		table.insert(queue, "stay");
	end
	for _, buff in ipairs(missing) do
		table.insert(queue, buff.command);
	end
	UnBotWarlockGroupBuff.soulstoneAttempt = 0;
	if (#queue == 0) then
		UnBotWarlockGroupBuff.stage = "idle";
		UnBotWarlockGroupBuff.nextCheck = GetTime() + 5;
		return false;
	end
	UnBotWarlockGroupBuff.queue = queue;
	UnBotWarlockGroupBuff.queueIndex = 1;
	UnBotWarlockGroupBuff.stage = "send";
	UnBotWarlockGroupBuff.nextTime = GetTime();
	return true;
end

local function UnBotWarlockGroupBuffResetSoulstoneSearch(clearTried)
	UnBotWarlockGroupBuff.soulstoneStrategyName = nil;
	UnBotWarlockGroupBuff.soulstoneStrategyAt = 0;
	UnBotWarlockGroupBuff.soulstonePendingLogged = false;
	UnBotWarlockGroupBuff.soulstonePendingSince = 0;
	UnBotWarlockGroupBuff.soulstoneReplacementName = nil;
	UnBotWarlockGroupBuff.soulstoneReplacementOldName = nil;
	UnBotWarlockGroupBuff.soulstoneReplacementUntil = 0;
	UnBotWarlockGroupBuff.soulstoneReplacementCount = 0;
	UnBotWarlockGroupBuff.soulstoneReplacementExhausted = false;
	if (clearTried) then
		UnBotWarlockGroupBuff.soulstoneTriedNames = {};
	end
end

local function UnBotWarlockGroupBuffTryReplacement(now)
	local oldName = UnBotWarlockGroupBuff.activeName;
	if (
		not oldName
		or not UnBotBuffCycle.keptRegistryNames[oldName]
		or UnBotWarlockGroupBuff.soulstoneReplacementExhausted
		or (UnBotWarlockGroupBuff.soulstoneReplacementCount or 0) >= 4
	) then
		return false;
	end
	if (UnBotBuffCycleRaidSize() >= 25) then
		UnBotWarlockGroupBuff.soulstoneReplacementExhausted = true;
		UnBotSpecSummonMessage(
			"Soulstone: замена варлока пропущена — рейд заполнен 25/25. "
			.."Лишний бот за пределами инстанса вызываться не будет."
		);
		return false;
	end
	UnBotWarlockGroupBuff.soulstoneTriedNames[oldName] = true;
	local candidates = UnBotRegistryCandidates(
		"warlock",
		{"demonology"},
		UnBotWarlockGroupBuff.soulstoneTriedNames
	);
	local name = candidates[1];
	if (not name) then
		UnBotWarlockGroupBuff.soulstoneReplacementExhausted = true;
		UnBotSpecSummonMessage(
			"Soulstone: все сохранённые Demonology Warlock уже проверены; "
			.."текущий варлок продолжит ждать cooldown."
		);
		return false;
	end
	UnBotWarlockGroupBuff.soulstoneTriedNames[name] = true;
	UnBotWarlockGroupBuff.soulstoneReplacementCount =
		(UnBotWarlockGroupBuff.soulstoneReplacementCount or 0) + 1;
	UnBotWarlockGroupBuff.soulstoneReplacementName = name;
	UnBotWarlockGroupBuff.soulstoneReplacementOldName = oldName;
	UnBotWarlockGroupBuff.soulstoneReplacementUntil = now + 12;
	UnBotWarlockGroupBuff.stage = "wait_soulstone_replacement";
	UnBotWarlockGroupBuff.nextTime = now + 0.5;
	UnBotBuffCycleSendSay(".playerbot bot add "..name);
	UnBotSpecSummonMessage(
		"Soulstone: у "..oldName.." камень не готов; пробуем "..name
		.." ("..tostring(UnBotWarlockGroupBuff.soulstoneReplacementCount).."/4)."
	);
	return true;
end

local function UnBotWarlockGroupBuffAutomationBusy()
	return (
		(UnBotBotScanner and UnBotBotScanner.active)
		or (UnBotJunkCleaner and UnBotJunkCleaner.active)
		or (UnBotFastJunkRaid and UnBotFastJunkRaid.active)
		or (UnBotSoulstoneTest.active and UnBotSoulstoneTest.stage ~= "passed")
		or (UnBotSindragosaPrep and UnBotSindragosaPrep.maintenance)
		or UnBotBuffCycle.active
		or UnBotSpecSummon.active
	);
end

local warlockGroupBuffFrame = CreateFrame("Frame", "UnBotWarlockGroupBuffFrame");
warlockGroupBuffFrame:SetScript("OnUpdate", function()
	local now = GetTime();
	if (now < (UnBotWarlockGroupBuff.nextTime or 0)) then
		return;
	end
	local playerLevel = UnBotBuffCyclePlayerLevel();
	if (playerLevel ~= UnBotWarlockGroupBuff.lastPlayerLevel) then
		UnBotWarlockGroupBuff.lastPlayerLevel = playerLevel;
		UnBotWarlockGroupBuff.retryRound = 0;
		UnBotWarlockGroupBuff.suppressedUntil = 0;
		UnBotWarlockGroupBuff.cooldownUntil = 0;
		UnBotWarlockGroupBuffResetSoulstoneSearch(true);
	end
	if (
		UnBotWarlockGroupBuffAutomationBusy()
		or (InCombatLockdown and InCombatLockdown())
		or (UnitAffectingCombat and UnitAffectingCombat("player"))
	) then
		UnBotWarlockGroupBuff.nextTime = now + 1;
		return;
	end
	if (not UnBotWarlockGroupBuffHasAvailable()) then
		UnBotWarlockGroupBuff.activeName = nil;
		UnBotWarlockGroupBuff.stage = "idle";
		UnBotWarlockGroupBuff.queue = {};
		UnBotWarlockGroupBuff.soulstoneAttempt = 0;
		UnBotWarlockGroupBuff.retryRound = 0;
		UnBotWarlockGroupBuff.suppressedUntil = 0;
		UnBotWarlockGroupBuffResetSoulstoneSearch(true);
		UnBotWarlockGroupBuff.nextCheck = now + 5;
		UnBotWarlockGroupBuff.nextTime = now + 5;
		return;
	end
	if (now < (UnBotWarlockGroupBuff.suppressedUntil or 0)) then
		UnBotWarlockGroupBuff.nextTime = UnBotWarlockGroupBuff.suppressedUntil;
		return;
	end
	if (UnBotWarlockGroupBuff.stage == "wait_soulstone_replacement") then
		local replacementName = UnBotWarlockGroupBuff.soulstoneReplacementName;
		local oldName = UnBotWarlockGroupBuff.soulstoneReplacementOldName;
		if (UnBotBuffCyclePlayerHasBuff(UnBotSoulstoneTestAura)) then
			UnBotRegistryMarkSoulstoneCooldown(UnBotSoulstoneAuraCasterName(oldName));
			if (replacementName and UnBotSpecSummonIsInGroup(replacementName)) then
				UnBotSpecSummonUninvite(replacementName);
				UnBotBuffCycle.cleanup[replacementName] = {
					removeSent = false,
					nextTime = now + 0.5,
					untilTime = now + 30,
				};
			elseif (replacementName) then
				UnBotBuffCycleSendSay(".playerbot bot remove "..replacementName);
			end
			UnBotWarlockGroupBuff.stage = "idle";
			UnBotWarlockGroupBuff.soulstoneReplacementName = nil;
			UnBotWarlockGroupBuff.soulstoneReplacementOldName = nil;
			UnBotWarlockGroupBuff.soulstonePendingSince = 0;
			UnBotWarlockGroupBuff.nextCheck = now + 5;
			UnBotWarlockGroupBuff.nextTime = now + 5;
			UnBotSpecSummonMessage("Soulstone confirmed from "..tostring(oldName).."; replacement cancelled.");
		elseif (replacementName and UnBotSpecSummonIsInGroup(replacementName)) then
			UnBotBuffCycle.keptRegistryNames[replacementName] = true;
			UnBotBuffCycle.summoned[replacementName] = true;
			UnBotRememberKnownBot(replacementName);
			local summonCount = UnBotRegistryRecordGameplaySummon(replacementName, "soulstone-replacement");
			if (oldName and oldName ~= replacementName and UnBotSpecSummonIsInGroup(oldName)) then
				UnBotBuffCycle.keptRegistryNames[oldName] = nil;
				UnBotSpecSummonUninvite(oldName);
				UnBotBuffCycle.cleanup[oldName] = {
					removeSent = false,
					nextTime = now + 0.5,
					untilTime = now + 30,
				};
			end
			UnBotWarlockGroupBuff.activeName = replacementName;
			UnBotWarlockGroupBuff.stage = "wait_soulstone_replacement_reset";
			UnBotWarlockGroupBuff.soulstoneStrategyName = nil;
			UnBotWarlockGroupBuff.soulstoneStrategyAt = 0;
			UnBotWarlockGroupBuff.soulstonePendingLogged = false;
			UnBotWarlockGroupBuff.soulstonePendingSince = 0;
			UnBotWarlockGroupBuff.soulstoneReplacementName = nil;
			UnBotWarlockGroupBuff.soulstoneReplacementOldName = nil;
			UnBotBuffCycleSendWhisper(replacementName, "summon");
			UnBotBuffCycleSendWhisper(replacementName, "stay");
			UnBotBuffCycleSendWhisper(replacementName, "reset botAI");
			UnBotWarlockGroupBuff.nextTime = now + 1;
			UnBotSpecSummonMessage(
				"Soulstone: replacement Warlock ready ("..replacementName
				..", summons "..tostring(summonCount or "?")..")."
			);
		elseif (now >= (UnBotWarlockGroupBuff.soulstoneReplacementUntil or 0)) then
			if (replacementName) then
				UnBotBuffCycleSendSay(".playerbot bot remove "..replacementName);
			end
			UnBotWarlockGroupBuff.stage = "idle";
			UnBotWarlockGroupBuff.soulstoneReplacementName = nil;
			UnBotWarlockGroupBuff.soulstoneReplacementOldName = nil;
			UnBotWarlockGroupBuff.soulstonePendingSince = now - 15;
			UnBotWarlockGroupBuff.nextTime = now;
			if (not UnBotWarlockGroupBuffTryReplacement(now)) then
				UnBotWarlockGroupBuff.nextCheck = now + 5;
				UnBotWarlockGroupBuff.nextTime = now + 5;
			end
		else
			UnBotWarlockGroupBuff.nextTime = now + 0.5;
		end
		return;
	elseif (UnBotWarlockGroupBuff.stage == "wait_soulstone_replacement_reset") then
		UnBotWarlockGroupBuffBuildQueue(false);
		return;
	end

	local name = UnBotWarlockGroupBuffFind();
	if (not name) then
		UnBotWarlockGroupBuff.activeName = nil;
		UnBotWarlockGroupBuff.stage = "idle";
		UnBotWarlockGroupBuff.queue = {};
		UnBotWarlockGroupBuff.soulstoneAttempt = 0;
		UnBotWarlockGroupBuff.retryRound = 0;
		UnBotWarlockGroupBuff.suppressedUntil = 0;
		UnBotWarlockGroupBuffResetSoulstoneSearch(true);
		UnBotWarlockGroupBuff.nextTime = now + 2;
		return;
	end
	if (name ~= UnBotWarlockGroupBuff.activeName) then
		UnBotWarlockGroupBuff.activeName = name;
		UnBotWarlockGroupBuff.stage = "idle";
		UnBotWarlockGroupBuff.soulstoneAttempt = 0;
		UnBotWarlockGroupBuff.cooldownUntil = 0;
		UnBotWarlockGroupBuff.retryRound = 0;
		UnBotWarlockGroupBuff.suppressedUntil = 0;
		UnBotWarlockGroupBuffResetSoulstoneSearch(true);
		UnBotWarlockGroupBuff.soulstoneTriedNames[name] = true;
		UnBotSpecSummonMessage(
			"Warlock group buffs: "..name
			.." will maintain only buffs available at player level "
			..tostring(UnBotBuffCyclePlayerLevel()).."."
		);
		UnBotWarlockGroupBuffBuildQueue(true);
	end

	if (UnBotWarlockGroupBuff.stage == "send") then
		local command = UnBotWarlockGroupBuff.queue[UnBotWarlockGroupBuff.queueIndex];
		if (command) then
			UnBotBuffCycleSendWhisper(name, command);
			UnBotWarlockGroupBuff.queueIndex = UnBotWarlockGroupBuff.queueIndex + 1;
			UnBotWarlockGroupBuff.nextTime = now + 0.7;
		else
			UnBotWarlockGroupBuff.stage = "verify";
			UnBotWarlockGroupBuff.nextTime = now + 4;
		end
	elseif (UnBotWarlockGroupBuff.stage == "verify") then
		local missing, soulstoneMissing = UnBotWarlockGroupBuffMissing();
		if (#missing == 0 and not soulstoneMissing) then
			UnBotSpecSummonMessage("Warlock group buffs confirmed from "..name..".");
			UnBotWarlockGroupBuff.stage = "idle";
			UnBotWarlockGroupBuff.retryRound = 0;
			UnBotWarlockGroupBuff.suppressedUntil = 0;
			UnBotWarlockGroupBuff.soulstonePendingLogged = false;
			UnBotWarlockGroupBuff.soulstonePendingSince = 0;
			UnBotWarlockGroupBuff.nextCheck = now + 5;
			UnBotWarlockGroupBuff.nextTime = now + 5;
		elseif (
			#missing == 0
			and soulstoneMissing
			and UnBotWarlockGroupBuff.soulstoneStrategyName == name
		) then
			UnBotWarlockGroupBuff.stage = "idle";
			UnBotWarlockGroupBuff.retryRound = 0;
			UnBotWarlockGroupBuff.nextCheck = now + 5;
			UnBotWarlockGroupBuff.nextTime = now + 5;
			if (not UnBotWarlockGroupBuff.soulstonePendingLogged) then
				UnBotWarlockGroupBuff.soulstonePendingLogged = true;
				UnBotSpecSummonMessage(
					"Soulstone pending from "..name
					..": strategy is enabled; waiting for the existing stone cooldown."
				);
			end
		else
			UnBotWarlockGroupBuff.retryRound = (UnBotWarlockGroupBuff.retryRound or 0) + 1;
			if (UnBotWarlockGroupBuff.retryRound >= 3) then
				UnBotWarlockGroupBuff.stage = "idle";
				UnBotWarlockGroupBuff.queue = {};
				UnBotWarlockGroupBuff.soulstoneAttempt = 0;
				UnBotWarlockGroupBuff.suppressedUntil = now + 300;
				UnBotWarlockGroupBuff.nextCheck = UnBotWarlockGroupBuff.suppressedUntil;
				UnBotWarlockGroupBuff.nextTime = UnBotWarlockGroupBuff.suppressedUntil;
				UnBotSpecSummonMessage(
					"Warlock group buffs: недоступные баффы больше не повторяются; "
					.."следующая проверка через 5 минут или после повышения уровня."
				);
			else
				UnBotWarlockGroupBuffBuildQueue(false);
				if (UnBotWarlockGroupBuff.stage == "idle") then
					UnBotWarlockGroupBuff.nextTime = math.max(
						now + 5,
						UnBotWarlockGroupBuff.cooldownUntil or 0
					);
				end
			end
		end
	elseif (now >= (UnBotWarlockGroupBuff.nextCheck or 0)) then
		local missing, soulstoneMissing = UnBotWarlockGroupBuffMissing();
		if (
			#missing == 0
			and soulstoneMissing
			and (UnBotWarlockGroupBuff.soulstonePendingSince or 0) > 0
			and now >= UnBotWarlockGroupBuff.soulstonePendingSince + 15
			and UnBotWarlockGroupBuffTryReplacement(now)
		) then
			return;
		end
		if (now >= (UnBotWarlockGroupBuff.cooldownUntil or 0)) then
			UnBotWarlockGroupBuffBuildQueue(false);
		end
		UnBotWarlockGroupBuff.nextTime = math.max(
			now + 1,
			UnBotWarlockGroupBuff.cooldownUntil or 0
		);
	end
end);

