_G.UnBotJunkCleaner = UnBotJunkCleaner;

-- Реальная скорость серверных операций заметно различается между серверами и
-- даже между запусками. Поэтому сохраняем отдельное обучаемое среднее для
-- каждого режима, а не обещаем пользователю фиксированное время.
UnBotServiceTiming = UnBotServiceTiming or {};
UnBotServiceTiming.defaults = UnBotServiceTiming.defaults or {
	standard = 52,
	deep = 70,
	bags = 20,
	fast = 4,
};

function UnBotServiceTiming.Get(mode)
	UnBotSquadConfig = UnBotSquadConfig or {};
	UnBotSquadConfig.botServiceTiming =
		type(UnBotSquadConfig.botServiceTiming) == "table"
		and UnBotSquadConfig.botServiceTiming or {};
	local key = UnBotServiceTiming.defaults[mode] and mode or "standard";
	local entry = UnBotSquadConfig.botServiceTiming[key];
	if (type(entry) ~= "table") then
		entry = {};
		UnBotSquadConfig.botServiceTiming[key] = entry;
	end
	entry.avgSeconds = math.max(1, tonumber(entry.avgSeconds)
		or UnBotServiceTiming.defaults[key]);
	entry.samples = math.max(0, tonumber(entry.samples) or 0);
	return entry;
end

function UnBotServiceTiming.Record(mode, seconds, weight)
	local value = tonumber(seconds);
	if (not value or value < 1 or value > 900) then
		return;
	end
	local entry = UnBotServiceTiming.Get(mode);
	local oldWeight = math.min(200, tonumber(entry.samples) or 0);
	local addedWeight = math.min(
		math.max(0, 200 - oldWeight),
		math.max(1, tonumber(weight) or 1)
	);
	if (addedWeight == 0) then
		-- После двухсот замеров продолжаем медленно адаптироваться к серверу.
		oldWeight = 199;
		addedWeight = 1;
	end
	entry.avgSeconds = ((entry.avgSeconds * oldWeight) + (value * addedWeight))
		/ (oldWeight + addedWeight);
	entry.samples = math.min(200, oldWeight + addedWeight);
	entry.updatedAt = time();
end

function UnBotServiceTiming.RecordAggregate(mode, totalSeconds, botCount)
	local count = math.max(0, tonumber(botCount) or 0);
	if (count > 0) then
		UnBotServiceTiming.Record(mode, (tonumber(totalSeconds) or 0) / count, count);
	end
end

function UnBotServiceTiming.Format(seconds)
	local value = math.max(0, math.floor((tonumber(seconds) or 0) + 0.5));
	local hours = math.floor(value / 3600);
	local minutes = math.floor((value % 3600) / 60);
	local secs = value % 60;
	if (hours > 0) then
		return tostring(hours).." ч "..tostring(minutes).." мин";
	end
	if (minutes > 0) then
		return tostring(minutes).." мин "..tostring(secs).." сек";
	end
	return tostring(secs).." сек";
end

function UnBotServiceTiming.EstimateText(mode, botCount)
	local entry = UnBotServiceTiming.Get(mode);
	local count = math.max(0, tonumber(botCount) or 0);
	local prefix = entry.samples > 0 and "примерно " or "предварительно примерно ";
	return prefix..UnBotServiceTiming.Format(entry.avgSeconds * count)
		.."; среднее "..UnBotServiceTiming.Format(entry.avgSeconds).."/бот; замеров "
		..tostring(entry.samples);
end

function UnBotServiceTiming.ActiveText(mode, state)
	if (not mode or type(state) ~= "table") then
		return nil;
	end
	local entry = UnBotServiceTiming.Get(mode);
	local remaining;
	local overdue = false;
	if (mode == "fast") then
		local total = #(state.queue or {});
		local predicted = entry.avgSeconds * total;
		local elapsed = state.runStartedAt and state.runStartedAt > 0
			and math.max(0, GetTime() - state.runStartedAt) or 0;
		remaining = math.max(0, predicted - elapsed);
		overdue = elapsed > predicted;
	else
		local index = math.max(0, tonumber(state.index) or 0);
		remaining = math.max(0, #(state.queue or {}) - index) * entry.avgSeconds;
		if (state.currentStartedAt and state.currentStartedAt > 0) then
			local currentElapsed = GetTime() - state.currentStartedAt;
			remaining = remaining + math.max(0, entry.avgSeconds - currentElapsed);
			overdue = currentElapsed > entry.avgSeconds;
		end
	end
	return (overdue and "прогноз превышен; далее ~" or "осталось ~")
		..UnBotServiceTiming.Format(remaining)
		.." | среднее "..UnBotServiceTiming.Format(entry.avgSeconds).."/бот ("
		..tostring(entry.samples).." замеров)";
end

function UnBotServiceTiming.RunSummary(mode, startedAt)
	local elapsed = startedAt and startedAt > 0 and math.max(0, GetTime() - startedAt) or 0;
	local entry = UnBotServiceTiming.Get(mode);
	return "Фактическое время: "..UnBotServiceTiming.Format(elapsed)
		.."; сохранённое среднее "..UnBotServiceTiming.Format(entry.avgSeconds)
		.."/бот ("..tostring(entry.samples).." замеров).";
end

UnBotJunkCleanerCheckpoint = UnBotJunkCleanerCheckpoint or {};

function UnBotJunkCleanerCheckpoint.GetActive()
	local checkpoint = UnBotSquadConfig and UnBotSquadConfig.junkMaintenanceCheckpoint;
	if (
		type(checkpoint) ~= "table"
		or not checkpoint.active
		or type(checkpoint.names) ~= "table"
		or not next(checkpoint.names)
	) then
		return nil;
	end
	checkpoint.completed = type(checkpoint.completed) == "table"
		and checkpoint.completed or {};
	return checkpoint;
end

function UnBotJunkCleanerCheckpoint.Create(names, mode)
	UnBotSquadConfig = UnBotSquadConfig or {};
	local checkpoint = {
		schemaVersion = 2,
		active = true,
		mode = mode,
		startedAt = time(),
		updatedAt = time(),
		total = 0,
		completedCount = 0,
		names = {},
		completed = {},
	};
	for _, name in ipairs(names or {}) do
		if (
			UnBotIsValidBotName(name)
			and UnBotBotRegistry
			and UnBotBotRegistry.bots
			and UnBotBotRegistry.bots[name]
			and not checkpoint.names[name]
		) then
			checkpoint.names[name] = true;
			checkpoint.total = checkpoint.total + 1;
		end
	end
	if (checkpoint.total == 0) then
		checkpoint.active = false;
		checkpoint.finishedAt = time();
	end
	UnBotSquadConfig.junkMaintenanceCheckpoint = checkpoint;
	return checkpoint;
end

function UnBotJunkCleanerCheckpoint.Complete(name, profile)
	local checkpoint = UnBotJunkCleanerCheckpoint.GetActive();
	if (not checkpoint or not checkpoint.names[name] or not profile) then
		return false;
	end
	local snapshot = {
		completedAt = time(),
		junkSoldAt = profile.junkSoldAt,
		junkSoldSummonCount = profile.junkSoldSummonCount,
		reagentCountsAt = profile.reagentCountsAt,
		reagentCounts = {},
		freeBagSlots = profile.freeBagSlots,
		bagSlotsUsed = profile.bagSlotsUsed,
		bagSlotsTotal = profile.bagSlotsTotal,
		bagSpaceCheckedAt = profile.bagSpaceCheckedAt,
		lastReagentRestockAt = profile.lastReagentRestockAt,
		lastReagentRestockCount = profile.lastReagentRestockCount,
	};
	for itemId, count in pairs(profile.reagentCounts or {}) do
		if (tonumber(itemId)) then
			snapshot.reagentCounts[tonumber(itemId)] = math.max(0, tonumber(count) or 0);
		end
	end
	if (not checkpoint.completed[name]) then
		checkpoint.completedCount = (tonumber(checkpoint.completedCount) or 0) + 1;
	end
	checkpoint.completed[name] = snapshot;
	checkpoint.lastCompletedName = name;
	checkpoint.updatedAt = time();
	profile.forceJunkCycle = nil;
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	return true;
end

function UnBotJunkCleanerCheckpoint.FinishRun()
	local checkpoint = UnBotJunkCleanerCheckpoint.GetActive();
	if (not checkpoint) then
		return 0, 0, false;
	end
	local total = 0;
	local completed = 0;
	for name in pairs(checkpoint.names or {}) do
		if (UnBotBotRegistry.bots and UnBotBotRegistry.bots[name]) then
			total = total + 1;
			if (checkpoint.completed and checkpoint.completed[name]) then
				completed = completed + 1;
			end
		end
	end
	checkpoint.total = total;
	checkpoint.completedCount = completed;
	checkpoint.updatedAt = time();
	local pending = math.max(0, total - completed);
	if (pending == 0) then
		checkpoint.active = false;
		checkpoint.finishedAt = time();
	end
	return completed, pending, true;
end

function UnBotJunkCleanerCheckpoint.Restore()
	local checkpoint = UnBotJunkCleanerCheckpoint.GetActive();
	if (not checkpoint) then
		return 0;
	end
	local restored = 0;
	for name, snapshot in pairs(checkpoint.completed or {}) do
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (profile and type(snapshot) == "table") then
			if (
				(tonumber(snapshot.junkSoldAt) or 0)
				>= (tonumber(profile.junkSoldAt) or 0)
			) then
				profile.junkSoldAt = snapshot.junkSoldAt;
				profile.junkSoldSummonCount = snapshot.junkSoldSummonCount;
			end
			if (
				(tonumber(snapshot.reagentCountsAt) or 0)
				>= (tonumber(profile.reagentCountsAt) or 0)
			) then
				profile.reagentCounts = profile.reagentCounts or {};
				for itemId, count in pairs(snapshot.reagentCounts or {}) do
					if (tonumber(itemId)) then
						profile.reagentCounts[tonumber(itemId)] =
							math.max(0, tonumber(count) or 0);
						profile.reagentCounts[tostring(itemId)] = nil;
					end
				end
				profile.reagentCountsAt = snapshot.reagentCountsAt;
			end
			if (
				(tonumber(snapshot.bagSpaceCheckedAt) or 0)
				>= (tonumber(profile.bagSpaceCheckedAt) or 0)
			) then
				profile.freeBagSlots = snapshot.freeBagSlots;
				profile.bagSlotsUsed = snapshot.bagSlotsUsed;
				profile.bagSlotsTotal = snapshot.bagSlotsTotal;
				profile.bagSpaceCheckedAt = snapshot.bagSpaceCheckedAt;
			end
			if (
				(tonumber(snapshot.lastReagentRestockAt) or 0)
				>= (tonumber(profile.lastReagentRestockAt) or 0)
			) then
				profile.lastReagentRestockAt = snapshot.lastReagentRestockAt;
				profile.lastReagentRestockCount = snapshot.lastReagentRestockCount;
			end
			profile.forceJunkCycle = nil;
			restored = restored + 1;
		end
	end
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	return restored;
end

function UnBotJunkCleanerCheckpoint.AdoptLegacyForced()
	if (UnBotJunkCleanerCheckpoint.GetActive()) then
		return 0;
	end
	local names = {};
	for name, profile in pairs((UnBotBotRegistry and UnBotBotRegistry.bots) or {}) do
		if (
			UnBotIsValidBotName(name)
			and profile
			and not UnBotIsAccountAltProfile(name, profile)
			and profile.forceJunkCycle
		) then
			table.insert(names, name);
		end
	end
	if (#names > 0) then
		UnBotJunkCleanerCheckpoint.Create(names);
	end
	return #names;
end

UnBotBagSpaceAuditCheckpoint = UnBotBagSpaceAuditCheckpoint or {};

function UnBotBagSpaceAuditCheckpoint.GetActive()
	local checkpoint = UnBotSquadConfig and UnBotSquadConfig.bagSpaceAuditCheckpoint;
	if (
		type(checkpoint) ~= "table"
		or not checkpoint.active
		or type(checkpoint.names) ~= "table"
		or not next(checkpoint.names)
	) then
		return nil;
	end
	checkpoint.completed = type(checkpoint.completed) == "table"
		and checkpoint.completed or {};
	return checkpoint;
end

function UnBotBagSpaceAuditCheckpoint.Create(names)
	UnBotSquadConfig = UnBotSquadConfig or {};
	local checkpoint = {
		schemaVersion = 1,
		active = true,
		startedAt = time(),
		updatedAt = time(),
		total = 0,
		completedCount = 0,
		names = {},
		completed = {},
	};
	for _, name in ipairs(names or {}) do
		if (
			UnBotIsValidBotName(name)
			and UnBotBotRegistry
			and UnBotBotRegistry.bots
			and UnBotBotRegistry.bots[name]
			and not checkpoint.names[name]
		) then
			checkpoint.names[name] = true;
			checkpoint.total = checkpoint.total + 1;
		end
	end
	if (checkpoint.total == 0) then
		checkpoint.active = false;
		checkpoint.finishedAt = time();
	end
	UnBotSquadConfig.bagSpaceAuditCheckpoint = checkpoint;
	return checkpoint;
end

function UnBotBagSpaceAuditCheckpoint.Complete(name, profile)
	local checkpoint = UnBotBagSpaceAuditCheckpoint.GetActive();
	if (
		not checkpoint
		or not checkpoint.names[name]
		or not profile
		or profile.freeBagSlots == nil
	) then
		return false;
	end
	if (not checkpoint.completed[name]) then
		checkpoint.completedCount = (tonumber(checkpoint.completedCount) or 0) + 1;
	end
	checkpoint.completed[name] = {
		completedAt = time(),
		freeBagSlots = profile.freeBagSlots,
		bagSlotsUsed = profile.bagSlotsUsed,
		bagSlotsTotal = profile.bagSlotsTotal,
		bagSpaceCheckedAt = profile.bagSpaceCheckedAt,
	};
	checkpoint.lastCompletedName = name;
	checkpoint.updatedAt = time();
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	return true;
end

function UnBotBagSpaceAuditCheckpoint.FinishRun()
	local checkpoint = UnBotBagSpaceAuditCheckpoint.GetActive();
	if (not checkpoint) then
		return 0, 0, false;
	end
	local total = 0;
	local completed = 0;
	for name in pairs(checkpoint.names or {}) do
		if (UnBotBotRegistry.bots and UnBotBotRegistry.bots[name]) then
			total = total + 1;
			if (checkpoint.completed and checkpoint.completed[name]) then
				completed = completed + 1;
			end
		end
	end
	checkpoint.total = total;
	checkpoint.completedCount = completed;
	checkpoint.updatedAt = time();
	local pending = math.max(0, total - completed);
	if (pending == 0) then
		checkpoint.active = false;
		checkpoint.finishedAt = time();
	end
	return completed, pending, true;
end

function UnBotBagSpaceAuditCheckpoint.Restore()
	local checkpoint = UnBotBagSpaceAuditCheckpoint.GetActive();
	if (not checkpoint) then
		return 0;
	end
	local restored = 0;
	for name, snapshot in pairs(checkpoint.completed or {}) do
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (
			profile
			and type(snapshot) == "table"
			and (tonumber(snapshot.bagSpaceCheckedAt) or 0)
				>= (tonumber(profile.bagSpaceCheckedAt) or 0)
		) then
			profile.freeBagSlots = snapshot.freeBagSlots;
			profile.bagSlotsUsed = snapshot.bagSlotsUsed;
			profile.bagSlotsTotal = snapshot.bagSlotsTotal;
			profile.bagSpaceCheckedAt = snapshot.bagSpaceCheckedAt;
			restored = restored + 1;
		end
	end
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	return restored;
end

UnBotJunkCleanerCleanupCurrent = nil;

function UnBotJunkCleanerReopenMerchant()
	if (MerchantFrame and MerchantFrame:IsShown()) then
		return true;
	end
	if (TradeFrame and TradeFrame:IsShown() and CancelTrade) then
		CancelTrade();
	end

	local merchantName = UnBotJunkCleaner.merchantName;
	if (merchantName and merchantName ~= "" and TargetByName) then
		TargetByName(merchantName, true);
	end
	if (
		merchantName
		and UnitExists("target")
		and UnitName("target") == merchantName
		and InteractUnit
	) then
		pcall(InteractUnit, "target");
	end
	return MerchantFrame and MerchantFrame:IsShown();
end

