	dk = {
		{ id = 37201, label = "Corpse Dust", target = 10 },
	},
	druid = {
		{ id = 44614, label = "Starleaf Seed", target = 10 },
		{ id = 44605, label = "Wild Spineleaf", target = 20 },
	},
	mage = {
		{ id = 17031, label = "Rune of Teleportation", target = 5 },
		{ id = 17032, label = "Rune of Portals", target = 5 },
		{ id = 17020, label = "Arcane Powder", target = 20 },
	},
	paladin = {
		{ id = 21177, label = "Symbol of Kings", target = 200 },
	},
	priest = {
		{ id = 44615, label = "Devout Candle", target = 40 },
	},
	shaman = {
		{ id = 17030, label = "Ankh", target = 5 },
	},
};

function UnBotReagentTargetGet(className, itemId, defaultTarget)
	UnBotSquadConfig = UnBotSquadConfig or {};
	UnBotSquadConfig.reagentTargets = UnBotSquadConfig.reagentTargets or {};
	className = UnBotSpecSummonNormalize(className);
	local classTargets = UnBotSquadConfig.reagentTargets[className];
	local saved = classTargets and classTargets[tonumber(itemId)];
	if (saved == nil and classTargets) then
		saved = classTargets[tostring(itemId)];
	end
	local value = tonumber(saved);
	if (value == nil) then
		value = tonumber(defaultTarget) or 0;
	end
	return math.max(0, math.min(5000, math.floor(value)));
end

function UnBotReagentTargetSet(className, itemId, value)
	UnBotSquadConfig = UnBotSquadConfig or {};
	UnBotSquadConfig.reagentTargets = UnBotSquadConfig.reagentTargets or {};
	className = UnBotSpecSummonNormalize(className);
	if (className == "" or not tonumber(itemId)) then
		return nil;
	end
	UnBotSquadConfig.reagentTargets[className] =
		UnBotSquadConfig.reagentTargets[className] or {};
	value = math.max(0, math.min(5000, math.floor(tonumber(value) or 0)));
	UnBotSquadConfig.reagentTargets[className][tonumber(itemId)] = value;
	UnBotSquadConfig.reagentTargets[className][tostring(itemId)] = nil;
	return value;
end

function UnBotRegistryStoreReagentCount(name, itemId, count)
	local profile = name and UnBotBotRegistry and UnBotBotRegistry.bots
		and UnBotBotRegistry.bots[name];
	if (not profile or not tonumber(itemId)) then
		return;
	end
	profile.reagentCounts = profile.reagentCounts or {};
	profile.reagentCounts[tonumber(itemId)] = math.max(0, tonumber(count) or 0);
	profile.reagentCounts[tostring(itemId)] = nil;
	profile.reagentCountsAt = time();
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
end

function UnBotRegistryNeedsReagentRestock(profile, offered)
	if (not profile or UnBotIsAccountAltProfile(profile.name, profile)) then
		return false;
	end
	local className = UnBotSpecSummonNormalize(profile.className);
	for _, wanted in ipairs(UnBotJunkCleanerReagentTargets[className] or {}) do
		local target = UnBotReagentTargetGet(className, wanted.id, wanted.target);
		local supported = not offered or offered[wanted.id];
		if (supported and target > 0) then
			local saved = profile.reagentCounts and (
				profile.reagentCounts[wanted.id] or profile.reagentCounts[tostring(wanted.id)]
			);
			if (saved == nil or (tonumber(saved) or 0) < target) then
				return true;
			end
		end
	end
	return false;
end

function UnBotJunkCleanerIsProtectedReagent(itemId)
	if (tonumber(itemId) == 6948) then
		return true;
	end
	for _, classItems in pairs(UnBotJunkCleanerReagentTargets or {}) do
		for _, reagent in ipairs(classItems or {}) do
			if (tonumber(reagent.id) == tonumber(itemId)) then
				return true;
			end
		end
	end
	return false;
end

-- По умолчанию сохраняем все предметы, кроме проверенного запасного снаряжения.
-- Таблица на текущем контроллере: без новых верхнеуровневых locals и SavedVariables.
function UnBotJunkCleaner.IsProtectedItem(itemId, text)
	itemId = tonumber(itemId);
	if (UnBotJunkCleanerIsProtectedReagent(itemId)) then return true; end
	if (itemId and ((itemId >= 5175 and itemId <= 5178)
		or itemId == 2901 or itemId == 5956 or itemId == 7005
		or itemId == 6219 or itemId == 10498 or itemId == 39505
		or itemId == 40772 or itemId == 40892 or itemId == 40893)) then
		return true;
	end
	local rawText = tostring(text or "");
	text = string.lower(rawText);
	for _, word in ipairs({
		"totem", "Тотем", "тотем", "hearthstone", "soulbound", "quest item",
		"Персональный", "персональный", "Предмет для задания", "предмет для задания",
		"classes:", "class:", "Классы:", "классы:", "Класс:", "класс:",
		"begins a quest", "starts a quest", "Начинает задание", "начинает задание",
		"fishing", "mining", "skinning",
		"blacksmith", "engineering", "herbalism", "alchemy", "enchanting",
		"leatherworking", "tailoring", "inscription", "jewelcraft", "cooking", "first aid",
		"Рыб", "рыб", "Удоч", "удоч", "Горн", "горн", "Шкур", "шкур", "Кузнеч", "кузнеч",
		"Инженер", "инженер", "Травнич", "травнич", "Сбор трав", "сбор трав",
		"Алхим", "алхим", "Наложение чар", "наложение чар", "Наложения чар", "наложения чар",
		"Кожев", "кожев", "Портняж", "портняж", "Начерт", "начерт",
		"Ювелир", "ювелир", "Кулинар", "кулинар", "Первая помощь", "первая помощь",
		"Первой помощи", "первой помощи",
	}) do
		if (string.find(text, word, 1, true) or string.find(rawText, word, 1, true)) then return true; end
	end
	return false;
end

function UnBotJunkCleanerShouldExtendedSell(itemId, rawName, message, knownQuality, rawLink)
	local itemName, itemLink, quality, itemLevel, minLevel, itemType, itemSubType,
		stackCount, equipLoc = GetItemInfo(itemId);
	itemLink = itemLink or rawLink;
	if (UnBotJunkCleaner.IsProtectedItem(itemId,
		tostring(rawName or "").." "..tostring(itemName or "").." "..tostring(message or ""))) then
		return false, itemLink;
	end
	-- Без полного локального описания предмет не продаётся, даже если цвет известен.
	if (not itemName or not quality or quality < 1 or quality > 3) then
		return false, itemLink;
	end
	if (itemType ~= "Armor" and itemType ~= "Weapon"
		and itemType ~= "Доспехи" and itemType ~= "Оружие") then
		return false, itemLink;
	end
	if (not equipLoc or equipLoc == "" or equipLoc == "INVTYPE_RELIC"
		or equipLoc == "INVTYPE_BAG" or equipLoc == "INVTYPE_TABARD"
		or equipLoc == "INVTYPE_TRINKET"
		or UnBotJunkCleaner.IsProtectedItem(itemId, itemSubType)) then
		return false, itemLink;
	end
	-- Профессиональные инструменты бывают оружием, а классовые предметы — бронёй.
	-- Проверяем полную подсказку; отсутствие или ещё не загруженная подсказка — отказ.
	if (not UnBotJunkCleaner.saleTooltip) then
		UnBotJunkCleaner.saleTooltip = CreateFrame("GameTooltip", "UnBotJunkSaleTooltip", UIParent, "GameTooltipTemplate");
	end
	local tooltip = UnBotJunkCleaner.saleTooltip;
	tooltip:SetOwner(UIParent, "ANCHOR_NONE");
	tooltip:ClearLines();
	local ok = pcall(tooltip.SetHyperlink, tooltip, "item:"..tostring(itemId));
	local first = _G["UnBotJunkSaleTooltipTextLeft1"];
	local complete = ok and first and first:GetText() == itemName and tooltip:NumLines() > 1;
	local protected = false;
	if (complete) then
		for i = 1, tooltip:NumLines() do
			for _, side in ipairs({"Left", "Right"}) do
				local line = _G["UnBotJunkSaleTooltipText"..side..i];
				if (line and UnBotJunkCleaner.IsProtectedItem(itemId, line:GetText())) then
					protected = true;
				end
			end
		end
	end
	tooltip:Hide();
	return complete and not protected, itemLink;
end

function UnBotJunkCleaner.BeginProtectedRestock()
	UnBotJunkCleaner.merchantReagents, UnBotJunkCleaner.merchantReagentCount =
		UnBotJunkCleanerScanMerchantReagents();
	UnBotJunkCleaner.reagentQueue = UnBotJunkCleanerBuildReagentQueue(UnBotJunkCleaner.currentName);
	UnBotJunkCleaner.reagentIndex = 0;
	if (#UnBotJunkCleaner.reagentQueue > 0) then
		UnBotJunkCleaner.stage = "next_reagent";
		UnBotJunkCleaner.nextTime = GetTime() + 0.2;
	else
		UnBotJunkCleanerStartInventoryAuditOrFinish();
	end
end

function UnBotJunkCleanerScanMerchantReagents()
	local offered = {};
	local supported = {};
	for _, classItems in pairs(UnBotJunkCleanerReagentTargets) do
		for _, reagent in ipairs(classItems) do
			supported[reagent.id] = true;
		end
	end
	local count = GetMerchantNumItems and GetMerchantNumItems() or 0;
	for i = 1, count, 1 do
		local itemName, texture, price, quantity = GetMerchantItemInfo(i);
		local link = GetMerchantItemLink and GetMerchantItemLink(i);
		local itemId = link and tonumber(string.match(link, "item:(%d+)"));
		if (not itemId and itemName and GetItemInfo) then
			local cachedName, cachedLink = GetItemInfo(itemName);
			local cachedId = cachedLink and tonumber(string.match(cachedLink, "item:(%d+)"));
			if (cachedId and supported[cachedId]) then
				itemId = cachedId;
				link = cachedLink;
			else
				for supportedId in pairs(supported) do
					local supportedName, supportedLink = GetItemInfo(supportedId);
					if (supportedName and supportedName == itemName) then
						itemId = supportedId;
						link = supportedLink;
						break
					end
				end
			end
		end
		if (itemId and supported[itemId]) then
			if (not link or link == "") then
				link = "|Hitem:"..tostring(itemId)..":0:0:0:0:0:0:0|h["
					..tostring(itemName or itemId).."]|h";
			end
			offered[itemId] = {
				id = itemId,
				label = itemName or tostring(itemId),
				link = link,
				bundleSize = math.max(1, tonumber(quantity) or 1),
				merchantIndex = i,
			};
		end
	end
	local offeredCount = 0;
	for _ in pairs(offered) do
		offeredCount = offeredCount + 1;
	end
	return offered, offeredCount;
end

function UnBotJunkCleanerBuildReagentQueue(name)
	local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name] or {};
	local className = UnBotSpecSummonNormalize(profile.className);
	local classItems = UnBotJunkCleanerReagentTargets[className] or {};
	local queue = {};
	for _, wanted in ipairs(classItems) do
		local merchantItem = UnBotJunkCleaner.merchantReagents[wanted.id];
		if (merchantItem and merchantItem.link) then
			table.insert(queue, {
				id = wanted.id,
				label = merchantItem.label or wanted.label,
				link = merchantItem.link,
				target = UnBotReagentTargetGet(className, wanted.id, wanted.target),
				bundleSize = merchantItem.bundleSize or 1,
			});
		end
	end
	return queue;
end

function UnBotJunkCleanerFinishCurrent()
	local name = UnBotJunkCleaner.currentName;
	if (not name) then
		return;
	end
	UnBotRegistryRecordJunkSale(name);
	UnBotJunkCleaner.processed = UnBotJunkCleaner.processed + 1;
	local profile = UnBotBotRegistry.bots[name] or {};
	if ((UnBotJunkCleaner.currentRestocked or 0) > 0) then
		UnBotJunkCleaner.restockedBots = UnBotJunkCleaner.restockedBots + 1;
		profile.lastReagentRestockAt = time();
		profile.lastReagentRestockCount = UnBotJunkCleaner.currentRestocked;
		UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	end
	if (not UnBotJunkCleaner.currentGroupOnly) then
		UnBotJunkCleanerCheckpoint.Complete(name, profile);
	end
	UnBotSpecSummonMessage(
		"Хлам обработан: "..tostring(name).." | "
		..UnBotRegistryFlagTimeText(profile.junkSoldAt)
		.." | summons "..tostring(profile.summonCount or 0)
		.." | реагентов куплено "..tostring(UnBotJunkCleaner.currentRestocked or 0)
		..(UnBotJunkCleaner.currentGroupOnly
			and " | бот оставлен в текущей группе."
			or " | checkpoint сохранён.")
	);
	if (UnBotJunkCleaner.currentGroupOnly) then
		UnBotJunkCleanerStartNext();
		return;
	end
	UnBotJunkCleanerCleanupCurrent();
	UnBotJunkCleaner.stage = "wait_leave";
	UnBotJunkCleaner.nextTime = GetTime() + 0.5;
	UnBotJunkCleaner.stageUntil = GetTime() + 12;
end

function UnBotJunkCleanerRecordStatsLine(message)
	local text = string.lower(tostring(message or ""));
	-- Некоторые серверные сборки добавляют в whisper цветовые коды или иначе
	-- оформляют слово Bag. Для сумок надёжным признаком остаётся пара занято/всего.
	text = string.gsub(text, "|c%x%x%x%x%x%x%x%x", "");
	text = string.gsub(text, "|r", "");
	local used, total = string.match(text, "(%d+)%s*/%s*(%d+)%s+bag");
	if (not used or not total) then
		used, total = string.match(text, "(%d+)%s*/%s*(%d+)");
	end
	used = tonumber(used);
	total = tonumber(total);
	if (used and total and (total <= 0 or total > 500 or used < 0 or used > total)) then
		used = nil;
		total = nil;
	end
	local free = tonumber(string.match(text, "free%s+inventory%s+slots?[^%d]*(%d+)"))
		or tonumber(string.match(text, "free%s+inventory%s+space[^%d]*(%d+)"))
		or tonumber(string.match(text, "free%s+bag%s+slots?[^%d]*(%d+)"))
		or tonumber(string.match(text, "free%s+bag%s+space[^%d]*(%d+)"))
		or tonumber(string.match(text, "free%s+slots?[^%d]*(%d+)"))
		or tonumber(string.match(text, "(%d+)%s+free%s+inventory%s+slots?"))
		or tonumber(string.match(text, "(%d+)%s+free%s+slots?"));
	if (free == nil and used and total and total >= used) then
		free = total - used;
	end
	if (free == nil) then
		return false;
	end
	UnBotJunkCleaner.statsReceived = true;
	UnBotJunkCleaner.freeBagSlots = math.max(0, free);
	UnBotJunkCleaner.bagSlotsUsed = used;
	UnBotJunkCleaner.bagSlotsTotal = total;
	local name = UnBotJunkCleaner.currentName;
	local profile = name and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (profile) then
		profile.freeBagSlots = UnBotJunkCleaner.freeBagSlots;
		profile.bagSlotsUsed = used;
		profile.bagSlotsTotal = total;
		profile.bagSpaceCheckedAt = time();
		UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	end
	return true;
end

function UnBotJunkCleanerStatsSenderMatches(sender)
	local expected = UnBotSpecSummonNormalize(UnBotJunkCleaner.currentName);
	local actual = tostring(sender or "");
	actual = string.gsub(actual, "|c%x%x%x%x%x%x%x%x", "");
	actual = string.gsub(actual, "|r", "");
	-- На некоторых реалмах CHAT_MSG_WHISPER возвращает Имя-Реалм, хотя в
	-- ростере и реестре хранится только имя персонажа.
	actual = string.match(actual, "^([^-]+)") or actual;
	return expected ~= "" and UnBotSpecSummonNormalize(actual) == expected;
end

function UnBotJunkCleanerStartStatsOrFinish()
	if (UnBotJunkCleaner.statsRequested) then
		UnBotJunkCleanerFinishCurrent();
		return;
	end
	local name = UnBotJunkCleaner.currentName;
	if (not name) then
		UnBotJunkCleanerFinishCurrent();
		return;
	end
	UnBotJunkCleaner.statsRequested = true;
	UnBotJunkCleaner.statsAttempts = 1;
	UnBotJunkCleaner.statsReceived = false;
	UnBotJunkCleaner.freeBagSlots = nil;
	UnBotJunkCleaner.bagSlotsUsed = nil;
	UnBotJunkCleaner.bagSlotsTotal = nil;
	UnBotBuffCycleSendWhisper(name, "stats");
	UnBotJunkCleaner.stage = "wait_stats";
	-- На загруженном сервере корректный ответ `103/112 Bag` нередко приходит
	-- через 3-4 секунды. Старое окно 2.5 секунды успевало удалить бота раньше ответа.
	UnBotJunkCleaner.nextTime = GetTime() + 7;
end

function UnBotBagSpaceAuditFinishCurrent()
	local name = UnBotJunkCleaner.currentName;
	if (not name) then
		return;
	end
	local profile = UnBotBotRegistry.bots[name] or {};
	UnBotJunkCleaner.processed = UnBotJunkCleaner.processed + 1;
	if (not UnBotJunkCleaner.currentGroupOnly) then
		UnBotBagSpaceAuditCheckpoint.Complete(name, profile);
	end
	local occupancy = UnBotJunkCleaner.bagSlotsUsed and UnBotJunkCleaner.bagSlotsTotal
		and (" | занято "..tostring(UnBotJunkCleaner.bagSlotsUsed)
			.."/"..tostring(UnBotJunkCleaner.bagSlotsTotal)) or "";
	UnBotSpecSummonMessage(
		"Сумки сохранены: "..tostring(name).." | свободно "
		..tostring(UnBotJunkCleaner.freeBagSlots or 0)..occupancy
		..(UnBotJunkCleaner.currentGroupOnly
			and " | бот оставлен в текущей группе."
			or " | checkpoint сохранён.")
	);
	if (UnBotJunkCleaner.currentGroupOnly) then
		UnBotJunkCleanerStartNext();
		return;
	end
	UnBotJunkCleanerCleanupCurrent();
	UnBotJunkCleaner.stage = "wait_leave";
	UnBotJunkCleaner.nextTime = GetTime() + 0.5;
	UnBotJunkCleaner.stageUntil = GetTime() + 12;
end

function UnBotBagSpaceAuditFailCurrent()
	local name = UnBotJunkCleaner.currentName;
	UnBotJunkCleaner.failed = UnBotJunkCleaner.failed + 1;
	UnBotSpecSummonMessage(
		"Сумки "..tostring(name)
		..": ответ `stats` не получен после двух запросов; "
		..(UnBotJunkCleaner.currentGroupOnly
			and "бот оставлен в текущей группе."
			or "бот оставлен в незавершённом checkpoint.")
	);
	if (UnBotJunkCleaner.currentGroupOnly) then
		UnBotJunkCleanerStartNext();
		return;
	end
	UnBotJunkCleanerCleanupCurrent();
	UnBotJunkCleaner.stage = "wait_leave";
	UnBotJunkCleaner.nextTime = GetTime() + 0.5;
	UnBotJunkCleaner.stageUntil = GetTime() + 12;
end

function UnBotJunkCleanerStartInventoryAuditOrFinish()
	if (not UnBotJunkCleaner.singleMode and not UnBotJunkCleaner.deepVendorCleanup) then
		UnBotJunkCleanerStartStatsOrFinish();
		return;
	end
	if ((tonumber(UnBotJunkCleaner.inventoryAuditPass) or 0) >= 2) then
		UnBotJunkCleanerStartStatsOrFinish();
		return;
	end
	local name = UnBotJunkCleaner.currentName;
	if (not name) then
		UnBotJunkCleanerFinishCurrent();
		return;
	end
	UnBotJunkCleaner.inventoryAuditPass =
		(tonumber(UnBotJunkCleaner.inventoryAuditPass) or 0) + 1;
	UnBotJunkCleaner.inventoryAuditDone = true;
	UnBotJunkCleaner.inventoryAuditHeaderSeen = false;
	UnBotJunkCleaner.inventoryAuditUntil = GetTime() + 12;
	UnBotJunkCleaner.inventoryAuditCounts = {};
	UnBotJunkCleaner.inventoryAuditExamples = {};
	UnBotJunkCleaner.inventoryReagentCounts = {};
	UnBotBuffCycleSendWhisper(name, "c");
	UnBotJunkCleaner.stage = "wait_inventory_audit";
	UnBotJunkCleaner.nextTime = GetTime() + 4;
	UnBotSpecSummonMessage(
		(UnBotJunkCleaner.inventoryAuditPass == 1 and "Аудит перед расширенной очисткой: "
			or "Контрольный аудит после расширенной очистки: ")
		..tostring(name).." показывает содержимое сумок."
	);
end

function UnBotJunkCleanerRecordInventoryAuditLine(message)
	local text = tostring(message or "");
	if (string.find(text, "=== Inventory ===", 1, true)) then
		UnBotJunkCleaner.inventoryAuditHeaderSeen = true;
		return;
	end
	local itemId = tonumber(string.match(text, "Hitem:(%d+):"));
	if (not itemId) then
		return;
	end
	local itemName, itemLink, quality = GetItemInfo(itemId);
	if (quality == nil) then
		local color = string.lower(tostring(string.match(text, "|c(ff%x%x%x%x%x%x)|Hitem") or ""));
		if (color == "ff9d9d9d") then
			quality = 0;
		elseif (color == "ffffffff") then
			quality = 1;
		elseif (color == "ff1eff00") then
			quality = 2;
		elseif (color == "ff0070dd") then
			quality = 3;
		elseif (color == "ffa335ee") then
			quality = 4;
		else
			quality = -1;
		end
	end
	local count = tonumber(string.match(text, "[xх](%d+)")) or 1;
	if (UnBotJunkCleanerIsProtectedReagent(itemId) and itemId ~= 6948) then
		UnBotJunkCleaner.inventoryReagentCounts[itemId] =
			(tonumber(UnBotJunkCleaner.inventoryReagentCounts[itemId]) or 0) + count;
	end
	UnBotJunkCleaner.inventoryAuditCounts[quality] =
		(tonumber(UnBotJunkCleaner.inventoryAuditCounts[quality]) or 0) + count;
	if (quality >= 1 and quality <= 3) then
		local examples = UnBotJunkCleaner.inventoryAuditExamples[quality] or {};
		if (#examples < 8) then
			table.insert(examples, tostring(itemName or ("item:"..tostring(itemId))).." x"..tostring(count));
			UnBotJunkCleaner.inventoryAuditExamples[quality] = examples;
		end
	end
	if (UnBotJunkCleaner.inventoryAuditPass == 1) then
		local rawName = string.match(text, "%[([^%]]+)%]") or itemName or ("item:"..tostring(itemId));
		local rawLink = string.match(text, "(|c%x+|Hitem:[^|]+|h%[[^%]]+%]|h|r)");
		if (not rawLink) then
			rawLink = "|Hitem:"..tostring(itemId)..":0:0:0:0:0:0:0|h["
				..tostring(rawName).."]|h";
		end
		local shouldSell, sellLink = UnBotJunkCleanerShouldExtendedSell(
			itemId,
			rawName,
			text,
			quality,
			rawLink
		);
		if (shouldSell and sellLink and not UnBotJunkCleaner.extendedSellSeen[itemId]) then
			UnBotJunkCleaner.extendedSellSeen[itemId] = true;
			table.insert(UnBotJunkCleaner.extendedSellQueue, {
				id = itemId,
				label = rawName,
				link = sellLink,
				message = text,
			});
		end
	end
end

function UnBotJunkCleanerFinishInventoryAudit()
	local name = UnBotJunkCleaner.currentName;
	if (not UnBotJunkCleaner.inventoryAuditHeaderSeen) then
		UnBotSpecSummonMessage("Расширенная продажа "..tostring(name)..": нет ответа инвентаря; продажа пропущена. Предметы сохранены.");
		UnBotJunkCleanerStartStatsOrFinish();
		return;
	end
	local counts = UnBotJunkCleaner.inventoryAuditCounts or {};
	local examples = UnBotJunkCleaner.inventoryAuditExamples or {};
	UnBotSpecSummonMessage(
		"Инвентарь "..tostring(name)..": серых "..tostring(counts[0] or 0)
		..", белых "..tostring(counts[1] or 0)
		..", зелёных "..tostring(counts[2] or 0)
		..", синих "..tostring(counts[3] or 0)
		..", эпических "..tostring(counts[4] or 0).."."
	);
	for quality = 1, 3, 1 do
		if (examples[quality] and #examples[quality] > 0) then
			local label = quality == 1 and "Белые" or (quality == 2 and "Зелёные" or "Синие");
			UnBotSpecSummonMessage(label.." в сумках: "..table.concat(examples[quality], ", ")..".");
		end
	end
	if (UnBotJunkCleaner.inventoryAuditPass == 1) then
		UnBotJunkCleaner.extendedSellConfirmed = 0;
		UnBotJunkCleaner.stage = "sell_extended";
		UnBotJunkCleaner.nextTime = GetTime() + 0.2;
		UnBotSpecSummonMessage(
			"Расширенная очистка "..tostring(name)
			..": защита классовых и профессиональных предметов включена. "
			.."Проверенных позиций для продажи: "..tostring(#UnBotJunkCleaner.extendedSellQueue).."."
		);
		return;
	end
	local profile = name and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (profile) then
		profile.inventoryAuditAt = time();
		profile.inventoryAuditCounts = {
			poor = tonumber(counts[0]) or 0,
			common = tonumber(counts[1]) or 0,
			uncommon = tonumber(counts[2]) or 0,
			rare = tonumber(counts[3]) or 0,
			epic = tonumber(counts[4]) or 0,
		};
		local className = UnBotSpecSummonNormalize(profile.className);
		for _, wanted in ipairs(UnBotJunkCleanerReagentTargets[className] or {}) do
			UnBotRegistryStoreReagentCount(
				name,
				wanted.id,
				tonumber(UnBotJunkCleaner.inventoryReagentCounts[wanted.id]) or 0
			);
		end
		UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	end
	UnBotJunkCleanerStartStatsOrFinish();
end

local function UnBotJunkCleanerBuildQueue()
	UnBotRegistryAttachStorage();
	local queue = {};
	local upToDate = 0;
	local registryTotal = 0;
	local checkpoint = UnBotJunkCleanerCheckpoint.GetActive();
	for name, profile in pairs(UnBotBotRegistry.bots or {}) do
		if (UnBotIsValidBotName(name) and profile and not UnBotIsAccountAltProfile(name, profile)) then
			registryTotal = registryTotal + 1;
			if (checkpoint and checkpoint.names[name]) then
				if (checkpoint.completed and checkpoint.completed[name]) then
					profile.forceJunkCycle = nil;
					upToDate = upToDate + 1;
				else
					table.insert(queue, name);
				end
			elseif (checkpoint) then
				upToDate = upToDate + 1;
			elseif (
				UnBotRegistryNeedsJunkSale(profile)
				or UnBotRegistryNeedsReagentRestock(profile, UnBotJunkCleaner.merchantReagents)
			) then
				table.insert(queue, name);
			else
				upToDate = upToDate + 1;
			end
		end
	end
	table.sort(queue, function(a, b)
		local pa = UnBotBotRegistry.bots[a] or {};
		local pb = UnBotBotRegistry.bots[b] or {};
		local classA = UnBotSpecSummonNormalize(pa.className);
		local classB = UnBotSpecSummonNormalize(pb.className);
		if (classA ~= classB) then
			return classA < classB;
		end
		local specA = UnBotSpecSummonNormalize(pa.specName);
		local specB = UnBotSpecSummonNormalize(pb.specName);
		if (specA ~= specB) then
			return specA < specB;
		end
		return string.lower(a) < string.lower(b);
	end);
	return queue, upToDate, registryTotal;
end

UnBotJunkCleanerCleanupCurrent = function()
	if (UnBotJunkCleaner.currentGroupOnly) then
		return;
	end
	local name = UnBotJunkCleaner.currentName;
	if (name and UnBotSpecSummonIsInGroup(name)) then
		UnBotSpecSummonUninvite(name);
		UnBotBuffCycle.cleanup[name] = {
			removeSent = false,
			nextTime = GetTime() + 0.5,
			untilTime = GetTime() + 30,
		};
	end
end

-- Возвращаем движение только тем участникам, которых текущий сервисный запуск
-- сам остановил командой `stay`. Это не затрагивает остальных членов группы.
function UnBotJunkSaleRestoreFollow(state)
	local restored = 0;
	local serviceLabel = state and state.bagAuditOnly
		and "Проверка сумок" or "Продажа хлама";
	for name in pairs((state and state.stayedNames) or {}) do
		if (UnBotSpecSummonIsInGroup(name)) then
			UnBotBuffCycleSendWhisper(name, "follow");
			restored = restored + 1;
		end
	end
	if (state) then
		state.stayedNames = {};
	end
	if (restored > 0) then
		UnBotSpecSummonMessage(
			serviceLabel..": после `stay` команда `follow` отправлена ботам: "
			..tostring(restored).."."
		);
	end
	return restored;
end

local function UnBotJunkCleanerStop(text, cleanup)
	UnBotJunkSaleRestoreFollow(UnBotJunkCleaner);
	if (cleanup) then
		UnBotJunkCleanerCleanupCurrent();
	end
	if (
		text and not cleanup
		and UnBotJunkCleaner.timingMode
		and (UnBotJunkCleaner.runStartedAt or 0) > 0
	) then
		text = text.." "..UnBotServiceTiming.RunSummary(
			UnBotJunkCleaner.timingMode,
			UnBotJunkCleaner.runStartedAt
		);
	end
	UnBotJunkCleaner.active = false;
	UnBotJunkCleaner.stage = nil;
	UnBotJunkCleaner.currentName = nil;
	UnBotJunkCleaner.afkCheckAt = 0;
	UnBotJunkCleaner.afkClearAttempts = 0;
	UnBotJunkCleaner.afkFailureReported = false;
	UnBotJunkCleaner.deepVendorCleanup = false;
	UnBotJunkCleaner.bagAuditOnly = false;
	UnBotJunkCleaner.currentGroupOnly = false;
	UnBotJunkCleaner.timingMode = nil;
	UnBotJunkCleaner.currentStartedAt = 0;
	UnBotJunkCleaner.runStartedAt = 0;
	if (text) then
		UnBotSpecSummonMessage(text);
	end
end

function UnBotJunkCleanerStartNext()
	if (
		(UnBotJunkCleaner.currentStartedAt or 0) > 0
		and UnBotJunkCleaner.timingMode
	) then
		UnBotServiceTiming.Record(
			UnBotJunkCleaner.timingMode,
			GetTime() - UnBotJunkCleaner.currentStartedAt
		);
	end
	UnBotJunkCleaner.currentStartedAt = 0;
	UnBotJunkCleaner.index = UnBotJunkCleaner.index + 1;
	if (UnBotJunkCleaner.index > #UnBotJunkCleaner.queue) then
		if (UnBotJunkCleaner.bagAuditOnly) then
			if (UnBotJunkCleaner.currentGroupOnly) then
				UnBotJunkCleanerStop(
					"Проверка текущей группы завершена: "
					..tostring(UnBotJunkCleaner.processed).." сумок сохранено, "
					..tostring(UnBotJunkCleaner.failed).." ответов не распознано. "
					.."Состав группы не изменён.",
					false
				);
				return;
			end
			local checkpointCompleted, checkpointPending =
				UnBotBagSpaceAuditCheckpoint.FinishRun();
			UnBotJunkCleanerStop(
				"Проверка сумок завершена: "..tostring(UnBotJunkCleaner.processed)
				.." сохранено, "..tostring(UnBotJunkCleaner.failed)
				.." недоступно или не распознано, "
				..tostring(UnBotJunkCleaner.afkClearCount or 0).." AFK-состояний снято. "
				.."Checkpoint: "..tostring(checkpointCompleted).." сохранено, "
				..tostring(checkpointPending).." осталось.",
				false
			);
			return;
		end
		if (UnBotJunkCleaner.currentGroupOnly) then
			UnBotJunkCleanerStop(
				"Обслуживание текущей группы завершено: "
				..tostring(UnBotJunkCleaner.processed).." ботов обработано, "
				..tostring(UnBotJunkCleaner.failed).." недоступно, реагентов куплено "
				..tostring(UnBotJunkCleaner.restockedItems)..". Состав группы не изменён.",
				false
			);
			return;
		end
		local checkpointCompleted, checkpointPending =
			UnBotJunkCleanerCheckpoint.FinishRun();
		UnBotJunkCleanerStop(
			"Junk cleaner finished: "..tostring(UnBotJunkCleaner.processed)
			.." processed, "..tostring(UnBotJunkCleaner.failed).." unavailable, "
			..tostring(UnBotJunkCleaner.upToDate).." skipped without new gameplay summons, "
			..tostring(UnBotJunkCleaner.restockedBots).." bots restocked, "
			..tostring(UnBotJunkCleaner.restockedItems).." reagent items purchased, "
			..tostring(UnBotJunkCleaner.afkClearCount or 0).." AFK states cleared. "
			.."Checkpoint: "..tostring(checkpointCompleted).." saved, "
			..tostring(checkpointPending).." pending.",
			false
		);
		return;
	end

	local name = UnBotJunkCleaner.queue[UnBotJunkCleaner.index];
	UnBotJunkCleaner.currentName = name;
	UnBotJunkCleaner.currentStartedAt = GetTime();
	if (UnBotJunkCleaner.currentGroupOnly) then
		local unit = UnBotSquadRosterFindUnit(name);
		if (not unit or not UnitIsConnected(unit)) then
			UnBotJunkCleaner.failed = UnBotJunkCleaner.failed + 1;
			UnBotJunkCleaner.currentStartedAt = 0;
			UnBotSpecSummonMessage(
				"Текущая группа: "..tostring(name).." сейчас офлайн и пропущен."
			);
			UnBotJunkCleanerStartNext();
			return;
		end
	end
	UnBotJunkCleaner.reagentQueue = {};
	UnBotJunkCleaner.reagentIndex = 0;
	UnBotJunkCleaner.queryItem = nil;
	UnBotJunkCleaner.queryCount = nil;
	UnBotJunkCleaner.queryHeaderSeen = false;
	UnBotJunkCleaner.purchasesRemaining = 0;
	UnBotJunkCleaner.currentRestocked = 0;
	UnBotJunkCleaner.inventoryAuditDone = false;
	UnBotJunkCleaner.inventoryAuditPass = 0;
	UnBotJunkCleaner.inventoryReagentCounts = {};
	UnBotJunkCleaner.statsRequested = false;
	UnBotJunkCleaner.statsAttempts = 0;
	UnBotJunkCleaner.statsReceived = false;
	UnBotJunkCleaner.freeBagSlots = nil;
	UnBotJunkCleaner.bagSlotsUsed = nil;
	UnBotJunkCleaner.bagSlotsTotal = nil;
	UnBotJunkCleaner.extendedSellQueue = {};
	UnBotJunkCleaner.extendedSellIndex = 0;
	UnBotJunkCleaner.extendedSellSeen = {};
	UnBotJunkCleaner.extendedSellRequested = 0;
	UnBotJunkCleaner.extendedSellConfirmed = 0;
	UnBotJunkCleaner.extendedSellCandidate = nil;
	UnBotJunkCleaner.extendedSellRetries = 0;
	UnBotJunkCleaner.vendorSellAttempts = 0;
	UnBotJunkCleaner.stage = "wait_member";
	UnBotJunkCleaner.nextTime = GetTime();
	UnBotJunkCleaner.stageUntil = GetTime()
		+ (UnBotJunkCleaner.currentGroupOnly and 3 or 12);
	if (UnBotJunkCleaner.currentGroupOnly) then
		local profile = UnBotBotRegistry.bots[name] or {};
		UnBotSpecSummonMessage(
			(UnBotJunkCleaner.bagAuditOnly and "Проверка сумок группы " or "Обслуживание группы ")
			..tostring(UnBotJunkCleaner.index).."/"..tostring(#UnBotJunkCleaner.queue)
			..": "..name.." ["..tostring(profile.className or "?").." "
			..tostring(profile.specName or "?").."]."
		);
		return;
	end
	UnBotJunkCleaner.nextTime = GetTime() + 0.25;
	UnBotJunkCleaner.requestedNames[name] = GetTime() + 120;
	SendChatMessage(".playerbot bot add "..name, "SAY");
	local profile = UnBotBotRegistry.bots[name] or {};
	if (UnBotJunkCleaner.bagAuditOnly) then
		UnBotSpecSummonMessage(
			"Проверка сумок "..tostring(UnBotJunkCleaner.index).."/"
			..tostring(#UnBotJunkCleaner.queue)..": вызываем "..name.."."
		);
	else
		UnBotSpecSummonMessage(
			"Junk registry "..tostring(UnBotJunkCleaner.index).."/"
			..tostring(#UnBotJunkCleaner.queue)..": adding "..name.." ["
			..tostring(profile.className or "?").." "..tostring(profile.specName or "?").."]."
		);
	end
end

local function UnBotJunkCleanerAcceptCurrent()
	local name = UnBotJunkCleaner.currentName;
	if (not name or not UnBotSpecSummonIsInGroup(name)) then
		return false;
	end
	UnBotJunkCleaner.requestedNames[name] = nil;
	UnBotRememberKnownBot(name);
	UnBotBuffCycleSendWhisper(name, "summon");
	UnBotBuffCycleSendWhisper(name, "stay");
	UnBotJunkCleaner.stayedNames[name] = true;
	if (UnBotJunkCleaner.bagAuditOnly) then
		UnBotJunkCleaner.stage = "bag_stats";
		UnBotJunkCleaner.nextTime = GetTime() + 1;
		return true;
	end
	UnBotJunkCleaner.merchantReopenAt = GetTime() + 0.5;
	UnBotJunkCleaner.stage = "sell";
	UnBotJunkCleaner.nextTime = GetTime() + 2;
	return true;
end

local function UnBotJunkCleanerStart(deepVendorCleanup, currentGroupOnly)
	if (UnBotFullTalentCatalog and UnBotFullTalentCatalog.IsBusy()) then UnBotSpecSummonMessage("Сначала завершите сбор полного каталога талантов."); return false; end
	currentGroupOnly = currentGroupOnly == true;
	if (UnBotJunkCleaner.active) then
		if (UnBotJunkCleaner.bagAuditOnly) then
			UnBotSpecSummonMessage("Сначала остановите отдельную проверку сумок.");
			return;
		end
		UnBotJunkCleanerStop(
			"Junk cleaner stopped: "..tostring(UnBotJunkCleaner.processed).."/"..tostring(#UnBotJunkCleaner.queue).." processed.",
			true
		);
		return;
	end
	if (UnBotFastJunkRaid and UnBotFastJunkRaid.active) then
		UnBotSpecSummonMessage("Сначала остановите быструю рейдовую продажу/закупку.");
		return;
	end
	if (UnBotBotScanner and UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Stop the bot scan before starting the junk cleaner.");
		return;
	end
	if (UnBotDKSpecBalance and UnBotDKSpecBalance.active) then
		UnBotSpecSummonMessage("Сначала остановите выравнивание спеков по количеству.");
		return;
	end
	if (UnBotBuffCycle.active or UnBotSoulstoneTest.active or UnBotSpecSummon.active) then
		UnBotSpecSummonMessage("Stop other UnBot automation before starting the junk cleaner.");
		return;
	end
	if (not currentGroupOnly and UnBotBuffCycleOtherMemberCount() > 0) then
		UnBotSpecSummonMessage("Junk cleaner requires an empty group.");
		return;
	end
	if (not MerchantFrame or not MerchantFrame:IsShown() or not UnitExists("target")) then
		UnBotSpecSummonMessage("Open a merchant window and keep that merchant targeted first.");
		return;
	end
	UnBotJunkCleaner.merchantName = UnitName("target");
	UnBotJunkCleaner.merchantGuid = UnitGUID("target");
	UnBotJunkCleaner.merchantReagents, UnBotJunkCleaner.merchantReagentCount =
		UnBotJunkCleanerScanMerchantReagents();

	if (currentGroupOnly) then
		UnBotJunkCleaner.queue = UnBotBotServiceBuildCurrentGroupQueue(
			deepVendorCleanup and "deep" or "standard"
		);
		UnBotJunkCleaner.upToDate = 0;
		UnBotJunkCleaner.registryTotal = #UnBotJunkCleaner.queue;
	else
		UnBotJunkCleaner.queue, UnBotJunkCleaner.upToDate, UnBotJunkCleaner.registryTotal =
			UnBotJunkCleanerBuildQueue();
	end
	if (#UnBotJunkCleaner.queue == 0) then
		if (currentGroupOnly) then
			UnBotSpecSummonMessage(
				"В текущей группе/рейде нет онлайн-ботов из сохранённого реестра."
			);
			return;
		end
		local checkpointCompleted, checkpointPending, hadCheckpoint =
			UnBotJunkCleanerCheckpoint.FinishRun();
		if ((UnBotJunkCleaner.registryTotal or 0) == 0) then
			UnBotSpecSummonMessage("Junk cleaner found no profiles in the saved bot registry. Run the full bot scan first.");
		elseif (hadCheckpoint and checkpointPending > 0) then
			UnBotSpecSummonMessage(
				"Сохраняемая партия пока не завершена: checkpoint "
				..tostring(checkpointCompleted)..", осталось "
				..tostring(checkpointPending)
				.." отсутствующих в текущем реестре имён."
			);
		else
			UnBotSpecSummonMessage(
				"Обслуживание не требуется: продажа хлама актуальна, а известные остатки реагентов не ниже заданных целей."
			);
		end
		return;
	end
	local checkpoint = not currentGroupOnly and UnBotJunkCleanerCheckpoint.GetActive() or nil;
	local requestedMode = deepVendorCleanup and "deep" or "standard";
	local effectiveMode = checkpoint and checkpoint.mode or requestedMode;
	if (effectiveMode ~= "deep" and effectiveMode ~= "standard") then
		effectiveMode = requestedMode;
	end
	if (not checkpoint and not currentGroupOnly) then
		checkpoint = UnBotJunkCleanerCheckpoint.Create(UnBotJunkCleaner.queue, effectiveMode);
	elseif (checkpoint and not checkpoint.mode) then
		checkpoint.mode = effectiveMode;
		checkpoint.updatedAt = time();
	elseif (checkpoint and checkpoint.mode ~= requestedMode) then
		UnBotSpecSummonMessage(
			"Checkpoint уже начат в режиме "
			..(checkpoint.mode == "deep" and "глубокой очистки" or "обычного обслуживания")
			.."; продолжаем партию без смены режима."
		);
	end
	if (checkpoint) then
		checkpoint.schemaVersion = 2;
	end

	UnBotJunkCleaner.active = true;
	UnBotJunkCleaner.index = 0;
	UnBotJunkCleaner.currentName = nil;
	UnBotJunkCleaner.processed = 0;
	UnBotJunkCleaner.failed = 0;
	UnBotJunkCleaner.restockedBots = 0;
	UnBotJunkCleaner.restockedItems = 0;
	UnBotJunkCleaner.singleMode = false;
	UnBotJunkCleaner.bagAuditOnly = false;
	UnBotJunkCleaner.currentGroupOnly = currentGroupOnly;
	UnBotJunkCleaner.deepVendorCleanup = effectiveMode == "deep";
	UnBotJunkCleaner.timingMode = UnBotJunkCleaner.deepVendorCleanup and "deep" or "standard";
	UnBotJunkCleaner.currentStartedAt = 0;
	UnBotJunkCleaner.runStartedAt = GetTime();
	UnBotJunkCleaner.stayedNames = {};
	UnBotJunkCleaner.requestedNames = currentGroupOnly
		and {} or (UnBotJunkCleaner.requestedNames or {});
	UnBotJunkCleaner.afkCheckAt = GetTime() + 1;
	UnBotJunkCleaner.afkClearAttempts = 0;
	UnBotJunkCleaner.afkClearCount = 0;
	UnBotJunkCleaner.afkFailureReported = false;
	UnBotJunkCleaner.afkLastReportAt = 0;
	UnBotSpecSummonMessage(
		"Точное обслуживание ("
		..(UnBotJunkCleaner.deepVendorCleanup
			and "глубокое: защищённая продажа снаряжения + покупка недостающих реагентов"
			or "обычное: серый хлам + покупка только недостающих реагентов")
		.."): к обработке "..tostring(#UnBotJunkCleaner.queue)
		.." из "..tostring(UnBotJunkCleaner.registryTotal)
		..", без продажи или дефицита реагентов пропущено "..tostring(UnBotJunkCleaner.upToDate)
		..". Поддерживаемых классовых реагентов у торговца: "
		..tostring(UnBotJunkCleaner.merchantReagentCount or 0)
		..". Торговец сохранён; закрытие его окна больше не останавливает очередь. "
		.."Защита от AFK включена до завершения или ручной остановки. "
		.."ВНИМАНИЕ, операция долгая: "
		..UnBotServiceTiming.EstimateText(
			UnBotJunkCleaner.timingMode,
			#UnBotJunkCleaner.queue
		)..". Прогноз пересчитывается по фактической скорости. "
		..(currentGroupOnly
			and "Обрабатывается только текущая группа; никто не будет добавлен или удалён."
			or ("Checkpoint партии: "..tostring(checkpoint.completedCount or 0).."/"
				..tostring(checkpoint.total or #UnBotJunkCleaner.queue).." сохранено."))
	);
	if ((UnBotJunkCleaner.merchantReagentCount or 0) == 0) then
		UnBotSpecSummonMessage(
			"У этого торговца нет поддерживаемых классовых реагентов: будет выполнена только продажа хлама."
		);
	end
	UnBotJunkCleanerStartNext();
end

function UnBotBotServiceStartMaintenance(currentGroupOnly)
	UnBotJunkCleanerStart(false, currentGroupOnly);
end

function UnBotBotServiceStartDeepMaintenance(currentGroupOnly)
	UnBotJunkCleanerStart(true, currentGroupOnly);
end

function UnBotBagSpaceAuditStart(currentGroupOnly)
	currentGroupOnly = currentGroupOnly == true;
	if (UnBotJunkCleaner.active) then
		if (UnBotJunkCleaner.bagAuditOnly) then
			UnBotJunkCleanerStop(
				"Проверка сумок остановлена: "..tostring(UnBotJunkCleaner.processed)
				.."/"..tostring(#UnBotJunkCleaner.queue).." сохранено. "
				..(UnBotJunkCleaner.currentGroupOnly
					and "Состав группы не изменён."
					or "Незавершённый checkpoint будет продолжен при следующем запуске."),
				true
			);
		else
			UnBotSpecSummonMessage("Сначала остановите текущее обслуживание продажи/реагентов.");
		end
		return;
	end
	if (UnBotFastJunkRaid and UnBotFastJunkRaid.active) then
		UnBotSpecSummonMessage("Сначала остановите быструю рейдовую продажу.");
		return;
	end
	if (UnBotBotScanner and UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Сначала остановите полный скан ботов.");
		return;
	end
	if (UnBotDKSpecBalance and UnBotDKSpecBalance.active) then
		UnBotSpecSummonMessage("Сначала остановите выравнивание спеков.");
		return;
	end
	if (UnBotBuffCycle.active or UnBotSoulstoneTest.active or UnBotSpecSummon.active) then
		UnBotSpecSummonMessage("Сначала остановите другую автоматизацию UnBot.");
		return;
	end
	if (not currentGroupOnly and UnBotBuffCycleOtherMemberCount() > 0) then
		UnBotSpecSummonMessage("Для проверки сумок группа должна быть пустой.");
		return;
	end

	UnBotRegistryAttachStorage();
	local checkpoint = not currentGroupOnly and UnBotBagSpaceAuditCheckpoint.GetActive() or nil;
	local queue = {};
	local registryTotal = 0;
	if (currentGroupOnly) then
		queue = UnBotBotServiceBuildCurrentGroupQueue("bags");
		registryTotal = #queue;
	else
		for name, profile in pairs(UnBotBotRegistry.bots or {}) do
			if (UnBotIsValidBotName(name) and profile and not UnBotIsAccountAltProfile(name, profile)) then
				registryTotal = registryTotal + 1;
				if (
					(not checkpoint)
					or (
						checkpoint.names[name]
						and not (checkpoint.completed and checkpoint.completed[name])
					)
				) then
					table.insert(queue, name);
				end
			end
		end
	end
	table.sort(queue, function(a, b) return string.lower(a) < string.lower(b); end);
	if (#queue == 0) then
		if (currentGroupOnly) then
			UnBotSpecSummonMessage(
				"В текущей группе/рейде нет онлайн-ботов из сохранённого реестра."
			);
			return;
		end
		local checkpointCompleted, checkpointPending, hadCheckpoint =
			UnBotBagSpaceAuditCheckpoint.FinishRun();
		if (registryTotal == 0) then
			UnBotSpecSummonMessage("В реестре нет ботов. Сначала выполните полный скан.");
		elseif (hadCheckpoint) then
			UnBotSpecSummonMessage(
				"Проверка сумок уже завершена: "..tostring(checkpointCompleted)
				.." сохранено, "..tostring(checkpointPending).." осталось."
			);
		else
			UnBotSpecSummonMessage("Для проверки сумок не найдено доступных профилей.");
		end
		return;
	end
	if (not checkpoint and not currentGroupOnly) then
		checkpoint = UnBotBagSpaceAuditCheckpoint.Create(queue);
	end

	UnBotJunkCleaner.queue = queue;
	UnBotJunkCleaner.registryTotal = registryTotal;
	UnBotJunkCleaner.upToDate = checkpoint and tonumber(checkpoint.completedCount) or 0;
	UnBotJunkCleaner.active = true;
	UnBotJunkCleaner.index = 0;
	UnBotJunkCleaner.currentName = nil;
	UnBotJunkCleaner.processed = 0;
	UnBotJunkCleaner.failed = 0;
	UnBotJunkCleaner.restockedBots = 0;
	UnBotJunkCleaner.restockedItems = 0;
	UnBotJunkCleaner.singleMode = false;
	UnBotJunkCleaner.deepVendorCleanup = false;
	UnBotJunkCleaner.bagAuditOnly = true;
	UnBotJunkCleaner.currentGroupOnly = currentGroupOnly;
	UnBotJunkCleaner.timingMode = "bags";
	UnBotJunkCleaner.currentStartedAt = 0;
	UnBotJunkCleaner.runStartedAt = GetTime();
	UnBotJunkCleaner.stayedNames = {};
	UnBotJunkCleaner.merchantName = nil;
	UnBotJunkCleaner.merchantGuid = nil;
	UnBotJunkCleaner.merchantReopenAt = nil;
	UnBotJunkCleaner.requestedNames = currentGroupOnly
		and {} or (UnBotJunkCleaner.requestedNames or {});
	UnBotJunkCleaner.afkCheckAt = GetTime() + 1;
	UnBotJunkCleaner.afkClearAttempts = 0;
	UnBotJunkCleaner.afkClearCount = 0;
	UnBotJunkCleaner.afkFailureReported = false;
	UnBotJunkCleaner.afkLastReportAt = 0;
	UnBotSpecSummonMessage(
		"Отдельная проверка сумок: к обработке "..tostring(#queue)
		.." из "..tostring(registryTotal).." ботов. "
		.."Продажа и закупка отключены; торговец не требуется. "
		.."Оценка времени: "..UnBotServiceTiming.EstimateText("bags", #queue)
		..". Прогноз пересчитывается по ходу прохода. "
		..(currentGroupOnly
			and "Проверяется только текущая группа; никто не будет добавлен или удалён."
			or ("Checkpoint: "..tostring(checkpoint.completedCount or 0).."/"
				..tostring(checkpoint.total or #queue).." сохранено."))
	);
	UnBotJunkCleanerStartNext();
end

function UnBotJunkCleanerStartSingle(botName)
	if (UnBotFullTalentCatalog and UnBotFullTalentCatalog.IsBusy()) then UnBotSpecSummonMessage("Сначала завершите сбор полного каталога талантов."); return false; end
	if (UnBotJunkCleaner.active) then
		UnBotJunkCleanerStop(
			"Точечная продажа/закупка остановлена: "
			..tostring(UnBotJunkCleaner.processed).."/"
			..tostring(#UnBotJunkCleaner.queue).." обработано.",
			true
		);
		return;
	end
	if (UnBotFastJunkRaid and UnBotFastJunkRaid.active) then
		UnBotSpecSummonMessage("Сначала остановите быструю рейдовую продажу/закупку.");
		return;
	end
	if (UnBotBotScanner and UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Сначала остановите полный скан ботов.");
		return;
	end
	if (UnBotBuffCycle.active or UnBotSoulstoneTest.active or UnBotSpecSummon.active) then
		UnBotSpecSummonMessage("Сначала остановите другую автоматизацию UnBot.");
		return;
	end
	if (UnBotBuffCycleOtherMemberCount() > 0) then
		UnBotSpecSummonMessage("Для точечного теста группа должна быть пустой.");
		return;
	end
	if (not MerchantFrame or not MerchantFrame:IsShown() or not UnitExists("target")) then
		UnBotSpecSummonMessage("Сначала откройте окно торговца реагентами и оставьте его в цели.");
		return;
	end

	UnBotRegistryAttachStorage();
	local requested = UnBotSpecSummonNormalize(botName);
	local resolvedName = nil;
	for name in pairs(UnBotBotRegistry.bots or {}) do
		if (UnBotSpecSummonNormalize(name) == requested) then
			resolvedName = name;
			break
		end
	end
	if (not resolvedName) then
		UnBotSpecSummonMessage(
			"Точечный тест: бот "..tostring(botName).." не найден в сохранённом реестре."
		);
		return;
	end
	if (UnBotIsAccountAltProfile(resolvedName, UnBotBotRegistry.bots[resolvedName])) then
		UnBotSpecSummonMessage(
			"Обслуживание отменено: "..resolvedName
			.." — защищённый альт аккаунта. Его сумки и предметы UnBot не изменяет."
		);
		return;
	end

	UnBotJunkCleaner.merchantName = UnitName("target");
	UnBotJunkCleaner.merchantGuid = UnitGUID("target");
	UnBotJunkCleaner.merchantReagents, UnBotJunkCleaner.merchantReagentCount =
		UnBotJunkCleanerScanMerchantReagents();
	UnBotJunkCleaner.queue = { resolvedName };
	UnBotJunkCleaner.upToDate = 0;
	UnBotJunkCleaner.registryTotal = 1;
	if (not UnBotJunkCleanerCheckpoint.GetActive()) then
		UnBotJunkCleanerCheckpoint.Create(UnBotJunkCleaner.queue);
	end
	UnBotJunkCleaner.active = true;
	UnBotJunkCleaner.index = 0;
	UnBotJunkCleaner.currentName = nil;
	UnBotJunkCleaner.processed = 0;
	UnBotJunkCleaner.failed = 0;
	UnBotJunkCleaner.restockedBots = 0;
	UnBotJunkCleaner.restockedItems = 0;
	UnBotJunkCleaner.singleMode = true;
	UnBotJunkCleaner.bagAuditOnly = false;
	UnBotJunkCleaner.currentGroupOnly = false;
	UnBotJunkCleaner.deepVendorCleanup = true;
	UnBotJunkCleaner.timingMode = nil;
	UnBotJunkCleaner.currentStartedAt = 0;
	UnBotJunkCleaner.runStartedAt = 0;
	UnBotJunkCleaner.stayedNames = {};
	UnBotJunkCleaner.requestedNames = UnBotJunkCleaner.requestedNames or {};
	UnBotJunkCleaner.afkCheckAt = GetTime() + 1;
	UnBotJunkCleaner.afkClearAttempts = 0;
	UnBotJunkCleaner.afkClearCount = 0;
	UnBotJunkCleaner.afkFailureReported = false;
	UnBotJunkCleaner.afkLastReportAt = 0;

	local profile = UnBotBotRegistry.bots[resolvedName] or {};
	local className = UnBotSpecSummonNormalize(profile.className);
	local wantedItems = UnBotJunkCleanerReagentTargets[className] or {};
	local offeredItems = UnBotJunkCleanerBuildReagentQueue(resolvedName);
	UnBotSpecSummonMessage(
		"Точечный тест продажи/закупки: "..resolvedName
		.." ["..tostring(profile.className or "?").." "
		..tostring(profile.specName or "?").."] | торговец "
		..tostring(UnBotJunkCleaner.merchantName or "?").." | подходящих реагентов "
		..tostring(#offeredItems).."/"..tostring(#wantedItems)
		..". После продажи ассортимент будет просканирован повторно. "
		.."Защита от AFK включена до окончания теста."
	);
	UnBotJunkCleanerStartNext();
end

-- Быстрая отдельная очистка только серого хлама. В отличие от полного
-- продавца она собирает рейд до 39 ботов и отправляет одну групповую `s *`.
-- `s vendor` и закупка реагентов здесь намеренно не выполняются.
UnBotFastJunkRaid = UnBotFastJunkRaid or {
	active = false,
	stage = nil,
	nextTime = 0,
	stageUntil = 0,
	queue = {},
	queueIndex = 0,
	batchNumber = 0,
	batchSize = 39,
	currentBatch = {},
	pending = {},
	processed = 0,
	failed = 0,
	merchantName = nil,
	merchantGuid = nil,
	merchantReagents = {},
	merchantReagentCount = 0,
	mode = "gray",
	batchClass = nil,
	buyQueue = {},
	buyIndex = 0,
	buyRemaining = 0,
	fallbackCleanupSent = false,
	runStartedAt = 0,
	currentGroupOnly = false,
	accountAltsOnly = false,
	targetNames = {},
	stayedNames = {},
};

function UnBotFastJunkRaidBuildQueue()
	UnBotRegistryAttachStorage();
	local queue = {};
	local total = 0;
	local upToDate = 0;
	for name, profile in pairs((UnBotBotRegistry and UnBotBotRegistry.bots) or {}) do
		if (UnBotIsValidBotName(name) and profile and not UnBotIsAccountAltProfile(name, profile)) then
			total = total + 1;
			if (UnBotRegistryNeedsJunkSale(profile)) then
				table.insert(queue, name);
			else
				upToDate = upToDate + 1;
			end
		end
	end
	table.sort(queue, function(a, b)
		return string.lower(a) < string.lower(b);
	end);
	return queue, total, upToDate;
end

function UnBotFastJunkRaidBuildReagentQueue()
	UnBotRegistryAttachStorage();
	local queue = {};
	local unsupported = 0;
	local upToDate = 0;
	for name, profile in pairs((UnBotBotRegistry and UnBotBotRegistry.bots) or {}) do
		if (UnBotIsValidBotName(name) and profile and not UnBotIsAccountAltProfile(name, profile)) then
			local className = UnBotSpecSummonNormalize(profile.className);
			local targetCount = 0;
			local offeredCount = 0;
			for _, reagent in ipairs(UnBotJunkCleanerReagentTargets[className] or {}) do
				targetCount = targetCount + 1;
				if (UnBotFastJunkRaid.merchantReagents[reagent.id]) then
					offeredCount = offeredCount + 1;
				end
			end
			local supported = targetCount > 0 and offeredCount == targetCount;
			if (supported and UnBotRegistryNeedsJunkSale(profile)) then
				table.insert(queue, name);
			elseif (supported) then
				upToDate = upToDate + 1;
			else
				unsupported = unsupported + 1;
			end
		end
	end
	table.sort(queue, function(a, b)
		local pa = UnBotBotRegistry.bots[a] or {};
		local pb = UnBotBotRegistry.bots[b] or {};
		local ca = UnBotSpecSummonNormalize(pa.className);
		local cb = UnBotSpecSummonNormalize(pb.className);
		if (ca ~= cb) then
			return ca < cb;
		end
		return string.lower(a) < string.lower(b);
	end);
	return queue, unsupported, upToDate;
end

function UnBotFastJunkRaidGroupChannel()
	if (GetNumRaidMembers() and GetNumRaidMembers() > 0) then
		return "RAID";
	end
	if (GetNumPartyMembers() and GetNumPartyMembers() > 0) then
		return "PARTY";
	end
	return nil;
end

function UnBotFastJunkRaidMemberCount()
	return UnBotBuffCycleOtherMemberCount();
end

function UnBotFastJunkRaidPendingCount()
	local count = 0;
	for _ in pairs(UnBotFastJunkRaid.pending or {}) do
		count = count + 1;
	end
	return count;
end

function UnBotFastJunkRaidReopenMerchant()
	local name = UnBotFastJunkRaid.merchantName;
	if (not name or name == "") then
		return false;
	end
	if (MerchantFrame and MerchantFrame:IsShown()) then
		return true;
	end
	local targetMatches = UnitExists("target") and UnitName("target") == name;
	if (
		targetMatches
		and UnBotFastJunkRaid.merchantGuid
		and UnitGUID("target") ~= UnBotFastJunkRaid.merchantGuid
	) then
		targetMatches = false;
	end
	if (not targetMatches and TargetByName) then
		pcall(TargetByName, name, true);
		targetMatches = UnitExists("target") and UnitName("target") == name;
		if (
			targetMatches
			and UnBotFastJunkRaid.merchantGuid
			and UnitGUID("target") ~= UnBotFastJunkRaid.merchantGuid
		) then
			targetMatches = false;
		end
	end
	if (targetMatches and InteractUnit) then
		pcall(InteractUnit, "target");
		return true;
	end
	return false;
end

function UnBotFastJunkRaidRefreshPending()
	local now = GetTime();
	-- A checkbox removed mid-run, unlink, login or disconnect revokes the
	-- remaining targeted commands; ordinary bots retain the existing path.
	if UnBotFastJunkRaid.currentGroupOnly and UnBotFastJunkRaid.mode == "gray" then
		for name, binding in pairs(UnBotFastJunkRaid.altSaleBindings or {}) do
			if UnBotFastJunkRaid.targetNames[name] and (not UnBotAccountAlts.IsGrayJunkAllowed(name)
				or UnBotAccountAlts.GrayJunkBinding(name) ~= binding or not UnBotAccountAlts.IsOnline(name)) then
				UnBotFastJunkRaid.targetNames[name] = nil;
				UnBotFastJunkRaid.failed = (UnBotFastJunkRaid.failed or 0) + 1;
			end
		end
	end
	for name, expiresAt in pairs(UnBotFastJunkRaid.pending or {}) do
		if (UnBotSpecSummonIsInGroup(name)) then
			UnBotFastJunkRaid.pending[name] = nil;
		elseif (now >= (expiresAt or 0)) then
			UnBotFastJunkRaid.pending[name] = nil;
			UnBotFastJunkRaid.failed = (UnBotFastJunkRaid.failed or 0) + 1;
		end
	end
end

function UnBotFastJunkRaidStop(text, cleanup)
	UnBotJunkSaleRestoreFollow(UnBotFastJunkRaid);
	if (
		cleanup
		and not UnBotFastJunkRaid.currentGroupOnly
		and UnBotFastJunkRaidMemberCount() > 0
	) then
		local channel = UnBotFastJunkRaidGroupChannel();
		if (channel) then
			SendChatMessage("leave", channel);
		end
		for name in pairs(UnBotSpecSummonGetMembers()) do
			if (name ~= UnitName("player")) then
				UnBotSpecSummonUninvite(name);
			end
		end
	end
	if (
		not cleanup
		and (UnBotFastJunkRaid.runStartedAt or 0) > 0
		and (UnBotFastJunkRaid.processed or 0) > 0
	) then
		UnBotServiceTiming.RecordAggregate(
			"fast",
			GetTime() - UnBotFastJunkRaid.runStartedAt,
			UnBotFastJunkRaid.processed
		);
		if (text) then
			text = text.." "..UnBotServiceTiming.RunSummary(
				"fast",
				UnBotFastJunkRaid.runStartedAt
			);
		end
	end
	UnBotFastJunkRaid.active = false;
	UnBotFastJunkRaid.stage = nil;
	UnBotFastJunkRaid.pending = {};
	UnBotFastJunkRaid.runStartedAt = 0;
	UnBotFastJunkRaid.currentGroupOnly = false;
	UnBotFastJunkRaid.accountAltsOnly = false;
	UnBotFastJunkRaid.targetNames = {};
	UnBotFastJunkRaid.stayedNames = {};
	if (text) then
		UnBotSpecSummonMessage(text);
	end
end

function UnBotFastJunkRaidStartBatch()
	if (UnBotFastJunkRaid.queueIndex >= #(UnBotFastJunkRaid.queue or {})) then
		if (UnBotFastJunkRaid.mode == "reagents") then
			UnBotFastJunkRaidStop(
				"Быстрая закупка завершена: продажу и закупку прошли "
				..tostring(UnBotFastJunkRaid.processed or 0).." ботов; недоступно "
				..tostring(UnBotFastJunkRaid.failed or 0)..".",
				false
			);
		else
			UnBotFastJunkRaidStop(
				"Быстрая продажа завершена: серый хлам обработан у "
				..tostring(UnBotFastJunkRaid.processed or 0).." ботов; недоступно "
				..tostring(UnBotFastJunkRaid.failed or 0)..".",
				false
			);
		end
		return;
	end
	UnBotFastJunkRaid.batchNumber = (UnBotFastJunkRaid.batchNumber or 0) + 1;
	UnBotFastJunkRaid.currentBatch = {};
	UnBotFastJunkRaid.pending = {};
	UnBotFastJunkRaid.buyQueue = {};
	UnBotFastJunkRaid.buyIndex = 0;
	UnBotFastJunkRaid.buyRemaining = 0;
	if (UnBotFastJunkRaid.mode == "reagents") then
		local firstName = UnBotFastJunkRaid.queue[UnBotFastJunkRaid.queueIndex + 1];
		local firstProfile = firstName and UnBotBotRegistry.bots[firstName] or {};
		UnBotFastJunkRaid.batchClass = UnBotSpecSummonNormalize(firstProfile.className);
	else
		UnBotFastJunkRaid.batchClass = nil;
	end
	UnBotFastJunkRaid.fallbackCleanupSent = false;
	UnBotFastJunkRaid.stage = "fill";
	UnBotFastJunkRaid.nextTime = GetTime();
	UnBotFastJunkRaid.stageUntil = GetTime() + 90;
	UnBotSpecSummonMessage(
		"Быстрая продажа: собирается рейд "..tostring(UnBotFastJunkRaid.batchNumber)
		..(UnBotFastJunkRaid.batchClass and " ["..UnBotFastJunkRaid.batchClass.."]" or "")
		..", осталось профилей "
		..tostring(#UnBotFastJunkRaid.queue - UnBotFastJunkRaid.queueIndex).."."
	);
end

function UnBotFastJunkRaidRecordSaleAttempt()
	local members = UnBotSpecSummonGetMembers();
	local count = 0;
	for name in pairs(members) do
		if (name ~= UnitName("player")) then
			local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
			local unit = UnBotFastJunkRaid.currentGroupOnly
				and UnBotSquadRosterFindUnit(name) or nil;
			if not profile and UnBotFastJunkRaid.currentGroupOnly and UnBotFastJunkRaid.targetNames[name]
				and unit and UnitIsConnected(unit) then count = count + 1; end
			if (
				profile
				and (
					not UnBotFastJunkRaid.currentGroupOnly
					or (
						UnBotFastJunkRaid.targetNames[name]
						and unit
						and UnitIsConnected(unit)
					)
				)
			) then
				profile.lastFastGraySaleAt = time();
				profile.fastGraySaleCount = (tonumber(profile.fastGraySaleCount) or 0) + 1;
				if (UnBotFastJunkRaid.mode == "reagents") then
					profile.lastFastReagentRestockAt = time();
					profile.fastReagentRestockCount =
						(tonumber(profile.fastReagentRestockCount) or 0) + 1;
					-- Этот режим сначала продаёт всё разрешённое сервером, затем
					-- восстанавливает классовые реагенты. Только после полного цикла
					-- снимаем принудительный флаг и запоминаем счётчик призывов.
					UnBotRegistryRecordJunkSale(name);
				else
					local className = UnBotSpecSummonNormalize(profile.className);
					if (#(UnBotJunkCleanerReagentTargets[className] or {}) == 0) then
						-- У этого класса нет покупаемых классовых реагентов: быстрая
						-- продажа уже является для него полным циклом.
						UnBotRegistryRecordJunkSale(name);
					end
				end
				count = count + 1;
			end
		end
	end
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	UnBotFastJunkRaid.processed = (UnBotFastJunkRaid.processed or 0) + count;
	return count;
end

function UnBotFastJunkRaidPrepareBuyQueue()
	local queue = {};
	for _, wanted in ipairs(
		UnBotJunkCleanerReagentTargets[UnBotFastJunkRaid.batchClass] or {}
	) do
		local offered = UnBotFastJunkRaid.merchantReagents[wanted.id];
		if (offered and offered.link) then
			table.insert(queue, {
				link = offered.link,
				label = offered.label or wanted.label,
				commands = math.ceil(
					(tonumber(wanted.target) or 0)
					/ math.max(1, tonumber(offered.bundleSize) or 1)
				),
			});
		end
	end
	UnBotFastJunkRaid.buyQueue = queue;
	UnBotFastJunkRaid.buyIndex = 1;
	UnBotFastJunkRaid.buyRemaining = queue[1] and queue[1].commands or 0;
	return #queue;
end

function UnBotFastJunkRaidFallbackCleanup()
	local members = UnBotSpecSummonGetMembers();
	for name in pairs(members) do
		if (name ~= UnitName("player")) then
			UnBotSpecSummonUninvite(name);
		end
	end
	UnBotFastJunkRaid.fallbackCleanupSent = true;
	UnBotFastJunkRaid.stageUntil = GetTime() + 15;
end

function UnBotFastJunkRaidStart(currentGroupOnly, accountAltsOnly)
	if (UnBotFullTalentCatalog and UnBotFullTalentCatalog.IsBusy()) then UnBotSpecSummonMessage("Сначала завершите сбор полного каталога талантов."); return false; end
	currentGroupOnly = currentGroupOnly == true;
	accountAltsOnly = currentGroupOnly and accountAltsOnly == true;
	if (UnBotFastJunkRaid.active) then
		UnBotFastJunkRaidStop(
			"Быстрая продажа остановлена после "
			..tostring(UnBotFastJunkRaid.processed or 0).." обработанных ботов.",
			true
		);
		return;
	end
	if (
		(UnBotJunkCleaner and UnBotJunkCleaner.active)
		or (UnBotBotScanner and UnBotBotScanner.active)
		or (UnBotBuffCycle and UnBotBuffCycle.active)
		or (UnBotSoulstoneTest and UnBotSoulstoneTest.active)
		or (UnBotSpecSummon and UnBotSpecSummon.active)
		or (UnBotDKSpecBalance and UnBotDKSpecBalance.active)
	) then
		UnBotSpecSummonMessage("Сначала остановите другие процессы UnBot.");
		return;
	end
	if (not currentGroupOnly and UnBotFastJunkRaidMemberCount() > 0) then
		UnBotSpecSummonMessage("Быстрая продажа требует пустую группу или рейд.");
		return;
	end
	if (not MerchantFrame or not MerchantFrame:IsShown() or not UnitExists("target")) then
		UnBotSpecSummonMessage("Сначала откройте окно торговца и оставьте его выбранным.");
		return;
	end
	local registryTotal, upToDate;
	if (currentGroupOnly) then
		UnBotFastJunkRaid.queue = UnBotBotServiceBuildCurrentGroupQueue(
			accountAltsOnly and "alt-fast" or "fast"
		);
		registryTotal = #UnBotFastJunkRaid.queue;
		upToDate = 0;
	else
		UnBotFastJunkRaid.queue, registryTotal, upToDate = UnBotFastJunkRaidBuildQueue();
	end
	if (#UnBotFastJunkRaid.queue == 0) then
		if (currentGroupOnly) then
			UnBotSpecSummonMessage(
				accountAltsOnly
					and "В текущей группе нет онлайн-альтов с разрешением на обслуживание."
					or "В текущей группе/рейде нет онлайн-ботов из сохранённого реестра."
			);
			return;
		end
		if ((registryTotal or 0) == 0) then
			UnBotSpecSummonMessage("В сохранённом реестре нет ботов. Сначала выполните полный скан.");
		else
			UnBotSpecSummonMessage(
				"Быстрая продажа не требуется: после последней обработки ни один бот не был вызван для игры."
			);
		end
		return;
	end
	UnBotFastJunkRaid.active = true;
	UnBotFastJunkRaid.mode = "gray";
	UnBotFastJunkRaid.queueIndex = 0;
	UnBotFastJunkRaid.batchNumber = 0;
	UnBotFastJunkRaid.processed = 0;
	UnBotFastJunkRaid.failed = 0;
	UnBotFastJunkRaid.runStartedAt = GetTime();
	UnBotFastJunkRaid.currentGroupOnly = currentGroupOnly;
	UnBotFastJunkRaid.accountAltsOnly = accountAltsOnly;
	UnBotFastJunkRaid.targetNames = {};
	UnBotFastJunkRaid.altSaleBindings = {};
	UnBotFastJunkRaid.stayedNames = {};
	for _, name in ipairs(UnBotFastJunkRaid.queue) do
		UnBotFastJunkRaid.targetNames[name] = true;
		if UnBotAccountAlts and UnBotAccountAlts.IsListed(name) then
			UnBotFastJunkRaid.altSaleBindings[name] = UnBotAccountAlts.GrayJunkBinding(name);
		end
	end
	UnBotFastJunkRaid.merchantName = UnitName("target");
	UnBotFastJunkRaid.merchantGuid = UnitGUID("target");
	UnBotSpecSummonMessage(
		(accountAltsOnly and "Продажа серого хлама альтов: " or "Быстрая рейдовая продажа серого хлама: ")
		..tostring(#UnBotFastJunkRaid.queue).." из "
		..tostring(registryTotal or #UnBotFastJunkRaid.queue)
		.." профилей, уже обработано "..tostring(upToDate or 0)
		..", до 39 ботов за рейд. "
		.."Оценка времени: "
		..UnBotServiceTiming.EstimateText("fast", #UnBotFastJunkRaid.queue)
		..". Прогноз пересчитывается в Центре. "
		.."Реагенты и `s vendor` этот режим не обрабатывает. "
		..(currentGroupOnly
			and (accountAltsOnly
				and "Адресные команды уйдут только разрешённым онлайн-альтам; состав не изменится."
				or "Команды уйдут только обычным ботам текущей группы; состав не изменится.")
			or "")
	);
	if (currentGroupOnly) then
		UnBotFastJunkRaid.queueIndex = #UnBotFastJunkRaid.queue;
		UnBotFastJunkRaid.batchNumber = 1;
		UnBotFastJunkRaid.currentBatch = UnBotFastJunkRaid.targetNames;
		UnBotFastJunkRaid.pending = {};
		UnBotFastJunkRaid.stage = "fill";
		UnBotFastJunkRaid.nextTime = GetTime();
		UnBotFastJunkRaid.stageUntil = GetTime() + 30;
	else
		UnBotFastJunkRaidStartBatch();
	end
end

function UnBotFastJunkRaidStartReagents()
	if (UnBotFullTalentCatalog and UnBotFullTalentCatalog.IsBusy()) then UnBotSpecSummonMessage("Сначала завершите сбор полного каталога талантов."); return false; end
	UnBotSpecSummonMessage(
		"Обычное точное обслуживание: продаётся только серый хлам; "
		.."каждый бот опрашивается отдельно и покупается только разница до целей."
	);
	UnBotJunkCleanerStart(false);
end

SLASH_UNBOTFASTJUNK1 = "/ubfastjunk";
SlashCmdList["UNBOTFASTJUNK"] = function()
	UnBotFastJunkRaidStart();
end

SLASH_UNBOTFASTRESTOCK1 = "/ubfastrestock";
SlashCmdList["UNBOTFASTRESTOCK"] = function()
	UnBotFastJunkRaidStartReagents();
end

UnBotFastJunkRaidFrame = UnBotFastJunkRaidFrame
	or CreateFrame("Frame", "UnBotFastJunkRaidFrame");
UnBotFastJunkRaidFrame:RegisterEvent("TRADE_SHOW");
UnBotFastJunkRaidFrame:SetScript("OnEvent", function(self, event)
	if (event == "TRADE_SHOW" and UnBotFastJunkRaid.active) then
		if (CancelTrade) then
			CancelTrade();
		end
		UnBotFastJunkRaid.nextTime = GetTime() + 0.4;
	end
end);

function UnBotFastJunkRaidBuyingChatFilter(self, event, message, author)
	if UnBotChatRouting then
		local group = UnBotChatRouting.Group(author, message);
		if group and UnBotChatRouting.Destination(group, UnBotChatRouting.Kind(event, message, author)) ~= "legacy" then return false; end
	end
	if (
		UnBotFastJunkRaid.active
		and UnBotFastJunkRaid.mode == "reagents"
		and UnBotFastJunkRaid.stage == "buy"
		and message
		and string.find(message, "Buying [", 1, true)
	) then
		return true;
	end
	return false;
end
if (ChatFrame_AddMessageEventFilter) then
	ChatFrame_AddMessageEventFilter("CHAT_MSG_WHISPER", UnBotFastJunkRaidBuyingChatFilter);
end

UnBotFastJunkRaidFrame:SetScript("OnUpdate", function()
	if (not UnBotFastJunkRaid.active) then
		return;
	end
	local now = GetTime();
	UnBotFastJunkRaidRefreshPending();
	if (now < (UnBotFastJunkRaid.nextTime or 0)) then
		return;
	end

	if (UnBotFastJunkRaid.stage == "fill") then
		local memberCount = UnBotFastJunkRaidMemberCount();
		local pendingCount = UnBotFastJunkRaidPendingCount();
		local nextName = UnBotFastJunkRaid.queue[UnBotFastJunkRaid.queueIndex + 1];
		local nextProfile = nextName and UnBotBotRegistry.bots[nextName] or {};
		local nextClass = UnBotSpecSummonNormalize(nextProfile.className);
		local classBoundary = (
			UnBotFastJunkRaid.mode == "reagents"
			and nextName
			and nextClass ~= UnBotFastJunkRaid.batchClass
		);
		if (
			memberCount >= (UnBotFastJunkRaid.batchSize or 39)
			or (classBoundary and pendingCount == 0)
			or (
				UnBotFastJunkRaid.queueIndex >= #UnBotFastJunkRaid.queue
				and pendingCount == 0
			)
		) then
			if (memberCount == 0) then
				if (UnBotFastJunkRaid.mode == "reagents" and classBoundary) then
					UnBotSpecSummonMessage(
						"Быстрая закупка: класс "
						..tostring(UnBotFastJunkRaid.batchClass or "?")
						.." недоступен, перехожу к следующему классу."
					);
					UnBotFastJunkRaidStartBatch();
					return;
				end
				UnBotFastJunkRaidStop(
					"Быстрая продажа завершена: доступных ботов больше нет; недоступно "
					..tostring(UnBotFastJunkRaid.failed or 0)..".",
					false
				);
				return;
			end
			if (UnBotFastJunkRaid.currentGroupOnly) then
				for _, name in ipairs(UnBotFastJunkRaid.queue or {}) do
					if (UnBotFastJunkRaid.targetNames[name]) then
						UnBotBuffCycleSendWhisper(name, "summon");
					end
				end
			else
				local channel = UnBotFastJunkRaidGroupChannel();
				if (channel) then
					SendChatMessage("summon", channel);
				end
			end
			UnBotFastJunkRaid.stage = "summon";
			UnBotFastJunkRaid.nextTime = now + 2.5;
			return;
		end
		if (now >= (UnBotFastJunkRaid.stageUntil or 0)) then
			UnBotFastJunkRaidStop("Быстрая продажа остановлена: набор рейда завис.", true);
			return;
		end
		if (
			memberCount + pendingCount < (UnBotFastJunkRaid.batchSize or 39)
			and UnBotFastJunkRaid.queueIndex < #UnBotFastJunkRaid.queue
			and not classBoundary
		) then
			UnBotFastJunkRaid.queueIndex = UnBotFastJunkRaid.queueIndex + 1;
			local name = UnBotFastJunkRaid.queue[UnBotFastJunkRaid.queueIndex];
			UnBotFastJunkRaid.currentBatch[name] = true;
			UnBotFastJunkRaid.pending[name] = now + 12;
			SendChatMessage(".playerbot bot add "..name, "SAY");
			UnBotFastJunkRaid.nextTime = now + 0.15;
		else
			UnBotFastJunkRaid.nextTime = now + 0.25;
		end
	elseif (UnBotFastJunkRaid.stage == "summon") then
		if (UnBotFastJunkRaid.currentGroupOnly) then
			for _, name in ipairs(UnBotFastJunkRaid.queue or {}) do
				if (UnBotFastJunkRaid.targetNames[name]) then
					UnBotBuffCycleSendWhisper(name, "stay");
					UnBotFastJunkRaid.stayedNames[name] = true;
				end
			end
		else
			local channel = UnBotFastJunkRaidGroupChannel();
			if (channel) then
				SendChatMessage("stay", channel);
				for name in pairs(UnBotSpecSummonGetMembers()) do
					if (name ~= UnitName("player")) then
						UnBotFastJunkRaid.stayedNames[name] = true;
					end
				end
			end
		end
		-- Сначала фиксируем переход: даже ошибка взаимодействия с NPC не должна
		-- оставлять автомат на стадии, которая повторно рассылает рейду `stay`.
		UnBotFastJunkRaid.stage = "sell";
		UnBotFastJunkRaid.nextTime = now + 1.5;
		UnBotFastJunkRaidReopenMerchant();
	elseif (UnBotFastJunkRaid.stage == "sell") then
		UnBotFastJunkRaidReopenMerchant();
		local channel = UnBotFastJunkRaidGroupChannel();
		if (not channel) then
			UnBotFastJunkRaidStop("Быстрая продажа остановлена: группа неожиданно распалась.", false);
			return;
		end
		if (UnBotFastJunkRaid.mode == "reagents") then
			SendChatMessage("s *", channel);
			UnBotSpecSummonMessage(
				"Быстрая закупка ["..tostring(UnBotFastJunkRaid.batchClass)
				.."]: продан только серый хлам; через 4 секунды начнётся покупка."
			);
			UnBotFastJunkRaid.stage = "prepare_buy";
			UnBotFastJunkRaid.nextTime = now + 4;
		else
			if (UnBotFastJunkRaid.currentGroupOnly) then
				for _, name in ipairs(UnBotFastJunkRaid.queue or {}) do
					if (UnBotFastJunkRaid.targetNames[name]) then
						UnBotBuffCycleSendWhisper(name, "s *");
					end
				end
			else
				SendChatMessage("s *", channel);
			end
			local soldCount = UnBotFastJunkRaidRecordSaleAttempt();
			UnBotSpecSummonMessage(
				"Быстрая продажа: команда `s *` отправлена "
				..(UnBotFastJunkRaid.accountAltsOnly and "разрешённым альтам " or (UnBotFastJunkRaid.currentGroupOnly and "обычным ботам группы " or "рейду "))
				..tostring(UnBotFastJunkRaid.batchNumber).." (участников "
				..tostring(soldCount)..")."
			);
			UnBotFastJunkRaid.stage = "leave";
			UnBotFastJunkRaid.nextTime = now + 4;
		end
	elseif (UnBotFastJunkRaid.stage == "prepare_buy") then
		UnBotFastJunkRaidReopenMerchant();
		local reagentCount = UnBotFastJunkRaidPrepareBuyQueue();
		if (reagentCount == 0) then
			UnBotSpecSummonMessage(
				"Быстрая закупка: у торговца нет реагентов для класса "
				..tostring(UnBotFastJunkRaid.batchClass).."."
			);
			UnBotFastJunkRaidRecordSaleAttempt();
			UnBotFastJunkRaid.stage = "leave";
			UnBotFastJunkRaid.nextTime = now + 1;
		else
			UnBotFastJunkRaid.stage = "buy";
			UnBotFastJunkRaid.nextTime = now;
			UnBotSpecSummonMessage(
				"Быстрая закупка ["..tostring(UnBotFastJunkRaid.batchClass)
				.."]: позиций реагентов "..tostring(reagentCount)
				..". Покупка идёт всему рейду одновременно."
			);
		end
	elseif (UnBotFastJunkRaid.stage == "buy") then
		local reagent = UnBotFastJunkRaid.buyQueue[UnBotFastJunkRaid.buyIndex];
		if (not reagent) then
			UnBotFastJunkRaid.stage = "finish_buy";
			UnBotFastJunkRaid.nextTime = now + 3;
		else
			if ((UnBotFastJunkRaid.buyRemaining or 0) <= 0) then
				UnBotFastJunkRaid.buyIndex = UnBotFastJunkRaid.buyIndex + 1;
				reagent = UnBotFastJunkRaid.buyQueue[UnBotFastJunkRaid.buyIndex];
				UnBotFastJunkRaid.buyRemaining = reagent and reagent.commands or 0;
				UnBotFastJunkRaid.nextTime = now + 0.5;
			else
				local channel = UnBotFastJunkRaidGroupChannel();
				if (not channel) then
					UnBotFastJunkRaidStop("Быстрая закупка остановлена: рейд распался.", false);
					return;
				end
				SendChatMessage("b "..reagent.link, channel);
				UnBotFastJunkRaid.buyRemaining = UnBotFastJunkRaid.buyRemaining - 1;
				if (
					UnBotFastJunkRaid.buyRemaining == 0
					or UnBotFastJunkRaid.buyRemaining % 25 == 0
				) then
					UnBotSpecSummonMessage(
						"Закупка ["..tostring(UnBotFastJunkRaid.batchClass).."] "
						..tostring(reagent.label)..": осталось групповых команд "
						..tostring(UnBotFastJunkRaid.buyRemaining).."."
					);
				end
				-- Одна команда заставляет купить предмет весь рейд. Пауза не даёт
				-- серверу получить сотни одновременных действий одним пакетом.
				UnBotFastJunkRaid.nextTime = now + 0.5;
			end
		end
	elseif (UnBotFastJunkRaid.stage == "finish_buy") then
		local processed = UnBotFastJunkRaidRecordSaleAttempt();
		UnBotSpecSummonMessage(
			"Быстрая закупка ["..tostring(UnBotFastJunkRaid.batchClass)
			.."] завершена для рейда из "..tostring(processed).." ботов."
		);
		UnBotFastJunkRaid.stage = "leave";
		UnBotFastJunkRaid.nextTime = now + 1;
	elseif (UnBotFastJunkRaid.stage == "leave") then
		if (UnBotFastJunkRaid.currentGroupOnly) then
			UnBotFastJunkRaidStop(
				(UnBotFastJunkRaid.accountAltsOnly
					and "Продажа хлама альтов завершена: серый хлам обработан у "
					or "Быстрая продажа обычных ботов завершена: серый хлам обработан у ")
				..tostring(UnBotFastJunkRaid.processed or 0)
				..(UnBotFastJunkRaid.accountAltsOnly and " альтов. " or " ботов. ")
				.."Состав группы не изменён.",
				false
			);
			return;
		end
		local channel = UnBotFastJunkRaidGroupChannel();
		if (channel) then
			SendChatMessage("leave", channel);
		end
		UnBotFastJunkRaid.stage = "wait_cleanup";
		UnBotFastJunkRaid.stageUntil = now + 6;
		UnBotFastJunkRaid.nextTime = now + 0.5;
	elseif (UnBotFastJunkRaid.stage == "wait_cleanup") then
		local memberCount = UnBotFastJunkRaidMemberCount();
		if (memberCount == 0) then
			UnBotFastJunkRaidStartBatch();
		elseif (now >= (UnBotFastJunkRaid.stageUntil or 0)) then
			if (not UnBotFastJunkRaid.fallbackCleanupSent) then
				UnBotSpecSummonMessage(
					"Быстрая продажа: после общей команды осталось "
					..tostring(memberCount).." ботов; удаляю их поимённо."
				);
				UnBotFastJunkRaidFallbackCleanup();
				UnBotFastJunkRaid.nextTime = now + 0.5;
			else
				UnBotFastJunkRaidStop(
					"Быстрая продажа остановлена: в группе зависло ботов "
					..tostring(memberCount)..". Следующий рейд не вызывается во избежание серверного лимита 39.",
					false
				);
			end
		else
			UnBotFastJunkRaid.nextTime = now + 0.5;
		end
	end
end);

local junkCleanerFrame = CreateFrame("Frame", "UnBotJunkCleanerFrame");
junkCleanerFrame:RegisterEvent("PARTY_MEMBERS_CHANGED");
junkCleanerFrame:RegisterEvent("RAID_ROSTER_UPDATE");
junkCleanerFrame:RegisterEvent("CHAT_MSG_WHISPER");
junkCleanerFrame:RegisterEvent("TRADE_SHOW");
junkCleanerFrame:RegisterEvent("PLAYER_LOGOUT");
junkCleanerFrame:SetScript("OnEvent", function(self, event, message, sender)
	if (event == "PLAYER_LOGOUT") then
		-- `/reload` and normal logout write SavedVariables immediately after this
		-- event. Reattach both registry names to the checkpointed live table.
		UnBotSquadConfig = UnBotSquadConfig or {};
		UnBotSquadConfig.botRegistry = UnBotBotRegistry;
		return;
	end
	if (event == "TRADE_SHOW" and UnBotJunkCleaner.active) then
		if (CancelTrade) then
			CancelTrade();
		end
		UnBotJunkCleaner.merchantReopenAt = GetTime() + 0.35;
		UnBotSpecSummonMessage(
			"Продажа хлама: нежелательный обмен с ботом автоматически отклонён."
		);
		return;
	end
	if (
		event == "CHAT_MSG_WHISPER"
		and UnBotJunkCleaner.active
		and (
			UnBotJunkCleaner.stage == "wait_reagent_query"
			or UnBotJunkCleaner.stage == "wait_reagent_verify"
		)
		and sender == UnBotJunkCleaner.currentName
	) then
		if (string.find(tostring(message or ""), "=== Inventory ===", 1, true)) then
			UnBotJunkCleaner.queryHeaderSeen = true;
		end
		local queryItem = UnBotJunkCleaner.queryItem;
		if (
			queryItem
			and string.find(
				tostring(message or ""),
				"Hitem:"..tostring(queryItem.id)..":",
				1,
				true
			)
		) then
			UnBotJunkCleaner.queryHeaderSeen = true;
			UnBotJunkCleaner.queryCount =
				tonumber(string.match(tostring(message), "[xх](%d+)")) or 1;
			UnBotJunkCleaner.nextTime = GetTime() + 0.1;
		end
		return;
	end
	if (
		event == "CHAT_MSG_WHISPER"
		and UnBotJunkCleaner.active
		and UnBotJunkCleaner.stage == "wait_extended_sell"
		and sender == UnBotJunkCleaner.currentName
	) then
		local reply = string.lower(tostring(message or ""));
		if (string.find(reply, "selling", 1, true)
			and UnBotJunkCleaner.extendedSellCandidate
			and tonumber(string.match(tostring(message), "Hitem:(%d+):")) == UnBotJunkCleaner.extendedSellCandidate.id) then
			UnBotJunkCleaner.extendedSellConfirmed =
				(tonumber(UnBotJunkCleaner.extendedSellConfirmed) or 0) + 1;
			UnBotJunkCleaner.extendedSellCandidate = nil;
			UnBotJunkCleaner.extendedSellRetries = 0;
			UnBotJunkCleaner.stage = "sell_extended";
			UnBotJunkCleaner.nextTime = GetTime() + 0.45;
		elseif (string.find(reply, "cooldown", 1, true)) then
			local waitSeconds = tonumber(string.match(reply, "(%d+)%s+second")) or 3;
			UnBotJunkCleaner.stage = "sell_extended";
			UnBotJunkCleaner.nextTime = math.min(GetTime() + math.min(waitSeconds, 10) + 0.5,
				UnBotJunkCleaner.extendedSellUntil or GetTime());
		elseif (
			string.find(reply, "cannot sell", 1, true)
			or string.find(reply, "can't sell", 1, true)
			or string.find(reply, "not found", 1, true)
			or string.find(reply, "no items", 1, true)
		) then
			UnBotJunkCleaner.extendedSellCandidate = nil;
			UnBotJunkCleaner.extendedSellRetries = 0;
			UnBotJunkCleaner.stage = "sell_extended";
			UnBotJunkCleaner.nextTime = GetTime() + 0.3;
		end
		return;
	end
	if (
		event == "CHAT_MSG_WHISPER"
		and UnBotJunkCleaner.active
		and UnBotJunkCleaner.stage == "wait_stats"
		and UnBotJunkCleanerStatsSenderMatches(sender)
	) then
		if (UnBotJunkCleanerRecordStatsLine(message)) then
			UnBotJunkCleaner.nextTime = GetTime() + 0.4;
		end
		return;
	end
	if (
		event == "CHAT_MSG_WHISPER"
		and UnBotJunkCleaner.active
		and UnBotJunkCleaner.stage == "wait_inventory_audit"
		and sender == UnBotJunkCleaner.currentName
	) then
		UnBotJunkCleanerRecordInventoryAuditLine(message);
		UnBotJunkCleaner.nextTime = math.min(GetTime() + 1.2, UnBotJunkCleaner.inventoryAuditUntil or GetTime());
		return;
	end
	if (UnBotJunkCleaner.active and UnBotJunkCleaner.stage == "wait_member") then
		UnBotJunkCleanerAcceptCurrent();
	end
end);

junkCleanerFrame:SetScript("OnUpdate", function()
	local now = GetTime();
	if (
		UnBotJunkCleaner.active
		and now >= (tonumber(UnBotJunkCleaner.afkCheckAt) or 0)
	) then
		UnBotJunkCleaner.afkCheckAt = now + 2;
		if (UnitIsAFK and UnitIsAFK("player")) then
			if ((tonumber(UnBotJunkCleaner.afkClearAttempts) or 0) < 3) then
				UnBotJunkCleaner.afkClearAttempts =
					(tonumber(UnBotJunkCleaner.afkClearAttempts) or 0) + 1;
				if (SendChatMessage) then
					SendChatMessage("", "AFK");
				end
			elseif (not UnBotJunkCleaner.afkFailureReported) then
				UnBotJunkCleaner.afkFailureReported = true;
				UnBotSpecSummonMessage(
					"Защита от AFK: клиент не снял статус после трёх попыток. "
					.."Дальнейшие попытки снятия остановлены; снимите AFK вручную."
				);
			end
		elseif ((tonumber(UnBotJunkCleaner.afkClearAttempts) or 0) > 0) then
			if (not UnBotJunkCleaner.afkFailureReported) then
				UnBotJunkCleaner.afkClearCount =
					(tonumber(UnBotJunkCleaner.afkClearCount) or 0) + 1;
			end
			UnBotJunkCleaner.afkClearAttempts = 0;
			if (UnBotJunkCleaner.afkFailureReported) then
				UnBotJunkCleaner.afkFailureReported = false;
				UnBotSpecSummonMessage(
					"Защита от AFK: статус снят вручную; автоматическая проверка снова включена."
				);
			elseif (
				UnBotJunkCleaner.afkClearCount == 1
				or now >= (tonumber(UnBotJunkCleaner.afkLastReportAt) or 0) + 3600
			) then
				UnBotJunkCleaner.afkLastReportAt = now;
				UnBotSpecSummonMessage(
					"Защита от AFK: статус автоматически снят; цикл продолжается "
					.."(срабатываний "..tostring(UnBotJunkCleaner.afkClearCount)..")."
				);
			end
		end
	end
	if (
		UnBotJunkCleaner.active
		and UnBotJunkCleaner.merchantReopenAt
		and now >= UnBotJunkCleaner.merchantReopenAt
	) then
		UnBotJunkCleaner.merchantReopenAt = nil;
		UnBotJunkCleanerReopenMerchant();
	end
	for name, expiresAt in pairs(UnBotJunkCleaner.requestedNames or {}) do
		if (
			name ~= UnBotJunkCleaner.currentName
			and UnBotSpecSummonIsInGroup(name)
			and not (UnBotBuffCycle.cleanup and UnBotBuffCycle.cleanup[name])
		) then
			UnBotSpecSummonUninvite(name);
			UnBotBuffCycle.cleanup[name] = {
				removeSent = false,
				nextTime = now + 0.5,
				untilTime = now + 30,
			};
			UnBotJunkCleaner.requestedNames[name] = nil;
			UnBotSpecSummonMessage("Junk registry: caught delayed bot "..name.."; removing it safely.");
		elseif (now >= (expiresAt or 0) and not UnBotSpecSummonIsInGroup(name)) then
			UnBotJunkCleaner.requestedNames[name] = nil;
		end
	end
	if (not UnBotJunkCleaner.active or now < (UnBotJunkCleaner.nextTime or 0)) then
		return;
	end
	local name = UnBotJunkCleaner.currentName;

	if (UnBotJunkCleaner.stage == "wait_member") then
		if (not UnBotJunkCleanerAcceptCurrent()) then
			if (now >= UnBotJunkCleaner.stageUntil) then
				UnBotJunkCleaner.failed = UnBotJunkCleaner.failed + 1;
				if (UnBotJunkCleaner.bagAuditOnly) then
					UnBotSpecSummonMessage(
						"Проверка сумок: "..tostring(name)
						.." не вошёл в группу и остался в незавершённом checkpoint."
					);
				else
					UnBotSpecSummonMessage(
						"Junk registry: "..tostring(name)
						.." did not join and was skipped without an unsafe remove command."
					);
				end
				UnBotJunkCleanerStartNext();
			else
				UnBotJunkCleaner.nextTime = now + 0.25;
			end
		end
	elseif (UnBotJunkCleaner.stage == "bag_stats") then
		UnBotJunkCleanerStartStatsOrFinish();
	elseif (UnBotJunkCleaner.stage == "sell") then
		if (not MerchantFrame or not MerchantFrame:IsShown()) then
			UnBotJunkCleanerReopenMerchant();
		end
		UnBotBuffCycleSendWhisper(name, "s *");
		UnBotJunkCleaner.stage = "wait_sell";
		UnBotJunkCleaner.nextTime = now + 3;
	elseif (UnBotJunkCleaner.stage == "wait_sell") then
		local rescanned, rescannedCount = UnBotJunkCleanerScanMerchantReagents();
		UnBotJunkCleaner.merchantReagents = rescanned;
		UnBotJunkCleaner.merchantReagentCount = rescannedCount;
		if (UnBotJunkCleaner.singleMode or UnBotJunkCleaner.deepVendorCleanup) then
			UnBotJunkCleanerStartInventoryAuditOrFinish();
		else
			UnBotSpecSummonMessage("Обычное обслуживание "..tostring(name)..": серый хлам продан; классовые и профессиональные предметы сохранены.");
			UnBotJunkCleaner.BeginProtectedRestock();
		end
	elseif (UnBotJunkCleaner.stage == "next_reagent") then
		UnBotJunkCleaner.reagentIndex = UnBotJunkCleaner.reagentIndex + 1;
		local reagent = UnBotJunkCleaner.reagentQueue[UnBotJunkCleaner.reagentIndex];
		if (not reagent) then
			UnBotJunkCleanerStartInventoryAuditOrFinish();
		else
			UnBotJunkCleaner.queryItem = reagent;
			reagent.verifyRetries = 0;
			UnBotJunkCleaner.queryCount = nil;
			UnBotJunkCleaner.queryHeaderSeen = false;
			UnBotBuffCycleSendWhisper(name, "c "..reagent.link);
			UnBotJunkCleaner.stage = "wait_reagent_query";
			UnBotJunkCleaner.nextTime = now + 2.5;
		end
	elseif (UnBotJunkCleaner.stage == "wait_reagent_query") then
		local reagent = UnBotJunkCleaner.queryItem;
		if (not reagent) then
			UnBotJunkCleaner.stage = "next_reagent";
			UnBotJunkCleaner.nextTime = now;
		elseif (not UnBotJunkCleaner.queryHeaderSeen) then
			UnBotSpecSummonMessage(
				"Реагенты: "..tostring(name).." не подтвердил количество "
				..tostring(reagent.label).."; покупка пропущена безопасно."
			);
			UnBotJunkCleaner.stage = "next_reagent";
			UnBotJunkCleaner.nextTime = now;
		else
			local currentCount = tonumber(UnBotJunkCleaner.queryCount) or 0;
			UnBotRegistryStoreReagentCount(name, reagent.id, currentCount);
			UnBotJunkCleaner.queryBeforeCount = currentCount;
			local missing = math.max(0, (tonumber(reagent.target) or 0) - currentCount);
			local bundleSize = math.max(1, tonumber(reagent.bundleSize) or 1);
			UnBotJunkCleaner.purchasesRemaining = math.ceil(missing / bundleSize);
			if (UnBotJunkCleaner.purchasesRemaining > 0) then
				UnBotSpecSummonMessage(
					"Реагенты: "..name.." | "..tostring(reagent.label)
					.." "..tostring(currentCount).."/"..tostring(reagent.target)
					.." | покупок "..tostring(UnBotJunkCleaner.purchasesRemaining).."."
				);
				UnBotJunkCleaner.stage = "buy_reagent";
				UnBotJunkCleaner.nextTime = now;
			else
				UnBotJunkCleaner.stage = "next_reagent";
				UnBotJunkCleaner.nextTime = now;
			end
		end
	elseif (UnBotJunkCleaner.stage == "buy_reagent") then
		if (not MerchantFrame or not MerchantFrame:IsShown()) then
			UnBotJunkCleanerReopenMerchant();
		end
		local reagent = UnBotJunkCleaner.queryItem;
		if (not reagent or UnBotJunkCleaner.purchasesRemaining <= 0) then
			UnBotJunkCleaner.stage = "start_reagent_verify";
			-- Покупки на сервере применяются с задержкой. Ранняя проверка видела
			-- неполный стек и запускала лишний добор поверх целевого количества.
			UnBotJunkCleaner.nextTime = now + 3.5;
		else
			UnBotBuffCycleSendWhisper(name, "b "..reagent.link);
			UnBotJunkCleaner.purchasesRemaining = UnBotJunkCleaner.purchasesRemaining - 1;
			UnBotJunkCleaner.nextTime = now + 0.65;
		end
	elseif (UnBotJunkCleaner.stage == "start_reagent_verify") then
		local reagent = UnBotJunkCleaner.queryItem;
		if (not reagent) then
			UnBotJunkCleaner.stage = "next_reagent";
			UnBotJunkCleaner.nextTime = now;
		else
			UnBotJunkCleaner.queryCount = nil;
			UnBotJunkCleaner.queryHeaderSeen = false;
			UnBotBuffCycleSendWhisper(name, "c "..reagent.link);
			UnBotJunkCleaner.stage = "wait_reagent_verify";
			UnBotJunkCleaner.nextTime = now + 2.5;
		end
	elseif (UnBotJunkCleaner.stage == "wait_reagent_verify") then
		local reagent = UnBotJunkCleaner.queryItem;
		if (not reagent) then
			UnBotJunkCleaner.stage = "next_reagent";
			UnBotJunkCleaner.nextTime = now;
		elseif (not UnBotJunkCleaner.queryHeaderSeen) then
			UnBotSpecSummonMessage(
				"Реагенты: "..tostring(name).." не подтвердил итоговый запас "
				..tostring(reagent.label).."; результат не засчитан."
			);
			UnBotJunkCleaner.stage = "next_reagent";
			UnBotJunkCleaner.nextTime = now;
		else
			local finalCount = tonumber(UnBotJunkCleaner.queryCount) or 0;
			UnBotRegistryStoreReagentCount(name, reagent.id, finalCount);
			local bought = math.max(
				0,
				finalCount - (tonumber(UnBotJunkCleaner.queryBeforeCount) or 0)
			);
			UnBotJunkCleaner.currentRestocked =
				UnBotJunkCleaner.currentRestocked + bought;
			UnBotJunkCleaner.restockedItems =
				UnBotJunkCleaner.restockedItems + bought;
			local targetCount = tonumber(reagent.target) or 0;
			if (finalCount < targetCount and (tonumber(reagent.verifyRetries) or 0) < 3) then
				reagent.verifyRetries = (tonumber(reagent.verifyRetries) or 0) + 1;
				local bundleSize = math.max(1, tonumber(reagent.bundleSize) or 1);
				UnBotJunkCleaner.queryBeforeCount = finalCount;
				UnBotJunkCleaner.purchasesRemaining =
					math.ceil((targetCount - finalCount) / bundleSize);
				UnBotSpecSummonMessage(
					"Реагентов пока недостаточно: "..name.." | "..tostring(reagent.label)
					.." "..tostring(finalCount).."/"..tostring(targetCount)
					.." | добираем ещё "..tostring(UnBotJunkCleaner.purchasesRemaining)
					.." (повтор "..tostring(reagent.verifyRetries).."/3)."
				);
				UnBotJunkCleaner.stage = "buy_reagent";
				UnBotJunkCleaner.nextTime = now + 0.8;
			else
				local statusText = finalCount >= targetCount
					and "Реагенты подтверждены: "
					or "Реагенты закуплены частично после трёх повторов: ";
				UnBotSpecSummonMessage(
					statusText..name.." | "..tostring(reagent.label)
					.." "..tostring(finalCount).."/"..tostring(targetCount)
					.." | последняя покупка "..tostring(bought).."."
				);
				UnBotJunkCleaner.stage = "next_reagent";
				UnBotJunkCleaner.nextTime = now + 0.2;
			end
		end
	elseif (UnBotJunkCleaner.stage == "wait_stats") then
		if (
			not UnBotJunkCleaner.statsReceived
			and (tonumber(UnBotJunkCleaner.statsAttempts) or 0) < 2
		) then
			UnBotJunkCleaner.statsAttempts =
				(tonumber(UnBotJunkCleaner.statsAttempts) or 0) + 1;
			UnBotBuffCycleSendWhisper(name, "stats");
			UnBotJunkCleaner.nextTime = now + 7;
			return;
		end
		if (UnBotJunkCleaner.bagAuditOnly) then
			if (UnBotJunkCleaner.statsReceived) then
				UnBotBagSpaceAuditFinishCurrent();
			else
				UnBotBagSpaceAuditFailCurrent();
			end
			return;
		end
		if (UnBotJunkCleaner.statsReceived) then
			local occupancy = UnBotJunkCleaner.bagSlotsUsed and UnBotJunkCleaner.bagSlotsTotal
				and ("; занято "..tostring(UnBotJunkCleaner.bagSlotsUsed)
					.."/"..tostring(UnBotJunkCleaner.bagSlotsTotal)) or "";
			UnBotSpecSummonMessage(
				"Сумки "..tostring(name)..": свободно "
				..tostring(UnBotJunkCleaner.freeBagSlots or 0).." ячеек"..occupancy.."."
			);
		else
			UnBotSpecSummonMessage(
				"Сумки "..tostring(name)
				..": ответ `stats` не получен после двух запросов; "
				.."в реестре оставлено прежнее значение."
			);
		end
		UnBotJunkCleanerFinishCurrent();
	elseif (UnBotJunkCleaner.stage == "wait_inventory_audit") then
		UnBotJunkCleanerFinishInventoryAudit();
	elseif (UnBotJunkCleaner.stage == "sell_extended") then
		if (not MerchantFrame or not MerchantFrame:IsShown()) then
			UnBotJunkCleanerReopenMerchant();
		end
		local candidate = UnBotJunkCleaner.extendedSellCandidate;
		if (not candidate) then
			UnBotJunkCleaner.extendedSellIndex =
				(tonumber(UnBotJunkCleaner.extendedSellIndex) or 0) + 1;
			candidate = UnBotJunkCleaner.extendedSellQueue[UnBotJunkCleaner.extendedSellIndex];
			UnBotJunkCleaner.extendedSellCandidate = candidate;
			UnBotJunkCleaner.extendedSellRetries = 0;
			UnBotJunkCleaner.extendedSellUntil = now + 12;
		end
		if (not candidate) then
			UnBotSpecSummonMessage(
				"Расширенная очистка "..tostring(name)..": отправлено команд продажи "
				..tostring(UnBotJunkCleaner.extendedSellRequested or 0)
				..", подтверждено "..tostring(UnBotJunkCleaner.extendedSellConfirmed or 0)
				..". Проверяем запас реагентов и содержимое сумок."
			);
			UnBotJunkCleaner.BeginProtectedRestock();
		elseif (now >= (UnBotJunkCleaner.extendedSellUntil or 0)
			or (tonumber(candidate.attempts) or 0) >= 2
			or not UnBotJunkCleanerShouldExtendedSell(candidate.id, candidate.label, candidate.message, nil, candidate.link)) then
			UnBotSpecSummonMessage("Расширенная продажа: сохранён предмет "..tostring(candidate.label).." (защита или лимит попыток).");
			UnBotJunkCleaner.extendedSellCandidate = nil;
			UnBotJunkCleaner.nextTime = now + 0.3;
		else
			candidate.attempts = (tonumber(candidate.attempts) or 0) + 1;
			UnBotBuffCycleSendWhisper(name, "s "..tostring(candidate.link));
			UnBotJunkCleaner.extendedSellRequested =
				(tonumber(UnBotJunkCleaner.extendedSellRequested) or 0) + 1;
			UnBotSpecSummonMessage(
				"Расширенная продажа "..tostring(UnBotJunkCleaner.extendedSellIndex).."/"
				..tostring(#UnBotJunkCleaner.extendedSellQueue)..": "
				..tostring(candidate.label)
				..((tonumber(UnBotJunkCleaner.extendedSellRetries) or 0) > 0 and " (повтор)." or ".")
			);
			UnBotJunkCleaner.stage = "wait_extended_sell";
			UnBotJunkCleaner.nextTime = now + 3.5;
		end
	elseif (UnBotJunkCleaner.stage == "wait_extended_sell") then
		if ((tonumber(UnBotJunkCleaner.extendedSellRetries) or 0) < 1) then
			UnBotJunkCleaner.extendedSellRetries =
				(tonumber(UnBotJunkCleaner.extendedSellRetries) or 0) + 1;
			UnBotJunkCleaner.stage = "sell_extended";
			UnBotJunkCleaner.nextTime = now + 0.2;
		else
			UnBotSpecSummonMessage(
				"Расширенная продажа: нет подтверждения от "..tostring(name)
				.." для "..tostring(
					UnBotJunkCleaner.extendedSellCandidate
					and UnBotJunkCleaner.extendedSellCandidate.label
					or "неизвестного предмета"
				).."; переходим дальше."
			);
			UnBotJunkCleaner.extendedSellCandidate = nil;
			UnBotJunkCleaner.extendedSellRetries = 0;
			UnBotJunkCleaner.stage = "sell_extended";
			UnBotJunkCleaner.nextTime = now + 0.3;
		end
	elseif (UnBotJunkCleaner.stage == "wait_leave") then
		if (not UnBotSpecSummonIsInGroup(name) or now >= UnBotJunkCleaner.stageUntil) then
			UnBotJunkCleanerStartNext();
		else
			UnBotSpecSummonUninvite(name);
			UnBotJunkCleaner.nextTime = now + 0.75;
		end
	end
end);

UnBotBotScanner = {
	active = false,
	stopRequested = false,
	stage = nil,
	nextTime = 0,
	stageUntil = 0,
	classes = {"warrior", "paladin", "hunter", "rogue", "priest", "shaman", "mage", "warlock", "druid", "dk"},
	classQueue = {},
	classIndex = 0,
	className = nil,
	round = 0,
	maxRounds = 12,
	emptyFullRounds = 0,
	requiredEmptyFullRounds = 3,
	noJoinAttempts = 0,
	maxNoJoinAttempts = 3,
	knownMembers = {},
	currentName = nil,
	whoAttempts = 0,
	maxWhoAttempts = 3,
	batchNames = {},
	batchOrder = {},
	batchCount = 0,
	newThisRound = 0,
	newThisRun = 0,
	scannedThisRun = {},
	finalizedClasses = {},
	failedClasses = {},
	deferredAttempts = {},
	maxDeferredRetries = 2,
	runStartedAt = 0,
	runStartedServerTime = 0,
	nextProgressMessage = 0,
	endedByFullRaid = false,
	cleanupIndex = 1,
	cleanupUntil = 0,
	lateCleanupUntil = 0,
	lateCleanupNames = {},
	cleanupOwnedNames = {},
	autoReloadPending = false,
	autoReloadNotBefore = 0,
	autoReloadQuietUntil = 0,
	autoReloadDeadline = 0,
	stopText = nil,
	scanId = nil,
	scopeClass = nil,
	pendingSpecBalanceClass = nil,
	pendingSpecBalanceMinimum = 8,
	pendingSpecBalanceNotBefore = 0,
	pendingSpecBalanceDeadline = 0,
	pendingSpecBalanceResumeReady = false,
};

_G.UnBotBotScanner = UnBotBotScanner;

function UnBotClassSpecRebuildCheckpointSet(className, minimumCount, phase)
	UnBotSquadConfig = UnBotSquadConfig or {};
	local checkpoint = UnBotSquadConfig.specClassRebuildCheckpoint;
	if (type(checkpoint) ~= "table" or checkpoint.className ~= className) then
		checkpoint = {
			className = className,
			startedAt = time(),
		};
	end
	checkpoint.minimumCount = math.max(1, math.min(12, tonumber(minimumCount) or 8));
	checkpoint.phase = phase;
	checkpoint.updatedAt = time();
	checkpoint.registryContext = UnBotSquadConfig.activeBotRegistryContext;
	UnBotSquadConfig.specClassRebuildCheckpoint = checkpoint;
	return checkpoint;
end

function UnBotClassSpecRebuildCheckpointClear()
	if (UnBotSquadConfig) then
		UnBotSquadConfig.specClassRebuildCheckpoint = nil;
	end
end

local UnBotBotScannerClassFiles = {
	WARRIOR = "warrior",
	PALADIN = "paladin",
	HUNTER = "hunter",
	ROGUE = "rogue",
	PRIEST = "priest",
	SHAMAN = "shaman",
	MAGE = "mage",
	WARLOCK = "warlock",
	DRUID = "druid",
	DEATHKNIGHT = "dk",
};

local function UnBotBotScannerFindUnit(name)
	if (GetNumRaidMembers() and GetNumRaidMembers() > 0) then
		for i = 1, GetNumRaidMembers(), 1 do
			local unit = "raid"..i;
			if (GetRaidRosterInfo(i) == name or UnitName(unit) == name) then
				return unit;
			end
		end
	else
		for i = 1, GetNumPartyMembers(), 1 do
			local unit = "party"..i;
			if (UnitName(unit) == name) then
				return unit;
			end
		end
	end
	return nil;
end

local function UnBotBotScannerFindNewMember()
	local members = UnBotSpecSummonGetMembers();
	for name in pairs(members) do
		if (
			name ~= UnitName("player")
			and not UnBotBotScanner.batchNames[name]
		) then
			return name;
		end
	end
	return nil;
end

local UnBotBotScannerPrintSummary;

local function UnBotBotScannerProfileCount(className)
	local count = 0;
	for name, profile in pairs(UnBotBotRegistry.bots or {}) do
		if (
			name
			and profile
			and not UnBotIsAccountAltProfile(name, profile)
			and (not className or profile.className == className)
		) then
			count = count + 1;
		end
	end
	return count;
end

local function UnBotBotScannerBuildClassQueue()
	local entries = {};
	for i = 1, #UnBotBotScanner.classes, 1 do
		local className = UnBotBotScanner.classes[i];
		local count = UnBotBotScannerProfileCount(className);
		local status = UnBotBotRegistry.meta.classStatus[className] or {};
		local priority = 3;
		if (count == 0 or status.lastResult == "unavailable") then
			priority = 1;
		elseif (not status.completed) then
			priority = 2;
		end
		table.insert(entries, { className = className, priority = priority, order = i });
	end
	table.sort(entries, function(a, b)
		if (a.priority == b.priority) then
			return a.order < b.order;
		end
		return a.priority < b.priority;
	end);

	local queue = {};
	for i = 1, #entries, 1 do
		table.insert(queue, entries[i].className);
	end
	return queue;
end

local function UnBotBotScannerFinalizedCount()
	local count = 0;
	for i = 1, #UnBotBotScanner.classes, 1 do
		if (UnBotBotScanner.finalizedClasses[UnBotBotScanner.classes[i]]) then
			count = count + 1;
		end
	end
	return count;
end

local function UnBotBotScannerFormatDuration(seconds)
	seconds = math.max(0, math.floor(tonumber(seconds) or 0));
	local minutes = math.floor(seconds / 60);
	local remainingSeconds = seconds % 60;
	if (minutes >= 60) then
		local hours = math.floor(minutes / 60);
		minutes = minutes % 60;
		return tostring(hours).."h "..tostring(minutes).."m";
	end
	return tostring(minutes).."m "..tostring(remainingSeconds).."s";
end

local function UnBotBotScannerProgressText()
	local done = UnBotBotScannerFinalizedCount();
	local totalClasses = UnBotBotScanner.scopeClass and 1 or #UnBotBotScanner.classes;
	local remaining = math.max(0, totalClasses - done);
	local elapsed = math.max(0, GetTime() - (UnBotBotScanner.runStartedAt or GetTime()));
	if UnBotBotScanner.fastDiscovery then
		local b=UnBotBotScanner.fastBatch or {};
		return "классы "..done.."/"..totalClasses..", "..tostring(UnBotBotScanner.className or "-")..", пачка "..tostring(UnBotBotScanner.round).."/"..(UnBotBotScanner.classRefresh and 1 or UnBotBotScanner.maxRounds)..", запросы "..(b.sent or 0).."/"..(UnBotBotScanner.fastBatchSize or 35)..", вошли "..(UnBotBotScanner.batchCount or 0)..(UnBotBotScanner.namesOnly and (", классов "..(b.classCount or 0)) or (", who "..(b.whoCount or 0)))..", новых +"..(UnBotBotScanner.newThisRun or 0)..", прошло "..UnBotBotScannerFormatDuration(elapsed);
	end
	local etaText = "ETA ?";
	if (done > 0 and remaining > 0) then
		local eta = (elapsed / done) * remaining;
		etaText = "ETA ~"..UnBotBotScannerFormatDuration(eta);
	elseif (remaining == 0) then
		etaText = "ETA 0m";
	end
	local currentProgress = tostring(UnBotBotScanner.batchCount or 0).."/39";
	if (UnBotBotScanner.stage == "cleanup") then
		currentProgress = "cleanup "
			..tostring(math.min((UnBotBotScanner.cleanupIndex or 1) - 1, UnBotBotScanner.batchCount or 0))
			.."/"..tostring(UnBotBotScanner.batchCount or 0);
	end
	return (
		"classes "..tostring(done).."/"..tostring(totalClasses)
		..", left "..tostring(remaining)
		..", current "..tostring(UnBotBotScanner.className or "-")
		.." "..currentProgress
		..", new +"..tostring(UnBotBotScanner.newThisRun or 0)
		..", таланты "..tostring(UnBotBotScanner.talentSuccess or 0).."/"..tostring(UnBotBotScanner.talentAttempts or 0)
		..(UnBotBotScanner.stage=="wait_talents" and (" — "..tostring(UnBotBotScanner.currentName)) or "")
		..", elapsed "..UnBotBotScannerFormatDuration(elapsed)
		..", "..etaText
	);
end

local function UnBotBotScannerPrintStatus()
	if (UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Bot scan progress: "..UnBotBotScannerProgressText()..".");
	else
		UnBotBotScannerPrintSummary();
		local lastFinished = UnBotBotRegistry.meta.lastScanFinished;
		if (lastFinished) then
			UnBotSpecSummonMessage(
				"Last scan: profiles "..tostring(UnBotBotRegistry.meta.lastScanProfiles or 0)
				..", new +"..tostring(UnBotBotRegistry.meta.lastScanNew or 0).."."
			);
		end
	end
end

local function UnBotBotScannerStorageStatus(relink)
	if (relink) then
		UnBotRegistryAttachStorage();
	end
	local linked = (
		UnBotSquadConfig
		and UnBotSquadConfig.botRegistry
		and UnBotSquadConfig.botRegistry == UnBotBotRegistry
	);
	UnBotSpecSummonMessage(
		"Bot registry storage: "..(linked and "LINKED" or "NOT LINKED")
		.." | memory profiles: "..tostring(UnBotBotScannerProfileCount())
		..". Saved to disk on the next /reload or normal logout."
	);
	return linked;
end

function UnBotBotScanner.OtherOwnerActive()
	return UnBotSpecSummon.active or UnBotBuffCycle.active
		or (UnBotPVPSummon and UnBotPVPSummon.active)
		or (UnBotSquadBuilder and UnBotSquadBuilder.postSummonSequence)
		or (UnBotJunkCleaner and UnBotJunkCleaner.active)
		or (UnBotFastJunkRaid and UnBotFastJunkRaid.active)
		or (UnBotDKSpecBalance and UnBotDKSpecBalance.active)
		or (UnBotBotFix and UnBotBotFix.active)
		or (UnBotRaidReserve and UnBotRaidReserve.active)
		or (UnBotFullTalentCatalog and (UnBotFullTalentCatalog.active or UnBotFullTalentCatalog.cleanup))
		or (UnBotStrategySurvey and UnBotStrategySurvey.active)
		or (UnBotMythicPlusBuffIsRunning and UnBotMythicPlusBuffIsRunning());
end

function UnBotBotScanner.RememberCleanupMembers()
	UnBotBotScanner.cleanupOwnedNames = UnBotBotScanner.cleanupOwnedNames or {};
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		unit = unit or UnBotBotScannerFindUnit(name);
		if (UnBotIsValidBotName(name) and unit and UnitIsConnected(unit)
			and not UnBotSpecSummon.CleanupProtected(name)
			and not UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots and UnBotBotRegistry.bots[name])) then
			UnBotBotScanner.cleanupOwnedNames[name] = true;
		end
	end);
end

local function UnBotBotScannerQueueLateCleanup(showMessage)
	-- A class-wide add has no reliable identity for an unseen late arrival.
	-- Only names observed while this scan owned the group may be removed.
	if (UnBotBotScanner.OtherOwnerActive() or UnitAffectingCombat("player") or InCombatLockdown()) then return 0; end
	local queued = 0;
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		unit = unit or UnBotBotScannerFindUnit(name);
		if (UnBotIsValidBotName(name) and unit and UnitIsConnected(unit)
			and UnBotBotScanner.cleanupOwnedNames and UnBotBotScanner.cleanupOwnedNames[name]
			and not UnBotSpecSummon.CleanupProtected(name)
			and not UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots and UnBotBotRegistry.bots[name])
			and not UnBotBotScanner.lateCleanupNames[name]) then
			UnBotBotScanner.lateCleanupNames[name] = true;
			UnBotSpecSummonUninvite(name);
			UnBotBuffCycle.cleanup[name] = {
				removeSent = false,
				nextTime = GetTime() + 0.5,
				untilTime = GetTime() + 30,
			};
			queued = queued + 1;
		end
	end);
	if (showMessage) then
		UnBotSpecSummonMessage(
			"Bot scan cleanup: "..tostring(queued)
			.." group members queued; only known bots of this scan are watched for 60 seconds."
		);
	end
	if (queued > 0 and UnBotBotScanner.autoReloadPending) then
		local now = GetTime();
		UnBotBotScanner.autoReloadQuietUntil = now + 10;
		UnBotBotScanner.lateCleanupUntil = math.max(
			UnBotBotScanner.lateCleanupUntil or 0,
			now + 10
		);
	end
	return queued;
end

local function UnBotBotScannerStartLateCleanup()
	if (UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Stop the active bot scan before running manual cleanup.");
		return;
	end
	if (UnBotBotScanner.OtherOwnerActive()) then
		UnBotSpecSummonMessage("Очистка скана: сначала завершите текущий призыв или другую операцию.");
		return;
	end
	-- Explicit manual cleanup acquires the currently visible online bots once.
	UnBotBotScanner.cleanupOwnedNames = {};
	UnBotBotScanner.RememberCleanupMembers();
	UnBotBotScanner.lateCleanupNames = {};
	UnBotBotScanner.lateCleanupUntil = GetTime() + 60;
	UnBotBotScannerQueueLateCleanup(true);
end

local function UnBotBotScannerStoreProfile(name, whoInfo, rawWho)
	if (not UnBotIsValidBotName(name)) then
		return false;
	end

	local bots = UnBotBotRegistry.bots;
	local profile = bots[name];
	local isNew = profile == nil;
	if (not profile) then
		profile = {
			name = name,
			firstSeen = time(),
			seenCount = 0,
		};
		bots[name] = profile;
	end

	local unit = UnBotBotScannerFindUnit(name);
	if (unit) then
		local localizedClass, classFile = UnitClass(unit);
		local localizedRace, raceFile = UnitRace(unit);
		local level = UnitLevel(unit);
		profile.classLocalized = localizedClass or profile.classLocalized;
		profile.classFile = classFile or profile.classFile;
		profile.className = (classFile and UnBotBotScannerClassFiles[classFile]) or profile.className;
		profile.raceLocalized = localizedRace or profile.raceLocalized;
		profile.raceFile = raceFile or profile.raceFile;
		profile.level = (level and level > 0 and level) or profile.level;
		profile.sex = UnitSex(unit) or profile.sex;
	end

	if (whoInfo) then
		profile.className = whoInfo.className or profile.className;
		profile.specName = whoInfo.specName or profile.specName;
		profile.level = whoInfo.level or profile.level;
		profile.gearScore = whoInfo.gearScore or profile.gearScore;
		UnBotStoreFeralRole(profile, whoInfo);
	end
	if (rawWho and rawWho ~= "") then
		profile.rawWho = rawWho;
	end
	profile.name = name;
	profile.source = UnBotIsAccountAltProfile(name, profile) and "account-alt" or "full-scan";
	profile.lastSeen = time();
	profile.lastScanId = UnBotBotScanner.scanId;
	local scanHit = tostring(UnBotBotScanner.scanId).."|"..tostring(UnBotBotScanner.className).."|"..tostring(UnBotBotScanner.round);
	if (profile.lastScanHit ~= scanHit) then
		profile.seenCount = (profile.seenCount or 0) + 1;
		profile.lastScanHit = scanHit;
	end
	UnBotRememberKnownBot(name);
	-- Reassert the link on every profile write in case another UnBot window
	-- recreated its configuration table during the session.
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;

	if (isNew) then
		UnBotBotScanner.newThisRound = UnBotBotScanner.newThisRound + 1;
		UnBotBotScanner.newThisRun = UnBotBotScanner.newThisRun + 1;
	end
	UnBotBotScanner.scannedThisRun[name] = true;
	return isNew;
end

local function UnBotBotScannerProfileText(name, profile)
	profile = profile or {};
	local details = {
		tostring(name),
		tostring(profile.className or "?"),
		tostring(profile.specName or "?"),
		"lvl "..tostring(profile.level or "?"),
		"GS "..tostring(profile.gearScore or "?"),
		tostring(profile.raceLocalized or profile.raceFile or "?"),
		"summons "..tostring(profile.summonCount or 0),
		"junk "..(
			profile.junkSoldAt
			and UnBotRegistryFlagTimeText(profile.junkSoldAt)
			or "never"
		),
	};
	local flag = UnBotRegistryGetActiveFlag(profile);
	if (flag) then
		table.insert(
			details,
			"ИСКЛЮЧЁН до "..(flag.untilExit and "выхода из подземелья" or UnBotRegistryFlagTimeText(flag.untilTime)).." ("..flag.reason..")"
		);
	end
	return table.concat(details, " | ");
end

local function UnBotBotScannerPrintRegistry()
	local names = {};
	for name in pairs(UnBotBotRegistry.bots or {}) do
		if (not UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots[name])) then
			table.insert(names, name);
		end
	end
	table.sort(names, function(a, b)
		local pa = UnBotBotRegistry.bots[a] or {};
		local pb = UnBotBotRegistry.bots[b] or {};
		local ca = tostring(pa.className or "zz");
		local cb = tostring(pb.className or "zz");
		if (ca == cb) then
			return string.lower(a) < string.lower(b);
		end
		return ca < cb;
	end);

	UnBotSpecSummonMessage("Bot registry: "..tostring(#names).." profiles.");
	for i = 1, #names, 1 do
		local name = names[i];
		UnBotSpecSummonMessage(tostring(i)..". "..UnBotBotScannerProfileText(name, UnBotBotRegistry.bots[name]));
	end
end

UnBotBotScannerPrintSummary = function()
	local parts = {};
	for i = 1, #UnBotBotScanner.classes, 1 do
		local className = UnBotBotScanner.classes[i];
		table.insert(parts, className.." "..tostring(UnBotBotScannerProfileCount(className)));
	end
	UnBotSpecSummonMessage(
		"Bot registry: "..tostring(UnBotBotScannerProfileCount()).." total | "..table.concat(parts, ", ")
	);
end

local function UnBotBotScannerFinish()
	local scopedClass = UnBotBotScanner.scopeClass;
	local pendingBalanceClass = UnBotBotScanner.pendingSpecBalanceClass;
	local pendingBalanceReady = (
		pendingBalanceClass
		and not UnBotBotScanner.stopRequested
		and not UnBotBotScanner.failedClasses[pendingBalanceClass]
	);
	UnBotBotScanner.active = false;
	UnBotBotScanner.stage = nil;
	UnBotBotScanner.currentName = nil;
	UnBotBotRegistry.meta.scanInProgress = false;
	if (scopedClass) then
		UnBotBotRegistry.meta.lastClassScanFinished = time();
		UnBotBotRegistry.meta.lastClassScanName = scopedClass;
		UnBotBotRegistry.meta.lastClassScanNew = UnBotBotScanner.newThisRun;
		UnBotBotRegistry.meta.lastClassScanProfiles = UnBotBotScannerProfileCount(scopedClass);
		UnBotBotRegistry.meta.lastClassScanFailedClasses = {};
	else
		UnBotBotRegistry.meta.lastScanFinished = time();
		UnBotBotRegistry.meta.lastScanNew = UnBotBotScanner.newThisRun;
		UnBotBotRegistry.meta.lastScanProfiles = UnBotBotScannerProfileCount();
		UnBotBotRegistry.meta.lastScanCompletedClasses = UnBotBotScannerFinalizedCount();
		UnBotBotRegistry.meta.lastScanFailedClasses = {};
	end
	for className in pairs(UnBotBotScanner.failedClasses or {}) do
		table.insert(
			scopedClass and UnBotBotRegistry.meta.lastClassScanFailedClasses or UnBotBotRegistry.meta.lastScanFailedClasses,
			className
		);
	end
	table.sort(scopedClass and UnBotBotRegistry.meta.lastClassScanFailedClasses or UnBotBotRegistry.meta.lastScanFailedClasses);
	local finishTime = GetTime();
	UnBotBotScanner.autoReloadPending = not UnBotBotScanner.stopRequested;
	if (UnBotBotScanner.autoReloadPending) then
		UnBotBotScanner.autoReloadNotBefore = finishTime + (UnBotBotScanner.fastDiscovery and 0 or 60);
		UnBotBotScanner.autoReloadQuietUntil = finishTime + (UnBotBotScanner.fastDiscovery and 0 or 10);
		UnBotBotScanner.autoReloadDeadline = finishTime + 180;
	else
		UnBotBotScanner.autoReloadNotBefore = 0;
		UnBotBotScanner.autoReloadQuietUntil = 0;
		UnBotBotScanner.autoReloadDeadline = 0;
	end
	UnBotBotScanner.lateCleanupNames = {};
	UnBotBotScanner.lateCleanupUntil = finishTime + 60;
	UnBotBotScannerQueueLateCleanup(false);
	UnBotSpecSummonMessage(
		(UnBotBotScanner.stopText or "Bot scan finished.")
		.." New: "..tostring(UnBotBotScanner.newThisRun)
		..", registry: "..tostring(UnBotBotScannerProfileCount())
		..", elapsed: "..UnBotBotScannerFormatDuration(GetTime() - (UnBotBotScanner.runStartedAt or GetTime())).."."
	);
	local failedClassList = scopedClass and UnBotBotRegistry.meta.lastClassScanFailedClasses or UnBotBotRegistry.meta.lastScanFailedClasses;
	if (#failedClassList > 0) then
		UnBotSpecSummonMessage(
			"Bot scan unavailable or skipped classes: "..table.concat(failedClassList, ", ").."."
		);
	end
	if (pendingBalanceReady) then
		-- A class rebuild explicitly started by the user may continue in this
		-- session, but it must never create work that resumes at a later login.
		UnBotBotScanner.autoReloadPending = false;
		UnBotBotScanner.autoReloadNotBefore = 0;
		UnBotBotScanner.autoReloadQuietUntil = 0;
		UnBotBotScanner.autoReloadDeadline = 0;
		UnBotBotScanner.pendingSpecBalanceNotBefore = finishTime + 3;
		UnBotBotScanner.pendingSpecBalanceDeadline = finishTime + 180;
		UnBotBotScanner.pendingSpecBalanceResumeReady = true;
		UnBotClassSpecRebuildCheckpointClear();
		UnBotSpecSummonMessage(
			"Скан класса "..tostring(pendingBalanceClass)
			.." завершён; после очистки временного состава продолжу явно запущенную пересборку в текущей сессии. "
			.."После ReloadUI или нового входа она автоматически не возобновляется."
		);
	elseif (UnBotBotScanner.autoReloadPending) then
		UnBotBotScanner.pendingSpecBalanceClass = nil;
		UnBotBotScanner.pendingSpecBalanceNotBefore = 0;
		UnBotBotScanner.pendingSpecBalanceDeadline = 0;
		UnBotBotScanner.pendingSpecBalanceResumeReady = false;
		UnBotClassSpecRebuildCheckpointClear();
		local remaining=UnBotBotScanner.fastDiscovery and {} or UnBotSpecCountBalanceBuildAuditQueue(scopedClass,UnBotBotScanner.talentsReadThisRun);
		if (#remaining>0) then
			UnBotBotScanner.autoReloadPending=false;
			UnBotBotScanner.pendingTalentAudit={className=scopedClass,skipNames=UnBotBotScanner.talentsReadThisRun,notBefore=finishTime+60,deadline=finishTime+180};
			UnBotSpecSummonMessage("Скан: таланты прочитаны прямо в проходе у "..tostring(UnBotBotScanner.talentSuccess).." ботов; доберу "..#remaining.." не встреченных или не ответивших ботов реестра.");
		else UnBotSpecSummonMessage(UnBotBotScanner.namesOnly and "Сбор имён и классов завершён. После очистки сохраню через /reload." or UnBotBotScanner.fastDiscovery and "Быстрый поиск завершён: класс/спек обновлены по who; полный осмотр талантов запускается отдельно. После очистки сохраню через /reload." or "Скан: полные таланты реестра прочитаны прямо в проходе. После очистки сохраню через /reload."); end
	else
		UnBotBotScanner.pendingSpecBalanceClass = nil;
		UnBotBotScanner.pendingSpecBalanceNotBefore = 0;
		UnBotBotScanner.pendingSpecBalanceDeadline = 0;
		UnBotBotScanner.pendingSpecBalanceResumeReady = false;
		UnBotClassSpecRebuildCheckpointClear();
		UnBotSpecSummonMessage("Bot scan stopped manually; automatic ReloadUI cancelled.");
	end
	UnBotBotScannerPrintSummary();
end

local function UnBotBotScannerAfterCleanup()
	local classBatchCount = UnBotBotScanner.batchCount or 0;
	UnBotBotScanner.batchNames = {};
	UnBotBotScanner.batchOrder = {};
	UnBotBotScanner.batchCount = 0;
	UnBotBotScanner.currentName = nil;
	UnBotBotScanner.cleanupIndex = 1;
	UnBotBotScanner.cleanupUntil = 0;

	if (UnBotBotScanner.stopRequested) then
		UnBotBotScannerFinish();
		return;
	end

	-- The selected-class discovery button performs exactly one batch, including an empty pool.
	if (UnBotBotScanner.endedByFullRaid and not (UnBotBotScanner.fastDiscovery and (UnBotBotScanner.scopeClass or UnBotBotScanner.classRefresh))) then
		if (UnBotBotScanner.newThisRound == 0) then
			UnBotBotScanner.emptyFullRounds = UnBotBotScanner.emptyFullRounds + 1;
		else
			UnBotBotScanner.emptyFullRounds = 0;
		end
		if (
			UnBotBotScanner.emptyFullRounds < UnBotBotScanner.requiredEmptyFullRounds
			and UnBotBotScanner.round < UnBotBotScanner.maxRounds
		) then
			UnBotBotScanner.round = UnBotBotScanner.round + 1;
			UnBotBotScanner.stage = "start_round";
			UnBotBotScanner.nextTime = GetTime() + 1;
			UnBotSpecSummonMessage(
				"Bot scan pass complete: "..UnBotBotScanner.className
				.." found +"..tostring(UnBotBotScanner.newThisRound).." new; zero-new confirmations "
				..tostring(UnBotBotScanner.emptyFullRounds).."/"
				..tostring(UnBotBotScanner.requiredEmptyFullRounds)..". Next raid pass "
				..tostring(UnBotBotScanner.round).."/"..tostring(UnBotBotScanner.classRefresh and 1 or UnBotBotScanner.maxRounds).."."
			);
			return;
		end
		if (UnBotBotScanner.round >= UnBotBotScanner.maxRounds and UnBotBotScanner.newThisRound > 0) then
			UnBotSpecSummonMessage(
				"Bot scan warning: "..UnBotBotScanner.className.." reached the safety limit of "
				..tostring(UnBotBotScanner.classRefresh and 1 or UnBotBotScanner.maxRounds).." full raid passes."
			);
		end
	end

	local className = UnBotBotScanner.className;
	local classStatus = UnBotBotRegistry.meta.classStatus[className] or {};
	UnBotBotRegistry.meta.classStatus[className] = classStatus;
	local classSucceeded = UnBotBotScanner.endedByFullRaid or classBatchCount > 0;
	local classFailureReason = UnBotBotScanner.failedClasses[className];
	if (classFailureReason == "level-too-low") then
		classStatus.completed = classStatus.completed or false;
		classStatus.lastResult = "level-too-low";
		classStatus.lastFailed = time();
		classStatus.lastCount = UnBotBotScannerProfileCount(className);
		UnBotBotScanner.finalizedClasses[className] = true;
		UnBotSpecSummonMessage(
			"Bot scan class skipped: "..tostring(className)
			.." | player level is too low; no retries this run | "
			..UnBotBotScannerProgressText().."."
		);
	elseif (classSucceeded) then
		classStatus.completed = true;
		classStatus.lastResult = (UnBotBotScanner.fastDiscovery and (UnBotBotScanner.scopeClass or UnBotBotScanner.classRefresh)) and "single-pass"
			or (UnBotBotScanner.endedByFullRaid and "converged" or "exhausted");
		if (
			UnBotBotScanner.endedByFullRaid
			and not (UnBotBotScanner.fastDiscovery and (UnBotBotScanner.scopeClass or UnBotBotScanner.classRefresh))
			and UnBotBotScanner.round >= UnBotBotScanner.maxRounds
			and UnBotBotScanner.newThisRound > 0
		) then
			classStatus.lastResult = "safety-limit";
		end
		classStatus.lastFinished = time();
		classStatus.lastCount = UnBotBotScannerProfileCount(className);
		UnBotBotScanner.finalizedClasses[className] = true;
		UnBotBotScanner.failedClasses[className] = nil;
		UnBotSpecSummonMessage(
			"Bot scan class complete: "..tostring(className)
			.." | profiles "..tostring(classStatus.lastCount)
			.." | "..UnBotBotScannerProgressText().."."
		);
	else
		classStatus.lastResult = "unavailable";
		classStatus.lastFailed = time();
		classStatus.lastCount = UnBotBotScannerProfileCount(className);
		local deferred = (UnBotBotScanner.deferredAttempts[className] or 0) + 1;
		UnBotBotScanner.deferredAttempts[className] = deferred;
		if (deferred <= UnBotBotScanner.maxDeferredRetries and not (UnBotBotScanner.fastDiscovery and (UnBotBotScanner.scopeClass or UnBotBotScanner.classRefresh))) then
			table.insert(UnBotBotScanner.classQueue, className);
			UnBotSpecSummonMessage(
				"Bot scan deferred "..tostring(className)..": server returned no bot. "
				.."Will retry later ("..tostring(deferred).."/"..tostring(UnBotBotScanner.maxDeferredRetries)..") | "
				..UnBotBotScannerProgressText().."."
			);
		else
			classStatus.completed = classStatus.completed or false;
			UnBotBotScanner.finalizedClasses[className] = true;
			UnBotBotScanner.failedClasses[className] = true;
			UnBotSpecSummonMessage(
				"Bot scan class unavailable: "..tostring(className)
				..((UnBotBotScanner.fastDiscovery and (UnBotBotScanner.scopeClass or UnBotBotScanner.classRefresh)) and " after one pass | " or " after deferred retries | ")
				..UnBotBotScannerProgressText().."."
			);
		end
	end

	UnBotBotScanner.classIndex = UnBotBotScanner.classIndex + 1;
	if (UnBotBotScanner.classIndex > #UnBotBotScanner.classQueue) then
		if (next(UnBotBotScanner.failedClasses)) then
			UnBotBotScanner.stopText = "Bot scan finished with unavailable classes.";
		elseif (UnBotBotScanner.scopeClass) then
			UnBotBotScanner.stopText = "Bot scan completed selected class.";
		else
			UnBotBotScanner.stopText = "Bot scan completed all classes.";
		end
		UnBotBotScannerFinish();
		return;
	end

	UnBotBotScanner.className = UnBotBotScanner.classQueue[UnBotBotScanner.classIndex];
	UnBotBotScanner.round = 1;
	UnBotBotScanner.emptyFullRounds = 0;
	UnBotBotScanner.stage = "start_round";
	UnBotBotScanner.nextTime = GetTime() + 1;
end

local function UnBotBotScannerStartCleanup()
	if UnBotBotScanner.fastDiscovery then UnBotBotScanner.FastCleanup(); return; end
	UnBotBotScanner.RememberCleanupMembers();
	if (UnBotTalentInfo) then UnBotTalentInfo.Cancel(UnBotBotScanner); end
	if (UnitAffectingCombat("player") or InCombatLockdown()) then
		UnBotBotScanner.stopRequested=true;
		UnBotBotScanner.stage="wait_scan_combat";
		UnBotBotScanner.combatCleanupDeadline=GetTime()+180;
		UnBotBotScanner.nextTime=GetTime()+1;
		UnBotSpecSummonMessage("Скан остановлен боем; временный рейд будет очищен после боя.");
		return;
	end
	UnBotBotScanner.stage = "cleanup";
	UnBotBotScanner.currentName = nil;
	UnBotBotScanner.cleanupIndex = 1;
	UnBotBotScanner.cleanupUntil = GetTime() + 20;
	UnBotBotScanner.nextTime = GetTime() + 0.25;
end

local function UnBotBotScannerBeginAdd()
	if (GetNumPartyMembers() >= 4 and (not GetNumRaidMembers() or GetNumRaidMembers() == 0)) then
		ConvertToRaid();
	end
	UnBotBotScanner.knownMembers = UnBotSpecSummonGetMembers();
	UnBotBotScanner.currentName = nil;
	UnBotBotScanner.stage = "wait_member";
	UnBotBotScanner.stageUntil = GetTime() + 8;
	UnBotBotScanner.nextTime = GetTime() + 0.25;
	SendChatMessage(".playerbot bot addclass "..UnBotBotScanner.className, "SAY");
end

local function UnBotBotScannerStartRound()
	UnBotBotScanner.batchNames = {};
	UnBotBotScanner.batchOrder = {};
	UnBotBotScanner.batchCount = 0;
	UnBotBotScanner.newThisRound = 0;
	UnBotBotScanner.noJoinAttempts = 0;
	UnBotBotScanner.endedByFullRaid = false;
	local classStatus = UnBotBotRegistry.meta.classStatus[UnBotBotScanner.className] or {};
	UnBotBotRegistry.meta.classStatus[UnBotBotScanner.className] = classStatus;
	classStatus.lastAttemptStarted = time();
	classStatus.lastResult = "scanning";
	UnBotSpecSummonMessage(
		"Bot scan: "..UnBotBotScanner.className.." | raid pass "
		..tostring(UnBotBotScanner.round).."/"..tostring(UnBotBotScanner.classRefresh and 1 or UnBotBotScanner.maxRounds)
		.." | "..UnBotBotScannerProgressText().."."
	);
	if UnBotBotScanner.fastDiscovery then UnBotBotScanner.FastStartRound(); else UnBotBotScannerBeginAdd(); end
end

function UnBotBotScanner.ContinueAfterProfile()
	UnBotBotScanner.currentName,UnBotBotScanner.whoAttempts=nil,0;
	if (UnitAffectingCombat("player") or InCombatLockdown()) then UnBotBotScanner.stopRequested=true; end
	if (UnBotBotScanner.stopRequested) then UnBotBotScannerStartCleanup();
	elseif (UnBotBotScannerFindNewMember()) then
		UnBotBotScanner.stage="collect_member"; UnBotBotScanner.nextTime=GetTime()+.15;
	elseif (UnBotBuffCycleOtherMemberCount()>=39) then
		UnBotBotScanner.endedByFullRaid=true; UnBotBotScannerStartCleanup();
	else UnBotBotScanner.stage="add_next"; UnBotBotScanner.nextTime=GetTime()+.5; end
end

function UnBotBotScanner.ReadCurrentTalents()
	local s,name=UnBotBotScanner,UnBotBotScanner.currentName;
	if (s.stopRequested or UnitAffectingCombat("player") or InCombatLockdown()) then s.ContinueAfterProfile(); return; end
	if (not name) then s.ContinueAfterProfile(); return; end
	s.stage="wait_talents";
	UnBotSpecSummonMessage("Скан: читаю полные таланты "..name.." прямо в проходе.");
	UnBotTalentInfo.Begin(name,s,function(snapshot)
		s.talentsAttemptedThisRun[name]=true;
		s.talentAttempts=(s.talentAttempts or 0)+1;
		if (snapshot) then
			s.talentsReadThisRun[name]=true; s.talentSuccess=(s.talentSuccess or 0)+1;
		else s.talentFailed=(s.talentFailed or 0)+1; end
		s.ContinueAfterProfile();
		if (UnBotSpecAuditRefresh) then UnBotSpecAuditRefresh(); end
	end,function() return s.active and not s.stopRequested and s.currentName==name and s.stage=="wait_talents"; end);
end

local function UnBotBotScannerAcceptNewMember()
	local name = UnBotBotScannerFindNewMember();
	if (not name) then
		return false;
	end

	UnBotBotScanner.batchNames[name] = true;
	UnBotBotScanner.cleanupOwnedNames = UnBotBotScanner.cleanupOwnedNames or {};
	UnBotBotScanner.cleanupOwnedNames[name] = true;
	table.insert(UnBotBotScanner.batchOrder, name);
	UnBotBotScanner.batchCount = UnBotBotScanner.batchCount + 1;
	UnBotBotScanner.noJoinAttempts = 0;
	UnBotBotScanner.currentName = name;
	UnBotBotScanner.whoAttempts = 1;
	local profileComplete = UnBotBotScanner.talentsAttemptedThisRun[name];
	UnBotBotScannerStoreProfile(name, nil, nil);
	UnBotBotScanner.knownMembers = UnBotSpecSummonGetMembers();
	if (profileComplete) then
		UnBotBotScanner.currentName = nil;
		UnBotBotScanner.whoAttempts = 0;
		if (
			UnBotBotScanner.batchCount == 1
			or UnBotBotScanner.batchCount % 10 == 0
			or UnBotBotScanner.batchCount >= 39
		) then
			UnBotSpecSummonMessage(
				"Bot scan known: "..tostring(UnBotBotScanner.className).." "
				..tostring(UnBotBotScanner.batchCount).."/39 | "..UnBotBotScannerProgressText().."."
			);
		end
		UnBotBotScanner.ContinueAfterProfile();
		return true;
	end
	UnBotBotScanner.stage = "wait_who";
	UnBotBotScanner.stageUntil = GetTime() + 10;
	UnBotBotScanner.nextTime = GetTime() + 0.25;
	SendChatMessage("who", "WHISPER", nil, name);
	return true;
end

local function UnBotBotScannerStart(classFilter, balanceAfterScan, minimumCount)
	if (not (UnBotBotScanner and UnBotBotScanner.active) and UnBotFullTalentCatalog and UnBotFullTalentCatalog.IsBusy()) then UnBotSpecSummonMessage("Сначала завершите сбор полного каталога талантов."); return false; end
	if not (UnBotBotScanner and UnBotBotScanner.active) and UnBotStrategySurvey and UnBotStrategySurvey.active then UnBotSpecSummonMessage("Сначала остановите сбор стратегий."); return false; end
	if (UnBotBotScanner.active) then
		UnBotClassSpecRebuildCheckpointClear();
		UnBotBotScanner.pendingSpecBalanceClass = nil;
		UnBotBotScanner.pendingSpecBalanceNotBefore = 0;
		UnBotBotScanner.pendingSpecBalanceDeadline = 0;
		UnBotBotScanner.pendingSpecBalanceResumeReady = false;
		UnBotBotScanner.stopRequested = true;
		UnBotBotScanner.stopText = "Bot scan stopped by user.";
		UnBotSpecSummonMessage("Bot scan stopping; removing summoned bots.");
		UnBotBotScannerStartCleanup();
		return;
	end
	if (balanceAfterScan and not UnBotSpecSummonPlayerSupportsSpecs()) then
		UnBotClassSpecRebuildCheckpointClear();
		UnBotSpecSummonMessage("Пересборка специализаций доступна с 11 уровня. Для имён и классов нажмите «Найти новых ботов».");
		return;
	end
	classFilter = UnBotSpecSummonNormalize(classFilter);
	classFilter = UnBotSpecSummonClassAliases[classFilter] or classFilter;
	if (classFilter ~= "") then
		local supportedClass = false;
		for _, className in ipairs(UnBotBotScanner.classes or {}) do
			if (className == classFilter) then
				supportedClass = true;
				break
			end
		end
		if (not supportedClass) then
			UnBotSpecSummonMessage("Неизвестный класс для сканирования: "..tostring(classFilter)..".");
			return;
		end
	end
	if (UnBotBuffCycle.active or UnBotSoulstoneTest.active or UnBotSpecSummon.active or UnBotJunkCleaner.active or (UnBotFastJunkRaid and UnBotFastJunkRaid.active)) then
		UnBotSpecSummonMessage("Stop other UnBot automation before starting the bot scan.");
		return;
	end
	if (UnBotDKSpecBalance and UnBotDKSpecBalance.active) then
		UnBotSpecSummonMessage("Сначала остановите выравнивание спеков по количеству.");
		return;
	end
	if (UnBotBuffCycleOtherMemberCount() > 0) then
		UnBotSpecSummonMessage("Bot scan requires an empty group.");
		return;
	end

	UnBotRegistryAttachStorage();
	UnBotBotScanner.active = true;
	UnBotBotScanner.namesOnly = not UnBotSpecSummonPlayerSupportsSpecs();
	UnBotBotScanner.classRefresh = UnBotBotScanner.classRefreshRequested and not balanceAfterScan or false;
	UnBotBotScanner.fastDiscovery = (UnBotBotScanner.fastDiscoveryRequested or UnBotBotScanner.namesOnly or UnBotBotScanner.classRefresh) and not balanceAfterScan or false;
	UnBotBotScanner.fastBatchSize = UnBotBotScanner.classRefresh and 39 or 35;
	UnBotBotScanner.fastBatch = nil;
	UnBotBotScanner.batchCount,UnBotBotScanner.newThisRound=0,0;
	UnBotBotScanner.cleanupOwnedNames = {};
	UnBotBotScanner.autoReloadPending = false;
	UnBotBotScanner.autoReloadNotBefore = 0;
	UnBotBotScanner.autoReloadQuietUntil = 0;
	UnBotBotScanner.autoReloadDeadline = 0;
	UnBotBotScanner.lateCleanupUntil = 0;
	UnBotBotScanner.lateCleanupNames = {};
	UnBotBotScanner.stopRequested = false;
	UnBotBotScanner.stopText = nil;
	UnBotBotScanner.scopeClass = classFilter ~= "" and classFilter or nil;
	UnBotBotScanner.pendingSpecBalanceClass = balanceAfterScan and classFilter ~= "" and classFilter or nil;
	UnBotBotScanner.pendingSpecBalanceMinimum = math.max(1, math.min(12, tonumber(minimumCount) or 8));
	UnBotBotScanner.pendingSpecBalanceNotBefore = 0;
	UnBotBotScanner.pendingSpecBalanceDeadline = 0;
	UnBotBotScanner.pendingSpecBalanceResumeReady = false;
	UnBotBotScanner.classQueue = classFilter ~= "" and {classFilter} or UnBotBotScannerBuildClassQueue();
	UnBotBotScanner.classIndex = 1;
	UnBotBotScanner.className = UnBotBotScanner.classQueue[1];
	UnBotBotScanner.round = 1;
	UnBotBotScanner.emptyFullRounds = 0;
	UnBotBotScanner.newThisRun = 0;
	UnBotBotScanner.scannedThisRun = {};
	UnBotBotScanner.talentsAttemptedThisRun = {};
	UnBotBotScanner.talentsReadThisRun = {};
	UnBotBotScanner.talentAttempts,UnBotBotScanner.talentSuccess,UnBotBotScanner.talentFailed=0,0,0;
	UnBotBotScanner.finalizedClasses = {};
	UnBotBotScanner.failedClasses = {};
	UnBotBotScanner.deferredAttempts = {};
	UnBotBotScanner.runStartedAt = GetTime();
	UnBotBotScanner.runStartedServerTime = time();
	UnBotBotScanner.nextProgressMessage = GetTime() + 30;
	UnBotBotScanner.scanId = tostring(time()).."-"..tostring(UnitName("player") or "player");
	UnBotBotRegistry.meta.scanInProgress = true;
	if (classFilter ~= "") then
		UnBotBotRegistry.meta.lastClassScanStarted = time();
		UnBotBotRegistry.meta.lastClassScanName = classFilter;
	else
		UnBotBotRegistry.meta.lastScanStarted = time();
	end
	if (UnBotBotScanner.pendingSpecBalanceClass) then
		UnBotClassSpecRebuildCheckpointSet(
			UnBotBotScanner.pendingSpecBalanceClass,
			UnBotBotScanner.pendingSpecBalanceMinimum,
			"scan"
		);
	else
		UnBotClassSpecRebuildCheckpointClear();
	end
	UnBotSpecSummonMessage(
		classFilter ~= ""
		and ("Скан выбранного класса запущен: "..classFilter
			..(UnBotBotScanner.fastDiscovery and "; один проход, до 35 запросов, затем сохранение и /ubnames."
			or "; собираю полные рейдовые проходы до трёх проходов без новых имён."))
		or ("Bot scan started. Priority order: "..table.concat(UnBotBotScanner.classQueue, ", ")..".")
	);
	if UnBotBotScanner.namesOnly then
		UnBotSpecSummonMessage("Сбор реестра: только имена и классы; доступен с 1 уровня, без проверки специализаций, талантов и init.");
	end
	if UnBotBotScanner.classRefresh then
		UnBotSpecSummonMessage("Обновление списка: один проход каждого класса, до 39 ботов; повторных проходов нет.");
	end
	UnBotBotScannerStorageStatus(true);
	UnBotSpecSummonMessage("Bot scan progress: "..UnBotBotScannerProgressText()..".");
	UnBotBotScannerStartRound();
end

function UnBotBotScannerUIStart()
	if (UnBotBotScanner.active) then UnBotBotScannerStart(); return; end
	if (UnBotBotScanner.pendingTalentAudit or UnBotBotScanner.talentAuditRunning) then UnBotClassSpecRebuildStop(); return; end
	if UnBotRegistryRefresh and UnBotRegistryRefresh.Running() then UnBotRegistryRefresh.Stop(); return; end
	UnBotBotScanner.classRefreshRequested = true;
	UnBotBotScannerStart();
	UnBotBotScanner.classRefreshRequested = nil;
end

function UnBotBotScannerDiscover(classFilter)
	UnBotBotScanner.fastDiscoveryRequested = not UnBotBotScanner.active;
	UnBotBotScannerStart(classFilter);
	UnBotBotScanner.fastDiscoveryRequested = nil;
end

-- Fast discovery owns only an initially empty temporary group. Deep audits stay separate.
function UnBotBotScanner.FastAbort(reason)
 local s=UnBotBotScanner;s.active=false;s.stopRequested=true;s.stage=nil;s.autoReloadPending=false;
 s.lateCleanupUntil=0;s.fastBatch=nil;UnBotBotRegistry.meta.scanInProgress=false;
 UnBotSpecSummonMessage("Быстрый поиск остановлен: "..reason..". Состав сохранён; для записи реестра /reload.");
end
function UnBotBotScanner.FastStoreClass(name,e)
 local s=UnBotBotScanner;local b=s.fastBatch;
 if s.namesOnly and b and e.owned and not e.classStored then
  UnBotBotScannerStoreProfile(name,nil,nil);
  UnBotBotRegistry.bots[name].classCheckedAt=time();
  e.classStored=true;b.classCount=(b.classCount or 0)+1;
  if UnBotSpecAuditRefresh then UnBotSpecAuditRefresh(true);end
 end
end
function UnBotBotScanner.FastObserve()
 local s=UnBotBotScanner;local b=s.fastBatch;if not b then return false;end
 for name in pairs(UnBotSpecSummonGetMembers()) do
  if name~=UnitName("player") then
   local unit=UnBotBotScannerFindUnit(name);local e=b.entries[name];
   if not UnBotIsValidBotName(name) or not unit or not UnitGUID(unit) then return false;end
   if UnBotIsAccountAltProfile(name,UnBotBotRegistry.bots[name]) or UnBotSquadRosterIsOfflineReserve(name)
    or UnBotSpecSummon.CleanupProtected(name) or (e and e.guid~=UnitGUID(unit)) then
    s.FastAbort("чужой, защищённый участник или смена GUID");return false;
   end
   if not UnitIsConnected(unit) and not (b.phase=="cleanup" and b.leaveSent and e and e.owned) then
    s.FastAbort("участник ушёл офлайн");return false;
   end
   if not e then
    local _,file=UnitClass(unit);
    if UnBotBotScannerClassFiles[file]~=s.className then s.FastAbort("вошёл участник другого класса");return false;end
    e={guid=UnitGUID(unit)};b.entries[name]=e;s.batchNames[name]=true;
    s.batchOrder[#s.batchOrder+1]=name;s.batchCount=s.batchCount+1;
    if s.batchCount>(s.fastBatchSize or 35) then s.FastAbort("в составе больше участников, чем отправленных запросов");return false;end
   end
   if b.acks[UnBotSpecSummonNormalize(name)] then e.owned=true end
   if e.owned then
    s.cleanupOwnedNames[name]=true;
    s.FastStoreClass(name,e);
   end
  end
 end
 return true;
end
function UnBotBotScanner.FastStartRound()
 local s=UnBotBotScanner;
 if UnBotBuffCycleOtherMemberCount()>0 then s.FastAbort("перед новой пачкой группа не пуста");return;end
 s.fastBatch={phase="add",sent=0,entries={},acks={},context=UnBotRegistryCurrentContext(),whoCount=0,nextAt=GetTime()};
 s.stage="fast_discovery";s.nextTime=GetTime();
end
function UnBotBotScanner.FastCleanup()
 local s=UnBotBotScanner;local b=s.fastBatch;if not b then s.FastAbort("потеряно состояние пачки");return;end
 if s.stopRequested and b.lastSent and GetTime()<b.lastSent+6 then
  b.phase="join";b.joinUntil=b.lastSent+6;return;
 end
 if not s.FastObserve() then return;end
 for name in pairs(UnBotSpecSummonGetMembers()) do
  if name~=UnitName("player") and not (b.entries[name] and b.entries[name].owned) then
   s.FastAbort("не подтверждена принадлежность "..tostring(name).." к пачке");return;
  end
 end
 if b.phase~="cleanup" then
  b.phase="cleanup";b.cleanupUntil=GetTime()+8;b.emptySince=nil;b.leaveSent=true;
  UnBotSpecSummonMessage("Поиск "..s.className..": запросов "..b.sent.."/"..(s.fastBatchSize or 35)..", вошли "..s.batchCount..(s.namesOnly and (", классов "..tostring(b.classCount or 0)) or (", who "..b.whoCount))..", новых +"..s.newThisRound.."; выхожу из временной группы.");
  if UnBotBuffCycleOtherMemberCount()>0 then LeaveParty();end
 end
end
function UnBotBotScanner.FastEvent(event,text,sender)
 local s=UnBotBotScanner;local b=s.active and s.fastDiscovery and s.fastBatch;
 if not b or event=="PLAYER_LOGIN" then return false;end
 if b.context~=UnBotRegistryCurrentContext() then s.FastAbort("изменился сервер или фракция");return true;end
 if event=="CHAT_MSG_SYSTEM" then
  local name,result=UnBotSpecSummonNormalize(text):match("^add:%s*(%S+)%s*%-%s*(.-)%s*$");
  if name and result=="ok" then b.acks[name]=true;end
  local english=tostring(text or ""):lower();
  if english:find("level is too low",1,true) then
   s.failedClasses[s.className]="level-too-low";b.phase="join";b.joinUntil=(b.lastSent or GetTime())+6;
  elseif english:find("too many",1,true) or english:find("not allowed",1,true) then
   s.stopRequested=true;s.stopText="Поиск остановлен: сервер отказал в новых запросах.";
   b.phase="join";b.joinUntil=(b.lastSent or GetTime())+6;
  end
 elseif event=="CHAT_MSG_WHISPER" and b.phase=="who" then
  local name=tostring(sender or ""):gsub("%-.*$","");local e=b.entries[name];local unit=e and UnBotBotScannerFindUnit(name);
  local info=e and not e.who and UnBotSpecSummonParseWho(text);
  if info and info.className and (s.namesOnly or info.specName) and unit and UnitIsConnected(unit) and e.guid==UnitGUID(unit) then
   if info.className~=s.className then s.FastAbort("who показал другой класс у "..name);return true;end
   if s.namesOnly and info.text:match("playing with%s+([^%s,;]+)")~=UnBotSpecSummonNormalize(UnitName("player")) then return true;end
   e.who=true;e.owned=true;s.cleanupOwnedNames[name]=true;b.whoCount=b.whoCount+1;
   if s.namesOnly then s.FastStoreClass(name,e);
   else
    UnBotBotScannerStoreProfile(name,info,text);
    local p=UnBotBotRegistry.bots[name];p.specCheckedAt=time();p.registryCheckKind="who";
    if UnBotTalentInfo and UnBotTalentInfo.ObserveWho then UnBotTalentInfo.ObserveWho(p,info);end
   end
   if UnBotSpecAuditRefresh then UnBotSpecAuditRefresh(true);end
  end
 end
 return true;
end
function UnBotBotScanner.FastTick(now)
 local s=UnBotBotScanner;local b=s.fastBatch;
 if s.stage=="start_round" then if now>=(s.nextTime or 0) then UnBotBotScannerStartRound();end;return;end
 if not b then s.FastAbort("нет текущей пачки");return;end
 if b.context~=UnBotRegistryCurrentContext() or not UnitIsConnected("player") then s.FastAbort("контекст или соединение изменились");return;end
 if s.OtherOwnerActive() then s.FastAbort("началась другая операция");return;end
 if UnitAffectingCombat("player") or InCombatLockdown() then
  s.stopRequested=true;s.stopText="Поиск остановлен боем.";b.combatUntil=b.combatUntil or now+180;
  if now>=b.combatUntil then s.FastAbort("бой не завершился за180с");end;return;
 end
 if not s.FastObserve() then
  b.unresolvedUntil=b.unresolvedUntil or now+6;
  if s.active and now>=b.unresolvedUntil then s.FastAbort("имена ростера не разрешились за6с");end;return;
 end
 b.unresolvedUntil=nil;
 if s.stopRequested and b.phase=="add" then b.phase="join";b.joinUntil=(b.lastSent or now)+6;end
 if b.phase=="add" then
  if now<(b.nextAt or 0) then return;end
  if GetNumPartyMembers()>=4 and GetNumRaidMembers()==0 then ConvertToRaid();end
  if b.sent>=(s.fastBatchSize or 35) or UnBotBuffCycleOtherMemberCount()>=(s.fastBatchSize or 35) then b.phase="join";b.joinUntil=(b.lastSent or now)+6;return;end
  SendChatMessage(".playerbot bot addclass "..s.className,"SAY");b.sent=b.sent+1;b.lastSent=now;b.nextAt=now+.1;
 elseif b.phase=="join" then
  if now<(b.joinUntil or now) and s.batchCount<b.sent then return;end
  if s.stopRequested and now<(b.joinUntil or now) then return;end
  if s.stopRequested or s.batchCount==0 or s.failedClasses[s.className]=="level-too-low" then
   s.endedByFullRaid=false;s.FastCleanup();return;
  end
  if s.namesOnly and (b.classCount or 0)>=s.batchCount then s.endedByFullRaid=s.batchCount>0;s.FastCleanup();return;end
  if s.namesOnly then UnBotSpecSummonMessage("Подтверждаю имена и классы одним общим who; специализации не проверяются.");end
  b.phase="who";b.whoUntil=now+3;
  SendChatMessage("who",GetNumRaidMembers()>0 and "RAID" or "PARTY");
 elseif b.phase=="who" then
  if (s.namesOnly and (b.classCount or 0)>=s.batchCount) or b.whoCount>=s.batchCount or now>=b.whoUntil then
   s.endedByFullRaid=s.batchCount>0;
   if b.whoCount==0 then s.stopRequested=true;s.stopText="Поиск остановлен: на общий who никто не ответил.";end
   s.FastCleanup();
  end
 elseif b.phase=="cleanup" then
  if UnBotBuffCycleOtherMemberCount()==0 then
   b.emptySince=b.emptySince or now;
   if now-b.emptySince>=1 then s.fastBatch=nil;UnBotBotScannerAfterCleanup();end
  else b.emptySince=nil;if now>=b.cleanupUntil then s.FastAbort("выход из группы не подтвердился; повтор не отправлен");end end
 end
end


function UnBotBotScannerStartClassBalance(classFilter, minimumCount, talentMode)
	UnBotBotScanner.requestedTalentMode=talentMode;
	UnBotBotScannerStart(classFilter, true, minimumCount);
end

function UnBotClassSpecRebuildStop()
	if (UnBotBotScanner and UnBotBotScanner.pendingTalentAudit) then
		UnBotBotScanner.pendingTalentAudit=nil;
		UnBotSpecSummonMessage("Очередь полного осмотра отменена. Для сохранения реестра выполните /reload.");
		return;
	end
	if (UnBotBotScanner and UnBotBotScanner.pendingSpecBalanceClass) then
		UnBotClassSpecRebuildCheckpointClear();
		UnBotBotScanner.pendingSpecBalanceClass = nil;
		UnBotBotScanner.pendingSpecBalanceNotBefore = 0;
		UnBotBotScanner.pendingSpecBalanceDeadline = 0;
		UnBotBotScanner.pendingSpecBalanceResumeReady = false;
		if (UnBotBotScanner.active) then
			UnBotBotScanner.stopRequested = true;
			UnBotBotScanner.stopText = "Скан выбранного класса остановлен пользователем.";
			UnBotSpecSummonMessage("Пересборка класса: остановка запрошена; очищаю временный рейд.");
			UnBotBotScannerStartCleanup();
		else
			UnBotBotScanner.lateCleanupUntil = 0;
			UnBotSpecSummonMessage("Ожидание пересборки класса отменено.");
		end
		return;
	end
	UnBotClassSpecRebuildCheckpointClear();
	UnBotSpecAuditStop();
end

function UnBotBotScanner.TickTalentAudit(now)
	local pending=UnBotBotScanner.pendingTalentAudit;
	UnBotBotScannerQueueLateCleanup(false);
	if (now>=pending.deadline) then
		UnBotBotScanner.pendingTalentAudit=nil;
		UnBotSpecSummonMessage("Обновление реестра: очередь осмотра отменена — временная группа не очищена или занят другой цикл. Данные сохраните через /reload.");
	elseif (now>=pending.notBefore and UnBotBuffCycleOtherMemberCount()==0 and not UnitAffectingCombat("player")) then
		UnBotBotScanner.pendingTalentAudit=nil;
		if (UnBotDKSpecBalanceOtherAutomationActive()) then UnBotBotScanner.pendingTalentAudit=pending; return; end
		UnBotBotScanner.talentAuditRunning=true;
		UnBotDKSpecBalance.afterTalentAudit=function(complete)
			UnBotBotScanner.talentAuditRunning=false;
			if (complete) then
				UnBotBotScanner.autoReloadPending=true;
				UnBotBotScanner.autoReloadNotBefore=GetTime()+60;
				UnBotBotScanner.autoReloadQuietUntil=GetTime()+10;
				UnBotBotScanner.autoReloadDeadline=GetTime()+180;
			end
		end;
		if (not UnBotSpecAuditStart(pending.className,false,8,nil,pending.skipNames)) then
			UnBotBotScanner.talentAuditRunning=false; UnBotDKSpecBalance.afterTalentAudit=nil;
		end
	end
end

function UnBotBotScannerUIProgressText()
	if (UnBotBotScanner.pendingTalentAudit) then return "Обновление реестра: подготовка полного осмотра талантов."; end
	if (UnBotBotScanner.talentAuditRunning) then return "Обновление реестра: полные таланты "..tostring((UnBotDKSpecBalance.auditSuccess or 0)+(UnBotDKSpecBalance.auditFailed or 0)).." / "..tostring(UnBotDKSpecBalance.targetCount or 0).."."; end
	if (UnBotBotScanner.active) then
		return "Полный скан: "..UnBotBotScannerProgressText();
	end
	local meta = UnBotBotRegistry and UnBotBotRegistry.meta or {};
	if ((tonumber(meta.lastScanFinished) or 0) > 0) then
		return "Последний полный скан: "..date("%d.%m.%Y %H:%M", meta.lastScanFinished)
			..", профилей "..tostring(meta.lastScanProfiles or 0)
			..", новых +"..tostring(meta.lastScanNew or 0)..".";
	end
	return "Полный скан ещё не завершался.";
end

local botScannerFrame = CreateFrame("Frame", "UnBotBotScannerFrame");
botScannerFrame:RegisterEvent("PARTY_MEMBERS_CHANGED");
botScannerFrame:RegisterEvent("RAID_ROSTER_UPDATE");
botScannerFrame:RegisterEvent("CHAT_MSG_WHISPER");
botScannerFrame:RegisterEvent("CHAT_MSG_SYSTEM");
botScannerFrame:RegisterEvent("PLAYER_LOGIN");
botScannerFrame:SetScript("OnEvent", function(self, event, arg1, arg2)
	if UnBotBotScanner.fastDiscovery and UnBotBotScanner.FastEvent(event,arg1,arg2) then return; end
	if (event == "PLAYER_LOGIN") then
		UnBotRegistryAttachStorage();
		local cancelledCheckpoint = type(UnBotSquadConfig and UnBotSquadConfig.specClassRebuildCheckpoint) == "table";
		UnBotBotScanner.pendingSpecBalanceClass = nil;
		UnBotBotScanner.pendingSpecBalanceNotBefore = 0;
		UnBotBotScanner.pendingSpecBalanceDeadline = 0;
		UnBotBotScanner.pendingSpecBalanceResumeReady = false;
		UnBotBotScanner.autoReloadPending = false;
		UnBotClassSpecRebuildCheckpointClear();
		if (cancelledCheckpoint) then
			UnBotSpecSummonMessage(
				"Отложенная пересборка специализаций отменена при входе. "
				.."Аудит и выравнивание запускаются только явной командой в текущей сессии."
			);
		end
		return;
	end
	if (UnBotBotScanner.active and (event == "PARTY_MEMBERS_CHANGED" or event == "RAID_ROSTER_UPDATE")) then
		UnBotBotScanner.RememberCleanupMembers();
	end
	if (not UnBotBotScanner.active) then
		if (
			(event == "PARTY_MEMBERS_CHANGED" or event == "RAID_ROSTER_UPDATE")
			and GetTime() <= (UnBotBotScanner.lateCleanupUntil or 0)
		) then
			UnBotBotScannerQueueLateCleanup(false);
		end
		return;
	end
	if (event == "CHAT_MSG_SYSTEM") then
		local text = UnBotSpecSummonNormalize(arg1);
		if (
			UnBotBotScanner.stage == "wait_member"
			and (
				string.find(text, "your level is too low to summon", 1, true)
				or string.find(text, "уровень слишком низок для призыва", 1, true)
				or string.find(text, "уровень слишком низок, чтобы призвать", 1, true)
			)
		) then
			UnBotBotScanner.failedClasses[UnBotBotScanner.className] = "level-too-low";
			UnBotBotScanner.endedByFullRaid = false;
			UnBotSpecSummonMessage(
				"Bot scan: "..tostring(UnBotBotScanner.className)
				.." requires a higher player level; skipping this class without retries."
			);
			UnBotBotScannerStartCleanup();
		end
		return;
	end
	if (event == "CHAT_MSG_WHISPER") then
		if (UnBotBotScanner.stage ~= "wait_who" or arg2 ~= UnBotBotScanner.currentName) then
			return;
		end
		local whoInfo = UnBotSpecSummonParseWho(arg1);
		if (not whoInfo) then
			return;
		end
		UnBotBotScannerStoreProfile(arg2, whoInfo, arg1);
		UnBotSpecSummonMessage(
			"Bot scan saved: "..UnBotBotScannerProfileText(arg2, UnBotBotRegistry.bots[arg2])
			.." | "..UnBotBotScannerProgressText().."."
		);
		UnBotBotScanner.ReadCurrentTalents();
	elseif (UnBotBotScanner.stage == "wait_member") then
		UnBotBotScannerAcceptNewMember();
	end
end);

botScannerFrame:SetScript("OnUpdate", function()
	local now = GetTime();
	if UnBotBotScanner.active and UnBotBotScanner.fastDiscovery then UnBotBotScanner.FastTick(now); return; end
	if (not UnBotBotScanner.active) then
		if (UnBotBotScanner.pendingTalentAudit) then
			UnBotBotScanner.TickTalentAudit(now);
			return;
		end
		if (UnBotBotScanner.pendingSpecBalanceClass and UnBotBotScanner.pendingSpecBalanceResumeReady) then
			local memberCount = UnBotBuffCycleOtherMemberCount();
			if (memberCount > 0 and now <= (UnBotBotScanner.lateCleanupUntil or 0)) then
				UnBotBotScannerQueueLateCleanup(false);
			end
			local cleanupPending = false;
			for name in pairs(UnBotBotScanner.lateCleanupNames or {}) do
				if (
					UnBotSpecSummonIsInGroup(name)
					or (UnBotBuffCycle.cleanup and UnBotBuffCycle.cleanup[name])
				) then
					cleanupPending = true;
					break
				end
			end
			if (
				now >= (UnBotBotScanner.pendingSpecBalanceDeadline or 0)
				and (memberCount > 0 or cleanupPending)
			) then
				UnBotSpecSummonMessage(
					"Пересборка класса остановлена: после скана не удалось полностью очистить временный рейд за 180 секунд."
				);
				UnBotBotScanner.pendingSpecBalanceClass = nil;
				UnBotBotScanner.pendingSpecBalanceNotBefore = 0;
				UnBotBotScanner.pendingSpecBalanceDeadline = 0;
				UnBotBotScanner.pendingSpecBalanceResumeReady = false;
				UnBotClassSpecRebuildCheckpointClear();
			elseif (
				now >= (UnBotBotScanner.pendingSpecBalanceNotBefore or 0)
				and memberCount == 0
				and not cleanupPending
				and not UnitAffectingCombat("player")
			) then
				local balanceClass = UnBotBotScanner.pendingSpecBalanceClass;
				local balanceMinimum = UnBotBotScanner.pendingSpecBalanceMinimum or 8;
				UnBotBotScanner.pendingSpecBalanceClass = nil;
				UnBotBotScanner.pendingSpecBalanceNotBefore = 0;
				UnBotBotScanner.pendingSpecBalanceDeadline = 0;
				UnBotBotScanner.pendingSpecBalanceResumeReady = false;
				UnBotBotScanner.lateCleanupUntil = 0;
				UnBotSpecSummonMessage(
					"Скан класса завершён; добираю только не прочитанные таланты класса "
					..tostring(balanceClass).." перед пересборкой."
				);
				UnBotSpecAuditStart(balanceClass, true, balanceMinimum,UnBotBotScanner.requestedTalentMode,UnBotBotScanner.talentsReadThisRun);
				return;
			end
		end
		if (UnBotBotScanner.autoReloadPending) then
			if (UnBotBotScanner.OtherOwnerActive()) then
				UnBotBotScanner.autoReloadPending = false;
				UnBotSpecSummonMessage("Скан: начата другая операция; автоматический /reload отменён. Сохраните реестр вручную после её завершения.");
				return;
			end
			local memberCount = UnBotBuffCycleOtherMemberCount();
			if (memberCount > 0) then
				UnBotBotScannerQueueLateCleanup(false);
			end

			local cleanupPending = false;
			for name in pairs(UnBotBotScanner.lateCleanupNames or {}) do
				if (
					UnBotSpecSummonIsInGroup(name)
					or (UnBotBuffCycle.cleanup and UnBotBuffCycle.cleanup[name])
				) then
					cleanupPending = true;
					break
				end
			end

			local inCombat = InCombatLockdown and InCombatLockdown();
			local deadlineReached = (
				(UnBotBotScanner.autoReloadDeadline or 0) > 0
				and now >= UnBotBotScanner.autoReloadDeadline
			);
			local cleanupReady = (
				memberCount == 0
				and not cleanupPending
				and now >= (UnBotBotScanner.autoReloadQuietUntil or 0)
			);
			if (
				not inCombat
				and now >= (UnBotBotScanner.autoReloadNotBefore or 0)
				and (cleanupReady or deadlineReached)
			) then
				UnBotRegistryAttachStorage();
				UnBotBotRegistry.meta.lastAutoReload = time();
				UnBotBotRegistry.meta.lastAutoReloadProfiles = UnBotBotScannerProfileCount();
				UnBotBotScanner.autoReloadPending = false;
				if (deadlineReached and not cleanupReady) then
					UnBotSpecSummonMessage(
						"Bot scan: cleanup wait limit reached; ReloadUI now saves "
						..tostring(UnBotBotScannerProfileCount()).." registry profiles."
					);
				else
					UnBotSpecSummonMessage(
						"Bot scan cleanup complete; ReloadUI now saves "
						..tostring(UnBotBotScannerProfileCount()).." registry profiles."
					);
				end
				if (UnBotBotScanner.fastDiscovery) then
					UnBotSquadConfig.sharedNamesAfterRegistrySave = {context=UnBotRegistryCurrentContext(), player=UnitName("player"), requestedAt=time()};
				end
				ReloadUI();
			end
		end
		return;
	end
	if (now >= (UnBotBotScanner.nextProgressMessage or 0)) then
		UnBotSpecSummonMessage("Bot scan progress: "..UnBotBotScannerProgressText()..".");
		UnBotBotScanner.nextProgressMessage = now + 30;
	end
	if (now < (UnBotBotScanner.nextTime or 0)) then
		return;
	end
	if (UnBotBotScanner.stage=="wait_scan_combat") then
		if (not UnitAffectingCombat("player") and not InCombatLockdown()) then UnBotBotScannerStartCleanup();
		elseif (now>=(UnBotBotScanner.combatCleanupDeadline or 0)) then
			UnBotBotScanner.active=false; UnBotBotScanner.autoReloadPending=false;
			UnBotBotRegistry.meta.scanInProgress=false;
			UnBotSpecSummonMessage("Скан остановлен: бой не закончился за 180 секунд. После боя выполните /ubscan cleanup для освобождения временного рейда.");
		else UnBotBotScanner.nextTime=now+1; end
		return;
	elseif (UnitAffectingCombat("player") or InCombatLockdown()) then UnBotBotScannerStartCleanup(); return; end

	if (UnBotBotScanner.stage == "start_round") then
		UnBotBotScannerStartRound();
	elseif (UnBotBotScanner.stage == "add_next") then
		UnBotBotScannerBeginAdd();
	elseif (UnBotBotScanner.stage=="collect_member") then
		if (not UnBotBotScannerAcceptNewMember()) then UnBotBotScanner.ContinueAfterProfile(); end
	elseif (UnBotBotScanner.stage == "wait_member") then
		if (not UnBotBotScannerAcceptNewMember()) then
			if (now >= UnBotBotScanner.stageUntil) then
				UnBotBotScanner.noJoinAttempts = UnBotBotScanner.noJoinAttempts + 1;
				if (UnBotBotScanner.noJoinAttempts < UnBotBotScanner.maxNoJoinAttempts) then
					UnBotSpecSummonMessage(
						"Bot scan: no "..UnBotBotScanner.className.." joined; retry "
						..tostring(UnBotBotScanner.noJoinAttempts + 1).."/"
						..tostring(UnBotBotScanner.maxNoJoinAttempts).."."
					);
					UnBotBotScannerBeginAdd();
				else
					UnBotBotScanner.endedByFullRaid = false;
					UnBotBotScannerStartCleanup();
				end
			else
				UnBotBotScanner.nextTime = now + 0.25;
			end
		end
	elseif (UnBotBotScanner.stage == "wait_who") then
		if (now >= UnBotBotScanner.stageUntil) then
			if (UnBotBotScanner.whoAttempts < UnBotBotScanner.maxWhoAttempts) then
				UnBotBotScanner.whoAttempts = UnBotBotScanner.whoAttempts + 1;
				UnBotSpecSummonMessage(
					"Bot scan: retry who for "..tostring(UnBotBotScanner.currentName).." ("
					..tostring(UnBotBotScanner.whoAttempts).."/"..tostring(UnBotBotScanner.maxWhoAttempts)..")."
				);
				SendChatMessage("who", "WHISPER", nil, UnBotBotScanner.currentName);
				UnBotBotScanner.stageUntil = now + 10;
				UnBotBotScanner.nextTime = now + 0.25;
			else
				UnBotSpecSummonMessage(
					"Bot scan: no valid who response from "..tostring(UnBotBotScanner.currentName)
					.."; saved partial profile."
				);
				UnBotTalentInfo.Invalidate(UnBotBotRegistry.bots[UnBotBotScanner.currentName],"Нет свежего ответа who");
				UnBotBotScanner.talentsAttemptedThisRun[UnBotBotScanner.currentName]=true;
				UnBotBotScanner.talentAttempts=UnBotBotScanner.talentAttempts+1;
				UnBotBotScanner.talentFailed=UnBotBotScanner.talentFailed+1;
				UnBotBotScanner.ContinueAfterProfile();
				if (UnBotSpecAuditRefresh) then UnBotSpecAuditRefresh(); end
			end
		else
			UnBotBotScanner.nextTime = now + 0.25;
		end
	elseif (UnBotBotScanner.stage == "cleanup") then
		local members = UnBotSpecSummonGetMembers();
		for name in pairs(members) do
			if (name ~= UnitName("player")) then
				if (not UnBotBotScanner.batchNames[name]) then
					UnBotBotScanner.batchNames[name] = true;
					table.insert(UnBotBotScanner.batchOrder, name);
				end
			end
		end

		local hasOthers = UnBotBuffCycleOtherMemberCount() > 0;
		-- Safe order: remove one online bot from the raid, then take it offline.
		local name = UnBotBotScanner.batchOrder[UnBotBotScanner.cleanupIndex];
		if (name) then
			if (UnBotSpecSummonIsInGroup(name)) then
				UnBotSpecSummonUninvite(name);
				if (now >= UnBotBotScanner.cleanupUntil) then
					SendChatMessage(".playerbot bot remove "..name, "SAY");
					UnBotBotScanner.cleanupUntil = now + 20;
				end
				UnBotBotScanner.nextTime = now + 0.75;
			else
				SendChatMessage(".playerbot bot remove "..name, "SAY");
				UnBotBotScanner.cleanupIndex = UnBotBotScanner.cleanupIndex + 1;
				UnBotBotScanner.cleanupUntil = now + 20;
				UnBotBotScanner.nextTime = now + 0.5;
			end
		else
			-- UnitName can briefly be UNKNOWNOBJECT after a roster update.
			-- Wait for it to resolve instead of treating the group as empty.
			if (hasOthers) then
				UnBotBotScanner.nextTime = now + 0.25;
			else
				UnBotBotScannerAfterCleanup();
			end
		end
	end
end);

SLASH_UNBOTBOTSCAN1 = "/ubscan";
SLASH_UNBOTBOTSCAN2 = "/unbotscan";
SlashCmdList["UNBOTBOTSCAN"] = function(message)
	local command = UnBotSpecSummonNormalize(message);
	if (command == "list") then
		UnBotBotScannerPrintRegistry();
	elseif (command == "summary" or command == "stats") then
		UnBotBotScannerPrintSummary();
	elseif (command == "status" or command == "progress") then
		UnBotBotScannerPrintStatus();
	elseif (command == "storage" or command == "savecheck") then
		UnBotBotScannerStorageStatus(true);
	elseif (command == "cleanup" or command == "clean") then
		UnBotBotScannerStartLateCleanup();
	else
		UnBotBotScannerStart();
	end
end

-- Audit and balance every known class specialization in the registry.  A full
-- audit can confirm each bot through `who` before balancing.  During balancing
-- only currently available profiles count toward the minimum, and the whole
-- donor/deficit plan is rebuilt after every confirmed result.  This server accepts the explicit
-- `.playerbot bot init PLAYERNAME` form in SAY; the older whispered
-- `init=auto` form is unreliable and often returns the command usage.  Each
-- bot is processed and removed before the next one is invited.
UnBotDKSpecBalance = UnBotDKSpecBalance or {
	active = false,
	mode = "idle",
	stage = "idle",
	nextTime = 0,
	stageUntil = 0,
	cleanupUntil = 0,
	queue = {},
	index = 0,
	currentName = nil,
	currentTask = nil,
	minimumCount = 8,
	targetCount = 0,
	completed = 0,
	failed = 0,
	unresolved = 0,
	deficitText = "",
	addAttempts = 0,
	maxAddAttempts = 1,
	inviteAttempts = 0,
	maxInviteAttempts = 1,
	currentOwned = false,
	initAttempts = 0,
	maxInitAttempts = 12,
	lastInitAt = 0,
	whoAttempts = 0,
	maxWhoAttempts = 2,
	stopRequested = false,
	startedAt = 0,
	results = {},
	pendingBalance = false,
	pendingBalanceClass = nil,
	dynamicBalance = false,
	balanceClass = nil,
	excludedNames = {},
	attempted = 0,
	remaining = 0,
	replanned = 0,
	auditClass = nil,
	auditVerified = {},
	auditUnavailable = {},
	auditSuccess = 0,
	auditFailed = 0,
	auditCompletedAt = 0,
	auditWasComplete = false,
	pendingFeralWhoInfo = nil,
	pendingFeralWhoRaw = nil,
	pendingFeralWhoStage = nil,
	feralStrategyAttempts = 0,
};
UnBotSpecCountBalance = UnBotDKSpecBalance;

function UnBotSpecCountBalanceNormalizeSpec(specName)
	local spec = UnBotSpecSummonNormalize(specName);
	if (spec == "assasination") then
		return "assassination";
	elseif (spec == "feral") then
		return "feral combat";
	elseif (spec == "prot") then
		return "protection";
	elseif (spec == "ret") then
		return "retribution";
	elseif (spec == "resto") then
		return "restoration";
	end
	return spec;
end

function UnBotSpecCountBalanceProfileSpec(profile)
	local resolved=UnBotTalentInfo and UnBotTalentInfo.Spec(profile); if (resolved) then return resolved; end
	local className = UnBotSpecSummonNormalize(profile and profile.className);
	local specName = UnBotSpecCountBalanceNormalizeSpec(profile and profile.specName);
	if (className == "druid" and specName == "feral combat") then
		local feralRole = UnBotFeralProfileRole(profile);
		if (feralRole == "bear" or feralRole == "cat") then
			return "feral "..feralRole;
		end
	end
	return specName;
end

function UnBotSpecCountBalanceWhoSpec(whoInfo)
	local className = UnBotSpecSummonNormalize(whoInfo and whoInfo.className);
	local specName = UnBotSpecCountBalanceNormalizeSpec(whoInfo and whoInfo.specName);
	if (
		className == "druid"
		and specName == "feral combat"
		and whoInfo
		and (whoInfo.feralRole == "bear" or whoInfo.feralRole == "cat")
	) then
		return "feral "..whoInfo.feralRole;
	end
	return specName;
end

function UnBotSpecCountBalanceProfileAvailable(name, profile)
	return (
		UnBotIsValidBotName(name)
		and profile
		and not UnBotIsAccountAltProfile(name, profile)
		and not UnBotRegistryGetActiveFlag(profile)
		and not (
			UnBotDKSpecBalance
			and UnBotDKSpecBalance.auditUnavailable
			and UnBotDKSpecBalance.auditUnavailable[name]
		)
	);
end

function UnBotSpecCountBalanceBuildPlan(minimumCount, excludedNames, classFilter, talentMode)
	UnBotRegistryAttachStorage();
	classFilter = UnBotSpecSummonNormalize(classFilter);
	local specsByClass = {};
	local counts = {};
	local candidates = {};
	local talentTargets = talentMode and UnBotTalentInfo.Targets(classFilter,talentMode);
	for _, definition in ipairs(UnBotSpecSummonWhoSpecs) do
		local className = definition.className;
		specsByClass[className] = specsByClass[className] or {};
		counts[className] = counts[className] or {};
		candidates[className] = candidates[className] or {};
		local balanceSpecs = (
			className == "druid" and definition.key == "feral combat"
		) and {"feral bear", "feral cat"} or {definition.key};
		for _, specName in ipairs(balanceSpecs) do
			if (counts[className][specName] == nil) then
				counts[className][specName] = 0;
				candidates[className][specName] = {};
				table.insert(specsByClass[className], specName);
			end
		end
	end
	for name, profile in pairs(UnBotBotRegistry.bots or {}) do
		local className = UnBotSpecSummonNormalize(profile.className);
		local specName = UnBotSpecCountBalanceProfileSpec(profile);
		local available = UnBotSpecCountBalanceProfileAvailable(name, profile);
		if (talentMode) then available=available and UnBotTalentInfo.Get(profile).mode==talentMode; end
		if (available and counts[className] and counts[className][specName] ~= nil) then
			counts[className][specName] = counts[className][specName] + 1;
			if (not (excludedNames and excludedNames[name])) then
				table.insert(candidates[className][specName], name);
			end
		end
	end
	for _, classCandidates in pairs(candidates) do
		for _, names in pairs(classCandidates) do
			for index = #names, 2, -1 do
				local swapIndex = math.random(index);
				names[index], names[swapIndex] = names[swapIndex], names[index];
			end
		end
	end
	local queue = {};
	local deficitParts = {};
	local unresolved = 0;
	for _, className in ipairs(UnBotBotScanner.classes or {}) do
		if (classFilter == "" or className == classFilter) then
			for _, targetSpec in ipairs(specsByClass[className] or {}) do
			local missing = math.max(0, minimumCount - (counts[className][targetSpec] or 0));
			if (talentMode and not (talentTargets and talentTargets[targetSpec])) then missing=0; end
			if (missing > 0) then
				table.insert(
					deficitParts,
					className.." "..targetSpec.." "..tostring(counts[className][targetSpec] or 0)
						.."->"..tostring(minimumCount)
				);
			end
			while (missing > 0) do
				local donorSpec;
				local donorCount = minimumCount;
				for _, sourceSpec in ipairs(specsByClass[className] or {}) do
					if (
						sourceSpec ~= targetSpec
						and (counts[className][sourceSpec] or 0) > donorCount
						and #(candidates[className][sourceSpec] or {}) > 0
					) then
						donorSpec = sourceSpec;
						donorCount = counts[className][sourceSpec];
					end
				end
				if (not donorSpec) then
					unresolved = unresolved + missing;
					break
				end
				local name = table.remove(candidates[className][donorSpec]);
				table.insert(queue, {
					name = name,
					className = className,
					sourceSpec = donorSpec,
					targetSpec = targetSpec,
					preset = talentTargets and talentTargets[targetSpec],
				});
				counts[className][donorSpec] = counts[className][donorSpec] - 1;
				counts[className][targetSpec] = counts[className][targetSpec] + 1;
				missing = missing - 1;
			end
			end
		end
	end
	return queue, unresolved, deficitParts;
end

function UnBotSpecCountBalanceAvailableCount(className, specName, talentMode)
	UnBotRegistryAttachStorage();
	className = UnBotSpecSummonNormalize(className);
	specName = UnBotSpecCountBalanceNormalizeSpec(specName);
	local count = 0;
	for name, profile in pairs(UnBotBotRegistry.bots or {}) do
		if (
			UnBotSpecCountBalanceProfileAvailable(name, profile)
			and (not talentMode or UnBotTalentInfo.Get(profile).mode==talentMode)
			and UnBotSpecSummonNormalize(profile.className) == className
			and UnBotSpecCountBalanceProfileSpec(profile) == specName
		) then
			count = count + 1;
		end
	end
	return count;
end

function UnBotSpecCountBalanceBuildAuditQueue(classFilter, skipNames)
	UnBotRegistryAttachStorage();
	classFilter = UnBotSpecSummonNormalize(classFilter);
	local queue = {};
	for name, profile in pairs(UnBotBotRegistry.bots or {}) do
		local className = UnBotSpecSummonNormalize(profile.className);
		if (
			UnBotIsValidBotName(name)
			and not UnBotIsAccountAltProfile(name, profile)
			and (classFilter == "" or className == classFilter)
			and not (skipNames and skipNames[name])
		) then
			table.insert(queue, {
				name = name,
				className = className,
				sourceSpec = UnBotSpecCountBalanceProfileSpec(profile),
				action = "audit",
			});
		end
	end
	table.sort(queue, function(left, right)
		local leftKey = tostring(left.className or "").."\031"..tostring(left.sourceSpec or "").."\031"..tostring(left.name or "");
		local rightKey = tostring(right.className or "").."\031"..tostring(right.sourceSpec or "").."\031"..tostring(right.name or "");
		return leftKey < rightKey;
	end);
	return queue;
end

function UnBotDKSpecBalanceOtherAutomationActive()
	return (
		(UnBotFullTalentCatalog and UnBotFullTalentCatalog.IsBusy())
		or
		(UnBotStrategySurvey and UnBotStrategySurvey.active)
		or
		(UnBotBotScanner and UnBotBotScanner.active)
		or (UnBotBotScanner and UnBotBotScanner.pendingSpecBalanceClass)
		or (UnBotBotScanner and UnBotBotScanner.pendingTalentAudit)
		or (UnBotJunkCleaner and UnBotJunkCleaner.active)
		or (UnBotFastJunkRaid and UnBotFastJunkRaid.active)
		or (UnBotBuffCycle and UnBotBuffCycle.active)
		or (UnBotSoulstoneTest and UnBotSoulstoneTest.active)
		or (UnBotSpecSummon and UnBotSpecSummon.active)
		or (UnBotBotFix and UnBotBotFix.active)
		or (UnBotRaidReserve and UnBotRaidReserve.active)
		or (
			UnBotMythicPlusBuffIsRunning
			and UnBotMythicPlusBuffIsRunning()
		)
		or (
			UnBotSquadSpecCheck
			and (
				UnBotSquadSpecCheck.active
					or (UnBotSquadSpecCheck.autoStartAt or 0) > 0
			)
		)
	);
end

function UnBotDKSpecBalanceStoreWho(name, whoInfo, rawWho)
	if (not UnBotIsValidBotName(name) or not whoInfo or not whoInfo.className or not whoInfo.specName) then
		return;
	end
	UnBotRegistryAttachStorage();
	local profile = UnBotBotRegistry.bots[name] or {
		name = name,
		firstSeen = time(),
		seenCount = 0,
	};
	profile.name = name;
	profile.className = whoInfo.className;
	profile.specName = whoInfo.specName;
	profile.level = whoInfo.level or profile.level;
	profile.gearScore = whoInfo.gearScore or profile.gearScore;
	profile.rawWho = rawWho or profile.rawWho;
	UnBotStoreFeralRole(profile, whoInfo);
	profile.source = UnBotDKSpecBalance.mode == "audit" and "spec-audit" or "spec-count-balance";
	profile.lastSeen = time();
	profile.specCheckedAt = time();
	profile.seenCount = (profile.seenCount or 0) + 1;
	if (
		UnBotDKSpecBalance.currentTask
		and whoInfo.specName == UnBotDKSpecBalance.currentTask.targetSpec
	) then
		profile.specRebalancedAt = time();
		profile.specRebalanceFrom = UnBotDKSpecBalance.currentTask.sourceSpec;
		profile.specRebalanceTarget = UnBotDKSpecBalance.currentTask.targetSpec;
		profile.specRebalanceInitAttempts = UnBotDKSpecBalance.initAttempts or 0;
	end
	UnBotBotRegistry.bots[name] = profile;
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	UnBotRememberKnownBot(name);
	UnBotDKSpecBalance.auditVerified = UnBotDKSpecBalance.auditVerified or {};
	UnBotDKSpecBalance.auditVerified[name] = time();
	UnBotDKSpecBalance.auditUnavailable = UnBotDKSpecBalance.auditUnavailable or {};
	UnBotDKSpecBalance.auditUnavailable[name] = nil;
	if (UnBotSpecAuditRefresh) then
		UnBotSpecAuditRefresh();
	end
end

function UnBotDKSpecBalanceFinish(text)
	local state = UnBotDKSpecBalance;
	if (UnBotTalentInfo) then UnBotTalentInfo.Cancel(state); end
	local finishedMode = state.mode;
	local finishedClass = state.balanceClass;
	local auditWasComplete = state.auditWasComplete;
	if (state.registryRefreshJob) then UnBotRegistryRefresh.Finished(state,auditWasComplete,text); end
	state.active = false;
	state.mode = "idle";
	state.stage = "idle";
	state.nextTime = 0;
	state.stageUntil = 0;
	state.cleanupUntil = 0;
	state.currentName = nil;
	state.currentTask = nil;
	state.pendingFeralWhoInfo = nil;
	state.pendingFeralWhoRaw = nil;
	state.pendingFeralWhoStage = nil;
	state.pendingBalance = false;
	state.pendingBalanceClass = nil;
	state.balanceClass = nil;
	UnBotRegistryAttachStorage();
	if (finishedMode == "audit") then
		if (state.auditWasComplete) then
			state.auditCompletedAt = time();
			UnBotBotRegistry.meta.lastSpecAuditAt = state.auditCompletedAt;
			UnBotBotRegistry.meta.lastSpecAuditClass = state.auditClass;
			UnBotBotRegistry.meta.lastSpecAuditTarget = state.targetCount or 0;
			UnBotBotRegistry.meta.lastSpecAuditCompleted = state.auditSuccess or 0;
			UnBotBotRegistry.meta.lastSpecAuditFailed = state.auditFailed or 0;
		else
			UnBotBotRegistry.meta.lastSpecAuditStoppedAt = time();
		end
	else
		UnBotBotRegistry.meta.lastSpecCountBalanceAt = time();
		UnBotBotRegistry.meta.lastSpecCountBalanceClass = finishedClass;
		UnBotBotRegistry.meta.lastSpecCountBalanceMinimum = state.minimumCount or 8;
		UnBotBotRegistry.meta.lastSpecCountBalanceTarget = state.targetCount or 0;
		UnBotBotRegistry.meta.lastSpecCountBalanceCompleted = state.completed or 0;
		UnBotBotRegistry.meta.lastSpecCountBalanceFailed = state.failed or 0;
		UnBotBotRegistry.meta.lastSpecCountBalanceUnresolved = state.unresolved or 0;
	end
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	if (finishedMode == "balance" or (finishedMode == "audit" and not auditWasComplete)) then
		UnBotClassSpecRebuildCheckpointClear();
	end
	if (finishedMode == "audit") then
		UnBotSpecSummonMessage(
			(text or "Перепроверка спеков завершена.")
			.." Проверено: "..tostring(state.auditSuccess or 0).."/"..tostring(state.targetCount or 0)
			..", недоступно: "..tostring(state.auditFailed or 0)
			..", полные таланты: "..tostring(state.talentSuccess or 0)..", осмотр не подтверждён: "..tostring(state.talentFailed or 0)
			..", время: "..tostring(math.floor(GetTime() - (state.startedAt or GetTime()))).." сек. "
			.."Для сохранения реестра выполните /reload."
		);
	else
		UnBotSpecSummonMessage(
			(text or "Выравнивание спеков завершено.")
			.." Полезных изменений: "..tostring(state.completed or 0)
			..", неудачных кандидатов: "..tostring(state.failed or 0)
			..", осталось без доступного донора: "..tostring(state.unresolved or 0)
			..", перепланирований: "..tostring(state.replanned or 0)
			..", время: "..tostring(math.floor(GetTime() - (state.startedAt or GetTime()))).." сек. "
			.."Для сохранения реестра выполните /reload."
		);
	end
	if (UnBotSpecAuditRefresh) then
		UnBotSpecAuditRefresh();
	end
	if (state.afterTalentAudit) then
		local done=state.afterTalentAudit; state.afterTalentAudit=nil; done(auditWasComplete);
	end
end

function UnBotDKSpecBalanceBeginCleanup()
	local state = UnBotDKSpecBalance;
	if (UnBotTalentInfo) then UnBotTalentInfo.Cancel(state); end
	if (UnitAffectingCombat("player") or InCombatLockdown()) then
		state.stopRequested=true;
		state.stage="wait_talent_combat"; state.nextTime=GetTime()+1;
		state.combatCleanupDeadline=GetTime()+180;
		UnBotSpecSummonMessage("Проверка талантов остановлена боем; освобожу временного бота после боя.");
		return;
	end
	local name = state.currentName;
	if (not name) then
		state.stage = "next_bot";
		state.nextTime = GetTime() + 0.5;
		return;
	end
	if (UnBotSpecSummonIsInGroup(name)) then
		UnBotSpecSummonUninvite(name);
		state.stage = "wait_leave";
		state.nextTime = GetTime() + 0.75;
		state.stageUntil = GetTime() + 15;
		state.cleanupUntil = GetTime() + 30;
	else
		if (state.currentOwned) then
			SendChatMessage(".playerbot bot remove "..name, "SAY");
		end
		if (state.registryRefreshJob) then UnBotRegistryRefresh.Cleaned(state); end
		state.currentName = nil;
		state.currentTask = nil;
		state.currentOwned = false;
		state.stage = "next_bot";
		state.nextTime = GetTime() + 1;
	end
end

function UnBotDKSpecBalanceFailCurrent(reason)
	local state = UnBotDKSpecBalance;
	local name = state.currentName;
	if (name) then
		if (state.registryRefreshJob) then UnBotRegistryRefresh.Record(state,"failed",reason); end
		state.failed = (state.failed or 0) + 1;
		if (state.mode == "audit") then
			if (UnBotTalentInfo) then UnBotTalentInfo.Invalidate(UnBotBotRegistry.bots[name],reason); end
			state.auditFailed = (state.auditFailed or 0) + 1;
			state.auditUnavailable = state.auditUnavailable or {};
			state.auditUnavailable[name] = true;
		else
			state.excludedNames = state.excludedNames or {};
			state.excludedNames[name] = true;
			if ((state.initAttempts or 0) == 0 and not (state.currentTask and state.currentTask.preset)) then
				state.auditUnavailable = state.auditUnavailable or {};
				state.auditUnavailable[name] = true;
			end
		end
		state.results[name] = "failed: "..tostring(reason or "unknown");
		UnBotSpecSummonMessage(
			(state.mode == "audit" and "Перепроверка спеков: " or "Выравнивание спеков: ")
			..name.." пропущен — "..tostring(reason or "неизвестная ошибка").."."
		);
	end
	UnBotDKSpecBalanceBeginCleanup();
end

function UnBotDKSpecBalanceCompleteCurrent(whoInfo, rawWho, acceptedSpec)
	local state = UnBotDKSpecBalance;
	local name = state.currentName;
	local task = state.currentTask;
	if (not name) then
		return;
	end
	state.completed = (state.completed or 0) + 1;
	if (task and task.action == "audit") then
		state.auditSuccess = (state.auditSuccess or 0) + 1;
		state.results[name] = whoInfo.specName;
		if (
			state.auditSuccess == 1
			or state.auditSuccess % 10 == 0
			or state.auditSuccess + (state.auditFailed or 0) >= (state.targetCount or 0)
		) then
			UnBotSpecSummonMessage(
				"Перепроверка спеков: "..tostring(state.auditSuccess + (state.auditFailed or 0))
				.."/"..tostring(state.targetCount or 0)..", подтверждён "..name.." — "
				..tostring(whoInfo.className).." "..tostring(whoInfo.specName).."."
			);
		end
		UnBotDKSpecBalanceBeginCleanup();
		return;
	end
	acceptedSpec = acceptedSpec or (task and task.targetSpec) or whoInfo.specName;
	state.results[name] = acceptedSpec;
	local profile = UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (profile) then
		profile.specRebalancedAt = time();
		profile.specRebalanceFrom = task and task.sourceSpec or profile.specRebalanceFrom;
		profile.specRebalanceTarget = acceptedSpec;
		profile.specRebalanceInitAttempts = state.initAttempts or 0;
	end
	if (task and not task.preset) then
		local feralRole = string.match(tostring(acceptedSpec or ""), "^feral%s+(%S+)$");
		if (feralRole == "bear" or feralRole == "cat") then
			UnBotSpecSummonEnsureCombatRole(name, task.className, feralRole, "spec-count-balance");
		else
			UnBotSpecSummonEnsureTankStrategy(name, task.className, acceptedSpec, "spec-count-balance");
		end
	end
	UnBotSpecSummonMessage(
		"Выравнивание спеков: "..name.." подтверждён как "
		..tostring(task and task.className or whoInfo.className).." "..tostring(acceptedSpec).." ("
		.."полезных изменений "..tostring(state.completed)
		..", init "..tostring(state.initAttempts or 0)..")."
	);
	UnBotDKSpecBalanceBeginCleanup();
end

function UnBotDKSpecBalanceSendInit()
	local state = UnBotDKSpecBalance;
	if (not state.currentName) then
		return;
	end
	if (not UnBotSpecSummonPlayerSupportsSpecs()) then
		UnBotDKSpecBalanceFailCurrent("init отключён до 11 уровня");
		return;
	end
	local now = GetTime();
	local allowedAt = (state.lastInitAt or 0) + 3;
	if ((state.lastInitAt or 0) > 0 and now < allowedAt) then
		state.stage = "retry_init";
		state.nextTime = allowedAt;
		return;
	end
	state.initAttempts = (state.initAttempts or 0) + 1;
	state.whoAttempts = 0;
	state.lastInitAt = now;
	SendChatMessage(".playerbot bot init "..state.currentName, "SAY");
	state.stage = "wait_init_settle";
	state.nextTime = now + 1;
	state.stageUntil = now + 4;
	UnBotSpecSummonMessage(
		"Выравнивание спеков: "..state.currentName.." — init "
		..tostring(state.initAttempts).."/"..tostring(state.maxInitAttempts).."."
	);
end

function UnBotDKSpecBalanceSendWho(postInit)
	local state = UnBotDKSpecBalance;
	if (not state.currentName) then
		return;
	end
	state.whoAttempts = 1;
	if (postInit) then
		state.stage = "wait_post_who";
	else
		state.stage = "wait_initial_who";
	end
	SendChatMessage("who", "WHISPER", nil, state.currentName);
	state.nextTime = GetTime() + 0.25;
	state.stageUntil = GetTime() + (postInit and 3 or 5);
end

function UnBotDKSpecBalanceFinishAuditPhase()
	local state = UnBotDKSpecBalance;
	state.auditWasComplete = true;
	state.auditCompletedAt = time();
	UnBotRegistryAttachStorage();
	UnBotBotRegistry.meta.lastSpecAuditAt = state.auditCompletedAt;
	UnBotBotRegistry.meta.lastSpecAuditClass = state.auditClass;
	UnBotBotRegistry.meta.lastSpecAuditTarget = state.targetCount or 0;
	UnBotBotRegistry.meta.lastSpecAuditCompleted = state.auditSuccess or 0;
	UnBotBotRegistry.meta.lastSpecAuditFailed = state.auditFailed or 0;
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	UnBotSpecSummonMessage(
		"Перепроверка спеков завершена: подтверждено "..tostring(state.auditSuccess or 0)
		.."/"..tostring(state.targetCount or 0)..", недоступно "..tostring(state.auditFailed or 0).."."
	);
	if (UnBotSpecAuditRefresh) then
		UnBotSpecAuditRefresh();
	end
	if (state.pendingBalance and not state.stopRequested) then
		local minimumCount = state.minimumCount or 8;
		local balanceClass = state.pendingBalanceClass;
		state.pendingBalance = false;
		state.pendingBalanceClass = nil;
		state.active = false;
		local talentMode=state.pendingBalanceMode; state.pendingBalanceMode=nil;
		UnBotDKSpecBalanceStart(minimumCount, true, balanceClass,talentMode);
	else
		UnBotDKSpecBalanceFinish("Перепроверка спеков завершена.");
	end
end

function UnBotDKSpecBalanceStartCurrent()
	local state = UnBotDKSpecBalance;
	if (state.stopRequested) then
		UnBotDKSpecBalanceFinish(
			state.mode == "audit"
			and "Перепроверка спеков остановлена пользователем."
			or "Выравнивание спеков остановлено пользователем."
		);
		return;
	end
	if (state.mode == "balance" and state.dynamicBalance) then
		local queue, unresolved, deficitParts = UnBotSpecCountBalanceBuildPlan(
			state.minimumCount or 8,
			state.excludedNames,
			state.balanceClass,
			state.talentMode
		);
		state.queue = queue;
		state.remaining = #queue;
		state.unresolved = unresolved or 0;
		state.deficitText = table.concat(deficitParts, ", ");
		if (#deficitParts == 0) then
			UnBotDKSpecBalanceFinish("Выравнивание спеков завершено: подтверждённый минимум достигнут.");
			return;
		elseif (#queue == 0) then
			UnBotDKSpecBalanceFinish(
				"Выравнивание спеков завершено не полностью: доступных доноров больше нет. Дефицит: "
				..state.deficitText.."."
			);
			return;
		end
		state.currentTask = queue[1];
		state.currentName = state.currentTask and state.currentTask.name;
		state.attempted = (state.attempted or 0) + 1;
	else
		state.index = (state.index or 0) + 1;
		state.currentTask = state.queue[state.index];
		state.currentName = state.currentTask and state.currentTask.name;
	end
	if (not state.currentTask or not state.currentName) then
		if (state.mode == "audit") then
			UnBotDKSpecBalanceFinishAuditPhase();
		else
			UnBotDKSpecBalanceFinish("Выравнивание спеков завершено.");
		end
		return;
	end
	state.addAttempts = 1;
	state.inviteAttempts = 0;
	state.currentOwned = false;
	state.initAttempts = 0;
	state.lastInitAt = 0;
	state.whoAttempts = 0;
	state.pendingFeralWhoInfo = nil;
	state.pendingFeralWhoRaw = nil;
	state.pendingFeralWhoStage = nil;
	state.feralStrategyAttempts = 0;
	state.stage = "wait_member";
	state.nextTime = GetTime() + 1;
	state.stageUntil = GetTime() + 6;
	if (state.registryRefreshJob and not UnBotRegistryRefresh.BeforeAdd(state)) then return; end
	SendChatMessage(".playerbot bot add "..state.currentName, "SAY");
	if (state.mode == "audit") then
		UnBotSpecSummonMessage(
			"Перепроверка спеков: вызываю "..state.currentName.." ("
			..tostring(state.index).."/"..tostring(state.targetCount)..")."
		);
	else
		UnBotSpecSummonMessage(
			"Выравнивание спеков: вызываю "..state.currentName.." (кандидат "
			..tostring(state.attempted or 0)..", по текущему плану осталось "
			..tostring(state.remaining or 0)..") для "
			..state.currentTask.className.." "..state.currentTask.targetSpec.."."
		);
	end
end

function UnBotDKSpecBalanceStart(minimumCount, continuingAfterAudit, classFilter, talentMode)
	if (not UnBotSpecSummonPlayerSupportsSpecs()) then
		UnBotClassSpecRebuildCheckpointClear();
		UnBotSpecSummonMessage(
			"Выравнивание специализаций отключено до 11 уровня; доступен только подбор по классу."
		);
		return;
	end
	classFilter = UnBotSpecSummonNormalize(classFilter);
	classFilter = UnBotSpecSummonClassAliases[classFilter] or classFilter;
	if (classFilter == "") then
		UnBotSpecSummonMessage(
			"Пересборка сразу всех классов отключена для защиты общего серверного пула. "
			.."Выберите один класс во вкладке Специализации."
		);
		return;
	end
	local supportedClass = false;
	for _, className in ipairs(UnBotBotScanner.classes or {}) do
		if (className == classFilter) then
			supportedClass = true;
			break
		end
	end
	if (not supportedClass) then
		UnBotSpecSummonMessage("Неизвестный класс для пересборки: "..tostring(classFilter)..".");
		return;
	end
	local state = UnBotDKSpecBalance;
	if (not continuingAfterAudit) then
		if (state.active) then
			UnBotSpecSummonMessage("Аудит/балансировка уже выполняется. Используйте кнопку Стоп или /ubspecbalance stop.");
			return;
		end
		if (UnitAffectingCombat("player")) then
			UnBotSpecSummonMessage("Выравнивание спеков можно запускать только вне боя.");
			return;
		end
		if (UnBotDKSpecBalanceOtherAutomationActive()) then
			UnBotSpecSummonMessage("Сначала завершите другой автоматический цикл UnBot.");
			return;
		end
		if (UnBotBuffCycleOtherMemberCount() > 0) then
			UnBotSpecSummonMessage("Выравнивание спеков требует полностью пустую группу/рейд, включая офлайн-резерв.");
			return;
		end
	end
	minimumCount = math.max(1, math.min(12, tonumber(minimumCount) or 8));
	if (talentMode and not UnBotTalentInfo.Targets(classFilter,talentMode)) then
		UnBotSpecSummonMessage("Пересборка: сначала соберите полный каталог талантов этого класса."); return;
	end
	local queue, unresolved, deficitParts = UnBotSpecCountBalanceBuildPlan(minimumCount, {}, classFilter,talentMode);
	state.active = true;
	state.mode = "balance";
	state.talentMode=talentMode;
	state.dynamicBalance = true;
	state.balanceClass = classFilter ~= "" and classFilter or nil;
	state.minimumCount = minimumCount;
	state.completed = 0;
	state.failed = 0;
	state.unresolved = unresolved or 0;
	state.replanned = 0;
	state.attempted = 0;
	state.remaining = #queue;
	state.excludedNames = {};
	state.stopRequested = false;
	state.startedAt = GetTime();
	state.results = {};
	state.maxInitAttempts = 6;
	if (#deficitParts == 0) then
		state.targetCount = 0;
		UnBotDKSpecBalanceFinish(
			"Выравнивание не требуется: среди доступных профилей "
			..(classFilter ~= "" and ("класса "..classFilter.." ") or "во всех классах ")
			.."в каждой специализации не меньше "
			..tostring(minimumCount).." ботов."
		);
		return;
	end
	if (#queue == 0) then
		state.targetCount = 0;
		state.deficitText = table.concat(deficitParts, ", ");
		UnBotDKSpecBalanceFinish(
			"Выравнивание не выполнено: дефицит есть, но у соответствующих классов нет "
			.."доступных специализаций с запасом выше "..tostring(minimumCount)..". Дефицит: "
			..state.deficitText.."."
		);
		return;
	end
	state.stage = "next_bot";
	state.nextTime = GetTime();
	state.stageUntil = 0;
	state.cleanupUntil = 0;
	state.queue = queue;
	state.index = 0;
	state.currentName = nil;
	state.currentTask = nil;
	state.targetCount = #queue;
	state.deficitText = table.concat(deficitParts, ", ");
	UnBotSpecSummonMessage(
		"Динамическое выравнивание запущено: минимум "..tostring(minimumCount)
		.." доступных ботов на специализацию"
		..(classFilter ~= "" and (", класс "..classFilter) or "")
		..", начальный план "..tostring(#queue)
		.." ботов, не удалось запланировать "..tostring(unresolved or 0)..". Дефицит: "
		..state.deficitText..". План будет пересчитан после каждого who/init; "
		.."не более "..tostring(state.maxInitAttempts).." инициализаций на кандидата."
	);
	UnBotDKSpecBalanceStartCurrent();
end

function UnBotSpecCountBalanceStart(minimumCount, classFilter, talentMode)
	if (not UnBotSpecSummonPlayerSupportsSpecs()) then
		UnBotClassSpecRebuildCheckpointClear();
		UnBotSpecSummonMessage(
			"Пересборка специализаций отключена до 11 уровня; ботам не отправляются who/init."
		);
		return;
	end
	classFilter = UnBotSpecSummonNormalize(classFilter);
	classFilter = UnBotSpecSummonClassAliases[classFilter] or classFilter;
	if (classFilter == "") then
		UnBotSpecSummonMessage(
			"Пересборка сразу всех классов отключена для защиты общего серверного пула. "
			.."Выберите один класс во вкладке Специализации."
		);
		return;
	end
	UnBotBotScannerStartClassBalance(classFilter, minimumCount,talentMode);
end

function UnBotSpecAuditStart(classFilter, balanceAfterAudit, minimumCount, talentMode, skipNames, refreshJob, refreshQueue)
	if (not UnBotSpecSummonPlayerSupportsSpecs()) then
		UnBotClassSpecRebuildCheckpointClear();
		UnBotSpecSummonMessage(
			"Перепроверка специализаций отключена до 11 уровня; серверный спек 0/0/0 игнорируется."
		);
		return;
	end
	classFilter = UnBotSpecSummonNormalize(classFilter);
	classFilter = UnBotSpecSummonClassAliases[classFilter] or classFilter;
	local state = UnBotDKSpecBalance;
	if (balanceAfterAudit and classFilter == "") then
		UnBotSpecSummonMessage(
			"Пересборка сразу всех классов отключена. Для изменения специализаций выберите один класс."
		);
		return;
	end
	if (state.active) then
		UnBotSpecSummonMessage("Аудит/балансировка уже выполняется. Используйте кнопку Стоп или /ubspecbalance stop.");
		return;
	end
	if (UnitAffectingCombat("player")) then
		UnBotSpecSummonMessage("Перепроверку спеков можно запускать только вне боя.");
		return;
	end
	if (UnBotDKSpecBalanceOtherAutomationActive()) then
		UnBotSpecSummonMessage("Сначала завершите другой автоматический цикл UnBot.");
		return;
	end
	if (UnBotBuffCycleOtherMemberCount() > 0 and not (refreshJob and UnBotRegistryRefresh.RecoveryAllowed(refreshJob))) then
		UnBotSpecSummonMessage("Перепроверка спеков требует полностью пустую группу/рейд, включая офлайн-резерв.");
		return;
	end
	minimumCount = math.max(1, math.min(12, tonumber(minimumCount) or 8));
	local queue = refreshQueue or UnBotSpecCountBalanceBuildAuditQueue(classFilter,skipNames);
	if (#queue == 0 and not skipNames and not refreshJob) then
		UnBotSpecSummonMessage(
			classFilter ~= ""
			and ("В реестре нет ботов класса "..classFilter.." для перепроверки.")
			or "В реестре нет ботов для перепроверки. Сначала выполните полный скан."
		);
		return;
	end
	state.active = true;
	state.registryRefreshJob = refreshJob;
	state.mode = "audit";
	state.dynamicBalance = false;
	state.pendingBalance = balanceAfterAudit and true or false;
	state.pendingBalanceMode=balanceAfterAudit and talentMode or nil;
	state.pendingBalanceClass = balanceAfterAudit and classFilter ~= "" and classFilter or nil;
	state.auditClass = classFilter ~= "" and classFilter or nil;
	state.minimumCount = minimumCount;
	state.queue = queue;
	state.index = 0;
	state.currentName = nil;
	state.currentTask = nil;
	state.targetCount = #queue;
	state.completed = 0;
	state.failed = 0;
	state.unresolved = 0;
	if (classFilter == "") then
		state.auditVerified = {};
		state.auditUnavailable = {};
	else
		state.auditVerified = state.auditVerified or {};
		state.auditUnavailable = state.auditUnavailable or {};
		for _, task in ipairs(queue) do
			state.auditVerified[task.name] = nil;
			state.auditUnavailable[task.name] = nil;
		end
	end
	state.auditSuccess = 0;
	state.auditFailed = 0;
	state.talentSuccess = 0;
	state.talentFailed = 0;
	state.auditWasComplete = false;
	state.stopRequested = false;
	state.startedAt = GetTime();
	state.results = {};
	state.stage = "next_bot";
	state.nextTime = GetTime();
	state.stageUntil = 0;
	state.cleanupUntil = 0;
	UnBotSpecSummonMessage(
		"Перепроверка спеков запущена: "
		..(classFilter ~= "" and ("класс "..classFilter) or "весь реестр")
		..", ботов "..tostring(#queue)
		..(balanceAfterAudit and ("; затем динамическое выравнивание до минимума "..tostring(minimumCount)..".") or ".")
	);
	if (not (refreshJob and UnBotRegistryRefresh.Recover(state,refreshJob))) then
		UnBotDKSpecBalanceStartCurrent();
	end
	return true;
end

function UnBotSpecAuditStop()
	if (UnBotBatchSummon and UnBotBatchSummon.refresh) then UnBotRegistryRefresh.Stop(); return; end
	local state = UnBotDKSpecBalance;
	if (not state.active) then
		UnBotSpecSummonMessage("Аудит/балансировка уже остановлены.");
		return;
	end
	state.stopRequested = true;
	state.pendingBalance = false;
	UnBotClassSpecRebuildCheckpointClear();
	UnBotSpecSummonMessage("Аудит/балансировка: остановка запрошена; завершаю очистку текущего бота.");
	if (state.registryRefreshJob and state.stage == "wait_member" and not state.currentOwned
		and not UnBotSpecSummonIsInGroup(state.currentName)) then
		state.stage, state.nextTime, state.stageUntil = "wait_refresh_stop", GetTime()+.25, GetTime()+8;
		return;
	end
	UnBotDKSpecBalanceBeginCleanup();
end

function UnBotDKSpecBalanceStatus()
	local state = UnBotDKSpecBalance;
	if (not state.active) then
		UnBotSpecSummonMessage(
			"Аудит/балансировка не выполняются. Последняя перепроверка: "
			..tostring(state.auditSuccess or 0).." подтверждено, "
			..tostring(state.auditFailed or 0).." недоступно; последняя балансировка: "
			..tostring(state.completed or 0).." полезных изменений."
		);
		return;
	end
	if (state.mode == "audit") then
		UnBotSpecSummonMessage(
			"Перепроверка спеков: этап "..tostring(state.stage)
			..", бот "..tostring(state.currentName or "-")
			..", обработано "..tostring((state.auditSuccess or 0) + (state.auditFailed or 0))
			.."/"..tostring(state.targetCount or 0)
			..", подтверждено "..tostring(state.auditSuccess or 0)
			..", недоступно "..tostring(state.auditFailed or 0)
			..(state.pendingBalance and "; затем будет балансировка." or ".")
		);
	else
		UnBotSpecSummonMessage(
			"Выравнивание спеков: этап "..tostring(state.stage)
			..", бот "..tostring(state.currentName or "-")
			..", цель "..tostring(state.currentTask and (
				state.currentTask.className.." "..state.currentTask.targetSpec
			) or "-")
			..", полезных изменений "..tostring(state.completed or 0)
			..", неудачных кандидатов "..tostring(state.failed or 0)
			..", по текущему плану осталось "..tostring(state.remaining or 0).."."
		);
	end
end

function UnBotDKSpecBalanceProcessWho(whoInfo, rawWho)
	local state = UnBotDKSpecBalance;
	local sender = state.currentName;
	local task = state.currentTask;
	local actualSpec = UnBotSpecCountBalanceWhoSpec(whoInfo);
	UnBotDKSpecBalanceStoreWho(sender, whoInfo, rawWho);
	if (task and task.preset) then UnBotTalentInfo.BalanceWho(state,whoInfo,rawWho); return; end
	if (not task) then
		UnBotDKSpecBalanceFailCurrent("потеряна текущая задача");
	elseif (task.action == "audit") then
		state.stage = "wait_talents";
		UnBotTalentInfo.Begin(sender,state,function(snapshot,reason)
			if (snapshot) then state.talentSuccess=(state.talentSuccess or 0)+1;
			else state.talentFailed=(state.talentFailed or 0)+1; end
			if (state.registryRefreshJob) then UnBotRegistryRefresh.Record(state,snapshot and "verified" or "partial",reason); end
			UnBotDKSpecBalanceCompleteCurrent(whoInfo,rawWho,actualSpec);
		end,function() return state.active and state.currentName==sender and state.stage=="wait_talents"; end);
	elseif (whoInfo.className ~= task.className) then
		state.replanned = (state.replanned or 0) + 1;
		state.results[sender] = "replan class: "..tostring(task.className).." -> "..tostring(whoInfo.className);
		UnBotSpecSummonMessage(
			"Выравнивание спеков: реестр устарел — "..sender.." оказался класса "
			..tostring(whoInfo.className or "?").." вместо "..tostring(task.className)
			..". Не меняю бота и пересчитываю план."
		);
		UnBotDKSpecBalanceBeginCleanup();
	elseif (actualSpec == task.targetSpec) then
		UnBotDKSpecBalanceCompleteCurrent(whoInfo, rawWho, actualSpec);
	elseif (
		(task.targetSpec == "feral bear" or task.targetSpec == "feral cat")
		and (actualSpec == "feral bear" or actualSpec == "feral cat")
	) then
		local targetRole = string.match(task.targetSpec, "^feral%s+(%S+)$");
		UnBotSpecSummonEnsureFeralRoleStrategy(sender, task.className, targetRole, "spec-count-balance");
		whoInfo.feralRole = targetRole;
		whoInfo.feralRoleSource = "combat-strategy";
		UnBotDKSpecBalanceStoreWho(sender, whoInfo, rawWho);
		UnBotDKSpecBalanceCompleteCurrent(whoInfo, rawWho, task.targetSpec);
	elseif (state.stage == "wait_initial_who") then
		if (actualSpec ~= task.sourceSpec) then
			state.replanned = (state.replanned or 0) + 1;
			state.results[sender] = "replan: "..tostring(task.sourceSpec).." -> "..tostring(actualSpec);
			UnBotSpecSummonMessage(
				"Выравнивание спеков: реестр устарел — "..sender.." оказался "
				..tostring(actualSpec).." вместо "..tostring(task.sourceSpec)
				..". Не меняю бота и пересчитываю весь план."
			);
			UnBotDKSpecBalanceBeginCleanup();
		else
			UnBotSpecSummonMessage(
				"Выравнивание спеков: "..sender.." подтверждён как донор "..tostring(actualSpec)
				.."; цель "..task.targetSpec..", запускаю инициализацию."
			);
			UnBotDKSpecBalanceSendInit();
		end
	else
		local usefulCount = UnBotSpecCountBalanceAvailableCount(task.className, actualSpec);
		if (
			actualSpec ~= task.sourceSpec
			and usefulCount <= (state.minimumCount or 8)
		) then
			UnBotSpecSummonMessage(
				"Выравнивание спеков: "..sender.." получил не исходную цель, но закрыл дефицит "
				..tostring(actualSpec).." (теперь "..tostring(usefulCount).."/"
				..tostring(state.minimumCount or 8).."). Принимаю результат и пересчитываю план."
			);
			UnBotDKSpecBalanceCompleteCurrent(whoInfo, rawWho, actualSpec);
		elseif ((state.initAttempts or 0) < (state.maxInitAttempts or 12)) then
			UnBotSpecSummonMessage(
				"Выравнивание спеков: "..sender.." после init получил "..tostring(actualSpec)
				..", требуется "..task.targetSpec.."; повторю init "
				..tostring(state.initAttempts + 1).."/"..tostring(state.maxInitAttempts).."."
			);
			state.stage = "retry_init";
			state.nextTime = math.max(GetTime() + 0.1, (state.lastInitAt or 0) + 3);
		else
			UnBotDKSpecBalanceFailCurrent(
				task.targetSpec.." не получен за "..tostring(state.initAttempts).." инициализаций"
			);
		end
	end
end

UnBotDKSpecBalanceFrame = UnBotDKSpecBalanceFrame or CreateFrame("Frame", "UnBotDKSpecBalanceFrame");
UnBotDKSpecBalanceFrame:RegisterEvent("CHAT_MSG_WHISPER");
UnBotDKSpecBalanceFrame:RegisterEvent("CHAT_MSG_SYSTEM");
UnBotDKSpecBalanceFrame:RegisterEvent("PARTY_MEMBERS_CHANGED");
UnBotDKSpecBalanceFrame:RegisterEvent("RAID_ROSTER_UPDATE");
UnBotDKSpecBalanceFrame:SetScript("OnEvent", function(self, event, message, sender)
	if (UnBotBatchSummon and UnBotBatchSummon.refresh) then return; end
	local state = UnBotDKSpecBalance;
	if (not state.active) then
		return;
	end
	if (state.registryRefreshJob and not UnBotRegistryRefresh.Guard(state)) then return; end
	if (event == "PARTY_MEMBERS_CHANGED" or event == "RAID_ROSTER_UPDATE") then
		if (state.stage == "wait_member" and UnBotSpecSummonIsInGroup(state.currentName)) then
			state.currentOwned = true;
			UnBotDKSpecBalanceSendWho(false);
		end
		return;
	end
	if (event == "CHAT_MSG_SYSTEM") then
		local text = UnBotSpecSummonNormalize(message);
		if (
			state.mode == "balance"
			and
			state.stage ~= "wait_member"
			and string.find(text, "usage:", 1, true)
			and string.find(text, "add/init/remove", 1, true)
		) then
			UnBotDKSpecBalanceFailCurrent(
				"сервер отклонил команду init; дальнейшие попытки для этого бота остановлены"
			);
			return;
		end
		if (state.stage ~= "wait_member") then
			return;
		end
		local currentName = UnBotSpecSummonNormalize(state.currentName);
		if (not string.find(text, currentName, 1, true)) then
			return;
		end
		if (string.find(text, "add:", 1, true) and string.find(text, " - ok", 1, true)) then
			state.currentOwned = true;
			UnBotSpecSummonMessage(
				"Выравнивание спеков: "..state.currentName.." включён; сразу запрашиваю who."
			);
			UnBotDKSpecBalanceSendWho(false);
		elseif (
			string.find(text, "player already logged in", 1, true)
			or string.find(text, "already logged in", 1, true)
			or string.find(text, "already in group", 1, true)
			or string.find(text, "уже состоит в группе", 1, true)
			or string.find(text, "уже в игре", 1, true)
		) then
			UnBotRegistrySetHourlyQuarantine(
				state.currentName,
				"аудит: сервер подтвердил, что бот уже залогинен у другого игрока",
				"Ротация"
			);
			UnBotDKSpecBalanceFailCurrent(
				"бот уже занят другим игроком; повторные add/invite остановлены"
			);
		elseif (
			string.find(text, "не найден", 1, true)
			or string.find(text, "player not found", 1, true)
			or string.find(text, "no player named", 1, true)
		) then
			UnBotDKSpecBalanceFailCurrent("сервер не нашёл игрока после единственного вызова");
		end
		return;
	end
	if (event ~= "CHAT_MSG_WHISPER" or sender ~= state.currentName) then
		return;
	end
	if (state.stage=="wait_talent_preset") then UnBotTalentInfo.BalanceReply(state,message); return; end
	if (state.stage == "wait_member") then
		UnBotSpecSummonMessage(
			"Выравнивание спеков: "..state.currentName.." ответил; сразу запрашиваю who."
		);
		UnBotDKSpecBalanceSendWho(false);
		return;
	end
	if (state.stage == "wait_feral_strategy") then
		local feralRole, strategyReply = UnBotFeralRoleFromStrategyText(message);
		if (not strategyReply) then
			return;
		end
		local whoInfo = state.pendingFeralWhoInfo;
		local rawWho = state.pendingFeralWhoRaw;
		local whoStage = state.pendingFeralWhoStage;
		state.pendingFeralWhoInfo = nil;
		state.pendingFeralWhoRaw = nil;
		state.pendingFeralWhoStage = nil;
		if (not whoInfo or not feralRole) then
			UnBotDKSpecBalanceFailCurrent("ответ co ? не содержит однозначной стратегии bear или cat");
			return;
		end
		whoInfo.feralRole = feralRole;
		whoInfo.feralRoleSource = "combat-strategy";
		state.stage = whoStage or "wait_initial_who";
		UnBotSpecSummonMessage(
			"Feral-проверка: "..sender.." подтверждён через co ? как "
			..(feralRole == "bear" and "Bear" or "Cat").."."
		);
		UnBotDKSpecBalanceProcessWho(whoInfo, rawWho);
		return;
	end
	local text = UnBotSpecSummonNormalize(message);
	if (
		(state.stage == "wait_init_settle" or state.stage == "wait_post_who")
		and (
			string.find(text, "unknown command", 1, true)
			or string.find(text, "not allowed", 1, true)
			or string.find(text, "cannot initialize", 1, true)
		)
	) then
		UnBotDKSpecBalanceFailCurrent("сервер отклонил Initialize a bot: "..tostring(message));
		return;
	end
	if (state.stage ~= "wait_initial_who" and state.stage ~= "wait_post_who") then
		return;
	end
	local whoInfo = UnBotSpecSummonParseWho(message);
	if (not whoInfo) then
		return;
	end
	if (
		state.mode ~= "audit" and not state.talentMode
		and whoInfo.className == "druid"
		and whoInfo.specName == "feral combat"
		and not whoInfo.feralRole
	) then
		state.pendingFeralWhoInfo = whoInfo;
		state.pendingFeralWhoRaw = message;
		state.pendingFeralWhoStage = state.stage;
		state.feralStrategyAttempts = 1;
		state.stage = "wait_feral_strategy";
		state.nextTime = GetTime() + 0.25;
		state.stageUntil = GetTime() + 3;
		SendChatMessage("co ?", "WHISPER", nil, sender);
		UnBotSpecSummonMessage(
			"Feral-проверка: у "..sender.." расклад талантов не определяет Bear/Cat; запрашиваю co ?."
		);
		return;
	end
	UnBotDKSpecBalanceProcessWho(whoInfo, message);
end);

UnBotDKSpecBalanceFrame:SetScript("OnUpdate", function()
	if (UnBotBatchSummon and UnBotBatchSummon.refresh) then return; end
	local state = UnBotDKSpecBalance;
	if (state.active and state.registryRefreshJob and not UnBotRegistryRefresh.Guard(state)) then return; end
	if (not state.active or GetTime() < (state.nextTime or 0)) then
		return;
	end
	local now = GetTime();
	if (state.stage == "wait_refresh_stop") then
		if (UnBotSpecSummonIsInGroup(state.currentName)) then
			state.currentOwned = true;
			UnBotRegistryRefresh.Observe(state);
			UnBotDKSpecBalanceBeginCleanup();
		elseif (now >= state.stageUntil) then UnBotDKSpecBalanceBeginCleanup();
		else state.nextTime = now+.25; end
		return;
	end
	if (state.stage=="wait_talent_combat") then
		if (not UnitAffectingCombat("player") and not InCombatLockdown()) then UnBotDKSpecBalanceBeginCleanup();
		elseif (now>=(state.combatCleanupDeadline or 0)) then
			UnBotDKSpecBalanceFinish("Очистка остановлена таймаутом боя; уберите временного бота вручную: "..tostring(state.currentName)..".");
		else state.nextTime=now+1; end
		return;
	end
	if (state.stage=="wait_talent_preset") then
		if (now>=(state.stageUntil or 0)) then UnBotDKSpecBalanceFailCurrent("Нет подтверждения применения шаблона"); end
		return;
	end
	if (state.stage == "next_bot") then
		UnBotDKSpecBalanceStartCurrent();
	elseif (state.stage == "wait_member") then
		if (UnBotSpecSummonIsInGroup(state.currentName)) then
			state.currentOwned = true;
			UnBotDKSpecBalanceSendWho(false);
		elseif (now >= (state.stageUntil or 0)) then
			if ((state.addAttempts or 0) < (state.maxAddAttempts or 1)) then
				state.addAttempts = state.addAttempts + 1;
				state.inviteAttempts = 0;
				SendChatMessage(".playerbot bot add "..state.currentName, "SAY");
				state.stageUntil = now + 6;
				state.nextTime = now + 1;
				UnBotSpecSummonMessage(
					"Выравнивание спеков: повторный вызов "..state.currentName.." "
					..tostring(state.addAttempts).."/"..tostring(state.maxAddAttempts).."."
				);
			else
				UnBotDKSpecBalanceFailCurrent("не ответил и не подтвердился за 6 секунд");
			end
		else
			if ((state.inviteAttempts or 0) < (state.maxInviteAttempts or 1)) then
				state.inviteAttempts = state.inviteAttempts + 1;
				InviteUnit(state.currentName);
				state.nextTime = now + 1;
			else
				state.nextTime = now + 0.25;
			end
		end
	elseif (state.stage == "wait_init_settle") then
		UnBotDKSpecBalanceSendWho(true);
	elseif (state.stage == "retry_init") then
		UnBotDKSpecBalanceSendInit();
	elseif (state.stage == "wait_feral_strategy") then
		if (now >= (state.stageUntil or 0)) then
			if ((state.feralStrategyAttempts or 0) < 2) then
				state.feralStrategyAttempts = (state.feralStrategyAttempts or 0) + 1;
				SendChatMessage("co ?", "WHISPER", nil, state.currentName);
				state.stageUntil = now + 3;
				state.nextTime = now + 0.25;
			else
				state.pendingFeralWhoInfo = nil;
				state.pendingFeralWhoRaw = nil;
				state.pendingFeralWhoStage = nil;
				UnBotDKSpecBalanceFailCurrent("нет однозначного ответа co ? для Bear/Cat");
			end
		else
			state.nextTime = now + 0.25;
		end
	elseif (state.stage == "wait_initial_who" or state.stage == "wait_post_who") then
		if (now >= (state.stageUntil or 0)) then
			if ((state.whoAttempts or 0) < (state.maxWhoAttempts or 2)) then
				state.whoAttempts = state.whoAttempts + 1;
				SendChatMessage("who", "WHISPER", nil, state.currentName);
				state.stageUntil = now + 3;
				state.nextTime = now + 0.25;
				UnBotSpecSummonMessage(
					"Выравнивание спеков: повтор who для "..state.currentName.." "
					..tostring(state.whoAttempts).."/"..tostring(state.maxWhoAttempts).."."
				);
			else
				UnBotDKSpecBalanceFailCurrent("нет корректного ответа who");
			end
		else
			state.nextTime = now + 0.25;
		end
	elseif (state.stage == "wait_leave") then
		if (not UnBotSpecSummonIsInGroup(state.currentName)) then
			if (state.currentOwned) then
				SendChatMessage(".playerbot bot remove "..state.currentName, "SAY");
			end
			if (state.registryRefreshJob) then UnBotRegistryRefresh.Cleaned(state); end
			state.currentName = nil;
			state.currentTask = nil;
			state.currentOwned = false;
			if (state.stopRequested) then
				UnBotDKSpecBalanceFinish(
					state.mode == "audit"
					and "Перепроверка спеков остановлена пользователем."
					or "Выравнивание спеков остановлено пользователем."
				);
			else
				state.stage = "next_bot";
				state.nextTime = now + 1;
			end
		elseif (now >= (state.cleanupUntil or 0)) then
			if (state.currentOwned) then
				SendChatMessage(".playerbot bot remove "..state.currentName, "SAY");
			end
			UnBotDKSpecBalanceFinish(
				"Аудит/балансировка аварийно остановлены: не удалось удалить "..tostring(state.currentName).." из ростера."
			);
		else
			UnBotSpecSummonUninvite(state.currentName);
			if (state.currentOwned and now >= (state.stageUntil or 0)) then
				SendChatMessage(".playerbot bot remove "..state.currentName, "SAY");
			end
			state.nextTime = now + 1;
		end
	end
end);

SLASH_UNBOTSPECCOUNTBALANCE1 = "/ubspecbalance";
SLASH_UNBOTSPECCOUNTBALANCE2 = "/ubbalspec";
SlashCmdList["UNBOTSPECCOUNTBALANCE"] = function(message)
	local command = UnBotSpecSummonNormalize(message);
	if (command == "") then
		if (UnBotSpecAuditShow) then
			UnBotSpecAuditShow();
		else
			UnBotSpecSummonMessage("Окно аудита спеков ещё не загружено.");
		end
	elseif (command == "status" or command == "статус") then
		UnBotDKSpecBalanceStatus();
	elseif (command == "stop" or command == "стоп") then
		UnBotSpecAuditStop();
	elseif (command == "audit" or command == "проверить") then
		UnBotSpecAuditStart(nil, false, 8);
	elseif (string.find(command, "audit ", 1, true) == 1) then
		UnBotSpecAuditStart(string.sub(command, 7), false, 8);
	elseif (string.find(command, "balance ", 1, true) == 1) then
		local arguments = UnBotSpecSummonNormalize(string.sub(command, 9));
		local classToken = string.match(arguments, "^(%S+)");
		local className = UnBotSpecSummonClassAliases[classToken or ""];
		local minimumCount = tonumber(string.match(arguments, "(%d+)%s*$")) or 8;
		if (not className) then
			UnBotSpecSummonMessage("Формат: /ubspecbalance balance <класс> [минимум], например druid 1.");
			return;
		end
		UnBotSpecCountBalanceStart(minimumCount, className);
	else
		UnBotSpecCountBalanceStart(tonumber(command) or 8, nil);
	end
end

SLASH_UNBOTROTATIONFLAG1 = "/ubflag";
SLASH_UNBOTROTATIONFLAG2 = "/ubflags";
SlashCmdList["UNBOTROTATIONFLAG"] = UnBotRegistryFlagCommand;

function UnBotSpecSummon.BuffCycleSnapshot(source)
	if (source and not next(source)) then return source; end
	local snapshot = {};
	for name, value in pairs(source or {}) do snapshot[name] = value; end
	return snapshot;
end

local buffCycleFrame = CreateFrame("Frame", "UnBotBuffCycleFrame");
buffCycleFrame:RegisterEvent("PARTY_MEMBERS_CHANGED");
buffCycleFrame:RegisterEvent("RAID_ROSTER_UPDATE");
buffCycleFrame:RegisterEvent("CHAT_MSG_WHISPER");
buffCycleFrame:RegisterEvent("CHAT_MSG_SYSTEM");
buffCycleFrame:RegisterEvent("PLAYER_ENTERING_WORLD");
buffCycleFrame:RegisterEvent("PLAYER_DEAD");
buffCycleFrame:RegisterEvent("PLAYER_REGEN_DISABLED");
buffCycleFrame:SetScript("OnEvent", function(self, event, arg1, arg2)
	if event=="PLAYER_DEAD" or event=="PLAYER_REGEN_DISABLED" then
		UnBotBuffCycle.Interrupt(event=="PLAYER_DEAD" and "игрок погиб" or "начался бой"); return;
	end
	if event == "PLAYER_ENTERING_WORLD" then UnBotBuffCycleArrivalBlock(nil, false, true); return; end
	if event == "CHAT_MSG_SYSTEM" then
		local text = tostring(arg1 or ""):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "");
		local caster, failure = text:match("^([^%s:]+):%s*(.+)$");
		if (caster and UnBotBuffCycle.RecordCastRefusal(failure, caster)) then
			UnBotBuffDiagnosticRecordCastFailure(arg1, caster);
		end
		local name, result = text:match("^remove:%s*([^%s]+)%s*%-%s*(.-)%.?$");
		local cleanup = name and UnBotBuffCycle.cleanup and UnBotBuffCycle.cleanup[name];
		if cleanup and cleanup.removeSent and (result == "ok" or result == "player is offline") then
			cleanup.untilTime = GetTime();
		end
		if UnBotBuffCycle.active and (UnBotBuffCycle.stage == "summon" or UnBotBuffCycle.stage == "arrival") then
			local lower = text:lower();
			if not lower:match("^%s*%[") and (lower:find("not in your instance", 1, true) or lower:find("not in your dungeon", 1, true)
				or lower:find("не находится в вашем подземелье", 1, true)) then
				for index, caster in pairs(UnBotBuffCycle.assignments or {}) do
					if UnBotBuffCycleMessageHasName(lower, caster) and not UnBotBuffCycleCasterReady(caster) then
						UnBotBuffCycle.arrivalNextSummonAt[caster] = GetTime();
						UnBotBuffCycle.arrivalAttempts[caster] = 2;
						if not UnitAffectingCombat("player") then UnBotBuffCycleReplaceAbsentCaster(index, caster, GetTime()); end
						return;
					end
				end
			end
		end
	end
	if (event == "CHAT_MSG_WHISPER") then
		if (
			UnBotSquadConfig
			and UnBotSquadConfig.lastBuffDiagnostic
			and UnBotSquadConfig.lastBuffDiagnostic.active
			and arg2
			and (
				UnBotBuffCycle.summoned[arg2]
				or UnBotBuffCycle.cleanup[arg2]
				or UnBotBuffCycle.requestedByName[arg2]
				or UnBotBuffCycle.assignedNames[arg2]
				or UnBotBuffCycle.registryInvites[arg2]
			)
		) then
			UnBotBuffDiagnosticAdd("reply_whisper", tostring(arg2 or "unknown")..": "..tostring(arg1 or ""));
		end
		UnBotBuffDiagnosticRecordCastFailure(arg1, arg2);
		UnBotBuffCycle.RecordCastRefusal(arg1, arg2);
		if (UnBotBuffCycleRecordReagentFailure(arg1, arg2)) then
			return;
		end
		if (UnBotBuffCycle.log and arg2 and (UnBotBuffCycle.summoned[arg2] or UnBotBuffCycle.cleanup[arg2])) then
			UnBotSpecSummonMessage("Buff cycle result <- "..tostring(arg2)..": "..tostring(arg1));
		end
		return;
	end
	if (event == "CHAT_MSG_SYSTEM" and UnBotSquadConfig and UnBotSquadConfig.lastBuffDiagnostic and UnBotSquadConfig.lastBuffDiagnostic.active) then
		UnBotBuffDiagnosticAdd("system", arg1);
	end
	if (
		event == "CHAT_MSG_SYSTEM"
		and UnBotBuffCycle.active
		and UnBotBuffCycle.stage == "summon"
	) then
		local text = UnBotSpecSummonNormalize(arg1);
		if text:match("^%s*%[") then return; end
		local wrongInstance = string.find(text, "не находится в вашем подземелье", 1, true)
			or string.find(text, "not in your instance", 1, true)
			or string.find(text, "not in your dungeon", 1, true);
		local missingOnRealm = string.find(text, "player does not exist", 1, true)
			or string.find(text, "player not found", 1, true)
			or string.find(text, "no player named", 1, true)
			or string.find(text, "игрок не существует", 1, true)
			or string.find(text, "игрок не найден", 1, true);
		local alreadyActive = string.find(text, "player already logged in", 1, true)
			or string.find(text, "already logged in", 1, true)
			or string.find(text, "already in group", 1, true)
			or string.find(text, "уже состоит в группе", 1, true)
			or string.find(text, "уже в игре", 1, true);
		if (
			alreadyActive
			or wrongInstance
			or missingOnRealm
		) then
			for name in pairs(UnBotBuffCycle.registryInvites or {}) do
				if (
					UnBotBuffCycleMessageHasName(text, name)
					and not UnBotSpecSummonIsInGroup(name)
				) then
					if (alreadyActive) then
						UnBotBuffCycleQuarantineForHour(
							name,
							"бафф-цикл: сервер подтвердил, что бот уже залогинен у другого игрока"
						);
					elseif (wrongInstance) then
						UnBotBuffCycleArrivalBlock(name, true);
					end
					UnBotSpecSummonMessage(
						"Buff registry: "..tostring(name)
						..(missingOnRealm
							and " не найден на текущем реалме; возможно, запись устарела или относится к другому пулу"
							or wrongInstance
							and " временно находится в другой копии подземелья"
							or " уже занят другим игроком или группой")
						..(alreadyActive
							and "; помещён в карантин на час, повторные попытки сразу остановлены."
							or wrongInstance and "; помещён в карантин, повторные попытки остановлены."
							or "; пропускаю только в текущем запуске без карантина.")
					);
					UnBotBuffCycle.registryInvites[name] = nil;
					UnBotBuffCycle.requestedByName[name] = nil;
					return;
				end
			end
		end
		return;
	end
	if (UnBotBuffCycle.active) then
		UnBotBuffDiagnosticRoster(event);
		UnBotBuffCycleAssignMembers();
	end
end);

buffCycleFrame:SetScript("OnUpdate", function()
	local now = GetTime();
	if UnBotBuffCycle.active and UnitIsDeadOrGhost and UnitIsDeadOrGhost("player") then
		UnBotBuffCycle.Interrupt("игрок погиб");
	end
	if (UnitAffectingCombat and UnitAffectingCombat("player")) or (InCombatLockdown and InCombatLockdown()) then
		UnBotBuffCycle.Interrupt("начался бой");
		for _,cleanup in pairs(UnBotBuffCycle.cleanup or {}) do cleanup.untilTime=now+30; cleanup.nextTime=now+0.5; end
		return;
	end
	if (UnBotBuffCycle.active and IsMounted and IsMounted()) then
		UnBotBuffCycleStop(
			"Бафф-цикл остановлен: вы сели на маунта. Временные бафферы удаляются; спешьтесь и запустите цикл заново.",
			true
		);
		return;
	end
	if (
		UnBotBuffCycle.active
		and (
			UnBotBuffCycle.diagnosticLastStage ~= UnBotBuffCycle.stage
			or UnBotBuffCycle.diagnosticLastPhase ~= UnBotBuffCycle.phaseIndex
		)
	) then
		UnBotBuffCycle.diagnosticLastStage = UnBotBuffCycle.stage;
		UnBotBuffCycle.diagnosticLastPhase = UnBotBuffCycle.phaseIndex;
		UnBotBuffDiagnosticAdd(
			"state",
			"phase="..tostring(UnBotBuffCycle.phaseIndex).."; stage="..tostring(UnBotBuffCycle.stage)
		);
	end
	for name, invite in pairs(UnBotSpecSummon.BuffCycleSnapshot(UnBotBuffCycle.registryInvites)) do
		local assignmentIndex = UnBotBuffCycle.requestedByName[name];
		if (
			not UnBotBuffCycle.active
			or (UnBotBuffCycle.stage ~= "summon" and UnBotBuffCycle.stage ~= "arrival_cleanup")
			or not assignmentIndex
			or UnBotBuffCycle.assignments[assignmentIndex]
		) then
			UnBotBuffCycle.registryInvites[name] = nil;
		elseif (now >= (invite.nextTime or 0)) then
			if (UnitAffectingCombat and UnitAffectingCombat("player")) then
				invite.nextTime = now + 1;
				if (not invite.waitWithoutQuarantine) then
					invite.untilTime = math.max(invite.untilTime or 0, now + 2);
				end
			elseif (
				now >= (invite.untilTime or 0)
			) then
				if (invite.waitWithoutQuarantine) then
					UnBotSpecSummonMessage(
						"Бафф-цикл: "..tostring(name).." не вошёл после двух add с интервалом 3 секунды; следующий кандидат."
					);
				else
					UnBotBuffCycleQuarantineForHour(
						name,
						"не вошёл в группу после add и ограниченных приглашений"
					);
				end
				UnBotBuffCycle.registryInvites[name] = nil;
				UnBotBuffCycle.requestedByName[name] = nil;
			elseif (UnBotSpecSummonIsInGroup(name)) then
				-- Membership may arrive before the connected flag; do not invite twice.
				invite.nextTime = now + 0.25;
			elseif (invite.attempts or 0) >= (tonumber(invite.maxAttempts) or 4) then
				invite.nextTime = invite.untilTime or (now + 1);
			else
				invite.attempts = (invite.attempts or 0) + 1;
				if (
					(invite.waitWithoutQuarantine and invite.attempts == 1)
					or (not invite.waitWithoutQuarantine and invite.attempts == 3)
				) then
					UnBotBuffCycleSendSay(".playerbot bot add "..name);
				end
				InviteUnit(name);
				invite.nextTime = now + (tonumber(invite.retryInterval) or 2);
				if (invite.attempts == 1) then
					UnBotSpecSummonMessage(
						"Buff registry: "..name
						.." не вошёл автоматически после add; отправляю отдельное приглашение в группу"
						..(invite.waitWithoutQuarantine
							and " и жду ответ сервера до 3 минут без карантина."
							or ".")
					);
				end
			end
		end
	end
	for name, expiresAt in pairs(UnBotSpecSummon.BuffCycleSnapshot(UnBotBuffCycle.lateRegistryNames)) do
		local isCurrent = false;
		if (
			UnBotSpecSummon.CleanupProtected(name)
		) then
			isCurrent = true;
		end
		if (
			UnBotBuffCycle.keptRegistryNames[name]
			and UnBotSpecSummonIsInGroup(name)
		) then
			isCurrent = true;
		elseif (
			UnBotBuffCycle.keptRegistryNames[name]
			and not UnBotSpecSummonIsInGroup(name)
		) then
			UnBotBuffCycle.keptRegistryNames[name] = nil;
		end
		local requestedIndex = UnBotBuffCycle.requestedByName[name];
		if (
			UnBotBuffCycle.active
			and requestedIndex
			and not UnBotBuffCycle.assignments[requestedIndex]
			and UnBotBuffCycle.stage == "summon"
		) then
			isCurrent = true;
		end
		if (UnBotBuffCycle.active and UnBotBuffCycle.stage ~= "wait_cleanup") then
			for _, assignedName in pairs(UnBotBuffCycle.assignments or {}) do
				if (assignedName == name) then
					isCurrent = true;
					break
				end
			end
		end
		if (
			UnBotSpecSummonIsInGroup(name)
			and not isCurrent
			and not (UnBotBuffCycle.cleanup and UnBotBuffCycle.cleanup[name])
		) then
			UnBotSpecSummonUninvite(name);
			UnBotBuffCycle.cleanup[name] = {
				removeSent = false,
				nextTime = now + 0.5,
				untilTime = now + 30,
			};
			UnBotSpecSummonMessage("Buff registry: caught delayed bot "..name.."; removing it safely.");
		elseif (
			now >= (expiresAt or 0)
			and not UnBotSpecSummonIsInGroup(name)
			and not (UnBotBuffCycle.cleanup and UnBotBuffCycle.cleanup[name])
		) then
			UnBotBuffCycle.lateRegistryNames[name] = nil;
		end
	end
	for name, cleanup in pairs(UnBotSpecSummon.BuffCycleSnapshot(UnBotBuffCycle.cleanup)) do
		if (UnBotSpecSummon.CleanupProtected(name)) then
			UnBotSpecSummon.CancelStaleCleanup(name);
		elseif (cleanup.boundedArrival) then
			if (UnitAffectingCombat and UnitAffectingCombat("player")) then
				cleanup.untilTime = now + 15;
			elseif (UnBotSpecSummonIsInGroup(name)) then
				if (now >= cleanup.untilTime) then
					UnBotBuffCycle.cleanup[name] = nil;
					UnBotBuffCycle.lateRegistryNames[name] = nil;
					UnBotBuffCycle.summoned[name] = nil;
					if (UnBotBuffCycle.active) then
						UnBotBuffCycleStop("Бафф-цикл остановлен: не удалось освободить место после "..name..". Удалите его из группы вручную.", true);
					end
				elseif (now >= cleanup.nextTime and cleanup.attempts < 3) then
					UnBotSpecSummonUninvite(name);
					cleanup.attempts = cleanup.attempts + 1;
					cleanup.nextTime = now + 5;
				end
			elseif (not cleanup.removeSent) then
				if not (UnBotBatchSummon and UnBotBatchSummon.QueueBuff(".playerbot bot remove "..name)) then SendChatMessage(".playerbot bot remove "..name, "SAY"); end
				cleanup.removeSent = true;
				cleanup.untilTime = now + 3;
			elseif (now >= cleanup.untilTime) then
				UnBotBuffCycle.cleanup[name] = nil;
				UnBotBuffCycle.lateRegistryNames[name] = nil;
				UnBotBuffCycle.summoned[name] = nil;
			end
		elseif (
			UnBotBuffCycle.active
			and UnBotBuffCycle.originalMembers
			and UnBotBuffCycle.originalMembers[name]
		) then
			UnBotBuffCycle.cleanup[name] = nil;
			UnBotBuffCycle.lateRegistryNames[name] = nil;
		elseif (UnBotSpecSummonIsInGroup(name)) then
			if (now >= cleanup.untilTime) then
				UnBotBuffCycle.cleanup[name] = nil;
				UnBotBuffCycle.lateRegistryNames[name] = nil;
				UnBotBuffCycle.summoned[name] = nil;
				if UnBotBuffCycle.active then UnBotBuffCycleStop("Бафф-цикл остановлен: не удалось исключить "..name.." за 30 секунд. Удалите его вручную.", false); end
			elseif (now >= cleanup.nextTime and (cleanup.attempts or 0) < 3) then
				UnBotSpecSummonUninvite(name);
				cleanup.attempts = (cleanup.attempts or 0) + 1;
				cleanup.nextTime = now + 5;
			end
		elseif (not cleanup.removeSent) then
			if not (UnBotBatchSummon and UnBotBatchSummon.QueueBuff(".playerbot bot remove "..name)) then SendChatMessage(".playerbot bot remove "..name, "SAY"); end
			cleanup.removeSent = true;
			cleanup.untilTime = now + 3;
		elseif (now >= cleanup.untilTime) then
			UnBotBuffCycle.cleanup[name] = nil;
			UnBotBuffCycle.lateRegistryNames[name] = nil;
		end
	end
	UnBotBuffCycle.restoreReserveAt = nil; -- Offline resurrection reserve is manual and obsolete.
	if (UnBotBuffCycle.active) then
		UnBotBuffCycleProgressNotice(false, false);
	end

	if (not UnBotBuffCycle.active or now < (UnBotBuffCycle.nextTime or 0)) then
		return;
	end

	local phase = UnBotBuffCycleCurrentPhase();
	if (not phase) then
		UnBotBuffCycleStop("Buff cycle finished.", true);
		return;
	end
	UnBotBuffCycleAssignMembers();
	if UnBotBuffCycle.raidWaveMode and (UnBotBuffCycle.stage=="summon" or UnBotBuffCycle.stage=="arrival") then
		UnBotBuffCycle.CastReady(now,true);
	end

	if (UnBotBuffCycle.stage == "summon" and UnBotBuffCycleArrivalUpdate(now, true)) then
		return;
	end
	if (UnBotBuffCycle.stage == "arrival_cleanup") then
		local name = UnBotBuffCycle.arrivalReplacementName;
		if (name and UnBotBuffCycle.cleanup[name]) then
			UnBotBuffCycle.nextTime = now + 0.25;
			return;
		end
		UnBotBuffCycle.arrivalReplacementName = nil;
		UnBotBuffCycle.stage = "summon";
		UnBotBuffCycle.stageUntil = now + 10;
	end

	if (UnBotBuffCycle.stage == "summon") then
		if (UnBotBuffCycle.summonIndex <= #phase.bots) then
			local assignmentIndex = UnBotBuffCycle.summonIndex;
			local bot = phase.bots[assignmentIndex];
			if (
				not UnBotBuffCycle.assignments[assignmentIndex]
				and (not UnBotBuffCycle.raidWaveMode or not UnBotBuffCycleHasPendingRegistryInvites(assignmentIndex))
				and (UnBotBuffCycle.registryAttempts[assignmentIndex] or 0)
					< UnBotBuffCycleRegistryAttemptLimit(assignmentIndex)
			) then
				if (
					(UnBotBuffCycle.mode == "raid" or UnBotBuffCycle.raidWaveMode)
					and UnBotBuffCycleRaidFreeSlots(UnBotBuffCycle.raidWaveMode) <= 0
				) then
					if (not UnBotBuffCycle.capacityWaitLogged) then
						UnBotBuffCycle.capacityWaitLogged = true;
						UnBotSpecSummonMessage(
							"Баф рейда: свободных мест до лимита "
							..tostring(UnBotBuffCycle.raidMemberLimit).." нет; "
							.."новые баферы не вызываются."
						);
					end
					if (
						(UnBotBuffCycle.raidTemporaryCapacity or 0) <= 0
						or now >= UnBotBuffCycle.stageUntil
					) then
						UnBotSpecSummonMessage(
							"Баф рейда: продолжаем фазу только с баферами, уже находящимися в составе."
						);
						UnBotBuffCycleBeginArrivalWait(UnBotBuffCycle.replacementMissingOnly == true);
					else
						UnBotBuffCycle.nextTime = now + 0.5;
					end
					return;
				end
				local name = UnBotBuffCycleNextRegistryCandidate(assignmentIndex);
				if (name) then
					if (
						(UnBotBuffCycle.mode == "raid" or UnBotBuffCycle.raidWaveMode)
						and GetNumPartyMembers() >= 4
						and (not GetNumRaidMembers() or GetNumRaidMembers() == 0)
						and not UnBotFastSoloIsPartyInstance()
						and not (
							UnBotMythicPlusBuffIsRunning
							and UnBotMythicPlusBuffIsRunning()
						)
					) then
						ConvertToRaid();
					end
					UnBotBuffCycleSendSay(".playerbot bot add "..name);
					-- A large wave can take longer than the old fixed 10-second phase.
					if (UnBotBuffCycle.raidWaveMode) then
						UnBotBuffCycle.stageUntil = math.max(UnBotBuffCycle.stageUntil or 0, now + 10);
					end
					UnBotSpecSummonMessage(
						"Buff registry summon: "..bot.label.." -> "..name.." ("
						..bot.className.." "..bot.spec..", candidate "
						..tostring(UnBotBuffCycle.registryAttempts[assignmentIndex]).."/"
						..tostring(UnBotBuffCycleRegistryAttemptLimit(assignmentIndex))..")."
					);
				end
			end
			UnBotBuffCycle.summonIndex = UnBotBuffCycle.summonIndex + 1;
			UnBotBuffCycle.nextTime = now + (UnBotBatchSummon and 0.02 or 0.7);
		elseif (UnBotBuffCycleAllAssigned()) then
			UnBotBuffCycleBeginArrivalWait(UnBotBuffCycle.replacementMissingOnly == true);
		elseif (now >= UnBotBuffCycle.stageUntil or not UnBotBuffCycleHasPendingRegistryInvites()) then
			if UnBotBuffCycleHasPendingRegistryInvites() then
				UnBotBuffCycle.nextTime=now+0.25;
			elseif UnBotBuffCycleCanRetryRegistry() then
				UnBotBuffCycle.summonPass=UnBotBuffCycle.summonPass+1;
				UnBotBuffCycle.summonIndex=1;
				UnBotBuffCycle.stageUntil=now+7;
				UnBotBuffCycle.nextTime=now;
			else
				for index=1,#phase.bots do UnBotBuffCycle.MarkUnavailable(index); end
				UnBotBuffCycleBeginArrivalWait(UnBotBuffCycle.replacementMissingOnly==true);
			end
		else
			UnBotBuffCycle.nextTime = now + 0.25;
		end
	elseif (UnBotBuffCycle.stage == "arrival") then
		UnBotBuffCycleArrivalUpdate(now);
	elseif (UnBotBuffCycle.stage == "reset") then
		if UnBotBuffCycle.raidWaveMode then UnBotBuffCycle.setupIndex=#phase.bots+1; end
		if (UnBotBuffCycle.setupIndex <= #phase.bots) then
			local name = UnBotBuffCycle.assignments[UnBotBuffCycle.setupIndex];
			local bot = phase.bots[UnBotBuffCycle.setupIndex];
			if (name) then
				UnBotBuffCycleSendWhisper(name, "reset botAI");
				if (
					bot and bot.className == "warlock"
					and not (UnBotBuffCycle.originalMembers and UnBotBuffCycle.originalMembers[name])
				) then
					UnBotBuffCycleSendWhisper(name, "nc -ss master,-ss self,-ss tank,-ss healer");
				end
			end
			if (UnBotBuffCycle.replacementSetupOnly) then
				UnBotBuffCycle.replacementSetupOnly = nil;
				UnBotBuffCycle.setupIndex = #phase.bots + 1;
			else
				UnBotBuffCycle.setupIndex = UnBotBuffCycle.setupIndex + 1;
			end
			UnBotBuffCycle.nextTime = now + 0.4;
		else
			UnBotBuffCycle.stageUntil = now + (UnBotBuffCycle.mode == "raid" and 90 or 35);
			UnBotBuffCycleReportPlayerActions();
			local missingOnly = UnBotBuffCycle.replacementMissingOnly == true
				or UnBotBuffCycle.arrivalResumeMissingOnly == true;
			UnBotBuffCycle.replacementMissingOnly = nil;
			UnBotBuffCycle.arrivalResumeMissingOnly = false;
			UnBotBuffCycleStartCasting(missingOnly);
		end
	elseif (UnBotBuffCycle.stage == "cast") then
		UnBotBuffCycle.CastReady(now,false);
	elseif (UnBotBuffCycle.stage == "verify") then
		local requiredMissing = UnBotBuffCycleMissingBuffs(true);
		local allMissing = UnBotBuffCycleMissingBuffs(false);
		UnBotBuffDiagnosticVerify(requiredMissing, allMissing);
		if (
			UnBotBuffCycleMissingCastersNeedArrival(allMissing)
		) then
			return;
		end
		local maxCastAttempts = math.max(1, tonumber(UnBotBuffCycle.maxCastAttempts) or 2);
		local completedAttempts = (tonumber(UnBotBuffCycle.retryRound) or 0) + 1;
		if (#requiredMissing == 0 and (#allMissing == 0 or completedAttempts >= maxCastAttempts)) then
			if (#allMissing > 0) then
				local optionalLabels = {};
				local optionalSeen = {};
				for _, missing in ipairs(allMissing) do
					if (not optionalSeen[missing.buff.label]) then
						optionalSeen[missing.buff.label] = true;
						table.insert(optionalLabels, missing.buff.label);
					end
				end
				UnBotSpecSummonMessage("Buff cycle: "..phase.label.." core confirmed; optional unavailable: "..table.concat(optionalLabels, ", ")..".");
			else
				UnBotSpecSummonMessage("Buff cycle: "..phase.label.." confirmed.");
			end
			UnBotBuffCycleBeginCleanup();
		elseif (now < UnBotBuffCycle.stageUntil and completedAttempts < maxCastAttempts) then
			UnBotBuffCycle.retryRound = UnBotBuffCycle.retryRound + 1;
			UnBotSpecSummonMessage(
				"Buff cycle: retrying "..tostring(#allMissing)
				.." missing buffs (attempt "..tostring(completedAttempts + 1)
				.."/"..tostring(maxCastAttempts)..")."
			);
			UnBotBuffCycleStartCasting(true);
		elseif (UnBotBuffCycleTryReplaceSanctuaryCaster(requiredMissing)) then
			return;
		else
			UnBotBuffCycleQuarantineMissingCasters(requiredMissing);
			local labels = {};
			local labelSeen = {};
			for _, missing in ipairs(allMissing) do
				if (not labelSeen[missing.buff.label]) then
					labelSeen[missing.buff.label] = true;
					table.insert(labels, missing.buff.label);
				end
			end
			UnBotSpecSummonMessage(
				"Buff cycle: "
				..(completedAttempts >= maxCastAttempts
					and ("maximum "..tostring(maxCastAttempts).." attempts reached")
					or "phase timeout")
				.."; missing: "..(#labels > 0 and table.concat(labels, ", ") or "none").."."
			);
			UnBotBuffCycleBeginCleanup();
		end
	elseif (UnBotBuffCycle.stage == "wait_cleanup") then
		if (UnBotBuffCyclePhaseMembersGone() and not next(UnBotBuffCycle.cleanup)) then
			UnBotBuffCycle.phaseIndex = UnBotBuffCycle.phaseIndex + 1;
			UnBotBuffCycleStartPhase();
		elseif (now >= UnBotBuffCycle.stageUntil + 20) then
			UnBotBuffCycleStop("Бафф-цикл остановлен: очистка временных бафферов не завершена. Исходный состав сохранён.", false);
		else
			-- Only the bounded cleanup queue sends exclusion requests.
			UnBotBuffCycle.nextTime = now + 0.75;
		end
	end
end);

