function UnBotSquadReserveCount(value, legacyValue)
	local count = tonumber(value);
	if (count == nil) then
		count = legacyValue and 1 or 0;
	end
	return math.max(0, math.min(3, math.floor(count)));
end

function UnBotSquadBuilder.NormalizeSlots(slots)
	local normalized = {};
	local normalByKey = {};
	local altByKey = {};
	local function AddNormal(source, count)
		count = math.max(1, math.min(39, math.floor(tonumber(count) or 1)));
		local key = tostring(source.className).."\031"..tostring(source.specKey);
		local existing = not source.reserveOnly and normalByKey[key] or nil;
		if (existing) then
			existing.count = math.min(39, (tonumber(existing.count) or 1) + count);
			return;
		end
		if (#normalized >= UnBotSquadBuilderMaxSlots) then
			return;
		end
		local target = source;
		target.accountAltName = nil;
		target.count = source.reserveOnly and 0 or count;
		table.insert(normalized, target);
		if (not source.reserveOnly) then
			normalByKey[key] = target;
		end
	end

	for _, slot in ipairs(type(slots) == "table" and slots or {}) do
		if (
			type(slot) == "table"
			and type(slot.className) == "string"
			and type(slot.specKey) == "string"
		) then
			if (slot.accountAltName) then
				local altKey = UnBotAccountAlts and UnBotAccountAlts.Key
					and UnBotAccountAlts.Key(slot.accountAltName)
					or string.lower(tostring(slot.accountAltName));
				if (not altByKey[altKey] and #normalized < UnBotSquadBuilderMaxSlots) then
					slot.count = 1;
					slot.reserveOnly = nil;
					altByKey[altKey] = slot;
					table.insert(normalized, slot);
				end
			else
				AddNormal(slot, slot.count);
			end
		end
	end
	return normalized;
end

local function UnBotSquadBuilderEnsureConfig(displayOnly)
	-- Rendering must not copy every preset or rerun migrations.
	if (displayOnly and UnBotSquadBuilder and UnBotSquadBuilder.configReady
		and UnBotSquadConfig and UnBotSquadBuilder.configSource == UnBotSquadConfig
		and UnBotSquadConfig.activeSquadBuilderCharacterKey == UnBotSquadBuilderCharacterKey()) then return; end
	if (not UnBotSquadConfig) then
		UnBotSquadConfig = {};
	end
	UnBotSquadConfig.slots = UnBotSquadConfig.slots or {};
	UnBotSquadConfig.presets = UnBotSquadConfig.presets or {};
	if (UnBotSquadBuilderAttachCharacterStorage) then
		UnBotSquadBuilderAttachCharacterStorage();
	end
	for _, slot in ipairs(UnBotSquadConfig.slots) do
		if (slot.accountAltName and (tonumber(slot.count) or 1) ~= 1) then
			UnBotSquadConfig.slots = UnBotSquadBuilder.NormalizeSlots(UnBotSquadConfig.slots);
			break
		end
	end
	UnBotSquadConfig.bossPresets = UnBotSquadConfig.bossPresets or {};
	UnBotSquadConfig.bossPresetBackups = UnBotSquadConfig.bossPresetBackups or {};
	UnBotSquadConfig.resurrectionReserveCount = 0;
	UnBotSquadConfig.includeResurrectionReserve = false;
	UnBotSquadConfig.buffRaidAfterSummon =
		UnBotSquadConfig.buffRaidAfterSummon and true or false;
	if (UnBotSquadConfig.forceMasterLootAfterSummon == nil) then
		UnBotSquadConfig.forceMasterLootAfterSummon = true;
	else
		UnBotSquadConfig.forceMasterLootAfterSummon =
			UnBotSquadConfig.forceMasterLootAfterSummon and true or false;
	end
	UnBotSquadConfig.recordFullCombatLog =
		UnBotSquadConfig.recordFullCombatLog and true or false;
	UnBotBuffProfileEnsure();
	if (UnBotBossPresetSeedDefaults) then
		UnBotBossPresetSeedDefaults();
	end
	if (UnBotBossPresetMigrateStorage) then
		UnBotBossPresetMigrateStorage();
	end
	if (UnBotSquadBuilder) then
		UnBotSquadBuilder.configReady = true; UnBotSquadBuilder.configSource = UnBotSquadConfig;
	end
end

function UnBotSquadCombatLogApply(enabled, announce)
	enabled = enabled and true or false;
	if (type(LoggingCombat) ~= "function") then
		if (announce) then
			UnBotSpecSummonMessage(
				"Полный combat log недоступен: клиент не предоставляет LoggingCombat()."
			);
		end
		return false;
	end
	local ok, errorText = pcall(LoggingCombat, enabled);
	if (not ok) then
		UnBotSpecSummonMessage(
			"Не удалось "..(enabled and "включить" or "выключить")
			.." полный combat log: "..tostring(errorText or "неизвестная ошибка").."."
		);
		return false;
	end
	if (announce) then
		if (enabled) then
			UnBotSpecSummonMessage(
				"Полный combat log включён: Logs\\WoWCombatLog.txt. Запись продолжится до снятия галочки."
			);
		else
			UnBotSpecSummonMessage("Полный combat log выключен.");
		end
	end
	return true;
end

local function UnBotSquadBuilderBotCount(displayOnly)
	UnBotSquadBuilderEnsureConfig(displayOnly);
	local count = 0;
	for i = 1, #UnBotSquadConfig.slots, 1 do
		if (not UnBotSquadConfig.slots[i].reserveOnly) then
			count = count + (tonumber(UnBotSquadConfig.slots[i].count) or 0);
		end
	end
	return count;
end

local function UnBotSquadBuilderCopySlots(source, excludedAccountAltName)
	local copy = {};
	for i = 1, #(source or {}), 1 do
		local slot = source[i];
		if (
			type(slot) == "table"
			and type(slot.className) == "string"
			and type(slot.specKey) == "string"
			and not slot.reserveOnly
			and not (
				slot.accountAltName
				and excludedAccountAltName
				and UnBotSpecSummonNormalize(slot.accountAltName)
					== UnBotSpecSummonNormalize(excludedAccountAltName)
			)
		) then
			table.insert(copy, {
				className = slot.className,
				specKey = slot.specKey,
				label = slot.label,
				count = math.max(1, math.min(39, math.floor(tonumber(slot.count) or 1))),
				accountAltName = slot.accountAltName,
			});
		end
	end
	return UnBotSquadBuilder.NormalizeSlots(copy);
end

function UnBotSquadBuilderCharacterKey()
	local realmName = GetRealmName and GetRealmName() or "unknown-realm";
	local playerName = UnitName("player") or "unknown-character";
	local realmKey = UnBotSpecSummonNormalize(realmName);
	local playerKey = UnBotSpecSummonNormalize(playerName);
	if (realmKey == "") then realmKey = "unknown-realm"; end
	if (playerKey == "") then playerKey = "unknown-character"; end
	return realmKey.."|"..playerKey;
end

function UnBotSquadBuilderCopyCharacterSlots(source, excludedAccountAltName)
	local copy = {};
	for _, slot in ipairs(type(source) == "table" and source or {}) do
		if (
			type(slot) == "table"
			and type(slot.className) == "string"
			and type(slot.specKey) == "string"
			and not (
				slot.accountAltName
				and excludedAccountAltName
				and UnBotSpecSummonNormalize(slot.accountAltName)
					== UnBotSpecSummonNormalize(excludedAccountAltName)
			)
		) then
			local target = {};
			for key, value in pairs(slot) do
				target[key] = value;
			end
			table.insert(copy, target);
		end
	end
	return UnBotSquadBuilder.NormalizeSlots(copy);
end

function UnBotSquadBuilderCopyCharacterPresets(source, excludedAccountAltName)
	local copy = {};
	for index, preset in pairs(type(source) == "table" and source or {}) do
		if (type(preset) == "table") then
			local target = {};
			for key, value in pairs(preset) do
				if (key ~= "slots") then
					target[key] = value;
				end
			end
			target.slots = UnBotSquadBuilderCopySlots(
				preset.slots,
				excludedAccountAltName
			);
			if (#target.slots > 0) then
				copy[index] = target;
			end
		else
			copy[index] = preset;
		end
	end
	return copy;
end

function UnBotSquadBuilderAttachCharacterStorage()
	UnBotSquadConfig = UnBotSquadConfig or {};
	local playerName = UnitName("player") or "unknown-character";
	local contextKey = UnBotSquadBuilderCharacterKey();
	UnBotSquadConfig.squadBuilderByCharacter =
		type(UnBotSquadConfig.squadBuilderByCharacter) == "table"
		and UnBotSquadConfig.squadBuilderByCharacter or {};

	if ((tonumber(UnBotSquadConfig.squadBuilderCharacterStorageVersion) or 0) < 1) then
		UnBotSquadConfig.legacySquadBuilderTemplate = {
			slots = UnBotSquadBuilderCopyCharacterSlots(UnBotSquadConfig.slots),
			presets = UnBotSquadBuilderCopyCharacterPresets(UnBotSquadConfig.presets),
			resurrectionReserveCount = UnBotSquadReserveCount(
				UnBotSquadConfig.resurrectionReserveCount,
				UnBotSquadConfig.includeResurrectionReserve
			),
			migratedAt = date and date("%Y-%m-%d %H:%M:%S") or nil,
		};
		UnBotSquadConfig.squadBuilderCharacterStorageVersion = 1;
	end

	local storage = UnBotSquadConfig.squadBuilderByCharacter;
	local active = storage[contextKey];
	if (
		UnBotSquadConfig.activeSquadBuilderCharacterKey == contextKey
		and type(active) == "table"
	) then
		active.slots = type(UnBotSquadConfig.slots) == "table"
			and UnBotSquadConfig.slots or active.slots;
		active.presets = type(UnBotSquadConfig.presets) == "table"
			and UnBotSquadConfig.presets or active.presets;
		active.resurrectionReserveCount = UnBotSquadReserveCount(
			UnBotSquadConfig.resurrectionReserveCount,
			UnBotSquadConfig.includeResurrectionReserve
		);
	end
	if (type(active) ~= "table") then
		local template = type(UnBotSquadConfig.legacySquadBuilderTemplate) == "table"
			and UnBotSquadConfig.legacySquadBuilderTemplate or {};
		active = {
			slots = UnBotSquadBuilderCopyCharacterSlots(template.slots, playerName),
			presets = UnBotSquadBuilderCopyCharacterPresets(template.presets, playerName),
			resurrectionReserveCount = UnBotSquadReserveCount(
				template.resurrectionReserveCount
			),
			characterName = playerName,
			realmName = GetRealmName and GetRealmName() or nil,
			createdAt = date and date("%Y-%m-%d %H:%M:%S") or nil,
		};
		storage[contextKey] = active;
	end

	active.slots = UnBotSquadBuilderCopyCharacterSlots(active.slots, playerName);
	active.presets = UnBotSquadBuilderCopyCharacterPresets(active.presets, playerName);
	active.characterName = playerName;
	active.realmName = GetRealmName and GetRealmName() or active.realmName;
	active.resurrectionReserveCount = 0;
	UnBotSquadConfig.slots = active.slots;
	UnBotSquadConfig.presets = active.presets;
	UnBotSquadConfig.resurrectionReserveCount = active.resurrectionReserveCount;
	UnBotSquadConfig.includeResurrectionReserve = false;
	UnBotSquadConfig.activeSquadBuilderCharacterKey = contextKey;
	return active;
end

function UnBotSquadBuilderSetSlots(slots)
	local active = UnBotSquadBuilderAttachCharacterStorage();
	active.slots = UnBotSquadBuilderCopyCharacterSlots(slots, UnitName("player"));
	UnBotSquadConfig.slots = active.slots;
	return active.slots;
end

function UnBotBossPresetRequirements(preset)
	if (type(preset) ~= "table") then
		return nil;
	end
	if (type(preset.requirements) == "table" and #preset.requirements > 0) then
		return preset.requirements;
	end
	if (type(preset.slots) == "table" and #preset.slots > 0) then
		return preset.slots;
	end
	return nil;
end

function UnBotBossPresetMigrateStorage()
	for _, presetGroups in ipairs({
		UnBotSquadConfig.bossPresets or {},
		UnBotSquadConfig.bossPresetBackups or {},
	}) do
		for _, modes in pairs(presetGroups) do
			if (type(modes) == "table") then
				for _, preset in pairs(modes) do
					local requirements = UnBotBossPresetRequirements(preset);
					if (requirements) then
						if (type(preset.requirements) ~= "table" or #preset.requirements == 0) then
							preset.requirements = UnBotSquadBuilderCopySlots(requirements);
						end
						local hasAccountAlt = false;
						for _, slot in ipairs(preset.requirements or requirements) do
							if (slot.accountAltName) then hasAccountAlt = true; break end
						end
						preset.storageMode = hasAccountAlt and "class-spec+account-alt" or "class-spec";
						preset.schemaVersion = hasAccountAlt and 3 or 2;
					end
				end
			end
		end
	end
end

local function UnBotSquadBuilderSlotsCount(slots)
	local count = 0;
	for i = 1, #(slots or {}), 1 do
		if (not slots[i].reserveOnly) then
			count = count + (tonumber(slots[i].count) or 0);
		end
	end
	return count;
end

local function UnBotSquadBuilderPresetExists(index)
	local preset = UnBotSquadConfig.presets and UnBotSquadConfig.presets[index];
	return type(preset) == "table" and type(preset.slots) == "table" and #preset.slots > 0;
end

