function UnBotBossPresetModesForBoss(instanceType, bossKey, instanceInfo)
	if (instanceType == "party") then
		return UnBotBossPresetDungeonModes;
	end
	if (bossKey == "temple_of_ahn_qiraj__the_twin_emperors") then
		return { UnBotBossPresetTwinsPlayerMode };
	end
	if (instanceInfo and instanceInfo.raidSize == 20) then
		return { UnBotBossPresetClassic20Mode };
	end
	if (instanceInfo and instanceInfo.raidSize == 40) then
		if bossKey == "naxxramas__gluth" then
			return { UnBotBossPresetClassic40Mode, { key = "40n_corridor", label = "40 — коридор" }, { key = "40n_full", label = "40 — полный" }, { key = "40n_intercept", label = "40 — перехват" } };
		end
		return { UnBotBossPresetClassic40Mode };
	end
	if (instanceInfo and instanceInfo.expansion == "tbc") then
		if (instanceInfo.raidSize == 10) then
			return { UnBotBossPresetModes[1] };
		end
		return { UnBotBossPresetModes[3] };
	end
	if (bossKey == "valithria_dreamwalker") then
		return {
			UnBotBossPresetModes[1],
			UnBotBossPresetModes[2],
			UnBotBossPresetModes[3],
			UnBotBossPresetModes[4],
			UnBotBossPresetValithria18Mode,
		};
	end
	return UnBotBossPresetModes;
end

