function UnBotBossPresetAutoStrategyEnabled(bossKey, modeKey, preset)
	if (not UnBotBossPresetAutoStrategyDescription(bossKey, modeKey)) then
		return false;
	end
	preset = preset or (
		UnBotBossPresetGet and UnBotBossPresetGet(bossKey, modeKey)
	);
	return type(preset) == "table" and preset.autoStrategyEnabled ~= false;
end

function UnBotBossPresetLoadedAutoStrategyEnabled(bossKey)
	if UnBotSquadConfig and UnBotSquadConfig.forcedWipe then return false; end
	local loaded = UnBotSquadBuilder and UnBotSquadBuilder.loadedBossPreset;
	if (not loaded or (bossKey and loaded.bossKey ~= bossKey)) then
		return false;
	end
	local preset = UnBotSquadConfig
		and UnBotSquadConfig.bossPresets
		and UnBotSquadConfig.bossPresets[loaded.bossKey]
		and UnBotSquadConfig.bossPresets[loaded.bossKey][loaded.modeKey];
	return UnBotBossPresetAutoStrategyEnabled(
		loaded.bossKey,
		loaded.modeKey,
		preset
	);
end

