	end
	return nil;
end

function UnBotBossPresetExtractLegacyStartMessage(preset)
	local raw = tostring(preset and preset.guideText or "");
	if (raw == "") then
		return nil;
	end
	raw = string.gsub(raw, "\r\n", "\n");
	local kept = {};
	local startLines = {};
	local inStart = false;
	local found = false;
	for line in string.gmatch(raw.."\n", "(.-)\n") do
		local label = string.match(line, "^%s*%[(.-)%]%s*$");
		if (label) then
			local normalizedLabel = UnBotSpecSummonNormalize(label);
			if (
				normalizedLabel == "старт"
				or normalizedLabel == "Старт"
				or normalizedLabel == "СТАРТ"
				or normalizedLabel == "start"
			) then
				inStart = true;
				found = true;
			else
				inStart = false;
				table.insert(kept, line);
			end
		elseif (inStart) then
			table.insert(startLines, line);
		else
			table.insert(kept, line);
		end
	end
	if (not found) then
		return nil;
	end
	local startMessage = table.concat(startLines, "\n");
	startMessage = string.gsub(startMessage, "^%s+", "");
	startMessage = string.gsub(startMessage, "%s+$", "");
	local guideText = table.concat(kept, "\n");
	guideText = string.gsub(guideText, "^%s+", "");
	guideText = string.gsub(guideText, "%s+$", "");
	preset.guideText = guideText;
	return startMessage ~= "" and startMessage or nil;
end

function UnBotBossPresetSeedStartMessages()
	if ((tonumber(UnBotSquadConfig.bossStartMessageSeedVersion) or 0) >= 1) then
		return;
	end
	local legacyStartGuideWasSeeded =
		(tonumber(UnBotSquadConfig.bossStartGuideSeedVersion) or 0) >= 1;
	local foundPreset = false;
	for bossKey, modes in pairs(UnBotSquadConfig.bossPresets or {}) do
		for modeKey, preset in pairs(modes or {}) do
			if (type(preset) == "table") then
				foundPreset = true;
				local extracted = UnBotBossPresetExtractLegacyStartMessage(preset);
				if (type(preset.startMessage) ~= "string") then
					if (extracted) then
						preset.startMessage = extracted;
					elseif (not legacyStartGuideWasSeeded) then
						preset.startMessage =
							UnBotBossPresetBuiltinStartMessage(bossKey, modeKey);
					end
				end
				if (extracted) then
					preset.guideUpdatedAt = "2026-08-29";
				end
				if (preset.startMessage) then
					preset.startMessageUpdatedAt = "2026-08-29";
				end
			end
		end
	end
	if (foundPreset) then
		UnBotSquadConfig.bossStartMessageSeedVersion = 1;
	end
end

function UnBotBossPresetSeedStartGuide()
	if ((tonumber(UnBotSquadConfig.bossStartGuideSeedVersion) or 0) >= 1) then
		return;
	end
	local marrowgarHeroic = UnBotSquadConfig.bossPresets.lord_marrowgar
		and UnBotSquadConfig.bossPresets.lord_marrowgar["25h"];
	if (type(marrowgarHeroic) ~= "table") then
		return;
	end
	if (
		type(marrowgarHeroic.guideText) ~= "string"
		or marrowgarHeroic.guideText == ""
	) then
		marrowgarHeroic.guideText = UnBotBossPresetBuiltinGuide(
			"lord_marrowgar",
			"25h"
		);
		marrowgarHeroic.guideUpdatedAt = "2026-08-29";
	end
	UnBotSquadConfig.bossStartGuideSeedVersion = 1;
end

