function UnBotBossPresetSeedLichKing()
	local presets = UnBotSquadConfig.bossPresets;
	presets.the_lich_king = presets.the_lich_king or {};
	-- Config-level markers survive Save/Standard/Previous replacing the preset table.
	UnBotSquadConfig.lichKingSoloPreset122 = UnBotSquadConfig.lichKingSoloPreset122 or {};
	for _, modeKey in ipairs({"25n", "25h"}) do
		local preset = presets.the_lich_king[modeKey];
		if not preset or not UnBotSquadConfig.lichKingSoloPreset122[modeKey] then
			preset = preset or {};
			presets.the_lich_king[modeKey] = preset;
			preset.lichKingBeforeSolo122 = {
				requirements = preset.requirements, slots = preset.slots,
				includeResurrectionReserve = preset.includeResurrectionReserve,
				resurrectionReserveCount = preset.resurrectionReserveCount,
				guideText = preset.guideText, startMessage = preset.startMessage,
				source = preset.source,
			};
			preset.requirements = {};
			preset.slots = {};
			preset.storageMode = "class-spec";
			preset.schemaVersion = 2;
			preset.includeResurrectionReserve = false;
			preset.resurrectionReserveCount = 0;
			preset.source = "Соло: при достаточном DPS и самохиле. Групповой состав не подтверждён";
			preset.guideText = UnBotBossPresetBuiltinGuide("the_lich_king", modeKey);
			preset.startMessage = UnBotBossPresetBuiltinStartMessage("the_lich_king", modeKey);
			preset.guideUpdatedAt = "2026-09-08";
			preset.startMessageUpdatedAt = "2026-09-08";
			UnBotSquadConfig.lichKingSoloPreset122[modeKey] = true;
		end
	end
	for _, modeKey in ipairs({"10n", "10h"}) do
		local preset = presets.the_lich_king[modeKey];
		if not preset then
			preset = {
				storageMode = "class-spec", schemaVersion = 2,
				requirements = {
					{className="paladin", specKey="prot", label="Paladin - Protection (Tank)", count=1},
					{className="paladin", specKey="holy", label="Paladin - Holy (Heal)", count=1},
					{className="hunter", specKey="mm", label="Hunter - Marksmanship (DPS)", count=1},
				},
				savedAt = "2026-09-07", source = "Lich King: experimental three-bot composition; kill not confirmed",
			};
			presets.the_lich_king[modeKey] = preset;
		end
		if not preset.lichKingComposition116 then
			local previous = preset.requirements or preset.slots or {};
			local requirements, hunter, rogue = {}, nil, nil;
			for _, slot in ipairs(previous) do
				local copy = {}; for key, value in pairs(slot) do copy[key] = value; end
				if not slot.reserveOnly and slot.className == "hunter" then
					if not hunter then hunter = copy; end
				elseif not slot.reserveOnly and slot.className == "rogue" then
					if not rogue then rogue = copy; end
				else requirements[#requirements+1] = copy; end
			end
			hunter = hunter or {className="hunter", specKey="mm", label="Hunter - Marksmanship (DPS)"};
			hunter.count = 2;
			rogue = rogue or {className="rogue"};
			rogue.specKey = "combat"; rogue.label = "Rogue - Combat (DPS)"; rogue.count = 1;
			requirements[#requirements+1] = hunter; requirements[#requirements+1] = rogue;
			preset.lichKingCompositionBefore116 = previous;
			preset.requirements = requirements;
			preset.lichKingComposition116 = true;
			UnBotSquadConfig.lichKing = UnBotSquadConfig.lichKing or {};
			UnBotSquadConfig.lichKing.rogueBossFocus = true;
		end
		if not preset.lichKingCompactTest119 then
			local previous = preset.requirements or preset.slots or {};
			local requirements = {
				{className="paladin",specKey="prot",label="Paladin - Protection (Tank)",count=1},
				{className="priest",specKey="disc",label="Priest - Discipline (Heal)",count=1},
				{className="shaman",specKey="enh",label="Shaman - Enhancement (DPS)",count=1},
			};
			for _,slot in ipairs(previous) do
				if slot.reserveOnly then
					local copy={};for key,value in pairs(slot) do copy[key]=value;end;
					requirements[#requirements+1]=copy;
				end
			end
			preset.lichKingBeforeCompactTest119 = previous;
			preset.requirements = requirements;
			preset.lichKingCompactTest119 = true;
			preset.source = "ТЕСТ: игрок-ретрик + прот-паладин + ДЦ-прист + энх-шаман; победа не подтверждена";
			UnBotSquadConfig.lichKing = UnBotSquadConfig.lichKing or {};
			UnBotSquadConfig.lichKing.rogueBossFocus = false;
		end
		if not preset.lichKingTacticsVersion then
			if preset.autoStrategyEnabled == nil then preset.autoStrategyEnabled = true; end
			if preset.guideText == nil then preset.guideText = UnBotBossPresetBuiltinGuide("the_lich_king", modeKey); end
			if preset.startMessage == nil then preset.startMessage = UnBotBossPresetBuiltinStartMessage("the_lich_king", modeKey); end
			preset.lichKingTacticsVersion = 1;
		end
	end
end

function UnBotBossPresetSeedHalion()
	local key = "the_ruby_sanctum__halion";
	local presets = UnBotSquadConfig.bossPresets;
	presets[key] = presets[key] or {};
	for _, modeKey in ipairs({"10n", "10h", "25n", "25h"}) do
		local preset = presets[key][modeKey] or {};
		presets[key][modeKey] = preset;
		if not preset.halionTwoRet120 then
			local previous = preset.requirements or preset.slots;
			-- SeedDefaults runs during file loading, before BuiltinGet is declared.
			local requirements = {
				{className="paladin", specKey="ret", label="Paladin - Retribution (DPS)", count=2},
			};
			local source = "Халион: игрок + два ретри-паладина; co -rs";
			for _, slot in ipairs(previous or {}) do
				if slot.reserveOnly then
					local copy = {}; for k, v in pairs(slot) do copy[k] = v; end
					requirements[#requirements + 1] = copy;
				end
			end
			preset.halionRequirementsBefore120 = previous;
			preset.requirements = requirements;
			preset.storageMode = "class-spec";
			preset.schemaVersion = 2;
			preset.source = source;
			preset.savedAt = "2026-09-08";
			if preset.autoStrategyEnabled == nil then preset.autoStrategyEnabled = true; end
			if preset.guideText == nil then preset.guideText = UnBotBossPresetBuiltinGuide(key, modeKey); end
			if preset.startMessage == nil then preset.startMessage = UnBotBossPresetBuiltinStartMessage(key, modeKey); end
			preset.halionTwoRet120 = true;
		end
	end
end

UnBotBossPresetSeedDefaults = function()
	if UnBotAuthorPresets then
		UnBotAuthorPresets.Sync(UnBotSquadConfig);
		return;
	end
	UnBotBossPresetSeedHalion();
	UnBotBossPresetSeedLichKing();
	local seedVersion = tonumber(UnBotSquadConfig.bossPresetSeedVersion) or 0;
	UnBotBossPresetSeedStartMessages();
	UnBotBossPresetSeedStartGuide();
	UnBotBossPresetSeedGunshipAllianceGuide();
	UnBotBossPresetSeedSaurfangStartMessage();
	UnBotBossPresetSeedFestergutTactics();
	UnBotBossPresetSeedRotfaceTactics();
	UnBotBossPresetSeedPutricideHeroicSoloTactics();
	UnBotBossPresetSeedBloodPrincesTactics();
	UnBotBossPresetSeedLanathelTactics();
	UnBotBossPresetSeedSvalnaTactics();
