	if (seedVersion >= 27) then
		return;
	end
	local presets = UnBotSquadConfig.bossPresets;
	presets.lord_marrowgar = presets.lord_marrowgar or {};
	presets.deathbringer_saurfang = presets.deathbringer_saurfang or {};
	presets.festergut = presets.festergut or {};
	presets.rotface = presets.rotface or {};
	presets.professor_putricide = presets.professor_putricide or {};
	presets.sister_svalna = presets.sister_svalna or {};
	presets.valithria_dreamwalker = presets.valithria_dreamwalker or {};
	presets.sindragosa = presets.sindragosa or {};
	presets.gunship_battle = presets.gunship_battle or {};
	if (seedVersion < 11) then
	if (not presets.lord_marrowgar["25h"]) then
		presets.lord_marrowgar["25h"] = {
			slots = UnBotSquadBuilderCopySlots(UnBotMarrowgar25HeroicPresetSlots),
			savedAt = "2026-07-28 21:07:21",
			source = "BossMemory: Lord Marrowgar 25 heroic, Tiridan + Blood DK + Holy Paladin",
			startMessage = UnBotBossPresetBuiltinStartMessage("lord_marrowgar", "25h"),
			startMessageUpdatedAt = "2026-08-29",
		};
	end
	presets.deathbringer_saurfang["25h"] = {
		slots = UnBotSquadBuilderCopySlots(UnBotSaurfang25HeroicPresetSlots),
		savedAt = "2026-07-29 13:21:24",
		source = "BossMemory kill: Tiridan + Blood DK + Holy Paladin + 3 Combat Rogue",
		startMessage = UnBotBossPresetBuiltinStartMessage(
			"deathbringer_saurfang",
			"25h"
		),
		startMessageUpdatedAt = "2026-08-29",
	};
	if (not presets.festergut["25h"]) then
		presets.festergut["25h"] = {
			slots = UnBotSquadBuilderCopySlots(UnBotFestergut25HeroicPresetSlots),
			savedAt = "2026-07-29",
			source = "Festergut 25 heroic: Tiridan + 2 Blood DK + Holy Paladin + 3 Combat Rogue",
			guideText = UnBotBossPresetBuiltinGuide("festergut", "25h"),
			guideUpdatedAt = "2026-08-29",
			startMessage = UnBotBossPresetBuiltinStartMessage(
				"festergut",
				"25h"
			),
			startMessageUpdatedAt = "2026-08-29",
		};
	end
	if (not presets.rotface["25h"]) then
		presets.rotface["25h"] = {
			slots = UnBotSquadBuilderCopySlots(UnBotSaurfang25HeroicPresetSlots),
			savedAt = "2026-07-29",
			source = "confirmed Rotface 25 heroic kill: Tiridan + Blood DK + Holy Paladin + 3 Combat Rogue",
			guideText = UnBotBossPresetBuiltinGuide("rotface", "25h"),
			guideUpdatedAt = "2026-08-29",
			startMessage = UnBotBossPresetBuiltinStartMessage(
				"rotface",
				"25h"
			),
			startMessageUpdatedAt = "2026-08-29",
		};
	end
	local currentPutricide = presets.professor_putricide["25h"];
	local migrateLegacyPutricide = currentPutricide
		and currentPutricide.source
		and (
			string.find(currentPutricide.source, "2 Blood DK", 1, true)
			or string.find(currentPutricide.source, "ICC add targeting retained", 1, true)
		);
	if (not currentPutricide or migrateLegacyPutricide) then
		if (migrateLegacyPutricide) then
			UnBotSquadConfig.bossPresetBackups.professor_putricide =
				UnBotSquadConfig.bossPresetBackups.professor_putricide or {};
			UnBotSquadConfig.bossPresetBackups.professor_putricide["25h"] = {
				slots = UnBotSquadBuilderCopySlots(currentPutricide.slots),
				savedAt = currentPutricide.savedAt,
				source = currentPutricide.source,
				backupAt = date("%Y-%m-%d %H:%M:%S"),
			};
		end
		presets.professor_putricide["25h"] = {
			slots = UnBotSquadBuilderCopySlots(UnBotPutricide25HeroicPresetSlots),
			savedAt = "2026-08-02",
			source = "Putricide 25 heroic boss-only test: player tank + Holy Paladin + Combat Rogue + Arms/Fury Warrior",
			guideText = UnBotBossPresetBuiltinGuide(
				"professor_putricide",
				"25h"
			),
			guideUpdatedAt = "2026-08-29",
			startMessage = UnBotBossPresetBuiltinStartMessage(
				"professor_putricide",
				"25h"
			),
			startMessageUpdatedAt = "2026-08-29",
		};
	end
	currentPutricide = presets.professor_putricide["25h"];
	local putricideSlotCount = 0;
	local putricideRogueCount = 0;
	local putricideWarriorCount = 0;
	local putricideHolyCount = 0;
	for _, slot in ipairs((currentPutricide and currentPutricide.slots) or {}) do
		local count = math.max(1, tonumber(slot.count) or 1);
		local className = UnBotSpecSummonNormalize(slot.className);
		local specName = UnBotSpecSummonNormalize(slot.specKey or slot.specName);
		putricideSlotCount = putricideSlotCount + count;
		if (className == "rogue" and specName == "combat") then
			putricideRogueCount = putricideRogueCount + count;
		elseif (
			className == "warrior"
			and (specName == "arms" or specName == "fury")
		) then
			putricideWarriorCount = putricideWarriorCount + count;
		elseif (className == "paladin" and specName == "holy") then
			putricideHolyCount = putricideHolyCount + count;
		end
	end
	if (
		currentPutricide
		and putricideSlotCount == 2
		and putricideRogueCount == 1
		and putricideWarriorCount == 1
		and putricideHolyCount == 0
	) then
		UnBotSquadConfig.bossPresetBackups.professor_putricide =
			UnBotSquadConfig.bossPresetBackups.professor_putricide or {};
		if (not UnBotSquadConfig.bossPresetBackups.professor_putricide["25h_pre_holy"]) then
			UnBotSquadConfig.bossPresetBackups.professor_putricide["25h_pre_holy"] = {
				slots = UnBotSquadBuilderCopySlots(currentPutricide.slots),
				savedAt = currentPutricide.savedAt,
				source = currentPutricide.source,
				backupAt = date("%Y-%m-%d %H:%M:%S"),
			};
		end
		table.insert(currentPutricide.slots, {
			className = "paladin",
			specKey = "holy",
			label = "|cFFF58CBAPaladin|r - Holy (Heal)",
			count = 1,
		});
		currentPutricide.savedAt = date("%Y-%m-%d %H:%M:%S");
		currentPutricide.source = "Putricide 25 heroic boss-only test: player tank + Holy Paladin + Combat Rogue + Arms/Fury Warrior";
	end
	if (not presets.valithria_dreamwalker["10n"]) then
		presets.valithria_dreamwalker["10n"] = {
			slots = UnBotSquadBuilderCopySlots(UnBotSquadBuilder.valithriaPresetSlots),
			savedAt = "2026-07-27",
			source = "successful Valithria composition",
		};
	end
	if (not presets.valithria_dreamwalker["25n"]) then
		presets.valithria_dreamwalker["25n"] = {
			slots = UnBotSquadBuilderCopySlots(UnBotValithria25NormalPresetSlots),
			savedAt = "2026-08-04",
			source = "recommended full Valithria 25 normal: player Retribution + 2 tanks + 6 healers + 16 bot DPS",
		};
	end
	if (not presets.valithria_dreamwalker["25h"]) then
		presets.valithria_dreamwalker["25h"] = {
			slots = UnBotSquadBuilderCopySlots(UnBotValithria25HeroicPresetSlots),
			savedAt = "2026-08-02",
			source = "Valithria 25 heroic video reconstruction: one bot of every class; inferred 2 tanks, 4 healers and 4 DPS",
		};
	end
	if (not presets.sindragosa["25n"]) then
		presets.sindragosa["25n"] = {
			slots = UnBotSquadBuilderCopySlots(UnBotSindragosaPresetSlots),
			savedAt = "2026-08-09",
			source = "Sindragosa 25 normal: Protection Warrior + Blood DK + Restoration Druid + 6 Demonology Warlock; healer tomb priority",
		};
	end
	end
	if (not presets.sister_svalna["25n"]) then
		presets.sister_svalna["25n"] = {
			requirements = UnBotSquadBuilderCopySlots(UnBotSvalna25NormalPresetSlots),
			storageMode = "class-spec",
			schemaVersion = 2,
			includeResurrectionReserve = true,
			resurrectionReserveCount = 1,
