local function UnBotSindragosaUnitHasSoulstone(unit)
	if (not unit or not UnitExists(unit)) then
		return false, nil;
	end
	for i = 1, 40, 1 do
		local auraName, rank, icon, count, debuffType, duration, expirationTime, unitCaster, isStealable, shouldConsolidate, spellId = UnitBuff(unit, i);
		if (not auraName) then
			break
		end
		for _, wantedId in ipairs(UnBotSoulstoneTestAura.ids or {}) do
			if (
				(spellId and spellId == wantedId)
				or (GetSpellInfo and auraName == GetSpellInfo(wantedId))
			) then
				return true, unitCaster and UnitName(unitCaster) or nil;
			end
		end
	end
	return false, nil;
end

local function UnBotSindragosaSoulstoneCoverage()
	local covered = {};
	local casters = {};
	local coverageByName = {};
	local targets = UnBotBuffCycleSnapshotTargets();
	for _, name in ipairs(targets) do
		local unit = UnBotBuffCycleResolveUnit(name);
		local hasSoulstone, casterName = UnBotSindragosaUnitHasSoulstone(unit);
		if (hasSoulstone) then
			table.insert(covered, name);
			coverageByName[name] = casterName;
			if (casterName) then
				casters[casterName] = true;
			end
		end
	end
	table.sort(covered);
	return covered, casters, coverageByName;
end

local function UnBotSindragosaCollectWarlocks()
	UnBotRegistryAttachStorage();
	local names = {};
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (
			profile
			and unit and UnitIsConnected(unit)
			and UnBotSpecSummonNormalize(profile.className) == "warlock"
		) then
			table.insert(names, name);
		end
	end);
	table.sort(names, function(a, b)
		local pa = UnBotBotRegistry.bots[a] or {};
		local pb = UnBotBotRegistry.bots[b] or {};
		local ga = tonumber(pa.gearScore) or 0;
		local gb = tonumber(pb.gearScore) or 0;
		if (ga ~= gb) then
			return ga > gb;
		end
		return string.lower(a) < string.lower(b);
	end);
	return names;
end

local function UnBotSindragosaStopSoulstone(text, keepMaintenance)
	UnBotSindragosaPrep.armed = false;
	UnBotSindragosaPrep.active = false;
	UnBotSindragosaPrep.stage = keepMaintenance and "monitor" or "idle";
	UnBotSindragosaPrep.maintenance = keepMaintenance and true or false;
	UnBotSindragosaPrep.monitorNext = GetTime() + 5;
	if (text) then
		UnBotSpecSummonMessage(text);
	end
end

function UnBotSindragosaReleaseBubbleReserve(reason, quiet)
	local state = UnBotSindragosaPrep;
	local name = state.bubbleReserveName;
	if (name) then
		if (state.bubbleReserveBlocked) then
			UnBotBuffCycleSendWhisper(name, "ss -Divine Shield");
		end
		if (state.bubbleReserveLayOnHandsBlocked) then
			UnBotBuffCycleSendWhisper(name, "ss -Lay on Hands");
		end
	end
	state.bubbleReserveName = nil;
	state.bubbleReserveBlocked = false;
	state.bubbleReserveLayOnHandsBlocked = false;
	state.bubbleReserveCastAt = nil;
	state.bubbleReserveCastUntil = nil;
	state.bubbleReserveCastAttempts = 0;
	state.bubbleReserveConsumed = false;
	if (name and not quiet) then
		UnBotSpecSummonMessage(
			"Синдрагоса: резерв бабла снят с "..name
			..(reason and (" — "..reason) or "").."."
		);
	end
end

function UnBotSindragosaAssignBubbleReserve(reason)
	local state = UnBotSindragosaPrep;
	local members = UnBotSpecSummonGetMembers();
	members[UnitName("player")] = nil;
	local onlineCount = 0;
	for name in pairs(members) do
		local unit = UnBotSquadRosterFindUnit(name);
		if (unit and (not UnitIsConnected or UnitIsConnected(unit))) then
			onlineCount = onlineCount + 1;
		end
	end
	local candidates = UnBotSindragosaRetTankCandidates();
	if (onlineCount ~= 2 or table.getn(candidates) ~= 2) then
		if (state.bubbleReserveName) then
			UnBotSindragosaReleaseBubbleReserve("состав больше не равен игрок + 2 ретрика", true);
		end
		return false;
	end

	local name = candidates[1];
	if (state.bubbleReserveName and state.bubbleReserveName ~= name) then
		UnBotSindragosaReleaseBubbleReserve("назначен другой ретрик", true);
	end
	state.bubbleReserveName = name;
	state.bubbleReserveCastAt = nil;
	state.bubbleReserveCastUntil = nil;
	state.bubbleReserveCastAttempts = 0;
	state.bubbleReserveConsumed = false;
	UnBotBuffCycleSendWhisper(name, "ss Divine Shield");
	UnBotBuffCycleSendWhisper(name, "ss Lay on Hands");
	state.bubbleReserveBlocked = true;
	state.bubbleReserveLayOnHandsBlocked = true;
	UnBotSpecSummonMessage(
		"Синдрагоса: "..name
		.." назначен резервом бабла; точечно заблокированы Divine Shield и Lay on Hands"
		..(reason and (" — "..reason) or "")
		..". ICC-стратегия и укрытие за глыбами не изменены."
	);
	return true;
end

function UnBotSindragosaStartBubbleReserve()
	local state = UnBotSindragosaPrep;
	if (state.bubbleReserveConsumed) then
		return false;
	end
	if (not state.bubbleReserveName and not UnBotSindragosaAssignBubbleReserve("воздушная фаза")) then
		return false;
	end
	local name = state.bubbleReserveName;
	local unit = name and UnBotBuffCycleResolveUnit(name) or nil;
	if (
		not unit
		or not UnitExists(unit)
		or (UnitIsConnected and not UnitIsConnected(unit))
		or UnitIsDeadOrGhost(unit)
		or UnBotSindragosaUnitHasDebuff(unit, 70157)
	) then
		state.bubbleReserveConsumed = true;
		if (state.bubbleReserveLayOnHandsBlocked and name) then
			UnBotBuffCycleSendWhisper(name, "ss -Lay on Hands");
			state.bubbleReserveLayOnHandsBlocked = false;
		end
		UnBotSpecSummonMessage(
			"Синдрагоса: у игрока нет Божественного щита, но резервный ретрик "
			..tostring(name or "не назначен").." недоступен."
		);
		return false;
	end
	if (UnBotSindragosaUnitHasDivineShield(unit)) then
		state.bubbleReserveConsumed = true;
		state.bubbleReserveCastAt = nil;
		state.bubbleReserveCastUntil = nil;
		state.bubbleReserveCastAttempts = 0;
		if (state.bubbleReserveBlocked) then
			UnBotBuffCycleSendWhisper(name, "ss -Divine Shield");
			state.bubbleReserveBlocked = false;
		end
		if (state.bubbleReserveLayOnHandsBlocked) then
			UnBotBuffCycleSendWhisper(name, "ss -Lay on Hands");
			state.bubbleReserveLayOnHandsBlocked = false;
		end
		UnBotSpecSummonMessage(
			"Синдрагоса: Божественный щит уже активен на резервном ретрике "..name.."."
		);
		return true;
	end
	if (state.bubbleReserveBlocked) then
		UnBotBuffCycleSendWhisper(name, "ss -Divine Shield");
		state.bubbleReserveBlocked = false;
	end
	state.bubbleReserveCastAttempts = 1;
	state.bubbleReserveCastAt = GetTime() + 0.2;
	state.bubbleReserveCastUntil = GetTime() + 1.2;
	UnBotBuffCycleSendWhisper(name, "cast Divine Shield");
	UnBotSpecSummonMessage(
		"Синдрагоса: у игрока нет Божественного щита — "..name
		.." получил команду резервного бабла (попытка 1/3)."
	);
	return true;
end

function UnBotSindragosaUpdateBubbleReserve(now)
	local state = UnBotSindragosaPrep;
	if (not state.bubbleReserveCastAt or now < state.bubbleReserveCastAt) then
		return;
	end
	local name = state.bubbleReserveName;
	local unit = name and UnBotBuffCycleResolveUnit(name) or nil;
	if (unit and UnitExists(unit) and UnBotSindragosaUnitHasDivineShield(unit)) then
		state.bubbleReserveCastAt = nil;
		state.bubbleReserveCastUntil = nil;
		state.bubbleReserveConsumed = true;
		if (state.bubbleReserveLayOnHandsBlocked) then
			UnBotBuffCycleSendWhisper(name, "ss -Lay on Hands");
			state.bubbleReserveLayOnHandsBlocked = false;
		end
		UnBotSpecSummonMessage(
			"Синдрагоса: резервный Божественный щит подтверждён на "..name
			.." до раздачи воздушных меток."
		);
		return;
	end
	if (
		not unit
		or not UnitExists(unit)
		or (UnitIsConnected and not UnitIsConnected(unit))
		or UnitIsDeadOrGhost(unit)
		or UnBotSindragosaUnitHasDebuff(unit, 70157)
	) then
		state.bubbleReserveCastAt = nil;
		state.bubbleReserveCastUntil = nil;
		state.bubbleReserveConsumed = true;
		if (state.bubbleReserveLayOnHandsBlocked and name) then
			UnBotBuffCycleSendWhisper(name, "ss -Lay on Hands");
			state.bubbleReserveLayOnHandsBlocked = false;
		end
		UnBotSpecSummonMessage(
			"Синдрагоса: резервный бабл не подтверждён — "
			..tostring(name or "ретрик").." стал недоступен."
		);
		return;
	end
	if (
		now < (state.bubbleReserveCastUntil or 0)
		and (tonumber(state.bubbleReserveCastAttempts) or 0) < 3
	) then
		state.bubbleReserveCastAttempts =
			(tonumber(state.bubbleReserveCastAttempts) or 0) + 1;
		state.bubbleReserveCastAt = now + 0.25;
		UnBotBuffCycleSendWhisper(name, "cast Divine Shield");
		UnBotSpecSummonMessage(
			"Синдрагоса: повтор резервного бабла для "..name
			.." (попытка "..state.bubbleReserveCastAttempts.."/3)."
		);
		return;
	end
	state.bubbleReserveCastAt = nil;
	state.bubbleReserveCastUntil = nil;
	state.bubbleReserveConsumed = true;
	if (state.bubbleReserveLayOnHandsBlocked and name) then
		UnBotBuffCycleSendWhisper(name, "ss -Lay on Hands");
		state.bubbleReserveLayOnHandsBlocked = false;
	end
	UnBotSpecSummonMessage(
		"Синдрагоса: резервный Божественный щит на "..tostring(name or "ретрике")
		.." не подтверждён; автоматические попытки остановлены."
	);
end

function UnBotSindragosaApplyFrostResistanceAura(reason)
	UnBotRegistryAttachStorage();
	local playerName = UnitName("player");
	for _, name in ipairs(UnBotBuffCycleSnapshotTargets()) do
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		local unit = UnBotBuffCycleResolveUnit(name);
		if (
			name ~= playerName
			and unit
			and UnitIsConnected(unit)
			and UnBotRegistryProfileMatches(
				profile,
				"paladin",
				{"retribution", "ret"}
			)
		) then
			UnBotBuffCycleSendWhisper(name, "co +rfrost");
			UnBotBuffCycleSendWhisper(name, "cast Frost Resistance Aura");
			UnBotSindragosaPrep.frostAuraPaladin = name;
			UnBotSpecSummonMessage(
				"Синдрагоса 25H: Retribution Paladin "..name
				.." получил обязательную стратегию Frost Resistance Aura"
				..(reason and (" — "..reason) or "").."."
			);
			return true;
		end
	end
	UnBotSpecSummonMessage(
		"Синдрагоса 25H: подключённый Retribution Paladin не найден; "
		.."Frost Resistance Aura не включена."
	);
	return false;
end

function UnBotSindragosaReleaseFrostResistanceAura()
	local name = UnBotSindragosaPrep.frostAuraPaladin;
	if (not name) then
		return;
	end
	local unit = UnBotBuffCycleResolveUnit(name);
	if (unit and UnitIsConnected(unit)) then
		UnBotBuffCycleSendWhisper(name, "co -rfrost");
	end
	UnBotSindragosaPrep.frostAuraPaladin = nil;
end

local function UnBotSindragosaStartSoulstones()
	UnBotSindragosaAssignBubbleReserve("состав готов");
	if (UnBotSindragosaIsHeroic25()) then
		UnBotSindragosaApplyFrostResistanceAura("состав готов");
	end
	local warlocks = UnBotSindragosaCollectWarlocks();
	if (#warlocks == 0) then
		UnBotSindragosaStopSoulstone(
			"Синдрагоса: в текущем составе нет варлоков — раздача Soulstone не запущена.",
			false
		);
		return;
	end

	local tankNames = {};
	local healerNames = {};
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		local className = UnBotSpecSummonNormalize(profile and profile.className);
		local specName = UnBotSpecSummonNormalize(profile and profile.specName);
		if (unit and UnitIsConnected(unit) and UnBotBuffCycleTargetIsTank(name)) then
			table.insert(tankNames, name);
		elseif (
			unit and UnitIsConnected(unit)
			and (
				(
					(className == "druid" or className == "shaman")
					and specName == "restoration"
				) or (
					className == "paladin"
					and specName == "holy"
				) or (
					className == "priest"
					and (specName == "holy" or specName == "discipline")
				)
			)
		) then
			table.insert(healerNames, name);
		end
	end);
	table.sort(tankNames);
	table.sort(healerNames);
	local roleTargets = {};
	local targetSeen = {};
	local function addRoleTarget(role, targetName)
		if (targetName and targetName ~= "" and not targetSeen[targetName]) then
			targetSeen[targetName] = true;
			table.insert(roleTargets, {role = role, targetName = targetName});
		end
	end
	for i = 1, math.min(2, #tankNames), 1 do
		addRoleTarget("tank", tankNames[i]);
	end
	for i = 1, math.min(3, #healerNames), 1 do
		addRoleTarget("healer", healerNames[i]);
	end
	addRoleTarget("master", UnitName("player"));
	UnBotSindragosaPrep.assignments = {};
	UnBotSindragosaPrep.assignedNames = {};
	UnBotSindragosaPrep.confirmedCasters = {};
	for i = 1, #warlocks, 1 do
		local desired = roleTargets[i];
		table.insert(UnBotSindragosaPrep.assignments, {
			name = warlocks[i],
			role = desired and desired.role or "self",
			targetName = desired and desired.targetName or warlocks[i],
		});
		UnBotSindragosaPrep.assignedNames[warlocks[i]] = true;
	end
	UnBotSindragosaPrep.armed = false;
	UnBotSindragosaPrep.active = true;
	UnBotSindragosaPrep.maintenance = true;
	UnBotSindragosaPrep.stage = "quiesce";
	UnBotSindragosaPrep.attempt = 1;
	UnBotSindragosaPrep.index = 1;
	UnBotSindragosaPrep.nextTime = GetTime();
	UnBotSpecSummonMessage(
		"Синдрагоса: раздача Soulstone запущена — варлоков "
		..tostring(#UnBotSindragosaPrep.assignments)
		..". Приоритет: два танка, до трёх хилов, мастер; остальные варлоки — себе."
	);
end

local function UnBotSindragosaLoadPreset(summonNow)
	UnBotSquadBuilderEnsureConfig();
	if (UnBotMarrowgarDisarmPreset) then
		UnBotMarrowgarDisarmPreset(true);
	end
	local savedPreset =
		UnBotSquadConfig.bossPresets
		and UnBotSquadConfig.bossPresets.sindragosa
		and UnBotSquadConfig.bossPresets.sindragosa["25n"];
	UnBotSquadBuilderSetSlots(
		UnBotBossPresetRequirements(savedPreset) or UnBotSindragosaPresetSlots
	);
	UnBotSquadConfig.resurrectionReserveCount = 0;
	UnBotSquadConfig.includeResurrectionReserve = false;
	if (UnBotSquadBuilder.scrollFrame) then
		UnBotSquadBuilder.scrollFrame:SetVerticalScroll(0);
	end
	UnBotSquadBuilderRefresh();
	UnBotSpecSummonMessage(
		"Пресет Синдрагосы загружен: "
		..tostring(UnBotSquadBuilderBotCount()).." ботов + вы."
	);
	UnBotSquadBuilder.loadedBossPreset = {
		bossKey = "sindragosa",
		modeKey = "25n",
	};
	if (not summonNow) then
		return;
	end
	UnBotBossPresetArmSpecialBehavior("sindragosa", "25n");
	UnBotSquadBuilderStart();
end

