function UnBotBossPresetFindBoss(bossKey)
	for _, boss in ipairs(UnBotBossPresetBosses) do
		if (boss.key == bossKey) then
			return boss;
		end
	end
	return nil;
end

function UnBotBossPresetFindMode(modeKey)
	if modeKey == "40n_corridor" then return { key = "40n_corridor", label = "40 — коридор" }; end
	if modeKey == "40n_full" then return { key = "40n_full", label = "40 — полный" }; end
	if modeKey == "40n_intercept" then return { key = "40n_intercept", label = "40 — перехват" }; end
	if (UnBotBossPresetTwinsPlayerMode.key == modeKey) then return UnBotBossPresetTwinsPlayerMode; end
	if (UnBotBossPresetTwinsSmallMode.key == modeKey) then return UnBotBossPresetTwinsSmallMode; end
	for _, mode in ipairs(UnBotBossPresetModes) do
		if (mode.key == modeKey) then
			return mode;
		end
	end
	if (UnBotBossPresetValithria18Mode.key == modeKey) then
		return UnBotBossPresetValithria18Mode;
	end
	if (UnBotBossPresetClassic20Mode.key == modeKey) then
		return UnBotBossPresetClassic20Mode;
	end
	if (UnBotBossPresetClassic40Mode.key == modeKey) then
		return UnBotBossPresetClassic40Mode;
	end
	return nil;
end

function UnBotBossPresetGet(bossKey, modeKey)
	UnBotSquadBuilderEnsureConfig();
	local bossPresets = UnBotSquadConfig.bossPresets[bossKey];
	local preset = bossPresets and bossPresets[modeKey];
	if (
		type(preset) == "table"
		and UnBotBossPresetRequirements(preset)
	) then
		return preset;
	end
	return nil;
end

function UnBotBossPresetEditableGet(bossKey, modeKey, create)
	UnBotSquadBuilderEnsureConfig();
	local bossPresets = UnBotSquadConfig.bossPresets[bossKey];
	local preset = bossPresets and bossPresets[modeKey];
	if (type(preset) == "table") then
		return preset;
	end
	if (not create) then
		return nil;
	end
	UnBotSquadConfig.bossPresets[bossKey] = bossPresets or {};
	preset = {};
	UnBotSquadConfig.bossPresets[bossKey][modeKey] = preset;
	return preset;
end

UnBotBossPresetGuide = UnBotBossPresetGuide or {
	active = nil,
	editor = nil,
	startEditor = nil,
};

function UnBotBossPresetGuideSections(preset)
	local sections = {};
	local raw = tostring(preset and preset.guideText or "");
	raw = string.gsub(raw, "\r\n", "\n");
	local current;
	for line in string.gmatch(raw.."\n", "(.-)\n") do
		local label = string.match(line, "^%s*%[(.-)%]%s*$");
		if (label and label ~= "") then
			current = { label = label, lines = {} };
			table.insert(sections, current);
		else
			if (not current) then
				current = { label = "Общее", lines = {} };
				table.insert(sections, current);
			end
			table.insert(current.lines, line);
		end
	end
	for _, section in ipairs(sections) do
		section.text = table.concat(section.lines, "\n");
		section.text = string.gsub(section.text, "^%s+", "");
		section.text = string.gsub(section.text, "%s+$", "");
		section.lines = nil;
	end
	return sections;
end

function UnBotBossPresetGuidePrint(title, text)
	UnBotSpecSummonMessage("|cff33ccffПамятка: "..tostring(title).."|r");
	for line in string.gmatch(tostring(text or "").."\n", "(.-)\n") do
		if (line ~= "") then
			local remaining = line;
			while (#remaining > 230) do
				local cut = 230;
				local prefix = string.sub(remaining, 1, cut);
				local space = string.match(prefix, "^.*()%s+");
				if (space and space > 80) then
					cut = space;
				end
				UnBotSpecSummonMessage(string.sub(remaining, 1, cut));
				remaining = string.gsub(string.sub(remaining, cut + 1), "^%s+", "");
			end
			if (remaining ~= "") then
				UnBotSpecSummonMessage(remaining);
			end
		end
	end
end

function UnBotBossPresetGuideShowStartWarning(bossKey, modeKey)
	local preset = UnBotBossPresetEditableGet(bossKey, modeKey, false) or {};
	local hasStoredMessage = type(preset.startMessage) == "string";
	local text = hasStoredMessage
		and preset.startMessage
		or (UnBotBossPresetBuiltinStartMessage(bossKey, modeKey) or "");
	if (text == "" and not hasStoredMessage) then
		local sections = UnBotBossPresetGuideSections(preset);
		for _, section in ipairs(sections) do
			local normalizedLabel = UnBotSpecSummonNormalize(section.label);
			if (
				normalizedLabel == "старт"
				or normalizedLabel == "Старт"
				or normalizedLabel == "СТАРТ"
				or normalizedLabel == "start"
			) then
				text = tostring(section.text or "");
				break
			end
		end
	end
	if (text == "") then
		return false;
	end
	if (RaidNotice_AddMessage and RaidWarningFrame) then
		RaidNotice_AddMessage(
			RaidWarningFrame,
			text,
			ChatTypeInfo and ChatTypeInfo["RAID_WARNING"]
		);
	elseif (UIErrorsFrame) then
		UIErrorsFrame:AddMessage(text, 1, 0.15, 0.15, 1);
	end
	if (PlaySound) then
		PlaySound("RaidWarning");
	end
	UnBotSpecSummonMessage(
		"Тактика перед пулом: "..string.gsub(text, "\n", " ")
	);
	local active = UnBotBossPresetGuide.active;
	if (
		active
		and active.bossKey == bossKey
		and active.modeKey == modeKey
	) then
		active.startWarningShown = true;
	end
	return true;
end

function UnBotBossPresetGuideActivate(bossKey, modeKey, preset, autoCombat)
	local sections = UnBotBossPresetGuideSections(preset);
	if (#sections == 0) then
		UnBotBossPresetGuide.active = nil;
		return false;
	end
	local boss = UnBotBossPresetFindBoss(bossKey);
	local mode = UnBotBossPresetFindMode(modeKey);
	UnBotBossPresetGuide.active = {
		bossKey = bossKey,
		modeKey = modeKey,
		bossLabel = boss and boss.label or bossKey,
		modeLabel = mode and mode.label or modeKey,
		sections = sections,
		currentIndex = 1,
		inCombat = false,
		autoCombat = autoCombat and true or false,
		startWarningShown = false,
	};
	UnBotBossPresetGuidePrint(
		UnBotBossPresetGuide.active.bossLabel.." — "
		..UnBotBossPresetGuide.active.modeLabel.." — "..sections[1].label,
		sections[1].text
	);
	if (#sections > 1) then
		UnBotSpecSummonMessage(
			"Следующая секция памятки: /ubphase next (всего "
			..tostring(#sections)..")."
		);
	end
	return true;
end

function UnBotBossPresetGuideSelectSolo(bossKey, modeKey, preset)
	preset = preset or UnBotBossPresetEditableGet(bossKey, modeKey, false) or {};
	local guideText = type(preset.guideText) == "string"
		and preset.guideText
		or (UnBotBossPresetBuiltinGuide(bossKey, modeKey) or "");
	local startMessage = type(preset.startMessage) == "string"
		and preset.startMessage
		or (UnBotBossPresetBuiltinStartMessage(bossKey, modeKey) or "");
	if (guideText == "" and startMessage == "") then
		UnBotBossPresetGuide.active = nil;
		return false;
	end
	return UnBotBossPresetGuideActivate(
		bossKey,
		modeKey,
		{
			guideText = guideText ~= "" and guideText
				or "[Общее]\nСтартовая подсказка для соло-боя активирована и появится при входе в бой.",
		},
		true
	);
end

function UnBotBossPresetGuideShowPhase(wanted)
	local active = UnBotBossPresetGuide.active;
	if (not active or not active.sections or #active.sections == 0) then
		UnBotSpecSummonMessage("Нет активной памятки пресета.");
		return false;
	end
	local index = tonumber(wanted);
	local command = UnBotSpecSummonNormalize(wanted or "next");
	if (command == "next" or command == "") then
		index = math.min(#active.sections, (active.currentIndex or 1) + 1);
	elseif (command == "prev" or command == "previous") then
		index = math.max(1, (active.currentIndex or 1) - 1);
	elseif (not index) then
		for candidateIndex, section in ipairs(active.sections) do
			if (UnBotSpecSummonNormalize(section.label) == command) then
				index = candidateIndex;
				break
			end
		end
	end
	if (not index or not active.sections[index]) then
		UnBotSpecSummonMessage("Секция памятки не найдена: "..tostring(wanted)..".");
		return false;
	end
	active.currentIndex = index;
	local section = active.sections[index];
	UnBotBossPresetGuidePrint(
		active.bossLabel.." — "..active.modeLabel.." — "..section.label,
		section.text
	);
	return true;
end

UnBotBossPresetGuideFrame = UnBotBossPresetGuideFrame
	or CreateFrame("Frame", "UnBotBossPresetGuideFrame");
UnBotBossPresetGuideFrame:RegisterEvent("PLAYER_REGEN_DISABLED");
UnBotBossPresetGuideFrame:RegisterEvent("PLAYER_REGEN_ENABLED");
UnBotBossPresetGuideFrame:SetScript("OnEvent", function(self, event)
	local active = UnBotBossPresetGuide.active;
	if (not active) then
		return;
	end
	if (
		event == "PLAYER_REGEN_DISABLED"
		and active.autoCombat
		and not active.inCombat
	) then
		active.inCombat = true;
		active.currentIndex = 1;
		if (not active.startWarningShown) then
			UnBotBossPresetGuideShowStartWarning(active.bossKey, active.modeKey);
		end
		if (#active.sections > 1) then
			UnBotBossPresetGuideShowPhase(2);
		end
	elseif (event == "PLAYER_REGEN_ENABLED") then
		active.inCombat = false;
		active.startWarningShown = false;
	end
end);

SLASH_UNBOTPRESETPHASE1 = "/ubphase";
SLASH_UNBOTPRESETPHASE2 = "/ubguide";
SlashCmdList["UNBOTPRESETPHASE"] = function(message)
	UnBotBossPresetGuideShowPhase(message);
end

function UnBotBossPresetSave(bossKey, modeKey)
	UnBotSquadBuilderEnsureConfig();
	local boss = UnBotBossPresetFindBoss(bossKey);
	local mode = UnBotBossPresetFindMode(modeKey);
	local botCount = UnBotSquadBuilderBotCount();
	if (not boss or not mode) then
		return;
	end
	if (botCount == 0) then
		UnBotSpecSummonMessage(
			"Пресет босса "..boss.label.." ("..mode.label
			.."): сначала добавьте участников."
		);
		return;
	end
	if (UnBotBossPresetBackupStore) then
		UnBotBossPresetBackupStore(bossKey, modeKey);
	end
	local previousPreset = UnBotSquadConfig.bossPresets[bossKey]
		and UnBotSquadConfig.bossPresets[bossKey][modeKey];
	UnBotSquadConfig.bossPresets[bossKey] =
		UnBotSquadConfig.bossPresets[bossKey] or {};
	UnBotAuthorPresets.StorePersonal(UnBotSquadConfig, bossKey, modeKey, {
		requirements = UnBotSquadBuilderCopySlots(UnBotSquadConfig.slots),
        lichKingComposition116 = previousPreset and previousPreset.lichKingComposition116,
        lichKingCompositionBefore116 = previousPreset and previousPreset.lichKingCompositionBefore116,
        lichKingCompactTest119 = previousPreset and previousPreset.lichKingCompactTest119,
        lichKingBeforeCompactTest119 = previousPreset and previousPreset.lichKingBeforeCompactTest119,
		storageMode = "class-spec+account-alt",
		schemaVersion = 3,
		includeResurrectionReserve = UnBotSquadConfig.includeResurrectionReserve and true or false,
		resurrectionReserveCount = UnBotSquadReserveCount(UnBotSquadConfig.resurrectionReserveCount),
		savedAt = date("%Y-%m-%d %H:%M:%S"),
		source = "saved class/spec requirements and named account alts",
		guideText = previousPreset and previousPreset.guideText
			or UnBotBossPresetBuiltinGuide(bossKey, modeKey),
		guideUpdatedAt = previousPreset and previousPreset.guideUpdatedAt,
		startMessage = previousPreset and previousPreset.startMessage
			or UnBotBossPresetBuiltinStartMessage(bossKey, modeKey),
		startMessageUpdatedAt = previousPreset and previousPreset.startMessageUpdatedAt,
		autoStrategyEnabled = previousPreset
			and previousPreset.autoStrategyEnabled ~= false,
		autoStrategyUpdatedAt = previousPreset and previousPreset.autoStrategyUpdatedAt,
		autoGuideOnTargetEnabled = previousPreset
			and previousPreset.autoGuideOnTargetEnabled == true,
		autoGuideOnTargetUpdatedAt = previousPreset
			and previousPreset.autoGuideOnTargetUpdatedAt,
		masterLootEnabled = not previousPreset
			or previousPreset.masterLootEnabled ~= false,
		masterLootUpdatedAt = previousPreset
			and previousPreset.masterLootUpdatedAt,
	}, previousPreset);
	UnBotSpecSummonMessage(
		"Пресет босса "..boss.label.." ("..mode.label..") сохранён: "
		..tostring(botCount).." ботов; сохранены только классы, спеки и количество."
	);
	if (UnBotBossPresetWindowRefresh) then
		UnBotBossPresetWindowRefresh();
	end
end

function UnBotBossPresetDelete(bossKey, modeKey)
	UnBotSquadBuilderEnsureConfig();
	UnBotBossPresetBackupStore(bossKey, modeKey);
	UnBotAuthorPresets.MarkPersonal(UnBotSquadConfig, bossKey, modeKey);
	local boss = UnBotBossPresetFindBoss(bossKey);
	local mode = UnBotBossPresetFindMode(modeKey);
	if (UnBotSquadConfig.bossPresets[bossKey]) then
		UnBotSquadConfig.bossPresets[bossKey][modeKey] = nil;
	end
	if (boss and mode) then
		UnBotSpecSummonMessage(
			"Пресет босса "..boss.label.." ("..mode.label..") удалён."
		);
	end
	if (UnBotBossPresetWindowRefresh) then
		UnBotBossPresetWindowRefresh();
	end
end

function UnBotBossPresetDisarmAutomaticStrategies(keepMasterLoot)
	if (UnBotViscidus and UnBotViscidus.Stop) then
		UnBotViscidus:Stop("автостратегия отключена");
	end
	if (UnBotSvalnaControl and UnBotSvalnaControl.armed and UnBotSvalnaDisarm) then
		UnBotSvalnaDisarm(true);
	end
	if (
		UnBotValithriaHeal
		and (
			UnBotValithriaHeal.armed
			or UnBotValithriaHeal.prepared
			or UnBotValithriaHeal.active
			or next(UnBotValithriaHeal.allHealers or {})
		)
		and UnBotValithriaDisarm
	) then
		UnBotValithriaDisarm(true);
	end
	if (
		UnBotPutricideDrink
		and (
			UnBotPutricideDrink.armed
			or UnBotPutricideDrink.active
			or UnBotPutricideDrink.bossOnlyMode
			or UnBotPutricideDrink.normalAnchorMode
		)
		and UnBotPutricideDisarm
	) then
		UnBotPutricideDisarm();
	end
	if (UnBotSindragosaPrep) then
		if (
			(UnBotSindragosaPrep.iccSuppressed or UnBotSindragosaPrep.encounterActive)
			and UnBotSindragosaRestoreIcc
		) then
			UnBotSindragosaRestoreIcc("автостратегия отключена", true);
		end
		if (UnBotSindragosaReleaseFrostResistanceAura) then
			UnBotSindragosaReleaseFrostResistanceAura();
		end
		if (UnBotSindragosaReleaseBubbleReserve) then
			UnBotSindragosaReleaseBubbleReserve("автостратегия отключена", true);
		end
		if (
			UnBotSindragosaPrep.armed
			or UnBotSindragosaPrep.active
			or UnBotSindragosaPrep.maintenance
		) then
			UnBotSindragosaStopSoulstone(nil, false);
		end
		UnBotSindragosaPrep.armed = false;
		UnBotSindragosaPrep.active = false;
		UnBotSindragosaPrep.maintenance = false;
		UnBotSindragosaPrep.focusEnabled = false;
		UnBotSindragosaPrep.encounterActive = false;
	end
	if (UnBotDeathwhisperControl and UnBotDeathwhisperControl.armed and UnBotDeathwhisperDisarm) then
		UnBotDeathwhisperDisarm(true);
	end
	if (
		not keepMasterLoot
		and UnBotGunshipMasterLoot
		and UnBotGunshipMasterLoot.active
		and UnBotGunshipMasterLootDisarm
	) then
		UnBotGunshipMasterLootDisarm(true);
	end
	if (
		UnBotMarrowgarRescue
		and (UnBotMarrowgarRescue.presetArmed or UnBotMarrowgarRescue.iccSuppressed)
		and UnBotMarrowgarDisarmPreset
	) then
		UnBotMarrowgarDisarmPreset(true);
	end
	if (UnBotSaurfangBeastFocus and UnBotSaurfangBeastFocus.active and UnBotSaurfangStopBeastFocus) then
		UnBotSaurfangStopBeastFocus();
	end
end

function UnBotBossPresetArmSpecialBehavior(bossKey, modeKey)
	UnBotBossPresetDisarmAutomaticStrategies(true);
	if (UnBotBossPresetArmMasterLoot) then
		UnBotBossPresetArmMasterLoot(bossKey, modeKey);
	end
	if (not UnBotBossPresetAutoStrategyEnabled(bossKey, modeKey)) then
		return false;
	end
	if (bossKey == "sister_svalna" and UnBotSvalnaPreparePreset) then
		UnBotSvalnaPreparePreset(modeKey);
	end
	if (bossKey == "valithria_dreamwalker") then
		UnBotValithriaHeal.armed = true;
		UnBotValithriaHeal.active = false;
		UnBotValithriaHeal.prepared = false;
	end
	if (bossKey == "sindragosa") then
		UnBotSindragosaPrep.armed = true;
		UnBotSindragosaPrep.active = false;
		UnBotSindragosaPrep.maintenance = true;
		UnBotSindragosaPrep.focusEnabled = true;
		UnBotSindragosaPrep.readyAt = GetTime() + 3;
		UnBotSindragosaPrep.lastTombGuid = nil;
	end
	if (bossKey == "lady_deathwhisper" and UnBotDeathwhisperArm) then
		UnBotDeathwhisperArm(modeKey);
	end
	return true;
end

function UnBotBossPresetLoad(bossKey, modeKey, summonNow)
	local boss = UnBotBossPresetFindBoss(bossKey);
	local mode = UnBotBossPresetFindMode(modeKey);
	local preset = UnBotBossPresetGet(bossKey, modeKey);
	UnBotSquadBuilder.loadedBossPreset = nil;
	if (not boss or not mode) then
		return;
	end
	UnBotBossPresetDisarmAutomaticStrategies(true);
	if (UnBotBossPresetArmMasterLoot) then
		UnBotBossPresetArmMasterLoot(bossKey, modeKey);
	end
	if (not preset) then
		local editable = UnBotBossPresetEditableGet(bossKey, modeKey, false) or {};
		if (UnBotBossPresetGuideSelectSolo(bossKey, modeKey, editable)) then
			UnBotSpecSummonMessage(
				boss.label.." ("..mode.label
				.."): состав пуст; соло-подсказки активированы для следующего боя."
			);
		else
			UnBotSpecSummonMessage(
				"Пресет босса "..boss.label.." ("..mode.label
				..") пока пуст; подсказки ещё не заполнены."
			);
		end
		return;
	end
	UnBotSquadBuilderSetSlots(
		UnBotBossPresetRequirements(preset)
	);
	UnBotSquadConfig.resurrectionReserveCount = 0;
	UnBotSquadConfig.includeResurrectionReserve = false;
	if (UnBotSquadBuilder.scrollFrame) then
		UnBotSquadBuilder.scrollFrame:SetVerticalScroll(0);
	end
	UnBotSquadBuilderRefresh();
	UnBotSpecSummonMessage(
		"Пресет босса "..boss.label.." ("..mode.label..") загружен: "
		..tostring(UnBotSquadBuilderBotCount())
		.." ботов по классу/спеку; имена будут выбраны из реестра."
	);
	UnBotSquadBuilder.loadedBossPreset = {
		bossKey = bossKey,
		modeKey = modeKey,
	};
	UnBotBossPresetGuideActivate(bossKey, modeKey, preset, summonNow);
	if (UnBotBossPresetAutoStrategyDescription(bossKey, modeKey)) then
		UnBotSpecSummonMessage(
			"Автостратегия "
			..(UnBotBossPresetAutoStrategyEnabled(bossKey, modeKey, preset)
				and "|cff33ff66ВКЛ|r"
				or "|cffff6060ВЫКЛ|r")
			.." для "..boss.label.." ("..mode.label..")."
		);
	end
	if (not summonNow) then
		if (UnBotBossPresetAutoStrategyEnabled(bossKey, modeKey, preset)) then
			if (bossKey == "sister_svalna" and UnBotSvalnaPreparePreset) then
				UnBotSvalnaPreparePreset(modeKey);
			elseif (bossKey == "lady_deathwhisper" and UnBotDeathwhisperArm) then
				UnBotDeathwhisperArm(modeKey);
			end
		end
		return;
	end
	UnBotBossPresetArmSpecialBehavior(bossKey, modeKey);
	UnBotSquadBuilder.pendingBossPreset = {
		bossKey = bossKey,
		modeKey = modeKey,
	};
	UnBotSquadBuilderStart(true);
end

function UnBotBossPresetModeAction(bossKey, modeKey)
	return function()
		if (IsControlKeyDown()) then
			UnBotBossPresetSave(bossKey, modeKey);
		elseif (IsAltKeyDown()) then
			UnBotBossPresetDelete(bossKey, modeKey);
		else
			UnBotBossPresetLoad(bossKey, modeKey, IsShiftKeyDown());
		end
	end
end

function UnBotBossPresetBuildMenu()
	UnBotSquadBuilderEnsureConfig();
	local menu = {
		{
			text = "Пресеты боссов ЦЛК",
			isTitle = true,
			notCheckable = true,
		},
		{
			text = "ЛКМ: загрузить | Shift+ЛКМ: призвать | Ctrl: сохранить | Alt: удалить",
			isTitle = true,
			notCheckable = true,
		},
	};
	for _, boss in ipairs(UnBotBossPresetBosses) do
		local bossMenu = {};
		for _, mode in ipairs(UnBotBossPresetModesForBoss("raid", boss.key)) do
			local preset = UnBotBossPresetGet(boss.key, mode.key);
			local suffix = preset
				and (" | "..tostring(UnBotSquadBuilderSlotsCount(
					UnBotBossPresetRequirements(preset)
				)).." ботов")
				or " | пусто";
			table.insert(bossMenu, {
				text = mode.label..suffix,
				notCheckable = true,
				func = UnBotBossPresetModeAction(boss.key, mode.key),
			});
		end
		table.insert(menu, {
			text = boss.label,
			notCheckable = true,
			hasArrow = true,
			menuList = bossMenu,
		});
	end
	return menu;
end

