UnBotBossPresetCatalog = UnBotBossPresetCatalog or {
	expanded = false,
	instanceType = "raid",
	raidExpansion = "wotlk",
	instances = {},
	bossByKey = {},
	instanceOffset = 0,
	bossOffset = 0,
	selectedInstance = nil,
	selectedBossKey = nil,
	selectedModeKey = nil,
	instanceButtons = {},
	bossButtons = {},
	modeButtons = {},
	reserveButtons = {},
	expansionButtons = {},
};

UnBotBossPresetCatalog.raidExpansion = UnBotBossPresetCatalog.raidExpansion or "wotlk";
UnBotBossPresetCatalog.expansionButtons = UnBotBossPresetCatalog.expansionButtons or {};

function UnBotBossPresetSlug(text)
	local value = string.lower(tostring(text or ""));
	value = string.gsub(value, "[^%w]+", "_");
	value = string.gsub(value, "^_+", "");
	value = string.gsub(value, "_+$", "");
	return value;
end

function UnBotBossPresetCatalogKey(instanceName, bossName)
	if (instanceName == "Icecrown Citadel") then
		local legacy = {
			["Lord Marrowgar"] = "lord_marrowgar",
			["Lady Deathwhisper"] = "lady_deathwhisper",
			["Gunship Battle"] = "gunship_battle",
			["Deathbringer Saurfang"] = "deathbringer_saurfang",
			["Festergut"] = "festergut",
			["Rotface"] = "rotface",
			["Professor Putricide"] = "professor_putricide",
			["Blood Prince Council"] = "blood_princes",
			["Blood-Queen Lana'thel"] = "blood_queen_lanathel",
			["Sister Svalna"] = "sister_svalna",
			["Valithria Dreamwalker"] = "valithria_dreamwalker",
			["Sindragosa"] = "sindragosa",
			["The Lich King"] = "the_lich_king",
		};
		if (legacy[bossName]) then
			return legacy[bossName];
		end
	end
	return UnBotBossPresetSlug(instanceName).."__"..UnBotBossPresetSlug(bossName);
end

function UnBotBossPresetCatalogRebuild()
	local catalog = UnBotBossPresetCatalog;
	catalog.instances = {};
	catalog.bossByKey = {};
	local source = BossMemoryBossCatalog;
	if (type(source) ~= "table" or #source == 0) then
		source = {
			{
				instance = "Icecrown Citadel",
				instanceType = "raid",
				expansion = "wotlk",
				raidSize = 25,
				bosses = {
					{ name = "Lord Marrowgar" },
					{ name = "Lady Deathwhisper" },
					{ name = "Gunship Battle" },
					{ name = "Deathbringer Saurfang" },
					{ name = "Festergut" },
					{ name = "Rotface" },
					{ name = "Professor Putricide" },
					{ name = "Blood Prince Council" },
					{ name = "Blood-Queen Lana'thel" },
					{ name = "Sister Svalna" },
					{ name = "Valithria Dreamwalker" },
					{ name = "Sindragosa" },
					{ name = "The Lich King" },
				},
			},
		};
	end
	for _, sourceInstance in ipairs(source) do
		local instance = {
			name = sourceInstance.instance,
			displayName = UnBotBossPresetInstanceLabels[sourceInstance.instance]
				or sourceInstance.instance,
			instanceType = sourceInstance.instanceType or "raid",
			expansion = sourceInstance.expansion or "wotlk",
			raidSize = sourceInstance.raidSize,
			bosses = {},
		};
		for _, sourceBoss in ipairs(sourceInstance.bosses or {}) do
			local boss = {
				key = UnBotBossPresetCatalogKey(instance.name, sourceBoss.name),
				label = UnBotBossPresetBossLabels[sourceBoss.name] or sourceBoss.name,
				instance = instance.name,
				instanceType = instance.instanceType,
				expansion = instance.expansion,
				raidSize = instance.raidSize,
			};
			table.insert(instance.bosses, boss);
			catalog.bossByKey[boss.key] = boss;
		end
		if (instance.name == "Icecrown Citadel") then
			local hasGunship = false;
			for _, boss in ipairs(instance.bosses) do
				if (boss.key == "gunship_battle") then
					hasGunship = true;
				end
			end
			if (not hasGunship) then
				local gunship = {
					key = "gunship_battle",
					label = UnBotBossPresetBossLabels["Gunship Battle"],
					instance = instance.name,
					instanceType = "raid",
				};
				table.insert(instance.bosses, 3, gunship);
				catalog.bossByKey[gunship.key] = gunship;
			end
		elseif (instance.name == "Trial of the Crusader") then
			local champions = {
				key = UnBotBossPresetCatalogKey(instance.name, "Faction Champions"),
				label = UnBotBossPresetBossLabels["Faction Champions"],
				instance = instance.name,
				instanceType = "raid",
			};
			table.insert(instance.bosses, 3, champions);
			catalog.bossByKey[champions.key] = champions;
		end
		table.insert(catalog.instances, instance);
	end
end

function UnBotBossPresetFindBoss(bossKey)
	for _, boss in ipairs(UnBotBossPresetBosses) do
		if (boss.key == bossKey) then
			return boss;
		end
	end
	if (
		not UnBotBossPresetCatalog.bossByKey
		or not UnBotBossPresetCatalog.bossByKey[bossKey]
	) then
		UnBotBossPresetCatalogRebuild();
	end
	return UnBotBossPresetCatalog.bossByKey[bossKey];
end

function UnBotBossPresetFindMode(modeKey)
	if modeKey == "40n_corridor" then return { key = "40n_corridor", label = "40 — коридор" }; end
	if modeKey == "40n_full" then return { key = "40n_full", label = "40 — полный" }; end
	if modeKey == "40n_intercept" then return { key = "40n_intercept", label = "40 — перехват" }; end
	if (UnBotBossPresetTwinsPlayerMode.key == modeKey) then return UnBotBossPresetTwinsPlayerMode; end
	if (UnBotBossPresetTwinsSmallMode.key == modeKey) then return UnBotBossPresetTwinsSmallMode; end
	for _, mode in ipairs(UnBotBossPresetModes) do
		if (mode.key == modeKey) then
			return mode;
		end
	end
	if (UnBotBossPresetValithria18Mode.key == modeKey) then
		return UnBotBossPresetValithria18Mode;
	end
	if (UnBotBossPresetClassic20Mode.key == modeKey) then
		return UnBotBossPresetClassic20Mode;
	end
	if (UnBotBossPresetClassic40Mode.key == modeKey) then
		return UnBotBossPresetClassic40Mode;
	end
	for _, mode in ipairs(UnBotBossPresetDungeonModes) do
		if (mode.key == modeKey) then
			return mode;
		end
	end
	return nil;
end

UnBotBossPresetAutoGuide = UnBotBossPresetAutoGuide or {};

function UnBotBossPresetAutoGuideModeKey(
	instanceType,
	difficultyIndex,
	maxPlayers,
	difficultyMode
)
	local index = tonumber(difficultyIndex) or 0;
	local size = tonumber(maxPlayers) or 0;
	local heroic = tostring(difficultyMode or "") == "heroic";
	if (instanceType == "party") then
		return (heroic or index == 2) and "5h" or "5n";
	end
	if (instanceType ~= "raid") then
		return nil;
	end
	if (index == 1) then
		return "10n";
	elseif (index == 2) then
		return "25n";
	elseif (index == 3) then
		return "10h";
	elseif (index == 4) then
		return "25h";
	end
	if (heroic) then
		return size >= 25 and "25h" or "10h";
	end
	return size >= 25 and "25n" or "10n";
end

function UnBotBossPresetAutoGuideEnabled(bossKey, modeKey)
	local preset = UnBotBossPresetEditableGet(bossKey, modeKey, false);
	return preset and preset.autoGuideOnTargetEnabled == true;
end

function UnBotBossPresetAutoGuideResolveMode(bossKey, baseModeKey)
	if bossKey == "temple_of_ahn_qiraj__the_twin_emperors" then return UnBotBossPresetTwinsPlayerMode.key; end
	local loaded = UnBotSquadBuilder.loadedBossPreset;
	local selectedBossKey = UnBotBossPresetCatalog.selectedBossKey;
	local selectedModeKey = UnBotBossPresetCatalog.selectedModeKey;
	local function compatible(modeKey)
		return modeKey == baseModeKey
			or (bossKey == "temple_of_ahn_qiraj__the_twin_emperors" and baseModeKey == "40n" and (modeKey == "40n6" or modeKey == "40n5"))
			or (bossKey == "naxxramas__gluth" and baseModeKey == "40n" and (modeKey == "40n_corridor" or modeKey == "40n_full" or modeKey == "40n_intercept"))
			or (baseModeKey == "25h" and modeKey == "25h18");
	end
	if (
		loaded
		and loaded.bossKey == bossKey
		and compatible(loaded.modeKey)
		and UnBotBossPresetAutoGuideEnabled(bossKey, loaded.modeKey)
	) then
		return loaded.modeKey;
	end
	if (
		selectedBossKey == bossKey
		and compatible(selectedModeKey)
		and UnBotBossPresetAutoGuideEnabled(bossKey, selectedModeKey)
	) then
		return selectedModeKey;
	end
	if (UnBotBossPresetAutoGuideEnabled(bossKey, baseModeKey)) then
		return baseModeKey;
	end
	if (
		baseModeKey == "25h"
		and UnBotBossPresetAutoGuideEnabled(bossKey, "25h18")
	) then
		return "25h18";
	end
	return nil;
end

function UnBotBossPresetPreferredMode(bossKey, baseModeKey)
	if bossKey == "temple_of_ahn_qiraj__the_twin_emperors" then return UnBotBossPresetTwinsPlayerMode.key; end
	local loaded = UnBotSquadBuilder.loadedBossPreset;
	local selectedBossKey = UnBotBossPresetCatalog.selectedBossKey;
	local selectedModeKey = UnBotBossPresetCatalog.selectedModeKey;
	local function compatible(modeKey)
		return modeKey == baseModeKey
			or (bossKey == "temple_of_ahn_qiraj__the_twin_emperors" and baseModeKey == "40n" and (modeKey == "40n6" or modeKey == "40n5"))
			or (bossKey == "naxxramas__gluth" and baseModeKey == "40n" and (modeKey == "40n_corridor" or modeKey == "40n_full" or modeKey == "40n_intercept"))
			or (baseModeKey == "25h" and modeKey == "25h18");
	end
	if (
		loaded
		and loaded.bossKey == bossKey
		and compatible(loaded.modeKey)
	) then
		return loaded.modeKey;
	end
	if (selectedBossKey == bossKey and compatible(selectedModeKey)) then
		return selectedModeKey;
	end
	return baseModeKey;
end

function UnBotBossPresetMasterLootEnabled(...)
	return UnBotLootSettings.Get().bossSelection;
end

function UnBotBossPresetTargetBoss(
	instanceName,
	bossName,
	targetGuid,
	instanceType,
	difficultyIndex,
	maxPlayers,
	difficultyMode
)
	local bossKey = UnBotBossPresetCatalogKey(instanceName, bossName);
	local boss = UnBotBossPresetFindBoss(bossKey);
	local baseModeKey = UnBotBossPresetAutoGuideModeKey(
		instanceType,
		difficultyIndex,
		maxPlayers,
		difficultyMode
	);
	local modeKey = baseModeKey
		and UnBotBossPresetAutoGuideResolveMode(bossKey, baseModeKey);
	if (not boss or not modeKey) then
		return false;
	end
	local active = UnBotBossPresetGuide.active;
	if (
		active
		and active.bossKey == bossKey
		and active.modeKey == modeKey
	) then
		active.targetGuid = targetGuid or active.targetGuid;
		return true;
	end
	local preset = UnBotBossPresetEditableGet(bossKey, modeKey, false) or {};
	if (not UnBotBossPresetGuideSelectSolo(bossKey, modeKey, preset)) then
		return false;
	end
	active = UnBotBossPresetGuide.active;
	if (active) then
		active.autoTarget = true;
		active.targetGuid = targetGuid;
		if (UnitAffectingCombat("player")) then
			active.inCombat = true;
			UnBotBossPresetGuideShowStartWarning(bossKey, modeKey);
			if (#active.sections > 1) then
				UnBotBossPresetGuideShowPhase(2);
			end
		end
	end
	UnBotBossPresetAutoGuide.bossKey = bossKey;
	UnBotBossPresetAutoGuide.modeKey = modeKey;
	UnBotBossPresetAutoGuide.targetGuid = targetGuid;
	UnBotSpecSummonMessage(
		"Автоподсказка по цели: "..boss.label.." ("
		..tostring((UnBotBossPresetFindMode(modeKey) or {}).label or modeKey)
		.."). Состав и автостратегия не запускались."
	);
	return true;
end

function UnBotBossPresetAttemptFinished(
	instanceName,
	bossName,
	result
)
	if (result ~= "kill" and result ~= "wipe") then
		return false;
	end
	local bossKey = UnBotBossPresetCatalogKey(instanceName, bossName);
	local active = UnBotBossPresetGuide.active;
	if (not active or active.bossKey ~= bossKey) then
		return false;
	end
	local boss = UnBotBossPresetFindBoss(bossKey);
	UnBotBossPresetGuide.active = nil;
	UnBotBossPresetAutoGuide.bossKey = nil;
	UnBotBossPresetAutoGuide.modeKey = nil;
	UnBotBossPresetAutoGuide.targetGuid = nil;
	UnBotSpecSummonMessage(
		"Подсказки "..tostring(boss and boss.label or bossName)
		.." отключены после результата BossMemory: "
		..(result == "kill" and "победа" or "вайп").."."
	);
	return true;
end

function UnBotBossPresetBuiltinGet(bossKey, modeKey)
	if UnBotAuthorPresets then
		return UnBotAuthorPresets.BuiltinGet(bossKey, modeKey);
	end
	if bossKey == "the_lich_king" and (modeKey == "25n" or modeKey == "25h") then
		return {}, "Соло: при достаточном DPS и самохиле. Групповой состав не подтверждён", 0,
			UnBotBossPresetBuiltinGuide(bossKey, modeKey), UnBotBossPresetBuiltinStartMessage(bossKey, modeKey);
	end
	if bossKey == "the_ruby_sanctum__halion" then
		return {
			{className="paladin", specKey="ret", label="Paladin - Retribution (DPS)", count=2},
		}, "Халион: игрок + два ретри-паладина; co -rs", 0,
			UnBotBossPresetBuiltinGuide(bossKey, modeKey), UnBotBossPresetBuiltinStartMessage(bossKey, modeKey);
	end
	if bossKey == "the_lich_king" then
		return {
			{className="paladin",specKey="prot",label="Paladin - Protection (Tank)",count=1},
			{className="priest",specKey="disc",label="Priest - Discipline (Heal)",count=1},
			{className="shaman",specKey="enh",label="Shaman - Enhancement (DPS)",count=1},
		}, "ТЕСТ: игрок-ретрик + прот-паладин + ДЦ-прист + энх-шаман; победа не подтверждена", 0,
			UnBotBossPresetBuiltinGuide(bossKey, modeKey), UnBotBossPresetBuiltinStartMessage(bossKey, modeKey);
	end

	if (bossKey == "lord_marrowgar" and modeKey == "25h") then
		return UnBotMarrowgar25HeroicPresetSlots,
			"стандарт: успешный Лорд Ребрад 25 гер",
			nil,
			UnBotBossPresetBuiltinGuide(bossKey, modeKey),
			UnBotBossPresetBuiltinStartMessage(bossKey, modeKey);
	elseif (bossKey == "deathbringer_saurfang" and modeKey == "25h") then
		return UnBotSaurfang25HeroicPresetSlots,
			"стандарт: успешный Саурфанг 25 гер";
	elseif (bossKey == "festergut" and modeKey == "25h") then
		return UnBotFestergut25HeroicPresetSlots,
			"стандарт: Тухлопуз 25 гер — 2 танка, хил и 3 мили-ДД";
	elseif (bossKey == "rotface" and modeKey == "25h") then
		return UnBotSaurfang25HeroicPresetSlots,
			"стандарт: подтверждённый Гниломорд 25 гер";
	elseif (bossKey == "professor_putricide" and modeKey == "25n") then
		return UnBotPutricide25NormalPresetSlots,
			"стандарт: Мерзоцид 25 — игрок управляет поганищем, Protection Paladin стоит танком-якорем",
			0,
			UnBotBossPresetBuiltinGuide(bossKey, modeKey);
	elseif (bossKey == "professor_putricide" and modeKey == "25h") then
		return UnBotPutricide25HeroicPresetSlots,
			"эксперимент: Мерзоцид 25 гер — игрок-танк, Holy Paladin, Combat Rogue и Arms/Fury Warrior";
	elseif (bossKey == "sister_svalna" and modeKey == "25n") then
		return UnBotSvalna25NormalPresetSlots,
			"стандарт: Сестра Свална 25 — игрок, Protection Paladin, Holy Paladin и офлайн-рестор-друид",
			1;
	elseif (bossKey == "valithria_dreamwalker" and modeKey == "10n") then
		return UnBotSquadBuilder.valithriaPresetSlots,
			"стандарт: успешная Валитрия 10";
	elseif (bossKey == "valithria_dreamwalker" and modeKey == "25n") then
		return UnBotValithria25NormalPresetSlots,
			"стандарт: полная Валитрия 25 — 2 танка, 6 хилов, 17 ДД с игроком";
	elseif (bossKey == "valithria_dreamwalker" and modeKey == "25h") then
		return UnBotValithria25HeroicPresetSlots,
			"рабочий: Валитрия 25 гер — 2 танка, 7 хилов, 16 ДД с игроком; усилен прямой хил и контроль аддов",
			nil,
			UnBotBossPresetBuiltinGuide(bossKey, modeKey);
	elseif (bossKey == "valithria_dreamwalker" and modeKey == "25h18") then
		return UnBotValithria25Heroic18PresetSlots,
			"тест победной схемы: Валитрия 25 гер #2 — игрок и бот Retribution, 2 Restoration Druid",
			nil,
			UnBotBossPresetBuiltinGuide(bossKey, modeKey);
	elseif (bossKey == "sindragosa" and modeKey == "25n") then
		return UnBotSindragosaPresetSlots,
			"рабочий перенос с подтверждённой Синдрагосы 25 гер: игрок + 2 Retribution Paladin",
			0,
			UnBotBossPresetBuiltinGuide(bossKey, modeKey);
	elseif (bossKey == "sindragosa" and modeKey == "25h") then
		return UnBotSindragosa25HeroicPresetSlots,
			"рабочий, убийство подтверждено 30.08.2026: игрок + 2 Retribution Paladin",
			0,
			UnBotBossPresetBuiltinGuide(bossKey, modeKey);
	end
	return nil, nil;
end

function UnBotBossPresetBackupStore(bossKey, modeKey)
	UnBotSquadBuilderEnsureConfig();
	local current = UnBotSquadConfig.bossPresets[bossKey]
		and UnBotSquadConfig.bossPresets[bossKey][modeKey];
	if type(current) ~= "table" then return false; end
	UnBotSquadConfig.bossPresetBackups[bossKey] =
		UnBotSquadConfig.bossPresetBackups[bossKey] or {};
	-- Full copy also preserves solo/guide-only presets and future fields.
	UnBotSquadConfig.bossPresetBackups[bossKey][modeKey] = UnBotAuthorPresets.Copy(current);
	return true;
end

function UnBotBossPresetRestoreStandard(bossKey, modeKey)
	UnBotSquadBuilderEnsureConfig();
	local boss = UnBotBossPresetFindBoss(bossKey);
	local mode = UnBotBossPresetFindMode(modeKey);
	if not boss or not mode then return; end
	UnBotBossPresetBackupStore(bossKey, modeKey);
	if UnBotAuthorPresets.ApplyDefault(UnBotSquadConfig, bossKey, modeKey) then
		UnBotSpecSummonMessage(
			"Пресет "..boss.label.." ("..mode.label.."): восстановлен авторский стандарт Теридана."
		);
	else
		UnBotSpecSummonMessage(
			"Для "..boss.label.." ("..mode.label
			..") авторского стандарта пока нет: пользовательский слот очищен, предыдущая версия сохранена."
		);
	end
	UnBotBossPresetCatalogRefresh();
end

function UnBotBossPresetRestorePrevious(bossKey, modeKey)
	UnBotSquadBuilderEnsureConfig();
	local boss = UnBotBossPresetFindBoss(bossKey);
	local mode = UnBotBossPresetFindMode(modeKey);
	local backups = UnBotSquadConfig.bossPresetBackups[bossKey];
	local backup = backups and backups[modeKey];
	if not boss or not mode then return; end
	if type(backup) ~= "table" then
		UnBotSpecSummonMessage(
			"У "..boss.label.." ("..mode.label..") пока нет предыдущей версии."
		);
		return;
	end
	local current = UnBotSquadConfig.bossPresets[bossKey]
		and UnBotSquadConfig.bossPresets[bossKey][modeKey];
	UnBotSquadConfig.bossPresets[bossKey] = UnBotSquadConfig.bossPresets[bossKey] or {};
	UnBotSquadConfig.bossPresets[bossKey][modeKey] = UnBotAuthorPresets.Copy(backup);
	backups[modeKey] = UnBotAuthorPresets.Copy(current);
	UnBotAuthorPresets.MarkPersonal(UnBotSquadConfig, bossKey, modeKey);
	UnBotSpecSummonMessage(
		"Предыдущая версия "..boss.label.." ("..mode.label..") восстановлена."
	);
	UnBotBossPresetCatalogRefresh();
end

UnBotBossPresetPendingAction = nil;

function UnBotBossPresetExecutePendingAction()
	local pending = UnBotBossPresetPendingAction;
	UnBotBossPresetPendingAction = nil;
	if (not pending) then
		return;
	end
	if (pending.action == "save") then
		UnBotBossPresetSave(pending.bossKey, pending.modeKey);
	elseif (pending.action == "standard") then
		UnBotBossPresetRestoreStandard(pending.bossKey, pending.modeKey);
	elseif (pending.action == "previous") then
		UnBotBossPresetRestorePrevious(pending.bossKey, pending.modeKey);
	end
end

StaticPopupDialogs["UNBOT_BOSS_PRESET_CONFIRM"] = {
	text = "%s",
	button1 = YES,
	button2 = NO,
	OnAccept = function()
		UnBotBossPresetExecutePendingAction();
	end,
	OnCancel = function()
		UnBotBossPresetPendingAction = nil;
	end,
	timeout = 0,
	whileDead = 1,
	hideOnEscape = 1,
	preferredIndex = 3,
};

function UnBotBossPresetConfirm(action, bossKey, modeKey)
	local boss = UnBotBossPresetFindBoss(bossKey);
	local mode = UnBotBossPresetFindMode(modeKey);
	if (not boss or not mode) then
		return;
	end
	local text;
	if (action == "save") then
		if (not UnBotSquadBuilderShowCurrentRoster()) then
			return;
		end
		local oldPreset = UnBotBossPresetGet(bossKey, modeKey);
		local oldCount = oldPreset and UnBotSquadBuilderSlotsCount(
			UnBotBossPresetRequirements(oldPreset)
		) or 0;
		local newCount = UnBotSquadBuilderBotCount();
		text =
			"Сохранить КЛАССЫ И СПЕКИ фактического состава для\n"
			..boss.label.." — "..mode.label.."?\n\n"
			.."Новый состав: "..tostring(newCount).." ботов.";
		if (oldCount > 0) then
			text = text.."\nБудет заменён пресет на "..tostring(oldCount)
				.." ботов; прежняя версия останется в резерве.";
		end
	elseif (action == "standard") then
		local slots = UnBotBossPresetBuiltinGet(bossKey, modeKey);
		if (slots) then
			text = "Вернуть авторский пресет Теридана для\n"
				..boss.label.." — "..mode.label
				.."?\n\nБудут восстановлены состав, резерв, памятки и настройки.\nТекущий пресет останется в резерве.";
		else
			text = "Для этого слота ещё нет стандартного состава.\n"
				.."Очистить пользовательский пресет "
				..boss.label.." — "..mode.label
				.."?\n\nТекущий пресет останется в резерве.";
		end
	elseif (action == "previous") then
		text = "Восстановить предыдущую сохранённую версию для\n"
			..boss.label.." — "..mode.label.."?";
	else
		return;
	end
	UnBotBossPresetPendingAction = {
		action = action,
		bossKey = bossKey,
		modeKey = modeKey,
	};
	StaticPopup_Show("UNBOT_BOSS_PRESET_CONFIRM", text);
end

function UnBotBossPresetCatalogFilteredInstances()
	local result = {};
	for _, instance in ipairs(UnBotBossPresetCatalog.instances or {}) do
		if (
			instance.instanceType == UnBotBossPresetCatalog.instanceType
			and (
				instance.instanceType ~= "raid"
				or instance.expansion == UnBotBossPresetCatalog.raidExpansion
			)
		) then
			table.insert(result, instance);
		end
	end
	return result;
end

function UnBotBossPresetCatalogPresetExistsForBoss(bossKey)
	local presets = UnBotSquadConfig
		and UnBotSquadConfig.bossPresets
		and UnBotSquadConfig.bossPresets[bossKey];
	if (not presets) then
		return false;
	end
	for _, preset in pairs(presets) do
		if (UnBotBossPresetRequirements(preset)) then
			return true;
		end
	end
	return false;
end

function UnBotBossPresetCatalogModeTooltip(self)
	local boss = UnBotBossPresetFindBoss(self.bossKey);
	local mode = UnBotBossPresetFindMode(self.modeKey);
	local preset = UnBotBossPresetGet(self.bossKey, self.modeKey);
	local backups = UnBotSquadConfig.bossPresetBackups[self.bossKey];
	local backup = backups and backups[self.modeKey];
	GameTooltip:SetOwner(self, "ANCHOR_TOP");
	GameTooltip:AddLine(
		(boss and boss.label or "?").." — "..(mode and mode.label or "?"),
		1, 0.82, 0, 1
	);
	if UnBotBossPresetEditableGet(self.bossKey, self.modeKey, false) then
		GameTooltip:AddLine(
			UnBotAuthorPresets.IsStandard(UnBotSquadConfig, self.bossKey, self.modeKey)
				and "Авторский стандарт: Теридан" or "Личный пресет (приоритет над авторским)",
			0.4, 0.85, 1, 1
		);
	end
	if (preset) then
		GameTooltip:AddLine(
			"Сохранено классов/спеков: "..tostring(UnBotSquadBuilderSlotsCount(
				UnBotBossPresetRequirements(preset)
			)),
			0, 1, 0, 1
		);
		if (self.modeKey == "25h18") then
			local botCount = UnBotSquadBuilderSlotsCount(
				UnBotBossPresetRequirements(preset)
			);
			GameTooltip:AddLine(
				"Боевой состав: "..tostring(botCount).." бота + игрок = "
				..tostring(botCount + 1).." участника.",
				0.2, 0.8, 1, 1
			);
		end

		if (preset.savedAt) then
			GameTooltip:AddLine("Дата: "..tostring(preset.savedAt), 0.8, 0.8, 0.8, 1);
		end
		local guideSections = UnBotBossPresetGuideSections(preset);
		if (#guideSections > 0) then
			GameTooltip:AddLine(
				"Памятка/фазы: "..tostring(#guideSections).." отдельных кнопок.",
				0.2, 0.8, 1, 1
			);
		end
		GameTooltip:AddLine(
			"Сообщение при старте: "
			..((type(preset.startMessage) == "string" and preset.startMessage ~= "")
				and "настроено" or "выключено"),
			0.95, 0.65, 0.15, 1
		);
		local autoDescription = UnBotBossPresetAutoStrategyDescription(
			self.bossKey,
			self.modeKey
		);
		if (autoDescription) then
			GameTooltip:AddLine(
				"Автостратегия: "
				..(UnBotBossPresetAutoStrategyEnabled(
					self.bossKey,
					self.modeKey,
					preset
				) and "ВКЛ" or "ВЫКЛ"),
				preset.autoStrategyEnabled ~= false and 0.2 or 1,
				preset.autoStrategyEnabled ~= false and 1 or 0.35,
				preset.autoStrategyEnabled ~= false and 0.2 or 0.25,
				1
			);
			GameTooltip:AddLine(autoDescription, 0.85, 0.85, 0.85, true);
		else
			GameTooltip:AddLine(
				"Автостратегия: нет. Пресет меняет только состав; памятки остаются информационными.",
				0.7, 0.7, 0.7, true
			);
		end
		GameTooltip:AddLine(
			"Автоподсказка по цели: "
			..(preset.autoGuideOnTargetEnabled == true and "ВКЛ" or "ВЫКЛ"),
			preset.autoGuideOnTargetEnabled == true and 0.2 or 0.8,
			preset.autoGuideOnTargetEnabled == true and 1 or 0.8,
			preset.autoGuideOnTargetEnabled == true and 0.2 or 0.8,
			1
		);
		GameTooltip:AddLine("Распределение добычи: общие «Настройки добычи».", 0.8, 0.8, 0.8, true);
	else
		GameTooltip:AddLine("Слот пока пуст.", 1, 0.35, 0.25, 1);
	end
	GameTooltip:AddLine("ЛКМ: выбрать и загрузить состав без призыва.", 1, 1, 1, 1);
	GameTooltip:AddLine("Призыв: отдельная кнопка «Призвать» слева.", 0, 1, 0, 1);
	GameTooltip:AddLine("ПКМ: сохранить классы и спеки текущего состава.", 0, 1, 1, 1);
	GameTooltip:AddLine("Shift+ПКМ: вернуть авторский стандарт / очистить слот.", 1, 0.82, 0, 1);
	if (backup) then
		GameTooltip:AddLine("Alt+ПКМ: восстановить предыдущую версию.", 0.7, 1, 0.7, 1);
	end
	GameTooltip:Show();
end

function UnBotBossPresetCatalogModeClick(self, mouseButton)
	UnBotBossPresetCatalog.selectedModeKey = self.modeKey;
	if (mouseButton == "RightButton") then
		if (IsShiftKeyDown()) then
			UnBotBossPresetConfirm("standard", self.bossKey, self.modeKey);
		elseif (IsAltKeyDown()) then
			UnBotBossPresetConfirm("previous", self.bossKey, self.modeKey);
		else
			UnBotBossPresetConfirm("save", self.bossKey, self.modeKey);
		end
	else
		UnBotBossPresetLoad(self.bossKey, self.modeKey, false);
	end
	UnBotBossPresetCatalogRefresh();
end

function UnBotBossPresetSetReserve(bossKey, modeKey, enabled)
	UnBotSpecSummonMessage("Резерв убран из призыва состава. Ручная устаревшая функция находится в меню «Воскрешение».");
	return false;
end

function UnBotBossPresetSetAutoStrategy(bossKey, modeKey, enabled)
	local boss = UnBotBossPresetFindBoss(bossKey);
	local mode = UnBotBossPresetFindMode(modeKey);
	local preset = UnBotBossPresetGet(bossKey, modeKey);
	local description = UnBotBossPresetAutoStrategyDescription(bossKey, modeKey);
	if (not boss or not mode or not preset) then
		UnBotSpecSummonMessage(
			"Сначала сохраните состав для выбранного босса и режима."
		);
		return false;
	end
	if (not description) then
		UnBotSpecSummonMessage(
			boss.label.." ("..mode.label
			.."): автоматические боссовые команды не предусмотрены."
		);
		return false;
	end
	UnBotBossPresetBackupStore(bossKey, modeKey);
	UnBotAuthorPresets.MarkPersonal(UnBotSquadConfig, bossKey, modeKey);
	preset.autoStrategyEnabled = enabled and true or false;
	preset.autoStrategyUpdatedAt = date("%Y-%m-%d %H:%M:%S");
	local loaded = UnBotSquadBuilder.loadedBossPreset;
	if (
		loaded
		and loaded.bossKey == bossKey
		and loaded.modeKey == modeKey
	) then
		UnBotBossPresetDisarmAutomaticStrategies(true);
		if (preset.autoStrategyEnabled) then
			if (bossKey == "sister_svalna" and UnBotSvalnaPreparePreset) then
				UnBotSvalnaPreparePreset(modeKey);
			elseif (bossKey == "lady_deathwhisper" and UnBotDeathwhisperArm) then
				UnBotDeathwhisperArm(modeKey);
			end
		end
	end
	UnBotSpecSummonMessage(
		boss.label.." ("..mode.label.."): автостратегия "
		..(preset.autoStrategyEnabled
			and "|cff33ff66ВКЛЮЧЕНА|r. Полностью применится при следующем призыве."
			or "|cffff6060ВЫКЛЮЧЕНА|r. Активные боссовые циклы остановлены.")
	);
	UnBotSpecSummonMessage(description);
	UnBotBossPresetCatalogRefresh();
	return true;
end

function UnBotBossPresetSetAutoGuideOnTarget(bossKey, modeKey, enabled)
	local boss = UnBotBossPresetFindBoss(bossKey);
	local mode = UnBotBossPresetFindMode(modeKey);
	if (not boss or not mode) then
		UnBotSpecSummonMessage("Сначала выберите босса и режим.");
		return false;
	end
	local preset = UnBotBossPresetEditableGet(bossKey, modeKey, true);
	if (enabled) then
		local guideText = type(preset.guideText) == "string"
			and preset.guideText
			or (UnBotBossPresetBuiltinGuide(bossKey, modeKey) or "");
		local startMessage = type(preset.startMessage) == "string"
			and preset.startMessage
			or (UnBotBossPresetBuiltinStartMessage(bossKey, modeKey) or "");
		if (guideText == "" and startMessage == "") then
			UnBotSpecSummonMessage(
				boss.label.." ("..mode.label
				.."): сначала заполните «Старт» или «Памятки»."
			);
			return false;
		end
	end
	UnBotBossPresetBackupStore(bossKey, modeKey);
	UnBotAuthorPresets.MarkPersonal(UnBotSquadConfig, bossKey, modeKey);
	preset.autoGuideOnTargetEnabled = enabled and true or false;
	preset.autoGuideOnTargetUpdatedAt = date("%Y-%m-%d %H:%M:%S");
	local active = UnBotBossPresetGuide.active;
	if (
		not preset.autoGuideOnTargetEnabled
		and active
		and active.autoTarget
		and active.bossKey == bossKey
		and active.modeKey == modeKey
	) then
		UnBotBossPresetGuide.active = nil;
		UnBotBossPresetAutoGuide.bossKey = nil;
		UnBotBossPresetAutoGuide.modeKey = nil;
		UnBotBossPresetAutoGuide.targetGuid = nil;
	end
	UnBotSpecSummonMessage(
		boss.label.." ("..mode.label.."): автоподсказка по выделению босса "
		..(preset.autoGuideOnTargetEnabled
			and "|cff33ff66ВКЛЮЧЕНА|r. При выборе цели появятся памятка и стартовое сообщение; состав не вызывается."
			or "|cffff6060ВЫКЛЮЧЕНА|r.")
	);
	UnBotBossPresetCatalogRefresh();
	return true;
end

function UnBotBossPresetSetMasterLoot(...)
	UnBotLootSettings.Show("master");
	return true;
end

function UnBotBossPresetGuideEditorCommit(frame)
	local index = tonumber(frame and frame.currentSectionIndex);
	local section = index and frame.sections and frame.sections[index];
	if (not section) then
		return;
	end
	local label = tostring(frame.labelEdit:GetText() or "");
	label = string.gsub(label, "^%s+", "");
	label = string.gsub(label, "%s+$", "");
	section.label = label ~= "" and label or ("Фаза "..tostring(index));
	section.text = frame.edit:GetText() or "";
end

function UnBotBossPresetGuideEditorRefreshButtons(frame)
	for index, button in ipairs(frame.sectionButtons or {}) do
		local section = frame.sections and frame.sections[index];
		button.sectionIndex = index;
		if (section) then
			button:SetText(tostring(index)..". "..tostring(section.label or ("Фаза "..index)));
			button:Show();
			if (frame.currentSectionIndex == index) then
				button:LockHighlight();
			else
				button:UnlockHighlight();
			end
		else
			button:UnlockHighlight();
			button:Hide();
		end
	end
end

function UnBotBossPresetGuideEditorSelect(frame, index)
	UnBotBossPresetGuideEditorCommit(frame);
	index = tonumber(index);
	local section = index and frame.sections and frame.sections[index];
	frame.currentSectionIndex = section and index or nil;
	if (section) then
		frame.labelEdit:SetText(section.label or ("Фаза "..tostring(index)));
		frame.edit:SetText(section.text or "");
		frame.edit:SetCursorPosition(0);
		frame.labelEdit:EnableMouse(true);
		frame.edit:EnableMouse(true);
		frame.labelEdit:SetAlpha(1);
		frame.edit:SetAlpha(1);
	else
		frame.labelEdit:SetText("");
		frame.edit:SetText("");
		frame.labelEdit:ClearFocus();
		frame.edit:ClearFocus();
		frame.labelEdit:EnableMouse(false);
		frame.edit:EnableMouse(false);
		frame.labelEdit:SetAlpha(0.55);
		frame.edit:SetAlpha(0.55);
	end
	UnBotBossPresetGuideEditorRefreshButtons(frame);
end

function UnBotBossPresetGuideEditorSerialize(frame)
	local blocks = {};
	for index, section in ipairs(frame.sections or {}) do
		local label = tostring(section.label or ("Фаза "..tostring(index)));
		label = string.gsub(label, "[%[%]]", "");
		label = string.gsub(label, "^%s+", "");
		label = string.gsub(label, "%s+$", "");
		if (label == "") then
			label = "Фаза "..tostring(index);
		end
		local text = tostring(section.text or "");
		text = string.gsub(text, "^%s+", "");
		text = string.gsub(text, "%s+$", "");
		table.insert(blocks, "["..label.."]"..(text ~= "" and ("\n"..text) or ""));
	end
	return table.concat(blocks, "\n\n");
end

function UnBotBossPresetGuideEditorCreate()
	if (UnBotBossPresetGuide.editor) then
		return UnBotBossPresetGuide.editor;
	end
	local frame = CreateFrame("Frame", "UnBotBossPresetGuideEditor", UIParent);
	frame:SetWidth(700);
	frame:SetHeight(460);
	frame:SetPoint("CENTER", UIParent, "CENTER", 0, 20);
	frame:SetFrameStrata("FULLSCREEN_DIALOG");
	frame:SetMovable(true);
	frame:EnableMouse(true);
	frame:RegisterForDrag("LeftButton");
	frame:SetScript("OnDragStart", function(self) self:StartMoving(); end);
	frame:SetScript("OnDragStop", function(self) self:StopMovingOrSizing(); end);
	frame:SetBackdrop({
		bgFile = [[Interface\DialogFrame\UI-DialogBox-Background]],
		edgeFile = [[Interface\DialogFrame\UI-DialogBox-Border]],
		tile = true, tileSize = 32, edgeSize = 24,
		insets = { left = 8, right = 8, top = 8, bottom = 8 },
	});
	frame:Hide();
	table.insert(UISpecialFrames, "UnBotBossPresetGuideEditor");

	frame.title = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge");
	frame.title:SetPoint("TOP", frame, "TOP", 0, -18);
	frame.title:SetText("Памятка пресета");
	local help = frame:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall");
	help:SetPoint("TOPLEFT", frame, "TOPLEFT", 190, -48);
	help:SetWidth(480);
	help:SetJustifyH("LEFT");
	help:SetText(
		"Каждая памятка или фаза редактируется отдельно. Выберите кнопку слева; "
		.."первая показывается при загрузке, вторая — на пуле, дальше работает /ubphase next. "
		.."Сообщение старта редактируется отдельно."
	);

	local sectionTitle = frame:CreateFontString(nil, "OVERLAY", "GameFontNormal");
	sectionTitle:SetPoint("TOPLEFT", frame, "TOPLEFT", 22, -50);
	sectionTitle:SetText("Памятки и фазы");
	frame.sectionButtons = {};
	frame.sections = {};
	frame.currentSectionIndex = nil;
	for index = 1, 12, 1 do
		local sectionButton = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
		sectionButton:SetWidth(145);
		sectionButton:SetHeight(23);
		sectionButton:SetPoint("TOPLEFT", frame, "TOPLEFT", 22, -70 - ((index - 1) * 25));
		sectionButton.sectionIndex = index;
		sectionButton:SetScript("OnClick", function(self)
			UnBotBossPresetGuideEditorSelect(frame, self.sectionIndex);
		end);
		sectionButton:Hide();
		table.insert(frame.sectionButtons, sectionButton);
	end

	local labelTitle = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall");
	labelTitle:SetPoint("TOPLEFT", frame, "TOPLEFT", 190, -82);
	labelTitle:SetText("Название кнопки / фазы:");
	local labelEdit = CreateFrame("EditBox", nil, frame, "InputBoxTemplate");
	labelEdit:SetWidth(455);
	labelEdit:SetHeight(22);
	labelEdit:SetPoint("TOPLEFT", frame, "TOPLEFT", 190, -98);
	labelEdit:SetAutoFocus(false);
	labelEdit:SetScript("OnEscapePressed", function() frame:Hide(); end);
	frame.labelEdit = labelEdit;

	local scroll = CreateFrame(
		"ScrollFrame",
		"UnBotBossPresetGuideEditorScrollFrame",
		frame,
		"UIPanelScrollFrameTemplate"
	);
	scroll:SetPoint("TOPLEFT", frame, "TOPLEFT", 190, -128);
	scroll:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -42, 58);
	local edit = CreateFrame("EditBox", nil, scroll);
	edit:SetMultiLine(true);
	edit:SetAutoFocus(false);
	edit:SetFontObject(ChatFontNormal);
	edit:SetWidth(455);
	edit:SetHeight(260);
	edit:SetTextInsets(6, 6, 6, 6);
	edit:SetScript("OnEscapePressed", function() frame:Hide(); end);
	edit:SetScript("OnTextChanged", function() scroll:UpdateScrollChildRect(); end);
	scroll:SetScrollChild(edit);
	frame.edit = edit;

	local addSection = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
	addSection:SetWidth(70);
	addSection:SetHeight(24);
	addSection:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", 22, 20);
	addSection:SetText("Добавить");
	addSection:SetScript("OnClick", function()
		UnBotBossPresetGuideEditorCommit(frame);
		if (#(frame.sections or {}) >= 12) then
			UnBotSpecSummonMessage("В одной памятке поддерживается не более 12 отдельных фаз.");
			return;
		end
		local index = #(frame.sections or {}) + 1;
		table.insert(frame.sections, {
			label = index == 1 and "Общее" or ("Фаза "..tostring(index)),
			text = "",
		});
		UnBotBossPresetGuideEditorSelect(frame, index);
	end);
	local deleteSection = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
	deleteSection:SetWidth(70);
	deleteSection:SetHeight(24);
	deleteSection:SetPoint("LEFT", addSection, "RIGHT", 5, 0);
	deleteSection:SetText("Удалить");
	deleteSection:SetScript("OnClick", function()
		local index = tonumber(frame.currentSectionIndex);
		if (not index or not frame.sections[index]) then
			return;
		end
		table.remove(frame.sections, index);
		frame.currentSectionIndex = nil;
		UnBotBossPresetGuideEditorSelect(
			frame,
			math.min(index, #frame.sections)
		);
	end);

	local save = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
	save:SetWidth(130);
	save:SetHeight(24);
	save:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", 190, 20);
	save:SetText("Сохранить всё");
	save:SetScript("OnClick", function()
		local preset = UnBotBossPresetEditableGet(
			frame.bossKey,
			frame.modeKey,
			true
		);
		if (not preset) then
			UnBotSpecSummonMessage("Памятка не сохранена: не выбран босс или режим.");
			return;
		end
		if (UnBotBossPresetRequirements(preset)) then
			UnBotBossPresetBackupStore(frame.bossKey, frame.modeKey);
		end
		UnBotBossPresetGuideEditorCommit(frame);
		UnBotAuthorPresets.MarkPersonal(UnBotSquadConfig, frame.bossKey, frame.modeKey);
		preset.guideText = UnBotBossPresetGuideEditorSerialize(frame);
		preset.guideUpdatedAt = date("%Y-%m-%d %H:%M:%S");
		UnBotSpecSummonMessage(
			"Памятки и фазы сохранены: "..tostring(#frame.sections).." отдельных кнопок."
		);
		if (UnBotBossPresetRequirements(preset)) then
			local activeGuide = UnBotBossPresetGuide.active;
			local keepAuto = activeGuide
				and activeGuide.bossKey == frame.bossKey
				and activeGuide.modeKey == frame.modeKey
				and activeGuide.autoCombat;
			UnBotBossPresetGuideActivate(frame.bossKey, frame.modeKey, preset, keepAuto);
		else
			UnBotBossPresetGuideSelectSolo(frame.bossKey, frame.modeKey, preset);
		end
		frame:Hide();
		UnBotBossPresetCatalogRefresh();
	end);
	local cancel = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
	cancel:SetWidth(130);
	cancel:SetHeight(24);
	cancel:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -22, 20);
	cancel:SetText("Отмена");
	cancel:SetScript("OnClick", function() frame:Hide(); end);
	UnBotBossPresetGuide.editor = frame;
	return frame;
end

function UnBotBossPresetGuideEditorOpen(bossKey, modeKey)
	local boss = UnBotBossPresetFindBoss(bossKey);
	local mode = UnBotBossPresetFindMode(modeKey);
	local preset = UnBotBossPresetEditableGet(bossKey, modeKey, false) or {};
	if (not boss or not mode) then
		UnBotSpecSummonMessage("Сначала выберите босса и сложность.");
		return false;
	end
	local frame = UnBotBossPresetGuideEditorCreate();
	frame.bossKey = bossKey;
	frame.modeKey = modeKey;
	frame.title:SetText("Памятки и фазы: "..boss.label.." — "..mode.label);
	frame.sections = UnBotBossPresetGuideSections({
		guideText = preset.guideText
			or UnBotBossPresetBuiltinGuide(bossKey, modeKey)
			or "[Общее]\n",
	});
	if (#frame.sections == 0) then
		frame.sections = {{ label = "Общее", text = "" }};
	end
	frame.currentSectionIndex = nil;
	UnBotBossPresetGuideEditorSelect(frame, 1);
	frame:Show();
	frame:Raise();
	return true;
end

function UnBotBossPresetStartEditorCreate()
	if (UnBotBossPresetGuide.startEditor) then
		return UnBotBossPresetGuide.startEditor;
	end
	local frame = CreateFrame("Frame", "UnBotBossPresetStartMessageEditor", UIParent);
	frame:SetWidth(600);
	frame:SetHeight(300);
	frame:SetPoint("CENTER", UIParent, "CENTER", 0, 20);
	frame:SetFrameStrata("FULLSCREEN_DIALOG");
	frame:SetMovable(true);
	frame:EnableMouse(true);
	frame:RegisterForDrag("LeftButton");
	frame:SetScript("OnDragStart", function(self) self:StartMoving(); end);
	frame:SetScript("OnDragStop", function(self) self:StopMovingOrSizing(); end);
	frame:SetBackdrop({
		bgFile = [[Interface\DialogFrame\UI-DialogBox-Background]],
		edgeFile = [[Interface\DialogFrame\UI-DialogBox-Border]],
		tile = true, tileSize = 32, edgeSize = 24,
		insets = { left = 8, right = 8, top = 8, bottom = 8 },
	});
	frame:Hide();
	table.insert(UISpecialFrames, "UnBotBossPresetStartMessageEditor");

	frame.title = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge");
	frame.title:SetPoint("TOP", frame, "TOP", 0, -18);
	frame.title:SetText("Сообщение при старте боя");
	local help = frame:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall");
	help:SetPoint("TOPLEFT", frame, "TOPLEFT", 22, -50);
	help:SetWidth(550);
	help:SetJustifyH("LEFT");
	help:SetText(
		"Этот текст один раз показывается крупно по центру после полной готовности состава. "
		.."Пишите 1–3 короткие строки. Пустое поле отключает сообщение для этого пресета."
	);

	local scroll = CreateFrame(
		"ScrollFrame",
		"UnBotBossPresetStartMessageEditorScrollFrame",
		frame,
		"UIPanelScrollFrameTemplate"
	);
	scroll:SetPoint("TOPLEFT", frame, "TOPLEFT", 22, -92);
	scroll:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -42, 58);
	local edit = CreateFrame("EditBox", nil, scroll);
	edit:SetMultiLine(true);
	edit:SetAutoFocus(false);
	edit:SetFontObject(ChatFontNormal);
	edit:SetWidth(530);
	edit:SetHeight(130);
	edit:SetTextInsets(6, 6, 6, 6);
	edit:SetScript("OnEscapePressed", function() frame:Hide(); end);
	edit:SetScript("OnTextChanged", function() scroll:UpdateScrollChildRect(); end);
	scroll:SetScrollChild(edit);
	frame.edit = edit;

	local save = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
	save:SetWidth(130);
	save:SetHeight(24);
	save:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", 22, 20);
	save:SetText("Сохранить");
	save:SetScript("OnClick", function()
		local preset = UnBotBossPresetEditableGet(
			frame.bossKey,
			frame.modeKey,
			true
		);
		if (not preset) then
			UnBotSpecSummonMessage("Стартовое сообщение не сохранено: не выбран босс или режим.");
			return;
		end
		if (UnBotBossPresetRequirements(preset)) then
			UnBotBossPresetBackupStore(frame.bossKey, frame.modeKey);
		end
		local text = frame.edit:GetText() or "";
		text = string.gsub(text, "^%s+", "");
		text = string.gsub(text, "%s+$", "");
		UnBotAuthorPresets.MarkPersonal(UnBotSquadConfig, frame.bossKey, frame.modeKey);
		preset.startMessage = text;
		preset.startMessageUpdatedAt = date("%Y-%m-%d %H:%M:%S");
		UnBotSpecSummonMessage(
			preset.startMessage ~= ""
			and "Сообщение при старте боя сохранено."
			or "Сообщение при старте боя отключено для этого пресета."
		);
		if (not UnBotBossPresetRequirements(preset)) then
			UnBotBossPresetGuideSelectSolo(frame.bossKey, frame.modeKey, preset);
		end
		frame:Hide();
		UnBotBossPresetCatalogRefresh();
	end);
	local cancel = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
	cancel:SetWidth(130);
	cancel:SetHeight(24);
	cancel:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -22, 20);
	cancel:SetText("Отмена");
	cancel:SetScript("OnClick", function() frame:Hide(); end);
	UnBotBossPresetGuide.startEditor = frame;
	return frame;
end

function UnBotBossPresetStartEditorOpen(bossKey, modeKey)
	local boss = UnBotBossPresetFindBoss(bossKey);
	local mode = UnBotBossPresetFindMode(modeKey);
	local preset = UnBotBossPresetEditableGet(bossKey, modeKey, false) or {};
	if (not boss or not mode) then
		UnBotSpecSummonMessage("Сначала выберите босса и сложность.");
		return false;
	end
	local frame = UnBotBossPresetStartEditorCreate();
	frame.bossKey = bossKey;
	frame.modeKey = modeKey;
	frame.title:SetText("Старт боя: "..boss.label.." — "..mode.label);
	frame.edit:SetText(
		preset.startMessage
		or UnBotBossPresetBuiltinStartMessage(bossKey, modeKey)
		or ""
	);
	frame.edit:SetCursorPosition(0);
	frame:Show();
	frame:Raise();
	return true;
end

function UnBotBossPresetCatalogRefresh()
	local catalog = UnBotBossPresetCatalog;
	if (not catalog.frame) then
		return;
	end
	UnBotSquadBuilderEnsureConfig();
	UnBotBossPresetCatalogRebuild();
	local instances = UnBotBossPresetCatalogFilteredInstances();
	catalog.filteredInstances = instances;
	local selectedStillExists = false;
	for _, instance in ipairs(instances) do
		if (instance.name == catalog.selectedInstance) then
			selectedStillExists = true;
		end
	end
	if (not selectedStillExists) then
		catalog.selectedInstance = instances[1] and instances[1].name or nil;
		catalog.instanceOffset = 0;
		catalog.bossOffset = 0;
		catalog.selectedBossKey = nil;
	end
	catalog.instanceOffset = math.max(
		0,
		math.min(catalog.instanceOffset or 0, math.max(0, #instances - #catalog.instanceButtons))
	);
	local selectedInstance;
	for _, instance in ipairs(instances) do
		if (instance.name == catalog.selectedInstance) then
			selectedInstance = instance;
		end
	end
	catalog.currentInstance = selectedInstance;
	local bosses = selectedInstance and selectedInstance.bosses or {};
	local selectedBossStillExists = false;
	for _, boss in ipairs(bosses) do
		if (boss.key == catalog.selectedBossKey) then
			selectedBossStillExists = true;
		end
	end
	if (not selectedBossStillExists) then
		catalog.selectedBossKey = bosses[1] and bosses[1].key or nil;
		catalog.bossOffset = 0;
	end
	catalog.bossOffset = math.max(
		0,
		math.min(catalog.bossOffset or 0, math.max(0, #bosses - #catalog.bossButtons))
	);
	for index, button in ipairs(catalog.instanceButtons) do
		local instance = instances[(catalog.instanceOffset or 0) + index];
		if (instance) then
			button.value = instance.name;
			button:SetText(instance.displayName or instance.name);
			button:Show();
			if (instance.name == catalog.selectedInstance) then
				button:LockHighlight();
			else
				button:UnlockHighlight();
			end
		else
			button.value = nil;
			button:Hide();
		end
	end
	for index, button in ipairs(catalog.bossButtons) do
		local boss = bosses[(catalog.bossOffset or 0) + index];
		if (boss) then
			button.value = boss.key;
			button:SetText(
				(UnBotBossPresetCatalogPresetExistsForBoss(boss.key) and "- " or "")
				..boss.label
			);
			button:Show();
			if (boss.key == catalog.selectedBossKey) then
				button:LockHighlight();
			else
				button:UnlockHighlight();
			end
		else
			button.value = nil;
			button:Hide();
		end
	end
	local modes = UnBotBossPresetModesForBoss(
		selectedInstance and selectedInstance.instanceType,
		catalog.selectedBossKey,
		selectedInstance
	);
	catalog.currentModes = modes;
	for index, button in ipairs(catalog.modeButtons) do
		local mode = modes[index];
		local reserveButton = catalog.reserveButtons[index];
		if (mode and catalog.selectedBossKey) then
			local preset = UnBotBossPresetGet(catalog.selectedBossKey, mode.key);
			local presetLabel = preset and (
				mode.key == "25h18"
				and (tostring(UnBotSquadBuilderSlotsCount(
					UnBotBossPresetRequirements(preset)
				) + 1).." участника")
				or (tostring(UnBotSquadBuilderSlotsCount(
					UnBotBossPresetRequirements(preset)
				)).." ботов")
			) or "пусто";
			button.bossKey = catalog.selectedBossKey;
			button.modeKey = mode.key;
			button:SetText(mode.label.."\n"..presetLabel);
			button:Show();
			if (mode.key == catalog.selectedModeKey) then
				button:LockHighlight();
			else
				button:UnlockHighlight();
			end

		else
			button.bossKey = nil;
			button.modeKey = nil;
			button:UnlockHighlight();
			button:Hide();
			if (reserveButton) then
				reserveButton.bossKey = nil;
				reserveButton.modeKey = nil;
				reserveButton:SetChecked(false);
				reserveButton:Hide();
			end
		end
	end
	if (catalog.instanceType == "raid") then
		catalog.raidTab:Disable();
		catalog.partyTab:Enable();
	else
		catalog.raidTab:Enable();
		catalog.partyTab:Disable();
	end
	for _, button in ipairs(catalog.expansionButtons or {}) do
		if (
			catalog.instanceType == "raid"
			and button.expansionKey == catalog.raidExpansion
		) then
			button:LockHighlight();
		else
			button:UnlockHighlight();
		end
	end
	catalog.instancePage:SetText(
		tostring(math.min(#instances, (catalog.instanceOffset or 0) + 1))
		.."-"..tostring(math.min(#instances, (catalog.instanceOffset or 0) + #catalog.instanceButtons))
		.." / "..tostring(#instances)
	);
	catalog.bossPage:SetText(
		tostring(math.min(#bosses, (catalog.bossOffset or 0) + 1))
		.."-"..tostring(math.min(#bosses, (catalog.bossOffset or 0) + #catalog.bossButtons))
		.." / "..tostring(#bosses)
	);
	local selectedBoss = UnBotBossPresetFindBoss(catalog.selectedBossKey);
	catalog.selection:SetText(
		selectedBoss
		and ("Выбран: "..tostring(selectedInstance.displayName or selectedInstance.name)
			.." — "..selectedBoss.label)
		or "Выберите босса."
	);
	local backups = catalog.selectedBossKey
		and UnBotSquadConfig.bossPresetBackups[catalog.selectedBossKey];
	if (backups and catalog.selectedModeKey and backups[catalog.selectedModeKey]) then
		catalog.previousButton:Enable();
	else
		catalog.previousButton:Disable();
	end
	if (catalog.guideButton) then
		if (
			catalog.selectedBossKey
			and catalog.selectedModeKey
		) then
			catalog.guideButton:Enable();
		else
			catalog.guideButton:Disable();
		end
	end
	if (catalog.startMessageButton) then
		if (
			catalog.selectedBossKey
			and catalog.selectedModeKey
		) then
			catalog.startMessageButton:Enable();
		else
			catalog.startMessageButton:Disable();
		end
	end
	if (catalog.plagueCheck) then
		if (catalog.selectedBossKey == "the_lich_king") then
			catalog.plagueCheck:Show();
			catalog.plagueCheck:SetChecked(not UnBotSquadConfig.lichKing or UnBotSquadConfig.lichKing.plagueEnabled ~= false);
			if (catalog.selectedModeKey and UnBotLichPlague and UnBotLichPlague.SetEnabled) then
				catalog.plagueCheck:Enable();
				catalog.plagueCheck.text:SetTextColor(1, 0.82, 0);
			else
				catalog.plagueCheck:Disable();
				catalog.plagueCheck.text:SetTextColor(0.5, 0.5, 0.5);
			end
		else
			catalog.plagueCheck:Hide();
		end
	end
	if (catalog.autoStrategyCheck) then
		local selectedPreset = catalog.selectedBossKey
			and catalog.selectedModeKey
			and UnBotBossPresetGet(
				catalog.selectedBossKey,
				catalog.selectedModeKey
			);
		local autoDescription = catalog.selectedBossKey
			and catalog.selectedModeKey
			and UnBotBossPresetAutoStrategyDescription(
				catalog.selectedBossKey,
				catalog.selectedModeKey
			);
		if (selectedPreset and autoDescription) then
			catalog.autoStrategyCheck:Enable();
			catalog.autoStrategyCheck:SetChecked(
				UnBotBossPresetAutoStrategyEnabled(
					catalog.selectedBossKey,
					catalog.selectedModeKey,
					selectedPreset
				)
			);
			catalog.autoStrategyCheck.text:SetTextColor(1, 0.82, 0);
		else
			catalog.autoStrategyCheck:SetChecked(false);
			catalog.autoStrategyCheck:Disable();
			catalog.autoStrategyCheck.text:SetTextColor(0.5, 0.5, 0.5);
		end
	end
	if (catalog.autoGuideCheck) then
		if (catalog.twinTankButton) then
			if (catalog.selectedBossKey == "temple_of_ahn_qiraj__the_twin_emperors") then
				catalog.twinTankButton:Show();
				catalog.autoGuideCheck.text:SetText("Автоподсказка");
				catalog.autoGuideCheck.text:SetWidth(92);
				catalog.autoGuideCheck:SetHitRectInsets(0, -94, 0, 0);
			else
				catalog.twinTankButton:Hide();
				catalog.autoGuideCheck.text:SetText("Автоподсказка при выделении босса");
				catalog.autoGuideCheck.text:SetWidth(228);
				catalog.autoGuideCheck:SetHitRectInsets(0, -230, 0, 0);
			end
		end
		local selectedPreset = catalog.selectedBossKey
			and catalog.selectedModeKey
			and UnBotBossPresetEditableGet(
				catalog.selectedBossKey,
				catalog.selectedModeKey,
				false
			);
		if (catalog.selectedBossKey and catalog.selectedModeKey) then
			catalog.autoGuideCheck:Enable();
			catalog.autoGuideCheck:SetChecked(
				selectedPreset
				and selectedPreset.autoGuideOnTargetEnabled == true
			);
			catalog.autoGuideCheck.text:SetTextColor(1, 0.82, 0);
		else
			catalog.autoGuideCheck:SetChecked(false);
			catalog.autoGuideCheck:Disable();
			catalog.autoGuideCheck.text:SetTextColor(0.5, 0.5, 0.5);
		end
	end
end

function UnBotBossPresetCatalogCreate(parent)
	if (UnBotBossPresetCatalog.frame) then
		return;
	end
	local catalog = UnBotBossPresetCatalog;
	local frame = CreateFrame("Frame", nil, parent);
	catalog.frame = frame;
	frame:SetWidth(470);
	frame:SetHeight(508);
	frame:SetPoint("TOPLEFT", parent, "TOPLEFT", 486, 0);
	frame:SetBackdrop({
		bgFile = [[Interface\DialogFrame\UI-DialogBox-Background]],
		edgeFile = [[Interface\DialogFrame\UI-DialogBox-Border]],
		tile = true, tileSize = 32, edgeSize = 24,
		insets = { left = 8, right = 8, top = 8, bottom = 8 },
	});
	frame:Hide();

	local title = frame:CreateFontString(nil, "OVERLAY", "GameFontNormalLarge");
	title:SetPoint("TOP", frame, "TOP", 0, -16);
	title:SetText("Составы по боссам");

	local collapse = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
	collapse:SetWidth(32);
	collapse:SetHeight(20);
	collapse:SetPoint("TOPRIGHT", frame, "TOPRIGHT", -48, -15);
	collapse:SetText(">>");
	collapse:SetScript("OnClick", function()
		UnBotBossPresetCatalogToggle();
	end);

	catalog.raidTab = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
	catalog.raidTab:SetWidth(100);
	catalog.raidTab:SetHeight(22);
	catalog.raidTab:SetPoint("TOPLEFT", frame, "TOPLEFT", 18, -45);
	catalog.raidTab:SetText("Рейды");
	catalog.raidTab:SetScript("OnClick", function()
		catalog.instanceType = "raid";
		catalog.selectedInstance = nil;
		catalog.selectedBossKey = nil;
		catalog.selectedModeKey = nil;
		UnBotSquadBuilder.loadedBossPreset = nil;
		UnBotBossPresetGuide.active = nil;
		UnBotBossPresetDisarmAutomaticStrategies();
		UnBotBossPresetCatalogRefresh();
	end);

	catalog.partyTab = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
	catalog.partyTab:SetWidth(120);
	catalog.partyTab:SetHeight(22);
	catalog.partyTab:SetPoint("LEFT", catalog.raidTab, "RIGHT", 5, 0);
	catalog.partyTab:SetText("Подземелья");
	catalog.partyTab:SetScript("OnClick", function()
		catalog.instanceType = "party";
		catalog.selectedInstance = nil;
		catalog.selectedBossKey = nil;
		catalog.selectedModeKey = nil;
		UnBotSquadBuilder.loadedBossPreset = nil;
		UnBotBossPresetGuide.active = nil;
		UnBotBossPresetDisarmAutomaticStrategies();
		UnBotBossPresetCatalogRefresh();
	end);

	for _, expansion in ipairs({
		{ key = "classic", label = "Классика", width = 62 },
		{ key = "tbc", label = "TBC", width = 50 },
		{ key = "wotlk", label = "WotLK", width = 68 },
	}) do
		local expansionButton = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
		expansionButton.expansionKey = expansion.key;
		expansionButton:SetWidth(expansion.width);
		expansionButton:SetHeight(22);
		if (#catalog.expansionButtons == 0) then
			expansionButton:SetPoint("LEFT", catalog.partyTab, "RIGHT", 5, 0);
		else
			expansionButton:SetPoint(
				"LEFT",
				catalog.expansionButtons[#catalog.expansionButtons],
				"RIGHT",
				3,
				0
			);
		end
		expansionButton:SetText(UnBotLocale.Text(expansion.label));
		expansionButton:SetScript("OnClick", function(self)
			catalog.instanceType = "raid";
			catalog.raidExpansion = self.expansionKey;
			catalog.selectedInstance = nil;
			catalog.selectedBossKey = nil;
			catalog.selectedModeKey = nil;
			catalog.instanceOffset = 0;
			catalog.bossOffset = 0;
			UnBotSquadBuilder.loadedBossPreset = nil;
			UnBotBossPresetGuide.active = nil;
			UnBotBossPresetDisarmAutomaticStrategies();
			UnBotBossPresetCatalogRefresh();
		end);
		table.insert(catalog.expansionButtons, expansionButton);
	end

	local instanceTitle = frame:CreateFontString(nil, "OVERLAY", "GameFontNormal");
	instanceTitle:SetPoint("TOPLEFT", frame, "TOPLEFT", 18, -76);
	instanceTitle:SetText("Рейд / подземелье");
	local bossTitle = frame:CreateFontString(nil, "OVERLAY", "GameFontNormal");
	bossTitle:SetPoint("TOPLEFT", frame, "TOPLEFT", 177, -76);
	bossTitle:SetText("Босс");

	for index = 1, 8, 1 do
		local instanceButton = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
		instanceButton:SetWidth(150);
		instanceButton:SetHeight(22);
		instanceButton:SetPoint("TOPLEFT", frame, "TOPLEFT", 16, -91 - ((index - 1) * 24));
		instanceButton:GetFontString():SetJustifyH("LEFT");
		instanceButton:SetScript("OnClick", function(self)
			catalog.selectedInstance = self.value;
