		bossButton:SetWidth(276);
		bossButton:SetHeight(22);
		bossButton:SetPoint("TOPLEFT", frame, "TOPLEFT", 175, -91 - ((index - 1) * 24));
		bossButton:GetFontString():SetJustifyH("LEFT");
		bossButton:SetScript("OnClick", function(self)
			catalog.selectedBossKey = self.value;
			catalog.selectedModeKey = nil;
			UnBotSquadBuilder.loadedBossPreset = nil;
			UnBotBossPresetGuide.active = nil;
			UnBotBossPresetDisarmAutomaticStrategies();
			UnBotGunshipMasterLoot.CheckBossClick(self.value);
			UnBotBossPresetCatalogRefresh();
		end);
