	end);
	local nextInstances = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
	nextInstances:SetWidth(34);
	nextInstances:SetHeight(20);
	nextInstances:SetPoint("LEFT", prevInstances, "RIGHT", 3, 0);
	nextInstances:SetText(">");
	nextInstances:SetScript("OnClick", function()
		catalog.instanceOffset = (catalog.instanceOffset or 0) + #catalog.instanceButtons;
		UnBotBossPresetCatalogRefresh();
	end);
	catalog.instancePage = frame:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall");
	catalog.instancePage:SetPoint("LEFT", nextInstances, "RIGHT", 5, 0);

	local prevBosses = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
	prevBosses:SetWidth(34);
	prevBosses:SetHeight(20);
	prevBosses:SetPoint("TOPLEFT", frame, "TOPLEFT", 175, -288);
	prevBosses:SetText("<");
	prevBosses:SetScript("OnClick", function()
		catalog.bossOffset = math.max(0, (catalog.bossOffset or 0) - #catalog.bossButtons);
		UnBotBossPresetCatalogRefresh();
	end);
	local nextBosses = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
	nextBosses:SetWidth(34);
	nextBosses:SetHeight(20);
	nextBosses:SetPoint("LEFT", prevBosses, "RIGHT", 3, 0);
	nextBosses:SetText(">");
	nextBosses:SetScript("OnClick", function()
		catalog.bossOffset = (catalog.bossOffset or 0) + #catalog.bossButtons;
		UnBotBossPresetCatalogRefresh();
	end);
	catalog.bossPage = frame:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall");
	catalog.bossPage:SetPoint("LEFT", nextBosses, "RIGHT", 5, 0);

	catalog.selection = frame:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall");
	catalog.selection:SetPoint("TOPLEFT", frame, "TOPLEFT", 18, -316);
	catalog.selection:SetWidth(430);
	catalog.selection:SetJustifyH("LEFT");

	for index = 1, 5, 1 do
		local modeButton = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate");
		modeButton:SetWidth(82);
		modeButton:SetHeight(38);
		modeButton:SetPoint("TOPLEFT", frame, "TOPLEFT", 18 + ((index - 1) * 86), -337);
		modeButton:RegisterForClicks("LeftButtonUp", "RightButtonUp");
		modeButton:SetScript("OnClick", UnBotBossPresetCatalogModeClick);
		modeButton:SetScript("OnEnter", UnBotBossPresetCatalogModeTooltip);
		modeButton:SetScript("OnLeave", function() GameTooltip:Hide(); end);
		table.insert(catalog.modeButtons, modeButton);


	end

	catalog.plagueCheck = CreateFrame("CheckButton", nil, frame, "UICheckButtonTemplate");
	catalog.plagueCheck:SetWidth(24);
	catalog.plagueCheck:SetHeight(22);
	catalog.plagueCheck:SetPoint("TOPLEFT", frame, "TOPLEFT", 18, -378);
	catalog.plagueCheck:SetHitRectInsets(0, -250, 0, 0);
	catalog.plagueCheck.text = catalog.plagueCheck:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall");
	catalog.plagueCheck.text:SetPoint("LEFT", catalog.plagueCheck, "RIGHT", -2, 0);
	catalog.plagueCheck.text:SetWidth(248);
	catalog.plagueCheck.text:SetJustifyH("LEFT");
	catalog.plagueCheck.text:SetText("Предупреждение о чуме");
	catalog.plagueCheck:Hide();
	catalog.plagueCheck:SetScript("OnClick", function(self)
		if (catalog.selectedBossKey ~= "the_lich_king" or not catalog.selectedModeKey) then return; end
		if (UnBotLichPlague and UnBotLichPlague.SetEnabled) then
			UnBotLichPlague.SetEnabled(self:GetChecked());
		else
			UnBotBossPresetCatalogRefresh();
		end
	end);
	catalog.plagueCheck:SetScript("OnEnter", function(self)
		GameTooltip:SetOwner(self, "ANCHOR_TOP");
		GameTooltip:AddLine("Предупреждение о чуме", 1, 0.82, 0);
		GameTooltip:AddLine("Табличка с носителями чумы, звуковое предупреждение и радар DBM на 10 ярдов. Выключение сразу скрывает предупреждение.", 1, 1, 1, true);
		GameTooltip:AddLine("Общая настройка для всех сложностей Лича и персонажей аккаунта. Сохраняется после /reload.", 0.2, 0.8, 1, true);
		GameTooltip:Show();
	end);
	catalog.plagueCheck:SetScript("OnLeave", function() GameTooltip:Hide(); end);

	catalog.autoStrategyCheck = CreateFrame(
		"CheckButton",
		nil,
		frame,
		"UICheckButtonTemplate"
	);
	catalog.autoStrategyCheck:SetWidth(24);
	catalog.autoStrategyCheck:SetHeight(22);
	catalog.autoStrategyCheck:SetPoint("TOPLEFT", frame, "TOPLEFT", 18, -406);
	catalog.autoStrategyCheck:SetHitRectInsets(0, -94, 0, 0);
	catalog.autoStrategyCheck.text = catalog.autoStrategyCheck:CreateFontString(
