function UnBotBossPresetCatalogToggle()
	local catalog = UnBotBossPresetCatalog;
	if (not UnBotSquadBuilder.frame) then
		return;
	end
	if (not catalog.frame) then
		UnBotBossPresetCatalogCreate(UnBotSquadBuilder.frame);
	end
	catalog.expanded = not catalog.expanded;
	if (catalog.expanded) then
		UnBotSquadBuilder.frame:SetWidth(956);
		catalog.frame:Show();
		UnBotBossPresetCatalogRefresh();
	else
		catalog.frame:Hide();
		UnBotSquadBuilder.frame:SetWidth(488);
	end
end

UnBotDeathwhisperControl = UnBotDeathwhisperControl or {
	armed = false,
	active = false,
	modeKey = nil,
	expiresAt = 0,
	seen = {},
	markAttempts = {},
	skullAnnouncements = {},
	wave = 0,
	lastWaveAt = 0,
	nextScanAt = 0,
	markFailureAnnounced = false,
};

function UnBotDeathwhisperResetTracking()
	local state = UnBotDeathwhisperControl;
	state.seen = {};
	state.markAttempts = {};
	state.skullAnnouncements = {};
	state.wave = 0;
	state.lastWaveAt = 0;
	state.nextScanAt = 0;
	state.markFailureAnnounced = false;
end

function UnBotDeathwhisperDisarm(silent)
	local state = UnBotDeathwhisperControl;
	local wasArmed = state.armed;
	state.armed = false;
	state.active = false;
	state.modeKey = nil;
	state.expiresAt = 0;
	UnBotDeathwhisperResetTracking();
	if (wasArmed and not silent) then
		UnBotSpecSummonMessage("Леди Смертный Шёпот: контроль аддов отключён.");
	end
end

function UnBotDeathwhisperArm(modeKey)
	local state = UnBotDeathwhisperControl;
	local alreadyArmed = state.armed and state.modeKey == modeKey;
	state.armed = true;
	state.active = UnitAffectingCombat and UnitAffectingCombat("player") and true or false;
	state.modeKey = modeKey;
	state.expiresAt = GetTime() + 1800;
	UnBotDeathwhisperResetTracking();
	if (not alreadyArmed) then
		UnBotSpecSummonMessage(
			"Леди Смертный Шёпот ("..tostring(modeKey or "режим")
			.."): на 30 минут включено отслеживание аддов. Череп — первая цель, "
			.."крест — вторая; видимые цели проверяются автоматически."
		);
	end
end

function UnBotDeathwhisperGuidEntry(guid)
	local hex = string.match(tostring(guid or ""), "^0[xX](%x+)$");
	if (not hex or #hex < 10) then
		return nil;
	end
	return tonumber(string.sub(hex, 5, 10), 16);
end

function UnBotDeathwhisperAddInfo(name, guid)
	local entry = UnBotDeathwhisperGuidEntry(guid);
	local original = tostring(name or "");
	local normalized = UnBotSpecSummonNormalize(original);
	if (
		entry == 38135
		or string.find(normalized, "deformed fanatic", 1, true)
		or string.find(original, "Деформированный фанатик", 1, true)
	) then
		return { kind = "deformed_fanatic", priority = 1, label = "Деформированный фанатик" };
	elseif (
		entry == 38136
		or string.find(normalized, "empowered adherent", 1, true)
		or string.find(original, "Усиленный адепт", 1, true)
	) then
		return { kind = "empowered_adherent", priority = 2, label = "Усиленный адепт" };
	elseif (
		entry == 38010
		or string.find(normalized, "reanimated adherent", 1, true)
		or string.find(original, "Воскрешённый адепт", 1, true)
		or string.find(original, "Воскрешенный адепт", 1, true)
	) then
		return { kind = "reanimated_adherent", priority = 3, label = "Воскрешённый адепт" };
	elseif (
		entry == 37949
		or string.find(normalized, "cult adherent", 1, true)
		or string.find(original, "Адепт культа", 1, true)
	) then
		return { kind = "cult_adherent", priority = 3, label = "Адепт культа" };
	elseif (
		entry == 38009
		or string.find(normalized, "reanimated fanatic", 1, true)
		or string.find(original, "Воскрешённый фанатик", 1, true)
		or string.find(original, "Воскрешенный фанатик", 1, true)
	) then
		return { kind = "reanimated_fanatic", priority = 4, label = "Воскрешённый фанатик" };
	elseif (
		entry == 37890
		or string.find(normalized, "cult fanatic", 1, true)
		or string.find(original, "Фанатик культа", 1, true)
	) then
		return { kind = "cult_fanatic", priority = 4, label = "Фанатик культа" };
	end
	return nil;
end

function UnBotDeathwhisperNotice(text, sound)
	if (RaidNotice_AddMessage and RaidWarningFrame) then
		RaidNotice_AddMessage(
			RaidWarningFrame,
			text,
			ChatTypeInfo and ChatTypeInfo["RAID_WARNING"]
		);
	elseif (UIErrorsFrame) then
		UIErrorsFrame:AddMessage(text, 1, 0.15, 0.15, 1);
	end
	if (sound and PlaySound) then
		PlaySound("RaidWarning");
	end
end

function UnBotDeathwhisperRegisterAdd(guid, name)
	if (not guid or guid == "") then
		return false;
	end
	local info = UnBotDeathwhisperAddInfo(name, guid);
	if (not info) then
		return false;
	end
	local state = UnBotDeathwhisperControl;
	local current = state.seen[guid];
	local changed = current and current.kind ~= info.kind;
	if (not current or changed) then
		state.seen[guid] = {
			kind = info.kind,
			priority = info.priority,
			label = info.label,
			seenAt = GetTime(),
		};
		local now = GetTime();
		if (not current and now - (state.lastWaveAt or 0) >= 6) then
			state.wave = (state.wave or 0) + 1;
			state.lastWaveAt = now;
			UnBotDeathwhisperNotice(
				"ВОЛНА АДДОВ — СРАЗУ ПЕРЕКЛЮЧИСЬ!\nЧЕРЕП — ПЕРВАЯ ЦЕЛЬ",
				true
			);
			UnBotSpecSummonMessage(
				"Леди: обнаружена волна аддов №"..tostring(state.wave)
				..". Видимые цели получат метки по приоритету."
			);
		elseif (info.priority <= 2) then
			UnBotDeathwhisperNotice(
				info.label.." — НЕМЕДЛЕННЫЙ ФОКУС!",
				true
			);
		end
		state.nextScanAt = 0;
	end
	return true;
end

function UnBotDeathwhisperCandidateUnits()
	local units = {
		"target", "focus", "mouseover", "targettarget", "focustarget",
		"boss1target", "boss2target", "boss3target", "boss4target",
	};
	local raidCount = GetNumRaidMembers() or 0;
	if (raidCount > 0) then
		for index = 1, math.min(40, raidCount), 1 do
			table.insert(units, "raid"..index.."target");
			table.insert(units, "raid"..index.."pettarget");
		end
	else
		for index = 1, math.min(4, GetNumPartyMembers() or 0), 1 do
			table.insert(units, "party"..index.."target");
			table.insert(units, "party"..index.."pettarget");
		end
	end
	return units;
end

function UnBotDeathwhisperVisibleAdds()
	local result = {};
	local seen = {};
	for _, unit in ipairs(UnBotDeathwhisperCandidateUnits()) do
		if (
			UnitExists(unit)
			and not UnitIsDeadOrGhost(unit)
			and (not UnitCanAttack or UnitCanAttack("player", unit))
		) then
			local guid = UnitGUID(unit);
			local info = UnBotDeathwhisperAddInfo(UnitName(unit), guid);
			if (guid and info and not seen[guid]) then
				seen[guid] = true;
				UnBotDeathwhisperRegisterAdd(guid, UnitName(unit));
				table.insert(result, {
					unit = unit,
					guid = guid,
					priority = info.priority,
					label = info.label,
				});
			end
		end
	end
	table.sort(result, function(left, right)
		if (left.priority ~= right.priority) then
			return left.priority < right.priority;
		end
		return tostring(left.guid) < tostring(right.guid);
	end);
	return result;
end

function UnBotDeathwhisperMarkVisibleAdds()
	local state = UnBotDeathwhisperControl;
	if (not state.armed or not state.active) then
		return false;
	end
	local icons = {8, 7, 6, 5, 4, 3, 2};
	local iconLabels = {
		[8] = "череп", [7] = "крест", [6] = "квадрат", [5] = "полумесяц",
		[4] = "треугольник", [3] = "ромб", [2] = "круг",
	};
	local markedAny = false;
	for index, candidate in ipairs(UnBotDeathwhisperVisibleAdds()) do
		local icon = icons[index];
		if (not icon) then
			break
		end
		local currentIcon = GetRaidTargetIndex and GetRaidTargetIndex(candidate.unit);
		if (currentIcon ~= icon) then
			local attemptKey = candidate.guid..":"..tostring(icon);
			local attempts = state.markAttempts[attemptKey] or 0;
			if (attempts < 4 and SetRaidTarget) then
				state.markAttempts[attemptKey] = attempts + 1;
				pcall(SetRaidTarget, candidate.unit, icon);
				currentIcon = GetRaidTargetIndex and GetRaidTargetIndex(candidate.unit);
			end
		end
		if (not GetRaidTargetIndex or currentIcon == icon) then
			markedAny = true;
			if (icon == 8 and not state.skullAnnouncements[candidate.guid]) then
				state.skullAnnouncements[candidate.guid] = true;
				UnBotDeathwhisperNotice(
					"ЦЕЛЬ №1: "..candidate.label.." — ЧЕРЕП",
					true
				);
				UnBotSpecSummonMessage(
					"Леди: "..candidate.label.." отмечен меткой "
					..tostring(iconLabels[icon]).." — бей первым."
				);
			end
		elseif (
			icon == 8
			and (state.markAttempts[candidate.guid..":"..tostring(icon)] or 0) >= 4
			and not state.markFailureAnnounced
		) then
			state.markFailureAnnounced = true;
			UnBotSpecSummonMessage(
				"|cffff6633Леди: метка череп не установилась после четырёх попыток. "
				.."Адд обнаружен, но клиент не дал доступного unit token/прав на метку; "
				.."поставьте череп на текущую цель вручную.|r"
			);
		end
	end
	return markedAny;
end

function UnBotDeathwhisperHandleCombatLog(...)
	local state = UnBotDeathwhisperControl;
	if (not state.armed or not state.active) then
		return;
	end
	local eventType = select(2, ...);
	local sourceGuid = select(3, ...);
	local sourceName = select(4, ...);
	local destinationGuid = select(6, ...);
	local destinationName = select(7, ...);
	if (eventType == "UNIT_DIED" or eventType == "UNIT_DESTROYED") then
		state.seen[destinationGuid] = nil;
		state.nextScanAt = 0;
		return;
	end
	UnBotDeathwhisperRegisterAdd(sourceGuid, sourceName);
	UnBotDeathwhisperRegisterAdd(destinationGuid, destinationName);
end

UnBotDeathwhisperFrame = UnBotDeathwhisperFrame
	or CreateFrame("Frame", "UnBotDeathwhisperFrame");
UnBotDeathwhisperFrame:RegisterEvent("COMBAT_LOG_EVENT_UNFILTERED");
UnBotDeathwhisperFrame:RegisterEvent("PLAYER_REGEN_DISABLED");
UnBotDeathwhisperFrame:RegisterEvent("PLAYER_REGEN_ENABLED");
UnBotDeathwhisperFrame:RegisterEvent("PLAYER_TARGET_CHANGED");
UnBotDeathwhisperFrame:RegisterEvent("UPDATE_MOUSEOVER_UNIT");
UnBotDeathwhisperFrame:RegisterEvent("RAID_TARGET_UPDATE");
UnBotDeathwhisperFrame:SetScript("OnEvent", function(self, event, ...)
	local state = UnBotDeathwhisperControl;
	if (not state.armed) then
		return;
	end
	if ((state.expiresAt or 0) > 0 and GetTime() >= state.expiresAt) then
		UnBotDeathwhisperDisarm(true);
		return;
	end
	if (event == "PLAYER_REGEN_DISABLED") then
		state.active = true;
		UnBotDeathwhisperResetTracking();
		state.nextScanAt = 0;
	elseif (event == "PLAYER_REGEN_ENABLED") then
		state.active = false;
		UnBotDeathwhisperResetTracking();
	elseif (event == "COMBAT_LOG_EVENT_UNFILTERED") then
		UnBotDeathwhisperHandleCombatLog(...);
	else
		state.nextScanAt = 0;
		if (state.active) then
			UnBotDeathwhisperMarkVisibleAdds();
		end
	end
end);
UnBotDeathwhisperFrame:SetScript("OnUpdate", function(self, elapsed)
	local state = UnBotDeathwhisperControl;
	if (not state.armed or not state.active) then
		return;
	end
	local now = GetTime();
	if ((state.expiresAt or 0) > 0 and now >= state.expiresAt) then
		UnBotDeathwhisperDisarm(true);
		return;
	end
	if (now >= (state.nextScanAt or 0)) then
		state.nextScanAt = now + 0.35;
		UnBotDeathwhisperMarkVisibleAdds();
	end
end);

UnBotGunshipMasterLoot = UnBotGunshipMasterLoot or {
	active = false,
	bossKey = nil,
	bossLabel = nil,
	modeKey = nil,
	attempts = 0,
	maxAttempts = 12,
	nextAttemptAt = 0,
	expiresAt = 0,
	settled = false,
	successAnnounced = false,
	failureAnnounced = false,
};

function UnBotGunshipMasterLootDisarm(silent)
	local state = UnBotGunshipMasterLoot;
	local wasActive = state.active;
	local bossLabel = state.bossLabel or "Босс";
	state.active = false;
	state.bossKey = nil;
	state.bossLabel = nil;
	state.modeKey = nil;
	state.attempts = 0;
	state.nextAttemptAt = 0;
	state.expiresAt = 0;
	state.settled = false;
	state.successAnnounced = false;
	state.failureAnnounced = false;
	state.summonGuard = false;
	state.summonDeadline = nil;
	if (not state.paused) then state.resumePost = nil; end
	state.trialCount = 0;
	state.checkedTrial = nil;
	state.trialNames = {};
	state.trialCheckAt = nil;
	state.trialWarning = nil;
	if (wasActive and not silent) then
		UnBotSpecSummonMessage(
			bossLabel..": автоустановка мастер-лута отменена."
		);
	end
end

function UnBotGunshipMasterLootPlayerIsMaster()
	if (not GetLootMethod) then
		return false;
	end
	local method, partyIndex, raidIndex = GetLootMethod();
	if (method ~= "master") then
		return false;
	end
	local playerName = UnBotSpecSummonNormalize(UnitName("player") or "");
	if ((GetNumRaidMembers() or 0) > 0) then
		local index = tonumber(raidIndex);
		if (not index or index < 1) then
			return false;
		end
		local masterName = GetRaidRosterInfo and GetRaidRosterInfo(index);
		return UnBotSpecSummonNormalize(masterName or "") == playerName;
	end
	local index = tonumber(partyIndex);
	if (index == 0) then
		return true;
	end
	if (index and index > 0) then
		return UnBotSpecSummonNormalize(UnitName("party"..index) or "")
			== playerName;
	end
	return false;
end

function UnBotGunshipMasterLootAnnounceSuccess()
	local state = UnBotGunshipMasterLoot;
	state.settled = true;
	state.nextAttemptAt = GetTime() + 2;
	if (not state.successAnnounced) then
		state.successAnnounced = true;
		UnBotSpecSummonMessage(
			(state.bossLabel or "Босс")..": установлен метод добычи "
			.."«Ответственный за добычу»; мастер — "
			..tostring(UnitName("player") or "игрок").."."
		);
	end
end

function UnBotGunshipMasterLootShowFailureAlert(details)
	local state = UnBotGunshipMasterLoot;
	local frame = state.failureAlertFrame;
	if (not frame) then
		frame = CreateFrame("Frame", nil, UIParent);
		frame:SetFrameStrata("FULLSCREEN_DIALOG");
		frame:SetWidth(900);
		frame:SetHeight(170);
		frame:SetPoint("CENTER", UIParent, "CENTER", 0, 130);
		frame:SetBackdrop({
			bgFile = "Interface\\Tooltips\\UI-Tooltip-Background",
			edgeFile = "Interface\\Tooltips\\UI-Tooltip-Border",
			tile = true, tileSize = 16, edgeSize = 20,
			insets = { left = 5, right = 5, top = 5, bottom = 5 },
		});
		frame:SetBackdropColor(0.25, 0, 0, 0.95);
		frame:SetBackdropBorderColor(1, 0.1, 0.1, 1);
		frame:EnableMouse(false);
		frame.title = frame:CreateFontString(nil, "OVERLAY");
		frame.title:SetFont(STANDARD_TEXT_FONT, 32, "OUTLINE");
		frame.title:SetPoint("TOP", frame, "TOP", 0, -25);
		frame.title:SetTextColor(1, 0.15, 0.15);
		frame.title:SetText("МАСТЕР-ЛУТ НЕ ВКЛЮЧИЛСЯ!");
		frame.details = frame:CreateFontString(nil, "OVERLAY");
		frame.details:SetFont(STANDARD_TEXT_FONT, 22, "OUTLINE");
		frame.details:SetPoint("TOP", frame.title, "BOTTOM", 0, -15);
		frame.details:SetWidth(850);
		frame.details:SetJustifyH("CENTER");
		frame.details:SetTextColor(1, 0.85, 0.2);
		frame:SetScript("OnUpdate", function(self)
			if (GetTime() >= (self.hideAt or 0)) then
				self:Hide();
			end
		end);
		state.failureAlertFrame = frame;
	end
	frame.details:SetText(details or (
		"НЕ НАЧИНАЙ БОЙ! Сбор остановлен.\n"
		.."Выключите мастер-лут или выполните /reload."
	));
	frame.hideAt = GetTime() + 5;
	frame:Show();
	if (PlaySound) then
		PlaySound("RaidWarning");
	end
end

function UnBotGunshipMasterLootFail(text)
	local state = UnBotGunshipMasterLoot;
	if (not state.failureAnnounced) then
		state.failureAnnounced = true;
		UnBotGunshipMasterLootShowFailureAlert();
		if (UnBotLootSettings) then UnBotLootSettings.RaidWarning("Ответственный за добычу не включается. "..tostring(text or "")); end
		UnBotSpecSummonMessage(
			"|cffff6060"..(state.bossLabel or "Босс")..": "
			..tostring(text or "не удалось установить мастер-лут.")
			.." Не начинай бой. Выключите мастер-лут или выполните /reload. "
			.."После снятия галочки нажмите «Призвать» — сбор продолжится с того же места.|r"
		);
	end
	state.active = false;
	state.settled = false;
	if (state.summonGuard) then
		UnBotGunshipMasterLoot.PauseSummon();
	end
end

-- A raid-boss click checks the existing roster once, independently of summon options.
function UnBotGunshipMasterLoot.HasGroupBots()
	for name in pairs(UnBotSpecSummonGetMembers()) do
		if (name ~= UnitName("player") and (
			(UnBotBotRegistry.bots and UnBotBotRegistry.bots[name])
			or UnBotKnownBots[name]
		)) then return true; end
	end
	return false;
end

function UnBotGunshipMasterLoot.FailBossClick(reason)
	local state = UnBotGunshipMasterLoot;
	local check = state.bossClickCheck;
	if (not check) then return; end
	state.bossClickCheck = nil;
	if (UnBotLootSettings) then
		UnBotLootSettings.Warning(check.bossLabel..": «Ответственный за добычу» не включается. "..reason);
		return;
	end
	UnBotGunshipMasterLootShowFailureAlert(
		"НЕ НАЧИНАЙ БОЙ! Мастер-лут не включается.\n"..reason
	);
	UnBotSpecSummonMessage("|cffff6060"..check.bossLabel
		..": мастер-лут не включается. "..reason.."|r");
end

function UnBotGunshipMasterLoot.UpdateBossClick()
	local state = UnBotGunshipMasterLoot;
	local check = state.bossClickCheck;
	if (not check or GetTime() < check.checkAt) then return; end
	if (not state.HasGroupBots()) then
		state.bossClickCheck = nil;
	elseif (GetLootMethod and GetLootMethod() == "master") then
		state.bossClickCheck = nil;
		UnBotSpecSummonMessage(check.bossLabel
			..": установлен метод добычи «Ответственный за добычу».");
	else
		state.FailBossClick("Сервер не подтвердил смену метода добычи. Проверьте права лидера; при повторном отказе полностью перезапустите WoW.");
	end
end

function UnBotGunshipMasterLoot.CheckBossClick(bossKey)
	local state = UnBotGunshipMasterLoot;
	local boss = bossKey and UnBotBossPresetFindBoss(bossKey);
	if (not boss or (boss.instanceType or "raid") ~= "raid"
		or not state.HasGroupBots()) then return; end
	if (UnBotLootSettings) then
		if (not UnBotLootSettings.Get().bossSelection) then return; end
		UnBotLootSettings.BossChoice();
	end
	if (GetLootMethod and GetLootMethod() == "master") then
		state.bossClickCheck = nil;
		return;
	end
	-- Several clicks while awaiting the same server response do not resend.
	if (state.bossClickCheck) then
		state.bossClickCheck.bossLabel = boss.label;
		return;
	end
	state.bossClickCheck = {bossLabel = boss.label, checkAt = GetTime() + 1.5};
	if ((InCombatLockdown and InCombatLockdown())
		or (UnitAffectingCombat and UnitAffectingCombat("player"))) then
		state.FailBossClick("Смена метода добычи сейчас недоступна в бою.");
		return;
	end
	if (not SetLootMethod or not GetLootMethod) then
		state.FailBossClick("Клиент не предоставил API смены метода добычи.");
		return;
	end
	local ok = pcall(SetLootMethod, "master", UnitName("player"));
	if (not ok) then
		state.FailBossClick("Клиент отклонил смену метода добычи.");
		return;
	end
	if (GetLootMethod() == "master") then
		state.bossClickCheck.checkAt = GetTime();
		state.UpdateBossClick();
	end
end

function UnBotGunshipMasterLoot.BeginSummon()
	if (UnBotLootSettings) then
		UnBotLootSettings.Get().manualGroupOverride = nil;
		UnBotLootSettings.bossLootHold = nil;
	end
	UnBotGunshipMasterLoot.bossClickCheck = nil;
	UnBotGunshipMasterLootDisarm(true);
	UnBotGunshipMasterLoot.resumeWithoutLoot = nil;
	if (not UnBotSquadConfig or UnBotSquadConfig.forceMasterLootAfterSummon == false) then return; end
	UnBotGunshipMasterLoot.summonGuard = true;
	UnBotGunshipMasterLoot.checkedTrial = 0;
	UnBotSquadBuilderArmMasterLoot();
end

function UnBotGunshipMasterLoot.RecordAttempt(name)
	local state = UnBotGunshipMasterLoot;
	if (not state.summonGuard) then return; end
	-- An add command may be refused or need an explicit invitation. Only a
	-- roster-confirmed join consumes a loot check; the summon controller owns
	-- the finite invitation/replacement attempts and their timeout.
	state.trialNames = state.trialNames or {};
	if (name and state.trialNames[name] == nil) then state.trialNames[name] = false; end
end

function UnBotGunshipMasterLoot.PauseSummon()
	local state = UnBotGunshipMasterLoot;
	if (state.paused) then return; end
	state.paused, state.pauseAt, state.summonGuard = true, GetTime(), false;
	state.pauseContext = UnBotRegistryCurrentContext and UnBotRegistryCurrentContext();
	state.pauseSignature = UnBotSquadSummon and UnBotSquadSummon.Signature
		and UnBotSquadSummon.Signature();
	state.pausedControllers = {};
	for _, controller in ipairs({UnBotSpecSummon or {}, UnBotSquadSpecCheck or {},
		UnBotSquadNearbyGate or {}, UnBotSquadSummon or {}, UnBotPVPSummon or {}, UnBotRaidReserve or {}}) do
		table.insert(state.pausedControllers, {controller = controller, active = controller.active,
			autoStartAt = controller.autoStartAt, autoPrepareAt = controller.autoPrepareAt});
		controller.active = false;
		if (controller.autoStartAt) then controller.autoStartAt = 0; end
		if (controller.autoPrepareAt) then controller.autoPrepareAt = 0; end
	end
	UnBotSpecSummonMessage("Сбор остановлен: мастер-лут не включился. Выключите мастер-лут или выполните /reload. После снятия галочки нажмите «Призвать» — продолжу с того же места.");
	if (UnBotSquadBuilderRefresh) then UnBotSquadBuilderRefresh(); end
	if (UnBotPVPSquad) then UnBotPVPSquad.Refresh(); end
end

function UnBotGunshipMasterLoot.RestoreSummon()
	local state, now = UnBotGunshipMasterLoot, GetTime();
	local elapsed = now - (state.pauseAt or now);
	local function ShiftTimers(controller, keys)
		for _, key in ipairs(keys) do
			if (type(controller[key]) == "number" and controller[key] > 0) then
				controller[key] = controller[key] + elapsed;
			end
		end
	end
	for _, saved in ipairs(state.pausedControllers or {}) do
		local controller = saved.controller;
		controller.active = saved.active;
		controller.autoStartAt, controller.autoPrepareAt = saved.autoStartAt, saved.autoPrepareAt;
		ShiftTimers(controller, {"nextTime", "nextTick", "deadline", "untilTime", "stageTime",
			"stageUntil", "inviteAt", "autoStartAt", "autoPrepareAt", "lastSend", "idleAt"});
		if (controller.op) then ShiftTimers(controller.op, {"at"}); end
		for _, queueKey in ipairs({"cleanup", "cleanupQueue", "kickQueue", "removals"}) do
			for _, entry in pairs(controller[queueKey] or {}) do
				ShiftTimers(entry, {"at", "nextTime", "untilTime", "deadline"});
			end
		end
		for name, deadline in pairs(controller.registryRequests or {}) do
			controller.registryRequests[name] = deadline + elapsed;
		end
	end
	-- Prefetched bots remain in the queue; do not resend their already issued add.
	for _, entry in ipairs((UnBotSpecSummon.squad and UnBotSpecSummon.squad.prefetch) or {}) do
		ShiftTimers(entry, {"sentAt"});
	end
	state.paused, state.pausedControllers = false, nil;
end

function UnBotGunshipMasterLoot.ResumeSummon()
	local state = UnBotGunshipMasterLoot;
	if (not state.paused) then return false; end
	if (UnitAffectingCombat("player") or (InCombatLockdown and InCombatLockdown())) then
		UnBotSpecSummonMessage("Продолжение сбора доступно вне боя."); return false;
	end
	if (UnBotSquadConfig.forceMasterLootAfterSummon ~= false and not UnBotGunshipMasterLootPlayerIsMaster()) then
		UnBotSpecSummonMessage("Сбор остановлен: выключите мастер-лут или выполните /reload, затем нажмите «Призвать»."); return false;
	end
	if ((state.pauseContext and UnBotRegistryCurrentContext() ~= state.pauseContext)
		or (state.pauseSignature and UnBotSquadSummon.Signature() ~= state.pauseSignature)) then
		UnBotSpecSummonMessage("Состав или мир изменён: нажмите «Стоп», затем начните новый сбор."); return false;
	end
	UnBotGunshipMasterLoot.RestoreSummon();
	state.failureAnnounced = false;
	state.summonGuard = UnBotSquadConfig.forceMasterLootAfterSummon ~= false;
	state.resumeWithoutLoot = not state.summonGuard;
	state.active = state.summonGuard;
	state.trialCount, state.checkedTrial, state.summonDeadline = 0, nil, nil;
	if (state.failureAlertFrame) then state.failureAlertFrame:Hide(); end
	UnBotSpecSummonMessage("Сбор продолжен с остановленного места; ранее призванные боты сохранены.");
	if (state.resumePost) then state.resumePost = nil; UnBotSquadPostSummonContinue(); end
	if (UnBotSquadBuilderRefresh) then UnBotSquadBuilderRefresh(); end
	if (UnBotPVPSquad) then UnBotPVPSquad.Refresh(); end
	return true;
end

function UnBotGunshipMasterLoot.CheckSummon(requireVerified)
	local state, now = UnBotGunshipMasterLoot, GetTime();
	if (state.paused) then return false; end
	if (not state.summonGuard or UnBotSquadConfig.forceMasterLootAfterSummon == false) then return true; end
	state.expiresAt = now + 90;
	for name, joined in pairs(state.trialNames or {}) do
		if (not joined and UnBotSpecSummonIsInGroup(name)) then
			state.trialNames[name] = true;
			state.trialCount = (state.trialCount or 0) + 1;
			state.checkedTrial = nil;
			state.trialCheckAt = now + 1;
		end
	end
	-- Master loot cannot be configured solo. Never stop invitation/replacement
	-- work for a loot failure while nobody has joined the player's group.
	if ((GetNumPartyMembers() or 0) == 0 and (GetNumRaidMembers() or 0) <= 1) then
		return true;
	end
	if (UnBotGunshipMasterLootPlayerIsMaster()) then
		state.summonDeadline = nil;
		state.trialCount = 0;
		state.checkedTrial = nil;
		state.trialWarning = nil;
		state.attempts = 0;
		UnBotGunshipMasterLootAnnounceSuccess();
		return true;
	end
	state.settled = false;
	if (state.checkedTrial ~= (state.trialCount or 0)) then
		state.checkedTrial = state.trialCount or 0;
		UnBotGunshipMasterLootTry();
		if (state.settled) then return UnBotGunshipMasterLoot.CheckSummon(requireVerified); end
	end
	if ((state.trialCount or 0) >= 3 or requireVerified) then
		state.summonDeadline = state.summonDeadline or math.max(now + 1, state.trialCheckAt or 0);
		if (now >= state.summonDeadline) then
			UnBotGunshipMasterLootFail("мастер-лут не включился после проверки призванных ботов.");
		end
		return false;
	end
	if (not state.trialWarning and (state.trialCount or 0) > 0) then
		state.trialWarning = true;
		UnBotSpecSummonMessage("Мастер-лут пока не включился: проверю ещё после двух следующих призывов.");
	end
	return true;
end

function UnBotGunshipMasterLootTry()
	local state = UnBotGunshipMasterLoot;
	if (not state.active) then
		return false;
	end
	local now = GetTime();
	if (now >= (state.expiresAt or 0)) then
		UnBotGunshipMasterLootFail(
			"группа или права лидера не появились за 90 секунд."
		);
		return false;
	end
	if (
		(GetNumRaidMembers() or 0) == 0
		and (GetNumPartyMembers() or 0) == 0
	) then
		state.nextAttemptAt = now + 0.75;
		return false;
	end
	if (UnitAffectingCombat and UnitAffectingCombat("player")) then
		state.nextAttemptAt = now + 1;
		return false;
	end
	if (UnBotGunshipMasterLootPlayerIsMaster()) then
		UnBotGunshipMasterLootAnnounceSuccess();
		return true;
	end
	if (not SetLootMethod) then
		if (state.summonGuard) then return false; end
		UnBotGunshipMasterLootFail("клиент не предоставил SetLootMethod.");
		return false;
	end
	if ((state.attempts or 0) >= (state.maxAttempts or 12)) then
		UnBotGunshipMasterLootFail(
			"после 12 попыток метод не применился."
		);
		return false;
	end
	state.attempts = (state.attempts or 0) + 1;
	state.nextAttemptAt = now + 0.75;
	pcall(SetLootMethod, "master", UnitName("player"));
	if (UnBotGunshipMasterLootPlayerIsMaster()) then
		UnBotGunshipMasterLootAnnounceSuccess();
		return true;
	end
	return false;
end

function UnBotGunshipMasterLootArm(bossKey, modeKey, labelOverride)
	local state = UnBotGunshipMasterLoot;
	-- Previewing a boss or enabling a checkbox is not a summon request.
	if (not state.summonGuard or state.paused) then return false; end
	local boss = bossKey and UnBotBossPresetFindBoss(bossKey);
	local continuing = state.active and state.bossKey == bossKey;
	state.active = true;
	state.bossKey = bossKey;
	state.bossLabel = labelOverride
		or (boss and boss.label)
		or tostring(bossKey or "Призыв состава");
	state.modeKey = modeKey;
	state.expiresAt = GetTime() + 90;
	state.nextAttemptAt = 0;
	state.settled = false;
	if (not continuing) then
		state.attempts = 0;
		state.successAnnounced = false;
		state.failureAnnounced = false;
		if (
			(GetNumRaidMembers() or 0) == 0
			and (GetNumPartyMembers() or 0) == 0
		) then
			UnBotSpecSummonMessage(
				state.bossLabel..": "
				..(bossKey and "босс выбран; " or "")
				.."после создания группы автоматически включу мастер-лут на игрока."
			);
		else
			UnBotSpecSummonMessage(
				state.bossLabel..": "
				..(bossKey and "босс выбран; " or "")
				.."автоматически включаю мастер-лут на игрока."
			);
		end
	end
	UnBotGunshipMasterLootTry();
	return true;
end

function UnBotBossPresetArmMasterLoot(bossKey, modeKey)
	if (UnBotLootSettings) then
		if (UnBotSquadConfig.forceMasterLootAfterSummon == false or UnBotLootSettings.Get().manualGroupOverride) then return false; end
		return UnBotGunshipMasterLootArm(bossKey, modeKey);
	end
	local preset = modeKey and UnBotBossPresetEditableGet(
		bossKey,
		modeKey,
		false
	);
	if (preset and preset.masterLootEnabled == false) then
		UnBotGunshipMasterLootDisarm(true);
		return false;
	end
	return UnBotGunshipMasterLootArm(bossKey, modeKey);
end

function UnBotSquadBuilderArmMasterLoot()
	if (
		not UnBotSquadConfig
		or UnBotSquadConfig.forceMasterLootAfterSummon == false
	) then
		return false;
	end
	local source = UnBotSquadBuilder.pendingBossPreset
		or UnBotSquadBuilder.loadedBossPreset;
	local bossKey = source and source.bossKey;
	local modeKey = source and source.modeKey;
	return UnBotGunshipMasterLootArm(
		bossKey,
		modeKey,
		bossKey and nil or "Призыв состава"
	);
end

UnBotGunshipMasterLootFrame = UnBotGunshipMasterLootFrame
	or CreateFrame("Frame", "UnBotGunshipMasterLootFrame");
UnBotGunshipMasterLootFrame:RegisterEvent("PARTY_MEMBERS_CHANGED");
UnBotGunshipMasterLootFrame:RegisterEvent("RAID_ROSTER_UPDATE");
UnBotGunshipMasterLootFrame:RegisterEvent("PLAYER_REGEN_ENABLED");
UnBotGunshipMasterLootFrame:SetScript("OnEvent", function()
	local state = UnBotGunshipMasterLoot;
	if (not state.active) then return; end
	if (not state.summonGuard) then
		UnBotGunshipMasterLootDisarm(true);
		return;
	end
	if (state.settled or (state.attempts or 0) == 0) then state.nextAttemptAt = 0; end
	UnBotGunshipMasterLoot.CheckSummon();
end);
UnBotGunshipMasterLootFrame:SetScript("OnUpdate", function()
	local state = UnBotGunshipMasterLoot;
	state.UpdateBossClick();
	if (not state.active) then return; end
	if (not state.summonGuard) then
		UnBotGunshipMasterLootDisarm(true);
		return;
	end
	if (not UnBotGunshipMasterLoot.CheckSummon(state.resumePost)) then return; end
	if (state.resumePost) then
		state.resumePost = nil;
		UnBotSquadPostSummonContinue();
	end
end);

function UnBotBossPresetAfterSquadComplete()
	local pending = UnBotSquadBuilder.pendingBossPreset;
	UnBotSquadBuilder.pendingBossPreset = nil;
	if (not pending) then
		return;
	end
	if UnBotGuardPosts and UnBotGuardPosts.Presets and UnBotGuardPosts.Presets.Quick then
		UnBotGuardPosts.Presets.Quick.Corridor:OnComplete(pending);
	end
	local autoStrategyEnabled = UnBotBossPresetAutoStrategyEnabled(
		pending.bossKey,
		pending.modeKey
	);
	if (UnBotBossPresetArmMasterLoot and not UnBotGunshipMasterLoot.resumeWithoutLoot) then
		UnBotBossPresetArmMasterLoot(pending.bossKey, pending.modeKey);
	end
	UnBotBossPresetGuideShowStartWarning(pending.bossKey, pending.modeKey);
	if autoStrategyEnabled and pending.bossKey == "the_ruby_sanctum__halion" then
		if UnBotSindragosaBroadcast("co -rs") then
			UnBotSpecSummonMessage("Халион: группе отправлено co -rs (отключение стратегии РС). Проверьте ответ ботов.");
		else
			UnBotSpecSummonMessage("Халион: co -rs не отправлено — нет группы.");
		end
	end
	if (
		autoStrategyEnabled
		and
		pending.bossKey == "lord_marrowgar"
		and UnBotMarrowgarArmPreset
	) then
		UnBotMarrowgarArmPreset(pending.modeKey);
	elseif (
		autoStrategyEnabled
		and
		pending.bossKey == "professor_putricide"
		and UnBotPutricidePreparePreset
	) then
		UnBotPutricidePreparePreset(pending.modeKey);
	elseif (
		autoStrategyEnabled
		and
		pending.bossKey == "valithria_dreamwalker"
		and UnBotValithriaPreparePreset
	) then
		UnBotValithriaPreparePreset(pending.modeKey);
	elseif (
		autoStrategyEnabled
		and
		pending.bossKey == "sister_svalna"
		and UnBotSvalnaPreparePreset
	) then
		UnBotSvalnaPreparePreset(pending.modeKey);
	end
end

function UnBotSquadPresetMemberLimit(pending)
	local modeKey = pending and tostring(pending.modeKey or "") or "";
	if (modeKey == "40n5") then return 3; end -- One paladin tank, one healer and the player.
	if (modeKey == "40n6") then return 7; end -- Six bots plus the player; the raid difficulty remains 40.
	if (modeKey == "25h18") then
		return 4;
	end
	local size = tonumber(string.match(modeKey, "^(%d+)"));
	if (size == 5 or size == 10 or size == 20 or size == 25 or size == 40) then
		return size;
	end
	return nil;
end

function UnBotSquadPostSummonContinue()
	if (UnBotGunshipMasterLoot and UnBotGunshipMasterLoot.CheckSummon
		and not UnBotGunshipMasterLoot.CheckSummon(true)) then
		if (UnBotGunshipMasterLoot.active) then UnBotGunshipMasterLoot.resumePost = true; end
		return;
	end
	local sequence = UnBotSquadBuilder.postSummonSequence;
	if (not sequence) then
		if (UnBotBossPresetAfterSquadComplete) then
			UnBotBossPresetAfterSquadComplete();
		end
		return;
	end
	if (sequence.requireArrival and not sequence.arrivalChecked) then
		local result = UnBotSquadNearbyGateStart(function()
			sequence.arrivalChecked = true;
			UnBotSquadPostSummonContinue();
		end, sequence.arrivalNames or {});
		if (result ~= "ready") then return; end
		sequence.arrivalChecked = true;
		UnBotSquadNearbyGateStop(nil, false);
		UnBotSpecSummonMessage("Состав собран: все выбранные боевые боты рядом с игроком.");
	end
	if (
		UnBotSquadConfig.forceMasterLootAfterSummon ~= false
		and not sequence.masterLootFinalChecked
	) then
		sequence.masterLootFinalChecked = true;
		if (UnBotSquadBuilderArmMasterLoot and not UnBotGunshipMasterLoot.summonGuard) then
			UnBotSquadBuilderArmMasterLoot();
		end
	end

	if (sequence.buffRaid and not sequence.buffStageFinished) then
		sequence.buffStageFinished = true;
		UnBotSpecSummonMessage(
			sequence.bossPreset
			and "Состав и спеки готовы. Этап 2/3: добаффаю текущим составом; временные баферы — только при наличии места."
			or "Состав и спеки готовы. Этап 2/2: добаффаю текущим составом; временные баферы — только при наличии места."
		);
		local started, startReason = UnBotRaidBuffCycleStart(
			UnBotSquadPostSummonContinue,
			sequence.memberLimit
		);
		if (started) then
			if (startReason ~= "nearby-replacing") then
				sequence.buffStarted = true;
			end
			return;
		end
		if (startReason == "nearby-blocked") then
			UnBotSpecSummonMessage(
				"Автоматическая очередь остановлена: предбаффовую проверку нельзя безопасно выполнить."
			);
			return;
		end
		UnBotSpecSummonMessage(
			"Автоматический баф рейда не запущен; продолжаю очередь без повторного спама."
		);
	end

	UnBotSquadBuilder.postSummonSequence = nil;
	local pending = UnBotSquadBuilder.pendingBossPreset;
	if (UnBotTwinEmperors and UnBotTwinEmperors.SquadReady
		and UnBotSquadBuilder.loadedBossPreset
		and UnBotSquadBuilder.loadedBossPreset.bossKey == "temple_of_ahn_qiraj__the_twin_emperors") then
		UnBotTwinEmperors:SquadReady();
	end
	local hasBossCommands = pending
		and UnBotBossPresetAutoStrategyEnabled(pending.bossKey, pending.modeKey)
		and (
		pending.bossKey == "lord_marrowgar"
		or pending.bossKey == "professor_putricide"
		or pending.bossKey == "the_ruby_sanctum__halion"
		or pending.bossKey == "valithria_dreamwalker"
		or pending.bossKey == "sister_svalna"
		);
	if (hasBossCommands) then
		UnBotSpecSummonMessage(
			sequence.buffStarted
			and "Баф рейда завершён. Этап 3/3: применяю команды выбранного босса."
			or (
				sequence.buffRaid
				and "Этап 3/3: применяю команды выбранного босса."
				or "Состав и спеки готовы: применяю команды выбранного босса."
			)
		);
	end
	if (UnBotBossPresetAfterSquadComplete) then
		UnBotBossPresetAfterSquadComplete();
	end
	if (UnBotGunshipMasterLoot) then UnBotGunshipMasterLoot.summonGuard = false; end
	if (UnBotSummonLog) then UnBotSummonLog.Safe("CompletePVE",sequence); end
	if (UnBotSquadLoot and not (UnBotSquadSummon and UnBotSquadSummon.active)) then UnBotSquadLoot.Auto(); end
end

UnBotSvalnaControl = UnBotSvalnaControl or {
	armed = false,
	modeKey = nil,
	phase = 0,
	bossGuid = nil,
	trackedMobs = {},
	deadMobs = {},
	mobSeen = false,
	emptySince = nil,
	combatStartedAt = nil,
	nextScanAt = 0,
	nextMarkAt = 0,
	markAttempts = 0,
	markFailureAnnounced = false,
	markAnnouncedPhase = 0,
	markConfirmedPhase = 0,
	commandStep = 1,
	commandRounds = 0,
	nextCommandAt = 0,
	expiresAt = 0,
};

function UnBotSvalnaNameMatches(name, guid)
	local originalName = tostring(name or "");
	local normalized = UnBotSpecSummonNormalize(name);
	if (
		string.find(normalized, "sister svalna", 1, true)
		or string.find(originalName, "Сестра Свална", 1, true)
		or string.find(normalized, "сестра свална", 1, true)
	) then
		return true;
	end
	local hex = string.match(tostring(guid or ""), "^0[xX](%x+)$");
	return hex and #hex >= 10
		and tonumber(string.sub(hex, 5, 10), 16) == 37126
		or false;
end

function UnBotSvalnaCandidateUnits()
	local units = {
		"boss1", "boss2", "boss3", "boss4",
		"target", "focus", "mouseover", "targettarget",
	};
	local raidCount = GetNumRaidMembers() or 0;
	if (raidCount > 0) then
		for i = 1, math.min(40, raidCount), 1 do
			table.insert(units, "raid"..i.."target");
		end
	else
		for i = 1, math.min(4, GetNumPartyMembers() or 0), 1 do
			table.insert(units, "party"..i.."target");
		end
	end
	return units;
end

function UnBotSvalnaFindBossUnit()
	for _, unit in ipairs(UnBotSvalnaCandidateUnits()) do
		if (
			UnitExists(unit)
			and not UnitIsDeadOrGhost(unit)
			and UnBotSvalnaNameMatches(UnitName(unit), UnitGUID(unit))
		) then
			return unit;
		end
	end
	return nil;
end

function UnBotSvalnaIsHostileNpcFlags(flags)
	flags = tonumber(flags);
	return flags
		and bit
		and bit.band
		and bit.band(flags, 2048) ~= 0
		and bit.band(flags, 64) ~= 0
		or false;
end

function UnBotSvalnaTrackHostile(guid, name, flags)
	local state = UnBotSvalnaControl;
	if (
		not state.armed
		or state.phase ~= 1
		or not state.bossGuid
		or not guid
		or state.deadMobs[guid]
		or UnBotSvalnaNameMatches(name, guid)
		or not UnBotSvalnaIsHostileNpcFlags(flags)
	) then
		return false;
	end
	state.trackedMobs[guid] = GetTime();
	state.mobSeen = true;
	state.emptySince = nil;
	return true;
end

function UnBotSvalnaTrackVisibleAdds()
	local state = UnBotSvalnaControl;
	for _, unit in ipairs(UnBotSvalnaCandidateUnits()) do
		if (
			UnitExists(unit)
			and not UnitIsDeadOrGhost(unit)
			and UnitCanAttack("player", unit)
			and not UnBotSvalnaNameMatches(UnitName(unit), UnitGUID(unit))
		) then
			local guid = UnitGUID(unit);
			if (guid and not state.deadMobs[guid]) then
				state.trackedMobs[guid] = GetTime();
				state.mobSeen = true;
				state.emptySince = nil;
			end
		end
	end
end

function UnBotSvalnaAnnounceMark()
	local state = UnBotSvalnaControl;
	if (state.markAnnouncedPhase == state.phase) then
		return;
	end
	state.markAnnouncedPhase = state.phase;
	if (state.phase == 1) then
		UnBotSpecSummonMessage(
			"Свална: фаза 1 — на боссе установлена Луна. Сначала зачищаем мобов вокруг неё."
		);
	else
		UnBotSpecSummonMessage(
			"Свална: фаза 2 — на боссе установлен череп; танк и ДД фокусят только Свалну."
		);
	end
end

function UnBotSvalnaTryTargetBoss()
	if (not TargetByName or UnitAffectingCombat("player")) then
		return nil;
	end
	for _, bossName in ipairs({ "Сестра Свална", "Sister Svalna" }) do
		pcall(TargetByName, bossName, true);
		if (
			UnitExists("target")
			and not UnitIsDeadOrGhost("target")
			and UnBotSvalnaNameMatches(UnitName("target"), UnitGUID("target"))
		) then
			return "target";
		end
	end
	return nil;
end

function UnBotSvalnaEnsureMark()
	local state = UnBotSvalnaControl;
	if (state.markConfirmedPhase == state.phase) then
		return true;
	end
	local now = GetTime();
	if (now < (state.nextMarkAt or 0)) then
		return false;
	end
	state.nextMarkAt = now + 10;
	state.markAttempts = (state.markAttempts or 0) + 1;
	local unit = UnBotSvalnaFindBossUnit() or UnBotSvalnaTryTargetBoss();
	if (not unit) then
		return false;
	end
	state.bossGuid = UnitGUID(unit) or state.bossGuid;
	local wanted = state.phase == 2 and 8 or 5;
	if (GetRaidTargetIndex and GetRaidTargetIndex(unit) == wanted) then
		state.markConfirmedPhase = state.phase;
		UnBotSvalnaAnnounceMark();
		return true;
	end
	if (SetRaidTarget) then
		pcall(SetRaidTarget, unit, wanted);
	end
	if (GetRaidTargetIndex and GetRaidTargetIndex(unit) == wanted) then
		state.markConfirmedPhase = state.phase;
		UnBotSvalnaAnnounceMark();
		return true;
	end
	return false;
end

function UnBotSvalnaBeginPhaseTwo(reason)
	local state = UnBotSvalnaControl;
	if (not state.armed or state.phase ~= 1) then
		return;
	end
	state.phase = 2;
	state.trackedMobs = {};
	state.emptySince = nil;
	state.markAttempts = 0;
	state.markFailureAnnounced = false;
	state.nextMarkAt = 0;
	state.markConfirmedPhase = 0;
	state.commandStep = 1;
	state.commandRounds = 0;
	state.nextCommandAt = 0;
	local transitionText = reason == "сама Свална вступила в бой"
		and "Свална: подтверждено прямое вступление босса в бой"
		or (
			"Свална: все мобы вокруг убиты"
			..(reason and (" — "..reason) or "")
		);
	UnBotSpecSummonMessage(
		transitionText..". Перехожу к фазе 2 и меняю Луну на Череп."
	);
	UnBotSvalnaEnsureMark();
end

function UnBotSvalnaRunFocusCommands()
	local state = UnBotSvalnaControl;
	if (
		state.phase ~= 2
		or (state.commandRounds or 0) >= 3
		or GetTime() < (state.nextCommandAt or 0)
	) then
		return;
	end
	local bossUnit = UnBotSvalnaFindBossUnit();
	if (
		not bossUnit
		or not GetRaidTargetIndex
		or GetRaidTargetIndex(bossUnit) ~= 8
	) then
		return;
	end
	local commands = {
		"@tank rti skull",
		"@tank attack rti target",
		"@dps rti skull",
		"@dps attack rti target",
	};
	UnBotSindragosaBroadcast(commands[state.commandStep]);
	state.commandStep = state.commandStep + 1;
	if (state.commandStep > #commands) then
		state.commandStep = 1;
		state.commandRounds = (state.commandRounds or 0) + 1;
		state.nextCommandAt = GetTime() + 0.9;
	else
		state.nextCommandAt = GetTime() + 0.25;
	end
end

function UnBotSvalnaDisarm(silent)
	local state = UnBotSvalnaControl;
	local wasArmed = state.armed;
	state.armed = false;
	state.modeKey = nil;
	state.phase = 0;
	state.bossGuid = nil;
	state.trackedMobs = {};
	state.deadMobs = {};
	state.mobSeen = false;
	state.emptySince = nil;
	state.combatStartedAt = nil;
	state.nextScanAt = 0;
	state.nextMarkAt = 0;
	state.markAttempts = 0;
	state.markFailureAnnounced = false;
	state.markAnnouncedPhase = 0;
	state.markConfirmedPhase = 0;
	state.commandStep = 1;
	state.commandRounds = 0;
	state.nextCommandAt = 0;
	state.expiresAt = 0;
	if (wasArmed and not silent) then
		UnBotSpecSummonMessage("Свална: двухфазный контроль остановлен.");
	end
end

function UnBotSvalnaPreparePreset(modeKey)
	local state = UnBotSvalnaControl;
	if (state.armed and state.modeKey == modeKey) then
		UnBotSvalnaEnsureMark();
		return;
	end
	UnBotSvalnaDisarm(true);
	state.armed = true;
	state.modeKey = modeKey;
	state.phase = 1;
	state.expiresAt = GetTime() + 1200;
	UnBotSpecSummonMessage(
		"Свална ("..tostring(modeKey or "режим")
		.."): возьмите минимум 2 ботов для снятия копья. Двухфазный контроль включён на 20 минут: сначала Луна на Свалне, при начале боя с ней — Череп."
	);
	UnBotSvalnaEnsureMark();
end

UnBotSvalnaFrame = UnBotSvalnaFrame
	or CreateFrame("Frame", "UnBotSvalnaFrame");
UnBotSvalnaFrame:RegisterEvent("COMBAT_LOG_EVENT_UNFILTERED");
UnBotSvalnaFrame:RegisterEvent("PLAYER_REGEN_DISABLED");
UnBotSvalnaFrame:RegisterEvent("PLAYER_REGEN_ENABLED");
UnBotSvalnaFrame:RegisterEvent("RAID_TARGET_UPDATE");
UnBotSvalnaFrame:SetScript("OnEvent", function(self, event, ...)
	local state = UnBotSvalnaControl;
	if (not state.armed) then
		return;
	end
	if (event == "RAID_TARGET_UPDATE") then
		state.nextScanAt = 0;
		return;
	elseif (event == "PLAYER_REGEN_DISABLED") then
		state.combatStartedAt = GetTime();
		if (state.phase == 2) then
			state.commandStep = 1;
			state.commandRounds = 0;
			state.nextCommandAt = 0;
		end
		return;
	elseif (event == "PLAYER_REGEN_ENABLED") then
		if (state.phase == 1 and UnitIsDeadOrGhost("player")) then
			state.trackedMobs = {};
			state.deadMobs = {};
			state.mobSeen = false;
			state.emptySince = nil;
		end
		state.combatStartedAt = nil;
		return;
	end

	local eventType = select(2, ...);
	local sourceGuid = select(3, ...);
	local sourceName = select(4, ...);
	local sourceFlags = select(5, ...);
	local destinationGuid = select(6, ...);
	local destinationName = select(7, ...);
	local destinationFlags = select(8, ...);
	if (
		(eventType == "UNIT_DIED"
			or eventType == "UNIT_DESTROYED"
			or eventType == "PARTY_KILL")
		and UnBotSvalnaNameMatches(destinationName, destinationGuid)
	) then
		UnBotSpecSummonMessage("Свална: босс погиб, двухфазный контроль завершён.");
		UnBotSvalnaDisarm(true);
		return;
	end
	if (
		eventType == "UNIT_DIED"
		or eventType == "UNIT_DESTROYED"
		or eventType == "PARTY_KILL"
	) then
		if (destinationGuid) then
			state.deadMobs[destinationGuid] = true;
			if (state.trackedMobs[destinationGuid]) then
				state.trackedMobs[destinationGuid] = nil;
				if (state.mobSeen and not next(state.trackedMobs)) then
					state.emptySince = GetTime();
				end
			end
		end
		return;
	end
	if (
		state.phase == 1
		and (
			eventType == "SWING_DAMAGE"
			or eventType == "SWING_MISSED"
			or eventType == "RANGE_DAMAGE"
			or eventType == "RANGE_MISSED"
			or eventType == "SPELL_DAMAGE"
			or eventType == "SPELL_MISSED"
			or eventType == "SPELL_PERIODIC_DAMAGE"
		)
		and (
			UnBotSvalnaNameMatches(sourceName, sourceGuid)
			or UnBotSvalnaNameMatches(destinationName, destinationGuid)
		)
	) then
		UnBotSvalnaBeginPhaseTwo("сама Свална вступила в бой");
		return;
	end
	UnBotSvalnaTrackHostile(sourceGuid, sourceName, sourceFlags);
	UnBotSvalnaTrackHostile(
		destinationGuid,
		destinationName,
		destinationFlags
	);
end);
UnBotSvalnaFrame:SetScript("OnUpdate", function()
	local state = UnBotSvalnaControl;
	if (not state.armed) then
		return;
	end
	local now = GetTime();
	if (now >= (state.expiresAt or 0)) then
		UnBotSpecSummonMessage(
			"Свална: 20-минутный лимит двухфазного контроля истёк; цикл остановлен без повторов."
		);
		UnBotSvalnaDisarm(true);
		return;
	end
	if (now >= (state.nextScanAt or 0)) then
		state.nextScanAt = now + 0.25;
		UnBotSvalnaEnsureMark();
		if (state.phase == 1 and state.bossGuid) then
			UnBotSvalnaTrackVisibleAdds();
		end
	end
	if (
		state.phase == 1
		and state.mobSeen
		and not next(state.trackedMobs)
		and state.emptySince
		and now - state.emptySince >= 1.5
		and not UnitIsDeadOrGhost("player")
	) then
		UnBotSvalnaBeginPhaseTwo("подтверждена смерть последней враждебной цели");
	elseif (
		state.phase == 1
		and not state.mobSeen
		and state.combatStartedAt
		and now - state.combatStartedAt >= 2
	) then
		local bossUnit = UnBotSvalnaFindBossUnit();
		if (bossUnit and UnitAffectingCombat(bossUnit)) then
			UnBotSvalnaBeginPhaseTwo("бой начат уже без окружающих мобов");
		end
	end
	UnBotSvalnaRunFocusCommands();
end);

