function UnBotValithriaUnitIsBoss(unit)
	if (not unit or not UnitExists(unit)) then
		return false;
	end
	local name = UnBotSpecSummonNormalize(UnitName(unit));
	return name == UnBotSpecSummonNormalize("Валитрия Сноходица")
		or name == UnBotSpecSummonNormalize("Valithria Dreamwalker");
end

function UnBotValithriaInIcecrownRaid()
	local instanceName, instanceType = GetInstanceInfo();
	local originalName = tostring(instanceName or "");
	local normalized = UnBotSpecSummonNormalize(originalName);
	return instanceType == "raid" and (
		string.find(normalized, "icecrown citadel", 1, true)
		or string.find(originalName, "Цитадель Ледяной Короны", 1, true)
	) and true or false;
end

function UnBotValithriaCurrentModeKey()
	if (not GetInstanceInfo or not UnBotValithriaInIcecrownRaid()) then
		return "manual";
	end
	local instanceName, instanceType, difficultyIndex, difficultyName, maxPlayers =
		GetInstanceInfo();
	difficultyIndex = tonumber(difficultyIndex) or 0;
	maxPlayers = tonumber(maxPlayers) or 0;
	if (instanceType == "raid") then
		if (difficultyIndex == 4) then
			return "25h";
		elseif (difficultyIndex == 3) then
			return "10h";
		elseif (difficultyIndex == 2 or maxPlayers == 25) then
			return "25n";
		elseif (difficultyIndex == 1 or maxPlayers == 10) then
			return "10n";
		end
	end
	return "manual";
end

function UnBotValithriaNameIsAbomination(name)
	local originalName = tostring(name or "");
	local normalized = UnBotSpecSummonNormalize(originalName);
	return string.find(normalized, "gluttonous abomination", 1, true)
		or string.find(originalName, "Прожорливое поганище", 1, true);
end

function UnBotValithriaNameIsWorm(name)
	local originalName = tostring(name or "");
	local normalized = UnBotSpecSummonNormalize(originalName);
	return string.find(normalized, "rot worm", 1, true)
		or string.find(originalName, "Гнилостный червь", 1, true);
end

function UnBotValithriaAddKind(name)
	local originalName = tostring(name or "");
	local normalized = UnBotSpecSummonNormalize(originalName);
	if (
		string.find(normalized, "blazing skeleton", 1, true)
		or string.find(originalName, "Исторгающий пламя скелет", 1, true)
	) then
		return "skeleton", "Исторгающий пламя скелет";
	elseif (
		string.find(normalized, "blistering zombie", 1, true)
		or string.find(originalName, "Волдырный зомби", 1, true)
	) then
		return "zombie", "Волдырный зомби";
	elseif (
		string.find(normalized, "suppressor", 1, true)
		or string.find(originalName, "Подавитель", 1, true)
	) then
		return "suppressor", "Подавитель";
	elseif (
		string.find(normalized, "risen archmage", 1, true)
		or string.find(originalName, "Воскрешенный верховный маг", 1, true)
	) then
		return "archmage", "Воскрешенный верховный маг";
	elseif (UnBotValithriaNameIsAbomination(originalName)) then
		return "abomination", "Прожорливое поганище";
	end
	return nil, nil;
end

function UnBotValithriaAddPriority(kind)
	if (kind == "skeleton") then
		return 50;
	elseif (kind == "zombie") then
		return 40;
	elseif (kind == "suppressor") then
		return 35;
	elseif (kind == "archmage") then
		return 30;
	elseif (kind == "abomination") then
		return 20;
	end
	return 0;
end

function UnBotValithriaAddClaimDelay(kind)
	if (kind == "zombie" or kind == "abomination") then
		return 2.4;
	end
	return 0;
end

function UnBotValithriaAddNeedsTank(kind)
	return kind == "skeleton"
		or kind == "zombie"
		or kind == "abomination";
end

function UnBotValithriaAddNeedsHardTankClaim(kind)
	return kind == "zombie" or kind == "abomination";
end

function UnBotValithriaTankName(name)
	for _, tankName in ipairs(UnBotValithriaHeal.tanks or {}) do
		if (
			UnBotSpecSummonNormalize(tankName)
			== UnBotSpecSummonNormalize(name)
		) then
			return tankName;
		end
	end
	return nil;
end

function UnBotValithriaTankClaimConfirmed(sideName, guid, now)
	local state = UnBotValithriaHeal;
	local wantedTank = sideName == "left" and state.leftTank or state.rightTank;
	local claims = guid and state.tankClaims and state.tankClaims[guid];
	local claim = wantedTank and claims
		and claims[UnBotSpecSummonNormalize(wantedTank)];
	return claim
		and (now or GetTime()) - (claim.at or 0) <= 12;
end

function UnBotValithriaResetAddControl()
	local state = UnBotValithriaHeal;
	state.addSides = {
		left = {
			markerIndex = 8,
			markerName = "skull",
			markerLabel = "череп",
			label = "левый",
		},
		right = {
			markerIndex = 7,
			markerName = "cross",
			markerLabel = "крест",
			label = "правый",
		},
	};
	state.addNextScanAt = 0;
	state.addClaims = 0;
	state.addReports = 0;
	state.addMarkerFailures = 0;
	state.addMarkerAttempts = {};
	state.addFallbackSide = "left";
	state.tankClaims = {};
	state.tankClaimEvents = 0;
	state.dpsGateReleases = 0;
end

function UnBotValithriaSideState(sideName)
	local state = UnBotValithriaHeal;
	state.addSides = state.addSides or {};
	if (not state.addSides[sideName]) then
		state.addSides[sideName] = {
			markerIndex = sideName == "left" and 8 or 7,
			markerName = sideName == "left" and "skull" or "cross",
			markerLabel = sideName == "left" and "череп" or "крест",
			label = sideName == "left" and "левый" or "правый",
		};
	end
	return state.addSides[sideName];
end

function UnBotValithriaNameInList(name, list)
	local normalized = UnBotSpecSummonNormalize(name);
	for _, listedName in ipairs(list or {}) do
		if (normalized == UnBotSpecSummonNormalize(listedName)) then
			return true;
		end
	end
	return false;
end

function UnBotValithriaMemberSide(name)
	local state = UnBotValithriaHeal;
	local normalized = UnBotSpecSummonNormalize(name);
	if (
		(state.leftTank and normalized == UnBotSpecSummonNormalize(state.leftTank))
		or UnBotValithriaNameInList(name, state.leftDps)
	) then
		return "left";
	elseif (
		(state.rightTank and normalized == UnBotSpecSummonNormalize(state.rightTank))
		or UnBotValithriaNameInList(name, state.rightDps)
	) then
		return "right";
	end
	return nil;
end

function UnBotValithriaPrepareDps(name)
	if (not name or not UnBotSpecSummonIsInGroup(name)) then
		return;
	end
	SendChatMessage("co -dps assist", "WHISPER", nil, name);
	SendChatMessage("co -aoe", "WHISPER", nil, name);
	SendChatMessage("co +avoid aoe", "WHISPER", nil, name);
	SendChatMessage("co -formation", "WHISPER", nil, name);
	SendChatMessage("co -attack force", "WHISPER", nil, name);
	SendChatMessage("co -dps", "WHISPER", nil, name);
	SendChatMessage("co +threat", "WHISPER", nil, name);
	SendChatMessage("co -icc", "WHISPER", nil, name);
	SendChatMessage("nc +icc", "WHISPER", nil, name);
end

function UnBotValithriaSideDpsCommand(sideName, command)
	local state = UnBotValithriaHeal;
	local list = sideName == "left" and state.leftDps or state.rightDps;
	for _, name in ipairs(list or {}) do
		if (UnBotSpecSummonIsInGroup(name)) then
			SendChatMessage(command, "WHISPER", nil, name);
		end
	end
end

function UnBotValithriaSetSideDpsGate(sideName, open)
	local state = UnBotValithriaHeal;
	local side = UnBotValithriaSideState(sideName);
	open = open and true or false;
	if (side.dpsGateOpen == open) then
		return;
	end
	side.dpsGateOpen = open;
	if (open) then
		UnBotValithriaSideDpsCommand(sideName, "co -icc");
		UnBotValithriaSideDpsCommand(sideName, "co +dps");
		UnBotValithriaSideDpsCommand(sideName, "co +attack force");
		UnBotValithriaSideDpsCommand(sideName, "co +threat");
		state.dpsGateReleases = (state.dpsGateReleases or 0) + 1;
	else
		UnBotValithriaSideDpsCommand(sideName, "co -attack force");
		UnBotValithriaSideDpsCommand(sideName, "co -dps");
		UnBotValithriaSideDpsCommand(sideName, "co -dps assist");
		UnBotValithriaSideDpsCommand(sideName, "co -aoe");
		UnBotValithriaSideDpsCommand(sideName, "co -icc");
	end
end

function UnBotValithriaSideTankCommand(sideName, command)
	local state = UnBotValithriaHeal;
	local name = sideName == "left" and state.leftTank or state.rightTank;
	if (name and UnBotSpecSummonIsInGroup(name)) then
		SendChatMessage(command, "WHISPER", nil, name);
	end
end

function UnBotValithriaSideTankHasTarget(sideName, guid)
	local state = UnBotValithriaHeal;
	local name = sideName == "left" and state.leftTank or state.rightTank;
	local unit = name and UnBotSquadRosterFindUnit(name) or nil;
	local target = unit and (unit.."target") or nil;
	return target and UnitExists(target) and UnitGUID(target) == guid;
end

function UnBotValithriaAddUnitValid(unit)
	return unit
		and UnitExists(unit)
		and not UnitIsDeadOrGhost(unit)
		and (not UnitCanAttack or UnitCanAttack("player", unit))
		and UnBotValithriaAddKind(UnitName(unit)) ~= nil;
end

function UnBotValithriaAppendAddTarget(tokens, seen, unit)
	local token = unit and (unit.."target") or nil;
	if (token and not seen[token] and UnBotValithriaAddUnitValid(token)) then
		seen[token] = true;
		table.insert(tokens, token);
	end
end

function UnBotValithriaSideTargetTokens(sideName)
	local state = UnBotValithriaHeal;
	local tokens = {};
	local seen = {};
	local tankName = sideName == "left" and state.leftTank or state.rightTank;
	local dps = sideName == "left" and state.leftDps or state.rightDps;
	if (tankName) then
		UnBotValithriaAppendAddTarget(
			tokens,
			seen,
			UnBotSquadRosterFindUnit(tankName)
		);
	end
	for _, name in ipairs(dps or {}) do
		UnBotValithriaAppendAddTarget(
			tokens,
			seen,
			UnBotSquadRosterFindUnit(name)
		);
	end
	for index = 1, math.min(40, GetNumRaidMembers() or 0), 1 do
		local owner = "raid"..index;
		if (UnBotValithriaMemberSide(UnitName(owner)) == sideName) then
			UnBotValithriaAppendAddTarget(tokens, seen, owner);
		end
	end
	return tokens;
end

function UnBotValithriaGeneralTargetTokens()
	local tokens = {};
	local seen = {};
	for _, unit in ipairs({"target", "focus", "mouseover", "targettarget"}) do
		if (not seen[unit] and UnBotValithriaAddUnitValid(unit)) then
			seen[unit] = true;
			table.insert(tokens, unit);
		end
	end
	for index = 1, math.min(40, GetNumRaidMembers() or 0), 1 do
		local owner = "raid"..index;
		if (not UnBotValithriaMemberSide(UnitName(owner))) then
			UnBotValithriaAppendAddTarget(tokens, seen, owner);
		end
	end
	return tokens;
end

function UnBotValithriaBestAdd(tokens, currentGuid, excludedGuid)
	local bestUnit, bestKind, bestName, bestGuid, bestPriority = nil, nil, nil, nil, -1;
	for _, unit in ipairs(tokens or {}) do
		local guid = UnitGUID(unit);
		local kind, displayName = UnBotValithriaAddKind(UnitName(unit));
		if (guid and guid ~= excludedGuid and kind) then
			local priority = UnBotValithriaAddPriority(kind);
			if (guid == currentGuid) then
				priority = priority + 0.1;
			end
			if (priority > bestPriority) then
				bestUnit = unit;
				bestKind = kind;
				bestName = displayName;
				bestGuid = guid;
				bestPriority = priority;
			end
		end
	end
	return bestUnit, bestKind, bestName, bestGuid, bestPriority;
end

function UnBotValithriaFindVisibleAddGuid(guid)
	if (not guid) then
		return nil;
	end
	for _, unit in ipairs({"target", "focus", "mouseover", "targettarget"}) do
		if (UnBotValithriaAddUnitValid(unit) and UnitGUID(unit) == guid) then
			return unit;
		end
	end
	for index = 1, math.min(40, GetNumRaidMembers() or 0), 1 do
		local unit = "raid"..index.."target";
		if (UnBotValithriaAddUnitValid(unit) and UnitGUID(unit) == guid) then
			return unit;
		end
	end
	return nil;
end

function UnBotValithriaSetAddMarker(sideName, unit)
	local state = UnBotValithriaHeal;
	local side = UnBotValithriaSideState(sideName);
	local guid = UnitGUID(unit);
	state.addMarkerAttempts = state.addMarkerAttempts or {};
	if (
		GetRaidTargetIndex
		and GetRaidTargetIndex(unit) == side.markerIndex
	) then
		return true;
	end
	if (guid and (state.addMarkerAttempts[guid] or 0) >= 3) then
		if (not side.passiveReleased) then
			side.passiveReleased = true;
			UnBotValithriaSetSideDpsGate(sideName, false);
			UnBotSpecSummonMessage(
				"|cffffcc33Валитрия, "..tostring(side.label)
				.." фланг: метка этой цели недоступна; ДД удерживаются, нужен ручной фокус.|r"
			);
		end
		return false;
	end
	local ok = SetRaidTarget and pcall(SetRaidTarget, unit, side.markerIndex);
	if (
		ok
		and (
			not GetRaidTargetIndex
			or GetRaidTargetIndex(unit) == side.markerIndex
		)
	) then
		return true;
	end
	if (guid) then
		state.addMarkerAttempts[guid] = (state.addMarkerAttempts[guid] or 0) + 1;
	end
	state.addMarkerFailures = (state.addMarkerFailures or 0) + 1;
	if (state.addMarkerFailures <= 2) then
		UnBotSpecSummonMessage(
			"|cffff6060Валитрия: не удалось поставить метку "
			..tostring(side.markerLabel).." на адда; автоматический фокус этого адда пропущен.|r"
		);
	end
	if (
		guid
		and state.addMarkerAttempts[guid] >= 3
		and not side.passiveReleased
	) then
		side.passiveReleased = true;
		UnBotValithriaSetSideDpsGate(sideName, false);
		UnBotSpecSummonMessage(
			"|cffffcc33Валитрия, "..tostring(side.label)
			.." фланг: после трёх ошибок метки ДД удерживаются; нужен ручной фокус.|r"
		);
	end
	return false;
end

function UnBotValithriaClearSideAdd(sideName)
	UnBotValithriaSetSideDpsGate(sideName, false);
	local side = UnBotValithriaSideState(sideName);
	local oldGuid = side.guid;
	side.guid = nil;
	side.kind = nil;
	side.displayName = nil;
	side.lastSeenAt = 0;
	side.claimUntil = 0;
	side.claimMaxUntil = 0;
	side.tankClaimAttempts = 0;
	side.claimFallbackReported = false;
	side.commandPhase = nil;
	side.nextCommandAt = 0;
	side.commandAttempts = 0;
	side.tankConfirmedAt = nil;
	if (oldGuid and UnBotValithriaHeal.tankClaims) then
		UnBotValithriaHeal.tankClaims[oldGuid] = nil;
	end
end

function UnBotValithriaClearAddGuid(guid)
	if (not guid) then
		return;
	end
	for _, sideName in ipairs({"left", "right"}) do
		local side = UnBotValithriaSideState(sideName);
		if (side.guid == guid) then
			UnBotValithriaClearSideAdd(sideName);
		end
	end
end

function UnBotValithriaAddSideForGuid(guid)
	if (not guid) then
		return nil;
	end
	for _, sideName in ipairs({"left", "right"}) do
		if (UnBotValithriaSideState(sideName).guid == guid) then
			return sideName;
		end
	end
	return nil;
end

function UnBotValithriaAssignSideAdd(sideName, unit, kind, displayName)
	local state = UnBotValithriaHeal;
	local side = UnBotValithriaSideState(sideName);
	local guid = UnitGUID(unit);
	if (guid and side.guid ~= guid) then
		UnBotValithriaSetSideDpsGate(sideName, false);
	end
	if (not guid or not UnBotValithriaSetAddMarker(sideName, unit)) then
		return false;
	end
	if (side.passiveReleased) then
		side.passiveReleased = false;
		local dps = sideName == "left" and state.leftDps or state.rightDps;
		for _, name in ipairs(dps or {}) do
			UnBotValithriaPrepareDps(name);
		end
	end
	if (side.guid == guid) then
		side.lastSeenAt = GetTime();
		return true;
	end
	UnBotValithriaSetSideDpsGate(sideName, false);
	side.guid = guid;
	side.kind = kind;
	side.displayName = displayName;
	side.lastSeenAt = GetTime();
	side.claimUntil = side.lastSeenAt + UnBotValithriaAddClaimDelay(kind);
	side.claimMaxUntil = side.lastSeenAt + 5.5;
	side.tankClaimAttempts = 0;
	side.claimFallbackReported = false;
	side.commandAttempts = 0;
	side.nextCommandAt = 0;
	side.commandPhase = UnBotValithriaAddNeedsTank(kind)
		and "tank_target" or "dps_target";
	state.addClaims = (state.addClaims or 0) + 1;
	if ((state.addReports or 0) < 14) then
		state.addReports = (state.addReports or 0) + 1;
		local delay = UnBotValithriaAddClaimDelay(kind);
		UnBotSpecSummonMessage(
			"Валитрия, "..tostring(side.label).." фланг: "
			..tostring(displayName).." отмечен меткой "..tostring(side.markerLabel)
			..(delay > 0
				and ("; сначала танк, ДД не раньше "..tostring(delay)
					.." сек. и только после урона/таунта.")
				or "; немедленный фокус ДД.")
		);
	end
	return true;
end

function UnBotValithriaCombatEventConfirmsTank(eventType, spellId)
	if (
		eventType == "SWING_DAMAGE"
		or eventType == "RANGE_DAMAGE"
		or eventType == "SPELL_DAMAGE"
		or eventType == "SPELL_PERIODIC_DAMAGE"
		or eventType == "DAMAGE_SHIELD"
	) then
		return true;
	end
	return eventType == "SPELL_CAST_SUCCESS" and (
		spellId == 355
		or spellId == 6795
		or spellId == 31789
		or spellId == 49576
		or spellId == 56222
		or spellId == 62124
	);
end

function UnBotValithriaRecordTankClaim(
	eventType,
	sourceName,
	destinationGuid,
	destinationName,
	spellId
)
	local state = UnBotValithriaHeal;
	local tankName = UnBotValithriaTankName(sourceName);
	if (
		not tankName
		or not destinationGuid
		or (
			not UnBotValithriaAddKind(destinationName)
			and not UnBotValithriaNameIsWorm(destinationName)
		)
		or not UnBotValithriaCombatEventConfirmsTank(eventType, spellId)
	) then
		return false;
	end
	state.tankClaims = state.tankClaims or {};
	state.tankClaims[destinationGuid] = state.tankClaims[destinationGuid] or {};
	state.tankClaims[destinationGuid][UnBotSpecSummonNormalize(tankName)] = {
		name = tankName,
		at = GetTime(),
		eventType = eventType,
		spellId = spellId,
	};
	state.tankClaimEvents = (state.tankClaimEvents or 0) + 1;
	local sideName = UnBotValithriaAddSideForGuid(destinationGuid);
	if (sideName) then
		local side = UnBotValithriaSideState(sideName);
		local assignedTank = sideName == "left" and state.leftTank or state.rightTank;
		if (
			assignedTank
			and UnBotSpecSummonNormalize(assignedTank)
				== UnBotSpecSummonNormalize(tankName)
		) then
			side.tankConfirmedAt = GetTime();
			side.tankConfirmEvent = eventType;
			side.tankConfirmSpellId = spellId;
		end
	end
	return true;
end

function UnBotValithriaWormTankClaimConfirmed(now)
	local state = UnBotValithriaHeal;
	local claims = state.wormCurrentGuid
		and state.tankClaims
		and state.tankClaims[state.wormCurrentGuid];
	if (not claims) then
		return false;
	end
	if (state.wormSide == "left" or state.wormSide == "right") then
		local assignedTank = state.wormSide == "left"
			and state.leftTank or state.rightTank;
		local claim = assignedTank
			and claims[UnBotSpecSummonNormalize(assignedTank)];
		return claim and (now or GetTime()) - (claim.at or 0) <= 12;
	end
	for _, tankName in ipairs(state.tanks or {}) do
		local claim = claims[UnBotSpecSummonNormalize(tankName)];
		if (claim and (now or GetTime()) - (claim.at or 0) <= 12) then
			return true;
		end
	end
	return false;
end

function UnBotValithriaSideCurrentPriority(sideName)
	local side = UnBotValithriaSideState(sideName);
	return side.guid and UnBotValithriaAddPriority(side.kind) or 0;
end

function UnBotValithriaTryAssignSide(sideName, unit, kind, displayName, guid)
	if (not unit or not guid) then
		return false;
	end
	local otherSide = UnBotValithriaSideState(
		sideName == "left" and "right" or "left"
	);
	if (otherSide.guid == guid) then
		return false;
	end
	local side = UnBotValithriaSideState(sideName);
	if (
		side.guid == guid
		or not side.guid
		or UnBotValithriaAddPriority(kind) > UnBotValithriaAddPriority(side.kind)
	) then
		return UnBotValithriaAssignSideAdd(sideName, unit, kind, displayName);
	end
	return false;
end

function UnBotValithriaProcessSideAdd(now, sideName)
	local side = UnBotValithriaSideState(sideName);
	if (not side.guid) then
		return;
	end
	local unit = UnBotValithriaFindVisibleAddGuid(side.guid);
	if (unit) then
		side.lastSeenAt = now;
		UnBotValithriaSetAddMarker(sideName, unit);
	elseif (now - (side.lastSeenAt or 0) > 2.2) then
		UnBotValithriaClearSideAdd(sideName);
		return;
	end
	if (
		now < (side.nextCommandAt or 0)
		or (side.commandAttempts or 0) >= 3
	) then
		return;
	end
	if (side.commandPhase == "tank_target") then
		UnBotValithriaSideTankCommand(sideName, "rti "..side.markerName);
		side.commandPhase = "tank_attack";
		side.nextCommandAt = now + 0.25;
	elseif (side.commandPhase == "tank_attack") then
		UnBotValithriaSideTankCommand(sideName, "attack rti target");
		side.tankClaimAttempts = (side.tankClaimAttempts or 0) + 1;
		side.commandPhase = "dps_target";
		side.nextCommandAt = math.max(now + 0.25, side.claimUntil or 0);
	elseif (side.commandPhase == "dps_target") then
		if (
			UnBotValithriaAddNeedsHardTankClaim(side.kind)
				and not UnBotValithriaTankClaimConfirmed(sideName, side.guid, now)
		) then
			if (
				now < (side.claimMaxUntil or 0)
				and (side.tankClaimAttempts or 0) < 4
			) then
				UnBotValithriaSideTankCommand(sideName, "rti "..side.markerName);
				UnBotValithriaSideTankCommand(sideName, "attack rti target");
				side.tankClaimAttempts = (side.tankClaimAttempts or 0) + 1;
				side.nextCommandAt = now + 0.7;
				return;
			elseif (now < (side.claimMaxUntil or 0)) then
				side.nextCommandAt = side.claimMaxUntil;
				return;
			elseif (not side.claimFallbackReported) then
				side.claimFallbackReported = true;
				UnBotSpecSummonMessage(
					"|cffffcc33Валитрия, "..tostring(side.label)
					.." фланг: за 5,5 сек нет урона/таунта назначенного танка; "
					.."ДД остаются удержанными.|r"
				);
			end
			side.nextCommandAt = now + 1;
			return;
		end
		UnBotValithriaSetSideDpsGate(sideName, true);
		UnBotValithriaSideDpsCommand(sideName, "rti "..side.markerName);
		side.commandPhase = "dps_attack";
		side.nextCommandAt = now + 0.25;
	elseif (side.commandPhase == "dps_attack") then
		UnBotValithriaSideDpsCommand(sideName, "attack rti target");
		side.commandAttempts = (side.commandAttempts or 0) + 1;
		side.commandPhase = "dps_target";
		side.nextCommandAt = now + 0.9;
	end
end

function UnBotValithriaProcessAddControl(now)
	local state = UnBotValithriaHeal;
	if (not state.active or not state.addControl) then
		return;
	end
	UnBotValithriaProcessSideAdd(now, "left");
	UnBotValithriaProcessSideAdd(now, "right");
	if (now < (state.addNextScanAt or 0)) then
		return;
	end
	state.addNextScanAt = now + 0.15;
	local left = UnBotValithriaSideState("left");
	local right = UnBotValithriaSideState("right");
	local leftUnit, leftKind, leftName, leftGuid = UnBotValithriaBestAdd(
		UnBotValithriaSideTargetTokens("left"),
		left.guid,
		right.guid
	);
	local rightUnit, rightKind, rightName, rightGuid = UnBotValithriaBestAdd(
		UnBotValithriaSideTargetTokens("right"),
		right.guid,
		left.guid
	);
	UnBotValithriaTryAssignSide("left", leftUnit, leftKind, leftName, leftGuid);
	UnBotValithriaTryAssignSide("right", rightUnit, rightKind, rightName, rightGuid);
	local generalUnit, generalKind, generalName, generalGuid = UnBotValithriaBestAdd(
		UnBotValithriaGeneralTargetTokens(),
		nil,
		nil
	);
	if (
		generalGuid
		and generalGuid ~= left.guid
		and generalGuid ~= right.guid
	) then
		local generalPriority = UnBotValithriaAddPriority(generalKind);
		local leftPriority = UnBotValithriaSideCurrentPriority("left");
		local rightPriority = UnBotValithriaSideCurrentPriority("right");
		local sideName;
		if (leftPriority < rightPriority) then
			sideName = "left";
		elseif (rightPriority < leftPriority) then
			sideName = "right";
		else
			sideName = state.addFallbackSide or "left";
			state.addFallbackSide = sideName == "left" and "right" or "left";
		end
		if (generalPriority > UnBotValithriaSideCurrentPriority(sideName)) then
			UnBotValithriaAssignSideAdd(
				sideName,
				generalUnit,
				generalKind,
				generalName
			);
		end
	end
	UnBotValithriaProcessSideAdd(now, "left");
	UnBotValithriaProcessSideAdd(now, "right");
end

function UnBotValithriaPrepareTank(name)
	if (not name or not UnBotSpecSummonIsInGroup(name)) then
		return;
	end
	SendChatMessage("co -tank", "WHISPER", nil, name);
	SendChatMessage("co +tank aoe", "WHISPER", nil, name);
	SendChatMessage("co +pull", "WHISPER", nil, name);
	SendChatMessage("co +pull back", "WHISPER", nil, name);
	SendChatMessage("co +avoid aoe", "WHISPER", nil, name);
	SendChatMessage("co -dps assist", "WHISPER", nil, name);
	SendChatMessage("co -formation", "WHISPER", nil, name);
	SendChatMessage("co +icc", "WHISPER", nil, name);
	SendChatMessage("nc +icc", "WHISPER", nil, name);
end

function UnBotValithriaRestoreTank(name)
	if (not name or not UnBotSpecSummonIsInGroup(name)) then
		return;
	end
	SendChatMessage("co -tank aoe", "WHISPER", nil, name);
	SendChatMessage("co +tank", "WHISPER", nil, name);
	SendChatMessage("co -pull", "WHISPER", nil, name);
	SendChatMessage("co -pull back", "WHISPER", nil, name);
	SendChatMessage("co +dps assist", "WHISPER", nil, name);
	SendChatMessage("co +formation", "WHISPER", nil, name);
	SendChatMessage("nc +follow", "WHISPER", nil, name);
end

function UnBotValithriaFindVisibleWorm()
	local state = UnBotValithriaHeal;
	local units = {"target", "focus", "mouseover", "targettarget"};
	local raidCount = GetNumRaidMembers() or 0;
	if (raidCount > 0) then
		for index = 1, math.min(40, raidCount), 1 do
			table.insert(units, "raid"..index.."target");
		end
	else
		for index = 1, math.min(4, GetNumPartyMembers() or 0), 1 do
			table.insert(units, "party"..index.."target");
		end
	end
	local fallback = nil;
	for _, unit in ipairs(units) do
		if (
			UnitExists(unit)
			and not UnitIsDeadOrGhost(unit)
			and UnBotValithriaNameIsWorm(UnitName(unit))
		) then
			local guid = UnitGUID(unit);
			if (guid and guid == state.wormCurrentGuid) then
				return unit;
			end
			fallback = fallback or unit;
		end
	end
	return fallback;
end

function UnBotValithriaAcquireWorm()
	local state = UnBotValithriaHeal;
	local unit = UnBotValithriaFindVisibleWorm();
	if (not unit) then
		return false;
	end
	local guid = UnitGUID(unit);
	if (not guid) then
		return false;
	end
	if (
		SetRaidTarget
		and (not GetRaidTargetIndex or GetRaidTargetIndex(unit) ~= 4)
	) then
		SetRaidTarget(unit, 4);
	end
	if (GetRaidTargetIndex and GetRaidTargetIndex(unit) ~= 4) then
		return false;
	end
	if (guid ~= state.wormCurrentGuid) then
		UnBotValithriaSetWormDpsAoe(false);
		if (state.wormSide == "left" or state.wormSide == "right") then
			UnBotValithriaSetSideDpsGate(state.wormSide, false);
		else
			UnBotValithriaSetSideDpsGate("left", false);
			UnBotValithriaSetSideDpsGate("right", false);
		end
		state.wormTargets = (tonumber(state.wormTargets) or 0) + 1;
		state.wormDpsAt = GetTime() + 2.4;
		state.wormCommandPhase = "target";
		state.wormNextCommandAt = 0;
		state.wormDpsCommandPhase = "target";
		state.wormDpsNextCommandAt = 0;
	end
	state.wormCurrentGuid = guid;
	state.wormCurrentSeenAt = GetTime();
	return true;
end

function UnBotValithriaWormTankCommand(command)
	local state = UnBotValithriaHeal;
	if (state.wormSide == "left" or state.wormSide == "right") then
		UnBotValithriaSideTankCommand(state.wormSide, command);
		return;
	end
	for _, name in ipairs(state.tanks or {}) do
		if (UnBotSpecSummonIsInGroup(name)) then
			SendChatMessage(command, "WHISPER", nil, name);
		end
	end
end

function UnBotValithriaWormDpsCommand(command)
	local state = UnBotValithriaHeal;
	if (state.wormSide == "left" or state.wormSide == "right") then
		UnBotValithriaSideDpsCommand(state.wormSide, command);
		return;
	end
	UnBotValithriaSideDpsCommand("left", command);
	UnBotValithriaSideDpsCommand("right", command);
end

function UnBotValithriaSetWormDpsAoe(enabled)
	local state = UnBotValithriaHeal;
	if (enabled and state.wormDpsEnabled) then
		return;
	elseif (not enabled and not state.wormDpsEnabled) then
		return;
	end
	state.wormDpsEnabled = enabled and true or false;
	UnBotValithriaWormDpsCommand(enabled and "co +aoe" or "co -aoe");
end

function UnBotValithriaWormDpsBlocked()
	local state = UnBotValithriaHeal;
	if (state.wormSide == "left" or state.wormSide == "right") then
		return UnBotValithriaSideState(state.wormSide).guid ~= nil;
	end
	return UnBotValithriaSideState("left").guid ~= nil
		or UnBotValithriaSideState("right").guid ~= nil;
end

function UnBotValithriaStartWormCollection(sideName)
	local state = UnBotValithriaHeal;
	if (not state.active or not state.addControl) then
		return;
	end
	UnBotValithriaSetWormDpsAoe(false);
	local now = GetTime();
	state.abominationKills = (tonumber(state.abominationKills) or 0) + 1;
	state.wormWindowUntil = now + 10;
	state.wormNextScanAt = 0;
	state.wormNextCommandAt = 0;
	state.wormCommandPhase = "target";
	state.wormCommandAttempts = 0;
	state.wormCurrentGuid = nil;
	state.wormCurrentSeenAt = 0;
	state.wormWindowReported = false;
	state.wormSide = sideName;
	state.wormDpsAt = 0;
	state.wormDpsEnabled = false;
	state.wormDpsCommandPhase = "target";
	state.wormDpsCommandAttempts = 0;
	state.wormDpsNextCommandAt = 0;
	if (
		not state.guideAbominationShown
		and UnBotBossPresetGuide.active
		and UnBotBossPresetGuide.active.bossKey == "valithria_dreamwalker"
	) then
		state.guideAbominationShown = true;
		UnBotBossPresetGuideShowPhase("поганище");
	end
	if (sideName == "left" or sideName == "right") then
		local tankName = sideName == "left" and state.leftTank or state.rightTank;
		UnBotValithriaPrepareTank(tankName);
	else
		for _, name in ipairs(state.tanks or {}) do
			UnBotValithriaPrepareTank(name);
		end
	end
	UnBotSpecSummonMessage(
		"Валитрия: поганище погибло ("..tostring(state.abominationKills)
		..") — "..tostring(sideName == "left" and "левый" or (
			sideName == "right" and "правый" or "оба"
		)).." фланг собирает личинок; ДД подключатся не раньше 2,4 сек. "
		.."и только после урона/таунта назначенного танка."
	);
end

function UnBotValithriaHandleCombatLog(...)
	local state = UnBotValithriaHeal;
	if (not state.active or not UnBotValithriaInIcecrownRaid()) then
		return;
	end
	local eventType = select(2, ...);
	local sourceName = select(4, ...);
	local destinationGuid = select(6, ...);
	local destinationName = select(7, ...);
	local spellId = select(9, ...);
	local killedAddSide = destinationGuid
		and UnBotValithriaAddSideForGuid(destinationGuid) or nil;
	UnBotValithriaRecordTankClaim(
		eventType,
		sourceName,
		destinationGuid,
		destinationName,
		spellId
	);
	if (
		(eventType == "UNIT_DIED"
			or eventType == "UNIT_DESTROYED"
			or eventType == "PARTY_KILL")
		and destinationGuid
	) then
		UnBotValithriaClearAddGuid(destinationGuid);
	end
	if (
		(eventType == "UNIT_DIED" or eventType == "PARTY_KILL")
		and UnBotValithriaNameIsAbomination(destinationName)
	) then
		local now = GetTime();
		if (
			(destinationGuid and state.killedAbominations[destinationGuid])
			or (not destinationGuid and now - (state.lastAbominationDeathAt or 0) < 1)
		) then
			return;
		end
		if (destinationGuid) then
			state.killedAbominations[destinationGuid] = true;
		end
		state.lastAbominationDeathAt = now;
		UnBotValithriaStartWormCollection(killedAddSide);
		return;
	end
	if (
		(eventType == "UNIT_DIED" or eventType == "UNIT_DESTROYED")
		and UnBotValithriaNameIsWorm(destinationName)
		and (
			not destinationGuid
			or destinationGuid == state.wormCurrentGuid
		)
	) then
		UnBotValithriaSetWormDpsAoe(false);
		if (state.wormSide == "left" or state.wormSide == "right") then
			UnBotValithriaSetSideDpsGate(state.wormSide, false);
		end
		if (destinationGuid and state.tankClaims) then
			state.tankClaims[destinationGuid] = nil;
		end
		state.wormCurrentGuid = nil;
		state.wormCurrentSeenAt = 0;
		state.wormNextScanAt = 0;
		state.wormCommandPhase = "target";
		state.wormNextCommandAt = 0;
		state.wormDpsCommandPhase = "target";
		state.wormDpsNextCommandAt = 0;
		return;
	end
	if (
		eventType == "SPELL_AURA_REMOVED"
		and (spellId == 70873 or spellId == 71941)
		and destinationName
	) then
		local shortName = string.match(destinationName, "^[^-]+") or destinationName;
		for _, name in ipairs(state.allHealers or {}) do
			if (
				UnBotSpecSummonNormalize(name) == UnBotSpecSummonNormalize(destinationName)
				or UnBotSpecSummonNormalize(name) == UnBotSpecSummonNormalize(shortName)
			) then
				local unit = UnBotSquadRosterFindUnit(name);
				if (
					unit
					and UnitIsConnected(unit)
					and not UnitIsDeadOrGhost(unit)
					and UnitAffectingCombat(unit)
				) then
					state.vigorDrops[name] = (tonumber(state.vigorDrops[name]) or 0) + 1;
					if (GetTime() >= (state.vigorRepairAt[name] or 0)) then
						state.vigorRepairAt[name] = GetTime() + 15;
						SendChatMessage("co +icc", "WHISPER", nil, name);
						SendChatMessage("nc +icc", "WHISPER", nil, name);
						UnBotSpecSummonMessage(
							"Валитрия: у "..name.." слетел Emerald Vigor; ICC-порталы повторно включены."
						);
					end
				end
				break
			end
		end
	end
end

function UnBotValithriaProcessWormCollection(now)
	local state = UnBotValithriaHeal;
	if (not state.addControl or (state.wormWindowUntil or 0) <= 0) then
		return;
	end
	if (now >= state.wormWindowUntil) then
		UnBotValithriaSetWormDpsAoe(false);
		if (state.wormSide == "left" or state.wormSide == "right") then
			UnBotValithriaSetSideDpsGate(state.wormSide, false);
		else
			UnBotValithriaSetSideDpsGate("left", false);
			UnBotValithriaSetSideDpsGate("right", false);
		end
		if (not state.wormWindowReported) then
			state.wormWindowReported = true;
			UnBotSpecSummonMessage(
				"Валитрия: сбор личинок завершён; команд танкам "
				..tostring(state.wormCommandAttempts or 0)
				..", команд ДД "..tostring(state.wormDpsCommandAttempts or 0)
				..", найдено целей "..tostring(state.wormTargets or 0).."."
			);
		end
		state.wormWindowUntil = 0;
		state.wormCurrentGuid = nil;
		state.wormSide = nil;
		return;
	end
	if (
		state.wormCurrentGuid
		and now - (state.wormCurrentSeenAt or 0) > 1.5
	) then
		UnBotValithriaSetWormDpsAoe(false);
		if (state.wormSide == "left" or state.wormSide == "right") then
			UnBotValithriaSetSideDpsGate(state.wormSide, false);
		end
		state.wormCurrentGuid = nil;
		state.wormCommandPhase = "target";
		state.wormNextCommandAt = 0;
		state.wormDpsCommandPhase = "target";
		state.wormDpsNextCommandAt = 0;
	end
	if (now >= (state.wormNextScanAt or 0)) then
		state.wormNextScanAt = now + 0.12;
		UnBotValithriaAcquireWorm();
	end
	if (UnBotValithriaWormDpsBlocked()) then
		UnBotValithriaSetWormDpsAoe(false);
		state.wormDpsCommandAttempts = 3;
	end
	if (
		state.wormCurrentGuid
		and (state.wormDpsAt or 0) > 0
		and now >= state.wormDpsAt
		and UnBotValithriaWormTankClaimConfirmed(now)
		and now >= (state.wormDpsNextCommandAt or 0)
		and (state.wormDpsCommandAttempts or 0) < 3
	) then
		if (state.wormSide == "left" or state.wormSide == "right") then
			UnBotValithriaSetSideDpsGate(state.wormSide, true);
		else
			UnBotValithriaSetSideDpsGate("left", true);
			UnBotValithriaSetSideDpsGate("right", true);
		end
		UnBotValithriaSetWormDpsAoe(true);
		if (state.wormDpsCommandPhase == "target") then
			UnBotValithriaWormDpsCommand("rti triangle");
			state.wormDpsCommandPhase = "attack";
			state.wormDpsNextCommandAt = now + 0.25;
		else
			UnBotValithriaWormDpsCommand("attack rti target");
			state.wormDpsCommandAttempts =
				(state.wormDpsCommandAttempts or 0) + 1;
			state.wormDpsCommandPhase = "target";
			state.wormDpsNextCommandAt = now + 0.75;
		end
	end
	if (
		not state.wormCurrentGuid
		or now < (state.wormNextCommandAt or 0)
		or (state.wormCommandAttempts or 0) >= (state.wormMaxCommandAttempts or 4)
	) then
		return;
	end
	if (state.wormCommandPhase == "target") then
		UnBotValithriaWormTankCommand("rti triangle");
		state.wormCommandPhase = "attack";
		state.wormNextCommandAt = now + 0.25;
	else
		UnBotValithriaWormTankCommand("co +tank aoe");
		UnBotValithriaWormTankCommand("attack rti target");
		state.wormCommandAttempts = (state.wormCommandAttempts or 0) + 1;
		state.wormCommandPhase = "target";
		state.wormNextCommandAt = now + 0.75;
	end
end

function UnBotValithriaGuidToDecimal(guid)
	local hex = string.match(tostring(guid or ""), "^0[xX](%x+)$");
	if (not hex or #hex ~= 16) then
		return nil, nil;
	end
	local decimal = "0";
	for i = 1, #hex do
		local carry = tonumber(string.sub(hex, i, i), 16) or 0;
		local digits = {};
		for j = #decimal, 1, -1 do
			local value = (tonumber(string.sub(decimal, j, j)) or 0) * 16 + carry;
			table.insert(digits, 1, tostring(value % 10));
			carry = math.floor(value / 10);
		end
		while (carry > 0) do
			table.insert(digits, 1, tostring(carry % 10));
			carry = math.floor(carry / 10);
		end
		decimal = table.concat(digits);
	end
	return decimal, hex;
end

function UnBotValithriaBuildBossLink(guid)
	local decimal, hex = UnBotValithriaGuidToDecimal(guid);
	if (not decimal or not hex) then
		return nil;
	end
	local entry = tonumber(string.sub(hex, 5, 10), 16);
	if (not entry) then
		return nil;
	end
	return "|cFFFFFF00|Hfound:"..decimal..":"..tostring(entry)
		..":|h[Valithria Dreamwalker]|h|r";
end

function UnBotValithriaFindVisibleUnit()
	for _, unit in ipairs({"target", "focus", "mouseover"}) do
		if (UnBotValithriaUnitIsBoss(unit)) then
			return unit;
		end
	end
	return nil;
end

function UnBotValithriaMarkVisibleBoss(silent)
	local state = UnBotValithriaHeal;
	local unit = UnBotValithriaFindVisibleUnit();
	if (not unit) then
		return false;
	end
	state.bossName = UnitName(unit);
	state.bossGuid = UnitGUID(unit);
	state.bossLink = UnBotValithriaBuildBossLink(state.bossGuid);
	if (GetRaidTargetIndex) then
		state.bossMarked = GetRaidTargetIndex(unit) == 1;
	end
	if (
		SetRaidTarget
		and not state.bossMarked
		and not UnitAffectingCombat("player")
		and (not InCombatLockdown or not InCombatLockdown())
	) then
		SetRaidTarget(unit, 1);
		if (GetRaidTargetIndex) then
			state.bossMarked = GetRaidTargetIndex(unit) == 1;
		else
			state.bossMarked = true;
		end
	end
	if (state.bossMarked and not silent) then
		UnBotSpecSummonMessage(
			"Валитрия: цель отмечена звездой. Холипал начнёт прямой хил после входа в бой."
		);
	end
	return state.bossMarked;
end

function UnBotValithriaPrepareHealer(name)
	for _, command in ipairs({
		"co -aoe",
		"co +avoid aoe",
		"co -dps",
		"co -dps assist",
		"co -formation",
		"co -attack force",
		"co -flee",
		"co +heal",
		"co +icc",
		"nc +icc",
		"follow",
	}) do
		SendChatMessage(command, "WHISPER", nil, name);
	end
end

function UnBotValithriaIsHealer(profile)
	local className = UnBotSpecSummonNormalize(profile and profile.className);
	local specName = UnBotSpecSummonNormalize(profile and profile.specName);
	if (className == "paladin") then
		return specName == "holy";
	elseif (className == "priest") then
		return specName == "holy" or specName == "discipline";
	elseif (className == "shaman" or className == "druid") then
		return specName == "restoration";
	end
	return false;
end

function UnBotValithriaPrepareSupportHealer(name)
	SendChatMessage("co +avoid aoe", "WHISPER", nil, name);
	SendChatMessage("co +heal", "WHISPER", nil, name);
	SendChatMessage("co +icc", "WHISPER", nil, name);
	SendChatMessage("nc +icc", "WHISPER", nil, name);
	SendChatMessage("follow", "WHISPER", nil, name);
end

function UnBotValithriaAvailableCount(list)
	local count = 0;
	for _, name in ipairs(list or {}) do
		local unit = UnBotSquadRosterFindUnit(name);
		if (unit and UnitIsConnected(unit) and not UnitIsDeadOrGhost(unit)) then
			count = count + 1;
		end
	end
	return count;
end

function UnBotValithriaUnitInDream(unit)
	if (not unit or not UnitExists(unit)) then
		return false;
	end
	for index = 1, 40, 1 do
		local auraName, rank, icon, count, debuffType, duration,
			expirationTime, unitCaster, isStealable, shouldConsolidate,
			spellId = UnitBuff(unit, index);
		if (not auraName) then
			break
		end
		if (
			spellId == 70766
			or UnBotSpecSummonNormalize(auraName) == "dream state"
			or UnBotSpecSummonNormalize(auraName) == "состояние сна"
		) then
			return true;
		end
	end
	return false;
end

function UnBotValithriaPortalRecoverySpell(name)
	local profile = UnBotBotRegistry
		and UnBotBotRegistry.bots
		and UnBotBotRegistry.bots[name];
	local className = UnBotSpecSummonNormalize(profile and profile.className);
	if (className == "paladin") then
		return "Flash of Light";
	elseif (className == "priest") then
		return "Flash Heal";
	elseif (className == "shaman") then
		return "Lesser Healing Wave";
	elseif (className == "druid") then
		return "Regrowth";
	end
	return nil;
end

function UnBotValithriaStartPortalRecovery(name, now, healthPercent)
	local state = UnBotValithriaHeal;
	local spellName = UnBotValithriaPortalRecoverySpell(name);
	if (not spellName) then
		return false;
	end
	state.portalRecovery = state.portalRecovery or {};
	state.portalRecovery[name] = {
		spellName = spellName,
		attempts = 0,
		nextAt = now,
		untilAt = now + 7,
	};
	state.portalRecoveryEvents = (state.portalRecoveryEvents or 0) + 1;
	if (state.portalRecoveryEvents <= 8) then
		UnBotSpecSummonMessage(
			"Валитрия: "..name.." вышел из портала с "
			..tostring(math.floor((healthPercent or 0) * 100 + 0.5))
			.."% HP — временно приоритетно лечит себя."
		);
	end
	return true;
end

function UnBotValithriaProcessPortalRecovery(now)
	local state = UnBotValithriaHeal;
	state.healerDreamState = state.healerDreamState or {};
	state.portalRecovery = state.portalRecovery or {};
	for _, name in ipairs(state.allHealers or {}) do
		local unit = UnBotSquadRosterFindUnit(name);
		if (unit and UnitIsConnected(unit) and not UnitIsDeadOrGhost(unit)) then
			local inDream = UnBotValithriaUnitInDream(unit);
			if (inDream) then
				state.healerDreamState[name] = true;
				state.portalRecovery[name] = nil;
			elseif (state.healerDreamState[name]) then
				state.healerDreamState[name] = false;
				local healthMax = UnitHealthMax(unit) or 0;
				local healthPercent = healthMax > 0
					and (UnitHealth(unit) or 0) / healthMax or 1;
				if (healthPercent < 0.85) then
					UnBotValithriaStartPortalRecovery(
						name,
						now,
						healthPercent
					);
				end
			end
		end
	end
	for name, recovery in pairs(state.portalRecovery) do
		local unit = UnBotSquadRosterFindUnit(name);
		if (
			not unit
			or not UnitIsConnected(unit)
			or UnitIsDeadOrGhost(unit)
			or UnBotValithriaUnitInDream(unit)
		) then
			state.portalRecovery[name] = nil;
		else
			local healthMax = UnitHealthMax(unit) or 0;
			local healthPercent = healthMax > 0
				and (UnitHealth(unit) or 0) / healthMax or 1;
			if (healthPercent >= 0.85) then
				state.portalRecovery[name] = nil;
			elseif (
				now >= (recovery.nextAt or 0)
				and (recovery.attempts or 0) < 3
				and now < (recovery.untilAt or 0)
			) then
				SendChatMessage("co +heal", "WHISPER", nil, name);
				SendChatMessage(
					"cast "..recovery.spellName.." on "..name,
					"WHISPER",
					nil,
					name
				);
				recovery.attempts = (recovery.attempts or 0) + 1;
				recovery.nextAt = now + 1.5;
				state.portalRecoveryCommands =
					(state.portalRecoveryCommands or 0) + 1;
			elseif (now >= (recovery.untilAt or 0)) then
				state.portalRecovery[name] = nil;
			end
		end
	end
end

function UnBotValithriaHealerName(sender)
	local shortSender = string.match(tostring(sender or ""), "^[^-]+") or sender;
	for _, name in ipairs(UnBotValithriaHeal.healers or {}) do
		if (
			UnBotSpecSummonNormalize(name) == UnBotSpecSummonNormalize(sender)
			or UnBotSpecSummonNormalize(name) == UnBotSpecSummonNormalize(shortSender)
		) then
			return name;
		end
	end
	return nil;
end

function UnBotValithriaRestoreHealer(name)
	if (not UnBotSpecSummonIsInGroup(name)) then
		return;
	end
	SendChatMessage("follow", "WHISPER", nil, name);
	SendChatMessage("co -attack force", "WHISPER", nil, name);
	SendChatMessage("co +flee", "WHISPER", nil, name);
	SendChatMessage("co +dps assist", "WHISPER", nil, name);
	SendChatMessage("co +formation", "WHISPER", nil, name);
	SendChatMessage("co +avoid aoe", "WHISPER", nil, name);
	SendChatMessage("co +icc", "WHISPER", nil, name);
	SendChatMessage("nc +icc", "WHISPER", nil, name);
	SendChatMessage("nc +follow", "WHISPER", nil, name);
end

function UnBotValithriaRestoreDps(name)
	if (not name or not UnBotSpecSummonIsInGroup(name)) then
		return;
	end
	SendChatMessage("reset botAI", "WHISPER", nil, name);
	SendChatMessage("co +icc", "WHISPER", nil, name);
	SendChatMessage("nc +icc", "WHISPER", nil, name);
	SendChatMessage("nc +follow", "WHISPER", nil, name);
	SendChatMessage("follow", "WHISPER", nil, name);
end

function UnBotValithriaLayoutNames(list)
	return #((list) or {}) > 0 and table.concat(list, ", ") or "нет";
end

function UnBotValithriaLayoutStatus()
	local state = UnBotValithriaHeal;
	UnBotSpecSummonMessage(
		"Валитрия, стороны: левый танк "..tostring(state.leftTank or "нет")
		.."; левый ДД: "..UnBotValithriaLayoutNames(state.leftDps)
		.."; правый танк "..tostring(state.rightTank or "нет")
		.."; правый ДД: "..UnBotValithriaLayoutNames(state.rightDps)
		.."; центр/хилы: "..UnBotValithriaLayoutNames(state.allHealers).."."
	);
end

function UnBotValithriaLayoutBegin()
	local state = UnBotValithriaHeal;
	if (not state.prepared or not state.addControl) then
		UnBotSpecSummonMessage("Сначала загрузите и соберите пресет Валитрии 25 гер.");
		return false;
	end
	if (UnitAffectingCombat("player")) then
		UnBotSpecSummonMessage("RTSC-точки Валитрии задаются только вне боя.");
		return false;
	end
	local channel = GetNumRaidMembers() > 0 and "RAID" or "PARTY";
	SendChatMessage("rtsc", channel);
	UnBotValithriaLayoutStatus();
	UnBotSpecSummonMessage(
		"RTSC включён. По очереди: /ubvalithria setleft и клик Aedm в левую точку у хвоста; "
		.."setright — справа у хвоста; setcenter — центр за хвостом; затем /ubvalithria deploy."
	);
	state.layoutGuideShown = true;
	return true;
end

function UnBotValithriaLayoutSaveSpot(command)
	local state = UnBotValithriaHeal;
	if (not state.prepared or UnitAffectingCombat("player")) then
		UnBotSpecSummonMessage("Точка не выбрана: нужна подготовленная Валитрия и состояние вне боя.");
		return false;
	end
	local spot = command == "setleft" and 71
		or (command == "setright" and 72)
		or (command == "setcenter" and 73);
	if (not spot) then
		return false;
	end
	local channel = GetNumRaidMembers() > 0 and "RAID" or "PARTY";
	SendChatMessage("rtsc save "..tostring(spot), channel);
	UnBotSpecSummonMessage(
		"RTSC "..tostring(spot)..": теперь примените появившееся заклинание Aedm "
		.."и кликните нужную точку на полу."
	);
	return true;
end

function UnBotValithriaLayoutSend(list, spot, role)
	for _, name in ipairs(list or {}) do
		if (UnBotSpecSummonIsInGroup(name)) then
			SendChatMessage("nc -follow", "WHISPER", nil, name);
			SendChatMessage("co -formation", "WHISPER", nil, name);
			if (role == "dps") then
				UnBotValithriaPrepareDps(name);
			elseif (role == "tank") then
				UnBotValithriaPrepareTank(name);
			end
			SendChatMessage("rtsc go "..tostring(spot), "WHISPER", nil, name);
		end
	end
end

function UnBotValithriaLayoutDeploy()
	local state = UnBotValithriaHeal;
	if (not state.prepared or not state.addControl or UnitAffectingCombat("player")) then
		UnBotSpecSummonMessage("Расстановка доступна после сборки Валитрии 25 гер и только вне боя.");
		return false;
	end
	UnBotValithriaLayoutSend(state.leftTank and {state.leftTank} or {}, 71, "tank");
	UnBotValithriaLayoutSend(state.leftDps, 71, "dps");
	UnBotValithriaLayoutSend(state.rightTank and {state.rightTank} or {}, 72, "tank");
	UnBotValithriaLayoutSend(state.rightDps, 72, "dps");
	UnBotValithriaLayoutSend(state.allHealers, 73, "heal");
	state.layoutDeployed = true;
	UnBotSpecSummonMessage(
		"Валитрия: RTSC-расстановка отправлена. Левый/правый фланги стоят у хвоста, "
		.."хилеры — в центре. Танки используют pull back; боковые ДД работают "
		.."только по адресным черепу/кресту с контролем угрозы."
	);
	return true;
end

function UnBotValithriaDisarm(restore)
	local state = UnBotValithriaHeal;
	UnBotValithriaSetWormDpsAoe(false);
	if (restore) then
		for _, name in ipairs(state.allHealers or state.healers or {}) do
			UnBotValithriaRestoreHealer(name);
		end
	end
	for _, name in ipairs(state.tanks or {}) do
		UnBotValithriaRestoreTank(name);
	end
	for _, name in ipairs(state.leftDps or {}) do
		UnBotValithriaRestoreDps(name);
	end
	for _, name in ipairs(state.rightDps or {}) do
		UnBotValithriaRestoreDps(name);
	end
	state.armed = false;
	state.prepared = false;
	state.active = false;
	state.healers = {};
	state.allHealers = {};
	state.tanks = {};
	state.leftTank = nil;
	state.rightTank = nil;
	state.leftDps = {};
	state.rightDps = {};
	state.layoutDeployed = false;
	state.layoutGuideShown = false;
	state.guideAbominationShown = false;
	state.disabled = {};
	state.errors = {};
	state.pausedUntil = {};
	state.vigorDrops = {};
	state.vigorRepairAt = {};
	state.healerDreamState = {};
	state.portalRecovery = {};
	state.portalRecoveryEvents = 0;
	state.portalRecoveryCommands = 0;
	state.bossName = nil;
	state.bossGuid = nil;
	state.bossLink = nil;
	state.bossMarked = false;
	state.modeKey = nil;
	state.stopAt = nil;
	state.rounds = 0;
	state.confirmed = false;
	state.addControl = false;
	state.insideIccSeen = false;
	state.killedAbominations = {};
	state.abominationKills = 0;
	state.lastAbominationDeathAt = 0;
	state.wormWindowUntil = 0;
	state.wormNextScanAt = 0;
	state.wormNextCommandAt = 0;
	state.wormCommandPhase = "target";
	state.wormCommandAttempts = 0;
	state.wormCurrentGuid = nil;
	state.wormCurrentSeenAt = 0;
	state.wormTargets = 0;
	state.wormWindowReported = false;
	state.wormSide = nil;
	state.wormDpsAt = 0;
	state.wormDpsEnabled = false;
	state.wormDpsCommandPhase = "target";
	state.wormDpsCommandAttempts = 0;
	state.wormDpsNextCommandAt = 0;
	UnBotValithriaResetAddControl();
end

function UnBotValithriaPreparePreset(modeKey)
	local state = UnBotValithriaHeal;
	UnBotRegistryAttachStorage();
	state.armed = true;
	state.prepared = true;
	state.active = false;
	state.healers = {};
	state.allHealers = {};
	state.tanks = {};
	state.leftTank = nil;
	state.rightTank = nil;
	state.leftDps = {};
	state.rightDps = {};
	state.layoutDeployed = false;
	state.layoutGuideShown = false;
	state.guideAbominationShown = false;
	state.disabled = {};
	state.errors = {};
	state.pausedUntil = {};
	state.vigorDrops = {};
	state.vigorRepairAt = {};
	state.healerDreamState = {};
	state.portalRecovery = {};
	state.portalRecoveryEvents = 0;
	state.portalRecoveryCommands = 0;
	state.bossLink = nil;
	state.modeKey = modeKey;
	state.nativeOnly = modeKey == "25h18";
	state.addControl = modeKey == "25h";
	state.insideIccSeen = UnBotValithriaInIcecrownRaid();
	state.preparedUntil = GetTime() + 900;
	state.stopAt = nil;
	state.rounds = 0;
	state.confirmed = false;
	state.killedAbominations = {};
	state.abominationKills = 0;
	state.lastAbominationDeathAt = 0;
	state.wormWindowUntil = 0;
	state.wormNextScanAt = 0;
	state.wormNextCommandAt = 0;
	state.wormCommandPhase = "target";
	state.wormCommandAttempts = 0;
	state.wormCurrentGuid = nil;
	state.wormCurrentSeenAt = 0;
	state.wormTargets = 0;
	state.wormWindowReported = false;
	state.wormSide = nil;
	state.wormDpsAt = 0;
	state.wormDpsEnabled = false;
	state.wormDpsCommandPhase = "target";
	state.wormDpsCommandAttempts = 0;
	state.wormDpsNextCommandAt = 0;
	UnBotValithriaResetAddControl();
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (profile and unit and UnitIsConnected(unit)) then
			local isTank =
				state.addControl
				and name ~= UnitName("player")
				and UnBotBuffCycleTargetIsTank(name);
			local isHealer = UnBotValithriaIsHealer(profile);
			if (isTank) then
				table.insert(state.tanks, name);
				UnBotValithriaPrepareTank(name);
			end
			if (isHealer) then
				table.insert(state.allHealers, name);
				UnBotValithriaPrepareSupportHealer(name);
				if (
					UnBotSpecSummonNormalize(profile.className) == "paladin"
					and UnBotSpecSummonNormalize(profile.specName) == "holy"
				) then
					table.insert(state.healers, name);
					UnBotValithriaPrepareHealer(name);
				end
			elseif (state.nativeOnly and not isTank) then
				for _, command in ipairs({
					"co +avoid aoe",
					"co +dps",
					"co +dps assist",
					"co +icc",
					"nc +icc",
					"co -flee",
					"follow",
				}) do
					SendChatMessage(command, "WHISPER", nil, name);
				end
			elseif (state.addControl and not isTank) then
				if (#state.leftDps <= #state.rightDps) then
					table.insert(state.leftDps, name);
				else
					table.insert(state.rightDps, name);
				end
			end
		end
	end);
	if (state.nativeOnly) then
		if (#state.allHealers < 2) then
			UnBotValithriaDisarm(true);
			UnBotSpecSummonMessage(
				"|cffff6060Валитрия 25 гер #2: нужны два доступных Restoration Druid.|r"
			);
			return false;
		end
		state.armed = false;
		state.prepared = false;
		state.active = false;
		UnBotSpecSummonMessage(
			"Валитрия 25 гер #2: нативная ICC-стратегия готова — два Restoration Druid лечат, два Retribution зачищают аддов; строгий танковый контроль отключён."
		);
		return true;
	end
	state.leftTank = state.tanks[1];
	state.rightTank = state.tanks[2];
	for _, name in ipairs(state.leftDps or {}) do
		UnBotValithriaPrepareDps(name);
	end
	for _, name in ipairs(state.rightDps or {}) do
		UnBotValithriaPrepareDps(name);
	end
	if (#state.healers == 0) then
		UnBotValithriaDisarm(true);
		UnBotSpecSummonMessage(
			"|cffff6060Валитрия: в онлайн-составе не найден Holy Paladin; прямой хил не запущен.|r"
		);
		return false;
	end
	if (#state.allHealers < 2) then
		UnBotValithriaDisarm(true);
		UnBotSpecSummonMessage(
			"|cffff6060Валитрия: нужен минимум второй хилер. Один сервером оставляется на рейде и не идёт в порталы; рекомендуется Holy Paladin + Restoration Druid.|r"
		);
		return false;
	end
	if (state.addControl and #state.tanks < 2) then
		UnBotSpecSummonMessage(
			"|cffff6060Валитрия 25 гер: найдено танков "
			..tostring(#state.tanks)
			.."/2; автоматический сбор личинок будет ограничен.|r"
		);
	end
	if (state.addControl) then
		UnBotValithriaLayoutStatus();
		UnBotSpecSummonMessage(
			"Валитрия 25 гер: для первой настройки трёх точек используйте /ubvalithria layout; "
			.."если RTSC 71/72/73 уже сохранены — достаточно /ubvalithria deploy."
		);
	end
	UnBotValithriaMarkVisibleBoss(true);
	UnBotSpecSummonMessage(
		"|cffffff00Валитрия: включён гибридный режим — адресный Holy Light и серверные ICC-порталы ("
		..table.concat(state.healers, ", ")
		.."). Хилеры: "..table.concat(state.allHealers, ", ")
		..". Возьмите Валитрию в цель; до боя UnBot также отметит её звездой."
		..(state.addControl and (
			" Танки: "..table.concat(state.tanks, ", ")
			.." — включён tank aoe и сбор личинок после смерти поганища."
		) or "")
	);
	if (
		state.bossName
		and (
			UnitAffectingCombat("player")
			or (InCombatLockdown and InCombatLockdown())
		)
	) then
		UnBotValithriaBegin();
	end
	return true;
end

function UnBotValithriaBegin()
	local state = UnBotValithriaHeal;
	if (not state.armed or not state.prepared) then
		return false;
	end
	if (not UnBotValithriaInIcecrownRaid()) then
		return false;
	end
	state.insideIccSeen = true;
	if (UnBotValithriaAvailableCount(state.allHealers) < 2) then
		UnBotSpecSummonMessage(
			"|cffff6060Валитрия: запуск отменён — доступно меньше двух хилеров.|r"
		);
		UnBotValithriaDisarm(true);
		return false;
	end
	if (
		not state.bossName
		or not state.bossGuid
		or not state.bossLink
		or #state.healers == 0
	) then
		if (
			state.armed
			and state.prepared
			and (not state.bossName or not state.bossGuid or not state.bossLink)
		) then
			UnBotSpecSummonMessage(
				"|cffff6060Валитрия: прямой хил не стартовал — возьмите Валитрию в цель; требуется её точный GUID.|r"
			);
		end
		return false;
	end
	state.active = true;
	state.startedAt = GetTime();
	state.nextCastAt = state.startedAt + 1.8;
	state.stopAt = nil;
	state.rounds = 0;
	state.confirmed = false;
	state.killedAbominations = {};
	state.abominationKills = 0;
	state.lastAbominationDeathAt = 0;
	state.wormWindowUntil = 0;
	state.wormCommandAttempts = 0;
	state.wormTargets = 0;
	state.wormSide = nil;
	state.wormDpsAt = 0;
	state.wormDpsEnabled = false;
	state.wormDpsCommandPhase = "target";
	state.wormDpsCommandAttempts = 0;
	state.wormDpsNextCommandAt = 0;
	state.guideAbominationShown = false;
	state.healerDreamState = {};
	state.portalRecovery = {};
	state.portalRecoveryEvents = 0;
	state.portalRecoveryCommands = 0;
	UnBotValithriaResetAddControl();
	for _, name in ipairs(state.tanks or {}) do
		UnBotValithriaPrepareTank(name);
	end
	for _, name in ipairs(state.leftDps or {}) do
		UnBotValithriaPrepareDps(name);
	end
	for _, name in ipairs(state.rightDps or {}) do
		UnBotValithriaPrepareDps(name);
	end
	for _, name in ipairs(state.healers) do
		if (UnBotSpecSummonIsInGroup(name)) then
			SendChatMessage("co -attack force", "WHISPER", nil, name);
			SendChatMessage("co -flee", "WHISPER", nil, name);
			SendChatMessage("co +heal", "WHISPER", nil, name);
			SendChatMessage("co +icc", "WHISPER", nil, name);
			SendChatMessage("nc +icc", "WHISPER", nil, name);
			SendChatMessage("follow", "WHISPER", nil, name);
			if (state.bossMarked) then
				SendChatMessage("rti star", "WHISPER", nil, name);
			end
			if (state.bossLink) then
				SendChatMessage(
					"cast "..state.bossLink.." Beacon of Light",
					"WHISPER", nil, name
				);
			end
		end
	end
	UnBotSpecSummonMessage(
		"Валитрия: GUID-лечение запущено вместе с ICC-порталами; Частица Света и Свет небес каждые 2.8 сек."
	);
	if (state.addControl) then
		UnBotSpecSummonMessage(
			"Валитрия: контроль аддов активен — череп слева, крест справа; "
			.."зомби/поганище ждут реальный урон или таунт назначенного танка, "
			.."без подтверждения ДД не выпускаются; скелет фокусится сразу."
		);
	end
	return true;
end

function UnBotValithriaStopPull(reason)
	local state = UnBotValithriaHeal;
	if (not state.active) then
		return;
	end
	UnBotValithriaSetWormDpsAoe(false);
	state.active = false;
	state.stopAt = nil;
	state.wormWindowUntil = 0;
	state.wormCurrentGuid = nil;
	state.wormCurrentSeenAt = 0;
	UnBotSpecSummonMessage(
		"Валитрия: прямой хил остановлен ("..tostring(reason or "бой завершён")
		.."; циклов "..tostring(state.rounds or 0)..")."
	);
end

function UnBotValithriaHandleWhisper(message, sender)
	local state = UnBotValithriaHeal;
	if (not state.prepared or not sender) then
		return;
	end
	local name = UnBotValithriaHealerName(sender);
	if (not name) then
		return;
	end
	local text = UnBotSpecSummonNormalize(message);
	local isValithria = string.find(
		text, UnBotSpecSummonNormalize("Валитрия Сноходица"), 1, true
	) or string.find(text, "valithria dreamwalker", 1, true);
	if (
		state.active
		and isValithria
		and string.find(text, "casting", 1, true)
		and string.find(text, "holy light", 1, true)
	) then
		state.errors[name] = 0;
		state.pausedUntil[name] = nil;
		if (not state.confirmed) then
			state.confirmed = true;
			UnBotSpecSummonMessage(
				"|cff33ff66Валитрия: подтверждено — "..name.." кастует Holy Light именно в Валитрию.|r"
			);
		end
		return;
	end
	local fatal = string.find(text, "unknown spell", 1, true)
		or string.find(text, "spell not found", 1, true);
	local targetError = string.find(text, "no target", 1, true)
		or string.find(text, "target not found", 1, true)
		or string.find(text, "invalid target", 1, true)
		or string.find(text, "cannot cast", 1, true)
		or string.find(text, "can't cast", 1, true);
	if (targetError and not isValithria) then
		fatal = true;
	end
	if (not fatal and not targetError) then
		return;
	end
	state.errors[name] = (state.errors[name] or 0) + 1;
	if (targetError and isValithria and not fatal) then
		if (state.errors[name] >= 5) then
			state.errors[name] = 0;
			state.pausedUntil[name] = GetTime() + 20;
			UnBotSpecSummonMessage(
				"Валитрия: "..name.." временно не может кастовать в правильную цель; пауза адресных команд 20 секунд для портала/маны."
			);
		end
		return;
	end
	if (fatal) then
		state.disabled[name] = true;
		UnBotSpecSummonMessage(
			"|cffff6060Валитрия: "..name.." исключён из прямого хила после ответа: "
			..tostring(message).."|r"
		);
	end
end

UnBotValithriaFrame = UnBotValithriaFrame
	or CreateFrame("Frame", "UnBotValithriaFrame");
UnBotValithriaFrame:RegisterEvent("PLAYER_TARGET_CHANGED");
UnBotValithriaFrame:RegisterEvent("PLAYER_REGEN_DISABLED");
UnBotValithriaFrame:RegisterEvent("PLAYER_REGEN_ENABLED");
UnBotValithriaFrame:RegisterEvent("CHAT_MSG_WHISPER");
UnBotValithriaFrame:RegisterEvent("COMBAT_LOG_EVENT_UNFILTERED");
UnBotValithriaFrame:RegisterEvent("ZONE_CHANGED_NEW_AREA");
UnBotValithriaFrame:SetScript("OnEvent", function(self, event, ...)
	local state = UnBotValithriaHeal;
	if (event == "CHAT_MSG_WHISPER") then
		UnBotValithriaHandleWhisper(select(1, ...), select(2, ...));
	elseif (event == "COMBAT_LOG_EVENT_UNFILTERED") then
		UnBotValithriaHandleCombatLog(...);
	elseif (event == "ZONE_CHANGED_NEW_AREA") then
		if (UnBotValithriaInIcecrownRaid()) then
			state.insideIccSeen = true;
		elseif (state.insideIccSeen and (state.armed or state.prepared or state.active)) then
			UnBotValithriaDisarm(true);
			UnBotSpecSummonMessage(
				"Валитрия: подготовка снята после выхода из ЦЛК; вне рейда проверки хилов отключены."
			);
		end
	elseif (
		event == "PLAYER_TARGET_CHANGED"
		and state.armed
		and not state.active
		and UnBotValithriaInIcecrownRaid()
	) then
		UnBotValithriaMarkVisibleBoss(false);
		if (
			state.prepared
			and state.bossName
			and (
				UnitAffectingCombat("player")
				or (InCombatLockdown and InCombatLockdown())
			)
		) then
			UnBotValithriaBegin();
		end
	elseif (event == "PLAYER_REGEN_DISABLED") then
		UnBotValithriaBegin();
	elseif (event == "PLAYER_REGEN_ENABLED" and state.active) then
		state.stopAt = GetTime() + 6;
	end
end);
UnBotValithriaFrame:SetScript("OnUpdate", function()
	local state = UnBotValithriaHeal;
	local now = GetTime();
	if (now < (state.nextScanAt or 0)) then
		return;
	end
	state.nextScanAt = now + 0.2;
	if (not UnBotValithriaInIcecrownRaid()) then
		return;
	end
	state.insideIccSeen = true;
	if (state.armed and state.prepared and not state.active) then
		if (now > (state.preparedUntil or 0)) then
			UnBotValithriaDisarm(true);
			UnBotSpecSummonMessage("Валитрия: подготовка снята по таймауту 15 минут.");
			return;
		end
		if (not UnitAffectingCombat("player")) then
			UnBotValithriaMarkVisibleBoss(true);
		end
	end
	if (not state.active) then
		return;
	end
	UnBotValithriaProcessAddControl(now);
	UnBotValithriaProcessWormCollection(now);
	UnBotValithriaProcessPortalRecovery(now);
	if (UnBotValithriaAvailableCount(state.allHealers) < 2) then
		UnBotValithriaStopPull("осталось меньше двух доступных хилеров");
		UnBotValithriaDisarm(false);
		return;
	end
	if (state.stopAt and now >= state.stopAt) then
		UnBotValithriaStopPull("выход из боя");
		return;
	end
	local bossUnit = UnBotValithriaFindVisibleUnit();
	if (bossUnit and UnitHealthMax(bossUnit) > 0 and UnitHealth(bossUnit) >= UnitHealthMax(bossUnit)) then
		UnBotValithriaStopPull("Валитрия полностью вылечена");
		return;
	end
	if (
		now - (state.startedAt or now) >= (state.maxSeconds or 900)
		or (state.rounds or 0) >= (state.maxRounds or 320)
	) then
		UnBotValithriaStopPull("достигнут конечный лимит 15 минут/320 циклов");
		return;
	end
	if (now < (state.nextCastAt or 0)) then
		return;
	end
	state.nextCastAt = now + 2.8;
	state.rounds = (state.rounds or 0) + 1;
	local sent = 0;
	local availableDirect = 0;
	for _, name in ipairs(state.healers or {}) do
		local unit = UnBotSquadRosterFindUnit(name);
		if (
			not state.disabled[name]
			and unit
			and UnitIsConnected(unit)
			and not UnitIsDeadOrGhost(unit)
		) then
			availableDirect = availableDirect + 1;
			local manaMax = UnitManaMax(unit) or 0;
			local lowMana = manaMax > 0 and (UnitMana(unit) or 0) / manaMax < 0.08;
			if (
				not UnBotValithriaUnitInDream(unit)
				and not lowMana
				and not state.portalRecovery[name]
				and now >= (state.pausedUntil[name] or 0)
			) then
				SendChatMessage(
					"cast "..state.bossLink.." Holy Light",
					"WHISPER", nil, name
				);
				sent = sent + 1;
			end
		end
	end
	if (availableDirect == 0) then
		UnBotValithriaStopPull("нет доступного Holy Paladin");
		UnBotValithriaDisarm(false);
	end
end);

SLASH_UNBOTVALITHRIA1 = "/ubvalithria";
SlashCmdList["UNBOTVALITHRIA"] = function(message)
	local command = UnBotSpecSummonNormalize(message or "");
	if (command == "stop" or command == "off") then
		UnBotValithriaDisarm(true);
		UnBotSpecSummonMessage("Валитрия: специальный прямой хил выключен.");
	elseif (command == "layout") then
		UnBotValithriaLayoutBegin();
	elseif (
		command == "setleft"
		or command == "setright"
		or command == "setcenter"
	) then
		UnBotValithriaLayoutSaveSpot(command);
	elseif (command == "deploy") then
		UnBotValithriaLayoutDeploy();
	elseif (command == "sides") then
		UnBotValithriaLayoutStatus();
	elseif (command == "status") then
		local state = UnBotValithriaHeal;
		local vigorDropCount = 0;
		for _, count in pairs(state.vigorDrops or {}) do
			vigorDropCount = vigorDropCount + (tonumber(count) or 0);
		end
		UnBotSpecSummonMessage(
			"Валитрия: armed="..tostring(state.armed)
			..", prepared="..tostring(state.prepared)
			..", active="..tostring(state.active)
			..", target="..tostring(state.bossName or "нет")
			..", marked="..tostring(state.bossMarked)
			..", link="..tostring(state.bossLink ~= nil)
			..", confirmed="..tostring(state.confirmed)
			..", direct="..table.concat(state.healers or {}, ", ")
			..", allhealers="..table.concat(state.allHealers or {}, ", ")
			..", available="..tostring(UnBotValithriaAvailableCount(state.allHealers))
			..", insideICC="..tostring(UnBotValithriaInIcecrownRaid())
			..", addControl="..tostring(state.addControl)
			..", tanks="..table.concat(state.tanks or {}, ", ")
			..", leftTank="..tostring(state.leftTank)
			..", rightTank="..tostring(state.rightTank)
			..", leftDps="..tostring(#(state.leftDps or {}))
			..", rightDps="..tostring(#(state.rightDps or {}))
			..", layout="..tostring(state.layoutDeployed)
			..", abominations="..tostring(state.abominationKills or 0)
			..", wormCommands="..tostring(state.wormCommandAttempts or 0)
			..", wormDpsCommands="..tostring(state.wormDpsCommandAttempts or 0)
			..", wormSide="..tostring(state.wormSide or "нет")
			..", addClaims="..tostring(state.addClaims or 0)
			..", tankClaimEvents="..tostring(state.tankClaimEvents or 0)
			..", dpsGateReleases="..tostring(state.dpsGateReleases or 0)
			..", portalRecoveries="..tostring(state.portalRecoveryEvents or 0)
			..", portalSelfHeals="..tostring(state.portalRecoveryCommands or 0)
			..", markerFailures="..tostring(state.addMarkerFailures or 0)
			..", leftAdd="..tostring(
				UnBotValithriaSideState("left").displayName or "нет"
			)
			..", rightAdd="..tostring(
				UnBotValithriaSideState("right").displayName or "нет"
			)
			..", leftFallback="..tostring(
				UnBotValithriaSideState("left").passiveReleased and true or false
			)
			..", rightFallback="..tostring(
				UnBotValithriaSideState("right").passiveReleased and true or false
			)
			..", vigorDrops="..tostring(vigorDropCount)
			..", rounds="..tostring(state.rounds or 0).."."
		);
	else
		local modeKey = command == "25h" and "25h"
			or (command == "25h18" and "25h18")
			or (command == "25n" and "25n")
			or (command == "10h" and "10h")
			or (command == "10n" and "10n")
			or UnBotValithriaCurrentModeKey();
		UnBotSpecSummonMessage(
			"Валитрия: ручная подготовка определила режим "..tostring(modeKey)
			.." (сложность экземпляра "..tostring(select(3, GetInstanceInfo()) or "?")..")."
		);
		UnBotValithriaPreparePreset(modeKey);
	end
end

UnBotPutricideDrink = UnBotPutricideDrink or {
	armed = false,
	active = false,
	playerPilot = true,
	assistTank = nil,
	assistUnit = nil,
	assistIccSuppressed = false,
	queryAt = 0,
	queryAttempts = 0,
	waitingLos = false,
	useSentAt = 0,
	confirmed = false,
	failedThisCombat = false,
	bossOnlyMode = false,
	bossOnlyNames = {},
	bossOnlyHealerNames = {},
	normalAnchorMode = false,
	normalAnchorNames = {},
	normalAnchorLocked = false,
	normalAnchorLockAt = 0,
	normalAnchorRotationUntil = 0,
	normalAnchorNextJudgementAt = 0,
	normalAnchorJudgementAttempts = 0,
	normalAnchorLastBossSwingAt = 0,
	normalAnchorPhaseLocks = 0,
	bossFocusAttempts = 0,
	bossFocusNextAt = 0,
	bossFocusUntil = 0,
};

function UnBotPutricideSelectAssistTank()
	UnBotRegistryAttachStorage();
	local tanks = {};
	local explicitMainTank = nil;
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (
			profile
			and unit and UnitIsConnected(unit)
			and UnBotSpecSummonIsTankSpec(
				profile.className,
				UnBotFeralProfileRole(profile) or profile.specName
			)
		) then
			local tank = {
				name = name,
				unit = unit,
				mainTank = GetPartyAssignment
					and GetPartyAssignment("MAINTANK", unit),
			};
			table.insert(tanks, tank);
			if (tank.mainTank) then
				explicitMainTank = tank;
			end
		end
	end);
	if (#tanks < 2) then
		return nil, nil, #tanks, explicitMainTank;
	end

	-- SetPartyAssignment is protected/taint-sensitive in this 3.3.5 client.
	-- Never call it from the addon. For player-pilot mode we only need a
	-- deterministic second tank whose ICC strategy can be suppressed until
	-- the player enters the abomination.
	if (explicitMainTank) then
		for _, tank in ipairs(tanks) do
			if (tank ~= explicitMainTank) then
				return tank.name, tank.unit, #tanks, explicitMainTank;
			end
		end
	end
	return tanks[2].name, tanks[2].unit, #tanks, tanks[1];
end

function UnBotPutricideSetAssistIcc(enabled)
	local state = UnBotPutricideDrink;
	if (not state.assistTank) then
		state.assistIccSuppressed = false;
		return false;
	end
	local operation = enabled and "+icc" or "-icc";
	SendChatMessage("co "..operation, "WHISPER", nil, state.assistTank);
	SendChatMessage("nc "..operation, "WHISPER", nil, state.assistTank);
	state.assistIccSuppressed = not enabled;
	return true;
end

function UnBotPutricideApplyNormalAnchorCommands(name)
	if (not UnBotSpecSummonIsInGroup(name)) then
		return false;
	end
	-- Passive is the hard stop for the class AI. The explicit removals are kept as
	-- a fallback for server builds where the passive strategy is unavailable.
	SendChatMessage("co +passive", "WHISPER", nil, name);
	SendChatMessage(
		"co -tank,-tank aoe,-tank assist,-dps,-dps aoe,-dps assist,-dps debuff,-attack weak,-attack force,-grind,-aoe,-heal",
		"WHISPER", nil, name
	);
	SendChatMessage(
		"co -avoid aoe,-icc,-formation,-flee,-behind,-boost,-threat",
		"WHISPER", nil, name
	);
	SendChatMessage(
		"nc -icc,-follow,-move random,-grind,-attack weak,-attack force",
		"WHISPER", nil, name
	);
	SendChatMessage("nc +stay", "WHISPER", nil, name);
	SendChatMessage("stay", "WHISPER", nil, name);
	SendChatMessage("cast Seal of Wisdom", "WHISPER", nil, name);
	return true;
end

function UnBotPutricideLockNormalAnchors(reason)
	local state = UnBotPutricideDrink;
	if (not state.normalAnchorMode or state.normalAnchorLocked) then
		return false;
	end
	local lockedCount = 0;
	for _, name in ipairs(state.normalAnchorNames or {}) do
		if (UnBotPutricideApplyNormalAnchorCommands(name)) then
			lockedCount = lockedCount + 1;
		end
	end
	state.normalAnchorLocked = true;
	state.normalAnchorLockAt = 0;
	state.normalAnchorRotationUntil = GetTime() + 720;
	state.normalAnchorNextJudgementAt = GetTime() + 1.8;
	state.normalAnchorJudgementAttempts = 0;
	state.normalAnchorPhaseLocks = 0;
	UnBotSpecSummonMessage(
		"|cff33ff66Мерзоцид 25 обычный: прот-пал переведён в жёсткий passive + nc stay; все варианты tank/DPS/follow отключены, Правосудие разрешено только при свежем мили-ударе босса"
		..(reason and " ("..tostring(reason)..")" or "")..".|r"
	);
	return lockedCount > 0;
end

function UnBotPutricideDisarm()
	local state = UnBotPutricideDrink;
	if (state.assistIccSuppressed) then
		UnBotPutricideSetAssistIcc(true);
	end
	if (state.bossOnlyMode) then
		for _, name in ipairs(state.bossOnlyNames or {}) do
			if (UnBotSpecSummonIsInGroup(name)) then
				UnBotGroupStrategySendManualProfile(name, true);
				SendChatMessage("co -attack force", "WHISPER", nil, name);
				SendChatMessage("co +dps assist", "WHISPER", nil, name);
				SendChatMessage("nc +icc", "WHISPER", nil, name);
			end
		end
		for _, name in ipairs(state.bossOnlyHealerNames or {}) do
			if (UnBotSpecSummonIsInGroup(name)) then
				SendChatMessage("follow", "WHISPER", nil, name);
				SendChatMessage("co -attack force", "WHISPER", nil, name);
				SendChatMessage("co +flee", "WHISPER", nil, name);
				SendChatMessage("co +dps assist", "WHISPER", nil, name);
				SendChatMessage("co +formation", "WHISPER", nil, name);
				SendChatMessage("co +avoid aoe", "WHISPER", nil, name);
				SendChatMessage("co +icc", "WHISPER", nil, name);
				SendChatMessage("nc +icc", "WHISPER", nil, name);
			end
		end
	end
	if (state.normalAnchorMode) then
		for _, name in ipairs(state.normalAnchorNames or {}) do
			if (UnBotSpecSummonIsInGroup(name)) then
				SendChatMessage("co -passive", "WHISPER", nil, name);
				SendChatMessage("nc -stay", "WHISPER", nil, name);
				SendChatMessage("follow", "WHISPER", nil, name);
				SendChatMessage("nc +follow", "WHISPER", nil, name);
				SendChatMessage("co +aoe", "WHISPER", nil, name);
				SendChatMessage("co +avoid aoe", "WHISPER", nil, name);
				SendChatMessage("co +icc", "WHISPER", nil, name);
				SendChatMessage("nc +icc", "WHISPER", nil, name);
				SendChatMessage("co +dps", "WHISPER", nil, name);
				SendChatMessage("co +dps assist", "WHISPER", nil, name);
				SendChatMessage("co +formation", "WHISPER", nil, name);
				SendChatMessage("co +flee", "WHISPER", nil, name);
				SendChatMessage("co +tank", "WHISPER", nil, name);
			end
		end
	end
	state.armed = false;
	state.active = false;
	state.assistTank = nil;
	state.assistUnit = nil;
	state.assistIccSuppressed = false;
	state.confirmed = false;
	state.failedThisCombat = false;
	state.waitingLos = false;
	state.bossOnlyMode = false;
	state.bossOnlyNames = {};
	state.bossOnlyHealerNames = {};
	state.normalAnchorMode = false;
	state.normalAnchorNames = {};
	state.normalAnchorLocked = false;
	state.normalAnchorLockAt = 0;
	state.normalAnchorRotationUntil = 0;
	state.normalAnchorNextJudgementAt = 0;
	state.normalAnchorJudgementAttempts = 0;
	state.normalAnchorLastBossSwingAt = 0;
	state.normalAnchorPhaseLocks = 0;
	state.bossFocusAttempts = 0;
	state.bossFocusNextAt = 0;
	state.bossFocusUntil = 0;
end

function UnBotPutricidePreparePreset(modeKey)
	if (modeKey == "25n") then
		UnBotRegistryAttachStorage();
		local anchorNames = {};
		UnBotBuffCycleForEachGroupMember(function(name, unit)
			local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
			if (
				profile
				and unit and UnitIsConnected(unit)
				and UnBotSpecSummonNormalize(profile.className) == "paladin"
				and (
					UnBotSpecSummonNormalize(profile.specName) == "protection"
					or UnBotSpecSummonNormalize(profile.specName) == "prot"
				)
			) then
				table.insert(anchorNames, name);
			end
		end);
		UnBotPutricideDisarm();
		if (#anchorNames == 0) then
			UnBotSpecSummonMessage(
				"|cffff3333Мерзоцид 25 обычный: подключённый Protection Paladin не найден; профиль неподвижного танка не включён.|r"
			);
			return;
		end
		UnBotPutricideDrink.normalAnchorMode = true;
		UnBotPutricideDrink.normalAnchorNames = anchorNames;
		UnBotPutricideDrink.normalAnchorLocked = false;
		UnBotPutricideDrink.normalAnchorLockAt = 0;
		UnBotPutricideDrink.normalAnchorRotationUntil = 0;
		UnBotPutricideDrink.normalAnchorNextJudgementAt = 0;
		UnBotPutricideDrink.normalAnchorJudgementAttempts = 0;
		UnBotPutricideDrink.normalAnchorLastBossSwingAt = 0;
		UnBotPutricideDrink.normalAnchorPhaseLocks = 0;
		UnBotPutricideDrink.armed = true;
		UnBotPutricideDrink.active = false;
		UnBotPutricideDrink.playerPilot = true;
		UnBotPutricideDrink.confirmed = false;
		UnBotPutricideDrink.failedThisCombat = false;
		for _, name in ipairs(anchorNames) do
			SendChatMessage("co -passive", "WHISPER", nil, name);
			SendChatMessage("co -aoe", "WHISPER", nil, name);
			SendChatMessage("co -tank aoe", "WHISPER", nil, name);
			SendChatMessage("co -tank assist", "WHISPER", nil, name);
			SendChatMessage("co -avoid aoe", "WHISPER", nil, name);
			SendChatMessage("co -icc", "WHISPER", nil, name);
			SendChatMessage("nc -icc", "WHISPER", nil, name);
			SendChatMessage("co -dps", "WHISPER", nil, name);
			SendChatMessage("co -dps assist", "WHISPER", nil, name);
			SendChatMessage("co -formation", "WHISPER", nil, name);
			SendChatMessage("co -attack force", "WHISPER", nil, name);
			SendChatMessage("co -flee", "WHISPER", nil, name);
			SendChatMessage("co +tank", "WHISPER", nil, name);
			SendChatMessage("nc -follow", "WHISPER", nil, name);
			SendChatMessage("nc +stay", "WHISPER", nil, name);
			SendChatMessage("stay", "WHISPER", nil, name);
			SendChatMessage("cast Seal of Wisdom", "WHISPER", nil, name);
			SendChatMessage("co ?", "WHISPER", nil, name);
			SendChatMessage("nc ?", "WHISPER", nil, name);
		end
		UnBotSpecSummonMessage(
			"|cff33ff66Мерзоцид 25 обычный: Protection Paladin "
			..table.concat(anchorNames, ", ")
			.." подготовлен как танк-якорь: tank работает только до первого мили-удара Мерзоцида, затем остаются неподвижная автоатака, Печать/Правосудие мудрости и адресный самохил.|r"
		);
		UnBotSpecSummonMessage(
			"Поставьте прот-пала в нужной точке до пула, держите Мерзоцида в цели и выпейте Drink Me! своим персонажем. Танк не будет убегать из лужи."
		);
		return;
	end
	if (modeKey ~= "25h") then
		return;
	end
	UnBotRegistryAttachStorage();
	local groupBots = {};
	local tankCount = 0;
	local combatRogueCount = 0;
	local meleeWarriorCount = 0;
	local holyPaladinCount = 0;
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (profile and unit and UnitIsConnected(unit)) then
			table.insert(groupBots, { name = name, profile = profile });
			if (UnBotSpecSummonIsTankSpec(
				profile.className,
				UnBotFeralProfileRole(profile) or profile.specName
			)) then
				tankCount = tankCount + 1;
			elseif (
				UnBotSpecSummonNormalize(profile.className) == "rogue"
				and UnBotSpecSummonNormalize(profile.specName) == "combat"
			) then
				combatRogueCount = combatRogueCount + 1;
			elseif (
				UnBotSpecSummonNormalize(profile.className) == "warrior"
				and (
					UnBotSpecSummonNormalize(profile.specName) == "fury"
					or UnBotSpecSummonNormalize(profile.specName) == "arms"
				)
			) then
				meleeWarriorCount = meleeWarriorCount + 1;
			elseif (
				UnBotSpecSummonNormalize(profile.className) == "paladin"
				and UnBotSpecSummonNormalize(profile.specName) == "holy"
			) then
				holyPaladinCount = holyPaladinCount + 1;
			end
		end
	end);

	local bossOnlyMode = (
		(
			#groupBots == 2 + holyPaladinCount
			and tankCount == 0
			and combatRogueCount == 1
			and meleeWarriorCount == 1
			and holyPaladinCount <= 1
		)
		or (
			#groupBots == 1
			and tankCount == 0
			and combatRogueCount == 0
			and meleeWarriorCount == 0
			and holyPaladinCount == 1
		)
	);
	if (bossOnlyMode) then
		-- Экспериментальная схема из ручного прохождения: игрок сам танкует,
		-- водит Мерзоцида, а милишники получают одну цель на весь бой. Attack
		-- force запрещает самостоятельный выбор слизней, ICC и отход из AoE.
		UnBotPutricideDisarm();
		UnBotPutricideDrink.bossOnlyMode = true;
		UnBotPutricideDrink.bossOnlyNames = {};
		UnBotPutricideDrink.bossOnlyHealerNames = {};
		UnBotPutricideDrink.bossFocusAttempts = 0;
		UnBotPutricideDrink.bossFocusNextAt = 0;
		UnBotPutricideDrink.bossFocusUntil = 0;
		for _, bot in ipairs(groupBots) do
			if (
				UnBotSpecSummonNormalize(bot.profile.className) == "paladin"
				and UnBotSpecSummonNormalize(bot.profile.specName) == "holy"
			) then
				table.insert(UnBotPutricideDrink.bossOnlyHealerNames, bot.name);
				SendChatMessage("co -aoe", "WHISPER", nil, bot.name);
				SendChatMessage("co -avoid aoe", "WHISPER", nil, bot.name);
				SendChatMessage("co -icc", "WHISPER", nil, bot.name);
				SendChatMessage("co -dps", "WHISPER", nil, bot.name);
				SendChatMessage("co -dps assist", "WHISPER", nil, bot.name);
				SendChatMessage("co -formation", "WHISPER", nil, bot.name);
				SendChatMessage("co -attack force", "WHISPER", nil, bot.name);
				SendChatMessage("co -flee", "WHISPER", nil, bot.name);
				SendChatMessage("nc -icc", "WHISPER", nil, bot.name);
				SendChatMessage("co +heal", "WHISPER", nil, bot.name);
				SendChatMessage("stay", "WHISPER", nil, bot.name);
			else
				table.insert(UnBotPutricideDrink.bossOnlyNames, bot.name);
				UnBotGroupStrategySendManualProfile(bot.name, false);
				SendChatMessage("co -dps assist", "WHISPER", nil, bot.name);
				SendChatMessage("co +attack force", "WHISPER", nil, bot.name);
				SendChatMessage("co +dps", "WHISPER", nil, bot.name);
				SendChatMessage("co +behind", "WHISPER", nil, bot.name);
				SendChatMessage("co +boost", "WHISPER", nil, bot.name);
				SendChatMessage("co +potions", "WHISPER", nil, bot.name);
				SendChatMessage("nc -icc", "WHISPER", nil, bot.name);
			end
			SendChatMessage("co ?", "WHISPER", nil, bot.name);
			SendChatMessage("nc ?", "WHISPER", nil, bot.name);
		end
		UnBotSpecSummonMessage(
			"|cffffff00Мерзоцид 25 гер — boss-only профиль: присутствующие Combat Rogue и "
			.."Arms/Fury Warrior получили attack force + behind. Отключены dps assist, "
			.."aoe, avoid aoe и icc (co/nc). Holy Paladin переведён в режим лечебной "
			.."турели: stay + heal, без attack force и flee; отключены aoe, dps, "
			.."dps assist, formation, avoid aoe и icc. Drink Me! не используется.|r"
		);
		UnBotSpecSummonMessage(
			"Перед пулом и первую секунду боя держите Мерзоцида в цели. Боты будут закреплены только на нём и проигнорируют слизней и лужи."
		);
		return;
	end

	if (UnBotPutricideDrink.bossOnlyMode) then
		UnBotPutricideDisarm();
	end
	if (UnBotPutricideDrink.assistIccSuppressed) then
		UnBotPutricideSetAssistIcc(true);
	end
	if (UnBotSindragosaBroadcast) then
		UnBotSindragosaBroadcast("co +icc");
		UnBotSindragosaBroadcast("nc +icc");
	end
	local botCount = #groupBots;
	for _, bot in ipairs(groupBots) do
		local profile = bot.profile;
		if (
			profile
			and UnBotSpecSummonIsTankSpec(
				profile.className,
				UnBotFeralProfileRole(profile) or profile.specName
			)
		) then
			UnBotSpecSummonEnsureTankStrategy(
				bot.name,
				profile.className,
				UnBotFeralProfileRole(profile) or profile.specName,
				"putricide-25h-preset"
			);
		end
	end
	local assistTank, assistUnit, selectedTankCount, mainTank =
		UnBotPutricideSelectAssistTank();
	UnBotPutricideDrink.armed = true;
	UnBotPutricideDrink.active = false;
	UnBotPutricideDrink.playerPilot = true;
	UnBotPutricideDrink.assistTank = assistTank;
	UnBotPutricideDrink.assistUnit = assistUnit;
	UnBotPutricideDrink.queryAt = 0;
	UnBotPutricideDrink.queryAttempts = 0;
	UnBotPutricideDrink.waitingLos = false;
	UnBotPutricideDrink.useSentAt = 0;
	UnBotPutricideDrink.confirmed = false;
	UnBotPutricideDrink.failedThisCombat = false;
	UnBotPutricideSetAssistIcc(false);
	UnBotSpecSummonMessage(
		"Мерзоцид 25 гер: icc включена для штатного фокуса слизнюков; "
		..tostring(tankCount).." танкам повторно включена стратегия tank."
	);
	if (assistTank) then
		UnBotSpecSummonMessage(
			"Мерзоцид: пилот мерзости — "..UnitName("player")..". У второго танка "
			..assistTank.." временно отключена icc, чтобы он не выпил Drink Me! "
			.."раньше игрока."
		);
	else
		UnBotSpecSummonMessage(
			"|cffff6633Мерзоцид: второй танк не найден, но ручное превращение "
			.."игрока остаётся включено.|r"
		);
	end
	if (botCount > 6) then
		UnBotSpecSummonMessage(
			"|cffff6633В группе "..tostring(botCount)
			.." ботов, а пресет рассчитан на 6. Лишние участники не удаляются "
			.."автоматически и увеличивают здоровье босса.|r"
		);
	end
end

local function UnBotSindragosaIsTombTarget()
	if (not UnitExists("target")) then
		return false;
	end
	local name = UnBotSpecSummonNormalize(UnitName("target"));
	return (
		string.find(name, "ice tomb", 1, true)
		or string.find(name, "ледяной склеп", 1, true)
		or string.find(name, "ледяная глыба", 1, true)
	) and true or false;
end

function UnBotSindragosaGroupChannel()
	if (GetNumRaidMembers() and GetNumRaidMembers() > 0) then
		return "RAID";
	elseif (GetNumPartyMembers() and GetNumPartyMembers() > 0) then
		return "PARTY";
	end
	return nil;
end

function UnBotSindragosaBroadcast(command)
	local channel = UnBotSindragosaGroupChannel();
	if (channel) then
		SendChatMessage(command, channel);
		return true;
	end
	return false;
end

function UnBotPutricideNameMatches(name)
	name = UnBotSpecSummonNormalize(name);
	return (
		string.find(name, "professor putricide", 1, true)
		or string.find(name, "профессор мерзоцид", 1, true)
	) and true or false;
end

function UnBotPutricideBeginDrink()
	local state = UnBotPutricideDrink;
	if (
		not state.armed
		or state.active
		or state.failedThisCombat
	) then
		return;
	end
	state.active = true;
	state.queryAt = state.playerPilot and 0 or (GetTime() + 0.8);
	state.queryAttempts = 0;
	state.waitingLos = false;
	state.useSentAt = 0;
	state.confirmed = false;
	if (state.playerPilot) then
		UnBotSpecSummonMessage(
			"|cffffff00Мерзоцид: выпейте Drink Me! своим персонажем и "
			.."поглощайте Growing Ooze Puddle. Боты напиток не используют.|r"
		);
	else
		UnBotSpecSummonMessage(
			"Мерзоцид: бой начался; запрашиваю Drink Me! только у второго танка "
			..tostring(state.assistTank).."."
		);
	end
end

function UnBotPutricideTransformationPresent()
	local state = UnBotPutricideDrink;
	if (state.playerPilot) then
		if (
			(UnitInVehicle and UnitInVehicle("player"))
			or (UnitHasVehicleUI and UnitHasVehicleUI("player"))
		) then
			return true;
		end
		for index = 1, 40, 1 do
			local auraName, rank, icon, count, debuffType, duration,
				expirationTime, unitCaster, isStealable,
				shouldConsolidate, spellId = UnitBuff("player", index);
			if (not auraName) then
				break
			end
			if (
				spellId == 70311
				or UnBotSpecSummonNormalize(auraName)
					== "mutated transformation"
				or UnBotSpecSummonNormalize(auraName)
					== "мутировавшая трансформация"
			) then
				return true;
			end
		end
		return false;
	end
	if (not state.assistTank) then
		return false;
	end
	local found = false;
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		if (
			not found
			and UnBotSpecSummonNormalize(name)
				== UnBotSpecSummonNormalize(state.assistTank)
		) then
			state.assistUnit = unit;
			if (
				(UnitInVehicle and UnitInVehicle(unit))
				or (UnitHasVehicleUI and UnitHasVehicleUI(unit))
			) then
				found = true;
				return;
			end
			for index = 1, 40, 1 do
				local auraName, rank, icon, count, debuffType, duration,
					expirationTime, unitCaster, isStealable,
					shouldConsolidate, spellId = UnitBuff(unit, index);
				if (not auraName) then
					break
				end
				if (
					spellId == 70311
					or UnBotSpecSummonNormalize(auraName)
						== "mutated transformation"
					or UnBotSpecSummonNormalize(auraName)
						== "мутировавшая трансформация"
				) then
					found = true;
					break
				end
			end
		end
	end);
	return found;
end

function UnBotPutricideConfirmDrink(name)
	local state = UnBotPutricideDrink;
	local expectedName = state.playerPilot and UnitName("player")
		or state.assistTank;
	if (
		not state.active
		or not name
		or UnBotSpecSummonNormalize(name)
			~= UnBotSpecSummonNormalize(expectedName)
	) then
		return false;
	end
	state.confirmed = true;
	state.waitingLos = false;
	state.queryAt = 0;
	if (state.playerPilot) then
		UnBotPutricideSetAssistIcc(true);
		UnBotSpecSummonMessage(
			"|cff33ff66Мерзоцид: игрок стал Мутировавшим поганищем; "
			.."off-tank снова получил icc и вернулся к обычному бою.|r"
		);
	else
		SendChatMessage("co +tank", "WHISPER", nil, state.assistTank);
		UnBotPutricideSetAssistIcc(true);
		UnBotSpecSummonMessage(
			"|cff33ff66Мерзоцид: "..state.assistTank
			.." стал Мутировавшей мерзостью; tank/icc закреплены.|r"
		);
	end
	return true;
end

function UnBotPutricideHandleLosReply(message, sender)
	local state = UnBotPutricideDrink;
	if (
		state.playerPilot
		or
		not state.active
		or not state.waitingLos
		or UnBotSpecSummonNormalize(sender)
			~= UnBotSpecSummonNormalize(state.assistTank)
	) then
		return;
	end
	local normalized = UnBotSpecSummonNormalize(message);
	if (not string.find(normalized, "drink me", 1, true)) then
		return;
	end
	local link = string.match(
		message,
		"(|c%x%x%x%x%x%x%x%x|Hfound:[^|]+|h%[[^%]]+%]|h|r)"
	) or string.match(
		message,
		"(|Hfound:[^|]+|h%[[^%]]+%]|h)"
	);
	SendChatMessage(
		"u "..tostring(link or "1"),
		"WHISPER",
		nil,
		state.assistTank
	);
	state.waitingLos = false;
	state.useSentAt = GetTime();
	state.queryAt = GetTime() + 6.2;
	UnBotSpecSummonMessage(
		"Мерзоцид: команда u Drink Me! отправлена только "
		..state.assistTank.."."
	);
end

function UnBotPutricideResetAttempt()
	local state = UnBotPutricideDrink;
	if (not state.bossOnlyMode and state.playerPilot and state.assistTank) then
		UnBotPutricideSetAssistIcc(false);
	end
	state.active = false;
	state.queryAt = 0;
	state.queryAttempts = 0;
	state.waitingLos = false;
	state.useSentAt = 0;
	state.confirmed = false;
	state.failedThisCombat = false;
	state.normalAnchorLocked = false;
	state.normalAnchorLockAt = 0;
	state.normalAnchorRotationUntil = 0;
	state.normalAnchorNextJudgementAt = 0;
	state.normalAnchorJudgementAttempts = 0;
	state.normalAnchorLastBossSwingAt = 0;
	state.normalAnchorPhaseLocks = 0;
	state.bossFocusAttempts = 0;
	state.bossFocusNextAt = 0;
	state.bossFocusUntil = 0;
end

UnBotPutricideDrinkFrame = UnBotPutricideDrinkFrame
	or CreateFrame("Frame", "UnBotPutricideDrinkFrame");
UnBotPutricideDrinkFrame:RegisterEvent("CHAT_MSG_WHISPER");
UnBotPutricideDrinkFrame:RegisterEvent("COMBAT_LOG_EVENT_UNFILTERED");
UnBotPutricideDrinkFrame:RegisterEvent("PLAYER_REGEN_DISABLED");
UnBotPutricideDrinkFrame:RegisterEvent("PLAYER_REGEN_ENABLED");
UnBotPutricideDrinkFrame:SetScript("OnEvent", function(self, event, ...)
	local state = UnBotPutricideDrink;
	if (event == "CHAT_MSG_WHISPER") then
		UnBotPutricideHandleLosReply(select(1, ...), select(2, ...));
		return;
	end
	if (event == "PLAYER_REGEN_ENABLED") then
		if (state.active and not state.confirmed) then
			UnBotSpecSummonMessage(
				"Мерзоцид: бой закончился до подтверждения трансформации."
			);
		end
		UnBotPutricideResetAttempt();
		return;
	end
	if (event == "PLAYER_REGEN_DISABLED" and state.bossOnlyMode) then
		for _, name in ipairs(state.bossOnlyHealerNames or {}) do
			if (UnBotSpecSummonIsInGroup(name)) then
				SendChatMessage("co -attack force", "WHISPER", nil, name);
				SendChatMessage("co -flee", "WHISPER", nil, name);
				SendChatMessage("stay", "WHISPER", nil, name);
			end
		end
		if (
			UnitExists("target")
			and UnBotPutricideNameMatches(UnitName("target"))
		) then
			state.bossFocusAttempts = 0;
			state.bossFocusNextAt = GetTime();
			state.bossFocusUntil = GetTime() + 2;
			UnBotSpecSummonMessage(
				"Мерзоцид: boss-only pull подтверждён; отправляю мили-ДД прямой attack по текущей цели."
			);
		else
			UnBotSpecSummonMessage(
				"|cffff3333Мерзоцид: boss-only attack не отправлен — при входе в бой босс не был выбран целью.|r"
			);
		end
		return;
	end
	if (
		event == "PLAYER_REGEN_DISABLED"
		and state.normalAnchorMode
		and UnitExists("target")
		and UnBotPutricideNameMatches(UnitName("target"))
	) then
		state.normalAnchorLocked = false;
		state.normalAnchorLockAt = GetTime() + 4;
		for _, name in ipairs(state.normalAnchorNames or {}) do
			if (UnBotSpecSummonIsInGroup(name)) then
				SendChatMessage("co -passive", "WHISPER", nil, name);
				SendChatMessage("co -avoid aoe", "WHISPER", nil, name);
				SendChatMessage("co -icc", "WHISPER", nil, name);
				SendChatMessage("nc -icc", "WHISPER", nil, name);
				SendChatMessage("co -formation", "WHISPER", nil, name);
				SendChatMessage("co -flee", "WHISPER", nil, name);
				SendChatMessage("co -tank aoe", "WHISPER", nil, name);
				SendChatMessage("co -tank assist", "WHISPER", nil, name);
				SendChatMessage("co +tank", "WHISPER", nil, name);
				SendChatMessage("nc -follow", "WHISPER", nil, name);
				SendChatMessage("nc +stay", "WHISPER", nil, name);
				SendChatMessage("stay", "WHISPER", nil, name);
				SendChatMessage("cast Seal of Wisdom", "WHISPER", nil, name);
			end
		end
		UnBotSpecSummonMessage(
			"Мерзоцид 25 обычный: прот-пал получил до 4 секунд на захват босса; после первого мили-удара tank и активная ротация отключатся, но автоатака и мудрость останутся."
		);
	end
	if (not state.armed) then
		return;
	end
	if (event == "PLAYER_REGEN_DISABLED") then
		if (
			UnitExists("target")
			and UnBotPutricideNameMatches(UnitName("target"))
		) then
			UnBotPutricideBeginDrink();
		end
		return;
	end
	local eventType = select(2, ...);
	local sourceName = select(4, ...);
	local destinationName = select(7, ...);
	local spellId = tonumber((select(9, ...)));
	if (
		state.normalAnchorMode
		and UnBotPutricideNameMatches(sourceName)
		and (eventType == "SWING_DAMAGE" or eventType == "SWING_MISSED")
	) then
		for _, name in ipairs(state.normalAnchorNames or {}) do
			if (
				UnBotSpecSummonNormalize(destinationName)
				== UnBotSpecSummonNormalize(name)
			) then
				state.normalAnchorLastBossSwingAt = GetTime();
				if (not state.normalAnchorLocked) then
					UnBotPutricideLockNormalAnchors("первый удар босса по "..name);
				end
				break
			end
		end
	end
	if (
		state.normalAnchorMode
		and state.normalAnchorLocked
		and UnBotPutricideNameMatches(sourceName)
		and eventType == "SPELL_CAST_START"
		and spellId == 71617
		and (state.normalAnchorPhaseLocks or 0) < 2
	) then
		for _, name in ipairs(state.normalAnchorNames or {}) do
			UnBotPutricideApplyNormalAnchorCommands(name);
		end
		state.normalAnchorPhaseLocks = (state.normalAnchorPhaseLocks or 0) + 1;
		state.normalAnchorLastBossSwingAt = 0;
		state.normalAnchorNextJudgementAt = GetTime() + 0.5;
		UnBotSpecSummonMessage(
			"|cff33ff66Мерзоцид 25 обычный: начался фазовый переход — passive + nc stay повторены, Правосудие ждёт возвращения босса в мили.|r"
		);
	end
	if (
		UnBotPutricideNameMatches(sourceName)
		or UnBotPutricideNameMatches(destinationName)
	) then
		UnBotPutricideBeginDrink();
	end
	if (
		eventType == "SPELL_AURA_APPLIED"
		and spellId == 70311
	) then
		local expectedName = state.playerPilot and UnitName("player")
			or state.assistTank;
		if (
			UnBotSpecSummonNormalize(destinationName)
			== UnBotSpecSummonNormalize(expectedName)
		) then
			UnBotPutricideConfirmDrink(destinationName);
		else
			UnBotSpecSummonMessage(
				"|cffff3333Мерзоцид: Drink Me! использовал "
				..tostring(destinationName)
				..", а ожидался "..tostring(expectedName)
				..". Лучше перезапустить попытку.|r"
			);
		end
	end
end);
UnBotPutricideDrinkFrame:SetScript("OnUpdate", function()
	local state = UnBotPutricideDrink;
	local now = GetTime();
	if (
		state.normalAnchorMode
		and not state.normalAnchorLocked
		and (state.normalAnchorLockAt or 0) > 0
		and now >= state.normalAnchorLockAt
	) then
		UnBotPutricideLockNormalAnchors("аварийный таймаут 4 сек");
	end
	if (
		state.normalAnchorMode
		and state.normalAnchorLocked
		and state.active
		and (state.normalAnchorRotationUntil or 0) > 0
		and now >= (state.normalAnchorNextJudgementAt or 0)
	) then
		if (
			now > state.normalAnchorRotationUntil
			or (state.normalAnchorJudgementAttempts or 0) >= 85
		) then
			state.normalAnchorRotationUntil = 0;
			state.normalAnchorNextJudgementAt = 0;
			UnBotSpecSummonMessage(
				"Мерзоцид 25 обычный: конечное 12-минутное окно Правосудия мудрости завершено."
			);
		elseif now - (state.normalAnchorLastBossSwingAt or 0) <= 3.5 then
			for _, name in ipairs(state.normalAnchorNames or {}) do
				if (UnBotSpecSummonIsInGroup(name)) then
					SendChatMessage("cast Judgement of Wisdom", "WHISPER", nil, name);
				end
			end
			state.normalAnchorJudgementAttempts =
				(state.normalAnchorJudgementAttempts or 0) + 1;
			state.normalAnchorNextJudgementAt = now + 8.5;
		else
			-- Не просим дальнее Правосудие, пока босс не бьёт якорь в мили:
			-- серверный cast иначе сам строит маршрут к столу/стене.
			state.normalAnchorNextJudgementAt = now + 0.5;
		end
	end
	if (
		state.bossOnlyMode
		and (state.bossFocusAttempts or 0) < 2
		and now >= (state.bossFocusNextAt or 0)
		and now <= (state.bossFocusUntil or 0)
	) then
		for _, name in ipairs(state.bossOnlyNames or {}) do
			if (UnBotSpecSummonIsInGroup(name)) then
				SendChatMessage("attack", "WHISPER", nil, name);
			end
		end
		state.bossFocusAttempts = (state.bossFocusAttempts or 0) + 1;
		state.bossFocusNextAt = now + 0.6;
		if (state.bossFocusAttempts >= 2) then
			UnBotSpecSummonMessage(
				"Мерзоцид: boss-only фокус отправлен; дальнейших повторов attack не будет."
			);
		end
	end
	if (not state.active or state.confirmed) then
		return;
	end
	if (UnBotPutricideTransformationPresent()) then
		UnBotPutricideConfirmDrink(
			state.playerPilot and UnitName("player") or state.assistTank
		);
		return;
	end
	if (state.playerPilot) then
		return;
	end
	if (now < (state.queryAt or 0)) then
		return;
	end
	if ((state.queryAttempts or 0) >= 3) then
		state.active = false;
		state.failedThisCombat = true;
		UnBotSpecSummonMessage(
			"|cffff3333Мерзоцид: "..tostring(state.assistTank)
			.." не превратился после трёх попыток. Не рассылайте u 1 в рейд; "
			.."перезапустите бой или используйте Drink Me! шёпотом этому DK.|r"
		);
		return;
	end
	state.queryAttempts = (state.queryAttempts or 0) + 1;
	state.waitingLos = true;
	state.queryAt = now + 2.5;
	SendChatMessage("los gos", "WHISPER", nil, state.assistTank);
	UnBotSpecSummonMessage(
		"Мерзоцид: "..state.assistTank.." — поиск Drink Me! "
		..tostring(state.queryAttempts).."/3."
	);
end);

function UnBotSindragosaIsHeroic25()
	local _, instanceType, difficultyIndex = GetInstanceInfo();
	return instanceType == "raid" and tonumber(difficultyIndex) == 4;
end

function UnBotSindragosaIsNormal25()
	local _, instanceType, difficultyIndex = GetInstanceInfo();
	return instanceType == "raid" and tonumber(difficultyIndex) == 2;
end

function UnBotSindragosaHeroicBombHiding()
	return (
		UnBotSindragosaPrep.heroicBombActive
		and UnBotSindragosaPrep.heroicBombPhase == "hide"
	) and true or false;
end

function UnBotSindragosaEnableHeroicSingleTarget()
	if (
		not UnBotSindragosaIsHeroic25()
		or UnBotSindragosaPrep.heroicSingleTargetActive
	) then
		return;
	end
	UnBotSindragosaBroadcast("@dps co -aoe,-dps aoe");
	UnBotSindragosaBroadcast("@tank co -aoe,-tank aoe");
	UnBotSindragosaPrep.heroicSingleTargetActive = true;
	UnBotSpecSummonMessage(
		"Синдрагоса 25H: на воздушную фазу AoE отключено — весь урон идёт в одну RTI-глыбу."
	);
end

function UnBotSindragosaRestoreHeroicSingleTarget()
	if (not UnBotSindragosaPrep.heroicSingleTargetActive) then
		return;
	end
	UnBotSindragosaBroadcast("@dps co +dps aoe,+aoe");
	UnBotSindragosaBroadcast("@tank co +tank aoe,+aoe");
	UnBotSindragosaPrep.heroicSingleTargetActive = false;
end

function UnBotSindragosaStartHeroicBombCycle()
	if (not UnBotSindragosaIsHeroic25()) then
		return false;
	end
	if (UnBotSindragosaPrep.heroicBombActive) then
		if (UnBotSindragosaHeroicBombHiding()) then
			UnBotSindragosaBroadcast("co +icc");
			UnBotSindragosaBroadcast("nc +icc");
			UnBotSindragosaBroadcast("@warlock pet follow");
		end
		return true;
	end
	local now = GetTime();
	UnBotSindragosaEnableHeroicSingleTarget();
	UnBotSindragosaPrep.heroicBombActive = true;
	UnBotSindragosaPrep.heroicBombPhase = "hide";
	UnBotSindragosaPrep.heroicBombNextAt = now + 0.5;
	UnBotSindragosaPrep.heroicBombFirstWindow = true;
	UnBotSindragosaPrep.heroicBombStartedAt = now;
	UnBotSindragosaPrep.heroicBombFocusLocked = false;
	UnBotSindragosaPrep.frostBombCount = 0;
	UnBotSindragosaPrep.lastFrostBombAt = 0;
	UnBotSindragosaPrep.pendingTombAttackAt = nil;
	UnBotSindragosaPrep.tombAttackRepeatAt = 0;
	UnBotSindragosaPrep.tombAttackTargetSent = false;
	UnBotSindragosaPrep.tombAttackAttempts = 0;
	UnBotSindragosaBroadcast("co +icc");
	UnBotSindragosaBroadcast("nc +icc");
	UnBotSindragosaBroadcast("@warlock pet follow");
	UnBotSpecSummonMessage(
		"Синдрагоса 25H: глыбы сформированы — ICC включена всему рейду; "
		.."через 0,5 сек начнётся RTI-фокус до первой бомбы."
	);
	return true;
end

function UnBotSindragosaEnterHeroicBombAttackWindow(now)
	if (not UnBotSindragosaPrep.heroicBombActive) then
		return;
	end
	now = now or GetTime();
	local firstWindow = UnBotSindragosaPrep.heroicBombFirstWindow and true or false;
	UnBotSindragosaPrep.heroicBombPhase = "attack";
	UnBotSindragosaPrep.heroicBombNextAt = now + (firstWindow and 2.5 or 2);
	UnBotSindragosaPrep.heroicBombFirstWindow = false;
	UnBotSindragosaBroadcast("@dps co -icc");
	UnBotSindragosaBroadcast("@dps nc -icc");
	UnBotSindragosaBroadcast("@tank co -icc");
	UnBotSindragosaBroadcast("@tank nc -icc");
	UnBotSindragosaBroadcast("@heal co +icc");
	UnBotSindragosaBroadcast("@heal nc +icc");
	UnBotSindragosaMarkVisibleTombs();
	local icon = UnBotSindragosaPrep.tombAttackIcon
		or UnBotSindragosaNextTombIcon();
	UnBotSindragosaPrep.pendingTombAttackAt = nil;
	UnBotSindragosaPrep.tombAttackRepeatAt = 0;
	UnBotSindragosaPrep.tombAttackTargetSent = false;
	UnBotSindragosaPrep.tombAttackAttempts = 0;
	if (icon) then
		UnBotSindragosaPrep.tombAttackIcon = icon;
		UnBotSindragosaPrep.pendingTombAttackAt = now + (firstWindow and 0 or 0.15);
	end
	UnBotSindragosaPrep.heroicBombFocusLocked = icon and true or false;
	if (firstWindow) then
		UnBotSpecSummonMessage(
			"Синдрагоса 25H: прошло 0,5 сек после формирования глыб — "
			.."RTI-фокус ДД и танков на 2,5 сек: одна метка, атака через 0,3 сек "
			.."и ограниченный повтор; хилы сохраняют ICC. "
			.."Затем ICC включится всему рейду примерно за 2,2 сек до первой бомбы."
		);
	else
		UnBotSpecSummonMessage(
			"Синдрагоса 25H: бомба "
			..tostring(math.max(1, tonumber(UnBotSindragosaPrep.frostBombCount) or 0))
			.." прошла — двухсекундный RTI-фокус ДД и танков с раздельными "
			.."командами метки и атаки; хилы сохраняют ICC; цель — "
			..(icon and ("глыбы "..icon) or "обнаруженной глыбы").."."
		);
	end
end

function UnBotSindragosaEnterHeroicBombHideWindow(now)
	if (not UnBotSindragosaPrep.heroicBombActive) then
		return;
	end
	now = now or GetTime();
	UnBotSindragosaPrep.heroicBombPhase = "hide";
	UnBotSindragosaPrep.heroicBombNextAt = now + 4.2;
	UnBotSindragosaPrep.pendingTombAttackAt = nil;
	UnBotSindragosaPrep.tombAttackRepeatAt = 0;
	UnBotSindragosaPrep.tombAttackTargetSent = false;
	UnBotSindragosaBroadcast("co +icc");
	UnBotSindragosaBroadcast("nc +icc");
	UnBotSindragosaBroadcast("@warlock pet follow");
	UnBotSpecSummonMessage(
		"Синдрагоса 25H: укрытие — RTI остановлен, питомцы отозваны, ICC включена."
	);
end

function UnBotSindragosaRecordHeroicBomb(now)
	if (not UnBotSindragosaPrep.heroicBombActive) then
		return;
	end
	now = now or GetTime();
	if (now < (tonumber(UnBotSindragosaPrep.lastFrostBombAt) or 0) + 1) then
		return;
	end
	UnBotSindragosaPrep.lastFrostBombAt = now;
	UnBotSindragosaPrep.frostBombCount =
		(tonumber(UnBotSindragosaPrep.frostBombCount) or 0) + 1;
	UnBotSindragosaEnterHeroicBombAttackWindow(now);
end

function UnBotSindragosaStopHeroicBombCycle(reason)
	if (not UnBotSindragosaPrep.heroicBombActive) then
		return;
	end
	UnBotSindragosaPrep.heroicBombActive = false;
	UnBotSindragosaPrep.heroicBombPhase = nil;
	UnBotSindragosaPrep.heroicBombNextAt = nil;
	UnBotSindragosaPrep.heroicBombFirstWindow = false;
	UnBotSindragosaPrep.heroicBombStartedAt = nil;
	UnBotSindragosaPrep.heroicBombFocusLocked = false;
	UnBotSindragosaPrep.frostBombCount = 0;
	UnBotSindragosaPrep.lastFrostBombAt = 0;
	UnBotSindragosaPrep.tombAttackIcon = nil;
	UnBotSindragosaPrep.pendingTombAttackAt = nil;
	UnBotSindragosaPrep.tombAttackRepeatAt = 0;
	UnBotSindragosaPrep.tombAttackTargetSent = false;
	UnBotSindragosaPrep.tombAttackAttempts = 0;
	UnBotSindragosaPrep.nonTankIccEnabled = false;
	UnBotSindragosaPrep.disableNonTankIccAt = nil;
	UnBotSindragosaPrep.postTombIccUntil = nil;
	UnBotSindragosaPrep.beaconBots = {};
	UnBotSindragosaBroadcast("co -icc");
	UnBotSindragosaBroadcast("nc -icc");
	UnBotSpecSummonMessage(
		"Синдрагоса 25H: цикл бомб остановлен; ICC снова отключена"
		..(reason and (" — "..reason) or "").."."
	);
end

function UnBotSindragosaUpdateHeroicBombCycle(now)
	if (not UnBotSindragosaPrep.heroicBombActive) then
		return;
	end
	now = now or GetTime();
	if (
		UnBotSindragosaPrep.heroicBombStartedAt
		and now >= UnBotSindragosaPrep.heroicBombStartedAt + 75
	) then
		UnBotSindragosaStopHeroicBombCycle("защитный таймаут воздушной фазы");
		return;
	end
	if (now < (UnBotSindragosaPrep.heroicBombNextAt or 0)) then
		return;
	end
	if (UnBotSindragosaHeroicBombHiding()) then
		UnBotSindragosaPrep.lastFrostBombAt = now;
		UnBotSindragosaPrep.frostBombCount =
			(tonumber(UnBotSindragosaPrep.frostBombCount) or 0) + 1;
		UnBotSindragosaEnterHeroicBombAttackWindow(now);
	else
		UnBotSindragosaEnterHeroicBombHideWindow(now);
	end
end

function UnBotSindragosaTombAttackMaxAttempts()
	return UnBotSindragosaIsHeroic25() and 10 or 6;
end

function UnBotSindragosaSuppressIcc()
	if (UnBotSindragosaPrep.iccSuppressed) then
		return;
	end
	if (not UnBotSindragosaBroadcast("co -icc")) then
		return;
