	UnBotSindragosaBroadcast("nc -icc");
	UnBotSindragosaPrep.iccSuppressed = true;
	UnBotSindragosaPrep.iccSuppressedAt = GetTime();
	UnBotSindragosaPrep.frostBombCount = 0;
	UnBotSindragosaPrep.lastFrostBombAt = 0;
	UnBotSindragosaPrep.restoreIccAt = nil;
	UnBotSindragosaPrep.nextIccEnforceAt = GetTime() + 12;
	UnBotSindragosaPrep.nextBeaconScanAt = 0;
	UnBotSindragosaPrep.beaconBots = {};
	UnBotSindragosaPrep.nonTankIccEnabled = false;
	UnBotSindragosaPrep.disableNonTankIccAt = nil;
	UnBotSindragosaPrep.tombAttackIcon = nil;
	UnBotSindragosaPrep.tombAttackRepeatAt = 0;
	UnBotSindragosaPrep.tombDeaths = 0;
	UnBotSindragosaPrep.cycleBeaconCount = 0;
	UnBotSindragosaPrep.cycleBeaconNames = {};
	UnBotSindragosaPrep.cycleBeaconInfo = {};
	UnBotSindragosaPrep.priorityHealerName = nil;
	UnBotSindragosaPrep.priorityTombIcon = nil;
	UnBotSindragosaPrep.postTombIccUntil = nil;
	UnBotSindragosaPrep.tombAttackQueue = {};
	UnBotSindragosaPrep.tombGuids = {};
	UnBotSindragosaPrep.tombCycle = {};
	UnBotSindragosaPrep.tombMarkedCount = 0;
	UnBotSindragosaPrep.pendingTombAttackAt = nil;
	UnBotSindragosaPrep.tombAttackTargetSent = false;
	UnBotSindragosaPrep.tombAttackAttempts = 0;
	UnBotSindragosaPrep.playerTombRescue = false;
	UnBotSindragosaPrep.phaseThreeBeaconBots = {};
	UnBotSindragosaPrep.phaseThreeTombFocusActive = false;
	UnBotSindragosaPrep.phaseThreeTombVictim = nil;
	UnBotSindragosaPrep.phaseThreeTombVictims = {};
	UnBotSindragosaPrep.phaseThreeDiscoveryAt = nil;
	UnBotSindragosaPrep.phaseThreeDiscoveryAttempts = 0;
	UnBotSindragosaPrep.phaseThreeBossReturnAt = nil;
	UnBotSindragosaPrep.phaseThreeBossAttackAt = nil;
	UnBotSindragosaPrep.phaseThreeBossReturnAttempts = 0;
	UnBotSindragosaPrep.directTombAttackGuid = nil;
	UnBotSindragosaPrep.directTombAttackAt = nil;
	UnBotSindragosaPrep.directTombAttackAttempts = 0;
	UnBotSindragosaPrep.bubbleCheckAt = nil;
	UnBotSindragosaPrep.bubbleCheckUntil = nil;
	UnBotSindragosaPrep.bubbleWarningCount = 0;
	UnBotSindragosaPrep.airPositionLockPending = false;
	UnBotSindragosaPrep.airPositionLockAt = nil;
	UnBotSindragosaPrep.airPositionLocked = false;
	UnBotSindragosaPrep.airPositionLockUntil = nil;
	UnBotSindragosaPrep.nextAirPositionLockEnforceAt = 0;
	UnBotSindragosaPrep.airWarningAt = nil;
	UnBotSindragosaPrep.groundTankRegroupPending = false;
	UnBotSindragosaPrep.heroicBombActive = false;
	UnBotSindragosaPrep.heroicBombPhase = nil;
	UnBotSindragosaPrep.heroicBombNextAt = nil;
	UnBotSindragosaPrep.heroicBombFirstWindow = false;
	UnBotSindragosaPrep.heroicBombStartedAt = nil;
	UnBotSindragosaPrep.heroicBombFocusLocked = false;
	UnBotSindragosaPrep.heroicSingleTargetActive = false;
	UnBotSindragosaPrep.unchainedBots = {};
	UnBotSindragosaPrep.nextUnchainedEnforceAt = 0;
	UnBotSpecSummonMessage(
		"Синдрагоса: ICC отключена у рейда; при Ледяной метке она включится "
		.."персонально только подтверждённым носителям."
	);
end

function UnBotSindragosaWhisperIcc(name, enabled)
	if (not name or name == "" or name == UnitName("player")) then
		return false;
	end
	local operation = enabled and "+icc" or "-icc";
	SendChatMessage("co "..operation, "WHISPER", nil, name);
	SendChatMessage("nc "..operation, "WHISPER", nil, name);
	return true;
end

function UnBotSindragosaUsePhaseThreeBeaconSeparation()
	return (
		UnBotSindragosaIsNormal25()
		or UnBotSindragosaIsHeroic25()
	) and UnBotSindragosaIsPhaseThree();
end

function UnBotSindragosaSetPhaseThreeBeaconBot(name, enabled)
	if (not name or name == "" or name == UnitName("player")) then
		return false;
	end
	UnBotSindragosaPrep.phaseThreeBeaconBots =
		UnBotSindragosaPrep.phaseThreeBeaconBots or {};
	local wasEnabled = UnBotSindragosaPrep.phaseThreeBeaconBots[name] and true or false;
	if (enabled) then
		UnBotSindragosaPrep.phaseThreeBeaconBots[name] = true;
		SendChatMessage("co -icc,+move from group", "WHISPER", nil, name);
		SendChatMessage("nc -icc,+move from group", "WHISPER", nil, name);
		SendChatMessage("disperse set 24", "WHISPER", nil, name);
		SendChatMessage("move from group", "WHISPER", nil, name);
		UnBotRegistryAttachStorage();
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (UnBotSpecSummonNormalize(profile and profile.className) == "warlock") then
			SendChatMessage("pet follow", "WHISPER", nil, name);
		end
		if (not wasEnabled) then
			UnBotSpecSummonMessage(
				"Синдрагоса, фаза 3: "..name
				.." получил метку — ICC выключена, move from group отводит его "
				.."от рейда минимум на 24 м; summon запрещён."
			);
		end
	else
		UnBotSindragosaPrep.phaseThreeBeaconBots[name] = nil;
		SendChatMessage("disperse disable", "WHISPER", nil, name);
		SendChatMessage("co -move from group", "WHISPER", nil, name);
		SendChatMessage("nc -move from group", "WHISPER", nil, name);
		SendChatMessage("follow", "WHISPER", nil, name);
	end
	return true;
end

function UnBotSindragosaRestorePhaseThreeBeaconBots()
	for name in pairs(UnBotSindragosaPrep.phaseThreeBeaconBots or {}) do
		if (UnBotSpecSummonIsInGroup(name)) then
			SendChatMessage("disperse disable", "WHISPER", nil, name);
			SendChatMessage("co -move from group", "WHISPER", nil, name);
			SendChatMessage("nc -move from group", "WHISPER", nil, name);
			SendChatMessage("follow", "WHISPER", nil, name);
		end
	end
	UnBotSindragosaPrep.phaseThreeBeaconBots = {};
end

function UnBotSindragosaShowPhaseThreePlayerBeaconWarning()
	local text = "ГЛЫБА НА ТЕБЕ — ОТОЙДИ ОТ РЕЙДА!";
	if (RaidNotice_AddMessage and RaidWarningFrame) then
		RaidNotice_AddMessage(
			RaidWarningFrame,
			text,
			ChatTypeInfo and ChatTypeInfo["RAID_WARNING"]
		);
	elseif (UIErrorsFrame) then
		UIErrorsFrame:AddMessage(text, 1, 0.15, 0.15, 1);
	end
	if (PlaySound) then
		PlaySound("RaidWarning");
	end
end

function UnBotSindragosaPrepareAirSpread(reason, force)
	if (UnBotSindragosaPrep.spreadPrepared and not force) then
		return;
	end
	if (UnBotSindragosaIsHeroic25()) then
		if (not UnBotSindragosaBroadcast("co +icc")) then
			return;
		end
		UnBotSindragosaBroadcast("nc +icc");
		UnBotSindragosaPrep.spreadPrepared = true;
		UnBotSpecSummonMessage(
			"Синдрагоса 25H: ICC включена всему рейду после телепорта; "
			.."штатная стратегия разводит носителей меток и остальных"
			..(reason and (" — "..reason) or "").."."
		);
		return;
	end
	local distance = UnBotSindragosaIsHeroic25() and 28 or 20;
	if (not UnBotSindragosaBroadcast("disperse set "..tostring(distance))) then
		return;
	end
	UnBotSindragosaBroadcast("follow");
	UnBotSindragosaPrep.spreadPrepared = true;
	UnBotSpecSummonMessage(
		"Синдрагоса: принудительный follow + разведение всего рейда на "
		..tostring(distance).." м"
		..(reason and (" — "..reason) or "").."."
	);
end

function UnBotSindragosaLockAirPositions(now)
	if (
		not UnBotSindragosaIsNormal25()
		or UnBotSindragosaPrep.airPositionLocked
	) then
		return;
	end
	now = now or GetTime();
	UnBotSindragosaBroadcast("co +passive");
	UnBotSindragosaBroadcast("@warlock pet follow");
	UnBotSindragosaPrep.airPositionLockPending = false;
	UnBotSindragosaPrep.airPositionLockAt = nil;
	UnBotSindragosaPrep.airPositionLocked = true;
	UnBotSindragosaPrep.nextAirPositionLockEnforceAt = now + 1.5;
	UnBotSpecSummonMessage(
		"Синдрагоса 25N: разбег завершён — позиции зафиксированы passive до появления глыб."
	);
end

function UnBotSindragosaReleaseAirPositions(reason)
	if (
		not UnBotSindragosaPrep.airPositionLocked
		and not UnBotSindragosaPrep.airPositionLockPending
	) then
		return;
	end
	if (UnBotSindragosaPrep.airPositionLocked) then
		UnBotSindragosaBroadcast("co -passive");
	end
	UnBotSindragosaPrep.airPositionLockPending = false;
	UnBotSindragosaPrep.airPositionLockAt = nil;
	UnBotSindragosaPrep.airPositionLocked = false;
	UnBotSindragosaPrep.airPositionLockUntil = nil;
	UnBotSindragosaPrep.nextAirPositionLockEnforceAt = 0;
	if (next(UnBotSindragosaPrep.unchainedBots or {})) then
		UnBotSindragosaPrep.nextUnchainedEnforceAt = 0;
		UnBotSindragosaEnforceUnchainedMagic(GetTime());
	end
	UnBotSpecSummonMessage(
		"Синдрагоса 25N: фиксация позиций снята"
		..(reason and (" — "..reason) or "").."."
	);
end

function UnBotSindragosaBeginAirGather(reason)
	if (
		UnBotSindragosaPrep.spreadPrepared
		or UnBotSindragosaPrep.airGatherPending
	) then
		return;
	end
	if (UnBotSindragosaIsNormal25()) then
		local now = GetTime();
		UnBotSindragosaPrepareAirSpread(
			"25N: начало воздушной фазы без summon к игроку",
			true
		);
		UnBotSindragosaPrep.airPositionLockPending = true;
		UnBotSindragosaPrep.airPositionLockAt = now + 2.5;
		UnBotSindragosaPrep.airPositionLockUntil = now + 10.5;
		UnBotSpecSummonMessage(
			"Синдрагоса 25N: общий summon отключён; через 2,5 сек позиции будут зафиксированы."
		);
		return;
	else
		if (not UnBotSindragosaBroadcast("summon")) then
			return;
		end
	end
	UnBotSindragosaPrep.airGatherPending = true;
	UnBotSindragosaPrep.airSpreadAt = GetTime() + 0.8;
	if (UnBotSindragosaIsHeroic25()) then
		UnBotSpecSummonMessage(
			"Синдрагоса 25H: воздушная фаза — общий summon к игроку на балконе; "
			.."через 0,8 сек ICC включится всему рейду"
			..(reason and (" — "..reason) or "").."."
		);
	else
		UnBotSpecSummonMessage(
			"Синдрагоса: воздушная фаза — один общий summon к игроку; "
			.."через 0,8 сек начнётся разведение на 20 м"
			..(reason and (" — "..reason) or "").."."
		);
	end
end

function UnBotSindragosaShowAirWarning()
	local _, classToken = UnitClass("player");
	local text = classToken == "PALADIN"
		and "СКОРО ВЗЛЁТ — БЕГИ НА БАЛКОН И ГОТОВЬ БАБЛ!"
		or "СКОРО ВОЗДУШНАЯ ФАЗА — БЕГИ К СЕРЕДИНЕ БАЛКОНА!";
	if (RaidNotice_AddMessage and RaidWarningFrame) then
		RaidNotice_AddMessage(
			RaidWarningFrame,
			text,
			ChatTypeInfo and ChatTypeInfo["RAID_WARNING"]
		);
	elseif (UIErrorsFrame) then
		UIErrorsFrame:AddMessage(text, 1, 0.15, 0.15, 1);
	end
	if (PlaySound) then
		PlaySound("RaidWarning");
	end
	UnBotSpecSummonMessage(
		"Синдрагоса: примерно через 8 сек воздушная фаза — беги к середине балкона; "
		.."на начале каста к тебе телепортируется весь рейд."
		..(classToken == "PALADIN" and " Паладин: приготовь Божественный щит." or "")
	);
end

function UnBotSindragosaUnitHasDivineShield(unit)
	if (not unit or not UnitExists(unit)) then
		return false;
	end
	for index = 1, 40, 1 do
		local auraName, rank, icon, count, debuffType, duration,
			expirationTime, unitCaster, isStealable, shouldConsolidate,
			spellId = UnitBuff(unit, index);
		if (not auraName) then
			break
		end
		if (tonumber(spellId) == 642) then
			return true;
		end
	end
	return false;
end

function UnBotSindragosaPlayerHasDivineShield()
	return UnBotSindragosaUnitHasDivineShield("player");
end

function UnBotSindragosaShowCenterAirAlert(customText)
	local state = UnBotSindragosaPrep;
	if (not state.bubbleCenterFrame) then
		local frame = CreateFrame("Frame", nil, UIParent);
		frame:SetAllPoints(UIParent);
		frame:SetFrameStrata("DIALOG");
		frame:SetFrameLevel(100);
		local fontString = frame:CreateFontString(nil, "OVERLAY");
		fontString:SetPoint("CENTER", UIParent, "CENTER", 0, 0);
		fontString:SetJustifyH("CENTER");
		fontString:SetJustifyV("MIDDLE");
		fontString:SetTextColor(1, 0.05, 0.05, 1);
		fontString:SetShadowColor(0, 0, 0, 1);
		fontString:SetShadowOffset(3, -3);
		if (GameFontNormalHuge) then
			fontString:SetFontObject(GameFontNormalHuge);
		end
		local fontPath = STANDARD_TEXT_FONT;
		if (not fontPath and fontString.GetFont) then
			fontPath = fontString:GetFont();
		end
		if (fontPath) then
			fontString:SetFont(fontPath, 120, "THICKOUTLINE");
		end
		frame.alertText = fontString;
		state.bubbleCenterFrame = frame;
	end
	local _, classToken = UnitClass("player");
	if (customText) then
		state.bubbleCenterFrame.alertText:SetText(customText);
	elseif (classToken == "PALADIN") then
		state.bubbleCenterFrame.alertText:SetText(
			"ВОЗДУШНАЯ ФАЗА!\nБАБЛ СЕЙЧАС!"
		);
	else
		state.bubbleCenterFrame.alertText:SetText(
			"ВОЗДУШНАЯ ФАЗА!\nИММУНИТЕТ / ЗАЩИТА СЕЙЧАС!"
		);
	end
	state.bubbleCenterFrame:Show();
	state.bubbleCenterHideAt = GetTime() + 4.2;
	if (PlaySound) then
		PlaySound("RaidWarning");
	end
end

function UnBotSindragosaShowBubbleNowWarning()
	local _, classToken = UnitClass("player");
	if (UnBotSindragosaPlayerHasDivineShield()) then
		UnBotSindragosaShowCenterAirAlert(
			"ВОЗДУШНАЯ ФАЗА!\nБАБЛ ИГРОКА АКТИВЕН"
		);
		UnBotSindragosaPrep.bubbleCheckAt = nil;
		UnBotSindragosaPrep.bubbleCheckUntil = nil;
		UnBotSindragosaPrep.bubbleWarningCount = 0;
		UnBotSpecSummonMessage(
			"Синдрагоса: воздушная фаза началась — Божественный щит уже активен."
		);
		return;
	end
	if (UnBotSindragosaStartBubbleReserve()) then
		UnBotSindragosaShowCenterAirAlert(
			"ВОЗДУШНАЯ ФАЗА!\nРЕЗЕРВНЫЙ РЕТРИК: БАБЛ"
		);
		UnBotSindragosaPrep.bubbleCheckAt = nil;
		UnBotSindragosaPrep.bubbleCheckUntil = nil;
		UnBotSindragosaPrep.bubbleWarningCount = 0;
		return;
	end
	UnBotSindragosaShowCenterAirAlert();
	local text = classToken == "PALADIN"
		and "БАБЛ СЕЙЧАС — НАЧАЛАСЬ ВОЗДУШНАЯ ФАЗА!"
		or "ИММУНИТЕТ / ЗАЩИТА СЕЙЧАС — НАЧАЛАСЬ ВОЗДУШНАЯ ФАЗА!";
	if (RaidNotice_AddMessage and RaidWarningFrame) then
		RaidNotice_AddMessage(
			RaidWarningFrame,
			text,
			ChatTypeInfo and ChatTypeInfo["RAID_WARNING"]
		);
	elseif (UIErrorsFrame) then
		UIErrorsFrame:AddMessage(text, 1, 0.15, 0.15, 1);
	end
	if (classToken ~= "PALADIN") then
		UnBotSindragosaPrep.bubbleCheckAt = nil;
		UnBotSindragosaPrep.bubbleCheckUntil = nil;
		UnBotSindragosaPrep.bubbleWarningCount = 0;
		UnBotSpecSummonMessage(
			"Синдрагоса: используй иммунитет или сильную защиту сейчас. Аддон не может сам применить способность в бою."
		);
		return;
	end
	UnBotSindragosaPrep.bubbleCheckAt = GetTime() + 0.8;
	UnBotSindragosaPrep.bubbleCheckUntil = GetTime() + 3.2;
	UnBotSindragosaPrep.bubbleWarningCount = 1;
	UnBotSpecSummonMessage(
		classToken == "PALADIN"
		and "Синдрагоса: нажми Божественный щит сейчас. Аддон не может сам применить способность в бою."
		or "Синдрагоса: используй иммунитет или сильную защиту сейчас. Аддон не может сам применить способность в бою."
	);
end

function UnBotSindragosaRegroupTanksAfterAir()
	if (not UnBotSindragosaPrep.groundTankRegroupPending) then
		return;
	end
	UnBotSindragosaPrep.groundTankRegroupPending = false;
	if (UnBotSindragosaBroadcast("@tank summon")) then
		UnBotSpecSummonMessage(
			"Синдрагоса: первый удар после приземления — танки один раз "
			.."возвращены к игроку; ДД продолжают очередь глыб."
		);
	end
end

function UnBotSindragosaEnableNonTankIcc()
	if (UnBotSindragosaPrep.nonTankIccEnabled) then
		UnBotSindragosaPrep.disableNonTankIccAt = nil;
		return;
	end
	UnBotSindragosaPrep.nonTankIccEnabled = true;
	UnBotSindragosaPrep.disableNonTankIccAt = nil;
	UnBotSindragosaPrep.tombAttackIcon = nil;
	UnBotSindragosaPrep.tombAttackRepeatAt = 0;
	UnBotSindragosaPrep.tombDeaths = 0;
	UnBotSindragosaPrep.cycleBeaconCount = 0;
	UnBotSindragosaPrep.cycleBeaconNames = {};
	UnBotSindragosaPrep.cycleBeaconInfo = {};
	UnBotSindragosaPrep.priorityHealerName = nil;
	UnBotSindragosaPrep.priorityTombIcon = nil;
	UnBotSindragosaPrep.postTombIccUntil = nil;
	UnBotSindragosaPrep.tombAttackQueue = {};
	UnBotSindragosaPrep.tombGuids = {};
	UnBotSindragosaPrep.tombCycle = {};
	UnBotSindragosaPrep.tombMarkedCount = 0;
	UnBotSindragosaPrep.pendingTombAttackAt = nil;
	UnBotSindragosaPrep.tombAttackTargetSent = false;
	UnBotSindragosaPrep.tombAttackAttempts = 0;
	if (UnBotSindragosaUsePhaseThreeBeaconSeparation()) then
		UnBotSpecSummonMessage(
			"Синдрагоса, фаза 3: метка — общий follow/disperse не отправляется; "
			.."отводится только носитель."
		);
	else
		UnBotSindragosaPrepareAirSpread("Ледяная метка, повтор команды", true);
		if (UnBotSindragosaIsHeroic25()) then
			UnBotSpecSummonMessage(
				"Синдрагоса 25H: Ледяная метка — ICC остаётся включена всему рейду; "
				.."она разводит носителей и ботов без меток."
			);
		else
			UnBotSpecSummonMessage(
				"Синдрагоса: Ледяная метка — ICC включается только персонально носителям; "
				.."весь рейд сохраняет разрыв 20 м."
			);
		end
	end
end

function UnBotSindragosaNameIsHealer(name)
	UnBotRegistryAttachStorage();
	local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	local className = UnBotSpecSummonNormalize(profile and profile.className);
	local specName = UnBotSpecSummonNormalize(profile and profile.specName);
	return (
		(className == "paladin" and specName == "holy")
		or (
			className == "priest"
			and (specName == "holy" or specName == "disc" or specName == "discipline")
		)
		or (
			(className == "druid" or className == "shaman")
			and (specName == "resto" or specName == "restoration")
		)
	) and true or false;
end

function UnBotSindragosaShowUnchainedWarning(enabled)
	local text = enabled
		and "ОСВОБОЖДЕННАЯ МАГИЯ — КАСТУЙ С ПАУЗАМИ!"
		or "ОСВОБОЖДЕННАЯ МАГИЯ СНЯТА — МОЖНО КАСТОВАТЬ";
	if (RaidNotice_AddMessage and RaidWarningFrame) then
		RaidNotice_AddMessage(
			RaidWarningFrame,
			text,
			ChatTypeInfo and ChatTypeInfo["RAID_WARNING"]
		);
	elseif (UIErrorsFrame) then
		UIErrorsFrame:AddMessage(text, enabled and 1 or 0.2, enabled and 0.15 or 1, 0.15, 1);
	end
	if (enabled and PlaySound) then
		PlaySound("RaidWarning");
	end
end

function UnBotSindragosaSetUnchainedMagic(name, enabled)
	if (not name or name == "" or not UnBotSindragosaIsHeroic25()) then
		return;
	end
	if (name == UnitName("player")) then
		UnBotSindragosaShowUnchainedWarning(enabled);
		return;
	end
	UnBotSindragosaPrep.unchainedBots = UnBotSindragosaPrep.unchainedBots or {};
	local state = UnBotSindragosaPrep.unchainedBots[name];
	if (type(state) ~= "table") then
		state = {
			unchained = false,
			unstable = false,
			stacks = 0,
			paused = false,
			announcedPause = false,
			lastPauseAt = 0,
		};
	end
	if (enabled) then
		if (state.unchained) then
			return;
		end
		state.unchained = true;
		state.announcedPause = false;
		UnBotSindragosaPrep.unchainedBots[name] = state;
		UnBotSindragosaPrep.nextUnchainedEnforceAt = 0;
		UnBotSpecSummonMessage(
			"Синдрагоса 25H: "..name
			.." получил Освобождённую магию — разрешаю до "
			..tostring(UnBotSindragosaPrep.unchainedPauseStacks or 4)
			.." зарядов Неустойчивости."
		);
	else
		if (not UnBotSindragosaPrep.unchainedBots[name]) then
			return;
		end
		state.unchained = false;
		UnBotSindragosaPrep.unchainedBots[name] = state;
		if (not state.unstable) then
			if (state.paused and UnBotSpecSummonIsInGroup(name)) then
				SendChatMessage("co +heal", "WHISPER", nil, name);
			end
			UnBotSindragosaPrep.unchainedBots[name] = nil;
			UnBotSpecSummonMessage(
				"Синдрагоса 25H: Освобождённая магия снята с "..name
				.." — обычное лечение восстановлено."
			);
		end
		UnBotSindragosaPrep.nextUnchainedEnforceAt = 0;
	end
end

function UnBotSindragosaSetInstability(name, enabled, stackCount)
	if (not name or name == "" or not UnBotSindragosaIsHeroic25()) then
		return;
	end
	if (name == UnitName("player")) then
		return;
	end
	UnBotSindragosaPrep.unchainedBots = UnBotSindragosaPrep.unchainedBots or {};
	local state = UnBotSindragosaPrep.unchainedBots[name];
	if (type(state) ~= "table") then
		if (not enabled) then
			return;
		end
		state = {
			unchained = true,
			unstable = false,
			stacks = 0,
			paused = false,
			announcedPause = false,
			lastPauseAt = 0,
		};
		UnBotSindragosaPrep.unchainedBots[name] = state;
	end
	if (enabled) then
		state.unstable = true;
		state.stacks = math.max(
			tonumber(state.stacks) or 0,
			tonumber(stackCount) or 1
		);
		local pauseAt = tonumber(UnBotSindragosaPrep.unchainedPauseStacks) or 4;
		if (state.stacks >= pauseAt and not state.paused) then
			if (UnBotSpecSummonIsInGroup(name)) then
				SendChatMessage("co -heal", "WHISPER", nil, name);
			end
			state.paused = true;
			state.lastPauseAt = GetTime();
			UnBotSindragosaPrep.nextUnchainedEnforceAt = GetTime() + 2;
			if (not state.announcedPause) then
				state.announcedPause = true;
				UnBotSpecSummonMessage(
					"Синдрагоса 25H: "..name.." достиг "
					..tostring(state.stacks)
					.." зарядов Неустойчивости — heal временно отключён; ICC и движение сохранены."
				);
			end
		end
		return;
	end
	state.unstable = false;
	state.stacks = 0;
	if (state.paused and UnBotSpecSummonIsInGroup(name)) then
		SendChatMessage("co +heal", "WHISPER", nil, name);
	end
	state.paused = false;
	state.lastPauseAt = 0;
	if (not state.unchained) then
		UnBotSindragosaPrep.unchainedBots[name] = nil;
		UnBotSpecSummonMessage(
			"Синдрагоса 25H: цикл Неустойчивости завершён у "..name
			.." — обычное лечение восстановлено."
		);
	end
	UnBotSindragosaPrep.nextUnchainedEnforceAt = 0;
end

function UnBotSindragosaEnforceUnchainedMagic(now)
	now = now or GetTime();
	if (now < (UnBotSindragosaPrep.nextUnchainedEnforceAt or 0)) then
		return;
	end
	local active = UnBotSindragosaPrep.unchainedBots or {};
	local pausedFound = false;
	for name, state in pairs(active) do
		if (not UnBotSpecSummonIsInGroup(name)) then
			active[name] = nil;
		elseif (type(state) == "table" and state.paused) then
			SendChatMessage("co -heal", "WHISPER", nil, name);
			state.lastPauseAt = now;
			pausedFound = true;
		end
	end
	UnBotSindragosaPrep.nextUnchainedEnforceAt = now + (pausedFound and 2 or 0.5);
end

function UnBotSindragosaRestoreUnchainedMagic()
	for name, state in pairs(UnBotSindragosaPrep.unchainedBots or {}) do
		if (
			type(state) == "table"
			and state.paused
			and UnBotSpecSummonIsInGroup(name)
		) then
			SendChatMessage("co +heal", "WHISPER", nil, name);
		end
	end
	UnBotSindragosaPrep.unchainedBots = {};
	UnBotSindragosaPrep.nextUnchainedEnforceAt = 0;
end

function UnBotSindragosaActivateHealerDiscovery(name)
	if (not name or name == "") then
		return;
	end
	UnBotSindragosaPrep.tombCycle = UnBotSindragosaPrep.tombCycle or {};
	local cycle = UnBotSindragosaPrep.tombCycle;
	cycle.priorityHealerName = name;
	UnBotSindragosaPrep.priorityHealerName = name;
	UnBotSindragosaPrep.priorityTombIcon = "star";
	local untilTime = GetTime() + 6;
	if (
		not UnBotSindragosaPrep.postTombIccUntil
		or UnBotSindragosaPrep.postTombIccUntil < untilTime
	) then
		UnBotSindragosaPrep.postTombIccUntil = untilTime;
		UnBotSindragosaPrep.disableNonTankIccAt = untilTime;
	end
	if (UnBotSindragosaIsHeroic25()) then
		UnBotSindragosaBroadcast("co +icc");
		UnBotSindragosaBroadcast("nc +icc");
	else
		UnBotSindragosaBroadcast("@dps co +icc");
		UnBotSindragosaBroadcast("@dps nc +icc");
		UnBotSindragosaBroadcast("@heal co +icc");
		UnBotSindragosaBroadcast("@heal nc +icc");
		UnBotSindragosaBroadcast("@tank co -icc");
		UnBotSindragosaBroadcast("@tank nc -icc");
	end
	if (not cycle.healerDiscoveryAnnounced) then
		cycle.healerDiscoveryAnnounced = true;
		UnBotSpecSummonMessage(
			"Синдрагоса: заморожен хилер "..name
			.." — ищу его фактическую глыбу по порядку 70157; "
			.."star станет первым фокусом после освобождения игрока."
		);
	end
end

function UnBotSindragosaInferTombSequence(freedName, tombGuid)
	local cycle = UnBotSindragosaPrep.tombCycle or {};
	local freedInfo = cycle.freezeInfo and cycle.freezeInfo[freedName];
	local healerIndex = tonumber(cycle.priorityFreezeIndex);
	local freedIndex = freedInfo and tonumber(freedInfo.index);
	local serial = tombGuid
		and tonumber(string.sub(tostring(tombGuid), -6), 16);
	if (not healerIndex or not freedIndex or not serial) then
		return;
	end
	cycle.sequenceBaseSerial = serial - (freedIndex - 1);
	cycle.prioritySerial = cycle.sequenceBaseSerial + (healerIndex - 1);
	UnBotSpecSummonMessage(
		"Синдрагоса: последовательность глыб подтверждена по "..freedName
		.."; глыба хила ожидается с serial "
		..string.format("%X", cycle.prioritySerial).."."
	);
end

function UnBotSindragosaQueueTombIcon(iconName, priority)
	if (not iconName or iconName == "") then
		return;
	end
	UnBotSindragosaPrep.tombAttackQueue = UnBotSindragosaPrep.tombAttackQueue or {};
	UnBotSindragosaPrep.tombCycle = UnBotSindragosaPrep.tombCycle or {};
	local cycle = UnBotSindragosaPrep.tombCycle;
	cycle.queueSeen = cycle.queueSeen or {};
	if (cycle.queueSeen[iconName]) then
		return;
	end
	cycle.queueSeen[iconName] = true;
	if (priority) then
		table.insert(UnBotSindragosaPrep.tombAttackQueue, 1, iconName);
	else
		table.insert(UnBotSindragosaPrep.tombAttackQueue, iconName);
	end
end

function UnBotSindragosaNextTombIcon()
	local cycle = UnBotSindragosaPrep.tombCycle or {};
	for _, iconName in ipairs(UnBotSindragosaPrep.tombAttackQueue or {}) do
		local guid = cycle.iconOwners and cycle.iconOwners[iconName];
		if (guid and not (cycle.deadGuids and cycle.deadGuids[guid])) then
			return iconName;
		end
	end
	return nil;
end

function UnBotSindragosaPrepareHealerTombPriority()
	local entries = {};
	for name in pairs(UnBotSindragosaPrep.cycleBeaconNames or {}) do
		local info = UnBotSindragosaPrep.cycleBeaconInfo
			and UnBotSindragosaPrep.cycleBeaconInfo[name];
		if (info and info.guid) then
			table.insert(entries, info);
		end
	end
	table.sort(entries, function(a, b)
		return tostring(a.guid) < tostring(b.guid);
	end);
	local healerName = UnBotSindragosaPrep.tombCycle
		and UnBotSindragosaPrep.tombCycle.priorityHealerName;
	for i, info in ipairs(entries) do
		if (not healerName and info.healer) then
			healerName = info.name;
			break
		end
	end
	UnBotSindragosaPrep.tombCycle = UnBotSindragosaPrep.tombCycle or {};
	UnBotSindragosaPrep.tombCycle.iconOwners = {};
	UnBotSindragosaPrep.tombCycle.deadGuids = {};
	UnBotSindragosaPrep.tombCycle.queueSeen = {};
	UnBotSindragosaPrep.tombCycle.tombNames =
		UnBotSindragosaPrep.tombCycle.tombNames or {};
	UnBotSindragosaPrep.tombCycle.tombCount =
		tonumber(UnBotSindragosaPrep.tombCycle.tombCount) or 0;
	UnBotSindragosaBroadcast("disperse disable");
	UnBotSindragosaPrep.spreadPrepared = false;
	UnBotSindragosaPrep.airGatherPending = false;
	UnBotSindragosaPrep.airSpreadAt = nil;
	if (not healerName) then
		UnBotSindragosaPrep.disableNonTankIccAt = GetTime() + 1.2;
		UnBotSindragosaStartHeroicBombCycle();
		return;
	end
	UnBotSindragosaActivateHealerDiscovery(healerName);
	UnBotSindragosaStartHeroicBombCycle();
end

function UnBotSindragosaOrderDpsAttackIcon(icon, urgent)
	if (not icon or icon == "") then
		return;
	end
	urgent = urgent and true or false;
	if (UnBotSindragosaHeroicBombHiding()) then
		UnBotSindragosaPrep.tombAttackIcon = icon;
		UnBotSindragosaPrep.pendingTombAttackAt = nil;
		UnBotSindragosaPrep.tombAttackRepeatAt = 0;
		UnBotSindragosaPrep.tombAttackTargetSent = false;
		UnBotSindragosaPrep.tombAttackAttempts = 0;
		return;
	end
	if (urgent) then
		UnBotSindragosaPrep.pendingTombAttackAt = GetTime() + 0.15;
	elseif (UnBotSindragosaPrep.playerTombRescue) then
		UnBotSindragosaPrep.pendingTombAttackAt = GetTime() + 0.4;
	else
		UnBotSindragosaPrep.pendingTombAttackAt = GetTime() + 0.35;
	end
	UnBotSindragosaPrep.tombAttackIcon = icon;
	UnBotSindragosaPrep.tombAttackRepeatAt = 0;
	UnBotSindragosaPrep.tombAttackTargetSent = false;
	UnBotSindragosaPrep.tombAttackAttempts = 0;
	if (urgent) then
		UnBotSpecSummonMessage(
			"Синдрагоса: глыба игрока подтверждена — немедленный RTI-фокус "
			.."ДД и танков на "..icon.." без summon к глыбе."
		);
	elseif (UnBotSindragosaPrep.playerTombRescue) then
		UnBotSpecSummonMessage(
			"Синдрагоса: следующая глыба — продолжаю фокус "..icon
			.." без повторного summon к замороженному игроку."
		);
	else
		UnBotSpecSummonMessage(
			"Синдрагоса: немедленный RTI-фокус ДД и танков на "..icon.."."
		);
	end
end

function UnBotSindragosaBeginPhaseThreeTombFocus(victimName)
	if (not UnBotSindragosaIsPhaseThree()) then
		return false;
	end
	local now = GetTime();
	UnBotSindragosaPrep.phaseThreeTombVictims =
		UnBotSindragosaPrep.phaseThreeTombVictims or {};
	if (victimName) then
		UnBotSindragosaPrep.phaseThreeTombVictims[victimName] = true;
	end
	UnBotSindragosaPrep.phaseThreeTombFocusActive = true;
	UnBotSindragosaPrep.phaseThreeTombVictim = victimName;
	UnBotSindragosaPrep.phaseThreeDiscoveryAt = nil;
	UnBotSindragosaPrep.phaseThreeDiscoveryAttempts = 0;
	UnBotSindragosaPrep.phaseThreeBossReturnAt = nil;
	UnBotSindragosaPrep.phaseThreeBossAttackAt = nil;
	UnBotSindragosaPrep.phaseThreeBossReturnAttempts = 0;
	UnBotSindragosaPrep.directTombAttackGuid = nil;
	UnBotSindragosaPrep.directTombAttackAt = nil;
	UnBotSindragosaPrep.directTombAttackAttempts = 0;
	UnBotSindragosaPrep.phaseThreeDpsSuppressed = true;
	UnBotSindragosaPrep.disableNonTankIccAt = nil;
	UnBotSindragosaPrep.tombAttackIcon = nil;
	UnBotSindragosaPrep.tombAttackRepeatAt = 0;
	UnBotSindragosaPrep.tombAttackTargetSent = false;
	UnBotSindragosaPrep.tombAttackAttempts = 0;
	-- Ice Tomb is passive, so mark-rti cannot discover it reliably. Keep DPS off
	-- the boss until the player selects the tomb; that unit token is then passed
	-- straight to Playerbot through the plain attack command.
	UnBotSindragosaPrep.pendingTombAttackAt = nil;
	UnBotSindragosaBroadcast("@dps co +passive,-icc,-mark rti,-aoe");
	UnBotSindragosaBroadcast("@dps nc -icc");
	UnBotSindragosaBroadcast("@warlock pet follow");
	local bossUnit = UnBotSindragosaFindBossUnit();
	if (bossUnit and SetRaidTarget) then
		-- Moon remains a stable return route while mark rti moves skull to the
		-- new tomb. It still works if every DPS has already left the boss target.
		SetRaidTarget(bossUnit, 5);
	end
	UnBotSpecSummonMessage(
		"Синдрагоса, фаза 3: "..tostring(victimName or "цель")
		.." заморожен — ДД прекращают бить босса. Выделите глыбу один раз: "
		.."боты получат прямую команду атаковать текущую цель без RTI."
	);
	return true;
end

function UnBotSindragosaEndPhaseThreeTombFocus(reason, quiet)
	if (not UnBotSindragosaPrep.phaseThreeTombFocusActive) then
		return false;
	end
	UnBotSindragosaPrep.phaseThreeTombFocusActive = false;
	UnBotSindragosaPrep.phaseThreeTombVictim = nil;
	UnBotSindragosaPrep.phaseThreeTombVictims = {};
	UnBotSindragosaPrep.phaseThreeDiscoveryAt = nil;
	UnBotSindragosaPrep.phaseThreeDiscoveryAttempts = 0;
	UnBotSindragosaPrep.phaseThreeDpsSuppressed = false;
	UnBotSindragosaPrep.tombAttackIcon = nil;
	UnBotSindragosaPrep.tombAttackRepeatAt = 0;
	UnBotSindragosaPrep.pendingTombAttackAt = nil;
	UnBotSindragosaPrep.tombAttackTargetSent = false;
	UnBotSindragosaPrep.tombAttackAttempts = 0;
	UnBotSindragosaPrep.directTombAttackGuid = nil;
	UnBotSindragosaPrep.directTombAttackAt = nil;
	UnBotSindragosaPrep.directTombAttackAttempts = 0;
	UnBotSindragosaBroadcast("@dps co -passive,-mark rti,-icc,-aoe");
	UnBotSindragosaBroadcast("@dps nc -icc");
	if (UnBotSindragosaPrep.playerTombRescue) then
		UnBotSindragosaBroadcast("@tank co -mark rti,-aoe");
	end
	UnBotSindragosaBroadcast("@warlock pet follow");
	UnBotSindragosaPrep.phaseThreeBossReturnAttempts = 0;
	UnBotSindragosaPrep.phaseThreeBossReturnAt = GetTime() + 0.2;
	UnBotSindragosaPrep.phaseThreeBossAttackAt = nil;
	if (not quiet) then
		UnBotSpecSummonMessage(
			"Синдрагоса, фаза 3: глыба уничтожена — ДД возвращаются на Синдрагосу"
			..(reason and (" — "..reason) or "").."."
		);
	end
	return true;
end

function UnBotSindragosaPhaseThreeTombVictimCount()
	local count = 0;
	for _ in pairs(UnBotSindragosaPrep.phaseThreeTombVictims or {}) do
		count = count + 1;
	end
	return count;
end

function UnBotSindragosaReleasePhaseThreeTombVictim(victimName)
	UnBotSindragosaPrep.phaseThreeTombVictims =
		UnBotSindragosaPrep.phaseThreeTombVictims or {};
	if (victimName) then
		UnBotSindragosaPrep.phaseThreeTombVictims[victimName] = nil;
	end
	local remaining = UnBotSindragosaPhaseThreeTombVictimCount();
	if (remaining <= 0) then
		return UnBotSindragosaEndPhaseThreeTombFocus("снята последняя аура глыбы");
	end
	UnBotSindragosaPrep.phaseThreeTombFocusActive = true;
	UnBotSindragosaPrep.phaseThreeDiscoveryAt = nil;
	UnBotSindragosaPrep.phaseThreeDiscoveryAttempts = 0;
	UnBotSindragosaPrep.tombAttackIcon = nil;
	UnBotSindragosaPrep.tombAttackTargetSent = false;
	UnBotSindragosaPrep.tombAttackAttempts = 0;
	UnBotSindragosaPrep.tombAttackRepeatAt = 0;
	UnBotSindragosaPrep.pendingTombAttackAt = nil;
	UnBotSindragosaPrep.directTombAttackGuid = nil;
	UnBotSindragosaPrep.directTombAttackAt = nil;
	UnBotSindragosaPrep.directTombAttackAttempts = 0;
	UnBotSindragosaBroadcast("@dps co +passive,-icc,-mark rti,-aoe");
	UnBotSpecSummonMessage(
		"Синдрагоса, фаза 3: одна глыба разрушена, но осталось "
		..tostring(remaining).." — босса пока не атакуем; выделите следующую глыбу."
	);
	return true;
end

function UnBotSindragosaTriggerPhaseThreeTombDiscovery()
	if (not UnBotSindragosaPrep.phaseThreeTombFocusActive) then
		UnBotSindragosaPrep.phaseThreeDiscoveryAt = nil;
		return false;
	end
	local attempt = (tonumber(UnBotSindragosaPrep.phaseThreeDiscoveryAttempts) or 0) + 1;
	UnBotSindragosaPrep.phaseThreeDiscoveryAttempts = attempt;
	-- Ice Tomb is passive and does not enter mark-rti's attacker list by itself.
	-- Instant class AoE gives it the first damage event, after which the existing
	-- raid-target scanner and mark-rti can acquire it without a player click.
	UnBotSindragosaBroadcast("@warrior cast Whirlwind");
	UnBotSindragosaBroadcast("@rogue cast Fan of Knives");
	UnBotSindragosaBroadcast("@paladin cast Consecration");
	UnBotSindragosaBroadcast("@dk cast Blood Boil");
	UnBotSindragosaBroadcast("@druid cast Swipe");
	UnBotSindragosaBroadcast("@mage cast Arcane Explosion");
	UnBotSindragosaBroadcast("@priest cast Holy Nova");
	UnBotSindragosaBroadcast("@shaman cast Fire Nova");
	if (attempt < 3) then
		UnBotSindragosaPrep.phaseThreeDiscoveryAt = GetTime() + 1;
	else
		UnBotSindragosaPrep.phaseThreeDiscoveryAt = nil;
	end
	return true;
end

function UnBotSindragosaDisableNonTankIcc()
	if (not UnBotSindragosaPrep.nonTankIccEnabled) then
		return;
	end
	local heroicAttackWindow = (
		UnBotSindragosaIsHeroic25()
		and UnBotSindragosaPrep.heroicBombActive
		and not UnBotSindragosaHeroicBombHiding()
	) and true or false;
	UnBotSindragosaBroadcast("@dps co -icc");
	UnBotSindragosaBroadcast("@dps nc -icc");
	UnBotSindragosaBroadcast("@tank co -icc");
	UnBotSindragosaBroadcast("@tank nc -icc");
	UnBotSindragosaBroadcast("@heal co "..(heroicAttackWindow and "+icc" or "-icc"));
	UnBotSindragosaBroadcast("@heal nc "..(heroicAttackWindow and "+icc" or "-icc"));
	UnBotSindragosaPrep.nonTankIccEnabled = false;
	UnBotSindragosaPrep.disableNonTankIccAt = nil;
	UnBotSindragosaPrep.postTombIccUntil = nil;
	if (UnBotSindragosaHeroicBombHiding()) then
		UnBotSindragosaBroadcast("co +icc");
		UnBotSindragosaBroadcast("nc +icc");
		UnBotSindragosaBroadcast("@warlock pet follow");
		UnBotSpecSummonMessage(
			"Синдрагоса 25H: поиск глыб завершён; ICC остаётся включена до прохода бомбы."
		);
	elseif (heroicAttackWindow) then
		UnBotSpecSummonMessage(
			"Синдрагоса 25H: поиск глыб завершён — ICC отключена только у ДД и танков; хилы продолжают лечение и уходят в укрытие."
		);
	else
		UnBotSpecSummonMessage(
			"Синдрагоса: глыбы сформированы — ICC снова отключена у всего рейда."
		);
	end
	UnBotSindragosaMarkVisibleTombs();
	local firstIcon = UnBotSindragosaNextTombIcon();
	if (firstIcon) then
		UnBotSindragosaOrderDpsAttackIcon(firstIcon);
	else
		UnBotSpecSummonMessage(
			"Синдрагоса: жду появления глыбы в целях рейда; фокус включится при обнаружении."
		);
	end
end

function UnBotSindragosaSetBeaconBotIcc(name, enabled, guid)
	if (
		not name
		or name == ""
		or name == UnitName("player")
	) then
		return false;
	end
	UnBotRegistryAttachStorage();
	if (
		not UnBotBotRegistry.bots
		or not UnBotBotRegistry.bots[name]
	) then
		return false;
	end
	UnBotSindragosaPrep.beaconBots = UnBotSindragosaPrep.beaconBots or {};
	if (enabled) then
		local wasEnabled = UnBotSindragosaPrep.beaconBots[name] ~= nil;
		UnBotSindragosaPrep.beaconBots[name] = GetTime();
		UnBotSindragosaPrep.disableNonTankIccAt = nil;
		UnBotSindragosaEnableNonTankIcc();
		if (UnBotSindragosaUsePhaseThreeBeaconSeparation()) then
			if (not wasEnabled) then
				UnBotSindragosaSetPhaseThreeBeaconBot(name, true);
			end
		elseif (not UnBotSindragosaIsHeroic25()) then
			UnBotSindragosaWhisperIcc(name, true);
		end
		UnBotSindragosaPrep.cycleBeaconNames =
			UnBotSindragosaPrep.cycleBeaconNames or {};
		if (not UnBotSindragosaPrep.cycleBeaconNames[name]) then
			UnBotSindragosaPrep.cycleBeaconNames[name] = true;
			UnBotSindragosaPrep.cycleBeaconInfo =
				UnBotSindragosaPrep.cycleBeaconInfo or {};
			UnBotSindragosaPrep.cycleBeaconInfo[name] = {
				name = name,
				guid = guid,
				healer = UnBotSindragosaNameIsHealer(name),
			};
			UnBotSindragosaPrep.cycleBeaconCount =
				(tonumber(UnBotSindragosaPrep.cycleBeaconCount) or 0) + 1;
		end
		if (not wasEnabled) then
			UnBotSpecSummonMessage(
				"Синдрагоса: "..name.." получил Ледяную метку."
			);
		end
		return true;
	end
	if (not UnBotSindragosaPrep.beaconBots[name]) then
		return false;
	end
	UnBotSindragosaPrep.beaconBots[name] = nil;
	if (
		(UnBotSindragosaPrep.phaseThreeBeaconBots or {})[name]
		or UnBotSindragosaUsePhaseThreeBeaconSeparation()
	) then
		UnBotSindragosaSetPhaseThreeBeaconBot(name, false);
	elseif (not UnBotSindragosaIsHeroic25()) then
		UnBotSindragosaWhisperIcc(name, false);
	end
	UnBotSpecSummonMessage(
		"Синдрагоса: "..name.." превратился в глыбу."
	);
	if (not next(UnBotSindragosaPrep.beaconBots)) then
		UnBotSindragosaReleaseAirPositions("глыбы сформированы");
		if (UnBotSindragosaUsePhaseThreeBeaconSeparation()) then
			UnBotSindragosaPrep.disableNonTankIccAt = GetTime() + 0.15;
		else
			UnBotSindragosaPrepareHealerTombPriority();
		end
	end
	return true;
end

function UnBotSindragosaRecordPlayerBeacon()
	local playerName = UnitName("player");
	UnBotSindragosaEnableNonTankIcc();
	UnBotSindragosaPrep.cycleBeaconNames =
		UnBotSindragosaPrep.cycleBeaconNames or {};
	if (playerName and not UnBotSindragosaPrep.cycleBeaconNames[playerName]) then
		UnBotSindragosaPrep.cycleBeaconNames[playerName] = true;
		UnBotSindragosaPrep.cycleBeaconInfo =
			UnBotSindragosaPrep.cycleBeaconInfo or {};
		UnBotSindragosaPrep.cycleBeaconInfo[playerName] = {
			name = playerName,
			guid = UnitGUID("player"),
			healer = false,
		};
		UnBotSindragosaPrep.cycleBeaconCount =
			(tonumber(UnBotSindragosaPrep.cycleBeaconCount) or 0) + 1;
		UnBotSpecSummonMessage(
			"Синдрагоса: игрок получил Ледяную метку; остальные боты занимают безопасные позиции."
		);
		if (UnBotSindragosaUsePhaseThreeBeaconSeparation()) then
			UnBotSindragosaShowPhaseThreePlayerBeaconWarning();
		end
	end
end

function UnBotSindragosaRescuePlayerTomb()
	if (UnBotSindragosaPrep.playerTombRescue) then
		return;
	end
	UnBotSindragosaPrep.playerTombRescue = true;
	if (UnBotSindragosaPrep.phaseThreeTombFocusActive) then
		UnBotSindragosaPrep.tombAttackIcon = "skull";
		UnBotSindragosaBroadcast("@tank co +aoe");
		UnBotSpecSummonMessage(
			"Синдрагоса, фаза 3: игрок в глыбе — к фокусу ДД подключатся танки и их AoE."
		);
		return;
	end
	UnBotSindragosaMarkVisibleTombs();
	UnBotSindragosaOrderDpsAttackIcon("skull", true);
end

function UnBotSindragosaNameIsTomb(name)
	name = UnBotSpecSummonNormalize(name);
	return (
		string.find(name, "ice tomb", 1, true)
		or string.find(name, "ледяной склеп", 1, true)
		or string.find(name, "ледяная глыба", 1, true)
	) and true or false;
end

function UnBotSindragosaMarkVisibleTombs()
	if (not SetRaidTarget) then
		return;
	end
	UnBotSindragosaPrep.tombGuids = UnBotSindragosaPrep.tombGuids or {};
	UnBotSindragosaPrep.tombCycle = UnBotSindragosaPrep.tombCycle or {};
	local cycle = UnBotSindragosaPrep.tombCycle;
	cycle.iconOwners = cycle.iconOwners or {};
	cycle.deadGuids = cycle.deadGuids or {};
	cycle.queueSeen = cycle.queueSeen or {};
	local regularIcons = {
		{name = "skull", number = 8},
		{name = "cross", number = 7},
		{name = "square", number = 6},
		{name = "moon", number = 5},
		{name = "triangle", number = 4},
		{name = "diamond", number = 3},
		{name = "circle", number = 2},
	};
	local iconNumbers = {
		skull = 8, cross = 7, square = 6, moon = 5,
		triangle = 4, diamond = 3, circle = 2, star = 1,
	};
	local units = {"target", "focus", "mouseover"};
	local raidCount = GetNumRaidMembers() or 0;
	if (raidCount > 0) then
		for i = 1, math.min(40, raidCount), 1 do
			table.insert(units, "raid"..i.."target");
			table.insert(units, "raid"..i.."pettarget");
		end
	else
		for i = 1, math.min(4, GetNumPartyMembers() or 0), 1 do
			table.insert(units, "party"..i.."target");
			table.insert(units, "party"..i.."pettarget");
		end
	end
	local function tombSerial(unit)
		if (
			UnitExists(unit)
			and UnBotSindragosaNameIsTomb(UnitName(unit))
		) then
			return tonumber(string.sub(tostring(UnitGUID(unit) or ""), -6), 16);
		end
		return nil;
	end
	table.sort(units, function(a, b)
		local serialA = tombSerial(a);
		local serialB = tombSerial(b);
		if (serialA and serialB) then
			return serialA > serialB;
		end
		return serialA and not serialB;
	end);
	for _, unit in ipairs(units) do
		if (
			UnitExists(unit)
			and UnBotSindragosaNameIsTomb(UnitName(unit))
		) then
			local guid = UnitGUID(unit);
			if (guid and not UnBotSindragosaPrep.tombGuids[guid]) then
				local serial = tonumber(string.sub(tostring(guid), -6), 16);
				local iconName = nil;
				local raidIcon = nil;
				if (
					serial and cycle.prioritySerial
					and serial == cycle.prioritySerial
					and not cycle.iconOwners.star
				) then
					iconName = "star";
					raidIcon = 1;
					cycle.priorityGuid = guid;
				else
					for _, iconInfo in ipairs(regularIcons) do
						if (not cycle.iconOwners[iconInfo.name]) then
							iconName = iconInfo.name;
							raidIcon = iconInfo.number;
							break
						end
					end
				end
				if (not iconName) then
					UnBotSpecSummonMessage(
						"Синдрагоса: обнаружена лишняя глыба, но свободных рейдовых меток нет."
					);
					return;
				end
				UnBotSindragosaPrep.tombMarkedCount =
					(tonumber(UnBotSindragosaPrep.tombMarkedCount) or 0) + 1;
				SetRaidTarget(unit, raidIcon);
				UnBotSindragosaPrep.tombGuids[guid] = iconName;
				cycle.iconOwners[iconName] = guid;
				UnBotSindragosaQueueTombIcon(iconName, iconName == "star");
				UnBotSpecSummonMessage(
					"Синдрагоса: глыба закреплена за меткой "..iconName
					..(iconName == "star" and " (хил — сразу после игрока)." or ".")
				);
				if (
					iconName == "star"
					and not UnBotSindragosaPrep.playerTombRescue
					and (
						not UnBotSindragosaPrep.heroicBombActive
						or not UnBotSindragosaPrep.heroicBombFocusLocked
					)
				) then
					UnBotSindragosaPrep.tombAttackIcon = "star";
					UnBotSindragosaPrep.pendingTombAttackAt = GetTime() + 0.15;
					UnBotSindragosaPrep.tombAttackRepeatAt = 0;
					UnBotSindragosaPrep.tombAttackTargetSent = false;
					UnBotSindragosaPrep.tombAttackAttempts = 0;
					cycle.prioritySwitched = true;
					UnBotSpecSummonMessage(
						"Синдрагоса: глыба хила найдена — ДД немедленно переключаются на star."
					);
				elseif (
					not UnBotSindragosaPrep.tombAttackIcon
					and not UnBotSindragosaPrep.nonTankIccEnabled
				) then
					UnBotSindragosaOrderDpsAttackIcon(UnBotSindragosaNextTombIcon());
				end
			elseif (guid) then
				local iconName = UnBotSindragosaPrep.tombGuids[guid];
				local serial = tonumber(string.sub(tostring(guid), -6), 16);
				if (
					serial and cycle.prioritySerial
					and serial == cycle.prioritySerial
					and iconName ~= "star"
					and not cycle.iconOwners.star
					and (
						not UnBotSindragosaPrep.heroicBombActive
						or not UnBotSindragosaPrep.heroicBombFocusLocked
					)
				) then
					cycle.iconOwners[iconName] = nil;
					UnBotSindragosaPrep.tombGuids[guid] = "star";
					cycle.iconOwners.star = guid;
					cycle.priorityGuid = guid;
					iconName = "star";
					UnBotSindragosaQueueTombIcon("star", true);
					SetRaidTarget(unit, 1);
					if (not UnBotSindragosaPrep.playerTombRescue) then
						UnBotSindragosaPrep.tombAttackIcon = "star";
						UnBotSindragosaPrep.pendingTombAttackAt = GetTime() + 0.15;
						UnBotSindragosaPrep.tombAttackRepeatAt = 0;
						UnBotSindragosaPrep.tombAttackTargetSent = false;
						UnBotSindragosaPrep.tombAttackAttempts = 0;
						cycle.prioritySwitched = true;
					end
					UnBotSpecSummonMessage(
						"Синдрагоса: фактическая глыба хила подтверждена и повышена до star."
					);
				end
				local wantedNumber = iconNumbers[iconName];
				if (
					wantedNumber
					and GetRaidTargetIndex
					and GetRaidTargetIndex(unit) ~= wantedNumber
				) then
					SetRaidTarget(unit, wantedNumber);
				end
			end
		end
	end
end

function UnBotSindragosaUnitHasDebuff(unit, spellId)
	if (not UnitExists(unit)) then
		return false;
	end
	for i = 1, 40, 1 do
		local auraName, rank, icon, count, debuffType, duration, expirationTime, unitCaster, isStealable, shouldConsolidate, auraId =
			UnitDebuff(unit, i);
		if (not auraName) then
			break
		end
		if (tonumber(auraId) == tonumber(spellId)) then
			return true;
		end
	end
	return false;
end

function UnBotSindragosaScanBeaconBots()
	local now = GetTime();
	if (now < (UnBotSindragosaPrep.nextBeaconScanAt or 0)) then
		return;
	end
	UnBotSindragosaPrep.nextBeaconScanAt = now + 0.2;
	local seen = {};
	local raidCount = GetNumRaidMembers() or 0;
	if (raidCount > 0) then
		for i = 1, math.min(40, raidCount), 1 do
			local unit = "raid"..i;
			if (UnBotSindragosaUnitHasDebuff(unit, 70126)) then
				local name = UnitName(unit);
				seen[name] = true;
				UnBotSindragosaSetBeaconBotIcc(name, true, UnitGUID(unit));
			end
		end
	else
		for i = 1, math.min(4, GetNumPartyMembers() or 0), 1 do
			local unit = "party"..i;
			if (UnBotSindragosaUnitHasDebuff(unit, 70126)) then
				local name = UnitName(unit);
				seen[name] = true;
				UnBotSindragosaSetBeaconBotIcc(name, true, UnitGUID(unit));
			end
		end
	end
	for name, lastSeen in pairs(UnBotSindragosaPrep.beaconBots or {}) do
		if (
			not seen[name]
			and now >= (tonumber(lastSeen) or 0) + 1
		) then
			UnBotSindragosaSetBeaconBotIcc(name, false);
		end
	end
end

function UnBotSindragosaNameMatches(name)
	name = UnBotSpecSummonNormalize(name);
	return (
		string.find(name, "sindragosa", 1, true)
		or string.find(name, "синдрагоса", 1, true)
	) and true or false;
end

