function UnBotSindragosaFindBossUnit()
	local units = {"boss1", "boss2", "boss3", "boss4", "focus", "targettarget"};
	for _, unit in ipairs(units) do
		if (UnitExists(unit)) then
			local name = UnBotSpecSummonNormalize(UnitName(unit));
			if (
				string.find(name, "sindragosa", 1, true)
				or string.find(name, "синдрагоса", 1, true)
			) then
				return unit;
			end
		end
	end
	for i = 1, math.min(40, GetNumRaidMembers() or 0), 1 do
		local unit = "raid"..i.."target";
		if (UnitExists(unit)) then
			local name = UnBotSpecSummonNormalize(UnitName(unit));
			if (
				string.find(name, "sindragosa", 1, true)
				or string.find(name, "синдрагоса", 1, true)
			) then
				return unit;
			end
		end
	end
	return nil;
end

function UnBotSindragosaIsPhaseThree()
	local unit = UnBotSindragosaFindBossUnit();
	if (not unit) then
		return false;
	end
	local maximum = tonumber(UnitHealthMax(unit)) or 0;
	if (maximum <= 0) then
		return false;
	end
	return ((tonumber(UnitHealth(unit)) or 0) * 100 / maximum) <= 36;
end

function UnBotSindragosaSuppressPhaseThreeDps()
	if (UnBotSindragosaPrep.phaseThreeDpsSuppressed) then
		return;
	end
	UnBotSindragosaBroadcast("@dps co -icc");
	UnBotSindragosaBroadcast("@dps nc -icc");
	UnBotSindragosaPrep.phaseThreeDpsSuppressed = true;
	UnBotSpecSummonMessage(
		"Синдрагоса, фаза 3: ICC отключена только у DPS; танки и хилы сбрасывают стаки за глыбой."
	);
end

function UnBotSindragosaRestorePhaseThreeDps(reason, force)
	if (not UnBotSindragosaPrep.phaseThreeDpsSuppressed and not force) then
		return;
	end
	UnBotSindragosaPrep.phaseThreeDpsSuppressed = false;
end

function UnBotSindragosaRestoreIcc(reason, force)
	if (UnBotSindragosaReleaseBubbleReserve) then
		UnBotSindragosaReleaseBubbleReserve(reason or "бой завершён", true);
	end
	if (not UnBotSindragosaPrep.iccSuppressed and not force) then
		return;
	end
	UnBotSindragosaReleaseAirPositions("бой завершён");
	if (UnBotSindragosaPrep.retTankName) then
		SendChatMessage(
			"co -tank,+dps,-passive,-icc,-mark rti",
			"WHISPER",
			nil,
			UnBotSindragosaPrep.retTankName
		);
		SendChatMessage(
			"nc -tank,+dps,-icc",
			"WHISPER",
			nil,
			UnBotSindragosaPrep.retTankName
		);
	end
	UnBotSindragosaBroadcast("co +icc");
	UnBotSindragosaBroadcast("nc +icc");
	UnBotSindragosaBroadcast("@dps co -mark rti");
	UnBotSindragosaBroadcast("disperse disable");
	UnBotSindragosaRestoreHeroicSingleTarget();
	UnBotSindragosaRestoreUnchainedMagic();
	UnBotSindragosaRestorePhaseThreeBeaconBots();
	UnBotSindragosaPrep.spreadPrepared = false;
	UnBotSindragosaPrep.airGatherPending = false;
	UnBotSindragosaPrep.airSpreadAt = nil;
