		..(reason and (" — "..reason) or "").."."
	);
end

function UnBotSindragosaRetTankCandidates()
	UnBotRegistryAttachStorage();
	local result = {};
	local members = UnBotSpecSummonGetMembers();
	members[UnitName("player")] = nil;
	for name in pairs(members) do
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		local className = UnBotSpecSummonNormalize(profile and profile.className);
		local specName = UnBotSpecSummonNormalize(profile and profile.specName);
		local unit = UnBotSquadRosterFindUnit(name);
		if (
			className == "paladin"
			and (specName == "ret" or specName == "retribution")
			and unit
			and (not UnitIsConnected or UnitIsConnected(unit))
			and not UnitIsDeadOrGhost(unit)
		) then
			table.insert(result, name);
		end
	end
	table.sort(result);
	return result;
end

function UnBotSindragosaUpdateRetPaladinHealing(now)
	local state = UnBotSindragosaPrep;
	if (not state.encounterActive or now < (state.nextRetHealAt or 0)) then
		return;
	end
	state.nextRetHealAt = now + 0.25;

	local members = UnBotSpecSummonGetMembers();
	members[UnitName("player")] = nil;
	local onlineCount = 0;
	for name in pairs(members) do
		local unit = UnBotSquadRosterFindUnit(name);
		if (unit and (not UnitIsConnected or UnitIsConnected(unit))) then
			onlineCount = onlineCount + 1;
		end
	end
	local retPaladins = UnBotSindragosaRetTankCandidates();
	if (onlineCount ~= 2 or table.getn(retPaladins) ~= 2) then
		return;
	end

	state.retHealBots = state.retHealBots or {};
	for _, name in ipairs(retPaladins) do
		local unit = UnBotSquadRosterFindUnit(name);
		if (
			unit
			and UnitExists(unit)
			and (not UnitIsConnected or UnitIsConnected(unit))
			and not UnitIsDeadOrGhost(unit)
			and UnitAffectingCombat(unit)
			and not UnBotSindragosaUnitHasDebuff(unit, 70157)
		) then
			local maximum = tonumber(UnitHealthMax(unit)) or 0;
			local current = tonumber(UnitHealth(unit)) or 0;
			if (maximum > 0) then
				local healthPercent = (current / maximum) * 100;
				local botState = state.retHealBots[name];
				if (not botState) then
					botState = {
						layOnHandsUsed = false,
						holyLightAttempts = 0,
						nextHealAt = 0,
						healAnnounced = false,
						exhaustedAnnounced = false,
					};
					state.retHealBots[name] = botState;
				end
				if (
					healthPercent <= 20
					and not botState.layOnHandsUsed
					and (
						name ~= state.bubbleReserveName
						or state.bubbleReserveConsumed
					)
				) then
					botState.layOnHandsUsed = true;
					botState.nextHealAt = now + 1.5;
					SendChatMessage("cast Lay on Hands on "..name, "WHISPER", nil, name);
					UnBotSpecSummonMessage(
						"Синдрагоса: "..name.." на "
						..math.floor(healthPercent + 0.5)
						.."% HP — аварийная попытка Lay on Hands."
					);
				elseif (
					healthPercent <= 40
					and now >= (botState.nextHealAt or 0)
					and (botState.holyLightAttempts or 0) < 8
				) then
					botState.holyLightAttempts = (botState.holyLightAttempts or 0) + 1;
					botState.nextHealAt = now + 2.8;
					SendChatMessage("cast Holy Light on "..name, "WHISPER", nil, name);
					if (not botState.healAnnounced) then
						botState.healAnnounced = true;
						UnBotSpecSummonMessage(
							"Синдрагоса: "..name.." на "
							..math.floor(healthPercent + 0.5)
							.."% HP — включён Holy Light."
						);
					end
				elseif (
					healthPercent <= 40
					and (botState.holyLightAttempts or 0) >= 8
					and not botState.exhaustedAnnounced
				) then
					botState.exhaustedAnnounced = true;
					UnBotSpecSummonMessage(
						"Синдрагоса: "..name
						.." исчерпал 8 попыток Holy Light; цикл лечения остановлен."
					);
				elseif (healthPercent > 40) then
					botState.healAnnounced = false;
				end
			end
		end
	end
end

function UnBotSindragosaSendRetTankTaunt()
	local state = UnBotSindragosaPrep;
	local name = state.retTankName;
	if (
		not name
		or not state.encounterActive
		or not UnBotSindragosaIsPhaseThree()
	) then
		state.retTankTauntAt = nil;
		return false;
	end
	local attempt = (tonumber(state.retTankTauntAttempts) or 0) + 1;
	state.retTankTauntAttempts = attempt;
	if (attempt == 1) then
		SendChatMessage("co +tank,-dps,-passive,-icc,-mark rti", "WHISPER", nil, name);
		SendChatMessage("nc +tank,-dps,-icc", "WHISPER", nil, name);
		SendChatMessage("cast Righteous Fury", "WHISPER", nil, name);
	end
	SendChatMessage("rti moon", "WHISPER", nil, name);
	SendChatMessage("attack rti target", "WHISPER", nil, name);
	SendChatMessage("cast Hand of Reckoning", "WHISPER", nil, name);
	if (attempt < 3) then
		state.retTankTauntAt = GetTime() + 0.7;
	else
		state.retTankTauntAt = nil;
	end
	return true;
end

function UnBotSindragosaBeginRetTankRotation(frozenName)
	local state = UnBotSindragosaPrep;
	if (
		state.retTankName
		or not frozenName
		or frozenName == UnitName("player")
		or not UnBotSindragosaIsPhaseThree()
	) then
		return false;
	end
	local members = UnBotSpecSummonGetMembers();
	members[UnitName("player")] = nil;
	local memberCount = 0;
	for name in pairs(members) do
		local unit = UnBotSquadRosterFindUnit(name);
		if (unit and (not UnitIsConnected or UnitIsConnected(unit))) then
			memberCount = memberCount + 1;
		end
	end
	if (memberCount ~= 2) then
		return false;
	end
	local candidates = UnBotSindragosaRetTankCandidates();
	if (#candidates ~= 2) then
		return false;
	end
	local frozenIsRet = false;
	local tankName = nil;
	for _, name in ipairs(candidates) do
		if (name == frozenName) then
			frozenIsRet = true;
		else
			tankName = name;
		end
	end
	if (not frozenIsRet or not tankName) then
		return false;
	end
	state.retTankName = tankName;
	state.retTankFrozenName = frozenName;
	state.retTankTauntAttempts = 0;
	state.retTankTauntAt = GetTime();
	state.retTankPlayerReset = false;
	state.retTankExpiresAt = GetTime() + 35;
	local bossUnit = UnBotSindragosaFindBossUnit();
	if (bossUnit and SetRaidTarget) then
		SetRaidTarget(bossUnit, 5);
	end
	UnBotSindragosaSendRetTankTaunt();
	if (RaidNotice_AddMessage and RaidWarningFrame) then
		RaidNotice_AddMessage(
			RaidWarningFrame,
			string.upper(tankName).." ЗАБИРАЕТ БОССА — ВСТАНЬ ЗА ГЛЫБУ И СБРОСЬ СТАКИ!",
			ChatTypeInfo and ChatTypeInfo["RAID_WARNING"]
		);
	end
	if (PlaySound) then
		PlaySound("RaidWarning");
	end
	UnBotSpecSummonMessage(
		"Синдрагоса, ротация двух ретриков: "..frozenName.." в глыбе; "
		..tankName.." временно получает tank, Праведное неистовство и таунт. "
		.."Не ломайте глыбу до полного снятия Таинственной энергии с Tiridan."
	);
	return true;
end

function UnBotSindragosaPlayerBuffetCleared()
	local state = UnBotSindragosaPrep;
	if (not state.retTankName or state.retTankPlayerReset) then
		return false;
	end
	state.retTankPlayerReset = true;
	if (RaidNotice_AddMessage and RaidWarningFrame) then
		RaidNotice_AddMessage(
			RaidWarningFrame,
			"СТАКИ СНЯТЫ — ТАУНТ СИНДРАГОСУ ОБРАТНО!",
			ChatTypeInfo and ChatTypeInfo["RAID_WARNING"]
		);
	end
	if (PlaySound) then
		PlaySound("RaidWarning");
	end
	UnBotSpecSummonMessage(
		"Синдрагоса: Таинственная энергия с игрока снята. "
		.."Нажмите свой таунт; после первого удара босса по Tiridan временный танк вернётся в ДД."
	);
	return true;
end

function UnBotSindragosaFinishRetTankRotation()
	local state = UnBotSindragosaPrep;
	local name = state.retTankName;
	if (not name) then
		return false;
	end
	SendChatMessage("co -tank,+dps,-passive,-icc,-mark rti", "WHISPER", nil, name);
	SendChatMessage("nc -tank,+dps,-icc", "WHISPER", nil, name);
	SendChatMessage("cast Hand of Salvation on "..name, "WHISPER", nil, name);
	state.retTankName = nil;
	state.retTankFrozenName = nil;
	state.retTankTauntAt = nil;
	state.retTankTauntAttempts = 0;
	state.retTankPlayerReset = false;
	state.retTankExpiresAt = nil;
	UnBotSpecSummonMessage(
		"Синдрагоса: удар по Tiridan подтвердил обратный таунт; "..name
		.." снова ДД. Теперь выделите живую глыбу — начнётся прямой фокус."
	);
	if (UnBotSindragosaIsTombTarget()) then
		UnBotSindragosaStartDirectTombAttack(UnitGUID("target"));
	end
	return true;
end

function UnBotSindragosaSendDirectTombAttack()
	local state = UnBotSindragosaPrep;
	local guid = UnitGUID("target");
	if (
		not state.encounterActive
		or not UnBotSindragosaIsTombTarget()
		or (UnitIsDead and UnitIsDead("target"))
		or not guid
		or guid ~= state.directTombAttackGuid
	) then
		state.directTombAttackGuid = nil;
		state.directTombAttackAt = nil;
		state.directTombAttackAttempts = 0;
		return false;
	end
	local attempt = (tonumber(state.directTombAttackAttempts) or 0) + 1;
	state.directTombAttackAttempts = attempt;
	-- Plain "attack" means attack the master's current target. It does not depend
	-- on mark-rti seeing the passive Ice Tomb and therefore is the reliable bridge
	-- once the player has supplied a legal unit token by selecting the tomb.
	UnBotSindragosaBroadcast("@dps co -icc,-passive,-mark rti");
	UnBotSindragosaBroadcast("@dps nc -icc");
	UnBotSindragosaBroadcast("@dps attack");
	UnBotSindragosaBroadcast("@warlock pet attack");
	if (
		state.playerTombRescue
		or not UnBotSindragosaIsPhaseThree()
	) then
		UnBotSindragosaBroadcast("@tank co -icc,-passive,-mark rti");
		UnBotSindragosaBroadcast("@tank nc -icc");
		UnBotSindragosaBroadcast("@tank attack");
	end
	if (attempt < 5) then
		state.directTombAttackAt = GetTime() + 0.55;
	else
		state.directTombAttackAt = nil;
	end
	return true;
end

function UnBotSindragosaStartDirectTombAttack(guid)
	if (not guid or not UnBotSindragosaIsTombTarget()) then
		return false;
	end
	UnBotSindragosaPrep.directTombAttackGuid = guid;
	UnBotSindragosaPrep.directTombAttackAt = GetTime();
	UnBotSindragosaPrep.directTombAttackAttempts = 0;
	return UnBotSindragosaSendDirectTombAttack();
end

function UnBotSindragosaFocusSelectedTomb(force)
	if (UnBotSindragosaHeroicBombHiding()) then
		return false;
	end
	if (not UnBotSindragosaIsTombTarget()) then
		return false;
	end
	if (not UnBotSindragosaPrep.encounterActive) then
		UnBotSindragosaBeginFight();
	end
	local guid = UnitGUID("target");
	local now = GetTime();
	local targetChanged = guid ~= UnBotSindragosaPrep.lastTombGuid;
	if (
		not force
		and not targetChanged
		and now < (UnBotSindragosaPrep.lastFocusAt or 0) + 2.5
	) then
		return false;
	end

	local phaseThree = UnBotSindragosaIsPhaseThree();
	if (
		phaseThree
		and UnBotSindragosaPrep.retTankName
		and not UnBotSindragosaPrep.retTankPlayerReset
	) then
		if (force or targetChanged) then
			UnBotSpecSummonMessage(
				"Синдрагоса: глыба пока удерживается живой — сначала дождитесь "
				.."полного снятия Таинственной энергии за ней."
			);
		end
		return false;
	end
	UnBotSindragosaSuppressIcc();
	UnBotSindragosaMarkVisibleTombs();
	UnBotSindragosaPrep.lastTombGuid = guid;
	UnBotSindragosaPrep.lastFocusAt = now;
	if (
		force
		or targetChanged
		or guid ~= UnBotSindragosaPrep.directTombAttackGuid
	) then
		UnBotSindragosaStartDirectTombAttack(guid);
	end
	local iconName = UnBotSindragosaPrep.tombGuids
		and UnBotSindragosaPrep.tombGuids[guid];
	if (not iconName) then
		if (force or targetChanged) then
			UnBotSpecSummonMessage(
				"Синдрагоса: глыба выбрана — отправлена прямая команда атаки; "
				.."рейдовая метка для этого режима не требуется."
			);
		end
		return true;
	end
	local cycle = UnBotSindragosaPrep.tombCycle or {};
	local currentIcon = UnBotSindragosaPrep.tombAttackIcon;
	local currentGuid = currentIcon
		and cycle.iconOwners
		and cycle.iconOwners[currentIcon];
	if (
		not phaseThree
		and
		currentGuid
		and not (cycle.deadGuids and cycle.deadGuids[currentGuid])
	) then
		if (force and currentIcon == "star" and iconName ~= "star") then
			UnBotSpecSummonMessage(
				"Синдрагоса: ручная смена цели проигнорирована — глыба хила star ещё жива."
			);
		end
		return false;
	end
	UnBotSindragosaPrep.tombAttackIcon = iconName;
	if (UnBotSindragosaPrep.heroicBombActive) then
		UnBotSindragosaPrep.heroicBombFocusLocked = true;
	end
	UnBotSindragosaPrep.pendingTombAttackAt = nil;
	UnBotSindragosaPrep.tombAttackRepeatAt = 0;
	UnBotSindragosaPrep.tombAttackTargetSent = false;
	UnBotSindragosaPrep.tombAttackAttempts = 0;
	if (phaseThree) then
		UnBotSindragosaPrep.pendingTombAttackAt = nil;
	else
		UnBotSindragosaPrep.pendingTombAttackAt = now + 0.05;
	end
	if (next(UnBotSindragosaPrep.unchainedBots or {})) then
		UnBotSindragosaPrep.nextUnchainedEnforceAt = 0;
		UnBotSindragosaEnforceUnchainedMagic(now);
	end
	if (force or targetChanged) then
		if (phaseThree) then
			UnBotSpecSummonMessage(
				"Синдрагоса, фаза 3: ДД получили прямую атаку выбранной глыбы "
				..iconName.."; ICC и ожидание RTI отключены."
			);
		else
			UnBotSpecSummonMessage(
				"Синдрагоса: ДД и танки держат выбранную глыбу по неизменной метке "
				..iconName.."."
			);
		end
	end
	return true;
end

function UnBotSindragosaHandleCombatLog(...)
	local eventType = select(2, ...);
	local sourceName = select(4, ...);
	local destinationGuid = select(6, ...);
	local destinationName = select(7, ...);
	if (
		(eventType == "UNIT_DIED" or eventType == "UNIT_DESTROYED")
		and UnBotSindragosaNameMatches(destinationName)
	) then
		UnBotSindragosaRestoreIcc("Синдрагоса погибла");
		return;
	end
	if (
		UnBotSindragosaNameMatches(sourceName)
		or UnBotSindragosaNameMatches(destinationName)
	) then
		UnBotSindragosaBeginFight();
	end
	if (not UnBotSindragosaPrep.encounterActive) then
		return;
	end
	if (
		UnBotSindragosaPrep.heroicBombActive
		and (eventType == "SWING_DAMAGE" or eventType == "SWING_MISSED")
		and UnBotSindragosaNameMatches(sourceName)
	) then
		UnBotSindragosaStopHeroicBombCycle("Синдрагоса приземлилась");
	end
	if (
		UnBotSindragosaPrep.groundTankRegroupPending
		and (eventType == "SWING_DAMAGE" or eventType == "SWING_MISSED")
		and UnBotSindragosaNameMatches(sourceName)
		and not UnBotSindragosaUnitHasDebuff("player", 70157)
		and not UnitIsDeadOrGhost("player")
	) then
		UnBotSindragosaRegroupTanksAfterAir();
	end
	local spellId = tonumber((select(9, ...)));
	if (
		eventType == "SPELL_AURA_REMOVED"
		and spellId == 72530
		and destinationName == UnitName("player")
		and UnBotSindragosaPrep.retTankName
		and UnBotSindragosaIsPhaseThree()
	) then
		UnBotSindragosaPlayerBuffetCleared();
	end
	if (
		UnBotSindragosaPrep.retTankName
		and UnBotSindragosaPrep.retTankPlayerReset
		and (eventType == "SWING_DAMAGE" or eventType == "SWING_MISSED")
		and UnBotSindragosaNameMatches(sourceName)
		and destinationName == UnitName("player")
	) then
		UnBotSindragosaFinishRetTankRotation();
	end
	if (
		(eventType == "SPELL_AURA_APPLIED" or eventType == "SPELL_AURA_REFRESH")
		and spellId == 69762
	) then
		UnBotSindragosaSetUnchainedMagic(destinationName, true);
	elseif (eventType == "SPELL_AURA_REMOVED" and spellId == 69762) then
		UnBotSindragosaSetUnchainedMagic(destinationName, false);
	end
	if (spellId == 69766) then
		if (
			eventType == "SPELL_AURA_APPLIED"
			or eventType == "SPELL_AURA_REFRESH"
			or eventType == "SPELL_AURA_APPLIED_DOSE"
		) then
			UnBotSindragosaSetInstability(
				destinationName,
				true,
				tonumber((select(13, ...))) or 1
			);
		elseif (eventType == "SPELL_AURA_REMOVED") then
			UnBotSindragosaSetInstability(destinationName, false, 0);
		end
	end
	if (
		eventType == "SPELL_DAMAGE"
		and spellId == 71055
		and UnBotSindragosaNameMatches(sourceName)
	) then
		UnBotSindragosaRecordHeroicBomb(GetTime());
	end
	if (
		eventType == "SPELL_CAST_START"
		and spellId == 69712
	) then
		UnBotSindragosaPrep.airWarningAt = GetTime() + 101.5;
		UnBotSindragosaPrep.groundTankRegroupPending = true;
		UnBotSindragosaShowBubbleNowWarning();
		UnBotSindragosaBeginAirGather("начат каст Ледяного склепа");
	elseif (
		(eventType == "SPELL_AURA_APPLIED" or eventType == "SPELL_AURA_REFRESH")
		and spellId == 70126
	) then
		if (destinationName == UnitName("player")) then
			UnBotSindragosaRecordPlayerBeacon();
		else
			UnBotSindragosaSetBeaconBotIcc(destinationName, true, destinationGuid);
		end
	elseif (
		(eventType == "SPELL_AURA_REMOVED" and spellId == 70126)
		or (eventType == "SPELL_AURA_APPLIED" and spellId == 70157)
	) then
		if (
			spellId == 70157
			and eventType == "SPELL_AURA_APPLIED"
			and destinationName
		) then
			UnBotSindragosaPrep.tombCycle = UnBotSindragosaPrep.tombCycle or {};
			local cycle = UnBotSindragosaPrep.tombCycle;
			cycle.freezeInfo = cycle.freezeInfo or {};
			cycle.freezeOrder = cycle.freezeOrder or {};
			if (not cycle.freezeInfo[destinationName]) then
				local freezeInfo = {
					name = destinationName,
					guid = destinationGuid,
					index = #cycle.freezeOrder + 1,
					healer = UnBotSindragosaNameIsHealer(destinationName),
				};
				cycle.freezeInfo[destinationName] = freezeInfo;
				table.insert(cycle.freezeOrder, destinationName);
				if (freezeInfo.healer) then
					cycle.priorityFreezeIndex = freezeInfo.index;
					UnBotSindragosaActivateHealerDiscovery(destinationName);
				end
			end
			cycle.tombNames = cycle.tombNames or {};
			if (not cycle.tombNames[destinationName]) then
				cycle.tombNames[destinationName] = true;
				cycle.tombCount = (tonumber(cycle.tombCount) or 0) + 1;
				if (
					not (UnBotSindragosaPrep.cycleBeaconNames or {})[destinationName]
				) then
					UnBotSpecSummonMessage(
						"Синдрагоса: "..destinationName
						.." без Ледяной метки оказался в глыбе — зафиксировано наложение."
					);
				end
			end
		end
		UnBotSindragosaSetBeaconBotIcc(destinationName, false);
		if (
			spellId == 70157
			and eventType == "SPELL_AURA_APPLIED"
			and UnBotSindragosaIsPhaseThree()
		) then
			UnBotSindragosaBeginPhaseThreeTombFocus(destinationName);
			UnBotSindragosaBeginRetTankRotation(destinationName);
		end
		if (
			spellId == 70157
			and eventType == "SPELL_AURA_APPLIED"
			and not next(UnBotSindragosaPrep.beaconBots or {})
		) then
			UnBotSindragosaReleaseAirPositions("глыбы сформированы");
		end
		if (
			spellId == 70157
			and eventType == "SPELL_AURA_APPLIED"
			and destinationName == UnitName("player")
		) then
			UnBotSindragosaRescuePlayerTomb();
		end
		if (
			spellId == 70157
			and UnBotSindragosaPrep.nonTankIccEnabled
			and not next(UnBotSindragosaPrep.beaconBots or {})
			and not UnBotSindragosaPrep.postTombIccUntil
		) then
			UnBotSindragosaPrep.disableNonTankIccAt = GetTime() + 1.2;
		end
	elseif (eventType == "SPELL_AURA_REMOVED" and spellId == 70157) then
		if (UnBotSindragosaPrep.phaseThreeTombFocusActive) then
			UnBotSindragosaReleasePhaseThreeTombVictim(destinationName);
		end
		local cycle = UnBotSindragosaPrep.tombCycle or {};
		if (
			cycle.pendingKilledTombGuid
			and GetTime() <= (tonumber(cycle.pendingKilledAt) or 0) + 1
		) then
			UnBotSindragosaInferTombSequence(
				destinationName,
				cycle.pendingKilledTombGuid
			);
			cycle.pendingKilledTombGuid = nil;
			cycle.pendingKilledAt = nil;
		end
		if (destinationName == UnitName("player")) then
			if (UnBotSindragosaIsPhaseThree()) then
				local bossUnit = UnBotSindragosaFindBossUnit();
				if (bossUnit and SetRaidTarget) then
					SetRaidTarget(bossUnit, 5);
				end
				UnBotSindragosaBroadcast("@tank co -mark rti,-aoe");
				UnBotSindragosaBroadcast("@tank rti moon");
				UnBotSindragosaBroadcast("@tank attack rti target");
			end
			UnBotSindragosaPrep.playerTombRescue = false;
			local cycle = UnBotSindragosaPrep.tombCycle or {};
			local healerGuid = cycle.iconOwners and cycle.iconOwners.star;
			if (
				healerGuid
				and not (cycle.deadGuids and cycle.deadGuids[healerGuid])
			) then
				UnBotSpecSummonMessage(
					"Синдрагоса: игрок освобождён — следующая цель глыба хила (star)."
				);
				UnBotSindragosaOrderDpsAttackIcon("star");
			else
				UnBotSpecSummonMessage("Синдрагоса: игрок освобождён из глыбы.");
			end
		end
	end
	if (
		eventType == "PARTY_KILL"
		and destinationGuid
		and UnBotSindragosaNameIsTomb(destinationName)
	) then
		UnBotSindragosaPrep.tombCycle = UnBotSindragosaPrep.tombCycle or {};
		UnBotSindragosaPrep.tombCycle.pendingKilledTombGuid = destinationGuid;
		UnBotSindragosaPrep.tombCycle.pendingKilledAt = GetTime();
	end
	if (
		(eventType == "UNIT_DIED" or eventType == "UNIT_DESTROYED")
		and destinationGuid
		and destinationGuid == UnBotSindragosaPrep.lastTombGuid
	) then
		UnBotSindragosaPrep.lastTombGuid = nil;
	end
	if (
		(eventType == "UNIT_DIED" or eventType == "UNIT_DESTROYED")
		and UnBotSindragosaNameIsTomb(destinationName)
	) then
		UnBotSindragosaPrep.tombCycle = UnBotSindragosaPrep.tombCycle or {};
		local cycle = UnBotSindragosaPrep.tombCycle;
		cycle.deadGuids = cycle.deadGuids or {};
		if (destinationGuid and cycle.deadGuids[destinationGuid]) then
			return;
		end
		if (destinationGuid) then
			cycle.deadGuids[destinationGuid] = true;
		end
		local deadIcon = destinationGuid
			and UnBotSindragosaPrep.tombGuids
			and UnBotSindragosaPrep.tombGuids[destinationGuid];
		local wasCurrent = deadIcon
			and deadIcon == UnBotSindragosaPrep.tombAttackIcon;
		UnBotSindragosaPrep.tombDeaths =
			(tonumber(UnBotSindragosaPrep.tombDeaths) or 0) + 1;
		local expectedTombs = tonumber(cycle.tombCount) or 0;
		if (expectedTombs <= 0) then
			expectedTombs = math.max(
				1,
				tonumber(UnBotSindragosaPrep.cycleBeaconCount) or 0
			);
		end
		if (
			UnBotSindragosaPrep.tombDeaths
			>= expectedTombs
		) then
			UnBotSindragosaRestoreHeroicSingleTarget();
			UnBotSindragosaPrep.tombAttackIcon = nil;
			UnBotSindragosaPrep.tombAttackRepeatAt = 0;
			UnBotSindragosaPrep.pendingTombAttackAt = nil;
			UnBotSindragosaPrep.tombAttackTargetSent = false;
			UnBotSindragosaPrep.tombAttackAttempts = 0;
			UnBotSindragosaPrep.heroicBombFocusLocked = false;
			UnBotSpecSummonMessage("Синдрагоса: все глыбы текущего цикла уничтожены.");
		else
			if (wasCurrent) then
				UnBotSindragosaPrep.tombAttackIcon = nil;
				UnBotSindragosaPrep.tombAttackRepeatAt = 0;
				UnBotSindragosaPrep.pendingTombAttackAt = nil;
				UnBotSindragosaPrep.tombAttackTargetSent = false;
				UnBotSindragosaPrep.tombAttackAttempts = 0;
				UnBotSindragosaPrep.heroicBombFocusLocked = false;
			end
			local nextIcon = UnBotSindragosaNextTombIcon();
			if (
				nextIcon
				and nextIcon ~= UnBotSindragosaPrep.tombAttackIcon
			) then
				UnBotSindragosaOrderDpsAttackIcon(nextIcon);
			elseif (not nextIcon) then
				UnBotSindragosaPrep.tombAttackIcon = nil;
				UnBotSindragosaPrep.tombAttackRepeatAt = 0;
				UnBotSindragosaPrep.pendingTombAttackAt = nil;
				UnBotSindragosaPrep.tombAttackTargetSent = false;
				UnBotSpecSummonMessage(
					"Синдрагоса: жду следующую обнаруженную глыбу текущего цикла."
				);
			end
		end
	end
end

local UnBotSindragosaFrame = CreateFrame("Frame", "UnBotSindragosaFrame");
UnBotSindragosaFrame:RegisterEvent("PLAYER_TARGET_CHANGED");
UnBotSindragosaFrame:RegisterEvent("COMBAT_LOG_EVENT_UNFILTERED");
UnBotSindragosaFrame:RegisterEvent("PLAYER_REGEN_DISABLED");
UnBotSindragosaFrame:RegisterEvent("PLAYER_REGEN_ENABLED");
UnBotSindragosaFrame:SetScript("OnEvent", function(self, event, ...)
	if (not UnBotBossPresetLoadedAutoStrategyEnabled("sindragosa")) then
		return;
	end
	if (event == "COMBAT_LOG_EVENT_UNFILTERED") then
		UnBotSindragosaHandleCombatLog(...);
		return;
	elseif (event == "PLAYER_REGEN_DISABLED") then
		if (UnBotSindragosaFindBossUnit()) then
			UnBotSindragosaBeginFight();
		end
		return;
	elseif (event == "PLAYER_REGEN_ENABLED") then
		if (UnBotSindragosaPrep.encounterActive) then
			UnBotSindragosaPrep.encounterEndCheckAt = GetTime() + 5;
		end
		return;
	end
	if (UnBotSindragosaIsTombTarget()) then
		UnBotSindragosaFocusSelectedTomb(true);
	end
end);
UnBotSindragosaFrame:SetScript("OnUpdate", function()
	local now = GetTime();
	if (
		UnBotSindragosaPrep.bubbleCenterHideAt
		and now >= UnBotSindragosaPrep.bubbleCenterHideAt
	) then
		UnBotSindragosaPrep.bubbleCenterHideAt = nil;
		if (UnBotSindragosaPrep.bubbleCenterFrame) then
			UnBotSindragosaPrep.bubbleCenterFrame:Hide();
		end
	end
	if (not UnBotBossPresetLoadedAutoStrategyEnabled("sindragosa")) then
		return;
	end
	if (UnBotSindragosaPrep.encounterActive) then
		local bossUnit = UnBotSindragosaFindBossUnit();
		if (
			bossUnit
			and UnitAffectingCombat(bossUnit)
		) then
			UnBotSindragosaPrep.encounterEndCheckAt = nil;
		elseif (
			UnBotSindragosaPrep.encounterEndCheckAt
			and now >= UnBotSindragosaPrep.encounterEndCheckAt
			and not UnitAffectingCombat("player")
		) then
			UnBotSindragosaRestoreIcc("бой завершён или произошёл вайп");
		end
		UnBotSindragosaUpdateBubbleReserve(now);
		UnBotSindragosaUpdateRetPaladinHealing(now);
		if (
			UnBotSindragosaPrep.retTankTauntAt
			and now >= UnBotSindragosaPrep.retTankTauntAt
		) then
			UnBotSindragosaSendRetTankTaunt();
		end
		if (
			UnBotSindragosaPrep.retTankExpiresAt
			and now >= UnBotSindragosaPrep.retTankExpiresAt
		) then
			UnBotSindragosaPrep.retTankExpiresAt = nil;
			UnBotSindragosaPrep.retTankTauntAt = nil;
			UnBotSpecSummonMessage(
				"Синдрагоса: 35 секунд ротации ретриков истекли; циклические команды остановлены. "
				.."Временный танк сохранён до ручного обратного таунта или конца боя."
			);
		end
		if (
			UnBotSindragosaPrep.bubbleCheckAt
			and now >= UnBotSindragosaPrep.bubbleCheckAt
		) then
			if (UnBotSindragosaPlayerHasDivineShield()) then
				UnBotSindragosaPrep.bubbleCheckAt = nil;
				UnBotSindragosaPrep.bubbleCheckUntil = nil;
				UnBotSpecSummonMessage(
					"Синдрагоса: Божественный щит подтверждён до раздачи воздушных меток."
				);
			elseif (
				now < (UnBotSindragosaPrep.bubbleCheckUntil or 0)
				and (tonumber(UnBotSindragosaPrep.bubbleWarningCount) or 0) < 3
			) then
				if (RaidNotice_AddMessage and RaidWarningFrame) then
					RaidNotice_AddMessage(
						RaidWarningFrame,
						"БАБЛ СЕЙЧАС — НАЧАЛАСЬ ВОЗДУШНАЯ ФАЗА!",
						ChatTypeInfo and ChatTypeInfo["RAID_WARNING"]
					);
				elseif (UIErrorsFrame) then
					UIErrorsFrame:AddMessage(
						"БАБЛ СЕЙЧАС — НАЧАЛАСЬ ВОЗДУШНАЯ ФАЗА!",
						1, 0.15, 0.15, 1
					);
				end
				if (PlaySound) then
					PlaySound("RaidWarning");
				end
				UnBotSindragosaPrep.bubbleWarningCount =
					(tonumber(UnBotSindragosaPrep.bubbleWarningCount) or 0) + 1;
				UnBotSindragosaPrep.bubbleCheckAt = now + 0.8;
			else
				UnBotSindragosaPrep.bubbleCheckAt = nil;
				UnBotSindragosaPrep.bubbleCheckUntil = nil;
				UnBotSpecSummonMessage(
					"Синдрагоса: Божественный щит не подтверждён в окне воздушной фазы."
				);
			end
		end
		if (
			UnBotSindragosaPrep.phaseThreeBossReturnAt
			and now >= UnBotSindragosaPrep.phaseThreeBossReturnAt
		) then
			local returnBossUnit = UnBotSindragosaFindBossUnit();
			UnBotSindragosaPrep.phaseThreeBossReturnAttempts =
				(tonumber(UnBotSindragosaPrep.phaseThreeBossReturnAttempts) or 0) + 1;
			if (returnBossUnit and SetRaidTarget) then
				SetRaidTarget(returnBossUnit, 5);
			end
			if (
				returnBossUnit
				and (
					not GetRaidTargetIndex
					or GetRaidTargetIndex(returnBossUnit) == 5
				)
			) then
				UnBotSindragosaBroadcast("@dps rti moon");
				UnBotSindragosaPrep.phaseThreeBossReturnAt = nil;
				UnBotSindragosaPrep.phaseThreeBossAttackAt = now + 0.3;
			elseif (UnBotSindragosaPrep.phaseThreeBossReturnAttempts < 4) then
				UnBotSindragosaPrep.phaseThreeBossReturnAt = now + 0.5;
			else
				UnBotSindragosaPrep.phaseThreeBossReturnAt = nil;
				UnBotSindragosaBroadcast("@dps rti moon");
				UnBotSindragosaPrep.phaseThreeBossAttackAt = now + 0.3;
				UnBotSpecSummonMessage(
					"Синдрагоса, фаза 3: повторная проверка moon на боссе исчерпана; "
					.."использую метку, сохранённую перед фокусом глыбы."
				);
			end
		end
		if (
			UnBotSindragosaPrep.phaseThreeBossAttackAt
			and now >= UnBotSindragosaPrep.phaseThreeBossAttackAt
		) then
			UnBotSindragosaPrep.phaseThreeBossAttackAt = nil;
			UnBotSindragosaBroadcast("@dps attack rti target");
			UnBotSindragosaBroadcast("@warlock pet attack");
			UnBotSpecSummonMessage(
				"Синдрагоса, фаза 3: ДД вернулись по moon и снова атакуют Синдрагосу."
			);
		end
		if (
			UnBotSindragosaPrep.encounterActive
			and now >= (UnBotSindragosaPrep.nextIccEnforceAt or 0)
		) then
			if (
				UnBotSindragosaHeroicBombHiding()
				or (
					UnBotSindragosaIsHeroic25()
					and not UnBotSindragosaPrep.heroicBombActive
					and (
						UnBotSindragosaPrep.airGatherPending
						or UnBotSindragosaPrep.spreadPrepared
						or UnBotSindragosaPrep.nonTankIccEnabled
					)
				)
			) then
				UnBotSindragosaBroadcast("co +icc");
				UnBotSindragosaBroadcast("nc +icc");
				UnBotSindragosaBroadcast("@warlock pet follow");
			elseif (
				UnBotSindragosaIsHeroic25()
				and UnBotSindragosaPrep.heroicBombActive
			) then
				UnBotSindragosaBroadcast("@dps co -icc");
				UnBotSindragosaBroadcast("@dps nc -icc");
				UnBotSindragosaBroadcast("@tank co -icc");
				UnBotSindragosaBroadcast("@tank nc -icc");
				UnBotSindragosaBroadcast("@heal co +icc");
				UnBotSindragosaBroadcast("@heal nc +icc");
			else
				UnBotSindragosaBroadcast("co -icc");
				UnBotSindragosaBroadcast("nc -icc");
			end
			if (
				UnBotSindragosaPrep.nonTankIccEnabled
				and not UnBotSindragosaPrep.heroicBombActive
			) then
				if (
					UnBotSindragosaPrep.postTombIccUntil
					and now < UnBotSindragosaPrep.postTombIccUntil
				) then
					UnBotSindragosaBroadcast("@dps co +icc");
					UnBotSindragosaBroadcast("@dps nc +icc");
					UnBotSindragosaBroadcast("@heal co +icc");
					UnBotSindragosaBroadcast("@heal nc +icc");
				else
					for name in pairs(UnBotSindragosaPrep.beaconBots or {}) do
						if (UnBotSindragosaUsePhaseThreeBeaconSeparation()) then
							UnBotSindragosaSetPhaseThreeBeaconBot(name, true);
						else
							UnBotSindragosaWhisperIcc(name, true);
						end
					end
				end
			end
			UnBotSindragosaPrep.nextIccEnforceAt = now + 12;
		end
		UnBotSindragosaEnforceUnchainedMagic(now);
		UnBotSindragosaUpdateHeroicBombCycle(now);
		UnBotSindragosaScanBeaconBots();
		if (
			UnBotSindragosaPrep.airPositionLockPending
			and UnBotSindragosaPrep.airPositionLockAt
			and now >= UnBotSindragosaPrep.airPositionLockAt
		) then
			UnBotSindragosaLockAirPositions(now);
		end
		if (UnBotSindragosaPrep.airPositionLocked) then
			if (
				UnBotSindragosaPrep.airPositionLockUntil
				and now >= UnBotSindragosaPrep.airPositionLockUntil
			) then
				UnBotSindragosaReleaseAirPositions("защитный таймаут");
			elseif (
				now >= (UnBotSindragosaPrep.nextAirPositionLockEnforceAt or 0)
			) then
				UnBotSindragosaBroadcast("co +passive");
				UnBotSindragosaBroadcast("@warlock pet follow");
				UnBotSindragosaPrep.nextAirPositionLockEnforceAt = now + 1.5;
			end
		end
		if (
			UnBotSindragosaPrep.airWarningAt
			and now >= UnBotSindragosaPrep.airWarningAt
		) then
			UnBotSindragosaPrep.airWarningAt = nil;
			if (not UnBotSindragosaIsPhaseThree()) then
				UnBotSindragosaShowAirWarning();
			end
		end
		if (
			UnBotSindragosaPrep.airGatherPending
			and UnBotSindragosaPrep.airSpreadAt
			and now >= UnBotSindragosaPrep.airSpreadAt
		) then
			UnBotSindragosaPrep.airGatherPending = false;
			UnBotSindragosaPrep.airSpreadAt = nil;
			UnBotSindragosaPrepareAirSpread(
				"после общего summon в начале воздушной фазы",
				false
			);
		end
		if (
			UnBotSindragosaPrep.phaseThreeDiscoveryAt
			and now >= UnBotSindragosaPrep.phaseThreeDiscoveryAt
		) then
			UnBotSindragosaTriggerPhaseThreeTombDiscovery();
		end
		UnBotSindragosaMarkVisibleTombs();
		if (
			UnBotSindragosaPrep.directTombAttackAt
			and now >= UnBotSindragosaPrep.directTombAttackAt
		) then
			UnBotSindragosaSendDirectTombAttack();
		end
		if (
			UnBotSindragosaPrep.nonTankIccEnabled
			and UnBotSindragosaPrep.disableNonTankIccAt
			and now >= UnBotSindragosaPrep.disableNonTankIccAt
			and not next(UnBotSindragosaPrep.beaconBots or {})
		) then
			UnBotSindragosaDisableNonTankIcc();
		end
		if (
			UnBotSindragosaPrep.tombAttackIcon
			and UnBotSindragosaPrep.pendingTombAttackAt
			and now >= UnBotSindragosaPrep.pendingTombAttackAt
			and not UnBotSindragosaHeroicBombHiding()
			and not (
				UnBotSindragosaPrep.retTankName
				and not UnBotSindragosaPrep.retTankPlayerReset
			)
		) then
			if (not UnBotSindragosaPrep.tombAttackTargetSent) then
				if (UnBotSindragosaPrep.phaseThreeTombFocusActive) then
					UnBotSindragosaBroadcast("@dps co +mark rti");
				else
					UnBotSindragosaBroadcast(
						"@dps rti "..UnBotSindragosaPrep.tombAttackIcon
					);
				end
				if (
					UnBotSindragosaPrep.playerTombRescue
					or not UnBotSindragosaIsPhaseThree()
				) then
					UnBotSindragosaBroadcast(
						"@tank rti "..UnBotSindragosaPrep.tombAttackIcon
					);
				end
				UnBotSindragosaPrep.tombAttackTargetSent = true;
				UnBotSindragosaPrep.pendingTombAttackAt = now + 0.3;
			else
				if (UnBotSindragosaPrep.phaseThreeTombFocusActive) then
					UnBotSindragosaBroadcast(
						"@dps co -passive,+aoe,+mark rti,-icc"
					);
				end
				UnBotSindragosaBroadcast("@dps attack rti target");
				UnBotSindragosaBroadcast("@warlock pet follow");
				UnBotSindragosaBroadcast("@warlock pet attack");
				if (
					UnBotSindragosaPrep.playerTombRescue
					or not UnBotSindragosaIsPhaseThree()
				) then
					UnBotSindragosaBroadcast("@tank attack rti target");
				end
				if (next(UnBotSindragosaPrep.unchainedBots or {})) then
					UnBotSindragosaPrep.nextUnchainedEnforceAt = 0;
					UnBotSindragosaEnforceUnchainedMagic(now);
				end
				UnBotSindragosaPrep.pendingTombAttackAt = nil;
				UnBotSindragosaPrep.tombAttackTargetSent = false;
				UnBotSindragosaPrep.tombAttackAttempts =
					(tonumber(UnBotSindragosaPrep.tombAttackAttempts) or 0) + 1;
				UnBotSindragosaPrep.tombAttackRepeatAt = now + 0.8;
			end
		elseif (
			UnBotSindragosaPrep.tombAttackIcon
			and not UnBotSindragosaPrep.pendingTombAttackAt
			and now >= (UnBotSindragosaPrep.tombAttackRepeatAt or 0)
			and not UnBotSindragosaHeroicBombHiding()
			and (tonumber(UnBotSindragosaPrep.tombAttackAttempts) or 0)
				< UnBotSindragosaTombAttackMaxAttempts()
		) then
			UnBotSindragosaPrep.pendingTombAttackAt = now + 0.25;
			UnBotSindragosaPrep.tombAttackRepeatAt = 0;
			UnBotSindragosaPrep.tombAttackTargetSent = false;
		elseif (
			UnBotSindragosaPrep.tombAttackIcon
			and not UnBotSindragosaPrep.pendingTombAttackAt
			and not UnBotSindragosaHeroicBombHiding()
			and (tonumber(UnBotSindragosaPrep.tombAttackAttempts) or 0)
				>= UnBotSindragosaTombAttackMaxAttempts()
			and (UnBotSindragosaPrep.tombAttackRepeatAt or 0) > 0
		) then
			UnBotSindragosaPrep.tombAttackRepeatAt = 0;
			UnBotSindragosaPrep.tombAttackTargetSent = false;
			UnBotSpecSummonMessage(
				"Синдрагоса: автоматические попытки атаки исчерпаны; при необходимости выделите глыбу вручную."
			);
		end
		if (
			UnBotSindragosaPrep.encounterActive
			and UnBotSindragosaIsTombTarget()
		) then
			UnBotSindragosaFocusSelectedTomb(false);
		end
	end
	if (
		UnBotSindragosaPrep.armed
		and now >= (UnBotSindragosaPrep.readyAt or 0)
		and not UnBotSpecSummon.active
		and not UnBotSquadSpecCheck.active
		and (UnBotSquadSpecCheck.autoStartAt or 0) <= 0
	) then
		UnBotSindragosaStartSoulstones();
	end
	if (
		not UnBotSindragosaPrep.active
		or now < (UnBotSindragosaPrep.nextTime or 0)
	) then
		if (
			UnBotSindragosaPrep.maintenance
			and not UnBotSindragosaPrep.active
			and UnBotSindragosaPrep.stage == "monitor"
			and now >= (UnBotSindragosaPrep.monitorNext or 0)
		) then
			UnBotSindragosaPrep.monitorNext = now + 5;
			local present = 0;
			for name in pairs(UnBotSindragosaPrep.assignedNames or {}) do
				local unit = UnBotBuffCycleResolveUnit(name);
				if (unit and UnitIsConnected(unit)) then
					present = present + 1;
				end
			end
			if (present < 2) then
				UnBotSindragosaPrep.maintenance = false;
				UnBotSindragosaPrep.stage = "idle";
				if (not UnBotSindragosaPrep.encounterActive) then
					UnBotSindragosaPrep.focusEnabled = false;
					UnBotSpecSummonMessage(
						"Подготовка Синдрагосы отключена: исходный состав распущен."
					);
				end
			end
		end
		return;
	end

	if (UnBotSindragosaPrep.stage == "quiesce") then
		for _, assignment in ipairs(UnBotSindragosaPrep.assignments or {}) do
			local unit = UnBotBuffCycleResolveUnit(assignment.name);
			if (unit and UnitIsConnected(unit)) then
				UnBotBuffCycleSendWhisper(
					assignment.name,
					"nc -ss master,-ss self,-ss tank,-ss healer"
				);
			end
		end
		UnBotSindragosaPrep.stage = "assign";
		UnBotSindragosaPrep.index = 1;
		UnBotSindragosaPrep.nextTime = now + 1.5;
	elseif (UnBotSindragosaPrep.stage == "assign") then
		local assignment = UnBotSindragosaPrep.assignments[UnBotSindragosaPrep.index];
		if (assignment) then
			local unit = UnBotBuffCycleResolveUnit(assignment.name);
			if (unit and UnitIsConnected(unit)) then
				UnBotBuffCycleSendWhisper(assignment.name, "summon");
				UnBotBuffCycleSendWhisper(assignment.name, "stay");
				UnBotBuffCycleSendWhisper(
					assignment.name,
					"nc -ss master,-ss self,-ss tank,-ss healer,+ss "..assignment.role
				);
				UnBotBuffCycleSendWhisper(
					assignment.name,
					"cast 47883 on "..assignment.targetName
				);
				UnBotSpecSummonMessage(
					"Soulstone: "..assignment.name.." -> "..assignment.targetName
					.." ["..assignment.role.."]"
					.." ("..tostring(UnBotSindragosaPrep.index)
					.."/"..tostring(#UnBotSindragosaPrep.assignments)..")."
				);
			end
			UnBotSindragosaPrep.index = UnBotSindragosaPrep.index + 1;
			UnBotSindragosaPrep.nextTime = now + 0.8;
		else
			UnBotSindragosaPrep.stage = "verify";
			UnBotSindragosaPrep.nextTime = now + 6;
		end
	elseif (UnBotSindragosaPrep.stage == "verify") then
		local covered, casters, coverageByName = UnBotSindragosaSoulstoneCoverage();
		local exactCount = 0;
		local exactLabels = {};
		for _, assignment in ipairs(UnBotSindragosaPrep.assignments or {}) do
			if (coverageByName[assignment.targetName] == assignment.name) then
				exactCount = exactCount + 1;
				table.insert(
					exactLabels,
					assignment.targetName.." <- "..assignment.name
				);
				if (not UnBotSindragosaPrep.confirmedCasters[assignment.name]) then
					UnBotSindragosaPrep.confirmedCasters[assignment.name] = true;
					UnBotRegistryMarkSoulstoneCooldown(assignment.name);
				end
			end
		end
		for casterName in pairs(casters) do
			if (
				not UnBotSindragosaPrep.assignedNames[casterName]
			) then
				UnBotSpecSummonMessage(
					"Синдрагоса: обнаружен Soulstone от незапланированного кастера "
					..casterName.."; в точное подтверждение он не засчитан."
				);
			end
		end
		if (exactCount >= #UnBotSindragosaPrep.assignments) then
			UnBotSindragosaStopSoulstone(
				"Синдрагоса: точные Soulstone подтверждены "
				..tostring(exactCount).."/"..tostring(#UnBotSindragosaPrep.assignments)
				..": "..table.concat(exactLabels, ", ")
				..". Варлоки остаются в рейде.",
				true
			);
		elseif (UnBotSindragosaPrep.attempt < 4) then
			UnBotSindragosaPrep.attempt = UnBotSindragosaPrep.attempt + 1;
			UnBotSindragosaPrep.index = 1;
			UnBotSindragosaPrep.stage = "assign";
			UnBotSindragosaPrep.nextTime = now;
			UnBotSpecSummonMessage(
				"Синдрагоса: точно подтверждено Soulstone "..tostring(exactCount)
				.."/"..tostring(#UnBotSindragosaPrep.assignments)
				.."; ограниченный повтор "..tostring(UnBotSindragosaPrep.attempt).."/4."
			);
		else
			UnBotSindragosaStopSoulstone(
				"Синдрагоса: раздача завершена без бесконечного повтора. Точно подтверждено "
				..tostring(exactCount).."/"..tostring(#UnBotSindragosaPrep.assignments)
				..(exactCount > 0 and (": "..table.concat(exactLabels, ", ")) or "")
				.."; всего камней на рейде "..tostring(#covered)
				..". Стратегии остаются включены и могут сработать после cooldown.",
				true
			);
		end
	end
end);

UnBotSaurfangBeastFocus = {
	active = false,
	currentGuid = nil,
	currentSeenAt = 0,
	spawned = 0,
	killed = 0,
	nextScanAt = 0,
	nextCommandAt = 0,
	commandPhase = "target",
	activeUntil = 0,
	lastAnnounceAt = 0,
};

function UnBotSaurfangNameIsBeast(name)
	local originalName = tostring(name or "");
	name = UnBotSpecSummonNormalize(originalName);
	return (
		string.find(name, "blood beast", 1, true)
		or string.find(originalName, "Кровавое чудовище", 1, true)
		or string.find(name, "кровавое чудовище", 1, true)
	) and true or false;
end

function UnBotSaurfangVisibleBeastUnit()
	local units = {"target", "focus", "mouseover"};
	local raidCount = GetNumRaidMembers() or 0;
	if (raidCount > 0) then
		for i = 1, math.min(40, raidCount), 1 do
			table.insert(units, "raid"..i.."target");
		end
	else
		for i = 1, math.min(4, GetNumPartyMembers() or 0), 1 do
			table.insert(units, "party"..i.."target");
		end
	end

	local fallback = nil;
	for _, unit in ipairs(units) do
		if (
			UnitExists(unit)
			and not UnitIsDeadOrGhost(unit)
			and UnBotSaurfangNameIsBeast(UnitName(unit))
		) then
			local guid = UnitGUID(unit);
			if (
				guid
				and guid == UnBotSaurfangBeastFocus.currentGuid
			) then
				return unit;
			end
			fallback = fallback or unit;
		end
	end
	return fallback;
end

function UnBotSaurfangAcquireBeast()
	local unit = UnBotSaurfangVisibleBeastUnit();
	if (not unit) then
		return false;
	end
	local guid = UnitGUID(unit);
	if (not guid) then
		return false;
	end
	local changed = guid ~= UnBotSaurfangBeastFocus.currentGuid;
	UnBotSaurfangBeastFocus.currentGuid = guid;
	UnBotSaurfangBeastFocus.currentSeenAt = GetTime();
	if (
		SetRaidTarget
		and GetRaidTargetIndex
		and GetRaidTargetIndex(unit) ~= 8
	) then
		SetRaidTarget(unit, 8);
	end
	if (changed) then
		UnBotSaurfangBeastFocus.commandPhase = "target";
		UnBotSaurfangBeastFocus.nextCommandAt = 0;
		UnBotSpecSummonMessage(
			"Саурфанг: кровавое чудовище отмечено черепом; "
			.."все ДД переключаются в одиночную цель."
		);
	end
	return true;
end

function UnBotSaurfangStartBeastFocus()
	UnBotSaurfangBeastFocus.active = true;
	UnBotSaurfangBeastFocus.activeUntil = GetTime() + 30;
	UnBotSaurfangBeastFocus.nextScanAt = 0;
	UnBotSaurfangBeastFocus.spawned =
		(tonumber(UnBotSaurfangBeastFocus.spawned) or 0) + 1;
end

function UnBotSaurfangStopBeastFocus(message)
	if (message and UnBotSaurfangBeastFocus.active) then
		UnBotSpecSummonMessage(message);
	end
	UnBotSaurfangBeastFocus.active = false;
	UnBotSaurfangBeastFocus.currentGuid = nil;
	UnBotSaurfangBeastFocus.currentSeenAt = 0;
	UnBotSaurfangBeastFocus.nextScanAt = 0;
	UnBotSaurfangBeastFocus.nextCommandAt = 0;
	UnBotSaurfangBeastFocus.commandPhase = "target";
	UnBotSaurfangBeastFocus.activeUntil = 0;
end

UnBotSaurfangBeastFrame = CreateFrame(
	"Frame",
	"UnBotSaurfangBeastFrame"
);
UnBotSaurfangBeastFrame:RegisterEvent("COMBAT_LOG_EVENT_UNFILTERED");
UnBotSaurfangBeastFrame:RegisterEvent("RAID_TARGET_UPDATE");
UnBotSaurfangBeastFrame:RegisterEvent("PLAYER_REGEN_ENABLED");
UnBotSaurfangBeastFrame:SetScript("OnEvent", function(self, event, ...)
	if (event == "PLAYER_REGEN_ENABLED") then
		UnBotSaurfangStopBeastFocus(
			"Саурфанг: бой завершён; фокус кровавых чудовищ остановлен."
		);
		UnBotSaurfangBeastFocus.spawned = 0;
		UnBotSaurfangBeastFocus.killed = 0;
		return;
	elseif (event == "RAID_TARGET_UPDATE") then
		if (UnBotSaurfangBeastFocus.active) then
			UnBotSaurfangBeastFocus.nextScanAt = 0;
		end
		return;
	end
	if (not UnBotBossPresetLoadedAutoStrategyEnabled("deathbringer_saurfang")) then
		return;
	end

	local eventType = select(2, ...);
	local destinationGuid = select(6, ...);
	local destinationName = select(7, ...);
	if (
		eventType == "SPELL_SUMMON"
		and UnBotSaurfangNameIsBeast(destinationName)
	) then
		UnBotSaurfangStartBeastFocus();
	elseif (
		(eventType == "UNIT_DIED" or eventType == "PARTY_KILL")
		and UnBotSaurfangNameIsBeast(destinationName)
	) then
		UnBotSaurfangBeastFocus.killed =
			(tonumber(UnBotSaurfangBeastFocus.killed) or 0) + 1;
		if (
			not destinationGuid
			or destinationGuid == UnBotSaurfangBeastFocus.currentGuid
		) then
			UnBotSaurfangBeastFocus.currentGuid = nil;
			UnBotSaurfangBeastFocus.currentSeenAt = 0;
			UnBotSaurfangBeastFocus.commandPhase = "target";
			UnBotSaurfangBeastFocus.nextCommandAt = 0;
		end
		UnBotSaurfangBeastFocus.activeUntil = GetTime() + 8;
		UnBotSaurfangBeastFocus.nextScanAt = 0;
	end
end);

UnBotSaurfangBeastFrame:SetScript("OnUpdate", function()
	if (not UnBotSaurfangBeastFocus.active) then
		return;
	end
	local now = GetTime();
	if (now >= (UnBotSaurfangBeastFocus.nextScanAt or 0)) then
		UnBotSaurfangBeastFocus.nextScanAt = now + 0.15;
		UnBotSaurfangAcquireBeast();
	end

	if (
		UnBotSaurfangBeastFocus.currentGuid
		and now - (UnBotSaurfangBeastFocus.currentSeenAt or 0) > 4
	) then
		UnBotSaurfangBeastFocus.currentGuid = nil;
		UnBotSaurfangBeastFocus.commandPhase = "target";
		UnBotSaurfangBeastFocus.nextCommandAt = 0;
	end

	if (
		not UnBotSaurfangBeastFocus.currentGuid
		and now >= (UnBotSaurfangBeastFocus.activeUntil or 0)
	) then
		UnBotSaurfangStopBeastFocus(
			"Саурфанг: волна чудовищ закончена — ДД возвращаются к обычной стратегии."
		);
		return;
	end
	if (
		not UnBotSaurfangBeastFocus.currentGuid
		or now < (UnBotSaurfangBeastFocus.nextCommandAt or 0)
	) then
		return;
	end

	if (UnBotSaurfangBeastFocus.commandPhase == "target") then
		UnBotSindragosaBroadcast("@dps rti skull");
		UnBotSaurfangBeastFocus.commandPhase = "attack";
		UnBotSaurfangBeastFocus.nextCommandAt = now + 0.25;
	else
		-- This is deliberately the direct single-target chat command.
		-- "do attack rti target" is a different action and is rejected.
		UnBotSindragosaBroadcast("@dps attack rti target");
		UnBotSaurfangBeastFocus.commandPhase = "target";
		UnBotSaurfangBeastFocus.nextCommandAt = now + 0.9;
	end
end);

UnBotMarrowgarRescue = {
	active = false,
	presetArmed = false,
	presetMode = nil,
	iccSuppressed = false,
	encounterActive = false,
	nextIccEnforceAt = 0,
	impaled = {},
	nextScanAt = 0,
	nextCommandAt = 0,
	rescueUntil = 0,
	commandPhase = "discover",
	lastHelperSignature = nil,
	startedAt = 0,
	helperSet = {},
	confirmedHelpers = {},
	confirmedAny = false,
	boneStormActive = false,
	boneStormUntil = 0,
	nextStormAoeAt = 0,
	stormAoeAnnounced = false,
	lastStormSpikeCastAt = 0,
	lastImpaledCount = 0,
	nextSpikePreAoeAt = 0,
	lastPaladinSpikeAoeAt = 0,
	lastDeathKnightSpikeAoeAt = 0,
	lastDeathKnightSpikeBurstAt = 0,
};

function UnBotMarrowgarEnableStormAoe(force, reason)
	local state = UnBotMarrowgarRescue;
	local now = GetTime();
	if (not force and now < (state.nextStormAoeAt or 0)) then
		return false;
	end
	local sent = false;
	if (UnBotSindragosaBroadcast("@tank co +aoe")) then
		sent = true;
	end
	if (UnBotSindragosaBroadcast("@dps co +aoe")) then
		sent = true;
	end
	if (not sent) then
		return false;
	end
	state.nextStormAoeAt = now + 5;
	if (reason and not state.stormAoeAnnounced) then
		state.stormAoeAnnounced = true;
		UnBotSpecSummonMessage(reason);
	end
	return true;
end

function UnBotMarrowgarCommandSpikeAoe(reason)
	local state = UnBotMarrowgarRescue;
	local now = GetTime();
	local sent = false;
	-- Consecration lasts eight seconds. Outside Bone Storm the real three-second
	-- cast event places it; during Bone Storm the 15-20s forecast places it early.
	if (now - (state.lastPaladinSpikeAoeAt or 0) >= 8) then
		if (UnBotSindragosaBroadcast("@paladin cast Consecration")) then
			state.lastPaladinSpikeAoeAt = now;
			sent = true;
		end
	end
	-- Death and Decay persists long enough to cover the full DBM 15-20s window,
	-- but has a long cooldown. Never retry it on every spike while it is unavailable.
	if (now - (state.lastDeathKnightSpikeAoeAt or 0) >= 30) then
		if (UnBotSindragosaBroadcast("@dk cast Death and Decay")) then
			state.lastDeathKnightSpikeAoeAt = now;
			sent = true;
		end
	end
	if (sent and reason) then
		UnBotSpecSummonMessage(reason);
	end
	return sent;
end

function UnBotMarrowgarCommandHiddenSpikeBurst()
	local state = UnBotMarrowgarRescue;
	local now = GetTime();
	if (now - (state.lastDeathKnightSpikeBurstAt or 0) < 1) then
		return false;
	end
	if (not UnBotSindragosaBroadcast("@dk cast Blood Boil")) then
		return false;
	end
	state.lastDeathKnightSpikeBurstAt = now;
	return true;
end

function UnBotMarrowgarSuppressIcc(force)
	if (UnBotMarrowgarRescue.iccSuppressed and not force) then
		return;
	end
	if (not UnBotSindragosaBroadcast("co -icc")) then
		return;
	end
	UnBotSindragosaBroadcast("nc -icc");
	UnBotMarrowgarRescue.iccSuppressed = true;
	UnBotMarrowgarRescue.nextIccEnforceAt = GetTime() + 12;
	if (not force) then
		UnBotSpecSummonMessage(
			"Ребрад: стратегия icc отключена — группа остаётся в позиции игрока/танка."
		);
	end
end

function UnBotMarrowgarRestoreIcc(silent)
	if (not UnBotMarrowgarRescue.iccSuppressed) then
		return;
	end
	UnBotSindragosaBroadcast("co +icc");
	UnBotSindragosaBroadcast("nc +icc");
	UnBotMarrowgarRescue.iccSuppressed = false;
	UnBotMarrowgarRescue.nextIccEnforceAt = 0;
	if (not silent) then
		UnBotSpecSummonMessage("Ребрад: бой окончен, стратегия icc возвращена.");
	end
end

function UnBotMarrowgarArmPreset(modeKey)
	UnBotMarrowgarRescue.presetArmed = true;
	UnBotMarrowgarRescue.presetMode = modeKey;
	UnBotMarrowgarRescue.nextSpikePreAoeAt = 0;
	UnBotMarrowgarRescue.lastPaladinSpikeAoeAt = 0;
	UnBotMarrowgarRescue.lastDeathKnightSpikeAoeAt = 0;
	UnBotMarrowgarRescue.lastDeathKnightSpikeBurstAt = 0;
	UnBotMarrowgarSuppressIcc(false);
end

function UnBotMarrowgarDisarmPreset(restoreIcc)
	UnBotMarrowgarRescue.presetArmed = false;
	UnBotMarrowgarRescue.presetMode = nil;
	UnBotMarrowgarRescue.encounterActive = false;
	UnBotMarrowgarRescue.boneStormActive = false;
	UnBotMarrowgarRescue.boneStormUntil = 0;
	UnBotMarrowgarRescue.nextStormAoeAt = 0;
	UnBotMarrowgarRescue.stormAoeAnnounced = false;
	UnBotMarrowgarRescue.lastStormSpikeCastAt = 0;
	UnBotMarrowgarRescue.lastImpaledCount = 0;
	UnBotMarrowgarRescue.nextSpikePreAoeAt = 0;
	UnBotMarrowgarRescue.lastPaladinSpikeAoeAt = 0;
	UnBotMarrowgarRescue.lastDeathKnightSpikeAoeAt = 0;
	UnBotMarrowgarRescue.lastDeathKnightSpikeBurstAt = 0;
	if (restoreIcc) then
		UnBotMarrowgarRestoreIcc(true);
	end
end

function UnBotMarrowgarNameMatches(name)
	name = UnBotSpecSummonNormalize(name);
	return (
		string.find(name, "lord marrowgar", 1, true)
		or string.find(name, "лорд ребрад", 1, true)
	) and true or false;
end

function UnBotMarrowgarFindBossUnit()
	local units = {"boss1", "boss2", "boss3", "boss4", "focus", "target", "targettarget"};
	for _, unit in ipairs(units) do
		if (UnitExists(unit) and UnBotMarrowgarNameMatches(UnitName(unit))) then
			return unit;
		end
	end
	for i = 1, math.min(40, GetNumRaidMembers() or 0), 1 do
		local unit = "raid"..i.."target";
		if (UnitExists(unit) and UnBotMarrowgarNameMatches(UnitName(unit))) then
			return unit;
		end
	end
	for i = 1, math.min(4, GetNumPartyMembers() or 0), 1 do
		local unit = "party"..i.."target";
		if (UnitExists(unit) and UnBotMarrowgarNameMatches(UnitName(unit))) then
			return unit;
		end
	end
	return nil;
end

function UnBotMarrowgarIsHealer(name)
	local profile = UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	local className = UnBotSpecSummonNormalize(
		(profile and profile.className) or UnBotBuffCycleTargetClass(name)
	);
	local specName = UnBotSpecSummonNormalize(profile and profile.specName);
	if (className == "paladin") then
		return specName == "holy";
	elseif (className == "priest") then
		return specName == "holy" or specName == "discipline";
	elseif (className == "shaman" or className == "druid") then
		return specName == "restoration";
	end
	return false;
end

function UnBotMarrowgarScanImpaled()
	local seen = {};
	local function scan(name, unit)
		if (
			name
			and unit
			and UnitExists(unit)
			and UnBotSindragosaUnitHasDebuff(unit, 69065)
		) then
			seen[UnitGUID(unit) or name] = name;
		end
	end
	scan(UnitName("player"), "player");
	UnBotBuffCycleForEachGroupMember(scan);
	UnBotMarrowgarRescue.impaled = seen;
	return next(seen) ~= nil;
end

function UnBotMarrowgarImpaledNames()
	local names = {};
	for _, name in pairs(UnBotMarrowgarRescue.impaled or {}) do
		table.insert(names, name);
	end
	table.sort(names);
	return names;
end

function UnBotMarrowgarHelperNames()
	local bossUnit = UnBotMarrowgarFindBossUnit();
	local mainTankName = bossUnit and UnitName(bossUnit.."target") or nil;
	local preferred = {};
	local healers = {};
	local playerName = UnitName("player");
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		local profile = UnBotBotRegistry and UnBotBotRegistry.bots
			and UnBotBotRegistry.bots[name];
		if (
			name
			and unit
			and UnitExists(unit)
			and UnitIsConnected(unit)
			and profile
			and name ~= playerName
			and not UnitIsDeadOrGhost(unit)
			and not UnBotSindragosaUnitHasDebuff(unit, 69065)
		) then
			if (name == mainTankName) then
				-- The main tank must keep Marrowgar facing away from the group.
			elseif (UnBotMarrowgarIsHealer(name)) then
				table.insert(healers, name);
			else
				table.insert(preferred, name);
			end
		end
	end);
	table.sort(preferred);
	table.sort(healers);
	if (#preferred > 0) then
		return preferred, "ДД/оффтанк";
	elseif (#healers > 0) then
		return healers, "аварийно хил";
	end
	return {}, "нет свободных ботов";
end

function UnBotMarrowgarHelperNamesWithEscalation()
	local helpers, helperRole = UnBotMarrowgarHelperNames();
	local now = GetTime();
	if (
		#helpers > 0
		and helperRole == "ДД/оффтанк"
		and not UnBotMarrowgarRescue.confirmedAny
		and now - (UnBotMarrowgarRescue.startedAt or now) >= 1.8
	) then
		local helperSet = {};
		for _, name in ipairs(helpers) do
			helperSet[name] = true;
		end
		UnBotBuffCycleForEachGroupMember(function(name, unit)
			local profile = UnBotBotRegistry and UnBotBotRegistry.bots
				and UnBotBotRegistry.bots[name];
			if (
				name
				and unit
				and UnitExists(unit)
				and UnitIsConnected(unit)
				and profile
				and name ~= UnitName("player")
				and not UnitIsDeadOrGhost(unit)
				and not UnBotSindragosaUnitHasDebuff(unit, 69065)
				and UnBotMarrowgarIsHealer(name)
				and not helperSet[name]
			) then
				table.insert(helpers, name);
				helperSet[name] = true;
			end
		end);
		table.sort(helpers);
		if (#helpers > 1) then
			helperRole = "эскалация: оффтанк/ДД + хил";
		end
	end
	return helpers, helperRole;
end

function UnBotMarrowgarIsSpikeName(name)
	name = UnBotSpecSummonNormalize(name);
	return (
		string.find(name, "bone spike", 1, true)
		or string.find(name, "костяной шип", 1, true)
	) and true or false;
end

function UnBotMarrowgarConfirmedNames()
	local names = {};
	for name in pairs(UnBotMarrowgarRescue.confirmedHelpers or {}) do
		table.insert(names, name);
	end
	table.sort(names);
	return names;
end

function UnBotMarrowgarStartRescue(destinationGuid, destinationName)
	local wasActive = UnBotMarrowgarRescue.active;
	if (destinationName) then
		UnBotMarrowgarRescue.impaled[destinationGuid or destinationName] = destinationName;
	end
	local impaledCount = 0;
	for _ in pairs(UnBotMarrowgarRescue.impaled or {}) do
		impaledCount = impaledCount + 1;
	end
	if (UnBotMarrowgarRescue.boneStormActive or impaledCount > 1) then
		UnBotMarrowgarEnableStormAoe(false);
	end
	if (
		impaledCount > 1
		and impaledCount > (UnBotMarrowgarRescue.lastImpaledCount or 0)
	) then
		UnBotSpecSummonMessage(
			"|cffff6633Ребрад: одновременно на шипах "..tostring(impaledCount)
			.." цели — танки и ДД продолжают AoE, адресный фокус сохранён.|r"
		);
	end
	UnBotMarrowgarRescue.lastImpaledCount = impaledCount;
	UnBotMarrowgarRescue.active = true;
	UnBotMarrowgarRescue.rescueUntil = GetTime() + 18;
	UnBotMarrowgarRescue.nextScanAt = 0;
	if (not wasActive) then
		UnBotMarrowgarRescue.nextCommandAt = 0;
		UnBotMarrowgarRescue.commandPhase = "discover";
		UnBotMarrowgarRescue.lastHelperSignature = nil;
		UnBotMarrowgarRescue.startedAt = GetTime();
		UnBotMarrowgarRescue.helperSet = {};
		UnBotMarrowgarRescue.confirmedHelpers = {};
		UnBotMarrowgarRescue.confirmedAny = false;
		UnBotSpecSummonMessage(
			"Ребрад: шип на "..tostring(destinationName or "?")
			.."; запускаю принудительное освобождение."
		);
	end
end

function UnBotMarrowgarStopRescue(message)
	if (not UnBotMarrowgarRescue.active) then
		return;
	end
	UnBotMarrowgarRescue.active = false;
	UnBotMarrowgarRescue.impaled = {};
	UnBotMarrowgarRescue.nextScanAt = 0;
	UnBotMarrowgarRescue.nextCommandAt = 0;
	UnBotMarrowgarRescue.rescueUntil = 0;
	UnBotMarrowgarRescue.commandPhase = "discover";
	UnBotMarrowgarRescue.lastHelperSignature = nil;
	UnBotMarrowgarRescue.startedAt = 0;
	UnBotMarrowgarRescue.helperSet = {};
	UnBotMarrowgarRescue.confirmedHelpers = {};
	UnBotMarrowgarRescue.confirmedAny = false;
	UnBotMarrowgarRescue.lastImpaledCount = 0;
	if (message) then
		UnBotSpecSummonMessage(message);
	end
end

UnBotMarrowgarFrame = CreateFrame("Frame", "UnBotMarrowgarFrame");
UnBotMarrowgarFrame:RegisterEvent("COMBAT_LOG_EVENT_UNFILTERED");
UnBotMarrowgarFrame:RegisterEvent("PLAYER_REGEN_ENABLED");
UnBotMarrowgarFrame:RegisterEvent("PLAYER_REGEN_DISABLED");
UnBotMarrowgarFrame:SetScript("OnEvent", function(self, event, ...)
	if (event == "PLAYER_REGEN_ENABLED") then
		if (UnBotMarrowgarRescue.active) then
			UnBotMarrowgarRescue.rescueUntil = math.min(
				UnBotMarrowgarRescue.rescueUntil or 0,
				GetTime() + 2
			);
		end
		if (UnBotMarrowgarRescue.encounterActive) then
			UnBotMarrowgarRescue.encounterActive = false;
			UnBotMarrowgarRestoreIcc(false);
		end
		UnBotMarrowgarRescue.boneStormActive = false;
		UnBotMarrowgarRescue.boneStormUntil = 0;
		UnBotMarrowgarRescue.nextStormAoeAt = 0;
		UnBotMarrowgarRescue.stormAoeAnnounced = false;
		UnBotMarrowgarRescue.lastStormSpikeCastAt = 0;
		UnBotMarrowgarRescue.lastImpaledCount = 0;
		UnBotMarrowgarRescue.nextSpikePreAoeAt = 0;
		return;
	elseif (event == "PLAYER_REGEN_DISABLED") then
		if (
			UnBotMarrowgarRescue.presetArmed
			and UnBotMarrowgarFindBossUnit()
		) then
			UnBotMarrowgarRescue.encounterActive = true;
			-- Normal spikes expose a three-second cast and are handled directly.
			-- Forecasting is only needed once Bone Storm hides that cast window.
			UnBotMarrowgarRescue.nextSpikePreAoeAt = 0;
			UnBotMarrowgarSuppressIcc(true);
		end
		return;
	end
	local eventType = select(2, ...);
	local sourceName = select(4, ...);
	local destinationGuid = select(6, ...);
	local destinationName = select(7, ...);
	local spellId = tonumber((select(9, ...)));
	if (
		UnBotMarrowgarRescue.presetArmed
		and
		(eventType == "SPELL_CAST_START" or eventType == "SPELL_AURA_APPLIED")
		and spellId == 69076
	) then
		local wasStormActive = UnBotMarrowgarRescue.boneStormActive;
		UnBotMarrowgarRescue.boneStormActive = true;
		UnBotMarrowgarRescue.boneStormUntil = GetTime() + 35;
		if (not wasStormActive) then
			UnBotMarrowgarRescue.stormAoeAnnounced = false;
			local secondsToForecast =
				(UnBotMarrowgarRescue.nextSpikePreAoeAt or 0) - GetTime();
			if (secondsToForecast <= 0 or secondsToForecast >= 8) then
				UnBotMarrowgarCommandSpikeAoe(
					"|cffff6633Ребрад: начало Вихря — заранее поставлены Освящение паладина и Смерть и разложение ДК.|r"
				);
			end
			UnBotMarrowgarEnableStormAoe(
				true,
				"|cffff6633Ребрад: Вихрь костей — танкам и ДД включён AoE на случай скрытых героических шипов.|r"
			);
		else
			UnBotMarrowgarEnableStormAoe(false);
		end
	elseif (eventType == "SPELL_AURA_REMOVED" and spellId == 69076) then
		UnBotMarrowgarRescue.boneStormActive = false;
		UnBotMarrowgarRescue.boneStormUntil = 0;
		UnBotMarrowgarRescue.nextStormAoeAt = 0;
		UnBotMarrowgarRescue.stormAoeAnnounced = false;
	elseif (
		UnBotMarrowgarRescue.presetArmed
		and eventType == "SPELL_CAST_START"
		and (
			spellId == 69057
			or spellId == 70826
			or spellId == 72088
			or spellId == 72089
			or spellId == 73144
			or spellId == 73145
		)
	) then
		local now = GetTime();
		UnBotMarrowgarRescue.nextSpikePreAoeAt = now + 12.7;
		UnBotMarrowgarCommandSpikeAoe(
			"|cffff6633Ребрад: каст шипов — паладинам приказано Освящение, ДК — Смерть и разложение.|r"
		);
		if (
			UnBotMarrowgarRescue.boneStormActive
			and now - (UnBotMarrowgarRescue.lastStormSpikeCastAt or 0) >= 0.8
		) then
			UnBotMarrowgarRescue.lastStormSpikeCastAt = now;
			UnBotMarrowgarCommandHiddenSpikeBurst();
			UnBotSpecSummonMessage(
				"|cffff6633Ребрад: скрытый каст шипов во время Вихря — ДК дополнительно получил Blood Boil.|r"
			);
		end
		if (UnBotMarrowgarRescue.boneStormActive) then
			UnBotMarrowgarEnableStormAoe(false);
		end
	elseif (
		(eventType == "SPELL_AURA_APPLIED" or eventType == "SPELL_AURA_REFRESH")
		and spellId == 69065
	) then
		UnBotMarrowgarStartRescue(destinationGuid, destinationName);
	elseif (eventType == "SPELL_AURA_REMOVED" and spellId == 69065) then
		local destinationKey = destinationGuid or destinationName;
		if (destinationKey) then
			UnBotMarrowgarRescue.impaled[destinationKey] = nil;
		end
		UnBotMarrowgarRescue.rescueUntil = GetTime() + 2;
	elseif (
		(eventType == "UNIT_DIED" or eventType == "UNIT_DESTROYED")
		and destinationGuid
		and UnBotMarrowgarRescue.impaled[destinationGuid]
	) then
		UnBotMarrowgarRescue.impaled[destinationGuid] = nil;
	elseif (
		UnBotMarrowgarRescue.active
		and sourceName
		and UnBotMarrowgarRescue.helperSet[sourceName]
		and UnBotMarrowgarIsSpikeName(destinationName)
		and (
			eventType == "SWING_DAMAGE"
			or eventType == "RANGE_DAMAGE"
			or eventType == "SPELL_DAMAGE"
			or eventType == "SPELL_PERIODIC_DAMAGE"
		)
	) then
		if (not UnBotMarrowgarRescue.confirmedHelpers[sourceName]) then
			UnBotMarrowgarRescue.confirmedHelpers[sourceName] = true;
			UnBotMarrowgarRescue.confirmedAny = true;
			UnBotSpecSummonMessage(
				"Ребрад: "..sourceName.." подтвердил атаку шипа через "
				..string.format("%.1f", GetTime() - (UnBotMarrowgarRescue.startedAt or GetTime()))
				.." сек."
			);
		end
	end
end);
UnBotMarrowgarFrame:SetScript("OnUpdate", function()
	local now = GetTime();
	if (
		UnBotMarrowgarRescue.presetArmed
		and UnitAffectingCombat("player")
		and UnBotMarrowgarFindBossUnit()
	) then
		UnBotMarrowgarRescue.encounterActive = true;
		if (
			not UnBotMarrowgarRescue.iccSuppressed
			or GetTime() >= (UnBotMarrowgarRescue.nextIccEnforceAt or 0)
		) then
			UnBotMarrowgarSuppressIcc(true);
		end
	end
	if (
		UnBotMarrowgarRescue.encounterActive
		and (UnBotMarrowgarRescue.nextSpikePreAoeAt or 0) > 0
		and now >= UnBotMarrowgarRescue.nextSpikePreAoeAt
	) then
		UnBotMarrowgarRescue.nextSpikePreAoeAt = 0;
		if (UnBotMarrowgarRescue.boneStormActive) then
			UnBotMarrowgarCommandSpikeAoe(
				"|cffff6633Ребрад: прогноз скрытых шипов 15–20 сек — заранее поставлены классовые AoE паладина и ДК.|r"
			);
		end
	end
	if (UnBotMarrowgarRescue.boneStormActive) then
		if (now >= (UnBotMarrowgarRescue.boneStormUntil or 0)) then
			UnBotMarrowgarRescue.boneStormActive = false;
			UnBotMarrowgarRescue.nextStormAoeAt = 0;
		end
	end
	if (not UnBotMarrowgarRescue.active) then
		return;
	end
	if (now >= (UnBotMarrowgarRescue.nextScanAt or 0)) then
		UnBotMarrowgarRescue.nextScanAt = now + 0.2;
		if (UnBotMarrowgarScanImpaled()) then
			UnBotMarrowgarRescue.rescueUntil = now + 18;
		else
			UnBotMarrowgarRescue.rescueUntil = math.min(
				UnBotMarrowgarRescue.rescueUntil or 0,
				now + 2
			);
			if (now >= (UnBotMarrowgarRescue.rescueUntil or 0)) then
				local confirmedNames = UnBotMarrowgarConfirmedNames();
				if (#confirmedNames > 0) then
					UnBotMarrowgarStopRescue(
						"Ребрад: шип снят; подтверждённый фокус ботов: "
						..table.concat(confirmedNames, ", ").."."
					);
				else
					UnBotMarrowgarStopRescue(
						"Ребрад: шип снят без подтверждённого урона ботов "
						.."(вероятно, Освящение/клив игрока)."
					);
				end
				return;
			end
		end
	end
	if (now < (UnBotMarrowgarRescue.nextCommandAt or 0)) then
		return;
	end
	local helpers, helperRole = UnBotMarrowgarHelperNamesWithEscalation();
	if (#helpers == 0) then
		UnBotMarrowgarRescue.nextCommandAt = now + 0.5;
		return;
	end
	for _, name in ipairs(helpers) do
		UnBotMarrowgarRescue.helperSet[name] = true;
	end
	local signature = helperRole.."|"..table.concat(helpers, ",");
	if (signature ~= UnBotMarrowgarRescue.lastHelperSignature) then
		UnBotMarrowgarRescue.lastHelperSignature = signature;
		UnBotSpecSummonMessage(
			"Ребрад: шипы ["..table.concat(UnBotMarrowgarImpaledNames(), ", ")
			.."], освобождают "..table.concat(helpers, ", ").." ("..helperRole..")."
		);
	end
	if (UnBotMarrowgarRescue.commandPhase == "discover") then
		for _, name in ipairs(helpers) do
			SendChatMessage("do icc spike", "WHISPER", nil, name);
		end
		UnBotMarrowgarRescue.commandPhase = "target";
		UnBotMarrowgarRescue.nextCommandAt = now + 0.3;
	elseif (UnBotMarrowgarRescue.commandPhase == "target") then
		for _, name in ipairs(helpers) do
			SendChatMessage("rti skull", "WHISPER", nil, name);
		end
		UnBotMarrowgarRescue.commandPhase = "attack";
		UnBotMarrowgarRescue.nextCommandAt = now + 0.3;
	else
		for _, name in ipairs(helpers) do
			-- "attack rti target" is a chat command. Prefixing it with "do"
			-- turns it into a different action name and makes Playerbots reject it.
			SendChatMessage("attack rti target", "WHISPER", nil, name);
		end
		UnBotMarrowgarRescue.commandPhase = "discover";
		UnBotMarrowgarRescue.nextCommandAt = now + 0.55;
	end
end);

local function UnBotSquadBuilderSavePreset(index)
	UnBotSquadBuilderEnsureConfig();
	local botCount = UnBotSquadBuilderBotCount();
	if (botCount == 0) then
		UnBotSpecSummonMessage("Пресет "..tostring(index)..": сначала добавьте участников. Shift+ПКМ удаляет сохранённый пресет.");
		return;
	end
	UnBotSquadConfig.presets[index] = {
		slots = UnBotSquadBuilderCopySlots(UnBotSquadConfig.slots),
		includeResurrectionReserve = UnBotSquadConfig.includeResurrectionReserve and true or false,
		resurrectionReserveCount = UnBotSquadReserveCount(UnBotSquadConfig.resurrectionReserveCount),
		savedAt = date("%Y-%m-%d %H:%M:%S"),
	};
	UnBotSpecSummonMessage("Пресет "..tostring(index).." сохранён: "..tostring(botCount).." ботов.");
	UnBotSquadBuilderRefresh();
end

local function UnBotSquadBuilderDeletePreset(index)
	UnBotSquadBuilderEnsureConfig();
	UnBotSquadConfig.presets[index] = nil;
	UnBotSpecSummonMessage("Пресет "..tostring(index).." удалён.");
	UnBotSquadBuilderRefresh();
end

local function UnBotSquadBuilderLoadPreset(index, summonNow)
	UnBotSquadBuilderEnsureConfig();
	if (not UnBotSquadBuilderPresetExists(index)) then
		UnBotSpecSummonMessage("Пресет "..tostring(index).." пока пуст.");
		return;
	end
	local preset = UnBotSquadConfig.presets[index];
	UnBotSquadBuilder.loadedBossPreset = nil;
	UnBotSquadBuilder.pendingBossPreset = nil;
	UnBotSquadBuilderSetSlots(preset.slots);
	UnBotSquadConfig.resurrectionReserveCount = 0;
	UnBotSquadConfig.includeResurrectionReserve = false;
	local botCount = UnBotSquadBuilderBotCount();
	UnBotSpecSummonMessage("Пресет "..tostring(index).." загружен: "..tostring(botCount).." ботов.");
	if (UnBotSquadBuilder.scrollFrame) then
		UnBotSquadBuilder.scrollFrame:SetVerticalScroll(0);
	end
	UnBotSquadBuilderRefresh();
	if (summonNow) then
		UnBotSquadBuilderStart();
	end
end

function UnBotSquadBuilderPresetCommand(message)
	UnBotSquadBuilderEnsureConfig();
	local command = UnBotSpecSummonNormalize(message);
	local indexText = string.match(command, "^([1-5])$");
	if (not indexText) then
		local filled = {};
		for index = 1, 5, 1 do
			if (UnBotSquadBuilderPresetExists(index)) then
				table.insert(filled, tostring(index));
			end
		end
		UnBotSpecSummonMessage(
			"Призыв пресета: /ubpreset 1-5. Сохранены: "
			..(#filled > 0 and table.concat(filled, ", ") or "нет").."."
		);
		return;
	end
	UnBotSquadBuilderLoadPreset(tonumber(indexText), true);
end

SLASH_UNBOTSQUADPRESET1 = "/ubpreset";
SLASH_UNBOTSQUADPRESET2 = "/unbotpreset";
SlashCmdList["UNBOTSQUADPRESET"] = UnBotSquadBuilderPresetCommand;

local function UnBotSquadBuilderPresetTooltip(button)
	local index = button.presetIndex;
	GameTooltip:SetOwner(button, "ANCHOR_TOP");
	GameTooltip:AddLine("Пресет состава "..tostring(index), 0, 0.7, 0.7, 1);
	local preset = UnBotSquadConfig.presets and UnBotSquadConfig.presets[index];
	if (UnBotSquadBuilderPresetExists(index)) then
		for i = 1, #preset.slots, 1 do
			local slot = preset.slots[i];
			GameTooltip:AddLine(
				tostring(UnBotLocale.Text(slot.label) or (slot.className.." - "..slot.specKey))
				.." x"..tostring(slot.count or 1),
				1, 1, 1, 1
			);
		end
		GameTooltip:AddLine("Всего ботов: "..tostring(UnBotSquadBuilderSlotsCount(preset.slots)), 0, 1, 0, 1);

	else
		GameTooltip:AddLine("Пустой пресет.", 1, 0.82, 0, 1);
	end
	GameTooltip:AddLine("ЛКМ: только загрузить для редактирования.", 0, 1, 0, 1);
	GameTooltip:AddLine("Shift+ЛКМ: загрузить и сразу призвать.", 0, 1, 0, 1);
	GameTooltip:AddLine("ПКМ: сохранить текущий состав.", 0, 1, 0, 1);
	GameTooltip:AddLine("Shift+ПКМ: удалить пресет.", 1, 0.55, 0.2, 1);
	GameTooltip:AddLine("Макрос: /ubpreset "..tostring(index), 0.45, 0.82, 0.84, 1);
	GameTooltip:Show();
end

function UnBotSquadBuilderRosterAssignments(requestedSlots)
	local roster = {};
	local assigned = {};
	local claimed = {};
	local talentModes = {};
	local pvpNames = UnBotPVPSummon and UnBotPVPSummon.ReservedNames and UnBotPVPSummon.ReservedNames() or {};
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		local profile = UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		local online = unit and UnitIsConnected(unit) and true or false;
		table.insert(roster, {
			name = name,
			unit = unit,
			profile = profile,
			online = online,
			reserve = not online and UnBotSquadRosterIsOfflineReserve(name, unit) or false,
		});
	end);
	table.sort(roster, function(left, right)
		if (left.online ~= right.online) then
			return left.online;
		end
		return tostring(left.name) < tostring(right.name);
	end);
	local function matches(member, wantedSlot)
		if (wantedSlot.accountAltName) then
			return member.name == wantedSlot.accountAltName;
		end
		if (pvpNames[member.name]) then return false; end
		local profile = member.profile;
		if (not profile or UnBotSpecSummonNormalize(profile.className) ~= UnBotSpecSummonNormalize(wantedSlot.className)
			or UnBotIsAccountAltProfile(member.name, profile)) then
			return false;
		end
		if (member.online and UnBotTalentInfo and profile.talentSnapshot) then
			if (talentModes[profile] == nil) then
				talentModes[profile] = UnBotFullTalentCatalog.Get(profile.className,profile.level)
					and UnBotTalentInfo.Get(profile).mode or false;
			end
			local mode = talentModes[profile];
			-- A stale inspect is not a PvP verdict. Reuse the same fresh WHO proof
			-- as the production summon, without changing the saved classification.
			if (mode and mode ~= "pve" and not (mode == "unknown"
				and UnBotSpecSummonHasFreshConfirmation(member.name))) then return false; end
		end
		local aliases = UnBotSpecSummonNormalize(wantedSlot.specKey) == "any"
			and {anySpec = true}
			or (wantedSlot.specAliases or UnBotSpecSummonSpecAliases[wantedSlot.specKey] or {wantedSlot.specKey});
		return (
			tonumber(profile.level) and tonumber(profile.level) > 0
			and tonumber(profile.level) < 10
			and not aliases.feralRole
			and UnBotSpecSummonNormalize(profile.className)
				== UnBotSpecSummonNormalize(wantedSlot.className)
		) or UnBotRegistryProfileMatches(profile, wantedSlot.className, aliases);
	end
	-- Assign each online bot once: named and exact slots claim their requested
	-- counts before a class-wide "any" slot can use the remaining bots.
	for pass = 1, 3 do
		for _, wantedSlot in ipairs(requestedSlots or UnBotSquadConfig.slots or {}) do
			local isAny = UnBotSpecSummonNormalize(wantedSlot.specKey) == "any";
			if (not wantedSlot.reserveOnly and (
				(pass == 1 and wantedSlot.accountAltName)
				or (pass == 2 and not wantedSlot.accountAltName and not isAny)
				or (pass == 3 and not wantedSlot.accountAltName and isAny)
			)) then
				assigned[wantedSlot] = assigned[wantedSlot] or {};
				for _, member in ipairs(roster) do
					if (member.online and not claimed[member.name]
						and #assigned[wantedSlot] < (tonumber(wantedSlot.count) or 1)
						and matches(member, wantedSlot)) then
						claimed[member.name] = true;
						table.insert(assigned[wantedSlot], member);
					end
				end
			end
		end
	end
	-- Keep offline members visible for role actions, but never count them as
	-- filling a combat slot or show one reserve in several overlapping rows.
	for pass = 1, 4 do
		for _, wantedSlot in ipairs(requestedSlots or UnBotSquadConfig.slots or {}) do
			local isAny = UnBotSpecSummonNormalize(wantedSlot.specKey) == "any";
			if ((pass == 1 and wantedSlot.reserveOnly)
				or (pass == 2 and not wantedSlot.reserveOnly and wantedSlot.accountAltName)
				or (pass == 3 and not wantedSlot.reserveOnly and not wantedSlot.accountAltName and not isAny)
				or (pass == 4 and not wantedSlot.reserveOnly and not wantedSlot.accountAltName and isAny)) then
				for _, member in ipairs(roster) do
					if (not member.online and not claimed[member.name] and matches(member, wantedSlot)) then
						claimed[member.name] = true;
						assigned[wantedSlot] = assigned[wantedSlot] or {};
						table.insert(assigned[wantedSlot], member);
					end
				end
			end
		end
	end
	return assigned;
end

function UnBotSquadBuilderSlotRosterMembers(slot, assigned)
	if (not slot) then
		return {};
	end
	return (assigned or UnBotSquadBuilderRosterAssignments())[slot] or {};
end

function UnBotSquadBuilderSlotRosterText(slot, assigned)
	local onlineNames = {};
	local reserveNames = {};
	local unavailableNames = {};
	local required = slot and slot.reserveOnly and 0
		or math.max(1, tonumber(slot and slot.count) or 1);
	if (not slot) then
		return "";
	end
	if (slot.accountAltName and UnBotAccountAlts) then
		local status = UnBotAccountAlts.SquadFactionStatus(slot.accountAltName);
		if (status) then return status; end
	end
	for _, member in ipairs(UnBotSquadBuilderSlotRosterMembers(slot, assigned)) do
		if (member.online) then
			table.insert(onlineNames, member.name);
		elseif (member.reserve) then
			table.insert(reserveNames, member.name);
		else
			table.insert(unavailableNames, member.name);
		end
	end
	table.sort(onlineNames);
	table.sort(reserveNames);
	table.sort(unavailableNames);

	local parts = {};
	if (#onlineNames > 0) then
		table.insert(parts, "|cff00ff00"..table.concat(onlineNames, ", ").." — онлайн|r");
	end
	if (#reserveNames > 0) then
		table.insert(parts, "|cffaaaaaa"..table.concat(reserveNames, ", ")
			.." — офлайн (резерв в ростере)|r");
	end
	if (#unavailableNames > 0) then
		table.insert(parts, "|cffff6060"..table.concat(unavailableNames, ", ")
			.." — офлайн, не резерв (слот не засчитан)|r");
	end
	local missing = math.max(0, required - #onlineNames);
	if (missing > 0) then
		table.insert(parts, "|cffffcc00не назначено: "..tostring(missing).."|r");
	end
	return table.concat(parts, "   ");
end

UnBotSquadBuilderRefresh = function()
	if (not UnBotSquadBuilder.frame or not UnBotSquadBuilder.frame:IsShown()) then
		UnBotSquadBuilder.refreshDirty = true;
		return;
	end
	UnBotSquadBuilder.refreshDirty = nil;
	UnBotSquadBuilderEnsureConfig(true);
	if (UnBotSquadBuilder.raidBuffCheck) then
		UnBotSquadBuilder.raidBuffCheck:SetChecked(
			UnBotSquadConfig.buffRaidAfterSummon and true or false
		);
	end
	if (UnBotSquadBuilder.combatLogCheck) then
		UnBotSquadBuilder.combatLogCheck:SetChecked(
			UnBotSquadConfig.recordFullCombatLog and true or false
		);
	end
	if (UnBotSquadBuilder.summonLogCheck) then
		UnBotSquadBuilder.summonLogCheck:SetChecked(UnBotSquadConfig.summonLogging and true or false);
	end

	if UnBotDiagnostics and UnBotDiagnostics.RaidCheck then UnBotDiagnostics.RaidCheck();end
	if (UnBotSquadBuilderUI and UnBotSquadBuilderUI.RefreshSettings) then UnBotSquadBuilderUI.RefreshSettings(UnBotSquadBuilder); end
	if (UnBotSquadBuilderUI) then UnBotSquadBuilderUI.RefreshFreshness(UnBotSquadBuilder); end


	local rosterAssignments = UnBotSquadBuilderRosterAssignments();
	for i = 1, #UnBotSquadBuilder.rows, 1 do
		local row = UnBotSquadBuilder.rows[i];
		local slot = UnBotSquadConfig.slots[i];
		row.slotIndex = i;
		if (slot) then
			row.label:SetText((UnBotLocale.Text(slot.label) or (slot.className.." "..slot.specKey))
				..(slot.accountAltName and " |cff69ccf0[альт]|r" or "")
				..(slot.reserveOnly and " |cffaaaaaa[резерв]|r" or ""));
			if (slot.accountAltName) then
				row:SetBackdropColor(0.015, 0.12, 0.16, 0.94);
				row:SetBackdropBorderColor(0.2, 0.66, 0.82, 0.9);
				row.accent:SetVertexColor(0.25, 0.78, 1, 1);
				row.label:SetTextColor(0.78, 0.94, 1);
			elseif (slot.reserveOnly) then
				row:SetBackdropColor(0.08, 0.08, 0.09, 0.94);
				row:SetBackdropBorderColor(0.42, 0.42, 0.45, 0.85);
				row.accent:SetVertexColor(0.58, 0.58, 0.62, 1);
				row.label:SetTextColor(0.78, 0.78, 0.8);
			else
				local even = i % 2 == 0;
				row:SetBackdropColor(
					even and 0.025 or 0.035,
					even and 0.085 or 0.105,
					even and 0.095 or 0.12,
					0.94
				);
				row:SetBackdropBorderColor(0.13, 0.36, 0.4, 0.78);
				row.accent:SetVertexColor(0.12, 0.65, 0.68, 0.92);
				row.label:SetTextColor(1, 0.9, 0.58);
			end
			UnBotPVPSquad.UpdateCountEdit(row, slot);
			row.assignment:SetText(UnBotSquadBuilderSlotRosterText(slot, rosterAssignments));
			if (#UnBotSquadBuilderSlotRosterMembers(slot, rosterAssignments) > 0) then
				row.actions:Show();
			else
				row.actions:Hide();
			end
			if (slot.reserveOnly or slot.accountAltName) then
				row.minus:Hide();
				row.plus:Hide();
			else
				row.minus:Show();
				row.plus:Show();
			end
			row:Show();
		else
			row.assignment:SetText("");
			row.actions:Hide();
			row:Hide();
		end
	end

	for i = 1, #UnBotSquadBuilder.presetButtons, 1 do
		local button = UnBotSquadBuilder.presetButtons[i];
		local filled = UnBotSquadBuilderPresetExists(button.presetIndex);
		button:SetText(filled and (tostring(button.presetIndex).."*") or tostring(button.presetIndex));
		local fontString = button:GetFontString();
		if (fontString) then
			if (filled) then
				fontString:SetTextColor(0, 1, 0);
			else
				fontString:SetTextColor(1, 0.82, 0);
			end
		end
	end

	local botCount = UnBotSquadBuilderBotCount(true);
	local reserveNames = UnBotSquadRosterReserveNames();
	local reserveText = #reserveNames > 0
		and ("\n|cffaaaaaaОфлайн-резерв в составе рейда (ростере): "
			..table.concat(reserveNames, ", ")..". Не входит в боевой состав.|r")
		or "";
	if (UnBotSpecSummon.active and UnBotSpecSummon.mode == "squad") then
		local have = 0;
		local need = 0;
		for i = 1, #(UnBotSpecSummon.squad.slots), 1 do
			have = have + UnBotSpecSummon.squad.slots[i].have;
			need = need + UnBotSpecSummon.squad.slots[i].need;
		end
		UnBotSquadBuilder.status:SetText("|cff00ccccИдёт призыв: собрано "..tostring(have).."/"..tostring(need).." | проверено кандидатов: "..tostring(UnBotSpecSummon.tries).."|r"..reserveText);
	elseif (botCount > 0) then
		UnBotSquadBuilder.status:SetText("Выбрано PvE-ботов: "..tostring(botCount).."."..reserveText);
	elseif (botCount == 0) then
		UnBotSquadBuilder.status:SetText("|cffffff00Добавьте хотя бы одного боевого участника.|r"..reserveText);
	end
	if (UnBotPVPSquad and UnBotPVPSquad.Render) then
		UnBotPVPSquad.Render(rosterAssignments);
	end
end

local function UnBotSquadBuilderAdd(className, specKey, label)
	UnBotSquadBuilderEnsureConfig();
	if (not UnBotPVPSquad.CanAddMembers(1)) then return; end
	for i = 1, #UnBotSquadConfig.slots, 1 do
		local slot = UnBotSquadConfig.slots[i];
		if (
			not slot.accountAltName
			and slot.className == className
			and slot.specKey == specKey
		) then
			if (slot.reserveOnly) then
				slot.reserveOnly = nil;
				slot.count = 1;
			else
				slot.count = (tonumber(slot.count) or 1) + 1;
			end
			UnBotSquadBuilderRefresh();
			return;
		end
	end

	if (#UnBotSquadConfig.slots >= UnBotSquadBuilderMaxSlots) then
		UnBotSpecSummonMessage("Призыв состава: максимум 24 разные позиции — полный рейд 25 человек вместе с вами.");
		return;
	end
	table.insert(UnBotSquadConfig.slots, {
		className = className,
		specKey = specKey,
		label = label,
		count = 1,
	});
	UnBotSquadBuilderRefresh();
	if (UnBotSquadBuilder.scrollFrame) then
		UnBotSquadBuilder.scrollFrame:UpdateScrollChildRect();
		UnBotSquadBuilder.scrollFrame:SetVerticalScroll(
			UnBotSquadBuilder.scrollFrame:GetVerticalScrollRange() or 0
		);
	end
end

local function UnBotSquadBuilderFindProfileSlot(profile)
	if (not profile) then
		return nil;
	end
	for _, classInfo in ipairs(UnBotSquadBuilderSpecs) do
		if (
			UnBotSpecSummonNormalize(profile.className)
			== UnBotSpecSummonNormalize(classInfo.className)
		) then
			for _, spec in ipairs(classInfo.specs or {}) do
				local aliases = UnBotSpecSummonSpecAliases[spec.key] or {spec.key};
				if (UnBotRegistryProfileMatches(profile, classInfo.className, aliases)) then
					return {
						className = classInfo.className,
						specKey = spec.key,
						label = classInfo.label.." - "..spec.label,
					};
				end
			end
		end
	end
	if (UnBotIsAccountAltProfile(profile.name, profile)) then
		for _, classInfo in ipairs(UnBotSquadBuilderSpecs) do
			if (
				UnBotSpecSummonNormalize(profile.className)
				== UnBotSpecSummonNormalize(classInfo.className)
			) then
				return {
					className = classInfo.className,
					specKey = profile.specName or "any",
					label = classInfo.label..(profile.specName and (" - "..profile.specName) or ""),
				};
			end
		end
	end
	return nil;
end

function UnBotSquadBuilderAddAccountAlt(name, accountSelection)
	UnBotSquadBuilderEnsureConfig();
	if (UnBotAccountAlts) then name = UnBotAccountAlts.ResolveName(name,true) or name; end
	if (
		UnBotSpecSummonNormalize(name)
		== UnBotSpecSummonNormalize(UnitName("player") or "")
	) then
		UnBotSpecSummonMessage(
			"Текущий персонаж "..tostring(name)
			.." не добавлен: он уже входит в состав как игрок."
		);
		return;
	end
	if (
		not UnBotAccountAlts
		or not UnBotAccountAlts.IsEnabled
		or (accountSelection and not UnBotAccountAlts.IsListed(name))
		or (not accountSelection and not UnBotAccountAlts.IsEnabled(name))
	) then
		UnBotSpecSummonMessage("Альт "..tostring(name).." не найден или отключён.");
		return;
	end
	if (not UnBotAccountAlts.CanAddToSquad(name)) then
		UnBotSpecSummonMessage(UnBotAccountAlts.FactionRestrictionText(name));
		return;
	end
	if (
		not accountSelection and (not UnBotAccountAlts.IsCurrentFaction
		or not UnBotAccountAlts.IsCurrentFaction(name))
	) then
		UnBotSpecSummonMessage(
			UnBotAccountAlts.FactionRestrictionText
				and UnBotAccountAlts.FactionRestrictionText(name)
				or ("Фракция альта "..tostring(name).." не подтверждена.")
		);
		return;
	end
	for _, slot in ipairs(UnBotSquadConfig.slots) do
		if (slot.accountAltName == name) then
			UnBotSpecSummonMessage("Альт "..name.." уже добавлен в состав.");
			return;
		end
	end
	if (not UnBotPVPSquad.CanAddMembers(1)) then return; end
	local profile = UnBotAccountAlts.GetProfile(name);
	if (not profile and UnBotAccountAlts.ProtectProfile) then
		profile = UnBotAccountAlts.ProtectProfile(name, nil, nil);
	end
	local slotInfo = UnBotSquadBuilderFindProfileSlot(profile);
	if (not slotInfo) then
		slotInfo = {
			className = profile and profile.className or "unknown",
			specKey = profile and profile.specName or "any",
			label = "класс уточнится после призыва",
		};
	end
	if (#UnBotSquadConfig.slots >= UnBotSquadBuilderMaxSlots) then
		UnBotSpecSummonMessage("Призыв состава: достигнут лимит позиций редактора.");
		return;
	end
	table.insert(UnBotSquadConfig.slots, {
		className = slotInfo.className,
		specKey = slotInfo.specKey,
		label = name.." — "..slotInfo.label,
		count = 1,
		accountAltName = name,
	});
	UnBotSquadBuilderRefresh();
	return true;
end

function UnBotSquadBuilderAddAltAccount(accountKey)
	UnBotSquadBuilderEnsureConfig();
	local names = UnBotAccountAlts.AccountNames(accountKey);
	local selected, pending = {}, {};
	for _, slot in ipairs(UnBotSquadConfig.slots) do
		if (slot.accountAltName) then selected[UnBotAccountAlts.Key(slot.accountAltName)] = true; end
	end
	for _, name in ipairs(names) do
		if (not selected[UnBotAccountAlts.Key(name)]) then pending[#pending+1] = name; end
	end
	if (#UnBotSquadConfig.slots + #pending > UnBotSquadBuilderMaxSlots) then
		UnBotSpecSummonMessage("Все альты аккаунта не помещаются: нужно новых позиций "..#pending..", свободно "
			..(UnBotSquadBuilderMaxSlots-#UnBotSquadConfig.slots)..". Освободите позиции и повторите выбор аккаунта."); return;
	end
	if (not UnBotPVPSquad.CanAddMembers(#pending)) then return; end
	local count = 0;
	for _, name in ipairs(pending) do if (UnBotSquadBuilderAddAccountAlt(name,true)) then count=count+1; end end
	UnBotSpecSummonMessage("Альты аккаунта: добавлено в состав "..count..", уже были "..(#names-#pending)
		..". Вражеская фракция исключена; отключение проверяется при призыве.");
end

function UnBotSquadBuilderShowCurrentRoster(automatic)
	if (automatic ~= true and UnBotBatchSummon) then return UnBotBatchSummon.ShowCurrent(); end
	if (automatic == true) then
		local preserve = UnBotSquadSummon and UnBotSquadSummon.active;
		for _, slot in ipairs(UnBotSquadConfig.slots or {}) do
			if (slot.accountAltName and UnBotAccountAlts and UnBotAccountAlts.SquadFactionStatus(slot.accountAltName)) then preserve = true; end
		end
		if (preserve) then UnBotSquadBuilderRefresh(); return true; end
	end
	if (automatic ~= true and ((UnBotSquadSummon and UnBotSquadSummon.active)
		or (UnBotPVPSummon and UnBotPVPSummon.active) or UnBotSpecSummon.active
		or UnBotSquadBuilder.postSummonSequence)) then
		UnBotSpecSummonMessage("Текущий состав: дождитесь завершения призыва или остановите его.");
		return false;
	end
	UnBotSquadBuilderEnsureConfig();
	UnBotRegistryAttachStorage();

	local slots = {};
	local pvpSlots = {};
	local pvpState = UnBotPVPSquad and UnBotPVPSquad.State();
	local byKey = {};
	local skippedNames = {};
	local reserveNames = {};
	local reserveSlots = {};
	local overflow = 0;
	local memberCount = 0;

	UnBotBuffCycleForEachGroupMember(function(name, unit)
		if (UnBotSquadRosterIsOfflineReserve(name, unit)) then
			table.insert(reserveNames, name);
			local reserveProfile = UnBotBotRegistry and UnBotBotRegistry.bots
				and UnBotBotRegistry.bots[name];
			if (UnBotIsAccountAltProfile(name, reserveProfile)) then
				return;
			end
			local reserveSlotInfo = UnBotSquadBuilderFindProfileSlot(reserveProfile);
			if (reserveSlotInfo) then
				table.insert(reserveSlots, reserveSlotInfo);
			else
				table.insert(skippedNames, tostring(name).." (резерв)");
			end
			return;
		end
		memberCount = memberCount + 1;
		local profile = UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		local display, mode = profile,"pve";
		if (UnBotPVPSummon and pvpState) then display,mode = UnBotPVPSummon.RosterProfile(profile); end
		if (UnBotBatchSummon and UnBotBatchSummon.viewResults
			and not UnBotIsAccountAltProfile(name,profile) and not UnBotBatchSummon.viewResults[name]) then display = nil; end
		local slotInfo = UnBotSquadBuilderFindProfileSlot(display);
		if (slotInfo) then
			local accountAlt = UnBotIsAccountAltProfile(name, profile);
			local targetSlots = mode == "pvp" and pvpSlots or slots;
			local key = accountAlt and ("@"..name)
				or (mode.."\031"..slotInfo.className.."\031"..slotInfo.specKey);
			local slot = byKey[key];
			if (slot) then
				slot.count = slot.count + 1;
			elseif (#slots + #pvpSlots < UnBotSquadBuilderMaxSlots) then
				slot = {
					className = slotInfo.className,
					specKey = slotInfo.specKey,
					label = accountAlt and (name.." — "..slotInfo.label) or slotInfo.label,
					count = 1,
					accountAltName = accountAlt and name or nil,
					mode = mode == "pvp" and "PVP" or nil,
				};
				byKey[key] = slot;
				table.insert(targetSlots, slot);
			else
				overflow = overflow + 1;
			end
		else
			table.insert(skippedNames, tostring(name));
		end
	end);
	table.sort(reserveNames);
	local reserveRoleCount = 0;
	for _, slotInfo in ipairs(reserveSlots) do
		local key = "pve\031"..slotInfo.className.."\031"..slotInfo.specKey;
		if (not byKey[key] and #slots + #pvpSlots < UnBotSquadBuilderMaxSlots) then
			local reserveSlot = {
				className = slotInfo.className,
				specKey = slotInfo.specKey,
				label = slotInfo.label,
				count = 0,
				reserveOnly = true,
			};
			byKey[key] = reserveSlot;
			table.insert(slots, reserveSlot);
			reserveRoleCount = reserveRoleCount + 1;
		end
	end

	if (memberCount == 0) then
		UnBotSquadBuilderSetSlots(slots);
		if (pvpState) then pvpState.slots = pvpSlots; end
		UnBotSquadBuilderRefresh();
		if (#reserveNames > 0) then
			UnBotSpecSummonMessage(
				"Боевых ботов в текущем составе нет. Офлайн-резерв в составе рейда (ростере): "
				..table.concat(reserveNames, ", ").."."
			);
			return true;
		else
			UnBotSpecSummonMessage("Текущий состав: вы сейчас не состоите в группе или рейде.");
		end
		return false;
	end
	if (#slots + #pvpSlots == 0) then
		UnBotSpecSummonMessage(
			"Текущий состав: среди участников не найдено ботов с профилями в сохранённом реестре."
		);
		return false;
	end

	UnBotSquadBuilderSetSlots(slots);
	if (pvpState) then pvpState.slots = pvpSlots; end
	-- The rebuilt lists are a fresh view; old failed slot indexes belong to
	-- the previous summon plan. Persistent profile evidence remains intact.
	if (UnBotPVPSummon and not UnBotPVPSummon.active) then
		UnBotPVPSummon.signature,UnBotPVPSummon.items,UnBotPVPSummon.blocked = nil,nil,nil;
	end
	if (UnBotSquadBuilder.scrollFrame) then
		UnBotSquadBuilder.scrollFrame:SetVerticalScroll(0);
	end
	UnBotSquadBuilderRefresh();

	local pvpCount = pvpState and UnBotPVPSquad.Total(pvpState) or 0;
	local loadedCount = UnBotSquadBuilderSlotsCount(slots) + pvpCount;
	UnBotSpecSummonMessage(
		"Боевой состав загружен в сборщик: "..tostring(loadedCount)
		.." ботов (PvE "..tostring(loadedCount-pvpCount)..", PvP "..tostring(pvpCount)
		.."); боевых позиций "..tostring(#slots + #pvpSlots - reserveRoleCount)
		..", резервных ролей "..tostring(reserveRoleCount).."."
	);
	if (#reserveNames > 0) then
		UnBotSpecSummonMessage(
			"Офлайн-резерв в составе рейда (ростере): "
			..table.concat(reserveNames, ", ")
			..". В боевой пресет не добавлен."
		);
	end
	if (#skippedNames > 0) then
		UnBotSpecSummonMessage(
			"Не добавлены участники без профиля в реестре: "..table.concat(skippedNames, ", ").."."
		);
	end
	if (overflow > 0) then
		UnBotSpecSummonMessage(
			"Не показано позиций сверх лимита редактора: "..tostring(overflow).."."
		);
	end
	return true;
end

local function UnBotSquadSpecCheckStoreProfile(name, whoInfo, rawWho)
	if (not UnBotIsValidBotName(name) or not whoInfo or not whoInfo.className or not whoInfo.specName) then
		return nil, nil;
	end
	UnBotRegistryAttachStorage();
	local profile = UnBotBotRegistry.bots[name] or {
		name = name,
		firstSeen = time(),
		seenCount = 0,
	};
	local oldClass = profile.className;
	local oldSpec = profile.specName;
	local unit = UnBotBuffCycleResolveUnit(name);
	if (unit) then
		local localizedClass, classFile = UnitClass(unit);
		local localizedRace, raceFile = UnitRace(unit);
		profile.classLocalized = localizedClass or profile.classLocalized;
		profile.classFile = classFile or profile.classFile;
		profile.raceLocalized = localizedRace or profile.raceLocalized;
		profile.raceFile = raceFile or profile.raceFile;
		profile.sex = UnitSex(unit) or profile.sex;
	end
	profile.name = name;
	profile.className = whoInfo.className;
	profile.specName = whoInfo.specName;
	profile.level = whoInfo.level or profile.level;
	profile.gearScore = whoInfo.gearScore or profile.gearScore;
	profile.rawWho = rawWho or profile.rawWho;
	UnBotStoreFeralRole(profile, whoInfo);
	if (UnBotIsAccountAltProfile(name, profile)) then
		profile.accountAlt = true;
		profile.protectedAccountCharacter = true;
		profile.rotationAllowed = false;
		profile.source = "account-alt";
	else
		profile.source = "manual-spec-recheck";
	end
	profile.lastSeen = time();
	profile.specCheckedAt = time();
	profile.seenCount = (profile.seenCount or 0) + 1;
	UnBotBotRegistry.bots[name] = profile;
	UnBotSquadConfig.botRegistry = UnBotBotRegistry;
	UnBotRememberKnownBot(name);
	if (profile.accountAlt and UnBotAccountAlts and UnBotAccountAlts.ProtectProfile) then
		UnBotAccountAlts.ProtectProfile(name, whoInfo, rawWho);
	end
	if UnBotSpecSummon.confirmedRoster then UnBotSpecSummon.confirmedRoster.Who(name,whoInfo);end
	return oldClass, oldSpec;
end

local function UnBotSquadSpecCheckFinish()
	local total = #UnBotSquadSpecCheck.queue;
	local zoneCounts = {};
	local majorityZone;
	local majorityCount = 0;
	local secondCount = 0;
	for _, result in pairs(UnBotSquadSpecCheck.results or {}) do
		if (result.zoneName and result.zoneName ~= "") then
			zoneCounts[result.zoneName] = (zoneCounts[result.zoneName] or 0) + 1;
		end
	end
	for zoneName, count in pairs(zoneCounts) do
		if (count > majorityCount) then
			secondCount = majorityCount;
			majorityCount = count;
			majorityZone = zoneName;
		elseif (count > secondCount) then
			secondCount = count;
		end
	end

	local resolvedZone = UnBotSquadSpecCheck.referenceZone;
	if (not resolvedZone and majorityZone and majorityCount > secondCount) then
		resolvedZone = majorityZone;
	end
	local quarantineZone = UnBotSquadSpecCheck.referenceZone;
	if (
		not quarantineZone
		and majorityZone
		and majorityCount >= 2
		and majorityCount > secondCount
	) then
		quarantineZone = majorityZone;
	end

	local quarantined = tonumber(UnBotSquadSpecCheck.quarantinedDuringCheck) or 0;
	if (quarantineZone and UnBotSquadSpecCheck.mode ~= "pre_summon"
		and UnBotSquadSpecCheck.mode ~= "post_summon"
		and UnBotSquadSpecCheck.mode ~= "role_status") then
		for name, result in pairs(UnBotSquadSpecCheck.results or {}) do
			if (
				not UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots and UnBotBotRegistry.bots[name])
				and result.zoneName
				and result.zoneName ~= quarantineZone
				and (not result.visible or not result.near)
			) then
				local reason =
					"who: "..tostring(result.zoneName)
					.."; группа: "..tostring(quarantineZone)
					.."; бот не находится рядом";
				local untilTime = UnBotRegistryNextMorningTimestamp();
				if (UnBotRegistrySetQuarantine(name, reason, untilTime)) then
					quarantined = quarantined + 1;
					UnBotSpecSummonMessage(
						"Ротация: "..name.." помещён в карантин до "
						..UnBotRegistryFlagTimeText(untilTime).." — "..reason.."."
					);
				end
			end
		end
	end

	local checkMode = UnBotSquadSpecCheck.mode;
	local continuation = UnBotSquadSpecCheck.continuation;
	UnBotSquadSpecCheck.active = false;
	UnBotSquadSpecCheck.currentName = nil;
	UnBotSquadSpecCheck.mode = "manual";
	UnBotSquadSpecCheck.continuation = nil;
	UnBotSquadSpecCheck.referenceZone = nil;
	UnBotSquadSpecCheck.quarantinedDuringCheck = 0;
	UnBotSpecSummonMessage(
		"Проверка спеков завершена: проверено "..tostring(UnBotSquadSpecCheck.updated)
		.."/"..tostring(total)..", изменено "..tostring(UnBotSquadSpecCheck.changed)
		..", без ответа "..tostring(UnBotSquadSpecCheck.failed)
		..", карантин "..tostring(quarantined).."."
	);
	UnBotSpecSummonMessage("Обновлённый реестр запишется на диск при следующем /reload или нормальном выходе.");
	-- Finish the who pass without triggering roster replacement. Physical
	-- arrival is handled by the bounded, non-destructive pre-buff gate.
	if (checkMode == "pre_summon" and continuation) then
		UnBotSpecSummonMessage(
			"Текущий состав опрошен; продолжаю сбор и вызываю только недостающих ботов."
		);
		continuation(resolvedZone);
	elseif (checkMode ~= "role_status") then
		if (checkMode == "post_summon" and UnBotSquadPostSummonContinue) then
			UnBotSquadPostSummonContinue();
		end
		UnBotSquadBuilderShowCurrentRoster(true);
	end
	UnBotSquadBuilderRefresh();
end

UnBotSquadSpecCheckSchedule = function(queue, referenceZone)
	if (not UnBotSpecSummonPlayerSupportsSpecs()) then
		UnBotSquadSpecCheck.autoStartAt = 0;
		UnBotSquadSpecCheck.autoOptions = nil;
		UnBotSpecSummonMessage(
			"Итоговая проверка специализаций пропущена: до 11 уровня состав учитывается только по классам."
		);
		if (UnBotSquadPostSummonContinue) then
			UnBotSquadPostSummonContinue();
		end
		return;
	end
	if (not queue or #queue == 0) then
		UnBotSpecSummonMessage("Новых ботов для итоговой проверки нет.");
		return;
	end
	UnBotSquadSpecCheck.autoOptions = {
		queue = queue,
		mode = "post_summon",
		referenceZone = referenceZone,
	};
	UnBotSquadSpecCheck.autoStartAt = GetTime() + 2;
	UnBotSpecSummonMessage(
		"Состав собран. Через 2 секунды будут проверены только новые боты: "
		..tostring(#queue).."."
	);
	UnBotSquadBuilderRefresh();
end

UnBotSquadSpecCheckStart = function(options)
	if (UnBotFullTalentCatalog and UnBotFullTalentCatalog.IsBusy()) then UnBotSpecSummonMessage("Сначала завершите сбор полного каталога талантов."); return false; end
	if (UnBotDKSpecBalance and UnBotDKSpecBalance.active) then
		UnBotSpecSummonMessage("Сначала остановите выравнивание спеков по количеству.");
		return;
	end
	local automatedOptions =
		type(options) == "table"
		and type(options.queue) == "table"
		and options
		or nil;
	if (UnBotSquadSpecCheck.active) then
		UnBotSquadSpecCheck.active = false;
		UnBotSquadSpecCheck.currentName = nil;
		UnBotSquadSpecCheck.autoStartAt = 0;
		UnBotSquadSpecCheck.autoOptions = nil;
		UnBotSquadSpecCheck.mode = "manual";
		UnBotSquadSpecCheck.continuation = nil;
		UnBotSquadSpecCheck.referenceZone = nil;
		UnBotSpecSummonMessage("Проверка спеков остановлена.");
		UnBotSquadBuilderRefresh();
		return;
	end
	if (not UnBotSpecSummonPlayerSupportsSpecs()) then
		UnBotSquadSpecCheck.autoStartAt = 0;
		UnBotSquadSpecCheck.autoOptions = nil;
		UnBotSpecSummonMessage(
			"Проверка специализаций отключена до 11 уровня; сохранённые спеки не изменены."
		);
		if (
			automatedOptions
			and automatedOptions.mode == "pre_summon"
			and automatedOptions.continuation
		) then
			automatedOptions.continuation(automatedOptions.referenceZone);
		elseif (automatedOptions and automatedOptions.mode == "post_summon" and UnBotSquadPostSummonContinue) then
			UnBotSquadPostSummonContinue();
		end
		UnBotSquadBuilderRefresh();
		return;
	end
	if (UnBotBotScanner and UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Сначала остановите полный скан ботов.");
		return;
	end
	if (UnBotSpecSummon.active) then
		UnBotSpecSummonMessage("Сначала завершите текущий призыв.");
		return;
	end
	if (UnBotBuffCycle.active or (UnBotJunkCleaner and UnBotJunkCleaner.active)) then
		UnBotSpecSummonMessage("Сначала завершите текущую операцию UnBot.");
		return;
	end
	if (UnBotSoulstoneTest and UnBotSoulstoneTest.active) then
		UnBotSpecSummonMessage("Сначала завершите тест Soulstone.");
		return;
	end

	UnBotRegistryAttachStorage();
	local queue = {};
	local skipped = 0;
	local reserveSkipped = 0;
	local altSkipped = 0;
	local seen = {};
	if (automatedOptions) then
		for _, name in ipairs(automatedOptions.queue) do
			if (
				not seen[name]
				and UnBotSpecSummonIsInGroup(name)
				and UnBotBotRegistry.bots
				and UnBotBotRegistry.bots[name]
			) then
				if (UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots[name])) then
					altSkipped = altSkipped + 1;
				elseif (UnBotSquadRosterIsOfflineReserve(name)) then
					reserveSkipped = reserveSkipped + 1;
				else
					seen[name] = true;
					table.insert(queue, name);
				end
			end
		end
	else
		UnBotBuffCycleForEachGroupMember(function(name, unit)
			if (UnBotBotRegistry.bots and UnBotBotRegistry.bots[name]) then
				if (UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots[name])) then
					altSkipped = altSkipped + 1;
				elseif (UnBotSquadRosterIsOfflineReserve(name, unit)) then
					reserveSkipped = reserveSkipped + 1;
				elseif (not seen[name]) then
					seen[name] = true;
					table.insert(queue, name);
				end
			else
				skipped = skipped + 1;
			end
		end);
	end
	table.sort(queue);
	if (#queue == 0) then
		if (
			automatedOptions
			and automatedOptions.mode == "pre_summon"
			and automatedOptions.continuation
		) then
			UnBotSpecSummonMessage(
				"Боевой состав изменился до начала опроса; продолжаю сбор без предварительной проверки."
				..(altSkipped > 0 and (" Альты не проверяются по спекам: "..tostring(altSkipped)..".") or "")
				..(reserveSkipped > 0 and (" Офлайн-резерв пропущен: "..tostring(reserveSkipped)..".") or "")
			);
			automatedOptions.continuation(automatedOptions.referenceZone);
		elseif (automatedOptions and automatedOptions.mode == "post_summon") then
			UnBotSpecSummonMessage(
				(altSkipped > 0
					and "Новые альты не проверяются по специализации; продолжаю очередь после призыва."
					or "Новые боты вышли из состава до итоговой проверки; продолжаю очередь после призыва.")
			);
			if (UnBotSquadPostSummonContinue) then
				UnBotSquadPostSummonContinue();
			end
		else
			UnBotSpecSummonMessage(
				"Проверка спеков: в текущем боевом составе нет онлайн-ботов из сохранённого реестра."
				..(altSkipped > 0 and (" Альты пропущены: "..tostring(altSkipped)..".") or "")
				..(reserveSkipped > 0 and (" Офлайн-резерв не проверяется: "..tostring(reserveSkipped)..".") or "")
			);
		end
		return;
	end

	UnBotSquadSpecCheck.active = true;
	UnBotSquadSpecCheck.autoStartAt = 0;
	UnBotSquadSpecCheck.autoOptions = nil;
	UnBotSquadSpecCheck.mode = automatedOptions and (automatedOptions.mode or "automatic") or "manual";
	UnBotSquadSpecCheck.continuation = automatedOptions and automatedOptions.continuation or nil;
	UnBotSquadSpecCheck.referenceZone = automatedOptions and automatedOptions.referenceZone or nil;
	UnBotSquadSpecCheck.queue = queue;
	UnBotSquadSpecCheck.index = 1;
	UnBotSquadSpecCheck.currentName = nil;
	UnBotSquadSpecCheck.attempts = 0;
	UnBotSquadSpecCheck.nextTime = GetTime();
	UnBotSquadSpecCheck.untilTime = 0;
	UnBotSquadSpecCheck.updated = 0;
	UnBotSquadSpecCheck.changed = 0;
	UnBotSquadSpecCheck.failed = 0;
	UnBotSquadSpecCheck.quarantinedDuringCheck = 0;
	UnBotSquadSpecCheck.results = {};
	if (UnBotBatchSummon) then UnBotBatchSummon.BeginCheck(); end
	UnBotSpecSummonMessage(
		(
			UnBotSquadSpecCheck.mode == "pre_summon"
			and "Предварительная проверка текущего состава: "
			or "Проверка спеков запущена: "
		)
		.."ботов "..tostring(#queue)
		..(skipped > 0 and (", пропущено неизвестных участников "..tostring(skipped)) or "")
		..(altSkipped > 0 and (", альты не проверяются "..tostring(altSkipped)) or "")
		..(reserveSkipped > 0 and (", офлайн-резерв не проверяется "..tostring(reserveSkipped)) or "").."."
	);
	UnBotSquadBuilderRefresh();
end

-- An explicit named server failure ends this WHO request, unlike silence.
function UnBotSquadSpecCheck.PlayerNotFound(message, name)
 if not name then return false; end
 local text=UnBotSpecSummonNormalize(message);
 if ERR_CHAT_PLAYER_NOT_FOUND_S and text==UnBotSpecSummonNormalize(string.format(ERR_CHAT_PLAYER_NOT_FOUND_S,name)) then return true; end
 for _,format in ipairs({"Персонаж по имени \"%s\" в игре не найден.",
  "No player named '%s' is currently playing.","No player named \"%s\" is currently playing."}) do
  if text==UnBotSpecSummonNormalize(string.format(format,name)) then return true; end
 end
 return false;
end
function UnBotSquadSpecCheck.FailCurrent(reason)
 local check=UnBotSquadSpecCheck;
 if not check.active or not check.currentName then return; end
 if UnBotSpecSummon.confirmedRoster then UnBotSpecSummon.confirmedRoster.Forget(check.currentName);end
 UnBotSpecSummonMessage("Спек не проверен: "..check.currentName.." "..reason..".");
 check.failed=check.failed+1;
 check.currentName=nil;check.index=check.index+1;check.attempts=0;
 check.untilTime=0;check.nextTime=GetTime()+.25;
 if check.index>#check.queue then UnBotSquadSpecCheckFinish();
 else UnBotSquadBuilderRefresh(); end
end
local UnBotSquadSpecCheckFrame = CreateFrame("Frame", "UnBotSquadSpecCheckFrame");
UnBotSquadSpecCheckFrame:RegisterEvent("CHAT_MSG_WHISPER");
UnBotSquadSpecCheckFrame:RegisterEvent("CHAT_MSG_SYSTEM");
UnBotSquadSpecCheckFrame:SetScript("OnEvent", function(self, event, message, sender)
	if (UnBotBatchSummon and UnBotBatchSummon.CheckReply(event,message,sender)) then return; end
	if not UnBotSquadSpecCheck.active or not UnBotSquadSpecCheck.currentName then return; end
	if event == "CHAT_MSG_SYSTEM" then
		if UnBotSquadSpecCheck.PlayerNotFound(message,UnBotSquadSpecCheck.currentName) then
			UnBotSquadSpecCheck.FailCurrent("в игре не найден; повторные who отменены");
		end
		return;
	end
	if event ~= "CHAT_MSG_WHISPER" or sender ~= UnBotSquadSpecCheck.currentName then return; end
	local whoInfo = UnBotSpecSummonParseWho(message);
	if (not whoInfo or not whoInfo.className or not whoInfo.specName) then
		return;
	end

	local oldClass, oldSpec = UnBotSquadSpecCheckStoreProfile(sender, whoInfo, message);
	UnBotSpecSummonEnsureTankStrategy(
		sender,
		whoInfo.className,
		whoInfo.specName,
		"spec-recheck"
	);
	local unit = UnBotBuffCycleResolveUnit(sender);
	UnBotSquadSpecCheck.results[sender] = {
		zoneName = whoInfo.zoneName,
		visible = unit and UnitIsVisible and UnitIsVisible(unit) and true or false,
		near = unit and CheckInteractDistance and CheckInteractDistance(unit, 1) and true or false,
	};
	UnBotSquadSpecCheck.updated = UnBotSquadSpecCheck.updated + 1;
	if (oldClass ~= whoInfo.className or oldSpec ~= whoInfo.specName) then
		UnBotSquadSpecCheck.changed = UnBotSquadSpecCheck.changed + 1;
		UnBotSpecSummonMessage(
			"Последний известный спек обновлён: "..sender.." | "
			..tostring(oldClass or "?").." "..tostring(oldSpec or "?")
			.." -> "..tostring(whoInfo.className).." "..tostring(whoInfo.specName).."."
		);
	else
		UnBotSpecSummonMessage(
			"Спек подтверждён: "..sender.." | "
			..tostring(whoInfo.className).." "..tostring(whoInfo.specName).."."
		);
	end

	UnBotSquadSpecCheck.currentName = nil;
	UnBotSquadSpecCheck.index = UnBotSquadSpecCheck.index + 1;
	UnBotSquadSpecCheck.attempts = 0;
	UnBotSquadSpecCheck.nextTime = GetTime() + 0.25;
	if (UnBotSquadSpecCheck.index > #UnBotSquadSpecCheck.queue) then
		UnBotSquadSpecCheckFinish();
	end
end);
UnBotSquadSpecCheckFrame:SetScript("OnUpdate", function()
	if (UnBotBatchSummon and UnBotBatchSummon.CheckTick()) then return; end
	local now = GetTime();
	if (not UnBotSquadSpecCheck.active) then
		if (
			(UnBotSquadSpecCheck.autoStartAt or 0) > 0
			and now >= UnBotSquadSpecCheck.autoStartAt
		) then
			local autoOptions = UnBotSquadSpecCheck.autoOptions;
			UnBotSquadSpecCheck.autoStartAt = 0;
			UnBotSquadSpecCheck.autoOptions = nil;
			UnBotSquadSpecCheckStart(autoOptions);
		end
		return;
	end
	if (now < (UnBotSquadSpecCheck.nextTime or 0)) then
		return;
	end
	if (UnBotSquadSpecCheck.index > #UnBotSquadSpecCheck.queue) then
		UnBotSquadSpecCheckFinish();
		return;
	end

	if (not UnBotSquadSpecCheck.currentName) then
		UnBotSquadSpecCheck.currentName = UnBotSquadSpecCheck.queue[UnBotSquadSpecCheck.index];
		local unit = UnBotBuffCycleResolveUnit(UnBotSquadSpecCheck.currentName);
		if not UnBotSpecSummonIsInGroup(UnBotSquadSpecCheck.currentName) or (unit and not UnitIsConnected(unit)) then
			UnBotSquadSpecCheck.FailCurrent("уже вышел из группы или офлайн; who пропущен");
			return;
		end
		UnBotSquadSpecCheck.attempts = 1;
		SendChatMessage("who", "WHISPER", nil, UnBotSquadSpecCheck.currentName);
		UnBotSquadSpecCheck.untilTime = now + 6;
		UnBotSquadSpecCheck.nextTime = now + 0.25;
		UnBotSquadBuilderRefresh();
	elseif (now >= UnBotSquadSpecCheck.untilTime) then
		if (UnBotSquadSpecCheck.attempts < 3) then
			UnBotSquadSpecCheck.attempts = UnBotSquadSpecCheck.attempts + 1;
			SendChatMessage("who", "WHISPER", nil, UnBotSquadSpecCheck.currentName);
			UnBotSquadSpecCheck.untilTime = now + 6;
			UnBotSquadSpecCheck.nextTime = now + 0.25;
		else
			-- Missing who alone does not authorize quarantine or removal.
			UnBotSquadSpecCheck.FailCurrent("не ответил после 3 попыток");
		end
	else
		UnBotSquadSpecCheck.nextTime = now + 0.25;
	end
end);

local function UnBotSquadBuilderMakeAddFunc(className, specKey, label, mode)
	return function()
		if (mode == "PVP") then
			if (UnBotPVPSquad and UnBotPVPSquad.Add) then
				UnBotPVPSquad.Add(className, specKey);
			else
				UnBotSpecSummonMessage("Редактор PVP-состава не загружен.");
			end
			return;
		end
		UnBotSquadBuilderAdd(className, specKey, label);
	end
end

local function UnBotSquadBuilderBuildMenu()
	local menu = {
		{ text = "Выберите раздел", isTitle = true, notCheckable = true },
	};
	if (UnBotAccountAlts and UnBotAccountAlts.BuildSquadMenu) then
		table.insert(menu, {
			text = "|cff69ccf0Свой аккаунт|r",
			notCheckable = true,
			hasArrow = true,
			menuList = UnBotAccountAlts.BuildSquadMenu(UnBotSquadBuilderAddAccountAlt),
			func = function() UnBotSquadBuilderAddAltAccount(); end,
		});
		if (UnBotAccountAlts.BuildLinkedSquadMenu) then
			table.insert(menu, {text="|cff69ccf0Связанные аккаунты|r",notCheckable=true,hasArrow=true,
				menuList=UnBotAccountAlts.BuildLinkedSquadMenu(UnBotSquadBuilderAddAccountAlt,UnBotSquadBuilderAddAltAccount)});
		end
	end
	for _, modeLabel in ipairs({"PVE", "PVP"}) do
		local classMenu = {
			{ text = "Клик по классу — любой спек", isTitle = true, notCheckable = true },
		};
		for i = 1, #UnBotSquadBuilderSpecs, 1 do
			local classInfo = UnBotSquadBuilderSpecs[i];
			local subMenu = {};
			for j = 1, #classInfo.specs, 1 do
				local spec = classInfo.specs[j];
				table.insert(subMenu, {
					text = spec.label,
					notCheckable = true,
					func = UnBotSquadBuilderMakeAddFunc(classInfo.className, spec.key, classInfo.label.." - "..spec.label, modeLabel),
				});
			end
			table.insert(classMenu, {
				text = classInfo.label,
				notCheckable = true,
				hasArrow = true,
				menuList = subMenu,
				func = UnBotSquadBuilderMakeAddFunc(
					classInfo.className,
					"any",
					classInfo.label.." - Любая специализация",
					modeLabel
				),
			});
		end
		table.insert(menu, {
			text = modeLabel,
			notCheckable = true,
			hasArrow = true,
			menuList = classMenu,
		});
	end
	return menu;
end

UnBotSquadRoleAction = UnBotSquadRoleAction or {
	active = false,
	name = nil,
	summonAfter = false,
	nextTime = 0,
	deadline = 0,
	attempts = 0,
};

function UnBotSquadRoleActionFinish(text)
	UnBotSquadRoleAction.active = false;
	UnBotSquadRoleAction.name = nil;
	UnBotSquadRoleAction.summonAfter = false;
	UnBotSquadRoleAction.nextTime = 0;
	UnBotSquadRoleAction.deadline = 0;
	UnBotSquadRoleAction.attempts = 0;
	if (text) then
		UnBotSpecSummonMessage(text);
	end
	UnBotSquadBuilderRefresh();
end

function UnBotSquadRoleSetOffline(name)
	if (not name or not UnBotSpecSummonIsInGroup(name)) then
		UnBotSpecSummonMessage("Нельзя перевести бота офлайн: он уже вне состава рейда.");
		return;
	end
	if (not UnBotRaidReserveOnline(name)) then
		UnBotSpecSummonMessage(tostring(name).." уже офлайн в ростере.");
		return;
	end
	UnBotBuffCycleSendWhisper(name, "stay");
	UnBotBuffCycle.cleanup[name] = nil;
	UnBotBuffCycle.lateRegistryNames[name] = nil;
	UnBotBuffCycleSendSay(".playerbot bot remove "..name);
	UnBotSpecSummonMessage(tostring(name)..": отправлена команда офлайн без исключения из ростера.");
end

function UnBotSquadRoleSetOnline(name, summonAfter)
	if (not name) then
		return;
	end
	if (UnBotSpecSummonIsInGroup(name) and UnBotRaidReserveOnline(name)) then
		if (summonAfter) then
			if (UnitIsDeadOrGhost and UnitIsDeadOrGhost("player") and UnBotRaidReserveLockRescuer) then
				UnBotRaidReserveLockRescuer(name, true);
				UnBotBuffCycleSendWhisper(name, "cast Rebirth on "..(UnitName("player") or ""));
			else
				UnBotBuffCycleSendWhisper(name, "summon");
			end
			UnBotRegistryRecordGameplaySummon(name, "squad-role-action");
			UnBotSpecSummonMessage(tostring(name)..": уже онлайн, отправлен summon.");
		else
			UnBotSpecSummonMessage(tostring(name).." уже онлайн.");
		end
		return;
	end
	if (UnBotSquadRoleAction.active) then
		UnBotSquadRoleActionFinish("Предыдущее включение бота остановлено.");
	end
	UnBotSquadRoleAction.active = true;
	UnBotSquadRoleAction.name = name;
	UnBotSquadRoleAction.summonAfter = summonAfter and true or false;
	UnBotSquadRoleAction.nextTime = GetTime() + 1;
	UnBotSquadRoleAction.deadline = GetTime() + 15;
	UnBotSquadRoleAction.attempts = 0;
	UnBotBuffCycleSendSay(".playerbot bot add "..name);
	UnBotSpecSummonMessage(tostring(name)..": возвращаю онлайн"
		..(summonAfter and ", затем призову к игроку." or "."));
end

function UnBotBotCenterAddExact(name)
	local profile = name and UnBotBotRegistry and UnBotBotRegistry.bots
		and UnBotBotRegistry.bots[name];
	if (not name or not profile) then
		UnBotSpecSummonMessage("Точное добавление: сначала выберите существующего бота в списке.");
		return false;
	end
	if (UnBotIsAccountAltProfile and UnBotIsAccountAltProfile(name, profile)) then
		UnBotSpecSummonMessage("Точное добавление: альты подключаются на отдельной вкладке «Альты».");
		return false;
	end
	if (UnBotSpecSummonIsInGroup(name) and UnBotRaidReserveOnline(name)) then
		UnBotSpecSummonMessage(tostring(name).." уже онлайн в вашей группе.");
		return false;
	end
	if ((InCombatLockdown and InCombatLockdown()) or UnitAffectingCombat("player")) then
		UnBotSpecSummonMessage("Точное добавление недоступно в бою.");
		return false;
	end
	if (UnBotSpecSummon.active) then
		UnBotSpecSummonMessage("Точное добавление: дождитесь завершения текущего призыва.");
		return false;
	end
	if (UnBotBuffCycle.active) then
		UnBotSpecSummonMessage("Точное добавление: сначала завершите текущий бафф-цикл.");
		return false;
	end
	if ((UnBotBotScanner and UnBotBotScanner.active) or (UnBotDKSpecBalance and UnBotDKSpecBalance.active)) then
		UnBotSpecSummonMessage("Точное добавление: сначала остановите обновление или проверку списка ботов.");
		return false;
	end
	if ((UnBotJunkCleaner and UnBotJunkCleaner.active) or (UnBotFastJunkRaid and UnBotFastJunkRaid.active)) then
		UnBotSpecSummonMessage("Точное добавление: сначала завершите обслуживание ботов.");
		return false;
	end
	if (UnBotLockboxService and UnBotLockboxService.active) then
		UnBotSpecSummonMessage("Точное добавление: сначала завершите текущую операцию с сундуком.");
		return false;
	end
	if (UnBotGroundChest and UnBotGroundChest.active) then
		UnBotSpecSummonMessage("Точное добавление: сначала остановите сеанс наземного сундука.");
		return false;
	end
	if (UnBotSquadRoleAction.active) then
		UnBotSpecSummonMessage("Точное добавление: уже ожидается вход другого выбранного бота.");
		return false;
	end
	UnBotSquadRoleSetOnline(name, false);
	return true;
end

function UnBotSquadRoleRelease(name)
	if (not name or not UnBotSpecSummonIsInGroup(name)) then
		UnBotSpecSummonMessage("Release Spirit не отправлен: бот вне состава рейда.");
		return;
	end
	if (not UnBotRaidReserveOnline(name)) then
		UnBotSpecSummonMessage(tostring(name).." офлайн; сначала верните его онлайн.");
		return;
	end
	UnBotBuffCycleSendWhisper(name, "release");
	UnBotSpecSummonMessage(tostring(name)..": отправлен Release Spirit.");
end

function UnBotSquadRoleCheckStatus(name)
	if (not name or not UnBotSpecSummonIsInGroup(name)) then
		UnBotSpecSummonMessage(tostring(name or "Бот")..": вне состава рейда.");
		return;
	end
	if (not UnBotRaidReserveOnline(name)) then
		UnBotSpecSummonMessage(tostring(name)..": офлайн в ростере; это резерв, проверка локации не выполняется.");
		return;
	end
	UnBotSquadSpecCheckStart({
		queue = {name},
		mode = "role_status",
		referenceZone = GetRealZoneText and GetRealZoneText() or nil,
	});
end

function UnBotSquadBuilderOpenRoleActions(row)
	local slot = row and UnBotSquadConfig.slots[row.slotIndex];
	local members = UnBotSquadBuilderSlotRosterMembers(slot);
	local menu = {{
		text = "Управление ботами роли",
		isTitle = true,
		notCheckable = true,
	}};
	if (#members == 0) then
		table.insert(menu, {
			text = "Назначенных ботов нет",
			disabled = true,
			notCheckable = true,
		});
	end
	for _, member in ipairs(members) do
		local botName = member.name;
		local botOnline = member.online;
		local botMenu = {
			{
				text = botOnline and "Перевести офлайн" or "Вернуть онлайн",
				notCheckable = true,
				func = function()
					if (botOnline) then
						UnBotSquadRoleSetOffline(botName);
					else
						UnBotSquadRoleSetOnline(botName, false);
					end
				end,
			},
			{
				text = "Summon к игроку",
				notCheckable = true,
				func = function() UnBotSquadRoleSetOnline(botName, true); end,
			},
			{
				text = "Release Spirit",
				notCheckable = true,
				disabled = not botOnline,
				func = function() UnBotSquadRoleRelease(botName); end,
			},
			{
				text = "Проверить статус и локацию",
				notCheckable = true,
				func = function() UnBotSquadRoleCheckStatus(botName); end,
			},
		};
		table.insert(menu, {
			text = (botOnline and "|cff00ff00" or "|cffaaaaaa")
				..botName..(botOnline and " — онлайн|r" or " — офлайн, резерв|r"),
			notCheckable = true,
			hasArrow = true,
			menuList = botMenu,
		});
	end
	EasyMenu(UnBotLocale.Menu(menu), UnBotSquadBuilder.actionMenuFrame, row, 0, 0, "MENU", 2);
end

UnBotSquadRoleActionFrame = UnBotSquadRoleActionFrame
	or CreateFrame("Frame", "UnBotSquadRoleActionFrame");
UnBotSquadRoleActionFrame:SetScript("OnUpdate", function()
	local state = UnBotSquadRoleAction;
	if (not state.active or GetTime() < (state.nextTime or 0)) then
		return;
	end
	local now = GetTime();
	local name = state.name;
	if (name and UnBotSpecSummonIsInGroup(name) and UnBotRaidReserveOnline(name)) then
		if (state.summonAfter) then
			if (UnitIsDeadOrGhost and UnitIsDeadOrGhost("player") and UnBotRaidReserveLockRescuer) then
				UnBotRaidReserveLockRescuer(name, true);
				UnBotBuffCycleSendWhisper(name, "cast Rebirth on "..(UnitName("player") or ""));
			else
				UnBotBuffCycleSendWhisper(name, "stay");
				UnBotBuffCycleSendWhisper(name, "summon");
			end
			UnBotRegistryRecordGameplaySummon(name, "squad-role-action");
		else
			UnBotBuffCycleSendWhisper(name, "stay");
		end
		UnBotSquadRoleActionFinish(tostring(name).." теперь онлайн"
			..(state.summonAfter and " и получил summon." or "."));
	elseif (now >= (state.deadline or 0)) then
		UnBotSquadRoleActionFinish(tostring(name)..": не удалось подтвердить онлайн-статус за 15 секунд.");
	else
		state.attempts = (state.attempts or 0) + 1;
		if (state.attempts == 3 or state.attempts == 6) then
			UnBotBuffCycleSendSay(".playerbot bot add "..tostring(name));
		end
		InviteUnit(tostring(name));
		state.nextTime = now + 1.5;
	end
end);

function UnBotSquadBuilderRequirementsText()
	local parts = {};
	for i = 1, #UnBotSquadConfig.slots, 1 do
		local slot = UnBotSquadConfig.slots[i];
		if (not slot.reserveOnly) then
			if (slot.accountAltName) then
				table.insert(parts, "@"..slot.accountAltName);
			else
				table.insert(
					parts,
					slot.className.." "..slot.specKey.." "..tostring(slot.count)
				);
			end
		end
	end
	return table.concat(parts, ", ");
end

UnBotSquadBuilderStart = function(keepBossPreset)
	if (UnBotGunshipMasterLoot and UnBotGunshipMasterLoot.paused) then
		return UnBotGunshipMasterLoot.ResumeSummon();
	end
	keepBossPreset = keepBossPreset == true;
	if (UnBotSquadNearbyGate and UnBotSquadNearbyGate.active) then
		UnBotSquadNearbyGateStop(
			"Предыдущее ожидание ботов рядом остановлено новым призывом состава.",
			false
		);
	end
	UnBotSquadBuilder.postSummonSequence = nil;
	if (not keepBossPreset) then
		UnBotSquadBuilder.pendingBossPreset = nil;
	end
	local botCount = UnBotSquadBuilderBotCount();
	if (botCount == 0) then
		UnBotSpecSummonMessage("Squad builder: add at least one bot.");
		return;
	end
	if (botCount > 39) then
		UnBotSpecSummonMessage("Squad builder: WoW allows at most 39 bots plus your character; selected "..tostring(botCount)..".");
		return;
	end
	local occupiedOffline = #UnBotSquadRosterReserveNames();
	if (botCount + occupiedOffline > 39) then
		UnBotSpecSummonMessage("Недостаточно мест: выбрано ботов "..botCount..", офлайн-участников в ростере "..occupiedOffline..". Вместе с игроком доступно 40 мест.");
		return;
	end
	if (UnBotSquadConfig.recordFullCombatLog) then
		UnBotSquadCombatLogApply(true, true);
	end

	if (UnBotSpecSummon.active) then
		UnBotSpecSummonStop("Previous summon stopped.");
	end
	UnBotSquadBuilder.postSummonSequence = {
		buffRaid = UnBotSquadConfig.buffRaidAfterSummon and true or false,
		bossPreset = keepBossPreset and UnBotSquadBuilder.pendingBossPreset or nil,
		locationReplacementRounds = 0,
		memberLimit = keepBossPreset
			and UnBotSquadPresetMemberLimit(UnBotSquadBuilder.pendingBossPreset)
			or nil,
	};
	UnBotGunshipMasterLoot.BeginSummon();
	if (UnBotGunshipMasterLoot.failureAnnounced) then return; end
	if UnBotGuardPosts and UnBotGuardPosts.Presets and UnBotGuardPosts.Presets.Quick then
		UnBotGuardPosts.Presets.Quick:OnSummon(keepBossPreset and UnBotSquadBuilder.pendingBossPreset or nil);
	end
	if (UnBotSummonLog) then
		UnBotSummonLog.Safe("Begin", UnBotSquadBuilderRequirementsText(), "builder");
	end
	UnBotSpecSummonSquadStart(UnBotSquadBuilderRequirementsText());
	if (UnBotTwinEmperors and UnBotTwinEmperors.ArmFromPreset
		and UnBotBossPresetLoadedAutoStrategyEnabled
		and UnBotBossPresetLoadedAutoStrategyEnabled("temple_of_ahn_qiraj__the_twin_emperors")) then
		UnBotTwinEmperors:ArmFromPreset();
	end
	UnBotSquadBuilderRefresh();
end

