-- Batch runners need the normal button callbacks after each reload without opening the editor.
UnBotSquadBuilder.EnsureWindow = UnBotSquadBuilderCreate;

function UnBotSquadBuilderToggle()
	UnBotSquadBuilderCreate();
	if (UnBotSquadBuilder.frame:IsShown()) then
		UnBotSquadBuilder.frame:Hide();
	else
		if (UnBotSpecAuditWindow) then
			UnBotSpecAuditWindow:Hide();
		end
		UnBotSquadBuilder.frame:Show();
	end
end

function UnBotSquadBuilderShow()
	UnBotSquadBuilderCreate();
	if (UnBotSpecAuditWindow) then
		UnBotSpecAuditWindow:Hide();
	end
	if (UnBotSquadBuilder.frame:IsShown()) then UnBotSquadBuilderRefresh();
	else UnBotSquadBuilder.frame:Show(); end
end

SLASH_UNBOTSQUADUI1 = "/ubsquadui";
SlashCmdList["UNBOTSQUADUI"] = UnBotSquadBuilderToggle;

SLASH_UNBOTSINDRAGOSA1 = "/ubsindra";
SlashCmdList["UNBOTSINDRAGOSA"] = function(message)
	local command = UnBotSpecSummonNormalize(message);
	if (command == "alert" or command == "test" or command == "тест") then
		UnBotSindragosaShowCenterAirAlert();
		UnBotSpecSummonMessage(
			"Синдрагоса: показано тестовое предупреждение воздушной фазы."
		);
		return;
	end
	if (command == "off" or command == "стоп") then
		UnBotSindragosaRestorePhaseThreeDps("режим отключён вручную", true);
		UnBotSindragosaRestoreIcc("режим отключён вручную", true);
		for name in pairs(UnBotSindragosaPrep.assignedNames or {}) do
			local unit = UnBotBuffCycleResolveUnit(name);
			if (unit and UnitIsConnected(unit)) then
				UnBotBuffCycleSendWhisper(name, "nc -ss tank,-ss healer,-ss self");
			end
		end
		UnBotSindragosaPrep.armed = false;
		UnBotSindragosaPrep.active = false;
		UnBotSindragosaPrep.maintenance = false;
		UnBotSindragosaPrep.focusEnabled = false;
		UnBotSindragosaPrep.stage = "idle";
		UnBotSpecSummonMessage("Режим Синдрагосы отключён вручную.");
		return;
	end
	local onlyLoad = command == "load";
	UnBotSindragosaLoadPreset(not onlyLoad);
end;

UnBotDalaranPortal = UnBotDalaranPortal or {
	active = false,
	mageName = nil,
	stage = nil,
	nextTime = 0,
	destinationKey = "dalaran",
};

UnBotPortalDestinations = {
	dalaran = { label = "Даларан", spell = "Portal: Dalaran" },
	shattrath = { label = "Шаттрат", spell = "Portal: Shattrath" },
	stormwind = { label = "Штормград", spell = "Portal: Stormwind" },
	ironforge = { label = "Стальгорн", spell = "Portal: Ironforge" },
	darnassus = { label = "Дарнас", spell = "Portal: Darnassus" },
	exodar = { label = "Экзодар", spell = "Portal: Exodar" },
	theramore = { label = "Терамор", spell = "Portal: Theramore" },
	orgrimmar = { label = "Оргриммар", spell = "Portal: Orgrimmar" },
	undercity = { label = "Подгород", spell = "Portal: Undercity" },
	thunderbluff = { label = "Громовой Утёс", spell = "Portal: Thunder Bluff" },
	silvermoon = { label = "Луносвет", spell = "Portal: Silvermoon" },
	stonard = { label = "Каменор", spell = "Portal: Stonard" },
};

function UnBotPortalDestination()
	return UnBotPortalDestinations[UnBotDalaranPortal.destinationKey or "dalaran"]
		or UnBotPortalDestinations.dalaran;
end

function UnBotDalaranPortalMageReady(name)
	local destination = UnBotPortalDestination();
	if (not name or not UnBotSpecSummonIsInGroup(name)) then
		UnBotSpecSummonMessage("Портал в "..destination.label..": вызванный маг не найден в группе.");
		return;
	end
	UnBotDalaranPortal.active = true;
	UnBotDalaranPortal.mageName = name;
	UnBotDalaranPortal.stage = "summon";
	UnBotDalaranPortal.nextTime = GetTime() + 0.5;
	UnBotDalaranPortal.deadline = GetTime() + 90;
	UnBotDalaranPortal.summonAttempts = 0;
	UnBotDalaranPortal.castAttempts = 0;
	UnBotDalaranPortal.castSentAt = nil;
	UnBotDalaranPortal.castStarted = nil;
	UnBotDalaranPortal.manaNotice = nil;
	UnBotSpecSummonMessage(
		"Портал в "..destination.label..": маг "..name.." готов. Телепортирую его к игроку и запускаю каст."
	);
end

function UnBotDalaranPortalFindCurrentMage()
	local members = UnBotSpecSummonGetMembers();
	for name in pairs(members) do
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (
			name ~= UnitName("player")
			and profile
			and UnBotSpecSummonNormalize(profile.className) == "mage"
			and UnBotSquadRosterFindUnit(name)
			and UnitIsConnected(UnBotSquadRosterFindUnit(name))
			and not UnitIsDeadOrGhost(UnBotSquadRosterFindUnit(name))
		) then
			return name;
		end
	end
	return nil;
end

function UnBotDalaranPortalStart(destinationKey)
	if (UnBotDalaranPortal.active) then
		UnBotSpecSummonMessage("Портал: операция уже выполняется; повторный клик не нужен.");
		return;
	end
	if (UnitAffectingCombat("player") or UnitIsDeadOrGhost("player")) then
		UnBotSpecSummonMessage("Портал: запуск доступен живым и вне боя.");
		return;
	end
	if (UnBotDKSpecBalance and UnBotDKSpecBalance.active) then
		UnBotSpecSummonMessage("Сначала остановите выравнивание спеков по количеству.");
		return;
	end
	if (type(destinationKey) ~= "string" or not UnBotPortalDestinations[destinationKey]) then
		destinationKey = "dalaran";
	end
	UnBotDalaranPortal.destinationKey = destinationKey;
	local destination = UnBotPortalDestination();
	if (UnBotSpecSummon.active) then
		UnBotSpecSummonMessage("Портал в "..destination.label..": дождитесь завершения текущего призыва.");
		return;
	end
	if (UnBotBotScanner and UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Портал в "..destination.label..": сначала остановите полный скан ботов.");
		return;
	end
	if (UnBotJunkCleaner and UnBotJunkCleaner.active) then
		UnBotSpecSummonMessage("Портал в "..destination.label..": сначала остановите продажу хлама.");
		return;
	end
	if (UnBotFastJunkRaid and UnBotFastJunkRaid.active) then
		UnBotSpecSummonMessage("Портал в "..destination.label..": сначала остановите быструю рейдовую продажу/закупку.");
		return;
	end
	if (UnBotBuffCycle and UnBotBuffCycle.active) then
		UnBotSpecSummonMessage("Портал в "..destination.label..": сначала завершите цикл баффов.");
		return;
	end
	if (UnBotSoulstoneTest and UnBotSoulstoneTest.active) then
		UnBotSpecSummonMessage("Портал в "..destination.label..": сначала завершите тест Soulstone.");
		return;
	end

	local currentMage = UnBotDalaranPortalFindCurrentMage();
	if (currentMage) then
		UnBotDalaranPortalMageReady(currentMage);
		return;
	end
	local raidCount = GetNumRaidMembers() or 0;
	if (raidCount >= 40 or (raidCount == 0 and (GetNumPartyMembers() or 0) >= 4)) then
		UnBotSpecSummonMessage("Портал в "..destination.label..": нет свободного места для мага; офлайн-резерв тоже занимает место.");
		return;
	end

	local mageSpecs = {"arcane", "fire", "frost"};
	local registryCount = UnBotRegistryCandidateCount("mage", mageSpecs);
	if (registryCount == 0) then
		UnBotSpecSummonMessage(
			"Портал в "..destination.label..": в реестре нет доступного мага. "
			.."Проверьте /ubflag list или запустите полный скан."
		);
		return;
	end

	UnBotSpecSummon.active = true;
	UnBotSpecSummon.registryMode = true;
	UnBotSpecSummon.mode = "single";
	UnBotSpecSummon.className = "mage";
	UnBotSpecSummon.currentClassName = "mage";
	UnBotSpecSummon.specName = "любой спек";
	UnBotSpecSummon.specAliases = mageSpecs;
	UnBotSpecSummon.squad = nil;
	UnBotSpecSummon.tries = 0;
	UnBotSpecSummon.checked = {};
	UnBotSpecSummon.rejectedOnline = {};
	UnBotSpecSummon.kickQueue = {};
	UnBotSpecSummon.cleanupQueue = {};
	UnBotSpecSummon.requestedName = nil;
	UnBotSpecSummon.requestedSlot = nil;
	UnBotSpecSummon.completionAction = UnBotDalaranPortalMageReady;
	UnBotSpecSummon.completionSource = "dalaran-portal";
	UnBotSpecSummonMessage(
		"Портал в "..destination.label..": выбираю мага, которого дольше всего не призывали, из "
		..tostring(registryCount).." профилей реестра."
	);
	UnBotSpecSummonTryNext();
end

function UnBotDalaranPortal.Stop(reason)
	local state = UnBotDalaranPortal;
	state.active = false;
	state.stage = nil;
	state.nextTime = 0;
	UnBotSpecSummonMessage("Портал в "..UnBotPortalDestination().label..": "..reason);
end

function UnBotDalaranPortal.IsPortalSpell(spellName, spellID)
	local destination = UnBotPortalDestination();
	-- The server accepts English commands; client events carry localized names.
	return spellName == destination.spell
		or spellName == "Портал: "..destination.label
		or (UnBotDalaranPortal.destinationKey == "dalaran" and GetSpellInfo
			and spellName and spellName == GetSpellInfo(53142))
		or (UnBotDalaranPortal.destinationKey == "dalaran" and tonumber(spellID) == 53142);
end

function UnBotDalaranPortal.OnEvent(event, ...)
	local state = UnBotDalaranPortal;
	if (not state.active or not state.castSentAt) then return; end
	if (event == "CHAT_MSG_WHISPER") then
		local message, sender = ...;
		if (UnBotAccountAlts.SenderKey(sender) ~= UnBotAccountAlts.SenderKey(state.mageName)) then return; end
		local text = tostring(message or ""):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "");
		local lower = string.lower(text);
		if (lower:find("unknown spell", 1, true) or lower:find("cannot cast", 1, true)
			or lower:find("no items", 1, true) or lower:find("level is too low", 1, true)
			or lower:find("not enough", 1, true)) then
			state.Stop(state.mageName..": "..text..". Автоматические попытки остановлены.");
		elseif (lower:find("is failed", 1, true) and lower:find("cast ", 1, true)
			and not state.castStarted and state.stage == "verify") then
			-- Upstream CastSpell first stands a seated bot and returns false.
			-- This generic response permits a bounded retry; Cannot cast never does.
			if (state.castAttempts < 3) then
				state.stage = "cast";
				state.nextTime = GetTime() + 2;
			else
				state.Stop(state.mageName..": "..text..". Три попытки исчерпаны.");
			end
		end
	elseif (event == "UNIT_SPELLCAST_SUCCEEDED" or event == "UNIT_SPELLCAST_START") then
		local unit, spellName = ...;
		if (not unit or UnitName(unit) ~= state.mageName or not state.IsPortalSpell(spellName)) then return; end
		if (event == "UNIT_SPELLCAST_SUCCEEDED") then
			state.Stop("каст портала подтверждён. Маг "..state.mageName.." остаётся в группе.");
		else state.castStarted = true; end
	elseif (event == "COMBAT_LOG_EVENT_UNFILTERED") then
		-- WotLK 3.3.5 payload, before hideCaster/raidFlags were added.
		local timestamp, kind, sourceGUID, sourceName, sourceFlags,
			destGUID, destName, destFlags, spellID, spellName = ...;
		local unit = UnBotSquadRosterFindUnit(state.mageName);
		if (not unit or not sourceGUID or sourceGUID ~= UnitGUID(unit)
			or not state.IsPortalSpell(spellName, spellID)) then return; end
		if (kind == "SPELL_CAST_SUCCESS") then
			state.Stop("каст портала подтверждён. Маг "..state.mageName.." остаётся в группе.");
		elseif (kind == "SPELL_CAST_START") then
			state.castStarted = true;
		elseif (kind == "SPELL_CAST_FAILED") then
			state.Stop("сервер сообщил о неудачном касте мага "..state.mageName..". Повторы остановлены.");
		end
	end
end

UnBotDalaranPortalFrame = UnBotDalaranPortalFrame
	or CreateFrame("Frame", "UnBotDalaranPortalFrame");
UnBotDalaranPortalFrame:RegisterEvent("CHAT_MSG_WHISPER");
UnBotDalaranPortalFrame:RegisterEvent("COMBAT_LOG_EVENT_UNFILTERED");
UnBotDalaranPortalFrame:RegisterEvent("UNIT_SPELLCAST_SUCCEEDED");
UnBotDalaranPortalFrame:RegisterEvent("UNIT_SPELLCAST_START");
UnBotDalaranPortalFrame:SetScript("OnEvent", function(self, event, ...)
	UnBotDalaranPortal.OnEvent(event, ...);
end);
UnBotDalaranPortalFrame:SetScript("OnUpdate", function(self)
	if (
		not UnBotDalaranPortal.active
		or GetTime() < (UnBotDalaranPortal.nextTime or 0)
	) then
		return;
	end
	local name = UnBotDalaranPortal.mageName;
	local destination = UnBotPortalDestination();
	local state = UnBotDalaranPortal;
	local now = GetTime();
	state.nextTime = now + 0.25;
	if (not name or not UnBotSpecSummonIsInGroup(name)) then
		state.Stop("маг покинул группу, операция остановлена.");
		return;
	end
	local unit = UnBotSquadRosterFindUnit(name);
	if (UnitAffectingCombat("player") or UnitIsDeadOrGhost("player")
		or (unit and (UnitAffectingCombat(unit) or UnitIsDeadOrGhost(unit)))) then
		state.Stop("бой или смерть: операция остановлена.");
		return;
	end
	if (unit and not UnitIsConnected(unit)) then
		state.Stop("маг отключился; операция остановлена.");
		return;
	end
	if (now >= state.deadline) then
		state.Stop("истекло время ожидания мага/каста (90 секунд). Портал не подтверждён.");
		return;
	end
	if (state.stage == "summon") then
		state.summonAttempts = state.summonAttempts + 1;
		SendChatMessage("summon", "WHISPER", nil, name);
		state.stage = "arrival";
		state.arrivalDeadline = now + 8;
		state.nextTime = now + 2.5;
	elseif (state.stage == "arrival") then
		if (not unit or not UnBotSquadNearbyGateUnitReady(unit)) then
			if (now >= state.arrivalDeadline) then
				if (state.summonAttempts < 3) then state.stage = "summon";
				else state.Stop("маг не появился рядом после трёх попыток призыва."); end
			end
			return;
		end
		SendChatMessage("stay", "WHISPER", nil, name);
		state.stage = "cast";
		state.nextTime = now + 1;
	elseif (state.stage == "cast") then
		if (not unit or not UnBotSquadNearbyGateUnitReady(unit)) then
			state.Stop("маг перестал быть доступен рядом; каст отменён.");
			return;
		end
		if (UnitCastingInfo and UnitCastingInfo(unit)) then return; end
		if (UnitChannelInfo and UnitChannelInfo(unit)) then return; end
		-- A portal costs base mana; 20% of maximum is a conservative readiness gate.
		if (UnitManaMax(unit) <= 0 or UnitMana(unit) < UnitManaMax(unit) * 0.20) then
			if (not state.manaNotice) then
				state.manaNotice = true;
				UnBotSpecSummonMessage("Портал в "..destination.label..": жду ману мага; каст продолжится автоматически.");
			end
			return;
		end
		state.castAttempts = state.castAttempts + 1;
		state.castSentAt = now;
		state.castStarted = nil;
		state.stage = "verify";
		state.verifyDeadline = now + 18;
		-- 'reset' clears the AI food delay without resetting class strategies.
		-- Queue the cast immediately after it, before the bot chooses another meal.
		SendChatMessage("reset", "WHISPER", nil, name);
		SendChatMessage("cast "..destination.spell.." on "..name, "WHISPER", nil, name);
		UnBotSpecSummonMessage("Портал в "..destination.label..": прерываю отдых "..name
			..", запускаю каст ("..state.castAttempts.."/3) и жду подтверждения.");
	elseif (state.stage == "verify") then
		local castName = unit and UnitCastingInfo and UnitCastingInfo(unit);
		if (castName and state.IsPortalSpell(castName)) then state.castStarted = true; end
		if (now < state.verifyDeadline) then return; end
		if (state.castStarted) then
			state.Stop("начало каста было замечено, но завершение не подтверждено. Повтор не отправлен, чтобы не создать второй портал.");
		elseif (state.castAttempts < 3) then
			state.stage = "cast";
		else
			state.Stop("маг не начал портал после трёх попыток. Сервер не подтвердил выполнение.");
		end
	end
end);

UnBotLockboxService = UnBotLockboxService or {
	active = false,
	operation = nil,
	rogueName = nil,
	stage = nil,
	nextTime = 0,
	deadline = 0,
	summonAttempts = 0,
	nextSummonAt = 0,
	addedByService = false,
	offlineAttempts = 0,
	nextOfflineAt = 0,
	lockpickReplySeen = false,
	lockpickFound = false,
	lockpickQuietDeadline = 0,
	lockpickHardDeadline = 0,
};

function UnBotLockboxServiceStop(text, keepRogue)
	UnBotLockboxService.active = false;
	UnBotLockboxService.stage = nil;
	UnBotLockboxService.nextTime = math.huge;
	UnBotLockboxService.deadline = 0;
	UnBotLockboxService.summonAttempts = 0;
	UnBotLockboxService.nextSummonAt = 0;
	UnBotLockboxService.offlineAttempts = 0;
	UnBotLockboxService.nextOfflineAt = 0;
	UnBotLockboxService.lockpickReplySeen = false;
	UnBotLockboxService.lockpickFound = false;
	UnBotLockboxService.lockpickQuietDeadline = 0;
	UnBotLockboxService.lockpickHardDeadline = 0;
	UnBotLockboxService.tradeRequestPending = false;
	UnBotLockboxService.tradeMissingSince = nil;
	if (not keepRogue) then
		UnBotLockboxService.rogueName = nil;
		UnBotLockboxService.addedByService = false;
		UnBotLockboxService.operation = nil;
	end
	if (text) then
		UnBotSpecSummonMessage(text);
	end
end

function UnBotLockboxServiceStoreLockpickCapability(name, capable)
	if (not name) then
		return;
	end
	UnBotRegistryAttachStorage();
	local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (not profile) then
		return;
	end
	profile.lockpickSpellKnown = capable and true or false;
	profile.lockpickSpellId = capable and 1804 or nil;
	profile.lockpickSpellCheckedAt = time();
end

function UnBotLockboxServiceSenderMatches(sender)
	local expected = UnBotSpecSummonNormalize(UnBotLockboxService.rogueName);
	local actual = tostring(sender or "");
	actual = string.gsub(actual, "|c%x%x%x%x%x%x%x%x", "");
	actual = string.gsub(actual, "|r", "");
	actual = string.match(actual, "^([^-]+)") or actual;
	return expected ~= "" and UnBotSpecSummonNormalize(actual) == expected;
end

function UnBotLockboxServiceFinish(text)
	local name = UnBotLockboxService.rogueName;
	if (UnBotLockboxService.operation == "trade") then
		UnBotLockboxServiceStop(
			tostring(text or "Вскрытие сундука завершено.")
			.." Разбойник остаётся в группе для следующих сейфов. Отпустите его вручную, когда закончите.",
			false
		);
		return;
	end
	if (
		UnBotLockboxService.addedByService
		and name
		and UnBotSpecSummonIsInGroup(name)
	) then
		UnBotLockboxService.active = true;
		UnBotLockboxService.stage = "wait_offline";
		UnBotLockboxService.nextTime = GetTime() + 0.4;
		UnBotLockboxService.deadline = GetTime() + 8;
		UnBotLockboxService.offlineAttempts = 1;
		UnBotLockboxService.nextOfflineAt = GetTime() + 3;
		UnBotBuffCycleSendSay(".playerbot bot remove "..name);
		UnBotSpecSummonMessage(
			tostring(text or "Вскрытие сундука завершено.")
			.." Временный разбойник "..name
			.." переводится офлайн и остаётся участником ростера; команда исключения из группы не отправляется."
		);
		return;
	end
	UnBotLockboxServiceStop(
		tostring(text or "Вскрытие сундука завершено.")
		.." Разбойник был в исходном составе и оставлен без изменений.",
		false
	);
end

function UnBotLockboxServiceFindCurrentRogue(operation)
	UnBotRegistryAttachStorage();
	local members = UnBotSpecSummonGetMembers();
	local confirmedName = nil;
	local unknownName = nil;
	for name in pairs(members) do
		local unit = UnBotSquadRosterFindUnit(name);
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (
			name ~= UnitName("player")
			and unit
			and UnitIsConnected(unit)
			and profile
			and UnBotSpecSummonNormalize(profile.className) == "rogue"
			and not UnBotIsAccountAltProfile(name, profile)
		) then
			if (operation ~= "world") then
				return name;
			elseif (profile.lockpickSpellKnown == true) then
				confirmedName = confirmedName or name;
			elseif (profile.lockpickSpellKnown ~= false) then
				unknownName = unknownName or name;
			end
		end
	end
	return confirmedName or unknownName;
end

function UnBotLockboxServiceRogueReady(name)
	if (not name or not UnBotSpecSummonIsInGroup(name)) then
		UnBotLockboxServiceStop("Вскрытие сундука: вызванный дикий разбойник не найден в группе.");
		return;
	end
	UnBotLockboxService.rogueName = name;
	UnBotLockboxService.tradeAttempts = 0;
	UnBotLockboxService.tradeRequestPending = false;
	UnBotLockboxService.tradeMissingSince = nil;
	if ((InCombatLockdown and InCombatLockdown()) or UnitAffectingCombat("player")) then
		UnBotLockboxServiceFinish(
			"Вскрытие сундука: игрок вошёл в бой. Обмен не открывался; повторите сервис вне боя."
		);
		return;
	end
	UnBotLockboxService.active = true;
	UnBotLockboxService.summonAttempts = 0;
	UnBotLockboxService.nextSummonAt = 0;
	if (UnBotLockboxService.addedByService) then
		UnBotLockboxService.stage = "wait_poison";
		UnBotLockboxService.nextTime = GetTime() + 9;
		UnBotLockboxService.deadline = GetTime() + 20;
		UnBotSpecSummonMessage(
			(UnBotLockboxService.operation == "world"
				and "Наземный сундук: дикий разбойник "
				or "Lockbox из сумки: дикий разбойник ")..name
			.." вошёл в группу. Жду 9 секунд, пока он нанесёт яды на оружие; "
			..(UnBotLockboxService.operation == "world"
				and "после паузы проверю наличие Взлома замка (spell 1804)."
				or "до окончания паузы обмен не открывается.")
		);
	else
		UnBotLockboxService.stage = UnBotLockboxService.operation == "world"
			and "query_lockpick"
			or "summon";
		UnBotLockboxService.nextTime = GetTime() + 0.25;
		UnBotLockboxService.deadline = GetTime() + (UnBotLockboxService.operation == "world" and 7 or 15);
		UnBotSpecSummonMessage(
			(UnBotLockboxService.operation == "world"
				and "Наземный сундук: разбойник "..name
					.." уже находился в составе. Сначала проверяю наличие Взлома замка (spell 1804)."
				or "Lockbox из сумки: дикий разбойник "..name
					.." уже находился в составе. Подзываю его и открываю обмен.")
		);
	end
end

function UnBotLockboxService.IsOwnTradeVisible()
	return TradeFrame and TradeFrame:IsShown()
		and UnBotLockboxServiceSenderMatches(UnitName("NPC"));
end

function UnBotLockboxService.RecoverTrade(reason, retry)
	local state = UnBotLockboxService;
	if (TradeFrame and TradeFrame:IsShown()) then
		return;
	end
	-- Change stage BEFORE CloseTrade: its TRADE_CLOSED must not finish this service.
	state.stage = "retry_trade";
	state.nextTime = GetTime() + 1;
	state.deadline = GetTime() + 6;
	local partner = UnitName("NPC");
	if (state.tradeRequestPending) then
		state.tradeRequestPending = false;
		if (
			(InCombatLockdown and InCombatLockdown()) or UnitAffectingCombat("player")
			or (partner and partner ~= "" and not UnBotLockboxServiceSenderMatches(partner))
			or not CloseTrade
		) then
			retry = false;
		elseif (not pcall(CloseTrade)) then
			retry = false;
		end
	end
	if (retry and (state.tradeAttempts or 0) < 3) then
		UnBotSpecSummonMessage("Lockbox из сумки: "..tostring(reason)
			..". Сбрасываю запрос и повторю обмен с "..tostring(state.rogueName)
			.." (попытка "..tostring((state.tradeAttempts or 0) + 1).."/3).");
	else
		UnBotLockboxServiceManualFallback(reason);
	end
end

function UnBotLockboxServiceTradeReady()
	if (not UnBotLockboxService.IsOwnTradeVisible()) then
		return;
	end
	local name = UnBotLockboxService.rogueName or "разбойник";
	UnBotLockboxService.active = true;
	UnBotLockboxService.stage = "trade_open";
	UnBotLockboxService.nextTime = GetTime() + 0.2;
	UnBotLockboxService.deadline = GetTime() + 180;
	UnBotLockboxService.tradeRequestPending = false;
	UnBotLockboxService.tradeMissingSince = nil;
	UnBotSpecSummonMessage(
		"Lockbox из сумки: окно обмена с "..name.." открыто. Положите запертый сундук"
		.." и нажмите «Обмен». UnBot не кладёт предмет и не подтверждает сделку за вас. "
		.."Разбойник останется в группе для следующих сейфов. Отпустите его вручную, когда закончите."
	);
end

function UnBotLockboxServiceManualFallback(reason)
	local name = UnBotLockboxService.rogueName or "разбойника";
	UnBotLockboxService.active = true;
	UnBotLockboxService.stage = "manual_trade";
	UnBotLockboxService.nextTime = GetTime() + 0.25;
	UnBotLockboxService.deadline = GetTime() + 120;
	UnBotSpecSummonMessage(
		"Вскрытие сундука: "..tostring(reason or "обмен не открылся автоматически")
		..". Подойдите к разбойнику "..name.." и откройте с ним обмен вручную, "
		.."положите сундук и нажмите «Обмен». Ожидание ограничено двумя минутами; "
		.."разбойник останется в группе. Отпустите его вручную, когда закончите."
	);
end

function UnBotLockboxServiceStart(operation)
	operation = operation == "world" and "world" or "trade";
	if (operation == "world") then
		if (UnBotGroundChestOpen) then
			UnBotGroundChestOpen();
		else
			UnBotSpecSummonMessage("Наземный сундук: отдельное окно ещё не загрузилось; выполните полный перезапуск клиента WoW.");
		end
		return;
	end
	if (UnBotGroundChest and UnBotGroundChest.active) then
		UnBotSpecSummonMessage("Lockbox из сумки: сначала остановите сеанс наземного сундука.");
		return;
	end
	if (UnBotLockboxService.active) then
		UnBotSpecSummonMessage("Операция с сундуком уже выполняется; сначала завершите или закройте текущее окно сервиса.");
		return;
	end
	if ((InCombatLockdown and InCombatLockdown()) or UnitAffectingCombat("player")) then
		UnBotSpecSummonMessage("Вскрытие сундука нельзя запускать в бою.");
		return;
	end
	if (TradeFrame and TradeFrame:IsShown()) then
		UnBotSpecSummonMessage("Вскрытие сундука: сначала закройте текущее окно обмена.");
		return;
	end
	if (UnBotSpecSummon.active) then
		UnBotSpecSummonMessage("Вскрытие сундука: дождитесь завершения текущего призыва.");
		return;
	end
	if (UnBotBotScanner and UnBotBotScanner.active) then
		UnBotSpecSummonMessage("Вскрытие сундука: сначала остановите полный скан ботов.");
		return;
	end
	if (UnBotJunkCleaner and UnBotJunkCleaner.active) then
		UnBotSpecSummonMessage("Вскрытие сундука: сначала остановите продажу хлама.");
		return;
	end
	if (UnBotFastJunkRaid and UnBotFastJunkRaid.active) then
		UnBotSpecSummonMessage("Вскрытие сундука: сначала остановите быструю рейдовую продажу/закупку.");
		return;
	end
	if (UnBotBuffCycle and UnBotBuffCycle.active) then
		UnBotSpecSummonMessage("Вскрытие сундука: сначала завершите цикл баффов.");
		return;
	end
	if (UnBotSoulstoneTest and UnBotSoulstoneTest.active) then
		UnBotSpecSummonMessage("Вскрытие сундука: сначала завершите тест Soulstone.");
		return;
	end

	local currentRogue = UnBotLockboxServiceFindCurrentRogue(operation);
	UnBotLockboxService.operation = operation;
	if (currentRogue) then
		UnBotLockboxService.addedByService = false;
		UnBotLockboxServiceRogueReady(currentRogue);
		return;
	end

	local rogueSpecs = {"assassination", "assasination", "combat", "subtlety"};
	local excludedRogues = {};
	if (operation == "world") then
		UnBotRegistryAttachStorage();
		for name, profile in pairs(UnBotBotRegistry.bots or {}) do
			if (profile.lockpickSpellKnown == false) then
				excludedRogues[name] = true;
			end
		end
	end
	local registryCount = #UnBotRegistryCandidates("rogue", rogueSpecs, excludedRogues, true);
	if (registryCount == 0) then
		UnBotSpecSummonMessage(
			"Вскрытие сундука: в реестре нет доступного дикого разбойника. "
			.."Альты аккаунта для этого сервиса намеренно не используются. "
			.."Проверьте /ubflag list или запустите полный скан."
		);
		return;
	end

	UnBotSpecSummon.active = true;
	UnBotSpecSummon.registryMode = true;
	UnBotSpecSummon.mode = "single";
	UnBotSpecSummon.className = "rogue";
	UnBotSpecSummon.currentClassName = "rogue";
	UnBotSpecSummon.specName = "любой спек для вскрытия";
	UnBotSpecSummon.specAliases = rogueSpecs;
	UnBotSpecSummon.squad = nil;
	UnBotSpecSummon.tries = 0;
	UnBotSpecSummon.checked = excludedRogues;
	UnBotSpecSummon.rejectedOnline = {};
	UnBotSpecSummon.kickQueue = {};
	UnBotSpecSummon.cleanupQueue = {};
	UnBotSpecSummon.requestedName = nil;
	UnBotSpecSummon.requestedSlot = nil;
	UnBotSpecSummon.requestedFallback = false;
	UnBotSpecSummon.initAttempts = 0;
	UnBotSpecSummon.lastInitAt = 0;
	UnBotSpecSummon.whoAttempts = 0;
	UnBotSpecSummon.extraNames = {};
	UnBotSpecSummon.verifiedCandidates = {};
	UnBotSpecSummon.initUsed = {};
	UnBotSpecSummon.preferLockpick = operation == "world";
	UnBotLockboxService.addedByService = true;
	UnBotSpecSummon.completionAction = UnBotLockboxServiceRogueReady;
	UnBotSpecSummon.completionSource = "lockbox-service";
	UnBotSpecSummonMessage(
		(operation == "world"
			and "Наземный сундук: вызываю разбойника и проверю Взлом замка по spell ID 1804; "
			or "Lockbox из сумки: вызываю дикого разбойника для обмена; ")
		.."не более 3 попыток из "..tostring(registryCount).." доступных профилей."
	);
	UnBotSpecSummonTryNext();
end

UnBotLockboxServiceFrame = UnBotLockboxServiceFrame
	or CreateFrame("Frame", "UnBotLockboxServiceFrame");
UnBotLockboxServiceFrame:RegisterEvent("TRADE_SHOW");
UnBotLockboxServiceFrame:RegisterEvent("TRADE_CLOSED");
UnBotLockboxServiceFrame:RegisterEvent("UI_ERROR_MESSAGE");
UnBotLockboxServiceFrame:RegisterEvent("PLAYER_REGEN_DISABLED");
UnBotLockboxServiceFrame:RegisterEvent("CHAT_MSG_WHISPER");
UnBotLockboxServiceFrame:SetScript("OnEvent", function(self, event, message, sender)
	if (not UnBotLockboxService.active) then
		return;
	end
	if (
		event == "CHAT_MSG_WHISPER"
		and UnBotLockboxService.operation == "world"
		and UnBotLockboxService.stage == "wait_lockpick_spells"
		and UnBotLockboxServiceSenderMatches(sender)
	) then
		local text = tostring(message or "");
		UnBotLockboxService.lockpickReplySeen = true;
		UnBotLockboxService.lockpickQuietDeadline = GetTime() + 1.5;
		if (
			string.find(text, "Hspell:1804", 1, true)
			or string.find(text, "spell:1804", 1, true)
		) then
			UnBotLockboxService.lockpickFound = true;
		end
		return;
	end
	if (
		event == "TRADE_SHOW"
		and UnBotLockboxService.operation == "trade"
		and UnBotLockboxService.stage ~= "trade_open"
	) then
		-- TradeFrame may process TRADE_SHOW after us, or fail to show at all.
		-- Let OnUpdate verify the visible window and actual NPC partner.
		return;
	elseif (event == "TRADE_CLOSED" and UnBotLockboxService.stage == "trade_open") then
		UnBotLockboxService.nextTime = GetTime() + 0.2;
	elseif (
		event == "UI_ERROR_MESSAGE"
		and UnBotLockboxService.stage == "wait_trade"
		and UnBotLockboxService.tradeRequestPending
		and not (TradeFrame and TradeFrame:IsShown())
	) then
		UnBotLockboxService.RecoverTrade("при открытии обмена клиент сообщил: "..tostring(message), false);
	elseif (event == "PLAYER_REGEN_DISABLED") then
		if (UnBotLockboxService.stage ~= "wait_offline") then
			UnBotLockboxServiceFinish(
				UnBotLockboxService.operation == "world"
					and "Наземный сундук: начался бой. Ожидание автоматического взлома остановлено; повторите сервис вне боя."
					or "Lockbox из сумки: начался бой. Автоматическое открытие обмена остановлено; повторите сервис вне боя."
			);
		end
	end
end);
UnBotLockboxServiceFrame:SetScript("OnUpdate", function(self)
	if (
		not UnBotLockboxService.active
		or GetTime() < (UnBotLockboxService.nextTime or 0)
	) then
		return;
	end
	local now = GetTime();
	local name = UnBotLockboxService.rogueName;
	local unit = name and UnBotSquadRosterFindUnit(name) or nil;
	if (UnBotLockboxService.stage == "wait_offline") then
		if (name and UnBotSpecSummonIsInGroup(name) and unit and not UnitIsConnected(unit)) then
			UnBotLockboxServiceStop(
				"Вскрытие сундука: временный разбойник "..name
				.." подтверждён офлайн и сохранён в ростере группы.",
				false
			);
		elseif (not name or not UnBotSpecSummonIsInGroup(name)) then
			UnBotLockboxServiceStop(
				"Вскрытие сундука: временный разбойник больше не виден в ростере. UnBot не отправлял команду исключения из группы.",
				false
			);
		elseif (now >= (UnBotLockboxService.deadline or 0)) then
			UnBotLockboxServiceStop(
				"Вскрытие сундука: сервер не подтвердил офлайн-состояние за 8 секунд. Разбойник оставлен в группе; команда исключения не отправлялась.",
				false
			);
		elseif (
			unit
			and UnitIsConnected(unit)
			and now >= (UnBotLockboxService.nextOfflineAt or 0)
			and (UnBotLockboxService.offlineAttempts or 0) < 2
		) then
			UnBotLockboxService.offlineAttempts = (UnBotLockboxService.offlineAttempts or 0) + 1;
			UnBotLockboxService.nextOfflineAt = math.huge;
			UnBotBuffCycleSendSay(".playerbot bot remove "..name);
			UnBotLockboxService.nextTime = now + 0.25;
		else
			UnBotLockboxService.nextTime = now + 0.25;
		end
		return;
	end
	if (not name or not unit or not UnitIsConnected(unit)) then
		UnBotLockboxServiceStop("Вскрытие сундука: разбойник покинул группу или отключился.");
		return;
	end
	if ((InCombatLockdown and InCombatLockdown()) or UnitAffectingCombat("player")) then
		UnBotLockboxServiceFinish(
			UnBotLockboxService.operation == "world"
				and "Наземный сундук: начался бой. Ожидание автоматического взлома остановлено; повторите сервис вне боя."
				or "Lockbox из сумки: начался бой. Автоматическое открытие обмена остановлено; повторите сервис вне боя."
		);
		return;
	end

	if (UnBotLockboxService.operation == "trade") then
		if (UnBotLockboxService.IsOwnTradeVisible()) then
			if (UnBotLockboxService.stage ~= "trade_open") then
				UnBotLockboxServiceTradeReady();
			else
				UnBotLockboxService.tradeMissingSince = nil;
				UnBotLockboxService.nextTime = now + 0.2;
				if (now >= (UnBotLockboxService.deadline or 0)) then
					UnBotLockboxServiceStop("Lockbox из сумки: три минуты ожидания завершены. Открытый обмен и разбойник оставлены без изменений; завершите обмен вручную.");
				end
			end
			return;
		elseif (UnBotLockboxService.stage == "trade_open") then
			-- A delayed close event must not finish the service while its trade is visible.
			UnBotLockboxService.tradeMissingSince = UnBotLockboxService.tradeMissingSince or now;
			if (now - UnBotLockboxService.tradeMissingSince >= 0.5) then
				UnBotLockboxServiceFinish("Lockbox из сумки: подтверждённое окно обмена закрыто.");
			else
				UnBotLockboxService.nextTime = now + 0.2;
			end
			return;
		elseif (TradeFrame and TradeFrame:IsShown()) then
			if (UnBotLockboxService.stage ~= "manual_trade") then
				UnBotLockboxService.tradeRequestPending = false;
				UnBotLockboxServiceManualFallback("открыт обмен с другим или ещё не определённым участником; автоматические попытки остановлены");
			end
			if (now >= (UnBotLockboxService.deadline or 0)) then
				UnBotLockboxServiceFinish("Lockbox из сумки: обмен с выбранным разбойником не подтверждён за две минуты.");
			else
				UnBotLockboxService.nextTime = now + 0.25;
			end
			return;
		end
	end

	if (UnBotLockboxService.stage == "wait_poison") then
		UnBotLockboxService.stage = UnBotLockboxService.operation == "world"
			and "query_lockpick"
			or "summon";
		UnBotLockboxService.nextTime = now;
		UnBotLockboxService.deadline = now + (UnBotLockboxService.operation == "world" and 7 or 15);
		UnBotSpecSummonMessage(
			(UnBotLockboxService.operation == "world"
				and "Наземный сундук: пауза на нанесение ядов завершена; проверяю Взлом замка у "
				or "Lockbox из сумки: пауза на нанесение ядов завершена; подзываю ")
			..name
			..(UnBotLockboxService.operation == "world"
				and " по стабильному spell ID 1804."
				or " и только теперь открываю обмен.")
		);
	elseif (UnBotLockboxService.stage == "query_lockpick") then
		UnBotLockboxService.lockpickReplySeen = false;
		UnBotLockboxService.lockpickFound = false;
		UnBotLockboxService.lockpickQuietDeadline = 0;
		UnBotLockboxService.lockpickHardDeadline = now + 6;
		SendChatMessage("spells", "WHISPER", nil, name);
		UnBotLockboxService.stage = "wait_lockpick_spells";
		UnBotLockboxService.nextTime = now + 0.2;
	elseif (UnBotLockboxService.stage == "wait_lockpick_spells") then
		if (UnBotLockboxService.lockpickFound) then
			UnBotLockboxServiceStoreLockpickCapability(name, true);
			UnBotLockboxService.stage = "summon";
			UnBotLockboxService.nextTime = now;
			UnBotLockboxService.deadline = now + 15;
			UnBotSpecSummonMessage(
				"Наземный сундук: у "..name
				.." подтверждён Взлом замка (spell 1804). Подзываю его к игроку; "
				.."команды LOS u и cast не отправляются."
			);
		elseif (
			UnBotLockboxService.lockpickReplySeen
			and now >= (UnBotLockboxService.lockpickQuietDeadline or 0)
		) then
			UnBotLockboxServiceStoreLockpickCapability(name, false);
			UnBotLockboxServiceFinish(
				"Наземный сундук: в списке заклинаний "..name
				.." не найден Взлом замка (spell 1804). Рога помечен неподходящим и больше не будет "
				.."выбираться этим сервисом; LOS u и cast не отправлялись. Повторите сервис для проверки следующего роги."
			);
		elseif (now >= (UnBotLockboxService.lockpickHardDeadline or 0)) then
			UnBotLockboxServiceFinish(
				"Наземный сундук: "..name
				.." не ответил на запрос spells за 6 секунд. Профиль оставлен непроверенным; "
				.."LOS u и cast не отправлялись. Повторите сервис позже."
			);
		else
			UnBotLockboxService.nextTime = now + 0.2;
		end
	elseif (UnBotLockboxService.stage == "summon") then
		SendChatMessage("summon", "WHISPER", nil, name);
		SendChatMessage("stay", "WHISPER", nil, name);
		UnBotLockboxService.summonAttempts = 1;
		UnBotLockboxService.nextSummonAt = now + 4;
		UnBotLockboxService.stage = "wait_range";
		UnBotLockboxService.nextTime = now + 0.5;
	elseif (UnBotLockboxService.stage == "wait_range") then
		local near = CheckInteractDistance and CheckInteractDistance(unit, 2);
		if (near) then
			UnBotLockboxService.stage = UnBotLockboxService.operation == "world"
				and "wait_auto_lockpick"
				or "open_trade";
			UnBotLockboxService.nextTime = UnBotLockboxService.operation == "world" and now + 0.25 or 0;
			UnBotLockboxService.tradeReadyDeadline = now + 6;
			if (UnBotLockboxService.operation == "world") then
				UnBotLockboxService.deadline = now + 12;
				UnBotSpecSummonMessage(
					"Наземный сундук: "..name
					.." с подтверждённым Взломом замка находится рядом. Жду до 12 секунд его "
					.."автоматической реакции на ближайший запертый сундук; явная команда объекту не отправляется."
				);
			end
		elseif (now >= (UnBotLockboxService.deadline or 0)) then
			if (UnBotLockboxService.operation == "world") then
				UnBotLockboxServiceFinish(
					"Наземный сундук: разбойник не подошёл к игроку за 15 секунд; команды объекту не отправлялись."
				);
			else
				UnBotLockboxServiceManualFallback("разбойник не подошёл на дистанцию обмена за 15 секунд");
			end
		elseif (
			now >= (UnBotLockboxService.nextSummonAt or 0)
			and (UnBotLockboxService.summonAttempts or 0) < 3
		) then
			SendChatMessage("summon", "WHISPER", nil, name);
			SendChatMessage("stay", "WHISPER", nil, name);
			UnBotLockboxService.summonAttempts = (UnBotLockboxService.summonAttempts or 0) + 1;
			UnBotLockboxService.nextSummonAt = now + 4;
			UnBotLockboxService.nextTime = now + 0.5;
		else
			UnBotLockboxService.nextTime = now + 0.25;
		end
	elseif (UnBotLockboxService.stage == "wait_auto_lockpick") then
		if (now >= (UnBotLockboxService.deadline or 0)) then
			UnBotLockboxServiceFinish(
				"Наземный сундук: 12 секунд ожидания автоматического Взлома замка завершены. "
				.."Если сундук остался закрыт, возможна недостаточная прокачка навыка взлома или серверный запрет; "
				.."LOS u и cast не отправлялись."
			);
		else
			UnBotLockboxService.nextTime = now + 0.25;
		end
	elseif (UnBotLockboxService.stage == "retry_trade") then
		UnBotLockboxService.stage = "open_trade";
		UnBotLockboxService.tradeReadyDeadline = now + 6;
		UnBotLockboxService.nextTime = now;
	elseif (UnBotLockboxService.stage == "open_trade") then
		if (UnitIsDeadOrGhost and (UnitIsDeadOrGhost("player") or UnitIsDeadOrGhost(unit))) then
			UnBotLockboxServiceManualFallback("игрок или разбойник мёртв; автоматический обмен остановлен");
			return;
		end
		if (
			not CheckInteractDistance or not CheckInteractDistance(unit, 2)
			or (UnitCastingInfo and (UnitCastingInfo(unit) or UnitCastingInfo("player")))
			or (UnitChannelInfo and (UnitChannelInfo(unit) or UnitChannelInfo("player")))
		) then
			if (now >= (UnBotLockboxService.tradeReadyDeadline or 0)) then
				UnBotLockboxServiceManualFallback("разбойник не готов к обмену: проверьте расстояние и завершение заклинаний");
			else
				UnBotLockboxService.nextTime = now + 0.25;
			end
			return;
		end
		if (not InitiateTrade) then
			UnBotLockboxServiceManualFallback("клиент не поддерживает автоматический вызов обмена");
			return;
		end
		UnBotLockboxService.tradeAttempts = (UnBotLockboxService.tradeAttempts or 0) + 1;
		UnBotLockboxService.stage = "wait_trade";
		UnBotLockboxService.tradeRequestPending = true;
		UnBotLockboxService.deadline = now + 6;
		UnBotLockboxService.nextTime = now + 0.2;
		UnBotSpecSummonMessage("Lockbox из сумки: запрашиваю обмен с "..name
			.." (попытка "..tostring(UnBotLockboxService.tradeAttempts).."/3). Жду появления окна.");
		local ok = pcall(InitiateTrade, unit);
		if (not ok) then
			UnBotLockboxService.RecoverTrade("клиент заблокировал автоматический вызов обмена", false);
			return;
		end
	elseif (UnBotLockboxService.stage == "wait_trade") then
		if (now >= (UnBotLockboxService.deadline or 0)) then
			UnBotLockboxService.RecoverTrade("окно обмена не появилось за 6 секунд", true);
		else
			UnBotLockboxService.nextTime = now + 0.2;
		end
	elseif (UnBotLockboxService.stage == "manual_trade") then
		if (now >= (UnBotLockboxService.deadline or 0)) then
			UnBotLockboxServiceFinish(
				"Вскрытие сундука: ручной обмен не был открыт за две минуты."
			);
		else
			UnBotLockboxService.nextTime = now + 0.25;
		end
	end
end);

