-- Raid wipe recovery and a deliberately tiny offline reserve.  A character
-- cannot belong to two independent groups at once, therefore the reserve is
-- kept in the current raid roster but logged out after a summon/who location
-- check proves that the bot can reach the player.
-- AutoBalance only sees bots that actually enter the instance.  We limit the
-- reserve to at most three Restoration Druids and count every roster slot so
-- this feature cannot recreate the old "39 logged bots" problem. Warlocks are
-- never kept in the offline reserve:
-- this server removes Soulstone as soon as its caster logs out.
UnBotRaidReserve = UnBotRaidReserve or {
	active = false,
	action = nil,
	stage = "idle",
	nextTime = 0,
	stageUntil = 0,
	queue = {},
	queueIndex = 1,
	deadNames = {},
	startedAt = 0,
	releaseAt = 0,
	summonAt = 0,
	grindAt = 0,
	lastCountdown = nil,
	supportName = nil,
	supportNames = {},
	supportClass = nil,
	candidates = {},
	candidateIndex = 1,
	preparedNames = {},
	prepareTargetCount = 3,
	prepareWhoAttempts = 0,
	prepareReferenceZone = nil,
	rescueTargetNames = {},
	rescueTargetIndex = 0,
	soulstoneUntil = 0,
	supportInviteAt = 0,
	supportInviteAttempts = 0,
	autoPrepareAt = 0,
};

function UnBotMythicPlusBuffSuppressPendingReserve()
	UnBotBuffCycle.restoreReserveAt = nil;
	UnBotRaidReserve.autoPrepareAt = 0;
end

function UnBotRaidReserveResurrectionSpell(name)
	local profile = name and UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
	if (not profile or UnBotIsAccountAltProfile(name, profile)) then return nil; end
	local className = UnBotSpecSummonNormalize(profile.className);
	if (className == "druid") then return "Revive";
	elseif (className == "paladin") then return "Redemption";
	elseif (className == "priest") then return "Resurrection";
	elseif (className == "shaman") then return "Ancestral Spirit";
	end
end

function UnBotRaidReserveCastResurrection(name, tryRebirth)
	local spell = UnBotRaidReserveResurrectionSpell(name);
	if (
		not spell or not UnBotRaidReserveOnline(name)
		or (UnBotRaidReserve.resurrectionFailedNames and UnBotRaidReserve.resurrectionFailedNames[name])
	) then return false; end
	if (spell == "Revive" and tryRebirth and (UnitLevel("player") or 0) >= 20) then
		spell = "Rebirth";
	end
	UnBotBuffCycleSendWhisper(name, "cast "..spell.." on "..(UnitName("player") or ""));
	return true;
end

function UnBotRaidReserveEnsureStorage()
	UnBotRegistryAttachStorage();
	UnBotSquadConfig = UnBotSquadConfig or {};
	UnBotSquadConfig.raidReserve = UnBotSquadConfig.raidReserve or {};
	return UnBotSquadConfig.raidReserve;
end

function UnBotRaidReserveSavedNames(className)
	local storage = UnBotRaidReserveEnsureStorage();
	if (className ~= "druid") then
		local name = storage.warlockName;
		return name and {name} or {};
	end
	local result = {};
	local seen = {};
	local function keep(name)
		local profile = name and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (
			name
			and not seen[name]
			and #result < 3
			and profile
			and UnBotRaidReserveResurrectionSpell(name)
			and not UnBotRegistryGetActiveFlag(profile)
		) then
			seen[name] = true;
			table.insert(result, name);
		end
	end
	for _, name in ipairs(storage.resurrectionNames or {}) do
		keep(name);
	end
	for _, name in ipairs(storage.druidNames or {}) do
		keep(name);
	end
	keep(storage.druidName);
	-- Read without rewriting legacy names or discarding unavailable records.
	return result;
end

function UnBotRaidReserveSavedName(className)
	if (className == "druid") then
		return UnBotRaidReserveSavedNames(className)[1];
	end
	local storage = UnBotRaidReserveEnsureStorage();
	local field = "warlockName";
	local savedName = storage[field];
	local aliases = {"demonology"};
	local profile = savedName and UnBotBotRegistry.bots and UnBotBotRegistry.bots[savedName];
	if (
		profile
		and UnBotRegistryProfileMatches(profile, className, aliases)
		and not UnBotRegistryGetActiveFlag(profile)
	) then
		return savedName;
	end
	local candidates = UnBotRegistryCandidates(className, aliases);
	storage[field] = candidates[1];
	return candidates[1];
end

function UnBotRaidReserveUnit(name)
	return name and UnBotBuffCycleResolveUnit(name) or nil;
end

function UnBotRaidReserveOnline(name)
	local unit = UnBotRaidReserveUnit(name);
	return unit and UnitIsConnected(unit) and true or false;
end

function UnBotRaidReserveRemoveOfflineWarlocks()
	local storage = UnBotRaidReserveEnsureStorage();
	local oldReservedName = storage.warlockName;
	local removeNames = {};
	local seen = {};
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (
			name
			and not UnitIsConnected(unit)
			and (
				name == oldReservedName
				or (profile and UnBotRegistryProfileMatches(profile, "warlock", {"demonology", "affliction", "destruction"}))
			)
			and not seen[name]
		) then
			seen[name] = true;
			table.insert(removeNames, name);
		end
	end);
	for _, name in ipairs(removeNames) do
		UnBotSpecSummonUninvite(name);
		UnBotBuffCycleSendSay(".playerbot bot remove "..name, true);
	end
	storage.warlockName = nil;
	storage.soulstoneOfflineWorks = false;
	return #removeNames;
end

function UnBotRaidReserveTrimExcessDruids(keepNames)
	local keep = {};
	local removed = 0;
	for _, name in ipairs(keepNames or {}) do
		keep[name] = true;
	end
	for _, name in ipairs(UnBotSquadRosterReserveNames()) do
		local profile = UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (
			profile
			and not keep[name]
			and UnBotRegistryProfileMatches(profile, "druid", {"restoration"})
		) then
			UnBotSpecSummonUninvite(name);
			UnBotBuffCycleSendSay(".playerbot bot remove "..name, true);
			removed = removed + 1;
		end
	end
	return removed;
end

function UnBotRaidReservePrepareAccept(name)
	local state = UnBotRaidReserve;
	local storage = UnBotRaidReserveEnsureStorage();
	local seen = false;
	for _, preparedName in ipairs(state.preparedNames or {}) do
		if (preparedName == name) then
			seen = true;
			break
		end
	end
	if (not seen) then
		table.insert(state.preparedNames, name);
	end
	storage.druidNames = {};
	storage.resurrectionNames = {};
	for index = 1, math.min(3, #(state.preparedNames or {})) do
		local preparedName = state.preparedNames[index];
		table.insert(storage.resurrectionNames, preparedName);
		local profile = UnBotBotRegistry.bots[preparedName];
		if (UnBotRegistryProfileMatches(profile, "druid", {"restoration"})) then
			table.insert(storage.druidNames, preparedName);
		end
	end
	storage.druidName = storage.druidNames[1];
	storage.preparedAt = time();
	UnBotBuffCycle.cleanup[name] = nil;
	UnBotBuffCycle.lateRegistryNames[name] = nil;
	if (#state.preparedNames >= (state.prepareTargetCount or 3)) then
		local removed = UnBotRaidReserveTrimExcessDruids(state.preparedNames);
		UnBotRaidReserveStop(
			"Резерв подготовлен: боты для воскрешения офлайн в ростере — "
			..table.concat(state.preparedNames, ", ")
			..". Все исключены из AutoBalance"
			..(removed > 0 and ("; лишних резервных друидов удалено: "..tostring(removed)) or "")
			..".",
			true
		);
	else
		UnBotSpecSummonMessage(
			"Резерв: "..name.." подтверждён офлайн ("
			..tostring(#state.preparedNames).."/"..tostring(state.prepareTargetCount or 3)..")."
		);
		UnBotRaidReservePrepareTryNext();
	end
end

function UnBotRaidReservePrepareTryNext()
	local state = UnBotRaidReserve;
	state.queueIndex = (state.queueIndex or 0) + 1;
	local name = state.queue[state.queueIndex];
	while (name and UnBotRegistryGetActiveFlag(UnBotBotRegistry.bots[name])) do
		state.queueIndex = state.queueIndex + 1;
		name = state.queue[state.queueIndex];
	end
	if (not name) then
		if (#(state.preparedNames or {}) > 0) then
			UnBotRaidReserveStop(
				"Резерв подготовлен частично: боты для воскрешения офлайн в ростере — "
				..table.concat(state.preparedNames, ", ")
				..". Цель: "..tostring(state.prepareTargetCount or 3)..".",
				true
			);
		else
			UnBotRaidReserveEnsureStorage().preparedAt = nil;
			UnBotRaidReserveStop(
				"Резерв НЕ подготовлен: подходящие кандидаты не прошли проверку. Исходный состав сохранён.",
				true
			);
		end
		return false;
	end
	if (not UnBotSpecSummonIsInGroup(name)) then
		local raidCount = GetNumRaidMembers() or 0;
		local partyCount = GetNumPartyMembers() or 0;
		if (raidCount >= 40 or (raidCount == 0 and partyCount >= 4)) then
			UnBotRaidReserveStop("Резерв не подготовлен: в текущем ростере нет свободного места.", true);
			return false;
		end
	end
	state.supportName = name;
	state.prepareRetry = 0;
	state.prepareWhoAttempts = 0;
	-- A bot chosen as the reserve must never inherit an unfinished cleanup
	-- record from an earlier buff cycle, otherwise that old record can kick it
	-- out again while the reserve is being prepared.
	UnBotBuffCycle.cleanup[name] = nil;
	UnBotBuffCycle.lateRegistryNames[name] = nil;
	if (UnBotSpecSummonIsInGroup(name)) then
		if (UnBotRaidReserveOnline(name)) then
			UnBotRaidReserveStartLocationCheck(name);
		else
			state.stage = "prepare_login";
			state.nextTime = GetTime() + 1.25;
			state.stageUntil = GetTime() + 18;
			UnBotBuffCycleSendSay(".playerbot bot add "..name, true);
			UnBotSpecSummonMessage(
				"Резерв: временно включаю "..name.." для проверки summon и локации."
			);
		end
		return true;
	end
	state.stage = "prepare_login";
	state.nextTime = GetTime() + 1.25;
	state.stageUntil = GetTime() + 18;
	UnBotBuffCycleSendSay(".playerbot bot add "..name, true);
	UnBotSpecSummonMessage(
		"Резерв: возвращаю "..name.." ("..tostring(UnBotRaidReserveResurrectionSpell(name))..")"
		.." онлайн; затем отдельно приглашу его в состав рейда."
	);
	return true;
end

function UnBotRaidReserveStop(text, keepSupportOnline)
	local state = UnBotRaidReserve;
	if (not keepSupportOnline) then
		local removeNames = {};
		local seen = {};
		for _, name in ipairs(state.supportNames or {}) do
			if (name and not seen[name]) then
				seen[name] = true;
				table.insert(removeNames, name);
			end
		end
		if (state.supportName and not seen[state.supportName]) then
			table.insert(removeNames, state.supportName);
		end
		for _, name in ipairs(removeNames) do
			if (UnBotSpecSummonIsInGroup(name) and UnBotRaidReserveOnline(name)) then
				UnBotBuffCycleSendSay(".playerbot bot remove "..name, true);
			end
		end
	end
	state.active = false;
	state.action = nil;
	state.stage = "idle";
	state.nextTime = 0;
	state.stageUntil = 0;
	state.queue = {};
	state.queueIndex = 1;
	state.deadNames = {};
	state.supportName = nil;
	state.supportNames = {};
	state.supportClass = nil;
	state.candidates = {};
	state.candidateIndex = 1;
	state.preparedNames = {};
	state.prepareTargetCount = 3;
	state.prepareWhoAttempts = 0;
	state.prepareReferenceZone = nil;
	state.rescueTargetNames = {};
	state.rescueTargetIndex = 0;
	state.lastCountdown = nil;
	state.supportInviteAt = 0;
	state.supportInviteAttempts = 0;
	if (text) then
		UnBotSpecSummonMessage(text);
	end
	if (UnBotBuffCycle.dungeonReservePending) then
		local superFast = UnBotBuffCycle.dungeonReserveSuperFast == true;
		UnBotBuffCycle.dungeonReservePending = false;
		UnBotBuffCycle.dungeonReserveSuperFast = false;
		if (UnBotFastSoloDungeonReserveReady()) then
			if (UnBotBuffCycleOtherMemberCount(true) > 0) then
				UnBotSpecSummonMessage(
					"Fast Solo: офлайн-резерв подтверждён. Теперь безопасно переведите остальных активных участников офлайн и нажмите Fast Solo ещё раз."
				);
			else
				UnBotSpecSummonMessage(
					"Fast Solo: офлайн-резерв подтверждён в ростере. Запускаю баффы."
				);
				UnBotBuffCycleStart(superFast);
			end
		else
			UnBotSpecSummonMessage(
				"Fast Solo в подземелье не запущен: подтверждённого офлайн-резерва нет."
			);
		end
	end
end

function UnBotRaidReserveStartLocationCheck(name)
	local state = UnBotRaidReserve;
	state.prepareWhoAttempts = (state.prepareWhoAttempts or 0) + 1;
	UnBotBuffCycleSendWhisper(name, "summon");
	UnBotBuffCycleSendWhisper(name, "stay");
	state.stage = "prepare_summon_check";
	state.nextTime = GetTime() + 2;
	state.stageUntil = GetTime() + 8;
	UnBotSpecSummonMessage(
		"Резерв: проверяю, может ли "..tostring(name).." прибыть в "
		..tostring(state.prepareReferenceZone or "текущую зону")
		.." (попытка "..tostring(state.prepareWhoAttempts).."/2)."
	);
end

function UnBotRaidReserveRejectLocation(name, zoneName)
	local state = UnBotRaidReserve;
	local reason =
		"резерв: после summon who показывает "..tostring(zoneName or "неизвестную зону")
		.."; игрок: "..tostring(state.prepareReferenceZone or "неизвестная зона")
		.."; бот не находится рядом";
	local untilTime = UnBotRegistryNextMorningTimestamp();
	local quarantined = UnBotRegistrySetQuarantine(name, reason, untilTime);
	UnBotSpecSummonUninvite(name);
	UnBotBuffCycleSendSay(".playerbot bot remove "..tostring(name), true);
	if (quarantined) then
		UnBotSpecSummonMessage(
			"Ротация: "..tostring(name).." помещён в карантин до "
			..UnBotRegistryFlagTimeText(untilTime).." — "..reason..". Пробую следующего друида."
		);
	end
	state.stage = "prepare_skip";
	state.nextTime = GetTime() + 1;
end

function UnBotRaidReserveOtherAutomationActive(ignoreStrategySurvey, ignoreSpiritRescue, ignoreTwinTanks, ignoreTalentCatalog)
	return (
        (UnBotAltSetups and UnBotAltSetups.job) or
		(not ignoreTalentCatalog and UnBotFullTalentCatalog and UnBotFullTalentCatalog.IsBusy())
		or
		(not ignoreTalentCatalog and UnBotPVPSummon and UnBotPVPSummon.catalogOnly
			and (UnBotPVPSummon.active or next(UnBotPVPSummon.cleanup or {})))
		or
		(not ignoreTwinTanks and UnBotTwinEmperors and UnBotTwinEmperors.tanks
			and (UnBotTwinEmperors.tanks.armed or UnBotTwinEmperors.tanks.stage or UnBotTwinEmperors.tanks.restoring))
		or
		(not ignoreSpiritRescue and UnBotSpiritRescue and UnBotSpiritRescue.active)
		or
		(not ignoreStrategySurvey and UnBotStrategySurvey and UnBotStrategySurvey.active)
		or
		(UnBotBotScanner and UnBotBotScanner.active)
		or (UnBotJunkCleaner and UnBotJunkCleaner.active)
		or (UnBotFastJunkRaid and UnBotFastJunkRaid.active)
		or (UnBotBuffCycle and UnBotBuffCycle.active)
		or (UnBotSoulstoneTest and UnBotSoulstoneTest.active)
		or (UnBotSpecSummon and UnBotSpecSummon.active)
		or (UnBotSquadNearbyGate and UnBotSquadNearbyGate.active)
		or (UnBotDKSpecBalance and UnBotDKSpecBalance.active)
		or (
			UnBotMythicPlusBuffIsRunning
			and UnBotMythicPlusBuffIsRunning()
		)
		or (
			UnBotSquadSpecCheck
			and (
				UnBotSquadSpecCheck.active
				or (UnBotSquadSpecCheck.autoStartAt or 0) > 0
			)
		)
	);
end

function UnBotMythicPlusBuffOtherAutomationActive(ignoreStrategySurvey, ignoreTalentCatalog)
	return UnBotRaidReserveOtherAutomationActive(ignoreStrategySurvey, nil, nil, ignoreTalentCatalog)
		or (UnBotRaidReserve and UnBotRaidReserve.active)
		or (UnBotBotFix and UnBotBotFix.active);
end

function UnBotRaidReserveSchedulePrepare(delay)
	UnBotRaidReserve.autoPrepareAt = 0;
	return false; -- Deprecated automatic entrance; only the Resurrection menu can prepare reserve.
end

function UnBotRaidReserveCandidateList(className)
	local aliases = className == "druid" and {"restoration"} or {"demonology"};
	local candidates = UnBotRegistryCandidates(className, aliases);
	-- A druid/warlock already dead in the active raid cannot be our living
	-- support bot. Keep offline roster members: this server excludes them from
	-- AutoBalance even while the player is already inside the instance.
	for index = #candidates, 1, -1 do
		local unit = UnBotRaidReserveUnit(candidates[index]);
		if (unit and UnitIsConnected(unit) and UnitIsDeadOrGhost(unit)) then
			table.remove(candidates, index);
		end
	end
	local savedNames = UnBotRaidReserveSavedNames(className);
	for savedIndex = #savedNames, 1, -1 do
		local savedName = savedNames[savedIndex];
		local found = false;
		for index, name in ipairs(candidates) do
			if (name == savedName) then
				table.remove(candidates, index);
				table.insert(candidates, 1, name);
				found = true;
				break
			end
		end
		local unit = UnBotRaidReserveUnit(savedName);
		if (
			className == "druid" and not found
			and UnBotRaidReserveResurrectionSpell(savedName)
			and not (unit and UnitIsConnected(unit) and UnitIsDeadOrGhost(unit))
		) then table.insert(candidates, 1, savedName); end
	end
	return candidates;
end

function UnBotRaidReserveTryNextSupport(className)
	local state = UnBotRaidReserve;
	if (state.supportClass ~= className) then
		state.supportClass = className;
		state.candidates = UnBotRaidReserveCandidateList(className);
		state.candidateIndex = 1;
	end
	local name = state.candidates[state.candidateIndex];
	if (not name or state.candidateIndex > 4) then
		return false;
	end
	state.candidateIndex = state.candidateIndex + 1;
	state.supportName = name;
	state.stage = className == "druid" and "wait_druid" or "wait_warlock";
	state.nextTime = GetTime() + 0.25;
	state.stageUntil = GetTime() + 12;
	state.supportInviteAt = GetTime() + 1.25;
	state.supportInviteAttempts = 0;
	UnBotBuffCycleSendSay(".playerbot bot add "..name, true);
	UnBotSpecSummonMessage(
		"Резерв: включаю "..name.." ("
		..(className == "druid" and "Restoration Druid" or "Demonology Warlock")
		..")."
	);
	return true;
end

function UnBotRaidReservePrepare(allowFallback, automatic)
	if automatic then UnBotRaidReserve.autoPrepareAt=0; return false; end
	UnBotSquadBuilderEnsureConfig();
	UnBotRaidReserve.autoPrepareAt = 0;
	UnBotBuffCycle.restoreReserveAt = nil;
	if (UnBotRaidReserve.active) then
		if automatic then return; end
		UnBotRaidReserveStop("Подготовка резерва остановлена.");
		return;
	end
	if (UnitAffectingCombat("player")) then
		UnBotSpecSummonMessage("Резерв можно готовить только вне боя.");
		return;
	end
	if (UnBotRaidReserveOtherAutomationActive()) then
		UnBotSpecSummonMessage("Сначала завершите другой автоматический цикл UnBot.");
		return;
	end
	local targetCount = UnBotSquadReserveCount(
		UnBotSquadConfig and UnBotSquadConfig.resurrectionReserveCount,
		UnBotSquadConfig and UnBotSquadConfig.includeResurrectionReserve
	);
	if (targetCount == 0) then
		targetCount = 1;
		UnBotSpecSummonMessage(
			"Резерв не был указан: для ручной подготовки выбран 1 Restoration Druid."
		);
		UnBotSquadBuilderRefresh();
	end
	local candidates = UnBotRaidReserveCandidateList("druid");
	-- A reserve must be additional to the combat squad. Keep an already saved
	-- offline reserve, but never reinterpret another disconnected roster member
	-- as reserve: it may be a failed combat-slot summon awaiting quarantine.
	for index = #candidates, 1, -1 do
		local candidateName = candidates[index];
		if (
			UnBotSpecSummonIsInGroup(candidateName)
			and (
				UnBotRaidReserveOnline(candidateName)
				or not UnBotSquadRosterIsOfflineReserve(candidateName)
			)
		) then
			table.remove(candidates, index);
		end
	end
	local queue = {};
	local seen = {};
	for index = 1, math.min(6, #candidates) do
		queue[#queue + 1] = candidates[index];
		seen[candidates[index]] = true;
	end
	if (allowFallback and (UnitLevel("player") or 0) >= 12) then
		for _, className in ipairs({"paladin", "priest", "shaman", "druid"}) do
			local added = 0;
			for _, name in ipairs(UnBotRegistryCandidates(className, {}, nil, true)) do
				local unit = UnBotRaidReserveUnit(name);
				if (
					not seen[name] and UnBotRaidReserveResurrectionSpell(name)
					and not (unit and UnitIsConnected(unit) and UnitIsDeadOrGhost(unit))
					and (not UnBotSpecSummonIsInGroup(name) or UnBotSquadRosterIsOfflineReserve(name))
				) then
					queue[#queue + 1] = name;
					seen[name] = true;
					added = added + 1;
					if (added >= 6) then break end
				end
			end
		end
	end
	if (#queue == 0) then
		UnBotSpecSummonMessage(
			"В реестре нет свободного подходящего бота для резерва. Боевой состав не изменён."
		);
		return;
	end
	local removedWarlocks = UnBotRaidReserveRemoveOfflineWarlocks();
	UnBotRaidReserve.active = true;
	UnBotRaidReserve.action = "prepare";
	UnBotRaidReserve.queue = queue;
	UnBotRaidReserve.queueIndex = 0;
	UnBotRaidReserve.supportName = nil;
	UnBotRaidReserve.preparedNames = {};
	UnBotRaidReserve.prepareTargetCount = targetCount;
	UnBotRaidReserve.prepareWhoAttempts = 0;
	UnBotRaidReserve.prepareReferenceZone = GetRealZoneText and GetRealZoneText() or nil;
	UnBotRaidReserve.stage = "prepare_start";
	UnBotRaidReserve.nextTime = GetTime();
	UnBotSpecSummonMessage(
		"Подготовка резерва: требуется ботов для воскрешения "..tostring(targetCount)
		.."; каждый должен войти в ростер и остаться офлайн. "
		.."Удалено офлайн-варлоков: "..tostring(removedWarlocks).."."
	);
	UnBotRaidReservePrepareTryNext();
end

function UnBotRaidReserveCollectDead()
	local result = {};
	UnBotRaidReserveEnsureStorage();
	UnBotBuffCycleForEachGroupMember(function(name, unit)
		if (
			UnBotBotRegistry.bots
			and UnBotBotRegistry.bots[name]
			and UnitIsConnected(unit)
			and UnitIsDeadOrGhost(unit)
		) then
			table.insert(result, name);
		end
	end);
	table.sort(result);
	return result;
end

function UnBotRaidReserveLockRescuer(name, summonNow)
	if (not name) then
		return;
	end
	for _, command in ipairs({
		"co -attack force",
		"co -dps",
		"co -dps assist",
		"co -tank",
		"co -flee",
		"co -formation",
		"co -avoid aoe",
		"co -icc",
		"nc -icc",
		"co +heal",
		"stay",
	}) do
		UnBotBuffCycleSendWhisper(name, command);
	end
	if (summonNow) then
		UnBotBuffCycleSendWhisper(name, "summon");
		UnBotBuffCycleSendWhisper(name, "stay");
	end
end

function UnBotRaidReserveTryNextRescueDruid()
	local state = UnBotRaidReserve;
	while ((state.rescueTargetIndex or 0) < #(state.rescueTargetNames or {})) do
		state.rescueTargetIndex = (state.rescueTargetIndex or 0) + 1;
		local name = state.rescueTargetNames[state.rescueTargetIndex];
		local unit = UnBotRaidReserveUnit(name);
		if (not unit or not UnitIsConnected(unit) or not UnitIsDeadOrGhost(unit)) then
			state.supportName = name;
			state.stage = "wait_druid";
			state.nextTime = GetTime() + 0.25;
			state.stageUntil = GetTime() + 12;
			state.supportInviteAt = GetTime() + 1.25;
			state.supportInviteAttempts = 0;
			UnBotBuffCycleSendSay(".playerbot bot add "..name, true);
			UnBotSpecSummonMessage(
				"Воскрешение рейда: включаю резервного бота "..name
				.." ("..tostring(state.rescueTargetIndex).."/"
				..tostring(#state.rescueTargetNames)..")."
			);
			return true;
		end
		UnBotSpecSummonMessage("Резервный бот "..name.." уже мёртв; пробую следующего.");
	end
	return false;
end

function UnBotRaidRescueStart()
	UnBotSquadBuilderEnsureConfig();
	if (UnBotRaidReserve.active) then
		UnBotRaidReserveStop("Воскрешение рейда остановлено.");
		return;
	end
	if (UnitAffectingCombat("player")) then
		UnBotSpecSummonMessage("Воскрешение рейда запускается только после завершения боя.");
		return;
	end
	if (UnBotRaidReserveOtherAutomationActive()) then
		UnBotSpecSummonMessage("Сначала завершите другой автоматический цикл UnBot.");
		return;
	end
	local deadNames = UnBotRaidReserveCollectDead();
	if (#deadNames == 0 and not UnitIsDeadOrGhost("player")) then
		UnBotSpecSummonMessage("Воскрешение не требуется: мёртвых ботов в текущей группе не найдено.");
		return;
	end
	local druidNames = UnBotRaidReserveSavedNames("druid");
	local desiredCount = UnBotSquadReserveCount(
		UnBotSquadConfig and UnBotSquadConfig.resurrectionReserveCount,
		UnBotSquadConfig and UnBotSquadConfig.includeResurrectionReserve
	);
	if (desiredCount == 0) then
		desiredCount = 3;
	end
	if (#druidNames < desiredCount) then
		local seen = {};
		for _, name in ipairs(druidNames) do
			seen[name] = true;
		end
		for _, name in ipairs(UnBotRaidReserveCandidateList("druid")) do
			if (#druidNames >= desiredCount) then
				break
			end
			if (not seen[name]) then
				seen[name] = true;
				table.insert(druidNames, name);
			end
		end
	end
	if (#druidNames == 0) then
		UnBotSpecSummonMessage("В реестре нет доступного Restoration Druid.");
		return;
	end
	local state = UnBotRaidReserve;
	state.active = true;
	state.action = "rescue";
	state.resurrectionFailedNames = {};
	state.deadNames = deadNames;
	state.startedAt = GetTime();
	state.releaseAt = state.startedAt + 57;
	state.summonAt = state.startedAt + 61;
	state.grindAt = state.startedAt + 66;
	state.lastCountdown = nil;
	state.supportClass = nil;
	state.supportName = nil;
	state.supportNames = {};
	state.candidates = {};
	state.candidateIndex = 1;
	state.rescueTargetNames = {};
	for index = 1, math.min(desiredCount, #druidNames) do
		table.insert(state.rescueTargetNames, druidNames[index]);
	end
	if (#state.rescueTargetNames == 0) then
		for index = 1, math.min(3, #druidNames) do
			table.insert(state.rescueTargetNames, druidNames[index]);
		end
	end
	state.rescueTargetIndex = 0;
	UnBotSpecSummonMessage(
		"Воскрешение рейда запущено: мёртвых ботов "..tostring(#deadNames)
		..", резервных ботов "..tostring(#state.rescueTargetNames)
		..". Release через 57 сек., summon через 61 сек."
	);
	if (not UnBotRaidReserveTryNextRescueDruid()) then
		state.stage = "wait_release";
		state.nextTime = GetTime() + 1;
		UnBotSpecSummonMessage("Живой друид не найден; продолжаю цикл release/summon без него.");
	end
end

function UnBotRaidReserveSoulstoneTest()
	UnBotSpecSummonMessage(
		"Офлайн-Soulstone отключён: проверка показала, что аура исчезает, когда варлок уходит офлайн."
	);
end

function UnBotRaidReserveStatus()
	local storage = UnBotRaidReserveEnsureStorage();
	local druidNames = UnBotRaidReserveSavedNames("druid");
	local statusParts = {};
	local function status(name)
		if (not UnBotSpecSummonIsInGroup(name)) then
			return "вне ростера";
		elseif (UnBotRaidReserveOnline(name)) then
			return "онлайн";
		end
		return "офлайн в ростере";
	end
	for _, name in ipairs(druidNames) do
		table.insert(statusParts, name.." ["..status(name).."]");
	end
	UnBotSpecSummonMessage(
		"Резерв для воскрешения: "
		..(#statusParts > 0 and table.concat(statusParts, ", ") or "не выбраны")..". "
		.."Офлайн-Soulstone отключён: аура исчезает вместе с варлоком"
		..(UnBotRaidReserve.active and (". Сейчас: "..tostring(UnBotRaidReserve.stage)) or ".")
	);
end

function UnBotRaidReserveCleanup()
	local storage = UnBotRaidReserveEnsureStorage();
	UnBotRaidReserveStop(nil, true);
	local names = UnBotRaidReserveSavedNames("druid");
	if (storage.warlockName) then
		table.insert(names, storage.warlockName);
	end
	local seen = {};
	for _, name in ipairs(names) do
		if (name and not seen[name]) then
			seen[name] = true;
			if (UnBotSpecSummonIsInGroup(name)) then
				UnBotSpecSummonUninvite(name);
			end
			UnBotBuffCycleSendSay(".playerbot bot remove "..name, true);
		end
	end
	UnBotSpecSummonMessage(
		"Резерв очищен: служебным ботам отправлены leave/uninvite/remove. Сохранённые имена оставлены для следующей подготовки."
	);
end

function UnBotRaidReserveCountdown(now)
	local state = UnBotRaidReserve;
	local remaining = math.max(0, math.ceil((state.releaseAt or now) - now));
	local checkpoint = nil;
	if (remaining <= 5) then
		checkpoint = remaining;
	elseif (remaining <= 15) then
		checkpoint = 15;
	elseif (remaining <= 30) then
		checkpoint = 30;
	elseif (remaining <= 45) then
		checkpoint = 45;
	end
	if (checkpoint and checkpoint ~= state.lastCountdown) then
		state.lastCountdown = checkpoint;
		UnBotSpecSummonMessage("Воскрешение рейда: release через "..tostring(remaining).." сек.");
	end
end

UnBotRaidReserveFrame = UnBotRaidReserveFrame or CreateFrame("Frame", "UnBotRaidReserveFrame");
UnBotRaidReserveWhoFrame = UnBotRaidReserveWhoFrame or CreateFrame("Frame", "UnBotRaidReserveWhoFrame");
UnBotRaidReserveWhoFrame:RegisterEvent("CHAT_MSG_WHISPER");
UnBotRaidReserveWhoFrame:RegisterEvent("CHAT_MSG_SYSTEM");
UnBotRaidReserveWhoFrame:SetScript("OnEvent", function(self, event, message, sender)
	local state = UnBotRaidReserve;
	local name = state.queue and state.queue[state.queueIndex];
	if (state.active and state.action == "rescue" and state.supportName) then
		local text = UnBotSpecSummonNormalize(message);
		local failed = string.find(text, "cannot cast", 1, true)
			or string.find(text, "unknown spell", 1, true)
			or string.find(text, "no items", 1, true);
		if (failed and (sender == state.supportName or string.find(text, UnBotSpecSummonNormalize(state.supportName), 1, true))) then
			state.resurrectionFailedNames = state.resurrectionFailedNames or {};
			state.resurrectionFailedNames[state.supportName] = true;
			UnBotSpecSummonMessage("Резерв: "..state.supportName.." не может воскресить; повторные касты этому боту отменены.");
		end
	end
	if (state.active and event == "CHAT_MSG_SYSTEM") then
		local requestedName = state.action == "prepare" and name or state.supportName;
		local text = UnBotSpecSummonNormalize(message);
		local alreadyActive = string.find(text, "player already logged in", 1, true)
			or string.find(text, "already logged in", 1, true)
			or string.find(text, "already in group", 1, true)
			or string.find(text, "уже состоит в группе", 1, true)
			or string.find(text, "уже в игре", 1, true);
		if (
			requestedName
			and alreadyActive
			and not UnBotSpecSummonIsInGroup(requestedName)
			and (
				string.find(text, UnBotSpecSummonNormalize(requestedName), 1, true)
				or string.find(text, "player already logged in", 1, true)
			)
		) then
			UnBotRegistrySetHourlyQuarantine(
				requestedName,
				"резерв: сервер подтвердил, что бот уже залогинен у другого игрока",
				"Ротация"
			);
			UnBotSpecSummonMessage(
				"Резерв: "..requestedName
				.." уже занят другим игроком; повторные add/invite и принудительный remove отменены, карантин 1 час."
			);
			if (state.action == "prepare") then
				state.prepareRetry = 2;
				state.stage = "prepare_skip";
				state.nextTime = GetTime() + 0.1;
			elseif (state.action == "rescue") then
				if (not UnBotRaidReserveTryNextRescueDruid()) then
					state.stage = "wait_release";
					state.nextTime = GetTime() + 1;
				end
			end
			return;
		end
	end
	if (
		not state.active
		or state.action ~= "prepare"
		or state.stage ~= "prepare_who"
		or event ~= "CHAT_MSG_WHISPER"
		or not name
		or sender ~= name
	) then
		return;
	end
	local whoInfo = UnBotSpecSummonParseWho(message);
	if (not whoInfo or not whoInfo.className or not whoInfo.specName) then
		return;
	end
	UnBotSquadSpecCheckStoreProfile(sender, whoInfo, message);
	if (not UnBotRaidReserveResurrectionSpell(sender)) then
		UnBotSpecSummonUninvite(sender);
		UnBotBuffCycleSendSay(".playerbot bot remove "..sender, true);
		UnBotSpecSummonMessage("Резерв: "..sender.." не подтвердил класс с воскрешением; пробую следующего.");
		state.stage = "prepare_skip";
		state.nextTime = GetTime() + 1;
		return;
	end
	local unit = UnBotRaidReserveUnit(sender);
	local visible = unit and UnitIsVisible and UnitIsVisible(unit) and true or false;
	local near = unit and CheckInteractDistance and CheckInteractDistance(unit, 1) and true or false;
	local ready = UnBotSquadNearbyGateUnitReady
		and UnBotSquadNearbyGateUnitReady(unit)
		or (visible and near);
	local referenceZone = UnBotSpecSummonNormalize(state.prepareReferenceZone);
	local botZone = UnBotSpecSummonNormalize(whoInfo.zoneName);
	if (not ready) then
		if ((state.prepareWhoAttempts or 0) < 2) then
			UnBotSpecSummonMessage(
				"Резерв: "..sender.." после summon не находится рядом"
				..(botZone ~= "" and (" ["..tostring(whoInfo.zoneName).."]") or "")
				.."; повторяю контрольную попытку."
			);
			UnBotRaidReserveStartLocationCheck(sender);
			return;
		end
		UnBotRaidReserveRejectLocation(
			sender,
			botZone ~= "" and whoInfo.zoneName
				or (referenceZone ~= "" and "не виден в инстансе игрока" or nil)
		);
		return;
	end
	UnBotSpecSummonMessage(
		"Резерв: "..sender.." прошёл проверку summon/who"
		..(whoInfo.zoneName and (" ["..whoInfo.zoneName.."]") or "").."; перевожу офлайн."
	);
	UnBotBuffCycleSendWhisper(sender, "stay");
	state.stage = "prepare_offline";
	state.nextTime = GetTime() + 0.5;
	state.stageUntil = GetTime() + 10;
end);
UnBotRaidReserveFrame:SetScript("OnUpdate", function(self, elapsed)
	local state = UnBotRaidReserve;
	local now = GetTime();
	state.autoPrepareAt = 0; -- Never restart the obsolete reserve automatically.
	if (not state.active or now < (state.nextTime or 0)) then
		return;
	end
	if (UnitAffectingCombat("player")) then
		state.stageUntil = math.max(state.stageUntil or 0, now + 8);
		state.nextTime = now + 1;
		return;
	end

	if (state.action == "prepare") then
		local name = state.queue[state.queueIndex];
		if (state.stage == "prepare_login") then
			if (name and UnBotSpecSummonIsInGroup(name) and UnBotRaidReserveOnline(name)) then
				UnBotRaidReserveStartLocationCheck(name);
			else
				InviteUnit(tostring(name));
				state.stage = "prepare_wait";
				state.nextTime = now + 0.5;
				state.stageUntil = now + 8;
				UnBotSpecSummonMessage(
					"Резерв: "..tostring(name)
					.." получил отдельное приглашение в группу после включения онлайн."
				);
			end
		elseif (state.stage == "prepare_wait") then
			if (name and UnBotSpecSummonIsInGroup(name) and UnBotRaidReserveOnline(name)) then
				UnBotRaidReserveStartLocationCheck(name);
			elseif (now >= (state.stageUntil or 0)) then
				if ((state.prepareRetry or 0) == 0) then
					state.prepareRetry = 1;
					UnBotBuffCycleSendSay(".playerbot bot add "..tostring(name), true);
					InviteUnit(tostring(name));
					state.nextTime = now + 0.75;
					state.stageUntil = now + 8;
					UnBotSpecSummonMessage(
						"Резерв: "..tostring(name)
						.." ещё не в группе; повторяю online + приглашение."
					);
				elseif ((state.prepareRetry or 0) == 1) then
					state.prepareRetry = 2;
					UnBotBuffCycleSendSay(".playerbot bot remove "..tostring(name), true);
					state.stage = "prepare_readd";
					state.nextTime = now + 2;
					UnBotSpecSummonMessage(
						"Резерв: "..tostring(name)
						.." числится logged in, но не принял приглашение. Выполняю жёсткий перезапуск remove -> online -> invite."
					);
				else
					UnBotBuffCycleSendSay(".playerbot bot remove "..tostring(name), true);
					UnBotSpecSummonMessage(
						"Резерв: "..tostring(name).." не появился в ростере даже после перезапуска; этот кандидат не засчитан."
					);
					UnBotRaidReservePrepareTryNext();
				end
			else
				state.nextTime = now + 0.25;
			end
		elseif (state.stage == "prepare_readd") then
			UnBotBuffCycleSendSay(".playerbot bot add "..tostring(name), true);
			state.stage = "prepare_login";
			state.nextTime = now + 1.25;
			state.stageUntil = now + 12;
		elseif (state.stage == "prepare_summon_check") then
			if (not UnBotSpecSummonPlayerSupportsSpecs()) then
				local unit = UnBotRaidReserveUnit(name);
				local visible = unit and UnitIsVisible and UnitIsVisible(unit) and true or false;
				local near = unit and CheckInteractDistance and CheckInteractDistance(unit, 1) and true or false;
				local ready = UnBotSquadNearbyGateUnitReady
					and UnBotSquadNearbyGateUnitReady(unit)
					or (visible and near);
				if (ready) then
					UnBotSpecSummonMessage(
						"Резерв до 11 уровня: "..tostring(name)
						.." подтверждён рядом по классу druid без who специализации; перевожу офлайн."
					);
					UnBotBuffCycleSendWhisper(name, "stay");
					state.stage = "prepare_offline";
					state.nextTime = now + 0.5;
					state.stageUntil = now + 10;
				elseif ((state.prepareWhoAttempts or 0) < 2) then
					UnBotRaidReserveStartLocationCheck(name);
				else
					UnBotRaidReserveRejectLocation(name, "не виден рядом; who отключён до 11 уровня");
				end
			else
				SendChatMessage("who", "WHISPER", nil, tostring(name));
				state.stage = "prepare_who";
				state.nextTime = now + 0.25;
				state.stageUntil = now + 6;
			end
		elseif (state.stage == "prepare_who") then
			if (now >= (state.stageUntil or 0)) then
				if ((state.prepareWhoAttempts or 0) < 2) then
					UnBotRaidReserveStartLocationCheck(name);
				else
					UnBotSpecSummonUninvite(name);
					UnBotBuffCycleSendSay(".playerbot bot remove "..tostring(name), true);
					UnBotSpecSummonMessage(
						"Резерв: "..tostring(name)
						.." не ответил на who после 2 проверок summon; кандидат не засчитан."
					);
					state.stage = "prepare_skip";
					state.nextTime = now + 1;
				end
			else
				state.nextTime = now + 0.25;
			end
		elseif (state.stage == "prepare_skip") then
			UnBotRaidReservePrepareTryNext();
		elseif (state.stage == "prepare_offline") then
			if (name and UnBotSpecSummonIsInGroup(name) and UnBotRaidReserveOnline(name)) then
				UnBotBuffCycleSendSay(".playerbot bot remove "..name, true);
			end
			state.stage = "prepare_verify_offline";
			state.nextTime = now + 0.5;
		elseif (state.stage == "prepare_verify_offline") then
			if (name and UnBotSpecSummonIsInGroup(name) and not UnBotRaidReserveOnline(name)) then
				UnBotRaidReservePrepareAccept(name);
			elseif (now >= (state.stageUntil or 0)) then
				if (name and UnBotRaidReserveOnline(name)) then
					UnBotBuffCycleSendSay(".playerbot bot remove "..name, true);
				end
				UnBotSpecSummonMessage(
					"Резерв: "..tostring(name).." не остался офлайн в ростере; пробую следующего друида."
				);
				UnBotRaidReservePrepareTryNext();
			else
				state.nextTime = now + 0.5;
			end
		end
		return;
	end

	if (state.action == "rescue") then
		if (state.stage == "wait_druid") then
			if (
				state.supportName
				and not UnBotSpecSummonIsInGroup(state.supportName)
				and now >= (state.supportInviteAt or 0)
				and (state.supportInviteAttempts or 0) < 4
			) then
				state.supportInviteAttempts = (state.supportInviteAttempts or 0) + 1;
				if (state.supportInviteAttempts == 3) then
					UnBotBuffCycleSendSay(".playerbot bot add "..state.supportName, true);
				end
				InviteUnit(state.supportName);
				state.supportInviteAt = now + 2;
			end
			if (state.supportName and UnBotRaidReserveOnline(state.supportName)) then
				local knownSupport = false;
				for _, name in ipairs(state.supportNames or {}) do
					if (name == state.supportName) then
						knownSupport = true;
						break
					end
				end
				if (not knownSupport) then
					table.insert(state.supportNames, state.supportName);
				end
				UnBotRaidReserveLockRescuer(state.supportName, true);
				UnBotRegistryRecordGameplaySummon(state.supportName, "raid-rescue");
				state.stage = "druid_arrive";
				state.nextTime = now + 1.5;
			elseif (now >= (state.stageUntil or 0)) then
				UnBotSpecSummonMessage("Резервный бот "..tostring(state.supportName).." не вышел онлайн; пробую следующего.");
				if (state.supportName) then
					UnBotBuffCycleSendSay(".playerbot bot remove "..state.supportName, true);
				end
				if (not UnBotRaidReserveTryNextRescueDruid()) then
					state.stage = "wait_release";
					state.nextTime = now + 1;
				end
			else
				state.nextTime = now + 0.25;
			end
		elseif (state.stage == "druid_arrive") then
			if (UnitIsDeadOrGhost("player") and state.supportName) then
				UnBotRaidReserveLockRescuer(state.supportName, false);
				if (UnitIsGhost and UnitIsGhost("player")) then
					UnBotRaidReserveCastResurrection(state.supportName, false);
					UnBotSpecSummonMessage("Резерв прибыл: отправлено обычное воскрешение своего класса.");
				else
					UnBotRaidReserveCastResurrection(state.supportName, true);
					UnBotSpecSummonMessage("Резерв прибыл: отправлена команда воскрешения своего класса.");
				end
				state.stage = "druid_rebirth";
				state.nextTime = now + 11;
			else
				state.stage = "wait_release";
				state.nextTime = now + 1;
			end
		elseif (state.stage == "druid_rebirth") then
			if (UnitIsDeadOrGhost("player") and state.supportName) then
				UnBotRaidReserveLockRescuer(state.supportName, false);
				UnBotRaidReserveCastResurrection(state.supportName, false);
				if (UnBotRaidReserveTryNextRescueDruid()) then
					UnBotSpecSummonMessage("Воскрешение игрока пока не подтверждено; пробую следующего резервного бота.");
					return;
				end
			end
			state.stage = "wait_release";
			state.nextTime = now + 1;
		elseif (state.stage == "wait_release") then
			if (now >= state.releaseAt) then
				for _, name in ipairs(state.deadNames or {}) do
					if (UnBotSpecSummonIsInGroup(name)) then
						UnBotBuffCycleSendWhisper(name, "release");
					end
				end
				state.stage = "wait_summon";
				state.nextTime = now + 0.5;
				UnBotSpecSummonMessage("Воскрешение рейда: release отправлен; summon через 4 сек.");
			else
				UnBotRaidReserveCountdown(now);
				state.nextTime = now + 1;
			end
		elseif (state.stage == "wait_summon") then
			if (now >= state.summonAt) then
				for _, name in ipairs(state.deadNames or {}) do
					if (UnBotSpecSummonIsInGroup(name)) then
						UnBotBuffCycleSendWhisper(name, "summon");
					end
				end
				state.stage = "wait_grind";
				state.nextTime = now + 0.5;
				UnBotSpecSummonMessage("Воскрешение рейда: summon отправлен; возврат AI через 5 сек.");
			else
				state.nextTime = now + 0.5;
			end
		elseif (state.stage == "wait_grind") then
			if (now >= state.grindAt) then
				for _, name in ipairs(state.deadNames or {}) do
					if (UnBotSpecSummonIsInGroup(name)) then
						UnBotBuffCycleSendWhisper(name, "grind");
					end
				end
				if (UnitIsDeadOrGhost("player")) then
					for _, name in ipairs(state.supportNames or {}) do
						if (UnBotRaidReserveOnline(name)) then
							UnBotRaidReserveLockRescuer(name, false);
							UnBotRaidReserveCastResurrection(name, false);
						end
					end
					UnBotRaidReserveStop(
						"Цикл ботов завершён, но игрок всё ещё мёртв. Резервные боты оставлены онлайн для ручного воскрешения.",
						true
					);
				else
					UnBotRaidReserveStop("Воскрешение рейда завершено; резервные боты снова переведены офлайн.");
				end
			else
				state.nextTime = now + 0.5;
			end
		end
		return;
	end

	if (state.action == "soulstone") then
		if (state.stage == "wait_warlock") then
			if (state.supportName and UnBotRaidReserveOnline(state.supportName)) then
				UnBotBuffCycleSendWhisper(state.supportName, "summon");
				UnBotBuffCycleSendWhisper(state.supportName, "stay");
				UnBotBuffCycleSendWhisper(state.supportName, "nc +ss master");
				UnBotRegistryRecordGameplaySummon(state.supportName, "reserve-soulstone-test");
				state.stage = "soulstone_wait";
				state.soulstoneUntil = now + 35;
				state.nextTime = now + 2;
			elseif (now >= (state.stageUntil or 0)) then
				UnBotSpecSummonMessage("Резервный варлок "..tostring(state.supportName).." не вышел онлайн; пробую следующего.");
				if (state.supportName) then
					UnBotBuffCycleSendSay(".playerbot bot remove "..state.supportName, true);
				end
				if (not UnBotRaidReserveTryNextSupport("warlock")) then
					UnBotRaidReserveStop("Тест Soulstone остановлен: доступный варлок не найден.", true);
				end
			else
				state.nextTime = now + 0.25;
			end
		elseif (state.stage == "soulstone_wait") then
			if (UnBotBuffCyclePlayerHasBuff(UnBotSoulstoneTestAura)) then
				UnBotRegistryMarkSoulstoneCooldown(UnBotSoulstoneAuraCasterName(state.supportName));
				UnBotBuffCycleSendSay(".playerbot bot remove "..state.supportName, true);
				state.stage = "soulstone_offline_verify";
				state.nextTime = now + 4;
				UnBotSpecSummonMessage("Soulstone обнаружен. Варлок переведён офлайн; проверяю ауру через 4 сек.");
			elseif (now >= (state.soulstoneUntil or 0)) then
				UnBotRaidReserveStop(
					"Soulstone за 35 секунд не появился. Варлок оставлен онлайн: вероятнее всего, камень на перезарядке.",
					true
				);
			else
				state.nextTime = now + 2;
			end
		elseif (state.stage == "soulstone_offline_verify") then
			local storage = UnBotRaidReserveEnsureStorage();
			if (UnBotBuffCyclePlayerHasBuff(UnBotSoulstoneTestAura)) then
				storage.soulstoneOfflineWorks = true;
				storage.soulstoneOfflineTestedAt = time();
				UnBotRaidReserveStop(
					"УСПЕХ: Soulstone сохранился после перевода варлока офлайн. Варлок остался офлайн в ростере и не должен входить в AutoBalance.",
					true
				);
			else
				storage.soulstoneOfflineWorks = false;
				storage.soulstoneOfflineTestedAt = time();
				UnBotSpecSummonMessage(
					"Soulstone исчез после офлайна варлока — сервер связывает ауру с активным кастером. Возвращаю варлока онлайн."
				);
				state.stage = "soulstone_restore";
				state.nextTime = now + 0.25;
				state.stageUntil = now + 12;
				UnBotBuffCycleSendSay(".playerbot bot add "..state.supportName, true);
			end
		elseif (state.stage == "soulstone_restore") then
			if (state.supportName and UnBotRaidReserveOnline(state.supportName)) then
				UnBotBuffCycleSendWhisper(state.supportName, "summon");
				UnBotBuffCycleSendWhisper(state.supportName, "stay");
				UnBotBuffCycleSendWhisper(state.supportName, "nc +ss master");
				UnBotRaidReserveStop(
					"Варлок снова онлайн и оставлен в группе. Для сохранения Soulstone его нельзя переводить офлайн на этом сервере.",
					true
				);
			elseif (now >= (state.stageUntil or 0)) then
				UnBotRaidReserveStop("Не удалось вернуть резервного варлока онлайн.", true);
			else
				state.nextTime = now + 0.25;
			end
		end
	end
end);

SLASH_UNBOTRAIDRESCUE1 = "/ubrescue";
SlashCmdList["UNBOTRAIDRESCUE"] = function(message)
	local command = UnBotSpecSummonNormalize(message);
	if (command == "prepare" or command == "резерв") then
		UnBotRaidReservePrepare();
	elseif (command == "ss" or command == "soulstone") then
		UnBotSpecSummonMessage("Офлайн-Soulstone отключён: аура исчезает, когда варлок уходит офлайн.");
	elseif (command == "status" or command == "статус") then
		UnBotRaidReserveStatus();
	elseif (command == "clean" or command == "очистить") then
		UnBotRaidReserveCleanup();
	else
		UnBotRaidRescueStart();
	end
end;

-- Blood-Queen Lana'thel: park one chosen bot next to the Empowering Blood Orb,
-- then remotely make it use the orb and immediately summon it to the boss.
-- This is intentionally a two-click workflow: the first click can only park a
-- friendly registered bot; the second can only run while Lana'thel is targeted.
UnBotLanathelOrb = UnBotLanathelOrb or {
	armed = false,
	active = false,
	stage = "idle",
	botName = nil,
	bossName = nil,
	nextTime = 0,
	stageUntil = 0,
	losAttempts = 0,
	useAttempts = 0,
	objectIndex = nil,
};

function UnBotLanathelOrbIsBossTarget()
	if (not UnitExists("target") or not UnitCanAttack("player", "target")) then
		return false;
	end
	local targetName = UnBotSpecSummonNormalize(UnitName("target") or "");
	return (
		string.find(targetName, "lana", 1, true)
		or string.find(targetName, "ланат", 1, true)
		or string.find(targetName, "blood-queen", 1, true)
		or string.find(targetName, "кровавая королева", 1, true)
	) and true or false;
end

function UnBotLanathelOrbReturnToParked(text)
	UnBotLanathelOrb.active = false;
	UnBotLanathelOrb.stage = "parked";
	UnBotLanathelOrb.nextTime = 0;
	UnBotLanathelOrb.stageUntil = 0;
	UnBotLanathelOrb.objectIndex = nil;
	if (text) then
		UnBotSpecSummonMessage(text);
	end
end

function UnBotLanathelOrbReset(removeBot)
	local name = UnBotLanathelOrb.botName;
	if (removeBot and name and UnBotSpecSummonIsInGroup(name)) then
		UnBotBuffCycleSendWhisper(name, "follow");
	end
	UnBotLanathelOrb.armed = false;
	UnBotLanathelOrb.active = false;
	UnBotLanathelOrb.stage = "idle";
	UnBotLanathelOrb.botName = nil;
	UnBotLanathelOrb.bossName = nil;
	UnBotLanathelOrb.nextTime = 0;
	UnBotLanathelOrb.stageUntil = 0;
	UnBotLanathelOrb.losAttempts = 0;
	UnBotLanathelOrb.useAttempts = 0;
	UnBotLanathelOrb.objectIndex = nil;
	UnBotSpecSummonMessage("Лана'тель: подготовка сферы сброшена.");
end

function UnBotLanathelOrbAction()
	local state = UnBotLanathelOrb;
	if (state.active) then
		UnBotLanathelOrbReturnToParked(
			"Лана'тель: активный поиск сферы остановлен. Бот остался возле сферы; повторное нажатие запустит цикл снова."
		);
		return;
	end
	if (UnitAffectingCombat("player")) then
		UnBotSpecSummonMessage("Лана'тель: сферу нужно активировать до начала боя.");
		return;
	end

	if (not state.armed) then
		local name = UnitName("target");
		local unit = name and UnBotBuffCycleResolveUnit(name);
		local profile = name and UnBotBotRegistry and UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
		if (
			not name
			or name == UnitName("player")
			or not unit
			or not profile
			or not UnitIsConnected(unit)
			or UnitIsDeadOrGhost(unit)
		) then
			UnBotSpecSummonMessage(
				"Лана'тель, шаг 1: возле кровавой сферы выделите живого бота из реестра и нажмите кнопку ещё раз."
			);
			return;
		end
		state.armed = true;
		state.stage = "parked";
		state.botName = name;
		state.bossName = nil;
		state.losAttempts = 0;
		state.useAttempts = 0;
		state.objectIndex = nil;
		UnBotBuffCycleSendWhisper(name, "stay");
		UnBotSpecSummonMessage(
			"Лана'тель, шаг 1/2: "..name.." оставлен возле сферы командой stay. "
			.."Теперь бегите к боссу, выделите Лана'тель и нажмите эту же кнопку."
		);
		return;
	end

	if (not state.botName or not UnBotSpecSummonIsInGroup(state.botName)) then
		UnBotLanathelOrbReset(false);
		UnBotSpecSummonMessage("Оставленный бот больше не состоит в группе. Выполните шаг 1 заново.");
		return;
	end
	local botUnit = UnBotBuffCycleResolveUnit(state.botName);
	if (not botUnit or not UnitIsConnected(botUnit) or UnitIsDeadOrGhost(botUnit)) then
		UnBotSpecSummonMessage("Лана'тель: оставленный бот сейчас офлайн или мёртв; подготовка сохранена.");
		return;
	end
	if (not UnBotLanathelOrbIsBossTarget()) then
		UnBotSpecSummonMessage(
			"Лана'тель, шаг 2: выделите саму Кровавую королеву. Бот "..state.botName.." продолжает ждать возле сферы."
		);
		return;
	end

	state.active = true;
	state.stage = "query";
	state.bossName = UnitName("target");
	state.nextTime = GetTime();
	state.stageUntil = 0;
	state.losAttempts = 0;
	state.useAttempts = 0;
	state.objectIndex = nil;
	UnBotSpecSummonMessage(
		"Лана'тель, шаг 2/2: запрашиваю у "..state.botName
		.." объекты возле сферы. После подтверждения будут автоматически отправлены use, summon, follow и attack."
	);
end

function UnBotLanathelOrbStatus()
	local state = UnBotLanathelOrb;
	if (state.active) then
		UnBotSpecSummonMessage(
			"Лана'тель: выполняется этап "..tostring(state.stage)..", бот "..tostring(state.botName).."."
		);
	elseif (state.armed) then
		UnBotSpecSummonMessage(
			"Лана'тель: бот "..tostring(state.botName).." оставлен у сферы. Выделите босса и запустите второй шаг."
		);
	else
		UnBotSpecSummonMessage("Лана'тель: подготовка сферы не начата.");
	end
end

UnBotLanathelOrbFrame = UnBotLanathelOrbFrame or CreateFrame("Frame", "UnBotLanathelOrbFrame");
UnBotLanathelOrbFrame:RegisterEvent("CHAT_MSG_WHISPER");
UnBotLanathelOrbFrame:SetScript("OnEvent", function(self, event, message, sender)
	local state = UnBotLanathelOrb;
	if (not state.active or sender ~= state.botName) then
		return;
	end
	local text = string.lower(tostring(message or ""));
	local hasOrb = (
		string.find(text, "empowering blood orb", 1, true)
		or string.find(text, "кровав", 1, true)
	) and true or false;
	if (state.stage == "wait_los" and hasOrb) then
		local index = tonumber(string.match(text, "%[(%d+)%]"));
		if (index) then
			state.objectIndex = index;
			state.useAttempts = state.useAttempts + 1;
			UnBotBuffCycleSendWhisper(state.botName, "u "..tostring(index));
			state.stage = "wait_use";
			state.stageUntil = GetTime() + 4;
			state.nextTime = GetTime() + 0.25;
			UnBotSpecSummonMessage(
				"Лана'тель: сфера найдена как объект "..tostring(index).."; отправлена команда u "..tostring(index).."."
			);
		end
	elseif (
		state.stage == "wait_use"
		and hasOrb
		and string.find(text, "using", 1, true)
	) then
		state.stage = "summon";
		state.nextTime = GetTime() + 0.15;
		UnBotSpecSummonMessage("Лана'тель: бот подтвердил использование сферы. Телепортирую его к боссу.");
	end
end);

UnBotLanathelOrbFrame:SetScript("OnUpdate", function(self, elapsed)
	local state = UnBotLanathelOrb;
	if (not state.active or GetTime() < (state.nextTime or 0)) then
		return;
	end
	local now = GetTime();
	if (state.stage == "query") then
		state.losAttempts = state.losAttempts + 1;
		UnBotBuffCycleSendWhisper(state.botName, "los gos");
		state.stage = "wait_los";
		state.stageUntil = now + 4;
		state.nextTime = now + 0.25;
	elseif (state.stage == "wait_los") then
		if (now >= (state.stageUntil or 0)) then
			if (state.losAttempts < 3) then
				state.stage = "query";
				state.nextTime = now + 0.5;
				UnBotSpecSummonMessage(
					"Лана'тель: сфера пока не найдена, повтор los "..tostring(state.losAttempts + 1).."/3."
				);
			else
				UnBotLanathelOrbReturnToParked(
					"Лана'тель: бот не увидел Empowering Blood Orb после трёх запросов. Он остался на месте; подведите его ближе и повторите второй шаг."
				);
			end
		else
			state.nextTime = now + 0.25;
		end
	elseif (state.stage == "wait_use") then
		if (now >= (state.stageUntil or 0)) then
			if (state.useAttempts < 2 and state.objectIndex) then
				state.useAttempts = state.useAttempts + 1;
				UnBotBuffCycleSendWhisper(state.botName, "u "..tostring(state.objectIndex));
				state.stageUntil = now + 4;
				state.nextTime = now + 0.25;
				UnBotSpecSummonMessage("Лана'тель: подтверждения use нет, повтор 2/2.");
			else
				UnBotLanathelOrbReturnToParked(
					"Лана'тель: использование сферы не подтверждено. Бот не телепортирован и остался возле сферы."
				);
			end
		else
			state.nextTime = now + 0.25;
		end
	elseif (state.stage == "summon") then
		UnBotBuffCycleSendWhisper(state.botName, "summon");
		state.stage = "follow";
		state.nextTime = now + 0.6;
	elseif (state.stage == "follow") then
		UnBotBuffCycleSendWhisper(state.botName, "follow");
		state.stage = "attack";
		state.nextTime = now + 0.7;
	elseif (state.stage == "attack") then
		UnBotBuffCycleSendWhisper(state.botName, "attack");
		local name = state.botName;
		state.armed = false;
		state.active = false;
		state.stage = "idle";
		state.botName = nil;
		state.bossName = nil;
		state.nextTime = 0;
		state.objectIndex = nil;
		UnBotSpecSummonMessage(
			"Лана'тель: "..tostring(name).." использовал сферу, призван к игроку и отправлен атаковать босса. Окно усиления — около 30 секунд."
		);
	end
end);

UnBotToolsMenu = {
	{
		text = "Инструменты UnBot",
		isTitle = true,
		notCheckable = true,
	},
	{
		text = "Призыв состава",
		notCheckable = true,
		func = function() UnBotSquadBuilderToggle() end,
	},
	{
