function UnBotSpecSummonCreateButton()
	if (UnBotSpecSummonButton or not UnBotFrame) then
		return;
	end

	local button = CreateFrame("Button", "UnBotSpecSummonButton", UnBotFrame);
	button:SetWidth(24);
	button:SetHeight(24);
	button:SetPoint("LEFT", UnBotFrame, "RIGHT", 3, 0);
	button:SetPushedTexture([[Interface\BUTTONS\UI-Quickslot-Depress]]);
	button:SetHighlightTexture([[Interface\Buttons\UI-Common-MouseHilight]], "ADD");
	button.Icon = button:CreateTexture("UnBotSpecSummonButtonIcon", "BACKGROUND");
	button.Icon:SetTexture([[Interface\Icons\INV_Misc_Gear_01]]);
	button.Icon:SetAllPoints(button);
	button.Icon:Show();
	button:SetScript("OnEnter", UnBotSpecSummonButton_OnEnter);
	button:SetScript("OnLeave", function() GameTooltip:Hide(); end);
	button:SetScript("OnClick", function(self)
		if UnBotSquadCommands then UnBotSquadCommands.RefreshBehaviorMenu(); end
		EasyMenu(UnBotLocale.ToolsMenu(UnBotToolsMenu), UnBotSpecSummonMenuFrame, self, 0, 0, "MENU", 2);
	end);
	button:Show();
end

local UnBotSpecSummonLoader = CreateFrame("Frame");
UnBotSpecSummonLoader:RegisterEvent("ADDON_LOADED");
UnBotSpecSummonLoader:RegisterEvent("PLAYER_LOGIN");
UnBotSpecSummonLoader:SetScript("OnEvent", function(self, event, arg1)
	if (event == "ADDON_LOADED") then
		if (arg1 == "UnBotCustom") then
			UnBotRegistryAttachStorage();
			UnBotJunkCleanerCheckpoint.Restore();
			UnBotBagSpaceAuditCheckpoint.Restore();
			-- SavedVariables загружаются только к ADDON_LOADED. Раньше этот
			-- сброс выполнялся во время чтения файла и видел пустой реестр.
			UnBotJunkCleanerForceFullCycleRevision();
			-- Первая загрузка версии с checkpoint принимает уже оставшиеся
			-- forceJunkCycle-профили как незавершённую старую партию. Поэтому
			-- сохранённый до обновления прогресс не будет помечен заново.
			UnBotJunkCleanerCheckpoint.AdoptLegacyForced();
		end
		return;
	end
	UnBotRegistryAttachStorage();
	if (UnBotRegistrySeedImportStatus and not UnBotRegistrySeedImportStatus.reported) then
		UnBotRegistrySeedImportStatus.reported = true;
		DisplayInfomation(
			"|cff00ffffСтартовый реестр "..tostring(UnBotRegistrySeedImportStatus.realmName)
			..": добавлено "..tostring(UnBotRegistrySeedImportStatus.added)
			..", обновлено "..tostring(UnBotRegistrySeedImportStatus.updated)
			..", всего "..tostring(UnBotRegistrySeedImportStatus.total)..".|r"
		);
	end
	if (UnBotPublicRegistry) then UnBotPublicRegistry.Report(); end
	UnBotSpecSummonCreateButton();
	UnBotSquadBuilderCreate();
end);

-- Read-only context for diagnostics kept outside this chunk's local budget.
if (UnBotSummonLog) then
	UnBotSummonLog.Context = function()
		return UnBotSpecSummon, UnBotSquadSpecCheck, UnBotSquadBuilder,
			UnBotSquadNearbyGate, UnBotBuffCycle, UnBotRaidReserve;
	end
end
-- Share the actual lexical UI state with modules loaded after this file.
-- Keep the local bindings: existing PvE callbacks and external modules use one table.
_G.UnBotSquadBuilder = UnBotSquadBuilder;
_G.UnBotSquadBuilderRefresh = UnBotSquadBuilderRefresh;
-- Adapter for the independent PvP controller; the PvE state machine is unchanged.
UnBotPVPSquad.transport = {
	PVEOwner = UnBotSpecSummon,
	Message = UnBotSpecSummonMessage,
	Roster = UnBotSpecSummonGetMembers,
	Attach = UnBotRegistryAttachStorage,
	ActiveFlag = UnBotRegistryGetActiveFlag,
	SpecAliases = UnBotSpecSummonSpecAliases,
	PVECount = UnBotSquadBuilderBotCount,
	Settling = function()
		return next(UnBotSpecSummon.cleanupQueue or {})
			or (UnBotRaidReserve and (UnBotRaidReserve.autoPrepareAt or 0) > 0);
	end,
	Candidates = function(className, specKey, excluded)
		local aliases = specKey == "any" and {anySpec = true}
			or UnBotSpecSummonSpecAliases[specKey] or {specKey};
		return UnBotRegistryCandidates(className, aliases, excluded, false);
	end,
	Matches = function(profile, className, specKey)
		if (profile and profile.className == className and profile.specName == specKey) then return true; end
		if (profile and UnBotSpecSummonSpecAliases[profile.specName]) then
			local aliases = UnBotSpecSummonSpecAliases[profile.specName];
			profile = {className=profile.className, specName=aliases[1], feralRole=profile.feralRole or aliases.feralRole};
		end
		local aliases = specKey == "any" and {anySpec = true}
			or UnBotSpecSummonSpecAliases[specKey] or {specKey};
		return UnBotRegistryProfileMatches(profile, className, aliases);
	end,
	Protected = function()
		local names = {};
		for _, members in pairs(UnBotSquadBuilderRosterAssignments()) do
			for _, member in ipairs(members) do names[member.name] = true; end
		end
		for name in pairs(UnBotSpecSummonGetMembers()) do
			if (UnBotIsAccountAltProfile(name, UnBotBotRegistry.bots and UnBotBotRegistry.bots[name])
				or UnBotSquadRosterIsOfflineReserve(name)) then names[name] = true; end
		end
		names[UnitName("player")] = true;
		return names;
	end,
	Busy = function()
		return UnBotMythicPlusBuffOtherAutomationActive(nil, true)
			or (UnBotSquadRoleAction and UnBotSquadRoleAction.active)
			or (UnBotAccountAlts and (UnBotAccountAlts.active or UnBotAccountAlts.discoveryActive))
			or (UnBotAltStrategies and (UnBotAltStrategies.active or #UnBotAltStrategies.queue > 0))
			or (UnBotBeaconTravel and UnBotBeaconTravel.active);
	end,
	Uninvite = UnBotSpecSummonUninvite,
	Record = UnBotRegistryRecordGameplaySummon,
};
UnBotSpecSummonCreateButton();

-- BEGIN PVE FAST SHORTAGE
do
-- PvE-only shortage conversion and bounded rejection. Uses the existing summon clock.
UnBotPVEFastSummon = {blocked = {},releasedOnline = {}};
local f = UnBotPVEFastSummon;
local function state() return UnBotSpecSummon; end
local function transport() return UnBotSpecSummon.PVETransport; end
local function message(text) UnBotSpecSummonMessage("PvE: "..text); end
local function clean(text) return UnBotPVPSummon.Clean(text); end
local function role(className, key)
 local aliases = UnBotPVPSquad.transport.SpecAliases[key];
 return clean(aliases and aliases[1] or key);
end
function f.Group(className, key)
 key = role(className,key);
 if className == "mage" and (key == "arcane" or key == "fire" or key == "frost" or key == "frostfire") then return "mage"; end
 if className == "warlock" and (key == "affliction" or key == "demonology" or key == "destruction") then return "warlock"; end
 if className == "hunter" and (key == "marksmanship" or key == "survival") then return "hunter-ranged"; end
 if className == "priest" and (key == "holy" or key == "discipline") then return "priest-heal"; end
end
function f.Handles(slot)
 return slot and not slot.accountAltName and not slot.skipped
  and not (slot.specAliases and slot.specAliases.anySpec) and f.Group(slot.className,slot.specKey);
end
function f.Enabled()
 local s=state(); return s.active and s.registryMode and s.mode == "squad" and s.squad and not s.completionSource;
end
function f.Protected(name)
 local s,p=state(),UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
 if name == UnitName("player") or UnBotIsAccountAltProfile(name,p) or UnBotSquadRosterIsOfflineReserve(name)
  or (UnBotSquadRosterIsResurrectionReserve and UnBotSquadRosterIsResurrectionReserve(name))
  or s.CleanupProtected(name) or (s.squad and (s.squad.summonedNames or {})[name]) then return true; end
 for _,slot in ipairs(s.squad and s.squad.slots or {}) do if (slot.names or {})[name] then return true; end end
 for _,entry in ipairs(UnBotPVPSummon.items or {}) do
  if entry.name == name and not entry.failed and (entry.ready or UnBotPVPSummon.active) then return true; end
 end
 return false;
end
function f.Excluded(name)
 local s=state();
 return f.blocked[name] or (s.cleanupQueue[name] and s.cleanupQueue[name].pveOwned);
end
function f.PVPProfile(p)
 local c=p and p.talentClassification;
 if c and c.mode == "pvp" and not p.talentSnapshotStale then return true; end
 local a,b=p and p.pvpObservation,p and p.pveObservation;
 return a and (a.source=="applied" or a.source=="named" or a.source=="full-inspect")
  and (tonumber(a.checkedAt) or 0) >= (tonumber(b and b.checkedAt) or 0);
end
-- Called only by PvE, never by the shared registry/PvP candidate function.
function f.Candidates(names,slot,prefetch)
 local s,out,donors,counts=state(),{},{},{};
 local expanded,seen={},{};
 for _,name in ipairs(names) do table.insert(expanded,name);seen[name]=true; end
 if not prefetch and f.Handles(slot) then
  for name,who in pairs(s.verifiedCandidates or {}) do
   local p=UnBotBotRegistry.bots[name];
   if not seen[name] and p and not UnBotSquadRosterFindUnit(name) and not UnBotPVPSquad.transport.ActiveFlag(p)
    and not UnBotIsAccountAltProfile(name,p) and not (s.squad.initialNames or {})[name]
    and who.className==slot.className and f.Group(who.className,who.specName)==f.Group(slot.className,slot.specKey)
    and not UnBotPVPSquad.transport.Matches(p,slot.className,slot.specKey) then
    table.insert(expanded,name);
   end
  end
 end
 for _,name in ipairs(expanded) do
  local p=UnBotBotRegistry.bots[name];
  if not f.Excluded(name) then
   if not f.Handles(slot) or UnBotPVPSquad.transport.Matches(p,slot.className,slot.specKey) then
    table.insert(out,name);
   elseif not prefetch and not (s.fastTried or {})[name] and not f.PVPProfile(p)
    and f.Group(p.className,p.specName)==f.Group(slot.className,slot.specKey) then
    local key=role(p.className,p.specName);counts[key]=(counts[key] or 0)+1;
    table.insert(donors,{name=name,key=key});
   end
  end
 end
 if #out>0 or prefetch or not f.Handles(slot) then return out; end
 local required={};
 for _,wanted in ipairs(s.squad.slots) do
  if not wanted.accountAltName and not wanted.skipped and not wanted.pveExhausted
   and wanted.className==slot.className and wanted.have<wanted.need then
   local key=role(wanted.className,wanted.specKey);
   required[key]=(required[key] or 0)+wanted.need-wanted.have;
  end
 end
 -- Stable LRU order within the most numerous compatible surplus branch.
 local best,bestCount;
 for _,d in ipairs(donors) do
  if counts[d.key]>(required[d.key] or 0) and (not best or counts[d.key]>bestCount) then best,bestCount=d.key,counts[d.key]; end
 end
 for _,d in ipairs(donors) do if d.key==best then table.insert(out,d.name); end end
 return out;
end
function f.PendingDonor(slot)
 if not f.Handles(slot) then return false; end
 for name,e in pairs(state().cleanupQueue or {}) do
  local p=UnBotBotRegistry.bots[name];
  if e.pveOwned and p and not (state().fastTried or {})[name] and not f.PVPProfile(p)
   and f.Group(p.className,p.specName)==f.Group(slot.className,slot.specKey) then return true; end
 end
 return false;
end
function f.HasExact(slot,name)
 local s,n=state(),0;
 for _,candidate in ipairs(UnBotPVPSquad.transport.Candidates(slot.className,slot.specKey,s.checked)) do
  if candidate~=name and not f.Excluded(candidate) then n=n+1; end
 end
 for pending in pairs(s.squad.prefetchPending or {}) do
  if pending~=name and UnBotPVPSquad.transport.Matches(UnBotBotRegistry.bots[pending],slot.className,slot.specKey) then n=n+1; end
 end
 return n>=slot.need-slot.have;
end
function f.CancelCleanup(name)
 if f.autoRemoval and f.autoRemoval.target.name==name then f.autoRemoval=nil;end
 f.ResolveCleanup(name);
 f.blocked[name]=nil;
end
function f.ReleaseCandidate()
 local s=state();s.candidate,s.requestedName,s.requestedSlot=nil,nil,nil;
 s.requestedFallback=false;s.stage,s.stageTime="wait_next",GetTime()+.1;
end
function f.QueueCleanup(name)
 local s=state();
 if not name or not UnBotIsValidBotName(name) or f.Protected(name) then return false; end
 if s.cleanupQueue[name] and s.cleanupQueue[name].pveOwned then return true; end
 local unit=UnBotSquadRosterFindUnit(name);
 s.checked[name]=true;s.registryRequests[name]=nil;s.kickQueue[name]=nil;s.rejectedOnline[name]=nil;
 s.uninviteAttempts=s.uninviteAttempts or {};s.uninviteAttempts[name]=nil;
 s.cleanupQueue[name]={pveOwned=true,phase="leave",nextTime=GetTime(),untilTime=GetTime()+28,
  context=UnBotRegistryCurrentContext(),guid=unit and UnitGUID and UnitGUID(unit),leaves=0};
 return true;
end
-- A bot released by this run stays online. Reinvite it directly if selected as a donor.
function f.InviteReleased(name)
 local s,entry=state(),f.releasedOnline[name];
 if not entry or not f.Enabled() or entry.context~=UnBotRegistryCurrentContext()
  or GetTime()-entry.at>90 or not (s.verifiedCandidates or {})[name] or f.Protected(name) then return false; end
 f.releasedOnline[name]=nil;
 s.inviteAttempts,s.inviteAt=1,math.huge;
 message(name..": ранее исключён без отключения; отправляю приглашение по имени.");
 InviteUnit(name);return true;
end
function f.Reject(name)
 if not f.Enabled() then return false; end
 local s=state();name=name or s.candidate;
 if name then
  if not f.QueueCleanup(name) then
   s.checked[name]=true;s.registryRequests[name]=nil;
   if s.requestedSlot and s.requestedSlot.accountAltName then
    s.requestedSlot.pveExhausted="именной участник не подтверждён";
   end
  end
  message(tostring(name)..": слот не засчитан; продолжаю сбор остальных, очистка ограничена по времени.");
 end
 f.ReleaseCandidate();return true;
end
function f.CleanupDone(name,reason)
 local s,unit=state(),UnBotSquadRosterFindUnit(name);
 local entry=s.cleanupQueue[name];
 s.cleanupQueue[name],s.kickQueue[name],s.registryRequests[name],s.rejectedOnline[name]=nil,nil,nil,nil;
 if unit then
  f.blocked[name]=reason or "не вышел из ростера";
  local p=UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
  if p then
   p.pveCleanupFailure=p.pveCleanupFailure or {};
   p.pveCleanupFailure.context,p.pveCleanupFailure.at=UnBotRegistryCurrentContext(),time();
   p.pveCleanupFailure.reason=f.blocked[name];
   p.pveCleanupFailure.resolved=nil;
   p.pveCleanupFailure.recoveryAttempted=true;
   p.pveCleanupFailure.autoAttempts,p.pveCleanupFailure.autoAt,p.pveCleanupFailure.autoGUID=nil,nil,nil;
  end
  if UnBotRegistrySetHourlyQuarantine then UnBotRegistrySetHourlyQuarantine(name,"PvE: "..f.blocked[name],"PvE-карантин"); end
  message(name..": очистка завершена без освобождения места ("..f.blocked[name].."). Бот не засчитан; остальные позиции продолжаются.");

 else
  f.blocked[name]=nil;
  f.ResolveCleanup(name);
  if reason then
   s.initUsed=s.initUsed or {};s.fastTried=s.fastTried or {};
   s.initUsed[name],s.fastTried[name]=true,true;
  end
  if entry and entry.confirmedOnline then
   f.releasedOnline[name]={context=entry.context,at=GetTime()};
  end
  message(name..": место освобождено"..(reason and ("; "..reason) or "")..".");
 end
end
function f.TickCleanup()
 f.CheckManualRemoval();
 f.AutomaticRemovalTick();
 local s,now=state(),GetTime();
 if f.Enabled() then
  for name in pairs(s.kickQueue or {}) do
   if f.QueueCleanup(name) and s.candidate==name then f.ReleaseCandidate(); end
  end
 end
 for name in pairs(f.blocked) do if not s.cleanupQueue[name] and not UnBotSquadRosterFindUnit(name) then f.ResolveCleanup(name,true);f.blocked[name]=nil; end end
 for name,e in pairs(s.cleanupQueue or {}) do
  if e.pveOwned then
   local unit=UnBotSquadRosterFindUnit(name);
   if unit then e.absentSince=nil; end
   if f.Protected(name) then s.CancelStaleCleanup(name);
   elseif e.context~=UnBotRegistryCurrentContext() then
    s.cleanupQueue[name]=nil;f.blocked[name]=nil;
   elseif unit and (UnitName(unit)~=name or (e.guid and UnitGUID and UnitGUID(unit)~=e.guid)) then
    s.cleanupQueue[name]=nil;f.blocked[name]="изменилось имя или GUID участника";
   elseif UnitAffectingCombat("player") or InCombatLockdown() or (unit and UnitAffectingCombat(unit)) then
    f.CleanupDone(name,"очистка отменена из-за боя");
   elseif now>=e.untilTime then f.CleanupDone(name,"таймаут очистки 28 секунд");
   elseif not unit or now>=e.nextTime then
    if not unit then
     -- Group exclusion is enough: keep the rejected bot online, never send remove.
     e.absentSince=e.absentSince or now;
     if now-e.absentSince>=.5 then f.CleanupDone(name); end
    elseif e.refusal then f.CleanupDone(name,e.refusal);
    else
     e.absentSince=nil;
     if not UnitIsConnected(unit) then
      if not e.onlineRequestedAt then
       e.onlineRequestedAt=now;e.waitingOnline=true;e.nextTime=now+.5;
       message(name..": офлайн в рейде; возвращаю онлайн для исключения (до 10 секунд).");
       SendChatMessage(".playerbot bot add "..name,"SAY");
      elseif not e.waitingOnline or now-e.onlineRequestedAt>=10 then
       f.CleanupDone(name,"не подтвердил устойчивый онлайн; повторный add не отправляется");
      else e.nextTime=now+.5; end
     else
      if e.waitingOnline then
       e.waitingOnline=nil;e.leaves=0;e.leaveUntil=nil;
       s.uninviteAttempts[name]=nil;
       message(name..": снова онлайн; отправляю leave для выхода из рейда.");
      end
      e.confirmedOnline=true;
      e.leaveUntil=e.leaveUntil or (now+15);
      if now>=e.leaveUntil then f.CleanupDone(name,"не вышел из рейда за 15 секунд после leave");
      elseif e.leaves<2 then
       e.leaves=e.leaves+1;e.nextTime=now+2;
       message(name..": исключение из группы — leave ("..e.leaves.."/2).");
       SendChatMessage("leave","WHISPER",nil,name);
      else e.nextTime=math.min(e.leaveUntil,now+.5); end
     end
    end
   end
  end
 end
end
function f.MarkExhausted(slot,reason)
 slot.pveExhausted=reason;
 message(tostring(slot.className).." "..tostring(slot.specKey)..": недобор "..tostring(slot.need-slot.have)
  .." ("..reason.."); продолжаю другие позиции.");
 local s=state();s.stage,s.stageTime="wait_next",GetTime()+.1;
end
function f.HasCleanup()
 if f.autoRemoval or f.manualRemoval then return true;end
 for _,entry in pairs(state().cleanupQueue or {}) do if entry.pveOwned then return true; end end
end
function f.FinishPartial(reason)
 local parts,reasons,seen={},{},{};
 for _,slot in ipairs(state().squad.slots or {}) do
  if not slot.skipped and slot.have<slot.need then
   table.insert(parts,slot.className.." "..slot.specKey.." "..slot.have.."/"..slot.need);
   if slot.pveExhausted and not seen[slot.pveExhausted] then
    seen[slot.pveExhausted]=true;table.insert(reasons,slot.pveExhausted);
   end
  end
 end
 reason=reason or (#reasons>0 and ("Причины недобора: "..table.concat(reasons,"; ")..". Принятые участники сохранены.")
   or "Добор завершён без заполнения всех позиций; принятые участники сохранены.");
 UnBotSquadBuilder.postSummonSequence=nil;UnBotSquadBuilder.pendingBossPreset=nil;
 transport().Stop((#parts>0 and ("PvE собран частично: "..table.concat(parts,", ")..". ") or "PvE: целевые слоты заполнены. ")..reason);
 if UnBotSummonLog then UnBotSummonLog.Safe("Result","pve","partial",table.concat(parts,", ").."; "..reason); end
end
function f.BeforeFinish()
 f.AutomaticRemovalTick();
 if f.HasCleanup() then state().stage,state().stageTime="wait_next",GetTime()+.2;return true; end
 local names={};for name in pairs(f.blocked) do table.insert(names,name); end
 if #names>0 then table.sort(names);f.FinishPartial("Целевые слоты заполнены, но остались незачтённые участники: "..table.concat(names,", ")..". Автоматическое продолжение отложено.");return true; end
 return false;
end
function f.Capacity(name,slot)
 if UnBotSquadRosterFindUnit(name) then return true; end
 local s=state();local occupied=math.max(1+(GetNumPartyMembers() or 0),GetNumRaidMembers() or 0);
 for pending in pairs(s.squad.prefetchPending or {}) do if not UnBotSquadRosterFindUnit(pending) then occupied=occupied+1; end end
 -- Physical roster capacity is independent of the current instance/buff limit.
 if occupied<40 then return true; end
 f.AutomaticRemovalTick();
 if f.HasCleanup() then s.stage,s.stageTime="wait_next",GetTime()+.2;
 else f.MarkExhausted(slot,"достигнут лимит ростера 40 участников вместе с игроком; учитываются офлайн-участники и ожидающие приглашения"); end
 return false;
end
-- Equipped items are read only. Unknown gear cannot authorize a conversion.
function f.Gear(name,className)
 local unit=UnBotSquadRosterFindUnit(name);
 if not unit or not GetInventoryItemLink or not GetItemInfo or not GetItemStats then return nil,"экипировка ещё не прочитана"; end
 local signature,sp={},0;
 local required=className=="hunter" and {5,7,18} or {5,7,16};
 for _,slot in ipairs(required) do if not GetInventoryItemLink(unit,slot) then return nil,"не прочитаны обязательные предметы"; end end
 for slot=1,18 do
  local link=slot~=4 and GetInventoryItemLink(unit,slot);
  if link then
   local itemName,_,_,_,_,_,_,_,loc=GetItemInfo(link);
   if not itemName then return nil,"нет данных предмета в кэше"; end
   table.insert(signature,tostring(slot)..":"..link);
   local stats=GetItemStats(link);
   if not stats then return nil,"характеристики предмета не прочитаны"; end
   sp=sp+(stats.ITEM_MOD_SPELL_POWER_SHORT or 0)+(stats.ITEM_MOD_HEALING_DONE_SHORT or 0);
   if className=="hunter" then
    if slot==18 and loc~="INVTYPE_RANGED" and loc~="INVTYPE_RANGEDRIGHT" then return false,"нет подходящего дальнего оружия"; end
   elseif slot~=18 then
    for key,value in pairs(stats) do
     if value>0 and (key:find("SHADOW_DAMAGE",1,true) or key:find("FROST_DAMAGE",1,true)
      or key:find("FIRE_DAMAGE",1,true) or key:find("ARCANE_DAMAGE",1,true)) then return false,"экипировка привязана к школе магии"; end
    end
    if not f.tooltip then f.tooltip=CreateFrame("GameTooltip","UnBotPVEFastGearTooltip",UIParent,"GameTooltipTemplate"); end
    if not f.tooltip.SetHyperlink then return nil,"API описания предметов недоступен"; end
    f.tooltip:SetOwner(UIParent,"ANCHOR_NONE");f.tooltip:ClearLines();f.tooltip:SetHyperlink(link);
    if f.tooltip:NumLines()<2 then f.tooltip:Hide();return nil,"описание предмета ещё не прочитано"; end
    for line=2,f.tooltip:NumLines() do
     local text=_G["UnBotPVEFastGearTooltipTextLeft"..line];text=text and text:GetText() or "";
     local lower=clean(text);
     local school=lower:find("shadow",1,true) or lower:find("frost",1,true) or lower:find("fire",1,true)
      or lower:find("arcane",1,true) or lower:find("тьмы",1,true) or lower:find("льда",1,true)
      or lower:find("огня",1,true) or lower:find("тайной магии",1,true);
     local bonus=lower:find("increases damage",1,true) or lower:find("increases spell damage",1,true)
      or (lower:find("велич",1,true) and (lower:find("урон",1,true) or lower:find("заклинаний",1,true)));
     if school and bonus then f.tooltip:Hide();return false,"бонус предмета действует только на отдельную школу магии"; end
    end
    f.tooltip:Hide();
   end
  end
 end
 if className~="hunter" and sp<=0 then return false,"не подтверждён кастерский/лечебный эквип"; end
 return table.concat(signature,"|");
end
function f.Alive(op)
 local s,p=state(),UnBotBotRegistry.bots[op.name];local unit=UnBotSquadRosterFindUnit(op.name);
 return f.Enabled() and s.squad==op.owner and s.requestedName==op.name and s.candidate==op.name
  and op.context==UnBotRegistryCurrentContext() and p and p.className==op.className
  and unit and (not op.guid or UnitGUID(unit)==op.guid) and UnitName(unit)==op.name
  and UnitIsConnected(unit) and not UnitIsDeadOrGhost(unit) and not f.Protected(op.name)
  and not UnBotPVPSquad.transport.ActiveFlag(p) and not UnitAffectingCombat("player")
  and not InCombatLockdown() and not UnitAffectingCombat(unit) and op.slot.have<op.slot.need;
end
function f.Request(op,kind,command)
 op.kind,op.command,op.attempts,op.nextTime=kind,command,0,GetTime();
end
function f.Fail(reason)
 local op=f.op;if not op then return; end
 f.op=nil;message(op.name..": быстрый добор не подтверждён — "..reason.."; пробую другого кандидата.");
 if f.Enabled() and state().requestedName==op.name then
  if UnitAffectingCombat("player") or InCombatLockdown() then
   f.QueueCleanup(op.name);transport().Stop("PvE: быстрый добор отменён из-за боя; участники сохранены.");
  elseif op.context~=UnBotRegistryCurrentContext() then
   state().registryRequests[op.name]=nil;transport().Stop("PvE: быстрый добор отменён — сменился контекст.");
  else f.Reject(op.name); end
 end
end
function f.Begin(name,who,slot)
 local s=state();slot=slot or s.requestedSlot;
 if not f.Enabled() or not f.Handles(slot) or not who or not who.level or who.level<11
  or who.className~=slot.className or f.Group(who.className,who.specName)~=f.Group(slot.className,slot.specKey)
  or role(who.className,who.specName)==role(slot.className,slot.specKey)
  or (s.squad.initialNames or {})[name] or f.Protected(name) or f.PVPProfile(UnBotBotRegistry.bots[name])
  or (s.fastTried or {})[name] or f.HasExact(slot,name) then return false; end
 s.fastTried=s.fastTried or {};s.fastTried[name]=true;
 local unit=UnBotSquadRosterFindUnit(name);
 local op={name=name,className=who.className,who=who,slot=slot,owner=s.squad,
  guid=unit and UnitGUID and UnitGUID(unit),context=UnBotRegistryCurrentContext(),deadline=GetTime()+24,
  kind="gear",nextTime=GetTime(),gearDeadline=GetTime()+5};
 f.op=op;s.stage,s.stageTime="wait_pve_fast",GetTime();
 message(name..": быстрый добор "..tostring(who.specName).." → "..slot.specKey.."; проверяю эквип и серверный PvE-пресет.");
 return true;
end
function f.TickActive()
 local op=f.op;if not op then return false; end
 if not f.Alive(op) then f.Fail("кандидат, контекст или доступность изменились");return true; end
 local now=GetTime();
 if now>=op.deadline then f.Fail("общий таймаут 24 секунды");return true; end
 if now<(op.nextTime or 0) then return true; end
 if op.kind=="gear" then
  local signature,reason=f.Gear(op.name,op.className);
  if signature then op.gear=signature;f.Request(op,"catalog","talents spec list");
  elseif signature==false or now>=op.gearDeadline then f.Fail(reason);
  else
   if not op.inspectSent and NotifyInspect and CanInspect and CanInspect(UnBotSquadRosterFindUnit(op.name))
    and not (UnBotTalentInfo and UnBotTalentInfo.job) and not (InspectFrame and InspectFrame:IsShown()) then
    op.inspectSent=true;NotifyInspect(UnBotSquadRosterFindUnit(op.name));
   end
   op.nextTime=now+.5;
  end
  return true;
 end
 local limit=(op.kind=="apply" or op.kind=="reset") and 1 or 2;
 if op.attempts>=limit then f.Fail("нет подтверждения команды "..op.kind);return true; end
 if op.kind=="apply" then
  local gear,reason=f.Gear(op.name,op.className);
  if gear~=op.gear then f.Fail(reason or "экипировка изменилась");return true; end
  local p=UnBotBotRegistry.bots[op.name];
  if UnBotTalentInfo and UnBotTalentInfo.Invalidate then UnBotTalentInfo.Invalidate(p,"PvE: применён другой пресет"); end
  p.talentSnapshotStale=true;
 end
 op.attempts=op.attempts+1;op.sentAt=now;op.nextTime=now+3;
 SendChatMessage(op.command,"WHISPER",nil,op.name);return true;
end
function f.Reply(event,text,sender)
 local lower=clean(text);
 if event=="CHAT_MSG_SYSTEM" then
  local addName,addResult=lower:match("^add:%s*(.-)%s*%-%s*(.-)%s*$");
  if addName then
   for candidate,e in pairs(state().cleanupQueue or {}) do
    if e.pveOwned and e.waitingOnline and clean(candidate)==addName then
     if addResult~="ok" and not addResult:find("already",1,true) then
      e.refusal="сервер отказал add: "..tostring(addResult);e.nextTime=GetTime();
     end
     return true;
    end
   end
  end
 end
 local cleanup=event=="CHAT_MSG_WHISPER" and state().cleanupQueue[sender];
 if cleanup and cleanup.pveOwned and (cleanup.leaves or 0)>0
  and (lower:find("unknown command",1,true) or lower:find("i'll do it later",1,true)
   or lower:find("i will do it later",1,true)) then
  cleanup.refusal="бот отказал leave: "..lower;cleanup.nextTime=GetTime();return true;
 end
 local op=f.op;
 if not op or event~="CHAT_MSG_WHISPER" or sender~=op.name or not op.sentAt or op.attempts==0 then return false; end
 if not f.Alive(op) then f.Fail("кандидат недоступен");return true; end
 if lower:find("unknown command",1,true) or lower:find("unknown spell",1,true) or lower:find("not found",1,true)
  or lower:find("cannot cast",1,true) or lower:find("no items",1,true) or lower:find("too low",1,true)
  or lower:find("i'll do it later",1,true) then f.Fail("сервер отказал: "..lower);return true; end
 if op.kind=="catalog" then
  local templates=UnBotTalentCatalog.ReadReply(op,text);
  if templates then
   for _,template in ipairs(templates) do
    local prefix=clean(template.name):match("^(.-)%s+pve$");
    if prefix and UnBotPVPSquad.transport.Matches({className=op.className,specName=prefix},op.className,op.slot.specKey) then op.target=template;break end
   end
   if not op.target then f.Fail("на сервере нет нужного PvE-пресета");
   else f.Request(op,"apply","talents spec "..op.target.name); end
  end
 elseif op.kind=="apply" and lower=="picking "..clean(op.target.name) then
  op.ack=true;f.Request(op,"reset","reset botAI");
 elseif op.kind=="reset" and lower:find("ai was reset",1,true) then f.Request(op,"talents","talents");
 elseif op.kind=="talents" then
  local current=UnBotPVPSummon.Current(text);
  if current then
   local named=current.name==clean(op.target.name);
   local branch=UnBotPVPSquad.transport.Matches({className=op.className,specName=current.name},op.className,op.slot.specKey);
   local expected=math.max(0,op.who.level-9);
   if not op.ack or (not named and not branch) or current.points~=expected
    or (op.who.level==80 and current.build~=op.target.build) then f.Fail("таланты после применения не совпали с целевым PvE-билдом");
   else op.current=current;f.Request(op,"who","who"); end
  end
 elseif op.kind=="who" then
  local who=UnBotParseBotWho(text);
  if who and who.className and who.specName then
   local gear,reason=f.Gear(op.name,op.className);
   if not UnBotPVPSquad.transport.Matches(who,op.className,op.slot.specKey) or who.level~=op.who.level
    or (who.talentBuild and who.talentBuild:gsub("/","-")~=op.current.build) or gear~=op.gear then
    f.Fail(reason or "контрольный who или эквип не совпал");
   else
    transport().StoreWho(op.name,who,text);
    local p=UnBotBotRegistry.bots[op.name];
    p.pveObservation=p.pveObservation or {};
    p.pveObservation.checkedAt,p.pveObservation.preset=time(),op.target.name;
    p.pveObservation.build,p.pveObservation.source=op.current.build,"verified";
    p.source="pve-fast-shortage";
    f.op=nil;message(op.name..": быстрый добор подтверждён — "..op.target.name.."; init не нужен.");
    if not transport().Accept(op.name) then f.Reject(op.name); end
   end
  end
 end
 return true;
end
function f.Cancel()
 f.op=nil;
end

function f.ResolveCleanup(name,force)
 local p=UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
 if not p or (not force and not p.pveCleanupFailure) then return; end
 p.pveCleanupFailure=p.pveCleanupFailure or {};
 p.pveCleanupFailure.context,p.pveCleanupFailure.at=UnBotRegistryCurrentContext(),time();
 p.pveCleanupFailure.resolved,p.pveCleanupFailure.reason=true,nil;
end
-- Read-only recovery also recognises 6.39.24 cleanup failures after /reload.
function f.CleanupProblem(name)
 local p=UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
 if not p then return; end
 if f.blocked[name] then return f.blocked[name]; end
 local record=p.pveCleanupFailure;
 if record and record.context==UnBotRegistryCurrentContext() and record.resolved then return; end
 if record and record.context==UnBotRegistryCurrentContext()
  and (tonumber(p.lastSummonedAt) or 0)<=(tonumber(record.at) or 0) then return record.reason; end
 local flags=p.rotationFlags;
 if flags and flags.quarantineReason and flags.quarantineReason:match("^PvE:")
  and (tonumber(p.lastSummonedAt) or 0)<=(tonumber(flags.quarantinedAt) or 0) then return flags.quarantineReason; end
 local log=UnBotSquadConfig.summonLogs and UnBotSquadConfig.summonLogs[1];
 if not log or log.realm~=(GetRealmName and GetRealmName()) or log.player~=UnitName("player")
  or (log.faction and UnitFactionGroup and log.faction~=UnitFactionGroup("player"))
  or (tonumber(p.lastSummonedAt) or 0)>(tonumber(log.endedAt) or tonumber(log.startedAt) or 0) then return; end
 local result=log.results and log.results.pve;
 local names=result and result.status=="partial" and tostring(result.reason):match("остались незачтённые участники:%s*(.-)%.");
 for candidate in tostring(names or ""):gmatch("[^,%s]+") do
  if candidate==name then return result.reason; end
 end
end
function f.CleanupProblems()
 local result={};
 if UnBotRegistryMatchesCurrentContext and not UnBotRegistryMatchesCurrentContext(UnBotBotRegistry) then return result; end
 for name in pairs(UnBotPVPSquad.transport.Roster() or {}) do
  local unit=UnBotSquadRosterFindUnit(name);
  if unit and name~=UnitName("player") and f.CleanupProblem(name) and not f.Protected(name) then
   table.insert(result,{name=name,unit=unit,offline=not UnitIsConnected(unit),
    guid=UnitGUID and UnitGUID(unit),context=UnBotRegistryCurrentContext()});
  end
 end
 table.sort(result,function(a,b) if a.offline~=b.offline then return a.offline; end;return a.name<b.name; end);
 return result;
end
function f.ManualAllowed(target)
 if not target or not target.name or not UnBotIsValidBotName(target.name) then return false,"имя не подтверждено"; end
 if f.manualRemoval then return false,"ожидаю обновления ростера"; end
 if UnitAffectingCombat("player") or InCombatLockdown() then return false,"доступно вне боя"; end
 if target.context~=UnBotRegistryCurrentContext() then return false,"сменился сервер или персонаж"; end
 if GetNumRaidMembers()>0 then
  if not ((IsRaidLeader and IsRaidLeader()) or (IsRaidOfficer and IsRaidOfficer())) then return false,"нужны права лидера или помощника"; end
 elseif IsPartyLeader and not IsPartyLeader() then return false,"нужны права лидера группы"; end
 local unit=UnBotSquadRosterFindUnit(target.name);
 if not unit or UnitName(unit)~=target.name or UnitIsConnected(unit)
  or (target.guid and UnitGUID and UnitGUID(unit)~=target.guid) then return false,"бот или его состояние изменились"; end
 if f.Protected(target.name) or not f.CleanupProblem(target.name)
  or state().cleanupQueue[target.name] or state().kickQueue[target.name] then return false,"участник защищён или очистка ещё идёт"; end
 return true;
end
-- Invoked only by the visible button's OnClick; never from a timer.
function f.Exclude(target,automatic)
 local ok,reason=f.ManualAllowed(target);
 if not ok then if not automatic then message("Исключение не выполнено: "..reason..".");end;return false; end
 local unit=UnBotSquadRosterFindUnit(target.name);
 local name,realm=UnitName(unit);
 local fullname=realm and realm~="" and (name.."-"..realm) or name;
 local p=UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
 if p and p.pveCleanupFailure then
  p.pveCleanupFailure.autoAttempts=automatic and ((p.pveCleanupFailure.autoAttempts or 0)+1) or 2;
  p.pveCleanupFailure.autoAt=time();
  p.pveCleanupFailure.recoveryAttempted=true;
 end
 f.autoRemoval=nil;
 f.manualRemoval={name=name,context=target.context,untilTime=GetTime()+2,automatic=automatic};
 message(name..(automatic and ": отправлено автоматическое исключение; проверяю освобождение места."
  or ": отправлено исключение по нажатию; проверяю освобождение места."));
 UninviteUnit(fullname);
 return true;
end
function f.ManualExclude(target)
 return f.Exclude(target,false);
end
function f.QueueAutoRemoval(target)
 if f.autoRemoval or f.manualRemoval or not target or not target.offline then return;end
 local p=UnBotBotRegistry.bots and UnBotBotRegistry.bots[target.name];
 if not p then return;end
 local failure=p.pveCleanupFailure;
 if failure and (failure.recoveryAttempted or failure.context~=target.context
  or (failure.autoGUID and target.guid~=failure.autoGUID)) then return;end
 local ok=f.ManualAllowed(target);if not ok then return;end
 if not failure then
  failure={context=target.context,at=time(),reason=f.CleanupProblem(target.name)};
  p.pveCleanupFailure=failure;
 end
 failure.autoGUID=failure.autoGUID or target.guid;
 f.autoRemoval={target=target,at=GetTime()+2,untilTime=GetTime()+15};
end
function f.AutomaticRemovalTick()
 if not (UnBotPVPSquad.transport and UnBotPVPSquad.transport.Roster) then return;end
 local now=GetTime();if now<(f.nextAutoRemovalTick or 0) then return;end;f.nextAutoRemovalTick=now+.25;
 if f.manualRemoval then return;end
 if (UnBotPVPSummon and UnBotPVPSummon.active) then f.autoRemoval=nil;return;end
 local pending=f.autoRemoval;
 if pending then
  local target=pending.target;
  if UnitAffectingCombat("player") or InCombatLockdown() then
   local p=UnBotBotRegistry.bots and UnBotBotRegistry.bots[target.name];
   if p and p.pveCleanupFailure then p.pveCleanupFailure.recoveryAttempted=true;end
   f.autoRemoval=nil;return;
  end
  if now>=pending.untilTime or not f.ManualAllowed(target) then f.autoRemoval=nil;return;end
  if now>=pending.at then
   f.autoRemoval=nil;
   local p=UnBotBotRegistry.bots and UnBotBotRegistry.bots[target.name];
   if p and p.pveCleanupFailure then p.pveCleanupFailure.recoveryAttempted=true;end
   f.QueueCleanup(target.name);
  end
  return;
 end
 for _,target in ipairs(f.CleanupProblems()) do
  f.QueueAutoRemoval(target);if f.autoRemoval then return;end
 end
end
function f.CheckManualRemoval()
 local request=f.manualRemoval;if not request then return; end
 if request.context~=UnBotRegistryCurrentContext() then f.manualRemoval=nil;return; end
 local name=request.name;
 if not UnBotSquadRosterFindUnit(name) then
  f.ResolveCleanup(name,true);
  f.blocked[name]=nil;f.manualRemoval=nil;
  f.lastManualRemoval={name=name,removed=true,at=GetTime()};
  message(name..": исключён из группы, место освобождено.");
 elseif GetTime()>=request.untilTime then
  f.manualRemoval=nil;f.lastManualRemoval={name=name,removed=false,at=GetTime()};
  message(name..(request.automatic and ": автоматическое исключение не подтверждено ростером; доступна кнопка исключения."
   or ": исключение по нажатию не подтверждено ростером. Повторите штатное ПКМ → Исключить."));
 end
end
end
-- END PVE FAST SHORTAGE

-- BEGIN CONFIRMED ROSTER CACHE
-- Session-only evidence: never reconstruct this cache from saved registry hints.
do
UnBotSpecSummon.confirmedRoster={entries={},ttl=300};
local C=UnBotSpecSummon.confirmedRoster;
function C.Context()
 return UnBotRegistryCurrentContext().."|"..tostring(UnitGUID and UnitGUID("player") or UnitName("player"))
  .."|"..tostring(GetRealZoneText and GetRealZoneText() or "");
end
function C.Fingerprint(p)
 local s,a,b=p.talentSnapshot,p.pveObservation,p.pvpObservation;
 return table.concat({tostring(p.className),tostring(p.specName),tostring(p.feralRole),tostring(p.level),
  tostring(p.talentBuild),tostring(s),tostring(s and s.fingerprint),tostring(p.talentSnapshotStale),
  tostring(a and a.checkedAt),tostring(a and a.source),tostring(a and a.preset),tostring(a and a.build),
  tostring(b and b.checkedAt),tostring(b and b.source),tostring(b and b.preset),tostring(b and b.build)},"|");
end
function C.Live(name)
 local p=UnBotBotRegistry.bots and UnBotBotRegistry.bots[name];
 local unit=UnBotSquadRosterFindUnit(name);
 if not p or not unit or name==UnitName("player") or UnBotIsAccountAltProfile(name,p)
  or UnBotSquadRosterIsOfflineReserve(name) or not UnitIsConnected(unit) or UnitIsDeadOrGhost(unit)
  or UnitName(unit)~=name or not UnitGUID or not UnitGUID(unit) then return; end
 return p,unit;
end
function C.Forget(name)
 if name then C.entries[name]=nil;else C.entries={};end
end
function C.ForgetNamed(target)
 local lower=tostring(target or ""):lower();
 for name in pairs(C.entries) do
  if name:lower()==lower or (GetRealmName and (name.."-"..GetRealmName()):lower()==lower) then C.Forget(name);end
 end
end
function C.Validate(name)
 local record=C.entries[name];if not record then return;end
 local p,unit=C.Live(name);
 if not p or record.profile~=p or record.guid~=UnitGUID(unit) or record.context~=C.Context()
  or record.fingerprint~=C.Fingerprint(p) then C.Forget(name);return;end
 return record;
end
function C.Get(name,kind)
 local record=C.Validate(name);if not record then return;end
 local p=record.profile;
 local proof=record[kind];if not proof then return;end
 if GetTime()<proof.at or GetTime()-proof.at>C.ttl then record[kind]=nil;return;end
 if kind=="pvp" and (not UnBotPVPSummon or not UnBotPVPSummon.ObservationValid(p)
  or proof.catalog~=(UnBotTalentCatalog and UnBotTalentCatalog.Get(p.className))) then record.pvp=nil;return;end
 return proof;
end
function C.Remember(name,kind,proof)
 local p,unit=C.Live(name);if not p then return;end
 local fingerprint=C.Fingerprint(p);
 local record=C.entries[name];
 if not record or record.profile~=p or record.guid~=UnitGUID(unit) or record.context~=C.Context()
  or record.fingerprint~=fingerprint then
  record={profile=p,guid=UnitGUID(unit),context=C.Context(),fingerprint=fingerprint};C.entries[name]=record;
 end
 proof.at=GetTime();record[kind]=proof;
end
function C.Who(name,info)
 if not info or not info.className or not info.specName then return;end
 C.Remember(name,"who",{});
end
function C.PVP(entry)
 if not entry.ready or not entry.who or not entry.target or entry.cacheReused or UnBotPVPSummon.catalogOnly
  or not UnBotPVPSummon.ObservationValid(UnBotBotRegistry.bots[entry.name]) then return;end
 local p=UnBotBotRegistry.bots[entry.name];
 local display,mode=UnBotPVPSummon.RosterProfile(p);if mode~="pvp" then return;end
 C.Remember(entry.name,"pvp",{target=entry.target,catalog=UnBotTalentCatalog and UnBotTalentCatalog.Get(p.className),
  who={className=p.className,specName=display.specName,feralRole=display.feralRole,
   level=p.level,talentBuild=p.talentBuild}});
end
function C.ReusePVP(entry)
 local proof=C.Get(entry.name,"pvp");
 if not proof or entry.new or not UnBotPVPSummon.Near(entry)
  or not UnBotPVPSquad.transport.Matches(proof.who,entry.className,entry.specKey) then return false;end
 entry.who,entry.target=proof.who,proof.target;
 entry.ready,entry.prepared,entry.confirmation,entry.origin=true,true,"preserved","native-pvp";
 entry.cacheReused=true;
 UnBotPVPSummon.CandidateResult(entry,"ready","fresh-cache");
 return true;
end
function C.Watch()
 for name in pairs(C.entries) do C.Validate(name);end
end
function C.Command(command,channel,language,target)
 command=tostring(command or ""):lower();channel=tostring(channel or ""):upper();
 if channel=="WHISPER" then
  if (command:match("^talents%s+spec%s+") and command~="talents spec list")
   or command:match("^talents%s+apply") or command:match("^talents%s+switch")
   or command:match("^talents%s+autopick")
   or (command:match("^co%s+") and C.entries[target] and C.entries[target].profile.className=="druid"
    and ((command:find("+cat",1,true) and C.entries[target].profile.feralRole~="cat")
     or (command:find("+bear",1,true) and C.entries[target].profile.feralRole~="bear")
     or (command:find("+tank",1,true) and C.entries[target].profile.feralRole~="bear")
     or (command:find("-tank",1,true) and C.entries[target].profile.feralRole=="bear"))) then
   C.ForgetNamed(target);
  end
 else
  local action,name=command:match("^%.playerbots?%s+bot%s+(%S+)%s+(%S+)");
  if action=="init" or action=="add" or action=="remove" or action=="logout" then
   if name and name~="*" then
    for target in name:gmatch("[^,]+") do C.ForgetNamed(target);end
   else C.Forget();end
  end
 end
end
C.frame=CreateFrame("Frame");
for _,event in ipairs({"PARTY_MEMBERS_CHANGED","RAID_ROSTER_UPDATE","UNIT_FLAGS","PLAYER_ENTERING_WORLD"}) do C.frame:RegisterEvent(event);end
C.frame:SetScript("OnEvent",function(_,event,unit)
 if event=="PLAYER_ENTERING_WORLD" then C.Forget();
 elseif event=="UNIT_FLAGS" then if unit then C.Validate(UnitName(unit));end
 else C.Watch();end
end);
if hooksecurefunc then hooksecurefunc("SendChatMessage",C.Command);end
end
-- END CONFIRMED ROSTER CACHE

