UnBotSpecSummon.BatchAPI = {Parse=UnBotSpecSummonParseWho, Store=UnBotSquadSpecCheckStoreProfile, Candidates=UnBotRegistryCandidates,
 Buff=UnBotBuffCycle, Check=UnBotSquadSpecCheck, CheckStart=UnBotSquadSpecCheckStart, CheckFinish=UnBotSquadSpecCheckFinish,
 Show=UnBotSquadBuilderShowCurrentRoster, Refresh=UnBotSquadBuilderRefresh,
 SupportsSpecs=UnBotSpecSummonPlayerSupportsSpecs, OtherBusy=UnBotDKSpecBalanceOtherAutomationActive,
 Balance=UnBotDKSpecBalance, Fast=UnBotPVEFastSummon};
